            ['surah_id'=>2,'ayah_number'=>6,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Innal lazeena kafaroo sawaaa\'un \'alaihim \'a-anzar-tahum am lam tunzirhum laa yu\'minoon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>7,'arabic_text'=>'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Khatamal laahu \'alaa quloobihim wa-\'alaa sam\'i-him; wa-\'alaaaa absaarihim ghishaa-wa(tunw); wa-lahum \'azaabun \'azeem','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>8,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ','transliteration'=>'Wa-minan naasi mainy yaqoolu aamannaa billaahi wa-bil-yawmil aakhiri wa-maa hum bimu\'mineen','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>9,'arabic_text'=>'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ','transliteration'=>'Yukhaadi\'oonal laaha wallazeena aamanoo wa-maa yakhda\'oona illaaa anfusahum wa-maa yash\'uroon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>10,'arabic_text'=>'فِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ','transliteration'=>'Fee quloobihim mara-dun fazaadahumul laahu maradaa(n); wa-lahum \'azaabun aleemum bimaa kaanoo yakziboon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>11,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ','transliteration'=>'Wa-izaa qeela lahum laa tufsidoo fil ardi qaalooo innamaa nahnu muslihoon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>12,'arabic_text'=>'أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ','transliteration'=>'Alaaa innahum humul mufsidoona wa-laakil laa yash\'uroon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>13,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ','transliteration'=>'Wa-izaa qeela lahum aaminoo kamaaa aamanan naasu qaalooo anu\'minu kamaaa aamanas sufahaaa\'(u): alaaa innahum humus sufahaaa\'u wa-laakil laa ya\'lamoon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>14,'arabic_text'=>'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ','transliteration'=>'Wa-izaa laqul lazeena aamanoo qaalooo aamannaa wa-izaa khalaw ilaa shayaateenihim qaalooo innaa ma\'akum innamaa nahnu mustahzi\'oon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>15,'arabic_text'=>'ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','transliteration'=>'Allahu yastahzi\'u bihim wa-yamudduhum fee tughyaanihim ya\'mahoon','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>16,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ','transliteration'=>'Ulaaa\'ikal lazeenash tara-wud dalaalata bilhudaa famaa rabihat tijaaratuhum wa-maa kaanoo muhtadeen','page_number'=>3,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>17,'arabic_text'=>'مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ','transliteration'=>'Masaluhum kamasalil lazis tawqada naaran falammaaa adaaa\'at maa hawlahoo zahabal laahu binoorihim wa-tarakahum fee zulumaatil laa yubsiroon','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>18,'arabic_text'=>'صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ','transliteration'=>'Summum bukmun \'umyun fahum laa yarji\'oon','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>19,'arabic_text'=>'أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ','transliteration'=>'Aw kasaiyibim minas samaaa\'i feehi zulumaatunw wa-ra\'dunw wa-barq(unwi) yaj\'aloona asaabi\'ahum feee aazaanihim minas sawaa\'iqi hazaral mawt,(i) wallaahu muheetum bilkaafireen','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>20,'arabic_text'=>'يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Yakaadul barqu yakhtafu absaarahum; kullamaaa adaaa\'a lahum mashaw feehi wa-izaaa azlama \'alaihim qaamoo, wa-law shaaa\'al laahu lazahaba bisam\'ihim wa-absaarihim, innal laaha \'alaa kulli shai\'in Qadeer','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>21,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Yaaa-aiyuhan naasu \'budoo Rabbakumul lazee khalaqakum wallazeena min qablikum la\'allakum tattaqoon','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>22,'arabic_text'=>'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ','transliteration'=>'Allazee ja\'ala lakumul arda firaashanw wassamaaa\'a binaaa\'a(nw) wa-anzala minas samaaa\'i maaa\'an fa-akhraja bihee minas samaraati rizqal lakum; falaa taj\'aloo lillaahi andaadan wa-antum ta\'lamoon','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>23,'arabic_text'=>'وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-in kuntum fee raibim mimmaa nazzalnaa \'alaa \'abdinaa fatoo bi-sooratim mim mislihee- wad\'oo shuhadaaa\'akum min doonil laahi in kuntum saadiqeen','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>24,'arabic_text'=>'فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ','transliteration'=>'Fa-il lam taf\'aloo wa-lan taf\'aloo fattaqun naaral latee waqooduhan naasu walhijaara(tu); u\'iddat lil-kaafireen','page_number'=>4,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>25,'arabic_text'=>'وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ رِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ وَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wa-bashshiril lazeena aamanoo wa-\'amilus saalihaati anna lahum jannaatin tajree min tahtihal anhaar(u); kullamaa ruziqoo minhaa min samaratin rizqan qaaloo haazal lazee ruziqnaa min qabl(u); wa-utoo bihee mutashaabihaa(n); wa-lahum feehaaa azwaajum mutahhara-tu(nw); wa-hum feehaa khaalidoon','page_number'=>5,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>26,'arabic_text'=>'۞ إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ','transliteration'=>'^Innal laaha laa yastahyee-e ai yadriba masalam maa ba\'oodatan famaa fawqahaa, faammal lazeena aamanoo faya\'lamoona annahul haqqu mir rabbihim; wa-ammal lazeena kafaroo fayaqooloona maazaaa araadal laahu bihaazaa masalaa. Yudillu bihee- kaseeranw wa-yahdee bihee kaseeraa’n wa-maa yudillu bihee-e illal faasiqeen','page_number'=>5,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>27,'arabic_text'=>'ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Allazeena yanqudoona \'ahdal laahi mim ba\'di meesaaqihee wa-yaqta\'oona maaa amaral laahu bihee-e ai yoosala wa-yufsidoona fil ard,(i) ulaaa\'ika humul khaasiroon','page_number'=>5,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>28,'arabic_text'=>'كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Kaifa takfuroona billaahi wa-kuntum amwaatan fa-ahyaakum; summa yumeetukum summa yuhyeekum summaa ilaihi turja\'oon','page_number'=>5,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>29,'arabic_text'=>'هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Huwal lazee khalaqa lakum maa fil ardi jamee\'an summas tawaaa ilas samaaa\'i fasaw-waahunna sab\'a samaa-waat,(in) wa-Huwa bikulli shai\'in Aleem','page_number'=>5,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>30,'arabic_text'=>'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ','transliteration'=>'Wa-iz qaala rabbuka lil malaaa\'ikati innee jaa\'ilun fil-ardi khaleefa(tan); qaalooo ataj\'alu feehaa mai yufsidu feehaa wa-yasfikud dimaaa\'a wa-nahnu nusabbihu bihamdika wa-nuqaddisu lak(a); qaala inneee a\'lamu maa laa ta\'lamoon','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>31,'arabic_text'=>'وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-\'allama Aadamal asmaaa\'a kullahaa summa \'aradahum \'alal malaaa\'ikati faqaala ambi\'oonee bi-as maaa\'i haaa\'ulaaa\'i in-kuntum saadiqeen','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>32,'arabic_text'=>'قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ','transliteration'=>'Qaaloo subhaanaka laa \'ilma lanaaa illaa maa \'allamtanaaa; innaka antal \'aleemul hakeem','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>33,'arabic_text'=>'قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ','transliteration'=>'Qaala yaaa-Aadamu ambi\'hum biasmaaa\'ihim; falammaa amba-ahum bi-asmaaa\'ihim qaala alam aqul lakum inneee a\'lamu ghaibas samaawaati wal-ardi wa-a\'lamu maa tubdoona wa-maa kuntum taktumoon','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>34,'arabic_text'=>'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-iz qulnaa lilmalaaa\'i-katis judoo li-aadama fasajadooo illaaa Ibleesa abaa wastakbara wa-kaana minal kaafireen','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>35,'arabic_text'=>'وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-qulnaa yaaa Aadamus-kun anta wa-zawjukal jannata wa-kulaa minhaa raghadan haisu shi\'tumaa wa-laa taqrabaa haazihish shajarata fatakoonaa minaz zaalimeen','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>36,'arabic_text'=>'فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ','transliteration'=>'Fa-azallahumash Shaitaanu \'anhaa fa-akhrajahumaa mimmaa kaanaa feeh(i); wa-qulnah bitoo ba\'dukum liba\'din \'aduw(wunw); wa-lakum fil ardi mustaqarrunw wa-mataa\'un ilaa heen','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>37,'arabic_text'=>'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Fatalaqqaaa Aadamu mir Rabbihee Kalimaatin fataaba \'alaihi, innahoo Huwat Tawwaabur Raheem','page_number'=>6,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>38,'arabic_text'=>'قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Qulnah bitoo minhaa jamee-\'a(n); fa-immaa ya\'tiyannakum minnee huda(n) faman tabi\'a hudaaya falaa khawfun \'alaihim wa-laa hum yahza-noon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>39,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wallazeena kafaroo wa-kaz-zabooo bi-aayaatinaa ulaaa\'ika As-haabun Naar(i); hum feehaa khaalidoon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>40,'arabic_text'=>'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ','transliteration'=>'Yaa-Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa-awfoo bi\'Ahdeee oofi bi-ahdikum wa-iyyaaya farhaboon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>41,'arabic_text'=>'وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّٰيَ فَٱتَّقُونِ','transliteration'=>'Wa-aaminoo bimaaa anzaltu musaddiqal limaa ma\'akum wa-laa takoonooo awwala kaafirim bih(ee);- wa-laa tashtaroo bi-Aayaatee samanan qaleelanw wa-iyyaaya fattaqoon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>42,'arabic_text'=>'وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-laa talbisul haqqa bilbaatili wa-taktumul haqqa wa-antum ta\'lamoon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>43,'arabic_text'=>'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ','transliteration'=>'Wa-aqeemus salaata wa-aatuz zakaata warka\'oo ma\'ar raaki\'een','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>44,'arabic_text'=>'۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'^Ataamuroonan naasa bilbirri wa-tansawna anfusakum wa-antum tatloonal Kitaab,(a) afalaa ta\'qiloon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>45,'arabic_text'=>'وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ','transliteration'=>'Wasta\'eenoo bissabri was-Salaah,(ti) wa-innahaa lakabee-ratun illaa alal khaashi\'een','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>46,'arabic_text'=>'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ','transliteration'=>'Allazeena yazunnoona annahum mulaaqoo Rabbihim wa-annahum ilaihi raaji\'oon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>47,'arabic_text'=>'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Yaa-Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa-annee faddaltukum \'alal \'aalameen','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>48,'arabic_text'=>'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Wattaqoo Yawmal laa tajzee nafsun \'an nafsin shai\'a(nw) wa-laa yuqbalu minhaa shafaa\'atunw wa-laa yu\'khazu minhaa \'adlunw wa-laa hum yunsaroon','page_number'=>7,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>49,'arabic_text'=>'وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ','transliteration'=>'Wa-iz najjainaakum min Aali Fir\'awna yasoomoonakum sooo\'al azaabi yuzabbihoona abnaaa\'akum wa-yastahyoona nisaaa\'akum, wa-fee zaalikum balaaa\'um mir Rabbikum \'azeem','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>50,'arabic_text'=>'وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ','transliteration'=>'Wa-iz faraqnaa bikumul bahra fa-anjainaakum wa-agh-raqnaaa Aala Fir\'awna wa-antum tanzuroon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>51,'arabic_text'=>'وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ','transliteration'=>'Wa-iz waa\'adnaa Moosaaa arba\'eena lailatan summat takhaztumul \'ijla mim ba\'dihee wa-antum zaalimoon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>52,'arabic_text'=>'ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Summa \'afawnaa \'ankum mim ba\'di zaalika la\'allakum tashkuroon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>53,'arabic_text'=>'وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Wa-iz aatainaa Moosal kitaaba wal-Furqaana la\'allakum tahtadoon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>54,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Wa-iz qaala Moosaa liqawmihee- yaa-qawmi innakum zalamtum anfusakum bittikhaa-zikumul \'ijla fatoobooo ilaa Baari\'ikum faqtulooo anfusakum zaalikum khairul lakum \'inda Baari\'ikum fataaba \'alaikum, innahoo Huwat Tawwaabur Raheem','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>55,'arabic_text'=>'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ','transliteration'=>'Wa-iz qultum yaa-Moosaa lan nu\'mina laka hattaa naral laaha jahratan fa-akhazat-kumus saa\'iqatu wa-antum tanzuroon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>56,'arabic_text'=>'ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Summa ba\'asnaakum mim ba\'di mawtikum la\'allakum tashkuroon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>57,'arabic_text'=>'وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Wa-zallalnaa \'alaikumul ghamaama wa-anzalnaa \'alaikumul Manna was-Salwaa; kuloo min taiyibaati maa razaqnaakum; wa-maa zalamoonaa wa-laakin kaanooo anfusahum yazlimoon','page_number'=>8,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>58,'arabic_text'=>'وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-iz qulnad khuloo haazihil qaryata fakuloo minhaa haisu shi\'tum raghadanw wadkhulul baaba sujjadanw wa-qooloo hittatun naghfir lakum khataayaakum, wa-sanazeedul muhsineen','page_number'=>9,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>59,'arabic_text'=>'فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ','transliteration'=>'Fabaddalal lazeena zalamoo qawlan ghairal lazee qeela lahum fa-anzalnaa \'alal lazeena zalamoo rijzam minas samaaa\'i bimaa kaanoo yafsuqoon','page_number'=>9,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>60,'arabic_text'=>'۞ وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','transliteration'=>'^Wa-izis tasqaa Moosaa liqawmihee faqulnad rib bi\'asaakal hajar(a); fanfajarat minhusnataaa \'ashrata \'ayna(n); qad \'alima kullu unaasim mash-rabahum; kuloo washraboo mir rizqil laahi wa laa ta\'saw fil ardi mufsideen','page_number'=>9,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>61,'arabic_text'=>'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ','transliteration'=>'Wa-iz qultum yaa-Moosaa lan nasbira \'alaa ta\'aaminw waahidin fad\'u lanaa rabbaka yukhrij lanaa mimmaa tumbitul ardu mim baqlihaa wa-qis-saaa\'ihaa wa-foomihaa wa-\'adasihaa wa-basalihaa; qaala atastabdiloonal lazee huwa adnaa billazee huwa khayr, ihbitoo misran fa-inna lakum maa sa-altum: wa-duribat \'alaihimuz zillatu walmaskanatu wa-baaa\'oo bighadabim minal laah:(i) zaalika bi-annahum kaano yakfuroona bi-aayaatil laahi wa-yaqtuloonan Nabiyyeena bighairil haqq:(i) zaalika bimaa \'asaw wa-kaanoo ya\'tadoon','page_number'=>9,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>62,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Innal lazeena aamanoo wallazeena haadoo wan-nasaaraa was-Saabi\'eena man aamana billaahi wal-yawmil aakhiri wa-\'amila saalihan falahum ajruhum \'inda Rabbihim wa-laa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>63,'arabic_text'=>'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Wa-iz akhaznaa meesaaqakum wa-rafa\'naa fawqakumut Toora khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>64,'arabic_text'=>'ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Summa tawallaitum mim ba\'di zaalik(a); falawlaa fadlul laahi \'alaikum wa-rahmatuhoo lakuntum minal khaasireen','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>65,'arabic_text'=>'وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ','transliteration'=>'Wa-laqad \'alimtumul lazeena\' -tadaw minkum fis Sabti faqulnaa lahum koonoo qiradatan khaasi\'een','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>66,'arabic_text'=>'فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ','transliteration'=>'Faja\'alnaahaa nakaalal limaa baina yadihaa wa-maa khalfahaa wa-maw\'izatal lilmuttaqeen','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>67,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ','transliteration'=>'Wa-iz qaala Moosaa liqawmiheee innal laaha yaamurukum an tazbahoo baqara(tan); qaalooo atattakhizunna huzuwa(n); qaala a\'oozu billaahi an akoona minal jaahileen','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>68,'arabic_text'=>'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ','transliteration'=>'Qaalu ud\'u lanaa rabbaka yubaiyil lanaa maa hee,(a) qaala innahoo yaqoolu innahaa baqaratul laa faaridunw wa-laa bikrun \'awaanum baina zaalik(a); faf\'aloo maa tu\'maroon','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>69,'arabic_text'=>'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ','transliteration'=>'Qaalu ud\'u lanaa Rabbaka yubaiyil lanaa maa launuhaa, qaala innahoo yaqoolu innahaa baqaratun safraaa\'u faaqi\'ul launuhaa tasurrun naazireen','page_number'=>10,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>70,'arabic_text'=>'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ','transliteration'=>'Qaalu d-\'u lanaa Rabbaka yubaiyil lanaa maa hiya innal baqara tashaabaha \'alainaa wa-innaaa in shaaa\'al laahu lamuhtadoon','page_number'=>11,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>71,'arabic_text'=>'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ','transliteration'=>'Qaala innahoo yaqoolu innahaa baqaratul laa zaloolun tuseerul arda walaa tasqil harsa musallamatul laa shiyata feehaa, qaalul \'aana jita bilhaqq,(i) faza-bahoo-haa wamaa kaado yaf\'aloon','page_number'=>11,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>72,'arabic_text'=>'وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ','transliteration'=>'Waiz qataltum nafsan faddaara\'tum feehaa; wallaahu mukhrijum maa kuntum taktumoon','page_number'=>11,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>73,'arabic_text'=>'فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Faqulnad riboohu biba\'dihaa, kazaalika yuhyil laa-hul mawtaa wa-yureekum aayaatihee la\'allakum ta\'qiloon','page_number'=>11,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>74,'arabic_text'=>'ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Summa qasat quloobukum mim ba\'di zaalika fahiya kalhijaarati aw-ashaadu qaswa,(tan) wa-inna minal hijaarati lamaa yatafajjaru minhul anhaar,(u) wa-inna minhaa lamaa yash shaqqaqu fayakhruju minhul maaa\',(u) wa-inna minhaa lamaa yahbitu min khashyatil laah:(i) wamal laahu bighaafilin \'ammaa ta\'maloon','page_number'=>11,'juz_number'=>1,'hizb_number'=>1,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>75,'arabic_text'=>'۞ أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'^Afatatma\'oona ai yu\'minoo lakum wa-qad kaana fareequm minhum yasma\'oona Kalaamal laahi summa yuharri foonahoo mim ba\'di maa\'aqaloohu wa-hum ya\'lamoon','page_number'=>11,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>76,'arabic_text'=>'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Wa-izaa laqul lazeena aamanoo qaalooo aamannaa wa-izaa khalaa ba\'duhum ilaa ba\'din qaalooo atuhaddisoonahum bimaa fatahal laahu \'alaikum liyuhaajjookum bihee \'inda rabbikum, afalaa ta\'qiloon','page_number'=>11,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>77,'arabic_text'=>'أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ','transliteration'=>'Awalaa ya\'lamoona annal laaha ya\'lamu maa yusirroona wa-maa yu\'linoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>78,'arabic_text'=>'وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ','transliteration'=>'Wa-minhum ummiyyoona laa ya\'lamoonal kitaaba illaaa amaaniyya wa-in hum illaa yazunnoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>79,'arabic_text'=>'فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَوَيۡلٞ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلٞ لَّهُم مِّمَّا يَكۡسِبُونَ','transliteration'=>'Fawailul lillazeena yaktuboonal kitaaba bi-aidihim summa yaqooloona haazaa min \'indil laahi liyashtaroo bihee samanan qaleela(n); fawailul lahum mimaa katabat aydeehim wa-wailul lahum mimmaa yaksiboon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>80,'arabic_text'=>'وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Wa-qaaloo lan tamassanan Naaru illaaa ayyaamam ma\'doo-dah,(tan) qul attakhaztum \'indal laahi \'ahdan falain yukhlifal laahu \'ahdah(ooo); am taqooloona \'alal laahi maa laa ta\'lamoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>81,'arabic_text'=>'بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Balaa man kasaba sayyi\'atanw wa-ahaatat bihee khateee\'atuhoo fa-ulaaa\'ika As-haabun Naar(i); hum feehaa khaalidoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>82,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wallazeena aamanoo wa-\'amilus saalihaati ulaaa\'ika As-haabul Janna(ti); hum feeha khaalidoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>83,'arabic_text'=>'وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ','transliteration'=>'Wa-iz akhaznaa meesaaqa Baneee Israaa\'eela laa ta\'budoona illal laaha wa-bil waalidaini ihsaana(nw) wa-zil qurbaa walyataamaa walmasaakeeni wa-qooloo linnaasi husna(nw) wa-aqeemus salaata wa-aatuzZakaat(a) summa tawallaitum illaa qaleelam minkum wa-antum mu\'ridoon','page_number'=>12,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>84,'arabic_text'=>'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ','transliteration'=>'Wa-iz akhaznaa meesaa-qakum laa tasfikoona dimaaa\'akum wa-laa tukhrijoona anfusakum min diyaarikum summa aqrartum wa-antum tashhadoon','page_number'=>13,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>85,'arabic_text'=>'ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Summa antum haaa\'ulaaa\'i taqtuloona anfusakum wa-tukhrijoona fareeqam minkum min diyaarihim tazaaharoona \'alaihim bil-ismi wal\'udwaani wa-in yaatookum usaaraa tufaadoohum wahuwa muharramun \'alaikum ikhraajuhum, afatu\'-mi-noona biba\'dil Kitaabi wa-takfuroona biba\'d,(in) famaa jazaaa\'u mai yaf\'alu zaalika minkum illaa khizyun fil hayaatid dunyaa; wa-yawmal qiyaamati yuraddoona ilaaa ashaddil \'azaab:(i) wa-mal laahu bighaafilin \'ammaa ta\'maloon','page_number'=>13,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>86,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Ulaaa\'ikal lazeenash tarawul hayaatad dunyaa bil-aakhira(ti); falaa yukhaffafu \'anhumul \'azaabu wa-laa hum yunsaroon','page_number'=>13,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>87,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba wa-qaffainaa mim ba\'dihee bir-Rusul(i); wa-aatainaa \'Eesab- na- Maryamal baiyinaati wa-ayyadnaahu bi-Roohil Qudus:(i) afakullamaa jaaa\'akum Rasoolum bimaa laa tahwaaa anfusukumus takbartum fafareeqan kazzabtum wa-fareeqan taqtuloon','page_number'=>13,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>88,'arabic_text'=>'وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ','transliteration'=>'Wa-qaaloo quloobunaa ghulf,(um) bal la\'anahumul laahu bikufrihim faqaleelam maa yu\'minoon','page_number'=>13,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>89,'arabic_text'=>'وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-lammaa jaaa\'ahum Kitaabum min \'indil laahi musaddiqul limaa ma\'ahum wa-kaanoo min qablu yastaftihoona \'alal lazeena kafaroo falammaa jaaa\'ahum maa \'arafoo kafaroo bih,(ee) fala-\'natul laahi \'alal kaafireen','page_number'=>14,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>90,'arabic_text'=>'بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ','transliteration'=>'Bi\'samash taraw biheee anfusahum ai yakfuroo bimaaa anzalal laahu baghyan ain yunazzilal laahu min fadlihee \'alaa mai yashaaa\'u min ibaadi(hee); fabaaa\'oo bighadabin \'alaa ghadab,(in) wa-lilkaafireena \'azaabum muheen','page_number'=>14,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>91,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-izaa qeela lahum aaminoo bimaaa anzalal laahu qaaloo nu\'minu bimaaa unzila \'alainaa wa-yakfuroona bimaa waraaa\'ahoo wa-huwal haqqu musaddiqal limaa ma\'ahum: qul falima taqtuloona Ambiyaaa\'al laahi min qablu in kuntum mu\'mineen','page_number'=>14,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>92,'arabic_text'=>'۞ وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ','transliteration'=>'^Wa-laqad jaaa\'akum Moosa bilbaiyinaati summat takhaztumul \'ijla mim ba\'dihee wa-antum zaalimoon','page_number'=>14,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>93,'arabic_text'=>'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-iz akhaznaa meesaaqakum wa-rafa\'naa fawqakumut Toora khuzoo maaa aatainaakum biquwwatinw wasma\'oo; qaaloo sami\'naa wa-\'asainaa wa-ushriboo fee quloobihimul \'ijla bikufrihim, qul bi\'samaa yaamurukum biheee eemaanukum in kuntum mu\'mineen','page_number'=>14,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>94,'arabic_text'=>'قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Qul in kaanat lakumud Daarul Aakhiratu \'indal laahi khaalisatam min doonin naasi fatamannawul mawta in kuntum saadiqeen','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>95,'arabic_text'=>'وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ','transliteration'=>'Wa-lai yatamannawhu abadam bimaa qaddamat aideehim: wallaahu \'aleemum bizzaalimeen','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>96,'arabic_text'=>'وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ','transliteration'=>'Wa-latajidannahum ahrasannaasi \'alaa hayaatinw wa minal lazeena ashrakoo, yawaddu ahaduhum lau yu\'ammaru alfa sana(tinw) wa-maa huwa bi-muzahzihihee minal \'azaabi ai yu\'ammar:(a) wallaahu baseerum bimaa ya\'maloon','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>97,'arabic_text'=>'قُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ','transliteration'=>'Qul man kaana \'aduwwal li-Jibreela fa-innahoo nazzalahoo \'alaa qalbika bi-iznil laahi musaddiqal limaa baina yadaihi wa-hudanw wa-bushraa lilmu\'mineen','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>98,'arabic_text'=>'مَن كَانَ عَدُوّٗا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوّٞ لِّلۡكَٰفِرِينَ','transliteration'=>'Man kaana \'aduwwal lillaahi wa-malaaa\'ikatihee wa-Rusulihee wa-Jibreela wa-Meekaala fa-innal laaha \'aduwwul lilkaafireen','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>99,'arabic_text'=>'وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتٖۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ','transliteration'=>'Wa-laqad anzalnaaa ilaika Aayaatim baiyinaat(inw); wa-maa yakfuru bihaaa illal faasiqoon','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>100,'arabic_text'=>'أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Awa-kullamaa \'aahadoo ahdan nabazahoo fareequm minhum, bal aksaruhum laa yu\'minoon','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>101,'arabic_text'=>'وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-lammaa jaaa\'ahum Rasoolum min \'indil laahi musaddiqul limaa ma\'ahum nabaza fareequm minal lazeena ootul Kitaaba Kitaabal laahi waraaa\'a zuhoorihim ka-annahum laa ya\'lamoon','page_number'=>15,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>102,'arabic_text'=>'وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Wattaba\'oo maa tatlush Shayaateenu \'alaa mulki Sulaimaan(a); wamaa kafara Sulaimaanu walaakinnash Shayatteena kafaroo yu\'al-limoonan naasas sihra wa-maaa unzila \'alal malakaini bi-Baabila Haaroota wa-Maaroot, wa-maa yu\'allimaani min ahadin hattaa yaqoolaaa innamaa nahnu fitnatun falaa takfur; fayata\'al-lamoona minhumaa maa yufarriqoona bihee bainal mar\'yee wa-zawjih,(i) wa-maa hum bidaaarreena bi-hee min ahadin illaa bi-iznil llah,(i) wa-yata\'allamoona maa yadurruhum wa-laa yanfa\'uhum, wa-laqad \'alimoo lamanish taraahu maa lahoo fil Aakhirati min khalaaq,(in) wa-labi\'sa maa sharaw biheee anfusahum, lau kaanoo ya\'lamoon','page_number'=>16,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>103,'arabic_text'=>'وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Wa-law annahum aamanoo wattaqaw lamasoobatum min \'indil laahi khair(un); lau kaanoo ya\'lamoon','page_number'=>16,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>104,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo laa taqooloo raa\'inaa wa-qoolun zurnaa wasma\'oo: wa-lilkaafireena \'azaabun aleem','page_number'=>16,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>105,'arabic_text'=>'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Maa yawaddul lazeena kafaroo min ahlil kitaabi wa-lal mushrikeena ai-n yunazzala \'alaikum min khairim mir Rabbikum: wallaahu yakhtassu birahmatihee mai-n yashaaa,(u) wallaahu zul fadlil \'azeem','page_number'=>16,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>106,'arabic_text'=>'۞ مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'^Maa nansakh min aayatin aw nunsihaa na-ti bikhairim minhaaa aw mislihaaa: alam ta\'lam annal laaha \'alaa kulli shai\'in qadeer','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>107,'arabic_text'=>'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ','transliteration'=>'Alam ta\'lam annal laaha lahoo mulkus samaawaati wal-ard:(i) wa-maa lakum min doonil laahi minw waliyyinw wa-laa naseer','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>108,'arabic_text'=>'أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','transliteration'=>'Am tureedoona an tas\'aloo Rasoolakum kamaa su\'ila Moosa min qabl:(u) wa-mai-n yatabaddalil kufra bil-eemaani faqad dalla sawaaa\'as sabeel','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>109,'arabic_text'=>'وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wadda kaseerum min ahlil kitaabi lau yaruddoo-nakum mim ba\'di eemaanikum kuffaaran hasadam min \'indi anfusihim mim ba\'di maa tabaiyyana lahumul haqq(u); fa\'foo wasfahoo hattaa yaa-tiyal laahu bi-amrih:(ee) innal laaha \'alaa kulli shai\'in qadeer','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>110,'arabic_text'=>'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Wa-aqeemus salaata wa-aatuz zakaah,(ta) wa-maa tuqaddimoo li-anfusikum min khairin tajidoohu \'indal laah:(i) innal laaha bimaa ta\'maloona baseer','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>111,'arabic_text'=>'وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-qaaloo lai-n yadkhulal jannata illaa man kaana Hoodan aw Nasaaraa: tilka amaaniyyuhum: qul haatoo burhaa-nakum in kuntum saadiqeen','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>112,'arabic_text'=>'بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Balaa man aslama wajhahoo lillaahi wa-huwa muhsinun falahooo ajruhoo \'inda rabbihee wa-laa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>17,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>113,'arabic_text'=>'وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Wa-qaalatil Yahoodu laisatin Nasaaraa \'alaa shai\'inw wa-qaalatin Nasaaraaa laisatil Yahoodu \'alaa shai\'inw \'wa-hum yatloonal Kitaab:(a) kazaalika qaalal lazeena la ya\'lamoona misla qawlihim, fallaahu yahkumu bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>114,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ','transliteration'=>'Wa-man azlamu mimmam mana\'a masaajidal laahi ai-n yuzkara feehas muhoo wa-sa\'aa fee kharaabihaaa, ulaaa\'ika maa kaana lahum ai-n yadkhuloohaaa illaa khaaa\'ifeen,(a) lahum fid dunyaa khizyunw wa-lahum fil aakhirati \'azaabun \'azeem','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>115,'arabic_text'=>'وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ','transliteration'=>'Wa-lillaahil mashriqu walmaghrib,(u) fa-aynamaa tuwalloo fasamma wajhul laah,(i) innal laaha waasi\'un Aleem','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>116,'arabic_text'=>'وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ','transliteration'=>'Wa-qaalut takhazal laahu walada:(n) subhaana(hoo); bal lahoo maa fis samaawaati wal-ard(i); kullul lahoo qaanitoon','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>117,'arabic_text'=>'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Badeee\'us samaawaati wal-ard(i); wa-izaa qadaaa amran fa-innamaa yaqoolu lahoo kun fayakoon','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>118,'arabic_text'=>'وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ','transliteration'=>'Wa-qaalal lazeena laa ya\'lamoona lau-laa yukallimunal laahu au taateenaaa aaya:(tun) kazaalika qaalal lazeena min qablihim misla qawlihim. tashaabahat quloobuhum: qad baiyannal aayaati liqawmin-y yooqinoon','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>119,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ','transliteration'=>'Innaaa arsalnaaka bilhaqqi basheeranw wa-nazeera(nw); wa-laa tus\'alu \'an As-haabil Jaheem','page_number'=>18,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>120,'arabic_text'=>'وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ','transliteration'=>'Wa-lan tardaa \'ankal Yahoodu wa-lan Nasaaraa hattaa tattabi\'a millatahum: qul inna hudal laahi huwal hudaa: wa-la\'init taba\'ta ahwaaa\'ahum ba\'dal lazee jaaa\'aka minal \'ilmi maa laka minal laahi minw waliyyinw wa-laa naseer','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>121,'arabic_text'=>'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Allazeena aatainaahumul Kitaaba yatloonahoo haqqa tilaawatiheee ulaaa\'ika yu\'minoona bih:(ee) wa-mai-n yakfur bihee fa-ulaaa\'ika humul khaasiroon','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>122,'arabic_text'=>'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Yaa-Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa-annee faddaltukum \'alal \'aalameen','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>123,'arabic_text'=>'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Wattaqoo yawmal laa tajzee nafsun \'an nafsin shai-\'anw wa-laa yuqbalu minhaa \'adlunw wa-laa tanfa\'uhaa shafaa-\'atunw wa-laa hum yunsaroon','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>124,'arabic_text'=>'۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ','transliteration'=>'^Wa-izib talaaa Ibraaheema Rabbuhoo bi-Kalimaatin fa-atammahun(na); qaala Innee jaa\'iluka linnaasi Imaama(n); qaala wa-min zurriyyatee; qaala laa yanaalu \'ahdiz zaalimeen','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>125,'arabic_text'=>'وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ','transliteration'=>'Wa-iz ja\'alnal Baita masaabatal linnaasi wa-amna-nw wattakhizoo mim Maqaami Ibraaheema musallaaa; wa-\'ahidnaaa ilaaa Ibraaheema wa-Ismaa\'eela an tahhiraa Baitiya littaaa\'ifeena wal\'aakifeena warrukka\'is sujood','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>126,'arabic_text'=>'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Wa-iz qaala Ibraaheemu Rabbij \'al haazaa baladan aaminanw warzuq ahlahoo minas samaraati man aamana minhum billaahi wal-yawmil aakhir(i); qaala wa-man kafara fa-umatti\'uhoo qaleelan summa adtarruhooo ilaa \'azaabin Naar(i); wa-bi\'sal maseer','page_number'=>19,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>127,'arabic_text'=>'وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-iz yarfa\'u Ibraaheemul qawaa\'ida minal Baiti wa-Ismaa\'eelu Rabbanaa taqabbal minnaa; innaka Antas Samee\'ul Aleem','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>128,'arabic_text'=>'رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Rabbanaa waj\'alnaa muslimaini laka wa-min zurriyyatinaaa ummatam muslimatal laka wa-arinaa manaasikanaa wa-tub \'alainaa; innaka antat Tawwaabur Raheem','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>129,'arabic_text'=>'رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Rabbanaa wab\'as feehim Rasoolam minhum yatloo \'alaihim aayaatika wa-yu\'allimuhumul Kitaaba wal-Hikmata wa-yuzakkeehim, innaka Antal \'Azeezul Hakeem','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>130,'arabic_text'=>'وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-mai-n yarghabu \'am Millati Ibraaheema illaa man safiha nafsah,(u) wa-laqadi astafainaahu fid dunyaa; wa-innahoo fil aakhirati laminas saaliheen','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>131,'arabic_text'=>'إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Iz qaala lahoo Rabbuhooo aslim; qaala aslamtu li-Rabbil \'aalameen','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>132,'arabic_text'=>'وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ','transliteration'=>'Wa-wassaa bihaaa Ibraaheemu baneehi wa-Ya\'qoobu, yaa-baniyya innal laahas tafaa lakumud deena falaa tamootunna illaa wa-antum muslimoon','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>133,'arabic_text'=>'أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ','transliteration'=>'Am kuntum shuhadaaa\'a iz hadara Ya\'qoobal mawtu iz qaala libaneehi maa ta\'budoona mim ba\'dee qaaloo na\'budu ilaahaka wa-ilaaha aabaaa\'ika Ibraaheema wa-Ismaa\'eela wa-Ishaaqa Ilaahanw waahidanw wa-nahnu lahoo muslimoon','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>134,'arabic_text'=>'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Tilka ummatun qad khalat; lahaa maa kasabat wa-lakum maa kasabtum; wa-laa tus\'aloona \'ammaa kaanoo ya\'maloon','page_number'=>20,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>135,'arabic_text'=>'وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Wa-qaaloo koonoo Hoodan aw Nasaaraa tahtadoo: qul bal Millata Ibraaheema Haneefa(nw); wa-maa kaana minal mushrikeen','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>136,'arabic_text'=>'قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ','transliteration'=>'Qoolooo aamannaa billaahi wa-maaa unzila ilainaa wa-maaa unzila ilaaa Ibraaheema wa-Ismaa\'eela wa-Ishaaqa wa-Ya\'qooba wal-Asbaati wa-maa ootiya Moosa wa-\'Eesaa wa-maaa ootiyan Nabiyyoona mir Rabbihim laa nufarriqoo baina ahadim minhum wa-nahnu lahoo muslimoon','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>137,'arabic_text'=>'فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Fa-in aamanoo bimisli maaa aamantum bihee faqadih tadaw; wa-in tawallau fa-innamaa hum fee shiqaaq(i); fasayak-feekahumul laah,(u) wa-Huwas Samee\'ul Aleem','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>138,'arabic_text'=>'صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ','transliteration'=>'Sibghatal laah(i); wa-man ahsanu minal laahi sibgha(tanw); wa-nahnu lahoo \'aabidoon','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>139,'arabic_text'=>'قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ','transliteration'=>'Qul atuhaaajjoonanaa fil laahi wa-Huwa Rabbunaa wa-Rabbukum wa-lanaa a\'maalunaa wa-lakum a\'maalukum wa-nahnu lahoo mukhlisoon','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>140,'arabic_text'=>'أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Am taqooloona inna Ibraaheema wa-Ismaa\'eela wa-Ishaaqa wa-Ya\'qooba wal-asbaata kaanoo Hoodan aw Nasaaraa: qul \'a-antum a\'lamu amil laah:(u) wa-man azlamu mimman katama shahaadatan \'indahoo minal laah:(u) wa-mal laahu bighaafilin \'ammaa ta\'maloon','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>141,'arabic_text'=>'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Tilka ummatun qad khalat; lahaa maa kasabat wa-lakum maa kasabtum; wa-laa tus\'aloona \'ammaa kaano ya\'maloon','page_number'=>21,'juz_number'=>1,'hizb_number'=>2,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>142,'arabic_text'=>'۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'^Sayaqoolus sufahaaa\'u minan naasi maa wallaahum \'an Qiblatihimul latee kaanoo \'alaihaa, qul lillaahil mashriqu walmaghrib,(u) yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem','page_number'=>22,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>143,'arabic_text'=>'وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ','transliteration'=>'Wa-kazaalika ja\'alnaakum ummatanw wasatal litakoonoo shuhadaaa\'a \'alan naasi wa-yakoonar Rasoolu \'alaikum shaheedaa: wa-maa ja\'alnal qiblatal latee kunta \'alaihaaa illaa lina\'lama mai yattabi\'ur Rasoola mimmai yanqalibu \'alaa \'aqibaiyh,(i) wa-in kaanat lakabeeratan illaa \'alal lazeena hadal laah:(u) wa-maa kaanal laahu liyudee\'a eemaanakum, innal laaha binnaasi la-Ra\'oofur Raheem','page_number'=>22,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>144,'arabic_text'=>'قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ','transliteration'=>'Qad naraa taqalluba wajhika fis samaaa\'(i); fala-nuwalliyannaka qiblatan tardaahaa, fawalli wajhaka shatral Masjidil haaraam,(i) wa-haisu maa kuntum fawalloo wujoohakum shatrah: wa-innal lazeena ootul Kitaaba laya\'lamoona annahul haqqu mir Rabbihim: wa-mal laahu bighaafilin \'ammaa ya\'maloon','page_number'=>22,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>145,'arabic_text'=>'وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-la\'in ataital lazeena ootul kitaaba bikulli aayatim maa tabi\'oo Qiblatak, wa-maaa anta bitaabi\'in Qiblatahum, wa-maa ba\'duhum bitaabi\'in Qiblata ba\'d,(in) wa-la\'init taba\'ta ahwaaa\'ahum mim ba\'di maa jaaa\'aka minal \'ilmi innaka izal laminaz zaalimeen','page_number'=>22,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>146,'arabic_text'=>'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'Allazeena aatainaahumul kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum; wa-inna fareeqam minhum layaktumoonal haqqa wa-hum ya\'lamoon','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>147,'arabic_text'=>'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ','transliteration'=>'Alhaqqu mir Rabbik(a); falaa takoonana minal mumtareen','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>148,'arabic_text'=>'وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wa-likullinw wijhatun huwa muwalleehaa; fastabiqul khairaat,(i) ayna maa takoonoo ya`ti bikumul laahu jamee\'aa,(n) innal laaha \'alaa kulli shai\'in qadeer','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>149,'arabic_text'=>'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Wa-min haisu kharajta fawalli wajhaka shatral Masjidil Haraam(i); wa-innahoo lalhaqqu mir Rabbik: wa-mal laahu bighaafilin \'ammaa ta\'maloon','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>150,'arabic_text'=>'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Wa-min haisu kharajta fawalli wajhaka shatral Masjidil Haraam,(i) wa-haisu maa kuntum fawalloo wujoohakum shatrahoo li\'allaa yakoona linnaasi \'alaikum hujjatun illal lazeena zalamoo minhum falaa takhshawhum wakhshawnee wa-li-utimma ni\'matee \'alaikum wa-la\'allakum tahtadoon','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>151,'arabic_text'=>'كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ','transliteration'=>'kamaaa arsalnaa feekum Rasoolam minkum yatloo \'alaikum aayaatina wa-yuzakkeekum wa-yu\'alli-mukumul kitaaba wal-hikmata wa-yu\'allimukum maa lam takoonoo ta\'lamoon','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>152,'arabic_text'=>'فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ','transliteration'=>'Fazkurooneee azkurkum washkuroo lee wa-laa takfuroon','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>153,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ','transliteration'=>'Yaaa-ayyuhal laazeena aamanus ta\'eenoo bissabri was-Salaah,(ti) innal laaha ma\'as saabireen','page_number'=>23,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>154,'arabic_text'=>'وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ','transliteration'=>'Wa-laa taqooloo limai-n yuqtalu fee sabeelil laahi amwaat,(um) bal ahyaaa\'unw wa-laakil laa tash\'uroon','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>155,'arabic_text'=>'وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ','transliteration'=>'Wa-lanablu-wannakum bishai\'im minal khawfi waljoo\'i wa-naqsim minal amwaali wal-anfusi was-samaraat:(i) wa-bashshiris saabireen','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>156,'arabic_text'=>'ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ','transliteration'=>'Allazeena izaaa asaabathum museebatun qaalooo innaa lillaahi wa-innaaa ilaihi raaji\'oon','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>157,'arabic_text'=>'أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ','transliteration'=>'Ulaaa\'ika \'alaihim salawaatum mir Rabbihim wa-rahma(tum); wa-ulaaa\'ika humul muhtadoon','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>158,'arabic_text'=>'۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ','transliteration'=>'^Innas Safaa wal-Marwata min sha\'aaa\'iril laah(i); faman hajjal Baita awi\'tamara falaa junaaha \'alaihi ai yattawwafa bihimaa, wa man tatawwa\'a khairan fa-innal laaha Shaakirun \'Aleem','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>159,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّٰعِنُونَ','transliteration'=>'Innal lazeena yaktumoona maaa anzalnaa minal baiyinaati walhudaa mim ba\'di maa baiyannaahu linnaasi fil kitaab(i) ulaaa\'ika yal\'anuhumul laahu wa-yal\'anuhumul laa-\'inoon','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>160,'arabic_text'=>'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Illal lazeena taaboo wa-as-lahoo wa-baiyanoo fa-ulaaa\'ika atoobu \'alaihim, wa-Anat Tawwaabur Raheem','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>161,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ','transliteration'=>'Innal lazeena kafaroo wamaa-too wa-hum kuffaar(un) ulaaa\'ika \'alaihim la-\'natul laahi walmalaa\'ikati wannaasi ajma\'een','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>162,'arabic_text'=>'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ','transliteration'=>'khaalideena feeha; laa yukhaffafu \'anhumul \'azaabu wa-laa hum yunzaroon','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>163,'arabic_text'=>'وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ','transliteration'=>'Wa-ilaahukum illaahunw waahid(ul); laaa ilaaha illaa Huwar Rahmaanur Raheem','page_number'=>24,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>164,'arabic_text'=>'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Inna fee khalqis samaawaati wal-ardi wakhtilaafil laili wannahaari walfulkil latee tajree fil bahri bimaa yanfa\'un naasa wa-maaa anzalal laahu minas samaaa\'i mim maaa\'in fa-ahyaa bihil arda ba\'da mawtihaa wa-bas-sa feehaa min kulli daaabbatinw wa-tasreefir riyaahi was-sahaabil musakhkhari bainas samaaa\'i wal-ardi la-aayaatil liqawminy ya\'qiloon','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>165,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ','transliteration'=>'Wa-minan naasi mai yattakhizu min doonil laahi andaadai-n yuhibboonahum kahubbil laah(i); wallazeena aamanooo ashaddu hubbal lillah: wa-lau yaral lazeena zalamoo iz yarawnal \'azaaba annal quwwata lillaahi jamee\'a(nw) wa-annal laaha shadeedul \'azaab','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>166,'arabic_text'=>'إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ','transliteration'=>'Iz tabarra-al lazeenat tubi\'oo minal lazeenat taba\'oo wa-ra-awul \'azaaba wa-taqatta\'at bihimul as-baab','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>167,'arabic_text'=>'وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ','transliteration'=>'Wa-qaalal lazeenat taba\'oo lau anna lanaa karratan fanatabarra-a minhum kamaa tabarra\'oo minnaa: kazaalika yureehimul laahu a\'maalahum hasaraatin \'alaihim; wa-maa hum bikhaarijeena minan Naar','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>168,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ','transliteration'=>'Yaaa-ayyuhan naasu kuloo mimmaa fil ardi halaalan taiyyiba(nw) wa-laa tattabi\'oo khutu-waatish Shaitaan,(i) innahoo lakum \'aduwwum mubeen','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>169,'arabic_text'=>'إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Innamaa yaa`murukum bis-sooo\'i walfah-shaaa\'i wa-an taqooloo alal laahi maa laa ta\'lamoon','page_number'=>25,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>170,'arabic_text'=>'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ','transliteration'=>'Wa-izaa qeela lahumut tabi\'oo maaa anzalal laahu qaaloo bal nattabi\'u maaa alfainaa \'alaihi aabaaa\'anaaa: awa-lau kaana aabaaa\'hum laa ya\'qiloona shai\'anw wa-laa yahtadoon','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>171,'arabic_text'=>'وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ','transliteration'=>'Wa-masalul lazeena kafaroo kamasalil lazee yan\'iqu bimaa laa yasma\'u illaa du\'aaa\'anw wa-nidaaa\'aa,(n) summum bukmun \'umyun fahum laa ya\'qiloon','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>172,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo kuloo min taiyibaati maa razaqnaakum washkuroo lillaahi in kuntum iyyaahu ta\'budoon','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>173,'arabic_text'=>'إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Innamaa harrama \'alaikumul maitata waddama wa-lahmal khinzeeri wa-maaa uhilla bihee lighairil laah(i); famanid turra ghaira baaghinw wa-laa \'aadin falaaa isma \'alaih,(i) innal laaha Ghafoorur Raheem','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>174,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ','transliteration'=>'Innal lazeena yaktumoona maaa anzalal laahu minal kitaabi wa-yashtaroona bihee samanan qaleel(an) ulaaa\'ika maa yaakuloona fee butoonihim illan Naar(a) wa-laa yukallimu-humul laahu Yawmal Qiyaamati wa-laa yuzakkeehim wa-lahum \'azaabun aleem','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>175,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ','transliteration'=>'Ulaaa\'ikal lazeenash tarawud dalaalata bilhudaa wal\'azaaba bilmaghfirah,(ti) famaaa as-barahum \'alan Naar','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>176,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ','transliteration'=>'Zaalika bi-annal laaha nazzalal kitaaba bilhaqq: wa-innal lazee-nakh talafoo fil kitaabi lafee shiqaaqim ba\'eed','page_number'=>26,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>177,'arabic_text'=>'۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ','transliteration'=>'^Laisal birra an tuwalloo wujoohakum qibalal mashriqi walmaghribi wa-laakinnal birra man aamana billaahi wal-yawmil aakhiri wal-malaaa\'ikati wal-kitaabi wan-nabiyyeena wa-aatal maala \'alaa hubbihee zawil qurbaa walyataa-maa walmasaakeena wabnas sabeeli wassaaa\'ileena wa-fir riqaabi wa-aqaamas salaata wa-aataz zakaata walmoofoona bi-ahdihim izaa \'aahadoo; wa-saabireena fil baasaaa\'i waddarraaa\'i wa-heenal baas:(i) ulaaa\'ikal lazeena sadaqoo; wa-ulaaa\'ika humul muttaqoon','page_number'=>27,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>178,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo kutiba alaikumul qisaasu fil qatlaa; alhurru bilhurri wal\'abdu bil\'abdi wal-unsaa bil-unsaa, faman \'ufiya lahoo min akheehi shai\'un fattibaa\'um bilma\'roofi wa-adaaa\'un ilaihi bi-ihsaan:(in) zaalika takhfeefum mir rabbikum wa-rahmah:(tun) famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem','page_number'=>27,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>179,'arabic_text'=>'وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Wa-lakum fil qisaasi hayaatuin yaaa-ulil albaabi la\'allakum tattaqoon','page_number'=>27,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>180,'arabic_text'=>'كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ','transliteration'=>'Kutiba \'alaikum izaa hadara ahadakumul mawtu in taraka khairanil wasiyyatu lilwaalidaini wal-aqrabeena bil-ma\'roof(i); haqqan \'alal muttaqeen','page_number'=>27,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>181,'arabic_text'=>'فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Famam baddalahoo ba\'da-maa sami\'ahoo fa-innamaaa ismuhoo \'alal lazeena yubaddi-loonah,(u) innal laha Samee\'un \'Aleem','page_number'=>27,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>182,'arabic_text'=>'فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Faman khaafa mim moosin janafan aw isman fa-aslaha bainahum falaaa ismaa \'alayh,(i) innal laaha Ghafoorur Raheem','page_number'=>28,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>183,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo kutiba \'alaikumus Siyaamu kamaa kutiba \'alal lazeena min qablikum la\'allakum tattaqoon','page_number'=>28,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>184,'arabic_text'=>'أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Ayyaamam ma\'doodaat,(in) faman kaana minkum mareedan aw\' alaa safarin fa\'iddatum min ayyaamin ukhar,(a) wa-\'alal lazeena yuteeqoonahoo fidyatun ta\'aamu miskeen(in); faman tatawwa\'a khairan fahuwa khairul lah,(oo) wa-an tasoomoo khairul lakum; in kuntum ta\'lamoon','page_number'=>28,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>185,'arabic_text'=>'شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Shahru Ramadaanal lazeee unzila feehil Qur\'aanu hudal linnaasi wa-baiyinaatim minal hudaa wal-furqaan,(i) faman shahida minkumush shahra fal-yasum(hu); wa-man kaana mareedan aw \'alaa safarin fa\'iddatum min ayyaamin ukhar:(a) yureedul laahu bikumul yusra wa-laa yureedu bikumul \'usra wa-litukmilul \'iddata wa-litukabbirul laaha \'alaa maa hadaakum wa-la\'allakum tashkuroon','page_number'=>28,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>186,'arabic_text'=>'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ','transliteration'=>'Wa-izaa sa-alaka \'ibaadee \'annnee fa-innee qareeb(un); ujeebu da\'watad daa\'i izaa da\'aan(i); falyastajeeboo lee wal-yu\'minoo bee la\'allahum yarshudoon','page_number'=>28,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>187,'arabic_text'=>'أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ','transliteration'=>'Uhilla lakum laylatas Siyaamir rafasu ilaa nisaaa\'ikum, hunna libaasul lakum wa-antum libaasul lahunn:(a) \'alimal laahu annakum kuntum takhtaanoona anfusakum fataaba \'alaikum wa\'afaa \'ankum; fal\'aana baashiroo-hunna wabtaghoo maa katabal laahoo lakum, wa-kuloo washraboo hattaa yatabaiyana lakumul khaitul abyadu minal khaitil aswadi minal fajr(i); summa atimmus Siyaama ilal layl,(i) wa-laa tubaashiroo-hunna wa-antum \'aakifoona fil masaajid:(i) tilka hudoodul laahi falaa taqraboohaa: kazaalika yubaiyinul laahu aayaatihee linnaasi la\'allahum yattaqoon','page_number'=>29,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>188,'arabic_text'=>'وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-laa taakuloo amwaalakum bainakum bilbaatili wa-tudloo bihaaa ilal hukkaami litaakuloo fareeqam min amwaalin naasi bil-ismi wa-antum ta\'lamoon','page_number'=>29,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>189,'arabic_text'=>'۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'^Yas\'aloonaka \'anil ahilla(ti); qul hiya mawaaqeetu linnaasi wal-Hajj:(i) wa-laisal birru bi-an ta\'tul buyoota min zuhoorihaa wa-laakinnal birra manit taqaa: wa\'tul buyoota min abwaa-bihaa, wattaqul laaha la\'allakum tuflihoon','page_number'=>29,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>190,'arabic_text'=>'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ','transliteration'=>'Wa-qaatiloo fee sabeelil laahil lazeena yuqaatiloonakum wa-laa ta\'tadooo, innal laaha laa yuhibbul mu\'tadeen','page_number'=>29,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>191,'arabic_text'=>'وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ','transliteration'=>'Waq-tuloohum haisu saqif-tumoohum wa-akhrijoohum min haisu akhrajookum, walfitnatu ashaddu minal qatl,(i) wa-laa tuqaa-tiloohum \'indal Masjidil Haraami hattaa yuqaatilookum feeh(i); fa-in qaata-lookum faq-tuloohum: kazaalika jazaaa\'ul kaafireen','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>192,'arabic_text'=>'فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Fa-i\'ninn tahau fa-innal laaha Ghafoorur Raheem','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>193,'arabic_text'=>'وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ','transliteration'=>'Wa-qaatiloohum hatta laa takoona fitnatunw wa-yakoonad deenu lillaah(i); fa-inin tahau falaa \'udwaana illaa \'alaz zaalimeen','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>194,'arabic_text'=>'ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ','transliteration'=>'Ash-Shahrul Haraamu bish-Shahril Haraami wal-hurumaatu qisaas,(un) famani\' tadaa \'alaikum fa\'tadoo \'alaihi bimisli ma\' tadaa \'alaikum, wattaqul laaha wa\'lamooo annal laaha ma\'al muttaqeen','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>195,'arabic_text'=>'وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-anfiqoo fee sabeelil laahi wa-laa tulqoo bi-aydeekum ilat tahluka\'( ti) wa - ahsinoo\' innal laaha yuhibbul muhsineen','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>196,'arabic_text'=>'وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Wa-atimmul Hajja wal-Umarata lillaah,(i) fa-in uhsirtum famas taisara minal had(yi); walaa tahliqoo ru\'oosakum hatta yablughal hadyu mahilla,(hu) faman kaana minkum mareedan aw biheee azam mir ra\'sihee fafidyatum min Siyaamin aw sadaqatin aw nusuk,(in) fa-izaaa amintum faman tamatta\'a bil-\'Umrati ilal Hajji famas taisara minal had,(yi) famal lam yajid fa-Siyaamu salaasti ayyaamin fil Hajji wa-sab\'atin izaa raja\'tum: tilka \'asharatun kaamilah:(tun) zaalika limal lam yakun ahluhoo haadiril Masjidil Haraam,(i) wattaqul laaha wa\'lamoo annal laaha shadeedul \'iqaab','page_number'=>30,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>197,'arabic_text'=>'ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ','transliteration'=>'Al-Hajju ashhurum ma\'-loomaat,(tun) faman farada feehinnal hajja falaa rafasa wa-laa fusooqa wa-laa jidaala fil Hajj:(i) wa-maa taf\'aloo min khairien ya\'lamhul laah:(u) wa-tazawwadoo fa-inna khairaz zaadit taqwaa, wattaqooni yaaa-ulil albaab','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>198,'arabic_text'=>'لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ','transliteration'=>'Laisa \'alaikum junaahun an tabtaghoo fad-lam mir rabbikum, fa-izaaa afadtum min \'Arafaatin fazkurul laaha \'indal Mash\'aril Haraam(i); waz-kuroohu kamaa hadaakum wa-in kuntum min qablihee laminad daaalleen','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>199,'arabic_text'=>'ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Summa afeedoo min haisu afaadan naasu wastagh firullaah,(a) innal laaha Ghafoorur Raheem','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>200,'arabic_text'=>'فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ','transliteration'=>'Fa-iza qadaitum manaa-sikakum fazkurul laaha kazikrikum aabaaa\'akum aw ashadda zikraa:(n) faminan naasi ma-ien yaqoolu Rabbanaaa aatinaa fid dunyaa wa-maa lahoo fil Aakhirati min khalaaq','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>201,'arabic_text'=>'وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ','transliteration'=>'Wa-minhum maien yaqoolu rabbanaaa aatina fid dunyaa hasanatanw wa-fil aakhirati hasanatanw wa-qinaa azaaban Naar','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>202,'arabic_text'=>'أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Ulaaa\'ika lahum naseebum mimmaa kasaboo, wal-laahu saree\'ul hisaab','page_number'=>31,'juz_number'=>2,'hizb_number'=>3,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>203,'arabic_text'=>'۞ وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'^Wazkurul laaha feee ayyaamin ma\'doodaat,(in) faman ta\'ajjala fee yawmaini falaaa ismaa \'alaihi wa-man ta-akhara falaaa isma \'alayh,(i) limanit taqaa: wattaqul laaha wa\'lamooo annakum ilaihi tuhsharoon','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>204,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ','transliteration'=>'Wa-minan naasi mai yu\'jibuka qawluhoo fil hayaatid dunyaa wa-yushhidul laaha \'alaa maa fee qalbihee wa-huwa aladdul khisaam','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>205,'arabic_text'=>'وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ','transliteration'=>'Wa-izaa tawallaa sa\'aa fil-ardi liyufsida feeha wa-yuhlikal harsa wannasl:(a) wal laahu laa yuhibbul fasaad','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>206,'arabic_text'=>'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ','transliteration'=>'Wa-izaa qeela lahut taqil laaha akhazathul izzatu bil-ism,(i) fahasbuhoo jahannam,(u) wa-labi\'sal mihaad','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>207,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ','transliteration'=>'Wa-minan naasi maien yashree nafsahub tighaaa\'a mardaatil laah,(i) wallaahu ra\'oofum bil\'ibaad','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>208,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanud khuloo fis silmi kaaaffa(tanw) wa-laa tattabi\'oo khutuwaatish Shaitaan,(i) innahoo lakum \'aduwwum mubeen','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>209,'arabic_text'=>'فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','transliteration'=>'Fa-in zalaltum min ba\'di maa jaaa\'atkumul baiyinaatu fa\'lamoo annal laaha \'Azeezun hakeem','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>210,'arabic_text'=>'هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Hal yanzuroona illaaa a-ien ya\'tiya-humul laahu fee zulalim minal ghamaami walmalaaa\'ikatu wa-qudiyal amr,(u) wa-ilal laahi turja\'ul umoor','page_number'=>32,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>211,'arabic_text'=>'سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Sal Banee Israaa\'eela kam aatainaahum min aayatim baiyinah:(tin) wa-mai yubaddil ni\'matal laahi mim ba\'di maa jaaa\'athu fa-innal laaha shadeedul \'iqaab','page_number'=>33,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>212,'arabic_text'=>'زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ','transliteration'=>'Zuyyina lillazeena kafarul hayaatud dunyaa wa-yas-kharoona minal lazeena aamanoo wallazeenat taqaw fawqahum yawmal Qiyaamah:(ti) wallaahu yarzuqu ma-ien yashaaa\'u bighairi hisaab','page_number'=>33,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>213,'arabic_text'=>'كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ','transliteration'=>'Kaanan naasu ummatanw waahidatan fab\'asal laahun Nabiyyeena mubashshireena wa-munzireen(a) wa-anzala ma\'ahumul kitaaba bilhaqqi liyahkuma bainan naasi feemakh talafoo feeh,(i) wa-makh talafa feehi \'illal lazeena ootoohu mim ba\'di maa jaaa\'athumul baiyinaatu baghyam bainahum; fahadal laahul lazeena aamanoo limakh talafoo feehi minal haqqi bi-iznih:(i) wallaahu yahdee ma-ien yashaaa\'u ilaa Siraatim Mustaqeem','page_number'=>33,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>214,'arabic_text'=>'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ','transliteration'=>'Am hasibtum an tadkhulul jannata wa-lammaa yaa-tikum masalul lazeena khalaw min qablikum; massathumul baasaaa\'u waddarraaaa\'u wa-zulziloo hattaa yaqoolar Rasoolu wallazeena aamanoo ma\'ahoo mataa nasrul laah:(i) alaaa inna nasral laahi qareeb','page_number'=>33,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>215,'arabic_text'=>'يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ','transliteration'=>'Yas\'aloonaka maazaa yunfiqoon(a); qul maaa anfaqtum min khairin falil-waalidaini wal-aqrabeena walyataamaa wal-masaakeeni wabnis sabeel:(i) wa-maa taf\'aloo min khairin fa-innal laaha bihee \'Aleem','page_number'=>33,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>216,'arabic_text'=>'كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Kutiba alaikumul qitaalu wa-huwa kurhul lakum; wa\'asaaa an takrahoo shai\'anw wa-huwa khairul lakum; wa\'asaaa an tuhibbo shai\'anw wa-huwa sharrul lakum: wallaahu ya\'lamu wa-antum laa ta\'lamoon','page_number'=>34,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>217,'arabic_text'=>'يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Yas\'aloonaka \'anish Shahril Haraami qitaalin feeh(i); qul qitaalun feehi kabeer(unw); wa-saddun \'an sabeelil laahi wa-kufrum bihee wal-Masjidil Haraam(i) wa-ikhraaju ahlihee minhu akbaru \'indal laah,(i) wal-fitnatu akbaru minal qatl:(i) wa-laa yazaaloona yuqaatiloonakum hatta yaruddookum \'an deenikum inis tataa\'oo, wa-ma-ien yartadid minkum \'an deenihee fayamut wahuwa kaafirun fa-ulaaa\'ika habitat a\'maaluhum fid dunyaa wal-aakhira(ti); wa-ulaaa\'ika as-haabun Naar(i); hum feehaa khaalidoon','page_number'=>34,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>218,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Innal lazeena aamanoo wallazeena haajaroo wa-jaahadoo fee sabeelil laahi ulaaa\'ika yarjoona rahmatal laah,(i) wallaahu Ghafoorur Raheem','page_number'=>34,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>219,'arabic_text'=>'۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ','transliteration'=>'^Yas\'aloonaka \'anil khamri walmaisir(i); qul feehimaaa ismun kabeerunw wa-manaafi\'u linnaasi wa-ismuhumaa akbaru min naf\'ihimaa: wa-yas\'aloonaka maaza yunfiqoona qulil \'afuw:(a) kazaalika yubaiyinul laahu lakumul aayaati la\'allakum tatafakkaroon','page_number'=>34,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>220,'arabic_text'=>'فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ','transliteration'=>'Fid dunyaa wal-aakhirah:(ti) wa-yas\'aloonaka \'anil yataamaa; qul islaahul lahum khayr(un); wa-in tukhaalitoohum fa-ikhwaanukum, wallaahu ya\'lamul mufsida minal muslih,(i) wa-law shaaa\'al laahu la-a\'natakum, innal laaha \'Azeezun Hakeem','page_number'=>35,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>221,'arabic_text'=>'وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Wa-laa tankihul mushrikaati hattaa yu\'minn,(a) wa-la-amatum mu\'minatun khairum mim mushrikatinw wa-lau a\'jabatkum: wa-laa tunkihul mushrikeena hattaa yu\'minoo, wa-la\'abdum mu\'minun khairum mim mushrikinw wa-lau \'ajabakum: ulaaa\'ika yad\'oona ilan Naar(i); wallaahu yad\'ooo ilal Jannati wal-maghfirati biiznih(ee); wa-yubaiyinu Aayaatihee linnaasi la\'allahum yatazakkaroon','page_number'=>35,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>222,'arabic_text'=>'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ','transliteration'=>'Wa-yas\'aloonaka \'anil maheed(i); qul huwa aza(n) fa\'tazilun nisaaa\'a fil maheed(i); wa-laa taqraboo-hunna hattaa yathurn(a); fa-izaa tatah-harrna faatoohunna min haisu amarakumul laah,(u) innal laaha yuhibbut Tawwaabeena wa-yuhibbul mutatahhireen','page_number'=>35,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>223,'arabic_text'=>'نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Nisaaa\'ukum harsul lakum faatoo harsakum annaa shi\'tum; wa-qaddimoo li-anfusikum, wattaqul laaha wa\'lamooo annakum mulaaqooh:(u) wa-bash-shiril mu\'mineen','page_number'=>35,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>224,'arabic_text'=>'وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ','transliteration'=>'Wa-laa taj\'alul laaha \'urdatal li-aymaanikum an tabarroo wa-tattaqoo wa-tuslihoo bainan naas:(i) wallaahu Samee\'un \'Aleem','page_number'=>35,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>225,'arabic_text'=>'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ','transliteration'=>'Laa yu\'aakhi-zukumul laahu billaghwi feee aymaa-nikum wa-laakien yu\'aakhi-zukum bimaa kasabat quloo-bukum: wallaahu Ghafoorun Haleem','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>226,'arabic_text'=>'لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Lillazeena yu\'loona min nisaaa\'ihim tarabbusu arba\'ati ashhur(in); fa-in faaa\'oo fa-innal laaha Ghafoorur Raheem','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>227,'arabic_text'=>'وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Wa-in \'azamut talaaqa fa-innal laaha Samee\'un \'Aleem','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>228,'arabic_text'=>'وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','transliteration'=>'Walmutallaqaatu yatarab-basna bi-anfusi-hinna salaasata qurooo\',(in) wa-laa yahillu lahunna aien yaktumna maa khalaqal laahu feee arhaami-hinna in kunna yu\'minna bil-laahi wal-yawmil aakhir,(i) wa-bu\'oola-tuhunna ahaqqu biraddi-hinna fee zaalika in araadooo islaa-haa,(n) wa-lahunna mislul lazee alaihinna bilma\'roof,(i) wa-lir-rijjaali \'alaihinna daraja:(tun) wallaahu \'Azeezun Hakeem','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>229,'arabic_text'=>'ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Attalaaqu marrataan(i); fa-imsaakum bima\'roofin aw tasreehum bi-ihsaan:(in) wa-laa yahillu lakum an taakhuzoo mimmaaa aataitumoohunna shai\'an illaaa aien yakhaafaaa alla yuqeemaa hudoodal lah(i); fa-in khiftum allaa yuqeemaa hudoodal laahi falaa junaaha \'Alaihimaa feemaf tadat bih:(ee) tilka hudoodul laahi falaa ta\'tadoohaa, wa-maien yata\'adda hudoodal laahi fa-ulaaa\'ika humuz zaalimoon','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>230,'arabic_text'=>'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Fa-in talla-qahaa falaa tahillu lahoo mim ba\'du hattaa tankiha zawjan ghairah:(u) fa-in tallaqahaa falaa junaaha \'alaihimaaa aien yata-raaja\'aaa in zannaaa aien yuqeemaa hudoodal laah:(i) wa-tilka hudoodul laahi yubai-yyinuhaa liqawmien ya\'lamoon','page_number'=>36,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>231,'arabic_text'=>'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Wa-izaa tallaq-tumun nisaaa\'a faba-laghna ajala-hunna fa-amsi-koohunna bima\'roofin aw sarrihoo-hunna bima\'roof,(in) wa-laa tumsikoo-hunna diraa-ral lita\'tadoo, wa-maien yaf\'al zaalika faqad zalama naf-sah,(u) wa-laa tat-takhizooo aayaatil laahi huzuwaa,(nw) wazkuroo ni\'matal laahi \'alaikum wa-maaa anzala \'alaikum minal kitaabi wal-hikmati ya\'izukum bih,(i) wattaqul laaha wa\'lamooo annal laaha bikulli shai\'in \'Aleem','page_number'=>37,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>232,'arabic_text'=>'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Wa-izaa tallaqtumun nisaaa\'a fabalaghna ajalahunna falaa ta\'duloo-hunna aien yankihna azwaaja-hunna izaa taraadaw bainahum bilma\'roof:(i) zaalika yoo\'azu bihee man kaana minkum yu\'minu billaahi wal-yawmil aakhir:(i) zaalikum azkaa lakum wa-at-har:(u) wallaahu ya\'lamu wa-antum laa ta\'lamoon','page_number'=>37,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>233,'arabic_text'=>'۞ وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'^Walwaa-lidaatu yurdi\'na awlaada-hunna hawlaini kaamilain(i); liman araada a-ien yutimmar radaa\'ah,(ta) wa-\'alal mawloodi lahoo rizqu-hunna wa-kiswatuhunna bilma\'roof,(i) laa tukallafu nafsun illaa wus\'ahaa, laa tudaaarra waalidatum biwaladihaa wa-laa mawloodul lahoo biwaladih,(i) wa\'alal waarisi mislu zaalik:(a) fa-in araadaa Fisaalan \'an taraadim minhumaa wa-tashaawurin falaa junaaha \'alaihim:(a) wa-in aradttum an tastardi\'ooo awlaadakum falaa junaaha \'alaikum izaa sallamtum maaa aataitum bilma\'roof:(i) wattaqul laaha wa\'lamooo annal laaha bimaa ta\'maloona baseer','page_number'=>37,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>234,'arabic_text'=>'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Wallazeena yutawaffawna minkum-wa yazaroona azwaajaien yatarabbasna bi-anfusi-hinna arba\'ata ashhurinw wa\'ashra(n); fa-izaa balaghna ajalahunna falaa junaaha \'alaikum feemaa fa\'alna feee anfusi-hinna bilma\'roof:(i) wallaahu bimaa ta\'maloona Khabeer','page_number'=>38,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>235,'arabic_text'=>'وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ','transliteration'=>'Wa-laa junaaha \'alaikum feema \'arrad-tum bihee min khit-batin nisaaa\'ee aw aknantum feee anfusikum, \'alimal laahu annakum sataz-kuroo-nahunna wa-laakil laa tuwaa\'idoohunna sirran illaaa an taqooloo qawlam ma\'roofaa,(n) wa-laa ta\'zimoo \'uqdatan nikaahi hattaa yablughal kitaabu ajalah,(u) wa\'lamooo annal laaha ya\'lamu maa feee anfusikum fah-zarooh,(u) wa\'lamooo annal laaha Ghafoorun Haleem','page_number'=>38,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>236,'arabic_text'=>'لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ','transliteration'=>'Laa junaaha \'alaikum in tallaq-tumun nisaaa\'a maa lam tamassoo-hunna aw tafridoo lahunna fareedah,(tan) wa-matti\'oohunna \'alal moosi\'ee qadaruhoo wa-\'alal muqtiri qadaruhoo matta\'am bil-ma\'roof(i); haqqan \'alal muhsineen','page_number'=>38,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>237,'arabic_text'=>'وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ','transliteration'=>'Wa-in tallaqtumoo-hunna min qabli an tamassoo-hunna wa-qad farad-tum lahunna fareeda-tan fanis-fu maa farad-tum illaaa aien ya\'foona aw ya\'fuwal lazee biyadihee \'uqdatun nikaah,(i) wa-an ta\'fooo aqrabu littaqwaa, wa-laa tansawul fadla bainakum, innal laaha bimaa ta\'maloona Baseer','page_number'=>38,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>238,'arabic_text'=>'حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ','transliteration'=>'Haafizoo \'alas salawaati was-Salaatil Wustaa wa-qoomoo lillaahi qaaniteen','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>239,'arabic_text'=>'فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ','transliteration'=>'Fa-in khiftum farijaalan aw rukbaana(n); fa-izaaa amintum fazkurul laaha kamaa \'allamakum maa lam takoonoo ta\'lamoon','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>240,'arabic_text'=>'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wallazeena yutawaf-fawna minkum wa-yazaroona azwaajanw wasiyyatal li-azwaajihim mataa\'an ilal hawli ghaira ikhraaj,(in) fa-in kharajna falaa junaaha \'alaikum fee maa fa\'alna feee anfusihinna min ma\'roof:(in) wal-laahu Azeezun Hakeem','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>241,'arabic_text'=>'وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ','transliteration'=>'Wa-lilmutallaqaati mataa\'um bil-ma\'roof(i); haqqan \'alal muttaqeen','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>242,'arabic_text'=>'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum ta\'qiloon','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>243,'arabic_text'=>'۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ','transliteration'=>'^Alam tara ilal lazeena kharajoo min diyaari-him wa-hum uloofun hazaral mawt(i) faqaaala lahumul laahu mootoo summa ahyaahum, innal laaha lazoo fadlin \'alan naasi wa-laakinna aksaran naasi laa yashkuroon','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>244,'arabic_text'=>'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Wa-qaatiloo fee sabeelil laahi wa\'lamooo annal laaha Samee\'un \'Aleem','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>245,'arabic_text'=>'مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Man zal lazee yuqridul laaha qardan hasanan fayudaa-\'ifahoo lahoo ad\'aafan kaseerah,(tan) wallaahu yaqbidu wa-yabsutu wa-ilaihi turja\'oon','page_number'=>39,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>246,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ','transliteration'=>'Alam tara ilal mala-i mim Baneee Israaa\'eela mim ba\'di Moosaaa iz qaaloo li-Nabiyyil lahumub \'as lanaa malikan nuqaatil fee sabeelil laah(i); qaala hal \'asaitum in kutiba \'alaikumul qitaalu allaa tuqaatiloo; qaaloo wa-maa lanaaa allaa nuqaatila fee sabeelil laahi wa-qad ukhrijnaa min diyaarinaa wa-abnaaa\'inaa; falammaa kutiba \'alaihimul qitaalu tawallaw illaa qaleelam minhum: wallaahu \'aleemum bizzaalimeen','page_number'=>40,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>247,'arabic_text'=>'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ','transliteration'=>'Wa-qaala lahum Nabiy-yuhum innal laaha qad ba\'asa lakum Taaloota malikaa,(an) qaalooo annaa yakoonu lahul mulku \'alainaa wa-nahnu ahaqqu bilmulki minhu wa-lam yu\'ta sa\'atam minal maal,(i) qaala innal laahas tafaahu \'alaikum wa-zaadahoo bastatan fil \'ilmi waljism(i); wallaahu yu\'tee mulkahoo maien yashaaa\',(u) wallaahu Waasi\'un \'Aleem','page_number'=>40,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>248,'arabic_text'=>'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-qaala lahum Nabiyyuhum inna Aayata mulkiheee aien ya`atiya-kumut Taabootu feehi sakeenatum mir Rabbikum wa-baqiyyatum mimmaa taraka Aalu Moosa wa-Aalu Haaroona tahmi-luhul malaaa\'ikah,(tu) inna fee zaalika la-Aayatal lakum in kuntum mu\'mineen','page_number'=>40,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>249,'arabic_text'=>'فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ','transliteration'=>'Falammaa fasala Taalootu biljunoodi qaala innal laaha mub-taleekum binahar(in) faman shariba minhu falaisa minnee wa-mal lam yat\'amhu fa-innahoo minneee illaa manigh tarafa ghurfatam biyadih,(i) fashariboo minhu illaa qaleelam minhum, falammaa jaawazahoo huwa wallazeena aamanoo ma\'ahoo qaaloo laa taaqata lanal yawma bi-Jaaloota wa-junoodih,(i) qaalal lazeena yazunnoona annahum mulaaqul laahi kam min fi\'atin qaleelatin ghalabat fi\'atan kaseeratam bi-iznil laah:(i) wallaahu ma\'as saabireen','page_number'=>41,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>250,'arabic_text'=>'وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-lammaa barazoo li-Jaaloota wa-junoodihee qaaloo Rabbanaaa afrigh \'alainaa sabranw wa-sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen','page_number'=>41,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>251,'arabic_text'=>'فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Fahaza-moohum bi-iznil laah(i) wa-qatala Daawoodu jaaloota wa-aataahul laahul mulka Wal-Hikmata wa\'allamahoo mimmaa yashaaa\':(u) wa-law-laa daf\'ul laahin naasa ba\'dahum biba\'dil lafasadatil ard(u) wa-laakinnal laaha zoo fadlin \'alal \'aalameen','page_number'=>41,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>252,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ','transliteration'=>'Tilka Aayaatul laahi natloohaa \'alaika bilhaqq,(i) wa-innaka laminal mursaleen','page_number'=>41,'juz_number'=>2,'hizb_number'=>4,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>253,'arabic_text'=>'۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ','transliteration'=>'^Tilkar Rusulu faddalnaa ba\'dahum \'alaa ba\'d. minhum man kallamal laah(u); wa-rafa\'a ba\'dahum darajaat,(in) wa-aatainaa \'Eesab na Maryamal baiyinaati wa-ayyadnaahu bi-Roohil Qudus:(i) wa-law shaaa\'al laahu maq tatalal lazeena mim ba\'dihim mim ba\'di maa jaaa\'athumul baiyinaat(u) wa-laakinikh talafoo faminhum man aamana wa-minhum man kafar,(a) wa-law shaaa\'al laahu maq tataloo wa-laakinnal laaha yaf\'alu maa yureed','page_number'=>42,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>254,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo anfiqoo mimmaa razaq-naakum min qabli aien ya`atiya yawmul laa bai\'un feehee wa-la khullatunw wa-laa shafaa\'ah:(tun) wal-kaafiroona humuz zaalimoon','page_number'=>42,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>255,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ','transliteration'=>'Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom,(u) laa taakhuzuhoo sinatunw wa-laa nawm,(un) lahoo maa fis samaawaati wa-maa fil ard:(i) man zal lazee yashfa\'u indahooo illaa bi-iznih,(i) ya\'lamu maa baina aydeehim wa-maa khalfahum; wa-laa yuheetoona bishai\'im min \'ilmihee illaa bimaa shaaa\',(a) wasi\'a Kursiyyuhus samaawaati wal-ard(a); wa-laa Ya\'ooduhoo hifzuhum,(aa) wa-Huwal Aliyyul \'Azeem','page_number'=>42,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>256,'arabic_text'=>'لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','transliteration'=>'Laaa ikraaha fid deen(i); qadt tabiyanar rushdu minal ghayy,(i) famai yakfur bit-Taaghooti wa-yu\'mim billaahi faqadis tamsaka bil\'urwatil wusqaa lan fisaama lah:(aa) wallaahu Samee\'un \'Aleem','page_number'=>42,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>257,'arabic_text'=>'ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Allaahu waliyyul lazeena aamanoo yukhrijuhum minaz zulumaati ilan noor(i); wallazeena kafarooo awliyaaa\'uhumut Taaghootu yukhrijoo-nahum minan noori ilaz zulumaat:(i) ulaaa\'ika As-haabun Naar(i); hum feehaa khaalidoon','page_number'=>43,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>258,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Alam tara ilal lazee Haaajja Ibraaheema fee Rabbiheee an aataahul laahul mulka iz qaala Ibraaheemu Rabbiyal lazee yuhyee wa-yumeetu qaala ana uhyee wa-umeet(u); qaala Ibraaheemu fa-innal laaha yaatee bishshamsi minal mashriqi faati bihaa minal maghribi fabuhital lazee kafar:(a) wallaahu laa yahdil qawmaz zaalimeen','page_number'=>43,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>259,'arabic_text'=>'أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Aw kallazee marra \'alaa qaryatinw wa-hiya khaawiyatun \'alaa \'urooshihaa qaala annaa yuhyee haazihil laahu ba\'da mawtih(aa); fa-amaatahul laahu mi\'ata \'aamin summa ba\'a-sah(oo); qaala kam labist(a); qaala labistu yawman aw ba\'da yawm(in); qaala bal labista mi\'ata \'aamin fanzur ilaa ta\'aamika wa-sharaabika lam yatasannah; wanzur ilaa himaarika wa-linaj\'alaka Aayatal linnaas(i); wanzur ilal \'izaami kaifa nunshizuhaa summa naksoohaa lahmaa,(n) falammaa tabaiyyana lahoo qaala a\'lamu annal laaha \'alaa kulli shai\'in Qadeer','page_number'=>43,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>260,'arabic_text'=>'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wa-iz qaala Ibraaheemu Rabbi arinee kaifa tuhyil mawtaa; qaala awa-lam tu\'min; qaala balaa wa-laakil liyatma\'inna qalbee; qaala fakhuz arab\'atam minat tairi fasurhunna ilaika summaj \'al a\'alaa kulli jabalim minhunna juz\'a(n) summad\'uu hunna ya`ateenaka sa\'yaa,(n) wa\'lam annal laaha \'Azeezun Hakeem','page_number'=>44,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>261,'arabic_text'=>'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','transliteration'=>'Masalul lazeena yunfiqoona amwaalahum fee sabeelil laahi kamasali habbatin ambatat sab\'a sanaabil(a) fee kulli sumbulatim mi\'atu habbah:(tin) wallaahu yudaa\'ifu limaien yashaaa:(oo) wallaahu Waasi\'un \'Aleem','page_number'=>44,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>262,'arabic_text'=>'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Allazeena yunfiqoona amwaalahum fee sabeelil laahi summa laa yutbi\'oona maaa anfaqoo mann-anw wa-laaa azal lahum ajruhum \'inda Rabbihim; wa-laa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>44,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>263,'arabic_text'=>'۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ','transliteration'=>'^Qawlum ma\'roofunw wa-maghfiratun khairum min sadaqatien yatba\'uhaaa azaa: wallaahu Ghaniyyun Haleem','page_number'=>44,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>264,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo laa tubtiloo sadaqaatikum bilmanni wal-azaa kallazee yunfiqu maa-lahoo ri\'aaa\'an naasi wa-laa yu\'minu billaahi wal-yawmil aakhir(i); fama-saluhoo kamasali safwaanin \'alaihi turaabun fa-asaabahoo waabilun fatara-kahoo saldaa(l); laa yaqdiroona \'alaa shai\'im mimmaa kasaboo: wallaahu laa yahdil qawmal kaafireen','page_number'=>44,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>265,'arabic_text'=>'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ','transliteration'=>'Wa-masalul lazeena yunfiqoona amwaalahu mubtighaaa\'a mardaatil laahi wa-tasbeetam min anfusihim kamasali jannatim birabwatin asaa-bahaa waabilun fa-aatat ukulahaa di\'faini fa-il lam yusibhaa waabilun fatal:(lun) wallaahu bimaa ta\'maloona Baseer','page_number'=>45,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>266,'arabic_text'=>'أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ','transliteration'=>'Ayawaddu ahadukum an takoona lahoo jannatum min nakheelinw wa-a\'naabin tajree min tahtihal anhaar(u) lahoo feehaa min kullis samaraati wa-asaa-bahul kibaru wa-lahoo zurriyyatun du\'afaaa\'(u) fa-asaabahaaa i\'saarun feehi naarun fahtaraqat: kazaalika yubaiyinul laahu lakumul aayaati la\'allakum tata-fakkaroon','page_number'=>45,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>267,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ','transliteration'=>'Yaaa-\'ayyuhal lazeena aamanooo anfiqoo min taiyibaati maa kasabtum wa-mimmaaa akhrajna lakum minal ard(i); wa-laa tayammamul khabeesa minhu tunfiqoon(a) wa-lastum bi-aakhizeehi illaaa an tughmidoo feeh,(i) wa\'lamooo annal laaha Ghaniyyun Hameed','page_number'=>45,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>268,'arabic_text'=>'ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ','transliteration'=>'Ash-Shaitaanu ya\'idukumul faqra wa-ya\'murukum bil-fahshaaa(\'i); wallaahu ya\'idukum maghfiratam minhu wa-fadlaa:(n) wallaahu Waasi\'un \'Aleem','page_number'=>45,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>269,'arabic_text'=>'يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Yu\'til Hikmata maien yashaaa,(\'oo); wa-maien yu\'tal Hikmata faqad ootiya khairan kaseeraa:(n) wa-maa yazzakkaru illaaa ulul albaab','page_number'=>45,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>270,'arabic_text'=>'وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ','transliteration'=>'Wa-maaa anfaqtum min nafaqatin aw nazartum min nazrin fa-innal laaha ya\'lamuh:(u) wa-maa liz-zaalimeena min ansaar','page_number'=>46,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>271,'arabic_text'=>'إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'In tubdus sadaqaati fani\'immaa hi(ya); wa-in tukhfoohaa wa-tu\'toohal fuqaraaa\'a fahuwa khayrul lakum, wa-yukaffiru \'ankum min saiyi-aatikum: wallaahu bimaa ta\'maloona Khabeer','page_number'=>46,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>272,'arabic_text'=>'۞ لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ','transliteration'=>'^Laisa \'alaika hudaahum wa-laakinnal laaha yahdee maien yashaaa:(\'oo) wa-maa tunfiqoo min khairin fali-anfusikum, wa-maa tunfiqoona illab tighaaa\'a wajhil laah,(i) wa-maa tunfiqoo min khairien yuwaffa ilaikum wa-antum laa tuzlamoon','page_number'=>46,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>273,'arabic_text'=>'لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ','transliteration'=>'Lil-fuqaraaa\'il lazeena uh-siroo fee sabeelil laahi laa yastatee\'oona darban fil ard(i)-yah sabuhumul jaahilu aghniyaaa\'a minat ta\'affufi ta\'rifuhum biseemaahum laa yas\'aloonan naasa ilhaafaa:(n) wa-maa tunfiqoo min khairin fa-innal laaha bihee \'Aleem','page_number'=>46,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>274,'arabic_text'=>'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Allazeena yunfiqoona amwaalahum billaili wan-nahaari sirranw wa-\'alaaniyatan falahum ajruhum \'inda Rabbihim wa-laa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>46,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>275,'arabic_text'=>'ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Allazeena ya`akuloo`nar ribaa laa yaqoomoona illaa kamaa yaqoomul lazee yatakhabba-tuhush shaitaanu minal mass,(i) zaalika bi-annahum qaalooo innamal bai\'u mislur ribaa: wa-ahallal laahul bai\'a wa-harramar ribaa, faman jaaa\'ahoo maw\'izatum mir rabbihee fantahaa falahoo maa salafa wa-amruhooo ilal laah(i); wa-man \'aada fa-ulaaa-\'ika As-haabun naar(i); hum feehaa khaalidoon','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>276,'arabic_text'=>'يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ','transliteration'=>'Yamhaqul laahur ribaa wa-yurbis sadaqaat:(i) wallaahu laa yuhibbu kulla kaffaarin aseem','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>277,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Innal lazeena aamanoo wa-amilus saalihaati wa-aqaamus salaata wa-aata-wuz zakaata lahum ajruhum \'inda rabbihim wa-laa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>278,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanut taqul laaha wa-zaroo maa baqiya minar ribaaa in kuntum mu\'mineen','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>279,'arabic_text'=>'فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ','transliteration'=>'Fa-il lam taf\'aloo faa-zanoo biharbim minal laahi wa-Rasoolih(ee); wa-in tubtum falakum ru\'oosu amwaalikum laa tazlimoona wa-laa tuzlamoon','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>280,'arabic_text'=>'وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-in kaana zoo \'usratin fa-naziratun ilaa maisarah,(tinw) wa-an tasaddaqoo khairul lakum; in kuntum ta\'lamoon','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>281,'arabic_text'=>'وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wattaqoo yawman turja\'oona feehi ilal laah(i); summa tuwaffaa kullu nafsim maa kasabat wa-hum laa yuzlamoon','page_number'=>47,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>282,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo izaa tadaayantum bidaiynin ilaa ajalim musamman faktubooh,(u) walyaktub bainakum kaatibum bil\'adl,(i) wa-laa yaaba kaatibun aien yaktuba kamaa \'allamahul laah,(u) falyaktub walyum-li-lil lazee \'alaihil haqqu walyattaqil laaha rabbah(oo) wa-laa yabkhas minhu shai\'aa,(n) fa-in kaanal lazee \'alaihil haqqu safeehan aw da\'eefan aw laa yastatee\'u aien yumilla huwa falyumlil waliyyuhoo bil\'adl,(i) wastash-hidoo shaheedaini mir rijaalikum; fa-il lam yakoonaa rajulaini farajulunw wamra-ataani mimman tardawna minash shuhadaaa\'i an tadilla ihdaahumaa fatuzakkira ihdaahumal ukhraa, wa-laa yaabash shuhadaaa\'u izaa maa du\'oo, wa-laa tas\'amooo an taktuboohu sagheeran aw kabeeran ilaaa ajalih,(i) zaalikum aqsatu \'indal laahi wa-aqwamu lish-shahaadati wa-adnaaa allaa tartaabooo; illaaa an takoona tijaaratan haadiratan tudeeroonahaa bainakum falaisa \'alaikum junaahun allaa taktuboo:(ha) wa-ash-hidooo izaa tabaaya\'tum, wa-laa yudaaarra kaatibunw wa-laa shaheed,(un) wa-in taf\'aloo fa-innahoo fusooqum bikum: wattaqul laah(a); wa-yu\'allimu-kumul laah:(u) wallaahu bikulli shai\'in \'Aleem','page_number'=>48,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>283,'arabic_text'=>'۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ','transliteration'=>'^Wa-in kuntum \'alaa safarinw wa-lam tajidoo kaatiban fari-haanum maqbooda(tun); fa-in amina ba\'dukum ba\'dan falyu\'addil lazi tumina amaa-natahoo wal-yattaqil laaha Rabbah:(u) wa-laa taktumush shahaadah,(ta) wa-maien yaktumhaa fa-innahooo aasimun qalbuh:(u) wallaahu bimaa ta\'maloona \'Aleem','page_number'=>49,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>284,'arabic_text'=>'لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Lillaahi maa fis samaawaati wa-maa fil ard:(i) wa-in tubdoo maa feee anfusikum aw tukhfoohu yuhaasibkum bihil laah(u); fayaghfiru li-maien yashaaa\'u wa-yu\'azzibu maien yashaaa:(oo) wallaahu \'alaa kulli shai-in qadeer','page_number'=>49,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>285,'arabic_text'=>'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ','transliteration'=>'Aamanar Rasoolu bimaaa unzila ilaihi mir Rabbihee walmu\'minoon,(a) kullun aamana billaahi wa-Malaaa\'ikathihee wa-Kutubhihee wa-Rusulihee laa nufarriqu baina ahadim mir Rusulih,(i) wa-qaaloo sami\'naa wa-ata\'naa; ghufraanaka Rabbanaa wa-ilaikal maseer','page_number'=>49,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>2,'ayah_number'=>286,'arabic_text'=>'لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','transliteration'=>'Laa yukalliful laahu nafsan illaa wus\'ahaa, lahaa maa kasabat wa\'alaihaa mak tasabat: Rabbanaa laa tu\'aakhiznaaa in naseenaaa aw akhta`naa, Rabbanaa wa-laa tahmil \'alainaaa isran kamaa hamaltahoo \'alal lazeena min qablinaa, Rabbanaa wa-laa tuhammilnaa maa laa taaqata lanaa bih(i); wa\'fu \'annaa waghfir lanaa warhamnaa, Anta mawlaanaa fansurnaa \'alal qawmil kaafireen','page_number'=>49,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            /* Surah 3: Family of Imran (Ali 'Imran) */
            ['surah_id'=>3,'ayah_number'=>1,'arabic_text'=>'الٓمٓ','transliteration'=>'Alif-Laam-Meeem','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>2,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ','transliteration'=>'Allaahu laaa ilaaha illaa Huwal Haiyul Qaiyoom','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>3,'arabic_text'=>'نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ','transliteration'=>'Nazzala \'alaikal Kitaaba bilhaqqi musaddiqal limaa baina yadaihi wa-anzalat Tawraata wal-Injeel','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>4,'arabic_text'=>'مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ','transliteration'=>'Min qablu hudal linnaasi wa-anzalal Furqaan:(a) innal lazeena kafaroo bi-Aayaatil laahi lahum \'azaabun shadeed:(unw) wallaahu \'azeezun zun tiqaam','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>5,'arabic_text'=>'إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ','transliteration'=>'Innal laaha laa yakhfaa \'alaihi shai\'un fil ardi wa-laa fis samaaa\'','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>6,'arabic_text'=>'هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Huwal lazee yusawwi-rukum fil arhaami kaifa yashaaa,(\'oo) laa ilaaha illaa Huwal \'Azeezul Hakeem','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>7,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Huwal lazeee anzala \'alaikal Kitaaba minhu Aayaatum Muh-kamaatun hunna Ummul Kitaabi wa-ukharu Muta-shaabihaat(un); fa-ammal lazeena fee quloobihim zaiyghun fa-yattabi\'oona ma tashaa-baha minhub tighaaa \'alfitnati wabtighaaa\'a ta`weelih:(i) wa-maa ya\'lamu ta`wee-lahooo illal laah:(u) war-raasi-khoona fil \'ilmi yaqooloona aamannaa bihee kullum min \'indi Rabbinaa: wa-maa yazzakkaru illaaa ulul albaab','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>8,'arabic_text'=>'رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ','transliteration'=>'Rabbanaa laa tuzigh quloobanaa ba\'da iz hadaitanaa wa-hab lanaa mil ladunka rahmah,(tan) innaka antal Wahhaab','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>9,'arabic_text'=>'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ','transliteration'=>'Rabbanaaa innaka jaami \'un-naasi li-Yawmil laa raiba feeh,(i) innal laaha laa yukhliful mee\'aad','page_number'=>50,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>10,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ','transliteration'=>'Innal lazeena kafaroo lan tughniya \'anhum am-waaluhum wa-laaa aw-laaduhum minal laahi shai\'a(nw); wa-ulaaa\'ika hum waqoodun Naar','page_number'=>51,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>11,'arabic_text'=>'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Kada`abi Aali Fir\'awna wallazeena min qablihim, kazzaboo bi-Aayaatinaa fa-akhaza-humul laahu bi-zunoo-bihim: wallaahu shadeedul \'iqaab','page_number'=>51,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>12,'arabic_text'=>'قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ','transliteration'=>'Qul lillazeena kafaroo satugh-laboona wa-tuh`sharoona ilaa jahannam,(a) wa-bi\'sal mihaad','page_number'=>51,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>13,'arabic_text'=>'قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ','transliteration'=>'Qad kaana lakum Aayatun fee fi\'atainil taqat(aa); fi\'atun tuqaatilu fee sabeelil laahi wa-ukhraa kaafiratuien yaraw`nahum mis`laihim ra`ayal \'ayn,(i) wallaahu yu\'ayyidu bi-nasrihee maien yashaaa\':(u) innaa fee zaalika la-\'ibratal li-ulil absaar','page_number'=>51,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>14,'arabic_text'=>'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ','transliteration'=>'Zuyyina linnaasi hubbush shahawaati minan nisaaa\'i wal-baneena wal-qanaa-teeril muqan-tarati minaz zahabi wal-fiddati wal-khailil musaw-wamati wal-an\'aami walhars:(i) zaalika mataa\'ul hayaatid dunyaa; wallaahu \'indahoo husnul ma-aab','page_number'=>51,'juz_number'=>3,'hizb_number'=>5,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>15,'arabic_text'=>'۞ قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ','transliteration'=>'^Qul a\'unabbi-\'ukum bikhairim min zaalikum, lil-lazeenat taqaw \'inda Rabbihim jannaatun tajree min tah-tihal anhaaru khaalideena feehaa wa-azwaajum mutah-haratunw wa-ridwaanum minal laah:(i) wallaahu baseerum bil\'ibaad','page_number'=>51,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>16,'arabic_text'=>'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ','transliteration'=>'Allazeena yaqooloona Rabbanaaa innanaaa aamannaa faghfir lanaa zunoobanaa wa-qinaa \'azaaban Naar','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>17,'arabic_text'=>'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ','transliteration'=>'Assaabireena wassaa-diqeena walqaaniteena walmunfiqeena walmus-taghfireena bil-as-haar','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>18,'arabic_text'=>'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Shahidal laahu annahoo laa ilaaha illaa Huwa wal-malaaa\'ikatu wa-ulul \'ilmi qaaa\'imam bilqist; laaa ilaaha illaa Huwal \'Azeezul Hakeem','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>19,'arabic_text'=>'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Innad deena \'indal laahil Islaam;(u) wamakh talafal lazeena ootul Kitaaba illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum: wa-mai yakfur bi-Aayaatil laahi fa-innal laaha saree\'ul hisaab','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>20,'arabic_text'=>'فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ','transliteration'=>'Fa-in haaaj-jooka faqul aslamtu wajhiya lillaahi wa-manit taba\'an:(i) wa-qul lillazeena ootul Kitaaba wal-ummiyyeena \'a-aslamtum, fa-in aslamoo faqadih tadaw; wa-in tawallaw fa-innamaa \'alaikal balaagh:(u) wallaahu baseerum bil-\'ibaad','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>21,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ','transliteration'=>'Innal lazeena yakfuroona bi-Aayaatil laahi wa-yaqtuloonan Nabiyyeena bighairi haqqinw wa-yaqtuloonal lazeena yaa`muroona bilqisti minan naasi fabash-shirhum bi\'azaabin aleem','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>22,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ','transliteration'=>'Ulaaa\'ikal lazeena habitat a\'maaluhum fid dunyaa wal-Aaakhirah(ti) wa-maa lahum min naasireen','page_number'=>52,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>23,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ','transliteration'=>'Alam tara ilal lazeena ootoo naseebam minal Kitaabi yud\'awna ilaa Kitaabil laahi liyah-kuma bai-nahum summa yata-wallaa fareequm minhum wa-hum mu\'ridoon','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>24,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Zaalika bi-annahum qaaloo lan tamassanan naaru illaaa ayyaamam ma\'doodaat(inw); wa-gharrahum fee deenihim maa kaanoo yaftaroon','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>25,'arabic_text'=>'فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Fa-kaifa izaa jama\'naahum li-Yawmil laa raiba fee wa-wuffiyat kullu nafsim maa kasabat wa-hum laa yuzlamoon','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>26,'arabic_text'=>'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Qulil laahumma Maalikal Mulki tu\'til mulka man tashaaa\'u wa-tanzi\'ul mulka mimman tashhaaa\'u wa-tu\'izzu man tashaaa\'u wa-tuzillu man tashaaa\'(u); biyadikal khair(u); innaka \'alaa kulli shai\'in Qadeer','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>27,'arabic_text'=>'تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ','transliteration'=>'Toolijul laila fin nahaari wa-toolijun nahaara fil lail(i); wa-tukhrijul haiya minal maiy-yiti wa-tukhrijul maiy-yita minal haiy(yi); wa-tarzuqu man tashaaa\'u bighari hisaab','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>28,'arabic_text'=>'لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ','transliteration'=>'Laa yatta-khizil mu\'minoonal kaafireena awliyaaa\'a min doonil mu\'mineen(a); wa-maien yaf\'al zaalika falaisa minal laahi fee shai\'in illaaa an tat-taqoo minhum tuqaah:(tan) wa-yuhazzi-rukumul laahu nafsah:(u) wa-ilal laahil maseer','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>29,'arabic_text'=>'قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Qul in tukhfoo maa fee sudoorikum aw tubdoohu ya\'lamhul laah:(u) wa-ya\'lamu maa fis samaawaati wa-maa fil ard:(i) wallaahu \'alaa kulli shai\'in Qadeer','page_number'=>53,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>30,'arabic_text'=>'يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ','transliteration'=>'Yawma tajidu kullu nafsim maa \'amilat min khairim muh-dara(nw) wa-maa \'amilat min sooo\'in tawaddu law anna baina-haa wa-baina-hooo amadam ba\'eedaa:(an) wa-yuhazzi-rukumul laahu nafsah:(u) wallaahu ra\'oofum bil\'ibaad','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>31,'arabic_text'=>'قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Qul in kuntum tuhib-boonal laaha fattabi\'-oonee yuh`bib-kumul laahu wa-yaghfir lakum zunoobakum: wallaahu Ghafoorur Raheem','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>32,'arabic_text'=>'قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ','transliteration'=>'Qul atee\'ul laaha war-Rasool(a); fa-in tawallaw fa-innal laaha laa yuhibbul kaafireen','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>33,'arabic_text'=>'۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'^Innal laahas tafaaa Aadama wa-Noohanw wa-Aala Ibraaheema wa-Aala Imraana \'alal \'aalameen','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>34,'arabic_text'=>'ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','transliteration'=>'Zurriyyatam ba\'duhaa mim ba\'d:(inw) wallaahu Samee\'un \'Aleem','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>35,'arabic_text'=>'إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Iz qaalat im\'ra-atu \'Imraana Rabbi innee nazartu laka maa fee batnee muhar-ra-ra(n) fataqabbal min(nee); innaka Antas Samee\'ul \'Aleem','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>36,'arabic_text'=>'فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ','transliteration'=>'Fa-lammaa wada\'at-haa qaalat Rabbi innee wada\'tuhaaa unsaa wallaahu a\'lamu bimaa wada\'at wa-laisaz zakaru kalunsaa; wa-innee sammai-tuhaa Maryama wa-innee u\'eezuhaa bika wa-zurriy-yatahaa minash Shaitaanir Rajeem','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>37,'arabic_text'=>'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ','transliteration'=>'Fata-qabba-lahaa Rabbuhaa biqaboolin hasaninw wa-ambatahaa nabaatan hasananw wa-kaffalahaa Zakariyyaa; kullamaa dakhala \'alaihaa Zakariyyal Mihraaba wajada \'indahaa rizqa(n); qaala yaa-Maryamu annaa laki haazaa; qaalat huwa min \'indil laah(i); innal laaha yarzuqu maien yashaaa\'u bighairi hisaab','page_number'=>54,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>38,'arabic_text'=>'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ','transliteration'=>'Hunaaa-lika da\'aa Zakariyyaa Rabbah(oo); qaala Rabbi hab lee mil ladunka zurriyyatan taiyiba(tan); innaka samee\'ud du\'aaa\'','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>39,'arabic_text'=>'فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ','transliteration'=>'Fanaadat-hul malaaa\'ikatu wa-huwa qaaa\'ee-muien yusallee fil Mihraabi annal laaha yubash-shiruka bi-Yahyaa musaddiqam bi-Kalimatim minal laah(i) wa-saiyidanw wa-hasooranw wa-Nabiyyam minas saaliheen','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>40,'arabic_text'=>'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ','transliteration'=>'Qaala Rabbi annaa yakoonu lee ghulaamunw wa-qad bala-gha-niyal kibaru wam-raatee \'aaqir(un); qaala kazaa-likal laahu yaf\'alu maa yashaaa\'','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>41,'arabic_text'=>'قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ','transliteration'=>'Qaala Rabbij \'al leee Aayah(tan); qaala Aaayatuka allaa tukalliman naasa salaasata ayyaamin illa ramzaa:(an) wazkur Rabbaka kaseeranw wa-sabbih bil\'ashiyyi wal-ib-kaar','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>42,'arabic_text'=>'وَإِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-iz qaa-latil malaaa\'ikatu yaa-Maryamu innal laahas tafaaki wa-tah-haraki wastafaaki \'alaa nisaaa\'il \'aalameen','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>43,'arabic_text'=>'يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ','transliteration'=>'Yaa-Maryamu uq-nutee li-Rabbiki wasjudee warka\'ee ma\'ar raaki\'een','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>44,'arabic_text'=>'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ','transliteration'=>'Zaalika min ambaaa\'il ghaibi noo-heehi ilaik,(a) wa-maa kunta ladai`him iz yulqoona aq`laamahum ayyuhum yak-fulu Maryama wa-maa kunta ladai-him iz yakh-tasimoon','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>45,'arabic_text'=>'إِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ','transliteration'=>'Iz qaa-latil malaaa\'ikatu yaa-Maryamu innal laaha yubash-shiruki bi-Kalimatim minhus muhul Maseehu \'Eesab nu Maryama wajeehan fid dunyaa wal-Aakhirati wa-minal muqar-rabeen','page_number'=>55,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>46,'arabic_text'=>'وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-yukallimun naasa fil mahdi wa-kahlanw wa-minas saaliheen','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>47,'arabic_text'=>'قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Qaalat Rabbi annaa yakoonu lee waladunw wa-lam yamsa-snee bashar(un); qaala kazaa-likil laahu yakhluqu maa yashaaa\',(oo) izaa qadaaa amran fa-innamaa yaqoolu lahoo kun fayakoon','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>48,'arabic_text'=>'وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ','transliteration'=>'Wa-yu\'allimuhul Kitaaba wal-Hikmata wat-Tawraata wal-Injeel','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>49,'arabic_text'=>'وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-Rasoolan ilaa Baneee Israaa\'eela annee qad ji\'tukum bi-Aayatim mir Rabbikum; annee akhluqu lakum minat teeni kahai\'atit tairi fa-anfukhu feehi fayakoonu tairam bi-iznil laah(i); wa-ubri\'ul akmaha wal-abrasa wa-uhyil mawtaa bi-iznil laah(i); wa-unabbi\'ukum bimaa taa`kuloona wa-maa tadda-khiroona fee buyootikum, inna fee zaalika la-Aayatal lakum in kuntum mu\'mineen','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>50,'arabic_text'=>'وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ','transliteration'=>'Wa-musaddiqal limaa baina yadaiy-yaa minat Tawraati wa-li-uhilla lakum ba\'dal lazee hurrima \'alaikum, wa-ji\'tukum bi-Aayatim mir Rabbikum fattaqul laaha wa-atee\'oon','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>51,'arabic_text'=>'إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ','transliteration'=>'Innal laaha Rabbee wa-Rabbukum fa\'budooh:(u) haazaa Siraatum Mustaqeem','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>52,'arabic_text'=>'۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ','transliteration'=>'^Fa-lammaaa ahassa \'Eesaa min-humul kufra qaala man ansaaree ilal laah(i); qaalal Hawaariy-yoona nahnu ansaarul laahi aamannaa billaahi wash-had bi-annaa muslimoon','page_number'=>56,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>53,'arabic_text'=>'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ','transliteration'=>'Rabbanaaa aamannaa bimaaa anzalta wattaba\'nar Rasoola faktubnaa ma\'ash shaahideen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>54,'arabic_text'=>'وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ','transliteration'=>'Wa-makaroo wa-makaral laah(u); wallaahu khairul maakireen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>55,'arabic_text'=>'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','transliteration'=>'Iz qaalal laahu yaa-\'Eesaaa innee mutawaffeeka wa-raafi\'uka ilaiya wa-mutah-hiruka minal lazeena kafaroo wa-jaa\'ilul lazeenat taba-ooka fawqal lazeena kafarooo ilaa Yawmil Qiyaama(ti); summa ilaiya marji\'ukum fa-ahkumu bainakum feemaa kuntum feehi takh-taliifoon','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>56,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ','transliteration'=>'Fa-ammal lazeena kafaroo fa-u\'az-zibuhum \'azaaban shadeedan fid dunyaa wal-Aakhira(ti) wa-maa lahum min naasireen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>57,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-ammal lazeena aamanoo wa-\'amilus saalihaati fa-yuwaf-feehim ujoorahum: wallaahu laa yuhibbuz zaalimeen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>58,'arabic_text'=>'ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ','transliteration'=>'Zaalika natloohu \'alaika minal Aayaati wa-Zikril Hakeem','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>59,'arabic_text'=>'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Inna masala \'Eesaa \'indal laahi kamasali Aadam(a); khala-qahoo min turaabin summa qaala lahoo kun fayakoon','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>60,'arabic_text'=>'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ','transliteration'=>'Alhaqqu mir Rabbika falaa takum minal mumtareen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>61,'arabic_text'=>'فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ','transliteration'=>'Faman haaaj-jaka feehi mim ba\'di maa jaaa\'aka minal \'ilmi faqul ta\'aalaw nad\'u abnaaa\'anaa wa-abnaaa\'akum wa-nisaaa\'anaa wa-nisaaa\'akum wa-anfusanaa wa-anfusakum summa nabtahil fanaj\'al la\'natal laahi \'alal kaazibeen','page_number'=>57,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>62,'arabic_text'=>'إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Innaa haazaa lahuwal qasasul haqq,(u) wa-maa min ilaahin illal laah,(u) wa-innal laahaa la-Huwal \'Azeezul Hakeem','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>63,'arabic_text'=>'فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ','transliteration'=>'Fa-in tawallau fa-innal laaha \'aleemun bil-mufsideen','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>64,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ','transliteration'=>'Qul yaa-Ahlal Kitaabi ta\'aalau ilaa Kalimatin sawaaa\'im bainanaa wa-bainakum allaa na\'buda illal laaha wa-laa nushrika bihee shai\'anw wa-laa yat-takhiza ba\'dunaa ba\'dan arbaabam min doonil laah,(i) fa-in tawallau faqoo-lush hadoo bi-annaa muslimoon','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>65,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Yaaa-Ahlal Kitaabi limaa tuhaaaj-joona feee Ibraaheema wa-maaa unzilatit Tawraatu wal-Injeelu illaa mim ba\'dih,(ee) afala ta\'qiloon','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>66,'arabic_text'=>'هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Haaa-antum haaa\'ulaaa\'i haa-jajtum feemaa lakum bihee \'ilmun falima tuhaaaj-joonaa feemaa laisa lakum bihee \'ilm,(un) wal-laahu ya\'lamu wa-antum laa ta\'lamoon','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>67,'arabic_text'=>'مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Maa kaana Ibraaheemu Yahoodiy-yanw wa-laa Nasraa-niyyanw wa-laakin kaana Haneefam Muslima(nw) wa-maa kaana minal mushrikeen','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>68,'arabic_text'=>'إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Innaa awlan naasi bi-Ibraaheema lallazeenat taba-\'oohu wa-haazan nabiyyu wallazeena aamanoo: wallaahu waliyyul mu\'mineen','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>69,'arabic_text'=>'وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ','transliteration'=>'Waddat taaa\'ifatum min Ahlil Kitaabi lau yudil-loonakum wa-maa yudilloona illaaa anfusa-hum wa-maa yash\'uroon','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>70,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ','transliteration'=>'Yaaa-Ahlal Kitaabi lima takfuroona bi-Aayaatil laahi wan-antum tashadoon','page_number'=>58,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>71,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ','transliteration'=>'Yaaa-Ahalal Kitaabi lima talbisoonal haqqa bilbaatili wa-taktumoonal haqqa wa-antum ta\'lamoon','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>72,'arabic_text'=>'وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-qaalat taaa\'ifatum min Ahlil Kitaabi aaminoo billazeee unzila \'alal lazeena aamanoo waj-han nahaari wak-furooo aakhirahoo la\'alla-hum yarji\'oon','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>73,'arabic_text'=>'وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ','transliteration'=>'Wa-laa tu\'minooo illaa liman tabi\'a deenakum qul innal hudaa hudal laahi aien yu\'taaa ahadum misla maaa ooteetum auw yuhaaaj-jookum \'inda Rabbikum: qul innal fadla biyadil laahi yu`teehi maien yashaaa\':(u) wal-laahu Waasi\'un \'Aleem','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>74,'arabic_text'=>'يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Yakhtassu birahmatihee maien yashaaa\':(u) wal-laahu zul fadlil \'azeem','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>75,'arabic_text'=>'۞ وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'^Wa-min Ahlil Kitaabi man in taa`manhu biqintaarien yu\'addihee ilaika wa-minhum man in taamanhu bideenaaril laa yu\'addiheee ilaika illaa maa dumta \'alaihi qaaa\'ima:(n) zaalika bi-annahum qaaloo laisa \'alainaa fil ummiyyeena sabeel(unw) Wa-yaqooloona \'alal laahil kaziba wa-hum ya\'lamoon','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>76,'arabic_text'=>'بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ','transliteration'=>'Balaa man awfaa bi\'ahdihee wattaqaa fa-innal laaha yuhibbul muttaqeen','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>77,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Innal lazeena yashtaroona bi\'ahdil laahi wa-aymaanihim samanan qaleelan ulaaa\'ika laa khalaaqa lahum fil Aakhirati wa-laa yukallimu-humul laahu wa-laa yanzuru ilaihim Yawmal Qiyaamati wa-laa yuzakkeehim wa-lahum \'azabun \'aleem','page_number'=>59,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>78,'arabic_text'=>'وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'Wa-inna minhum lafaree qaien yalwoona alsinatahum bil Kitaabi litah-saboohu minal Kitaab, Wa-maa huwa minal Kitaabi Wa-yaqooloona huwa min \'indillaahi Wa-maa huwa min \'indillaah(i) Wa-yaqooloona \'alal laahil kaziba Wa-hum ya\'lamoon','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>79,'arabic_text'=>'مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ','transliteration'=>'Maa kaana li-basharin aien yu\'tiyahul laahul Kitaaba walhukma wan-Nubuwwata summa yaqoola linnaasi koonoo \'ibaadal lee min doonil laahi Wa-laakin koonoo rabbaaniyeena bimaa kuntum tu\'allimoonal Kitaaba Wa-bimaa kuntum tadrusoon','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>80,'arabic_text'=>'وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ','transliteration'=>'Wa-laa ya`murakum an tat-takhizul malaaa-\'ikata wan-Nabiyyeena arbaaba:(n) a`yaamurukum bilkufri ba\'da iz antum muslimoon','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>81,'arabic_text'=>'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ','transliteration'=>'Wa-iz akhazal laahu meesaaqan Nabiyyeena lamaaa aataitukum min Kitaabinw Wa-Hikmatin summa jaaa\'akum Rasoolum musaddiqul limaa ma\'akum latu\'minunna bihee Wala-tan-surunnah,(u) qaala \'aaqrartum Wa-akhaztum alaa zaalikum isree; qaalooo aqrarnaa, qaala fashhadoo Wa-ana ma\'akum minash shaahideen','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>82,'arabic_text'=>'فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Faman tawallaa ba\'da zaalika fa-ulaaa\'ika humul faasiqoon','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>83,'arabic_text'=>'أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ','transliteration'=>'Afaghaira deenil laahi yab-ghoona Wa-lahooo aslama man fis samaawaati wal-ardi taw\'anw Wa-karhanw Wa-ilaihi yurja\'oon','page_number'=>60,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>84,'arabic_text'=>'قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ','transliteration'=>'Qul aamannaa billaahi Wa-maaa unzila \'alainaa Wa-maaa unzila \'alaaa Ibraaheema Wa-Ismaa\'eela Wa-Iss-haaqa Wa-Ya\'qooba wal-Asbaati Wa-maaa ootiya Moosaa Wa-\'Eesaa wan-Nabiyyoona mir Rabbihim laa nufarriqu baina ahadim minhum Wa-nahnu lahoo muslimoon','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>85,'arabic_text'=>'وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Wa-maien yabtaghi ghairal Islaami deenan falaien yuqbala minhu Wa-huwa fil Aakhirati minal khaasireen','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>86,'arabic_text'=>'كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Kaifa yahdil laahu qawman kafaroo ba\'da eemaanihim Wa-shahidooo annar Rasoola haqqunw Wa-jaaa\'ahumul baiyinaat,(u) wal-laahu laa yahdil qawmaz zaalimeen','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>87,'arabic_text'=>'أُوْلَٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ','transliteration'=>'Ulaaa\'ika jazaaa\'uhum anna \'alaihim la\'natal laahi walmalaaa\'ikati wannaasi ajma\'een','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>88,'arabic_text'=>'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ','transliteration'=>'Khaalideena feehaa laa yukhaffafu \'anhumul \'azaabu Wa-laa hum yunzaroon','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>89,'arabic_text'=>'إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Illal lazeena taaboo mim ba\'di zaalika Wa-aslahoo fa-innal laaha Ghafoorur Raheem','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>90,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ','transliteration'=>'Innal lazeena kafaroo ba\'da eemaanihim summaz daadoo kufral lan tuqbala tawbatuhum Wa-ulaaa\'ika humud daaalloon','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>91,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّٰصِرِينَ','transliteration'=>'Innal lazeena kafaroo Wa-maatoo Wa-hum kuffaarun falaien yuqbala min ahadihim mil\'ul ardi zahabanw Wa-la-wif tadaa bih:(ee) ulaaa\'ika lahum \'azaabun aleemunw Wa-maa lahum min naasireen','page_number'=>61,'juz_number'=>3,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>92,'arabic_text'=>'لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ','transliteration'=>'Lan tanaalul birra hattaa tunfiqoo mimmaa tuhibboon,(a) Wa-maa tunfiqoo min shai\'in fa-innal laaha bihee \'Aleem','page_number'=>62,'juz_number'=>4,'hizb_number'=>6,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>93,'arabic_text'=>'۞ كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'^Kullut ta\'aami kaana hillal li-Baneee Israaa\'eela illaa maa harrama Israaa\'eelu \'alaa nafsihee min qabli an tunazzalat Tawraah:(tu) qul faa`too bit-Tawraati fatloohaaa in kuntum saadiqeen','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>94,'arabic_text'=>'فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Famanif taraa \'alal laahil kaziba mim ba\'di zaalika fa-ulaaa\'ika humuz zaalimoon','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>95,'arabic_text'=>'قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Qul sadaqal laah:(u) fattabi\'oo Millata Ibraaheema Haneefanw Wa-maa kaana minal mush-rikeen','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>96,'arabic_text'=>'إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ','transliteration'=>'Inna awwala Baitinw wudi\'a linnaasi lallazee bi-Bakkata mubaarakanw Wa-hudal lil-\'aalameen','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>97,'arabic_text'=>'فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ','transliteration'=>'Feehi Aayaatum baiyinaatum Maqaamu Ibraaheem(a); Wa-man dakha-lahoo kaana aamina:(n) Wa-lillaahi \'alan naasi Hijjul Baiti manis tataa\'a ilaihi sabeela,(n) Wa-man kafara fa-innal laaha ghaniyyun \'anil \'aalameen','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>98,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ','transliteration'=>'Qul yaaa-Ahlal Kitaabi lima takfuroona bi-Aayaatil laahi wallaahu shaheedun \'alaa maa ta\'maloon','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>99,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجٗا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Qul yaaa-Ahlal Kitaabi lima tasuddoona \'an sabeelil laahi man aamana tab-ghoo-nahaa \'iwajanw Wa-antum shuhadaaa\':(u) Wa-mal laahu bighaafilin \'ammaa ta\'maloon','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>100,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo in tutee\'oo fareeqam minal lazeena ootul Kitaaba yaruddookum ba\'da eemaanikum kaafireen','page_number'=>62,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>101,'arabic_text'=>'وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-kaifa takfuroona Wa-antum tutlaa \'alaikum Aayaatul laahi Wa-feekum Rasooluh:(u) Wa-maien ya\'tasim bil-laahi faqad hudiya ilaa Siraatim Mustaqeem','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>102,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanut taqul laaha haqqa tuqaatihee Wa-laa tamootunna illaa Wa-antum muslimoon','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>103,'arabic_text'=>'وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Wa\'tasimoo bi-Hablil laahi jamee\'anw Wa-laa tafarraqoo, wazkuroo ni\'matal laahi alaikum iz kuntum a\'daaa\'an fa-allafa baina quloobikum fa-asbah-tum bini\'matiheee ikhwaana(nw) Wa-kuntum \'alaa shafaa hufratim minan Naari fa-anqazakum minh:(a) kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum tahtadoon','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>104,'arabic_text'=>'وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Waltakum minkum ummatuien yad\'oona ilal khairi Wa-ya\'muroona bil-ma\'roofi Wa-yan-hawna \'anil munkar,(i) Wa-ulaaa\'ika humul muflihoon','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>105,'arabic_text'=>'وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Wa-laa takoonoo kallazeena tafarraqoo wakhtalafoo mim ba\'di maa jaaa\'ahumul baiyinaat,(u) Wa-ulaaa\'ika lahum \'azaabun \'azeem','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>106,'arabic_text'=>'يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ','transliteration'=>'Yawma tabi-yaddu wujoohunw Wa-taswaddu wujooh,(un) fa-ammal lazeenas waddat wujoo-hum akafartum ba\'da eemaanikum fazooqul \'azaaba bimaa kuntum takfuroon','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>107,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wa-ammal lazeena bi-yaddat wujoohuhum fafee rahmatil laahi hum feehaa khaalidoon','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>108,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ','transliteration'=>'Tilka Aayaatul laahi natloohaa \'alaika bilhaqq:(i) Wa-mal laahu yureedu zulmal lil\'aalameen','page_number'=>63,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>109,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Wa-lillaahi maa fis samaawaati Wa-maa fil ard:(i) Wa-ilal laahi turja\'ul umoor','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>110,'arabic_text'=>'كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Kuntum khaira ummatin ukhrijat linnaasi ta\'muroona bilma\'roofi Wa-tanhawna \'anil munkari Wa-tu\'minoona billaah:(i) Wa-law aamana Ahlul Kitaabi lakaana khairal lahum, minhumul mu\'minoona Wa-aksaru-humul faasiqoon','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>111,'arabic_text'=>'لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ','transliteration'=>'Laien yadurrookum \'illaaa aza(nw); Wa-ien yuqaa-tilookum yuwal-lookumul adbaara summa laa yunsaroon','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>112,'arabic_text'=>'ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ','transliteration'=>'Duribat \'alaihimuz zillatu aina maa suqifooo illaa bihablim minal laahi Wa-hablim minan naasi Wa-baaa\'oo bighadabim minal laahi Wa-duribat \'alaihimul maskanah,(tu) zaalika bi-annahum kaanoo yakfuroona bi-Aayaatil laahi Wa-yaqtuloonal Ambiyaaa\'a bighairi haqq,(in) zaalika bimaa \'asaw Wa-kaanoo ya\'tadoon','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>113,'arabic_text'=>'۞ لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ','transliteration'=>'^Laisoo sawaaa\'a:(n) min Ahlil Kitaabi ummatun qaaa\'ima-tuien yatloona Aayaatil laahi aanaaa\'al laili Wa-hum yasjudoon','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>114,'arabic_text'=>'يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Yu\'minoona billaahi wal-Yawmil Aakhiri Wa-ya\'muroona bilma\'roofi Wa-yanhawna \'anil munkari Wa-yusaari\'oona fil khairaat(i) Wa-ulaaa\'ika minas saaliheen','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>115,'arabic_text'=>'وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ','transliteration'=>'Wa-maa yaf\'aloo min khairin falaien yukfarooh:(u) wal-laahu \'aleemun bil-muttaqeen','page_number'=>64,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>116,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Innal lazeena kafaroo lan tughniya \'anhum amwaaluhum Wa-laaa awlaaduhum minal laahi shai\'a(nw); Wa-ulaaa\'ika As-haabun Naar,(i) hum feehaa khaalidoon','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>117,'arabic_text'=>'مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Masalu maa yunfiqoona fee haazihil hayaatid dunyaa kamasali reehin feehaa sirrun asaabat harsa qawmin zalamooo anfusahum fa-ahlakath,(hu) Wa-maa zalamahumul laahu Wa-laakin anfusahum yazlimoon','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>118,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo laa tat-takhizoo bitaa-natam min doonikum laa ya\'loonakum khabaala(nw) waddoo maa \'anittum qad badatil baghdaaa\'u min afwaahihim; Wa-maa tukhfee sudooruhum akbar,(u) qad baiyannaa lakumul Aayaat(i); in kuntum ta\'qiloon','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>119,'arabic_text'=>'هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Haaa-antum ulaaa\'i tuhib-boonahum Wa-laa yuhib-boonakum Wa-tu\'minoona bil-kitaabi kullihee Wa-izaa laqookum qaalooo aamannaa Wa-izaa khalaw \'addoo \'alaikumul anaa-mila minal ghaiz,(i) qul mootoo bighai-zikum: innal laaha \'aleemum bizaatis sudoor','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>120,'arabic_text'=>'إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ','transliteration'=>'In tamsaskum hasanatun tasu\'hum Wa-in tusibkum saiyyi\'a-tuien yafrahoo bih(aa); Wa-in tasbiroo Wa-tattaqoo laa yadurrukum kaiduhum shai\'a:(n) innal laaha bimaa ya\'maloona muheet','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>121,'arabic_text'=>'وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','transliteration'=>'Wa-iz ghadawta min ahlika tubawwi\'ul mu\'mineena maqaa\'ida lilqitaal:(i) wal-laahu samee\'un \'aleem','page_number'=>65,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>122,'arabic_text'=>'إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Iz hammat taaa\'ifataani minkum an taf-shalaa wal-laahu waliyyuhum:(a) Wa-\'alal laahi fal-yatawak-kalil mu\'minoon','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>123,'arabic_text'=>'وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wa-laqad nasarakumul laahu bi-Badrinw Wa-antum azilla(tun); fattaqul laaha la\'allakum tashkuroon','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>124,'arabic_text'=>'إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُنزَلِينَ','transliteration'=>'Iz taqoolu lil-mu\'mineena alaien yakfiyakum aien yumiddakum Rabbukum bi-salaa-sati aalaafim minal malaaa\'ikati munzaleen','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>125,'arabic_text'=>'بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ','transliteration'=>'Balaaa, in tasbiroo Wa-tattaqoo Wa-ya\'tookum min fawrihim haazaa yumdidkum Rabbukum bi-khamsati aalaafim minal malaaa\'ikati musawwimeen','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>126,'arabic_text'=>'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','transliteration'=>'Wa-maa ja\'alahul laahu illaa bushraa lakum Wa-litatma\'inna quloobukum bih:(i) Wa-man nasru illaa min \'indil laahil \'Azeezil Hakeem','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>127,'arabic_text'=>'لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ','transliteration'=>'Liyaqta\'a tarafam minal lazeena kafarooo auw yakbitahum fayan-qaliboo khaaa\'ibeen','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>128,'arabic_text'=>'لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ','transliteration'=>'Laisa laka minal amri shai\'un auw yatooba \'alaihim auw yu\'az-zi-bahum fa-innahum zaalimoon','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>129,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-lilaahi maa fis samaawaati Wa-maa fil ard,(i) yaghfiru limaien yashaaa\'u Wa-yu\'azzibu maien yashaaa\',(u) wallaahu Ghafoorur Raheem','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>130,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo la takulu ribaaa ad\'aafam mudaa\'afa(tanw); wattaqul laaha la\'allakum tuflihoon','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>131,'arabic_text'=>'وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ','transliteration'=>'Wattaqun Naaral lateee u\'iddat lilkaafireen','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>132,'arabic_text'=>'وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Wa-atee\'ul laaha war-Rasoola la\'allakum turhamoon','page_number'=>66,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>133,'arabic_text'=>'۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ','transliteration'=>'^Wa-saari\'ooo ilaa maghfiratim mir Rabbikum Wa-Jannatin ar-duhas samaawaatu wal-ardu u\'iddat lilmuttaqeen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>134,'arabic_text'=>'ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ','transliteration'=>'Allazeena yunfiqoona fis sarraaa\'i wad-darraaa\'i wal-kaazimeenal ghaiza wal-aafeena \'anin naas:(i) wal-laahu yuhibbul muhsineen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>135,'arabic_text'=>'وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'Wal-lazeena izaa fa\'aloo faa-hishatan aw zalamooo anfusahum zakarul laaha fastagh-faroo li-zunoobihim; Wa-maien yaghfiruz zunooba illal laahu Wa-lam yusirroo \'alaa maa fa\'aloo Wa-hum ya\'lamoon','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>136,'arabic_text'=>'أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ','transliteration'=>'Ulaaa\'ika jazaaa\'uhum maghfiratum mir Rabbihim Wa-Jannaatun tajree min tah-tihal anhaaru khaalideena feeha, Wa-ni\'ma ajrul \'aamileen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>137,'arabic_text'=>'قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ','transliteration'=>'Qad khalat min qablikum sunann faseeroo fil ardi fanzuroo kaifa kaana \'aaqiba-tul mukazzibeen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>138,'arabic_text'=>'هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ','transliteration'=>'Haazaa bayaanul linnaasi Wa-hudanw Wa-maw\'izatul lil-muttaqeen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>139,'arabic_text'=>'وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-laa tahinoo Wa-laa tahzanoo Wa-antumul a\'lawna in kuntum mu\'mineen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>140,'arabic_text'=>'إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ','transliteration'=>'Iien yamsaskum qarhum faqad massal qawma qarhum misluh,(u) Wa-tilkal ayyaamu nudaa-wiluhaa bainan naasi Wa-liya\'lamal laahul lazeena aamanoo Wa-yattakhiza minkum shuhadaaa:(\'a) wal-laahu laa yuh-ibbuz zaalimeen','page_number'=>67,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>141,'arabic_text'=>'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-liyumah-hisal laahul lazeena aamanoo Wa-yamhaqal kaafireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>142,'arabic_text'=>'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ','transliteration'=>'Am hasibtum an tadkhulul Jannnata Wa-lammaa ya\'lamil laahul lazeena jaahadoo minkum Wa-ya\'lamas saabireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>143,'arabic_text'=>'وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ','transliteration'=>'Wa-laqad kuntum tamann-nawnal mawta min qabli an tal-qawhu faqad ra-aitu-moohu Wa-antum tanzuroon','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>144,'arabic_text'=>'وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ','transliteration'=>'Wa-maa Muhammadun illaa Rasoolun qad khalat min qablihir Rusul,(u) afa\'im maata auw qutilan qalabtum \'alaaa a\'qaabikum, Wa-maien yanqalib \'alaa aqibaihi falaien yadurral laaha shai\'a:(n) Wa-sayajzil laahush shaakireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>145,'arabic_text'=>'وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ','transliteration'=>'Wa-maa kaana linafsin an tamoota illaa bi-iznil laahi kitaabam mu\'ajjala:(n) Wa-maien yurid sawaabad dunyaa nu\'tihee minhaa Wa-maien yurid sawaabal Aakhirati nu\'tihee minhaa, Wa-sanaj-zish shaakireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>146,'arabic_text'=>'وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ','transliteration'=>'Wa-ka-aiyim min Nabiyyin qaatala ma\'ahoo ribbiy-yoona kaseerun famaa wahanoo limaaa Asaabahum fee sabeelil laahi Wa-maa da\'ufoo Wa-mas takaanoo: wallaahu yuhibbus saabireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>147,'arabic_text'=>'وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-maa kaana qawlahum illaa an qaaloo Rabbanagh fir lanaa zunoobanaa Wa-israafanaa feee amrinaa Wa-sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>148,'arabic_text'=>'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ','transliteration'=>'Fa-aataahumul laahu sawaabad dunyaa Wa-husna sawaabil Aakhirah:(ti) wal-laahu yuhibbul muhsineen','page_number'=>68,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>149,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ','transliteration'=>'Yaaa-\'aiyuhal lazeena aamanoo in tutee\'ul lazeena kafaroo yarud-dookum \'alaaa a\'qaabikum fatan-qaliboo khaasireen','page_number'=>69,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>150,'arabic_text'=>'بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّٰصِرِينَ','transliteration'=>'Balil laahu maw-laakum; Wa-Huwa khairun naasireen','page_number'=>69,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>151,'arabic_text'=>'سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّٰلِمِينَ','transliteration'=>'Sanulqee fee quloobil lazeena kafarur ru\'ba bimaaa ashrakoo bil-laahi maa lam yunazzil bihee sultaana(nw); Wa-ma`wa-humun Naar,(u) Wa-bi\'sa maswaz zaalimeen','page_number'=>69,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>152,'arabic_text'=>'وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-laqad sadaqakumul laahu wa\'dahooo iz tahussoo-nahum bi-iznih(ee); hattaaa izaa fashiltum Wa-tanaaza\'tum fil amri Wa-\'asaitum mim ba\'di maaa araakum maa tuhibboon,(a) minkum maien yureedud dunyaa Wa-minkum maien yureedul Aakhira(h),(ta) summa sarafakum \'anhum liyab-taliyakum; Wa-laqad \'afaa \'ankum: wal-laahu zoo fadlin \'alal mu\'mineen','page_number'=>69,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>153,'arabic_text'=>'۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'^Iz tus\'idoona Wa-laa talwoona \'alaaa ahadinw war-Rasoolu yad\'ookum feee ukhraakum fa-asaabakum ghammam bighammil likailaa tahzanoo \'alaa maa faatakum Wa-laa maaa asaabakum: wal-laahu khabeerum bimaa ta\'maloon','page_number'=>69,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>154,'arabic_text'=>'ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Summa anzala \'alaikum mim ba\'dil ghammi amanatan nu\'aasai yaghshaa taaa\'-ifatam minkum; Wa-taaa\'ifatun qad ahammat-hum an-fusuhum yazun-noona bil-laahi ghairal haqqi zannal jaahiliyya(ti); yaqooloona hal lanaa minal amri min shai\':(in) qul innal amra kullahoo lillaah:(i) yukhfoona fee anfusihim maa laa yubdoona lak(a); yaqooloona law kaana lanaa minal amri shai\'um maa qutilnaa haahun:(a) qul law kuntum fee buyootikum laba-razal lazeena kutiba \'alaihimul qatlu ilaa madaa-ji\'ihim; Wa-liyab-taliyal laahu maa fee sudoorikum Wa-liyumah-hisa maa fee quloobikum: wallaahu \'aleemum bizaatis sudoor','page_number'=>70,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>155,'arabic_text'=>'إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ','transliteration'=>'Innal lazeena tawallaw minkum yawmal taqal jam\'aani innamas tazal-lahumush Shaitaanu biba\'di maa kasaboo; Wa-laqad \'afal laahu \'anhum: innnal laaha Ghafoorun Haleem','page_number'=>70,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>156,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Yaaa-ayyuhul lazeena aamanoo laa takoonoo kallazeena kafaroo Wa-qaaloo li-ikhwaanihim izaa daraboo fil ardi auw kaanoo ghuzzal law kaanoo \'indanaa maa maatoo Wa-maa qutiloo liyaj\'alal laahu zaalika hasratan fee quloobihim: wal-laahu yuhyee Wa-yumeet:(u) wallaahu bimaa ta\'maloona Baseer','page_number'=>70,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>157,'arabic_text'=>'وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ','transliteration'=>'Wa-la\'in qutiltum fee sabeelil laahi auw muttum la-maghfiratum minal laahi Wa-rahmatun khairum mimmaa yajma\'oon','page_number'=>70,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>158,'arabic_text'=>'وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ','transliteration'=>'Wa-la\'im muttum \'auw qutiltum la-ilal lahi tuhsharoon','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>159,'arabic_text'=>'فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ','transliteration'=>'Fabimaa rahmatim minal laahi linta lahum; Wa-law kunta fazzan ghaleezal qalbi lan-faddoo min hawlik(a); fa\'afu \'anhum wastaghfir lahum Wa-shaawir-hum fil amr(i); fa-izaa \'azamta fatawakkal \'alal laah,(i) innal laaha yuhibbul mutawak-kileen','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>160,'arabic_text'=>'إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Iien yansur-kumul laahu falaa ghaaliba lakum; Wa-ien yakh-zulkum faman zal lazee yan-surukum min ba\'dih:(i) Wa-\'alal laahi fal-yatawak-kalil mu\'minoon','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>161,'arabic_text'=>'وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-maa kaana li-Nabiyyin aien yaghull,(a) Wa-maien yaghlul ya\'ti bimaa ghalla Yawmal Qiyaamah,(ti) summa tuwaffaa kullu nafsim maa kasabat Wa-hum laa yuz-lamoon','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>162,'arabic_text'=>'أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Afamanit taba\'a Ridwaanal laahi kamam baaa\'a bi-sakha-tim minal laahi Wa-ma\'waahu Jahannam,(u) Wa-bi\'sal maseer','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>163,'arabic_text'=>'هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ','transliteration'=>'Hum darajaatun \'indal laah:(i) wallaahu baseerum bimaa ya\'maloon','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>164,'arabic_text'=>'لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ','transliteration'=>'Laqad mannal laahu \'alal mu\'mineena iz ba\'asa feehim Rasoolam min an-fusihim yatloo \'alaihim Aayaa-tihee Wa-yuzak-keehim Wa-yu\'allimu-humul Kitaaba wal-Hikma(ta) Wa-in kaanoo min qablu lafee dalaalim mubeen','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>165,'arabic_text'=>'أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Awa-lammaaa asaa-batkum museebatun qad asabtum mislaihaa qultum annaa haazaa; qul huwa min \'indi anfusikum: innal laaha \'alaa kulli shai\'in Qadeer','page_number'=>71,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>166,'arabic_text'=>'وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-maa asaabakum yawmal taqal jam\'aani fabi-iznil laahi Wa-liya\'lamal mu\'mineen','page_number'=>72,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>167,'arabic_text'=>'وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ','transliteration'=>'Wa-liya\'lamal lazeena naafaqoo, Wa-qeela lahum ta\'aalaw qaatiloo fee sabeelil laahi awid fa\'oo; qaaloo law na\'lamu qitaalal-lat taba\'naakum: hum lilkufri yawma\'izin aqrabu minhum lil-eemaan,(i) yaqooloona bi-afwaahi-him maa laisa fee quloobihim; wal-laahu a\'lamu bimaa yaktumoon','page_number'=>72,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>168,'arabic_text'=>'ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Allazeena qaaloo li-ikhwaanihim Wa-qa\'adoo law ataa\'oonaa maa qutiloo: qul fadra\'oo an anfusi-kumul mawta in kuntum saadiqeen','page_number'=>72,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>169,'arabic_text'=>'وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ','transliteration'=>'Wa-laa tahsabannal lazeena qutiloo fee sabeelil laahi amwaata,(m) bal ahyaaa\'un \'inda Rabbihim yurzaqoon','page_number'=>72,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>170,'arabic_text'=>'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Fari-heena bimaaa aataa-humul laahu min fadlihee Wa-yas-tabshiroona billazeena lam yalhaqoo bihim min khalfihim allaa khawfun \'alaihim Wa-laa hum yahzanoon','page_number'=>72,'juz_number'=>4,'hizb_number'=>7,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>171,'arabic_text'=>'۞ يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'^Yastabshiroona bini\'matim minal laahi Wa-fad-linw Wa-annal laaha laa yudee\'u ajral mu\'mineen','page_number'=>72,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>172,'arabic_text'=>'ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ','transliteration'=>'Al-lazeenas tajaaboo lil-laahi war-Rasooli mim ba\'di maaa asaa-bahumul qarh,(u) lil-lazeena ah-sanoo minhum wattaqaw ajrun \'azeem','page_number'=>72,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>173,'arabic_text'=>'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ','transliteration'=>'Allazeena qaala lahumun naasu innan naasa qad jama\'oo lakum fakh-shawhum fazaa-dahum emaana(nw) Wa-qaaloo hasbunal laahu Wa-ni\'mal wakeel','page_number'=>72,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>174,'arabic_text'=>'فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ','transliteration'=>'Fan-qalaboo bini\'matim minal laahi Wa-fadlil lam yam-sashum sooo\'unw wattaba\'oo rid-waanal laah:(i) wal-laahu zoo fadlin \'azeem','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>175,'arabic_text'=>'إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'In-namaa zaalikumush Shaitaanu yukhawwifu awliyaaa\'ah(oo) falaa takhaa-foohum Wa-khaafooni in kuntum mu\'mineen','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>176,'arabic_text'=>'وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ','transliteration'=>'Wa-laa yahzunkal lazeena yusaari\'oona fil Kufr,(i) innahum laien yadurrul laaha shai\'aa:(n) yureedul laahu allaa yaj\'ala lahum hazzan fil Aakhira(ti); Wa-lahum \'azaabun \'azeem','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>177,'arabic_text'=>'إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Innal lazeenash tarawul kufra bil-eemaani laien yadurrul laaha shai\'anw Wa-lahum \'azaabun aleem','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>178,'arabic_text'=>'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ','transliteration'=>'Wa-laa yah-sabannal lazeena kafarooo annamaa numlee lahum khairulli an-fusihim, innamaa numlee lahum liyaz-daadooo isma,(nw) Wa-lahum \'azaabum muheen','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>179,'arabic_text'=>'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ','transliteration'=>'Maa kaanal laahu liya-zaral mu\'mineena \'alaa maaa antum \'alaihi hattaa yameezal khabeesa minat taiyyib:(i) Wa-maa kaanal laahu liyut-li\'akum \'alal ghaib(i) Wa-laakinnal laaha yajtabee mir rusulihee maien yashaaa\'(oo); fa-aaminoo billaahi Wa-Rusulih,(i) Wa-in tu-\'minoo Wa-tattaqoo falakum ajrun \'azeem','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>180,'arabic_text'=>'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Wa-laa yah-sabannal lazeena yab-khaloona bimaa aataa-humul laahu min fadilhee huwa khairal lahum; bal huwa sharrul lahum; sayu-tawwa-qoona maa ba-khiloo bihee Yawmal Qiyaama(h):(ti) Wa-lillaahi meeraa-sus samaawaati wal-ard:(i) wal-laahu bimaa ta\'maloona Khabeer','page_number'=>73,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>181,'arabic_text'=>'لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ','transliteration'=>'Laqad sami\'al laahu qawlal lazeena qaalooo innal laaha faqeerunw Wa-nahnu aghniyaaa\'. Sanaktubu maa qaaloo Wa-qat-lahumul Ambiyaa\'a bighairi haqq(inw) Wa-naqoolu zooqoo \'azaabal Hareeq','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>182,'arabic_text'=>'ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ','transliteration'=>'Zaalika bimaa qaddamat ai-deekum Wa-annal laaha laisa bi-zallaamil lil\'abeed','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>183,'arabic_text'=>'ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Allazeena qaalooo innal laaha \'ahida ilainaaa allaa nu\'mina li-Rasoolin hatta ya\'tiyanaa biqurbaanin ta-kuluhun naar:(u) qul qad jaaa\'akum Rusulum min qablee bil-baiyinaati Wa-billazee qultum falima qatal-tumoohum in kuntum saadiqeen','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>184,'arabic_text'=>'فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ','transliteration'=>'Fa-in kaz-zabooka faqad kuz-ziba Rusulum min qablik(a) jaaa\'oo bil-baiyinaati waz-Zuburi wal-Kitaabil Muneer','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>185,'arabic_text'=>'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ','transliteration'=>'Kulu nafsin zaaa\'iqatul mawt:(i) Wa-innamaa tuwaffawna ujoorakum Yawmal Qiyaama(ti); faman zuhziha \'anin Naari Wa-udkhilal Jannata faqad faaz:(a) Wa-mal hayaatud dunyaaa illaa mataa\'ul ghuroor','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>186,'arabic_text'=>'۞ لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ','transliteration'=>'^Latub-lawunna feee amwaalikum Wa-anfusikum Wa-latasma\'unna minal lazeena ootul Kitaaba min qablikum Wa-minal lazeena ashrakooo azan kaseeraa,(n) Wa-in tasbiroo Wa-tattaqoo fa-inna zaalika min \'azmil umoor','page_number'=>74,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>187,'arabic_text'=>'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ','transliteration'=>'Wa-iz akhazal laahu meesaa-qal lazeena ootul Kitaaba latu-baiyyi-nunna-hoo lin-naasi Wa-laa taktumoona(hoo- fanabazoohu waraaa\'a zuhoorihim washtaraw bihee samanan qaleela(n); fabi\'sa maa yashtaroon','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>188,'arabic_text'=>'لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Laa tah-sabannal lazeena yaf-rahoona bimaaa ataw Wa-yuhibbona aien yuhmadoo bimaa lam yaf\'aloo falaa tah-sa-bunnahum bima-faazatim minal \'azaab(i); Wa-lahum \'azaabun aleem','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>189,'arabic_text'=>'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Wa-lillaahi mulkus samaawaati wal-ard:(i) wal-laahu \'alaa kulli shai\'in Qadeer','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>190,'arabic_text'=>'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ','transliteration'=>'Inna fee khalqis samaawaati wal-ardi wakh-tilaafil laili wan-nahaari la-Aayaatil li-ulil albaab','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>191,'arabic_text'=>'ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ','transliteration'=>'Al-lazeena yaz-kuroonal laaha qiyaamanw wa-qu\'oodanw wa-\'alaa junoo-bihim Wa-yata-fakkaroona fee khalqis samaawaati wal-ard(i) Rabbanaa maa khalaqta haaza baatila(n) Subhaanaka faqinaa \'azaaban Naar','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>192,'arabic_text'=>'رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ','transliteration'=>'Rabbanaaa innaka man tud-khilin Naara faqad akhzai-tah(oo); Wa-maa liz-zaalimeena min ansaar','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>193,'arabic_text'=>'رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ','transliteration'=>'Rabbanaaa innanaa sami\'naa munaa-di-yaien yunaadee lil-eemaani an aaminoo bi-Rabbikum fa-aamannaa, Rabbanaa faghfir lanaa zunoobanaa Wa-kaffir \'annaa saiyi-aatina Wa-tawaffanaa ma\'al abraar','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>194,'arabic_text'=>'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ','transliteration'=>'Rabbanaa Wa-aatinaa maa wa\'adt-tanaa \'alaa Rusulika Wa-laa tukhzinaa Yawmal Qiyaama(h):(ti) innaka laa tukhliful mee\'aad','page_number'=>75,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>195,'arabic_text'=>'فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ','transliteration'=>'Fas-tajaaba lahum Rabbuhum annee laaa Udee\'u \'amala \'aamilim minkum min zakarin aw unsaa; ba\'dukum mim ba\'d(in); fal-lazeena haajaroo Wa-ukhrijoo min diyaa-rihim Wa-oozoo fee sabeelee Wa-qaataloo Wa-qutiloo la-ukaf-firanna \'anhum saiyyi-aatihim Wa-la-ud-khilanna-hum Jannnatin tajree min tah-tihal anhaar(u) sawaabam min \'indil laah:(i) wal-laahu \'indahoo husnus sawaab','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>196,'arabic_text'=>'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ','transliteration'=>'Laa yaghur-rannaka taqal-lubul lazeena kafaroo fil bilaad','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>197,'arabic_text'=>'مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ','transliteration'=>'Mataa\'un qaleelun summa ma\'waahum Jahannam,(u) Wa-bi\'sal mihaad','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>198,'arabic_text'=>'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ','transliteration'=>'Laakinil lazeenat taqaw Rabbahum lahum Jannnaatun tajree min tah-tihal anhaaru khaalideena feehaa nuzulam min \'indil laah:(i) Wa-maa \'indal laahi khairul lil-abraar','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>199,'arabic_text'=>'وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Wa-inna min Ahlil Kitaabi lamaien yu\'minu billaahi Wa-maaa unzila ilaikum Wa-maaa unzila ilaihim khaashi\'eena lillaahi laa yash-taroona bi-Aayaatil laahi samanan qaleelaa:(n) ulaaa\'ika lahum ajruhum \'inda Rabbihim: innal laaha saree\'ul hisaab','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>3,'ayah_number'=>200,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanus biroo Wa-saabiroo Wa-raabitoo wattaqul laaha la\'allakum tuflihoon','page_number'=>76,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            /* Surah 4: The Women (An-Nisa) */
            ['surah_id'=>4,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا','transliteration'=>'Yaaa-aiyuhan naasut taqoo Rabbakumul lazee khalaqakum min nafsinw waahidatinw wa-khalaqa minhaa zawjahaa wa-bas-sa minhumaa rijaalan kaseeranw wa-nisaaa\'aa; wattaqul laahal lazee tasaaa-\'aloona bihee wal-arhaam; innal laaha kaana \'alaikum Raqeeba','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>2,'arabic_text'=>'وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا','transliteration'=>'Wa-aatul yataamaaa amwaalahum wa-laa tatabad-dalul khabeesa bittaiyibi wa-laa taakulooo amwaalahum ilaaa amwaalikum; innahoo kaana hooban kabeeraa','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>3,'arabic_text'=>'وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ','transliteration'=>'Wa-in khiftum allaa tuqsitoo fil yataamaa fankihoo maa taaba lakum minan nisaaa\'i masnaa wa-sulaasa wa-rubaa\'a fa\'in khiftum allaa ta\'diloo fawaahidatan aw maa malakat aimaanukum; zaalika adnaaa allaa ta\'ooloo','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>4,'arabic_text'=>'وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا','transliteration'=>'Wa-aatun nisaaa\'a sadu-qaatihinna nihlah; fa-in tibna lakum \'an shai\'im minhu nafsan fakuloohu hanee\'am mareee\'aa','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>5,'arabic_text'=>'وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا','transliteration'=>'Wa-laa tu\'tus sufahaaa\'a amwaalakumul latee ja\'alal laahu lakum qiyaamanw warzuqoohum feehaa waksoohum wa-qooloo lahum qawlam ma\'roofaa','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>6,'arabic_text'=>'وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا','transliteration'=>'Wabtalul yataamaa hattaaa izaa balaghun nikaaha fa-in aanastum minhum rushdan fad-fa\'ooo ilaihim amwaalahum wa-laa taa-kuloohaaa israafanw wa-bidaaran ai yakbaroo; wa-mai kaana ghaniyyan falyasta\'fif wa-mai kaana faqeeran falyaakul bilma\'roof; fa-izaa dafa\'tum ilaihim amwaalahum fa\'ashhidoo \'alaihim; wa-kafaa billaahi Haseeba','page_number'=>77,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>7,'arabic_text'=>'لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا','transliteration'=>'Lirrijaali naseebum mimmaa tarakal waalidaani wal-aqraboona wa-lin-nisaaa\'i naseebum mimmaa tarakal waalidaani wal-aqraboona mimmaa qalla minhu aw kasur; naseebam mafroodaa','page_number'=>78,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>8,'arabic_text'=>'وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا','transliteration'=>'Wa-izaa hadaral qismata ulul qurbaa walyataamaa walmasaakeenu farzuqoohum minhu wa-qooloo lahum qawlam ma\'roofaa','page_number'=>78,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>9,'arabic_text'=>'وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا','transliteration'=>'Walyakhshal lazeena law tarakoo min khalfihim zurriyyatan di\'aafan khaafoo \'alaihim falyattaqul laaha walyaqooloo qawlan sadeedaa','page_number'=>78,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>10,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا','transliteration'=>'Innal lazeena yaakuloona amwaalal yataamaa zulman innamaa yaakuloona fee butoonihim Naaranw-wa sayaslawna sa\'eeraa','page_number'=>78,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>11,'arabic_text'=>'يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا','transliteration'=>'Yooseekumul laahu fee awlaadikum liz-zakari mislu hazzil unsayayn(i); fa-in kunna nisaaa\'an fawqas nataini falahunna sulusaa maa taraka wa-in kaanat waahidatan falahan nisf; wa-li-abawaihi likulli waahidim minhumas sudusu mimmma taraka in kaana lahoo walad; fa-il lam yakul lahu waladunw wa-warisahoo abawaahu fali-ummihis sulus; fa-in kaana lahoo ikhwatun fali-ummihis sudus; mim ba\'di wasiyyatien yoosee bihaaa aw dayn; aabaaa\'ukum wa-abnaaa\'ukum laa tadroona ai-yuhum aqrabu lakum naf\'aa; fareedatam minal laah; innal laaha kaana \'Aleeman Hakeemaa','page_number'=>78,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>12,'arabic_text'=>'۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ','transliteration'=>'Wa-lakum nisfu maa taraka azwaajukum il lam yakul lahunna walad; fa-in kaana lahunna waladun falakumur rubu\'u mimmaa tarakna mim ba\'di wasiyyatien yuseena bihaaa aw dayn; wa-lahunnar rubu\'u mimmaa tarakum il lam yakul lakum walad; fa-in kaana lakum waladun falahunnas sumunu mimmaa taraktum; mim ba\'di wasiyyatin toosoona bihaaa aw dayn; wa-in kaana raju-luin yoorasu kalaalatan awim ra-atunw wa-lahooo akhun aw ukhtun falikulli waahidim minhumas sudus; fa-in kaanooo aksara min zaalika fahum shurakaaa\'u fis sulusi mim ba\'di wasiyyatien yoosaa bihaaa aw dainin ghaira mudaaarr(in); wasiyyatam minal laah; wallaahu \'Aleemun Haleem','page_number'=>79,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>13,'arabic_text'=>'تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Tilka hudoodul laah; wa-maien yuti\'il laaha wa-Rasoolahoo yudkhilhu Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; wa-zaalikal fawzul \'azeem','page_number'=>79,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>14,'arabic_text'=>'وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ','transliteration'=>'Wa-maien ya\'sil laaha wa-Rasoolahoo wa-yata\'adda hudoodahoo yudkhilhu Naaran khaalidan feehaa wa-lahoo \'azaabum muheen','page_number'=>79,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>15,'arabic_text'=>'وَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا','transliteration'=>'Wallaatee ya-teenal faahishata min nisaaa\'ikum fastashhidoo \'alaihinna arba\'atam minkum fa-in shahidoo fa-amsikoohunna fil buyooti hatta yatawaffaa-hunnal mawtu aw yaj\'alal laahu lahunna sabeelaa','page_number'=>80,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>16,'arabic_text'=>'وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا','transliteration'=>'Wallazaani ya-tiyaanihaa minkum fa-aazoohumaa fa-in taabaa wa-aslahaa fa-a\'ridoo \'anhumaaa; innal laaha kaana Tawwaabar Raheema','page_number'=>80,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>17,'arabic_text'=>'إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا','transliteration'=>'Innamat tawbatu \'alallaahi lillazeena ya\'maloonas sooo\'a bijahaalatin summa yatooboona min qareebin faulaaika yatoobul laahu \'alaihim; wa kaanal laahu \'Aleeman Hakeemaa','page_number'=>80,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>18,'arabic_text'=>'وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا','transliteration'=>'Wa-laisatit tawbatu lillazeena ya\'maloonas saiyiaati hattaaa izaa hadara ahadahumul mawtu qaala innee tubtul \'aana wa-lal lazeena yamootoona wa-hum kuffaar; ulaaa\'ika a\'tadnaa lahum \'azaaban aleemaa','page_number'=>80,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>19,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo laa yahillu lakum an tarisun nisaaa\'a karhan wa-laa ta\'duloohunna litazhaboo biba\'di maaa aataitumoohunna illaaa aien yaateena bifaa-hishatim mubaiyyinah; wa-\'aashiroo-hunna bilma\'roof; fa-in karihtumoohunna fa\'asaaa an takrahoo shai\'anw wa-yaj\'alal laahu feehi khairan kaseeraa','page_number'=>80,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>20,'arabic_text'=>'وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا','transliteration'=>'Wa-in arattumustib daala zawjim makaana zawjin wa-aataitum ihdaahunna qintaaran falaa taakhuzoo minhu shai\'aa; ataakhuzoonahoo buhtaannanw wa-ismam mubeenaa','page_number'=>81,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>21,'arabic_text'=>'وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا','transliteration'=>'Wa-kaifa taakhuzoonahoo wa-qad afdaa ba\'dukum ilaa ba\'dinw wa-akhazna minkum meesaaqan ghaleezaa','page_number'=>81,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>22,'arabic_text'=>'وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا','transliteration'=>'Wa-laa tankihoo maa nakaha aabaaa\'ukum minan nisaaa\'i illaa maa qad salaf; inahoo kaana faahishatanw wa-maqtanw wa-saaa\'a sabeelaa','page_number'=>81,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>23,'arabic_text'=>'حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Hurrimat \'alaikum umma-haatukum wa-bannaatukum wa-akhawaatukum wa-\'ammaatukum wa-khaalaatukum wa-banaatul akhi wa-banaatul ukhti wa-ummahaatu kumul laateee arda\'-nakum wa-akhawaatukum minarradaa\'ati wa-ummahaatu nisaaa\'ikum wa-rabaaa\'i-bukumul laatee fee hujoorikum min nisaaa\'ikumul laatee dakhaltum bihinna Fa-il lam takoonoo dakhaltum bihina falaa junaaha \'alaikum wa halaaa\'ilu abnaaa\'ikumul lazeena min aslaabikum wa-an tajma\'oo bainal ukhtaini illaa maa qad salaf; innallaaha kaana Ghafoorar Raheema','page_number'=>81,'juz_number'=>4,'hizb_number'=>8,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>24,'arabic_text'=>'۞ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا','transliteration'=>'Walmuhsanaatu minan nisaaa\'i illaa maa malakat aimaanukum kitaabal laahi \'alaikum; wa-uhilla lakum maa waraaa\'a zaalikum an tabtaghoo bi-amwaali kum muhsineena ghaira musaa-fiheen; famastamta\'tum bihee minhunna fa-aatoohunna ujoorahunna fareedah; wa-laa junaaha \'alaikum feemaa taraadaitum bihee mim ba\'dil fareedah; innal laaha kaana \'Aleeman Hakeemaa','page_number'=>82,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>25,'arabic_text'=>'وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-mal lam yastati\' minkum tawlan ai yankihal muhsanaatil mu\'minaati famimmaa malakat aimaanukum min fatayaatikumul mu\'minaat; wallaahu a\'lamu bi-eemaanikum; ba\'dukum mim ba\'d; fankihoohunna bi-izni ahlihinna wa-aatoohunna ujoorahunna bilma\'roofi muhsanaatin ghaira musaafihaatinw wa-laa muttakhizaati akhdaan; fa-izaaa uhsinna fa-in ataina bifaahi-shatin fa\'alaihinnna nisfu maa \'alal muhsanaati minal \'azaab; zaalika liman khashiyal \'anata minkum; wa an tasbiroo khairul lakum; wallaahu Ghafoorur Raheem','page_number'=>82,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>26,'arabic_text'=>'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Yureedul laahu liyubai-yina lakum wa-yahdiyakum sunanal lazeena min qablikum wa-yatooba \'alaikum; wallaahu \'Aleemun Hakeem','page_number'=>82,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>27,'arabic_text'=>'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا','transliteration'=>'Wallaahu yureedu ai yatooba \'alaikum wa-yureedul lazeena yattabi-\'oonash shahawaati an tameeloo mailan \'azeemaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>28,'arabic_text'=>'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا','transliteration'=>'Yureedul laahu ai yukhaffifa \'ankum; wa-khuliqal insaanu da\'eefaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>29,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo laa taakulooo amwaalakum bainakum bilbaatili \'illaaa an takoona tijaaratan \'an taraadim minkum; wa-laa taqtulooo anfusakum; innal laaha kaana bikum Raheemaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>30,'arabic_text'=>'وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا','transliteration'=>'Wa-mai yaf\'al zaalika \'udwaananw wa-zulman fasawfa nusleehi Naaraa; wa-kaana zaalika \'alal laahi yaseeraa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>31,'arabic_text'=>'إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا','transliteration'=>'In tajtaniboo kabaaa\'ira maa tunhawna \'anhu nukaffir \'ankum saiyiaatikum wa-nudkhilkum mudkhalan kareemaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>32,'arabic_text'=>'وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا','transliteration'=>'Wa-laa tatamannaw maa faddalal laahu bihee ba\'dakum \'alaa ba\'d; lirrijaali naseebum mimak tasaboo wa-linnisaaa\'i naseebum mimmak tasabna; was\'alu llaaha min fadlih; innal laaha kaana bikulli shai\'in \'Aleemaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>33,'arabic_text'=>'وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا','transliteration'=>'Wa-likullin ja\'alnaa ma-waaliya mimmaa tarakal waalidaani wal-aqraboon; wallazeena \'aqadat aimaanukum fa-aatoohum naseebahum; innal laaha kaana \'alaa kulli shai\'in Shaheedaa','page_number'=>83,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>34,'arabic_text'=>'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا','transliteration'=>'Arrijaalu qawwaamoona \'alan nisaaa\'i bimaa fad-dalal laahu ba\'dahum \'alaa ba\'dinw wa-bimaaa anfoqoo min amwaalihim; fassaalihaatu qaanitaatun haafizaatul lil-ghaibi bimaa hafizal laah; wallaatee takhaafoona nushu-zahunna fa-\'izoohunna wahjuroohunna fil madaaji\'i wadriboohunna fa-in ata\'nakum falaa tabghoo \'alaihinna sabeelaa; innal laaha kaana \'Aliyyan Kabeeraa','page_number'=>84,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>35,'arabic_text'=>'وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا','transliteration'=>'Wa-in khiftum shiqaaqa baini-himaa fab\'asoo haka-mam min ahlihee wa-hakamam min ahlihaa; iny yureedaaa islaah ai-yuwaffiqil laahu bainahumaa; innal laaha kaana \'Aleeman Khabeeraa','page_number'=>84,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>36,'arabic_text'=>'۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا','transliteration'=>'Wa\'budul laaha wa-laa tushrikoo bihee shai\'anw wa-bil-waalidaini ihsaananw wa-bizil qurbaa wal-yataamaa wal-masaakeeni wal-jaari zil-qurbaa wal-jaaril junubi was-saahibi biljambi wabnis sabeeli wa maa malakat aimaanukum; innal laaha laa yuhibbu man kaana mukhtaalan fakhooraa','page_number'=>84,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>37,'arabic_text'=>'ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا','transliteration'=>'Allazeena yabkhaloona wa-ya-muroonan naasa bilbukhli wa-yaktumoona maaa aataahu-mul laahu min-fadlih; wa a\'-tadnaa lilkaafireena \'azaabam muheenaa','page_number'=>84,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>38,'arabic_text'=>'وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا','transliteration'=>'Wallazeena yunfiqoona amwaalahum ri\'aaa\'an naasi wa-laa yu\'minoona billaahi wa-laa bil-Yawmil Aakhir; wa-mai yakunish shaitaanu lahoo qareenan fasaaa\'a qareenaa','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>39,'arabic_text'=>'وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا','transliteration'=>'Wa-maazaa \'alaihim law aamanoo billaahi wal-Yawmil Aakhiri wa-anfaqoo mimmaa razaqahumul laah; wa kaanallaahu bihim Aaleemaa','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>40,'arabic_text'=>'إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا','transliteration'=>'Innal laaha laa yazlimu misqaala zarratinw wa-in taku hasanatany yudaa\'ifhaa wa-yu\'ti mil ladunhu ajran \'azeemaa','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>41,'arabic_text'=>'فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدٗا','transliteration'=>'Fakaifa izaa ji\'naa min kulli ummatim bishaheedinw wa ji\'naabika \'alaa haaa\'ulaaa-\'i Shaheedan','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>42,'arabic_text'=>'يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا','transliteration'=>'Yawma\'iziny yawad dullazeena kafaroo wa\'asawur Rasoola law tusawwaa bihimul ardu wa-laa yaktumoonal laaha hadeesaa','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>43,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا','transliteration'=>'yaaa-aiyuhal lazeena aamanoo laa taqrabus Salaata wa-antum sukaaraa hatta ta\'lamoo ma taqooloona wa-la junuban illaa \'aabiree sabeelin hatta taghtasiloo; wa-in kuntum mardaaa aw \'alaa safarin aw jaaa\'a ahadum minkum minal ghaaa\'iti aw laamastumun nisaaa\'a falam tajidoo maaa\'an fatayam-mamoo sa\'eedan taiyiban famsahoo biwujoohikum wa-aideekum; innal laaha kaana \'Afuwwan Ghafooraa','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>44,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ','transliteration'=>'Alam tara ilal lazeena ootoo naseebam minal Kitaabi yashtaroonad dalaalata wa-yureedoona an tadillus sabeel','page_number'=>85,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>45,'arabic_text'=>'وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا','transliteration'=>'Wallaahu a\'lamu bi-a\'daaa\'i-kum; wa-kafaa billaahi waliyyanw wa-kafaa billaahi naseera','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>46,'arabic_text'=>'مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا','transliteration'=>'Minal lazeena haadoo yuharrifoonal Kalima \'am mawaadi\'ihee wa-yaqooloona sami\'naa wa-\'asainaa wasma\' ghaira musma\'inw wa-raa\'inaa lai-yyam bi-alsinatihim wa-ta\'nan fid deen; wa-law annahum qaaloo sami\'naa wa-ata\'naa wasma\' wanzurnaa lakaana khairal lahum wa-aqwama wa-laakil la\'anahumul laahu bikufrihim falaa yu\'minoona illaa qaleela','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>47,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا','transliteration'=>'yaaa aiyuha lazeena ootu Kitaaba aaminoo bimaa nazzalnaa musadiqallimaa ma\'akum min qabli an natmisa wujoohan fanaruddahaa \'alaaa adbaarihaaa aw nal\'anahum kamaa la\'annaaa Ashaabas Sabt; wa-kaana amrul laahi maf\'oolaa','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>48,'arabic_text'=>'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا','transliteration'=>'Innal laaha laa yaghfiru ai yushraka bihee wa-yaghfiru maa doona zaalika limai yashaaa\'; wa-mai yushrik billaahi faqadif taraaa isman \'azeemaa','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>49,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا','transliteration'=>'Alam tara ilal lazeena yuzakkoona anfusahum; balil laahu yuzakkee mai yashaaa\'u wa-laa yuzlamoona fateelaa','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>50,'arabic_text'=>'ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا','transliteration'=>'Unzur kaifa yaftaroona \'alal laahil kazib, wakafaa biheee ismamm mubeenaa','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>51,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا','transliteration'=>'Alam tara ilal lazeena \'ootoo naseebam minal kitaabi yu\'minoona bil-Jibti wat-Taaghooti wa-yaqooloona lillazeena kafaroo haaa-ulaaa\'i ahdaa minal lazeena aamanoo sabeelaa','page_number'=>86,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>52,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا','transliteration'=>'Ulaaa\'ikal lazeena la\'ana-humul laahu wa-mai yal\'anil laahu falan tajida lahoo naseeraa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>53,'arabic_text'=>'أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا','transliteration'=>'Am lahum naseebum minal mulki fa-izal laa yu\'toonan naasa naqeeraa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>54,'arabic_text'=>'أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا','transliteration'=>'Am yahsudoonan naasa \'alaa maaa aataahumul laahu min fadlihee faqad aatainaaa Aala Ibraaheemal Kitaaba wal-Hikmata wa-aatainaahum mulkan \'azeemaa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>55,'arabic_text'=>'فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا','transliteration'=>'Faminhum man aamana bihee wa-minhum man sadda \'anh; wa-kafaa bi-Jahannama sa\'eeraa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>56,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا','transliteration'=>'Innal lazeena kafaroo bi Aayaatinaa sawfa nusleehim Naaran kullamaa nadijat julooduhum baddalnaahum juloodan ghairahaa liyazooqul \'azaab; innallaaha kaana \'Azeezan Hakeemaa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>57,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا','transliteration'=>'Wallazeena aamanoo wa-\'amilus saalihaati sanud-khiluum jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa, lahum feehaaa azwaajum mutahharatun wa-nudkhiluhum zillan zaleelaa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>58,'arabic_text'=>'۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا','transliteration'=>'Innal laaha yaamurukum an tu\'addul amaanaati ilaaa ahlihaa wa-izaa hakamtum bainan naasi an tahkumoo bil-\'adl; innal laaha ni\'immaa ya\'izukum bih; innal laaha kaana Samee\'am Baseera','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>59,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا','transliteration'=>'Yaaa-aiyuhal lazeena aamanooo atee\'ul laaha wa-atee\'ur Rasoola wa-ulil amri minkum fa-in tanaaza\'tum fee shai\'in faruddoohu ilal laahi war-Rasooli in kuntum tu\'minoona billaahi wal-yawmil Aakhir; zaalika khairunw wa-ahsanu taaweelaa','page_number'=>87,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>60,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا','transliteration'=>'Alam tara ilal lazeena yaz\'umoona annahum aarmanoo bimaa unzilaa ilaika wa-maaa unzila min qablika yureedoona aien yatahaakamooo ilat Taaghooti wa-qad umirooo aien yakfuroo bih, wa-yureedush Shaitaanu aien yudillahum dalaalam ba\'eedaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>61,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا','transliteration'=>'Wa-izaa qeela lahum ta\'aalaw ilaa maaa anzalal laahu Wa-ilar Rasooli ra-aital munaafiqeena yasuddoona \'anka sudoodaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>62,'arabic_text'=>'فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا','transliteration'=>'Fakaifa izaaa asaabathum museebatum bima qaddamat aydeehim summa jaaa\'ooka yahlifoona billaahi in aradnaaa illaaa ihsaananw Wa-tawfeeqaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>63,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا','transliteration'=>'Ulaaa\'ikal lazeena ya\'la mullaahu maa fee quloobihim Fa-a\'rid \'anhum Wa-\'izhum Wa-qul lahum feee anfusihim qawlam baleeghaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>64,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا','transliteration'=>'Wa-maa arsalnaa mir Rasoolin illaa liyutaa\'a bi-iznil laah; Wa-law annahum \'iz zalamooo anfusahum jaaa\'ooka fastaghfarul laaha wastaghfara lahumur Rasoolu la-wajadul laaha Tawwaabar Raheemaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>65,'arabic_text'=>'فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا','transliteration'=>'Falaa Wa-Rabbika laa yu\'minoona hattaa yuhakkimooka feemaa shajara bainahum summa laa yajidoo fee anfusihim harajam mimmaa qadaita Wa-yusal-limoo tasleemaa','page_number'=>88,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>66,'arabic_text'=>'وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا','transliteration'=>'Wa-law annaa katabnaa \'alaihim aniq tulooo anfusakum awikh rujoo min diyaarikum maa fa\'aloohu illaa qaleelum minhum Wa-law annahum fa\'aloo maa yoo\'azoona bihee lakaana khairal lahum Wa-ashadda tasbeetaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>67,'arabic_text'=>'وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا','transliteration'=>'Wa-izal la-aatainaahum mil ladunnaaa ajran \'azeemaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>68,'arabic_text'=>'وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا','transliteration'=>'Wa-lahadainaahum Siraatam mustaqeemaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>69,'arabic_text'=>'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقٗا','transliteration'=>'Wa-maien yuti\'il laaha war-Rasoola Fa-ulaaa\'ika ma\'al lazeena an\'amal laahu \'alaihim minan nabiyyeena wassiddeeqeena washshuhadaaa\'i wassaaliheen; Wa-hasuna ulaaa\'ika rafeeqaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>70,'arabic_text'=>'ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا','transliteration'=>'Zaalikal fadlu minal laah; Wa-kafaa billaahi \'Aleemaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>71,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo khuzoo hizrakum fanfiroo subaain awin firoo jamee\'aa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>72,'arabic_text'=>'وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا','transliteration'=>'Wa-inna minkum lamal la-yubatti\'anna Fa-in asaabatkum museebatun qaala qad an\'amal laahu \'alaiya iz lam akum ma\'ahum shaheeda','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>73,'arabic_text'=>'وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا','transliteration'=>'Wa-la-in asaabakum fadlum minal laahi la-yaqoolanna ka-al lam takum bainakum Wa-bainahoo mawaddatuien yaa-laitanee kuntu ma\'ahum Fa-afooza fawzan \'azeemaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>74,'arabic_text'=>'۞ فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا','transliteration'=>'Falyuqaatil fee sabeelil laahil lazeena yashroonal hayaatad dunyaa bil-Aakhirah; Wa-maien uqaatil fee sabeelil laahi Fa-yuqtal aw yaghlib fasawfa nu\'teehi ajran \'azeemaa','page_number'=>89,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>75,'arabic_text'=>'وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا','transliteration'=>'Wa-maa lakum laa tuqaatiloona fee sabeelil laahi walmustad\'afeena minar rijaali wannisaaa\'i walwildaanil lazeena yaqooloona Rabbanaaa akhrijnaa min haazihil qaryatiz zaalimi ahluhaa waj\'al lanaa mil ladunka waliyanw waj\'al lanaa mil ladunka naseeraa','page_number'=>90,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>76,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا','transliteration'=>'Allazeena aamanoo yuqaatiloona fee sabeelil laahi wallazeena kafaroo yuqaatiloona fee sabeelit Taaghoot faqaatiloo awliyaaa\'ash Shaitaan; inna kaidash Shaitaani kaana da\'eefa','page_number'=>90,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>77,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا','transliteration'=>'Alam tara ilal lazeena qeela lahum kuffooo aidiyakum Wa-aqeemus Salaata wa-aatuz Zakaata falammaa kutiba \'alaihimul qitaalu izaa fareequm minhum yakhshawnnan naasa kakhashyatil laahi aw ashadda khashyah; Wa-qaaloo Rabbanaa lima katabta \'alainal qitaala law-laaa akhkhartanaa ilaaa ajalin qareeb; qul mataa\'ud dunyaa qaleelunw wal-Aakhiratu khairul limanit taqaa Wa-laa tuzlamoona fateelaa','page_number'=>90,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>78,'arabic_text'=>'أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا','transliteration'=>'Ainamaa takoonoo yudrikkumul mawtu Wa-law kuntum fee buroojim mushaiy-yadah; Wa-in tusibhum hasanatuien yaqooloo haazihee min \'indil laahi Wa-in tusibhum saiyyi\'atuien yaqooloo haazihee min \'indik; qul kullum min \'indil laahi famaali haaa-\'ulaaa\'il qawmi la yakaadoona yafqahoona hadeesaa','page_number'=>90,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>79,'arabic_text'=>'مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا','transliteration'=>'Maaa asaabaka min hasanatin faminal laahi Wa-maaa asaaabaka min saiyi\'atin famin nafsik; Wa-arsalnaaka linnaasi Rasoolaa; Wa-kafaa billaahi Shaheedaa','page_number'=>90,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>80,'arabic_text'=>'مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا','transliteration'=>'Man yuti\'ir Rasoola faqad ataa\'al laaha Wa-man tawallaa famaaa arsalnaaka \'alaihim hafeezaa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>81,'arabic_text'=>'وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','transliteration'=>'Wa-yaqooloona taa\'antun Fa-izaa barazoo min \'indika baiyata taaa\'ifatum minhum ghairal lazee taqoolu wallaahu yaktubu maa yubaiyitoona faa\'rid \'anhum Wa-tawakkal \'alal laah; Wa-kafaa billaahi Wakeelaa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>82,'arabic_text'=>'أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا','transliteration'=>'Afalaa yatadabbaroonal Qur\'aan; Wa-law kaana min \'indi ghairil laahi la-wajadoo feehi-kh tilaafan kaseeraa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>83,'arabic_text'=>'وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا','transliteration'=>'Wa-izaa jaaa\'ahum amrum minal amni awil khawfi azaa\'oo bihee Wa-law raddoohu ilar Rasooli Wa-ilaaa ulil amri minhum la\'alimahul lazeena yastambitoonahoo minhum; Wa-law-laa fadlul laahi \'alaikum Wa-rahmatuhoo lattaba\'tumush Shaitaana illaa qaleelaa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>84,'arabic_text'=>'فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا','transliteration'=>'Faqaatil fee sabeelil laahi laa tukallafu illa nafsaka Wa-harridil mu\'mineena \'asal laahu aien yakuffa ba-sal lazeena kafaroo; wallaahu ashaddu ba-sanw Wa-ashaddu tankeelaa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>85,'arabic_text'=>'مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا','transliteration'=>'Maien yashfa\' shafaa\'atan hasanataien yakul lahoo naseebum minhaa Wa-maien yashfa\' shafaa\'tan saiyyi\'ataien yakul lahoo kiflum minhaa; Wa-kaanal laahu \'alaa kulli shai\'im Muqeetaa','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>86,'arabic_text'=>'وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا','transliteration'=>'Wa-izaa huyyeetum bi-tahiy-yatin fahaiyyoo bi-ahsana minhaaa aw ruddoohaa; innal laaha kaana \'alaa kulli shai\'in Haseeba','page_number'=>91,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>87,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا','transliteration'=>'Allaahu laaa ilaaha illaa huwa la-yajma\'annakum ilaa Yawmil Qiyaamati laa raiba feeh; Wa-man asdaqu minal laahi hadeesaa','page_number'=>92,'juz_number'=>5,'hizb_number'=>9,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>88,'arabic_text'=>'۞ فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا','transliteration'=>'Famaa lakum fil muna-fiqeena fi-ataini wallaahu arkasahum bimaa kasaboo; atureedoona an tahdoo man adallal laahu Wa-maien yudli-lil laahu falan tajida lahoo sabeelaa','page_number'=>92,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>89,'arabic_text'=>'وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا','transliteration'=>'Wadoo law takfuroona kamaa kafaroo fatakoonoona sawaaa\'an falaa tattakhizoo minhum awliyaaa\'a hattaa yuhaajiroo fee sabeelil laah; Fa-in tawallaw Fa-khuzoohum waqtuloohum haisu wajadt-tumoohum Wa-laa tattakhizoo minhum waliyyanw Wa-laa naseeraa','page_number'=>92,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>90,'arabic_text'=>'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا','transliteration'=>'Illal lazeena yasiloona ilaa qawmim bainakum Wa-bainahum meesaaqun aw jaaa\'ookum hasirat sudooruhum aien yuqaatilookum aw yuqaatiloo qawmahum, Wa-law shaaa\'al laahu lasallatahum \'alaikum falaqaatalookum; Fa-ini\' tazalookum falam yuqaatilookum Wa-alqaw ilaikumus salama famaa ja\'alal laahu lakum \'alaihim sabeelaa','page_number'=>92,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>91,'arabic_text'=>'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا','transliteration'=>'Satajidoona aakhareena yureedoona aien yaamanookum Wa-yaamanoo qawmahum kullamaa ruddooo ilal fitnati urkisoo feehaa; Fa-il lam ya\'tazilookum Wa-yulqooo ilai kumus salama Wa-yakuffooo aidiyahum fakhuzoohum waqtuloohum haisu saqif-tumoohum; Wa-ulaaa\'ikum ja\'alnaa lakum \'alaihim sultaanam mubeenaa','page_number'=>92,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>92,'arabic_text'=>'وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا','transliteration'=>'Wa-maa kaana limu\'minin aien yaqtula mu\'minan illaa khata\'aa; waman qatala mu\'minan khata\'an fatahreeru raqabatim mu\'minatyunw Wa-diyatum musallamatun ilaaa ahliheee illaaa aien yassaddaqoo; Fa-in kaana min qawmin \'aduwwil lakum Wa-huwa mu\'minun fatahreeru raqabatim mu\'minah; Wa-in kaana min qawmim bainakum Wa-bainahum meesaaqun fadiyatum musallamatun ilaaa ahlihee Wa-tahreeru raqabatim mu\'minatin famal lam yajid Fa-Siyaamu shahraini mutataabi\'aini tawbatam minal laah; Wa-kaanal laahu \'Aleeman hakeemaa','page_number'=>93,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>93,'arabic_text'=>'وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا','transliteration'=>'Wa-maien yaqtul mu\'minam muta\'ammidan fajazaaa\'uhoo Jahannamu khaalidan feehaa Wa-ghadibal laahu\' alaihi Wa-la\'anahoo Wa-a\'adda lahoo \'azaaban \'azeemaa','page_number'=>93,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>94,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا','transliteration'=>'Yaaa aiyuhal lazeena aamanoo izaa darabtum fee sabeelil laahi fatabaiyyanoo Wa-laa taqooloo liman alqaaa ilaikumus salaama lasta mu\'minan tabtaghoona \'aradal hayaatid dunyaa fa\'indal laahi maghaanimu kaseerah; kazaalika kuntum min qablu famannnal laahu \'alaikum fatabaiyyanoo; innallaaha kaana bimaa ta\'maloona Khabeeraa','page_number'=>93,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>95,'arabic_text'=>'لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا','transliteration'=>'Laa yastawil qaa\'idoona Minal mu\'mineena ghairu ulid darari walmujaahidoona fee sabeelil laahi bi-amwaalihim Wa-anfusihim; faddalal laahul mujaahideena bi-amwaalihim Wa-anfusihim \'alal qaa\'ideena darajah; Wa-kullanw wa\'adal laahul husnaa; Wa-faddalal laahul mujaahideena \'alal qaa\'ideena ajran \'azeemaa','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>96,'arabic_text'=>'دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا','transliteration'=>'Darajaatim minhu Wa-maghfiratanw Wa-rahmah; Wa-kaanal laahu Ghafoorar Raheema','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>97,'arabic_text'=>'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا','transliteration'=>'Innal lazeena tawaffaa-humul malaaa-ikatu zaalimeee anfusihim qaaloo feema kuntum qaaloo kunnaa mustad\'afeena fil ard; qaalooo alam takun ardul laahi waasi\'atan fatuhaajiroo feehaa; Fa-ulaaa\'ika ma-waahum Jahannamu Wa-saaa-at maseeraa','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>98,'arabic_text'=>'إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا','transliteration'=>'Illal mustad-\'afeena minar rijaali wannisaaa\'i walwildaani laa yastatee\'oona heelatanw Wa-laa yahtadoona sabeela','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>99,'arabic_text'=>'فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا','transliteration'=>'Fa-ulaaa\'ika \'asal laahu aien ya\'fuwa \'anhum; Wa-kaanal laahu \'Afuwwan Ghafooraa','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>100,'arabic_text'=>'۞ وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wa-maien yuhaajir fee sabeelil laahi yajid fil ardi muraaghaman kaseeranw Wa-sa\'ah; Wa-maien yakhruj mim baitihee muhaajiran ilal laahi Wa-Rasoolihee summa yudrikhul mawtu faqad waqa\'a ajruhoo \'alal laah; Wa-kaanal laahu Ghafoorar Raheemaa','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>101,'arabic_text'=>'وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا','transliteration'=>'Wa-izaa darabtum fil ardi falaisa \'alaikum junaahun an taqsuroo minas Salaati in khiftum aien yaftinakumul lazeena kafarooo; innal kaafireena kaanoo lakum aduwwam mubeenaa','page_number'=>94,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>102,'arabic_text'=>'وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا','transliteration'=>'Wa-izaa kunta feehim Fa-aqamta lahumus Salaata faltaqum taaa\'ifatum minhum ma\'aka walyaakhuzooo aslihatahum Fa-izaa sajadoo fal-yakoonoo mienw waraaa\'ikum walta-ti taaa\'ifatun ukhraa lam yusalloo falyusallo ma\'aka walyaakhuzoo hizrahum Wa-aslihatahum; waddal lazeena kafaroo law taghfuloona \'an aslihatikum Wa-amti\'atikum Fa-yameeloona \'alaikum mailatanw waahidah; Wa-laa junaaha \'alaikum in kaana bikum azam mim matarin aw kuntum mardaaa an tada\'ooo aslihatakum Wa-khuzoo hizrakum; innal laaha a\'adda lilkaafireena \'azaabam muheenaa','page_number'=>95,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>103,'arabic_text'=>'فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا','transliteration'=>'Fa-izaa qadaitumus Salaata fazkurul laaha qiyaamanw Wa-qu\'oodanw Wa-\'alaa junoobikum; Fa-izat ma-nantum Fa-aqeemus Salaah; innas Salaata kaanat \'alal mu\'mineena kitaabam mawqootaa','page_number'=>95,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>104,'arabic_text'=>'وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','transliteration'=>'Wa-laa tahinoo fib tighaaa\'il qawmi in takoonoo ta-lamoona Fa-innahum ya-lamoona kamaa ta-lamoona; Wa-tarjoona minal laahi maa laa yar-joon; Wa-kaanal laahu \'Aleeman Hakeemaa','page_number'=>95,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>105,'arabic_text'=>'إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا','transliteration'=>'Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi litahkuma bainan naasi bimaaa araakal laah; Wa-laa takul lilkhaaa\'ineena khaseemaa','page_number'=>95,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>106,'arabic_text'=>'وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wastaghfiril laaha innal laaha kaana Ghafoorar Raheema','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>107,'arabic_text'=>'وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا','transliteration'=>'Wa-laa tujaadil \'anil lazeena yakhtaanoona anfusahum; innal laaha laa yuhibbu man kaana khawwaanan aseemaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>108,'arabic_text'=>'يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا','transliteration'=>'Yastakhfoona minan naasi Wa-laa yastakh-foona minal laahi Wa-huwa ma\'ahum iz yubaiyitoona maa laa yardaa minal qawl; Wa-kaanal laahu bimaa ya\'maloona muheetaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>109,'arabic_text'=>'هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا','transliteration'=>'Haaa-antum haaa\'ulaaa\'i jaadaltum \'anhum fil hayaatid dunyaa famaien yujaadilul laaha \'anhum Yawmal Qiyaamati am maien yakoonu \'alaihim wakeelaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>110,'arabic_text'=>'وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wa-maien ya\'mal sooo\'an aw yazlim nafsahoo summa yastaghfiril laaha yajidil laaha Ghafoorar Raheemaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>111,'arabic_text'=>'وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا','transliteration'=>'Wa-maien yaksib isman Fa-innamaa yaksibuhoo \'alaa nafsih; Wa-kaanal laahu \'Aleeman hakeemaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>112,'arabic_text'=>'وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا','transliteration'=>'Wa-maien yaksib khateee\'atan aw isman summa yarmi bihee bareee\'an faqadih tamala buhtaananw Wa-ismam mubeenaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>113,'arabic_text'=>'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا','transliteration'=>'Wa-law-laa fadlul laahi \'alaika Wa-rahmatuhoo lahammat taaa\'ifatum minhum aien yudillooka Wa-maa yudilloona illaaa anfusahum Wa-maa yadurroonaka min shai\'; Wa-anzalal laahu \'alaikal Kitaaba wal-hikmata wa-\'allamaka maa lam takun ta\'lam; Wa-kaana fadlul laahi \'alaika \'azeemaa','page_number'=>96,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>114,'arabic_text'=>'۞ لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا','transliteration'=>'laa khaira fee kaseerim min najwaahum illaa man amara bisadaqatin aw ma\'roofin aw islaahim bainan naas; Wa-maien yaf\'al zaalikab tighaaa\'a mardaatil laahi Fa-sawfa nu\'teehi ajran \'azeemaa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>115,'arabic_text'=>'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا','transliteration'=>'Wa-main yushaaqiqir Rasoola mim ba\'di maa tabaiyyana lahul hudaa wa-yattabi\' ghaira sabeelil mu\'mineena nuwallihee ma tawallaa Wa-nuslihee Jahannama Wa-saaa\'at maseeraa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>116,'arabic_text'=>'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا','transliteration'=>'Innal laaha laa yaghfiru aien yushraka bihee wayaghfiru maa doona zaalika limain yashaaa\'; Wa-main yushrik billaahi faqad dalla dalaalam ba\'eedaa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>117,'arabic_text'=>'إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا','transliteration'=>'Iien yad\'oona min dooniheee illaaa inaasanw wa-ien yad\'oona illaa Shaitaanam mareedaa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>118,'arabic_text'=>'لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا','transliteration'=>'La\'anahul laah; Wa-qaala la-attakhizanna min \'ibaadika naseebam mafroodaa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>119,'arabic_text'=>'وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا','transliteration'=>'Wa-la-udillannahum Wa-la-umanni-yannnahum Wa-la-aamurannahum fala-yubat-tikunna aazaanal an\'aami Wa-la-aamurannahum fala-yughaiy-yirunna khalqal laah; Wa-main yattakhizish Shaitaana waliyyam mmin doonil laahi faqad khasira khusraanam mubeena','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>120,'arabic_text'=>'يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا','transliteration'=>'Ya\'iduhum Wa-yuman-neehim Wa-maa ya\'iduhumush Shaitaanu illaa ghurooraa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>121,'arabic_text'=>'أُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا','transliteration'=>'Ulaaa\'ika ma\'waahum Jahannamu Wa-laa yajidoona \'anhaa maheesaa','page_number'=>97,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>122,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا','transliteration'=>'Wallazeena aamanoo Wa-\'amilus saalihaati sanud-khiluhum Jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; wa\'dal laahi haqqaa; Wa-man asdaqu minal laahi qeelaa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>123,'arabic_text'=>'لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا','transliteration'=>'Laisa bi-amaaniyyikum Wa-laaa amaaniyyi Ahlil Kitaab; main ya\'mal sooo\'aien yujza bihee Wa-laa yajid lahoo min doonil laahi waliyanw Wa-laa naseeraa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>124,'arabic_text'=>'وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا','transliteration'=>'Wa-main ya\'mal minas saalihaati min zakarin aw unsaa Wa-huwa mu\'minun fa-ulaaa\'ika yadkhuloonal Jannata Wa-laa yuzlamoona naqeeraa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>125,'arabic_text'=>'وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا','transliteration'=>'Wa-man ahsanu deenam mimmman aslama wajhahoo lillaahi Wa-huwa muhsinunw wattaba\'a Millata Ibraaheema haneefaa; wattakhazal laahu Ibraaheema khaleelaa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>126,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا','transliteration'=>'Wa-lillaahi maa fis samaawaati Wa-maa fil ard; Wa-kaanal laahu bikulli shai\'im muheetaa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>127,'arabic_text'=>'وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا','transliteration'=>'Wa-yastaftoonaka fin nisaaa\'i qulil laahu yufteekum feehinna Wa-maa yutlaa \'alaikum fil Kitaabi fee yataaman nisaaa\'il laatee laa tu\'toonahunna maa kutiba lahunnna Wa-targhaboona an tankihoohunna wal-mustad\'a-feena minal wildaani Wa-an taqoomoo lilyataamaa bilqist; Wa-maa taf\'aloo min khairin fa-innal laaha kaana bihee \'Aleemaa','page_number'=>98,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>128,'arabic_text'=>'وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا','transliteration'=>'Wa-inim ra-atun khaafat mim ba\'lihaa nushoozan aw i\'raadan falaa junaaha \'alaihi-maaa aien yuslihaa bainahumaa sulhaa; wassulhu khair; Wa-uhdiratil anfusush shuhh; Wa-in tuhsinoo Wa-tattaqoo fa-innal laaha kaana bimaa ta\'maloona Khabeeraa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>129,'arabic_text'=>'وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wa-lan tastatee\'ooo an ta\'diloo bainan nisaaa\'i Wa-law harastum falaa tameeloo kullal maili fatazaroohaa kalmu\'al-laqah; Wa-in tuslihoo Wa-tattaqoo fa-innal laaha kaana Ghafoorar Raheema','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>130,'arabic_text'=>'وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا','transliteration'=>'Wa-ien yatafarraqaa yughnil laahu kullam min sa\'atih; Wa-kaanal laahu Waasi\'an Hakeemaa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>131,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا','transliteration'=>'Wa-lillaahi ma fis samaawaati Wa-maa fil ard; Wa-laqad wassainal lazeena ootul Kitaaba min qablikum Wa-iyyaakum anit taqul laah; Wa-in takfuroo fa-inna lillaahi ma fis samaawaati Wa-ma fil ard; Wa-kaanal laahu Ghaniyyan hameedaa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>132,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','transliteration'=>'Wa-lillaahi ma fis samaawaati Wa-ma fil ard; Wa-kafaa billaahi Wakeelaa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>133,'arabic_text'=>'إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا','transliteration'=>'Ien yasha yuzhibkum aiy-yuhan naasu Wa-ya\'ti bi-aakhareen; Wa-kaanal laahu \'alaa zaalika Qadeeraa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>134,'arabic_text'=>'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا','transliteration'=>'man kaana yureedu sawaabad dunyaa fa\'indal laahi sawaabud dunyaa wal-Aakhirah; Wa-kaanal laahu Samee\'am Baseeraa','page_number'=>99,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>135,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا','transliteration'=>'Yaa-aiyyuhal lazeena aamanoo koonoo qawwa-meena bilqisti shuhadaaa\'a lillaahi Wa-law \'alaa anfusikum awil waalidaini wal-aqrabeen ien yakun ghaniyyan aw faqeeran fallaahu awlaa bihimaa falaaa tattabi\'ul hawaaa an ta\'diloo; Wa-in talwooo aw tu\'ridoo fa-innal laaha kaana bimaa ta\'maloona Khabeera','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>136,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanooo aaminoo billaahi Wa-Rasoolihee wal-Kitaabil lazee nazzala \'alaa Rasoolihee wal-Kitaabil lazeee anzala min qabl; Wa-main yakfur billaahi Wa-Malaaa\'ikatihee Wa-Kutubihee Wa-Rusulihee wal-Yawmil Aakhiri faqad dalla dalaalam ba\'eedaa','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>137,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا','transliteration'=>'Innal lazeena aamanoo summa kafaroo summa aamanoo summa kafaroo summaz daado kufral lam yakunil laahu liyaghfira lahum Wa-laa liyahdiyahum sabeelaa','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>138,'arabic_text'=>'بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا','transliteration'=>'Bash-shiril munaafiqeena bi-anna lahum \'azaaban aleemaa','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>139,'arabic_text'=>'ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا','transliteration'=>'Allazeena yattakhizoo-nal kaafireena awliyaaa\'a min doonil mu\'mineen; a-yabtaghoona \'indahumul \'izzata fainnnal \'izzata lillaahi jamee\'aa','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>140,'arabic_text'=>'وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا','transliteration'=>'Wa-qad nazzala \'alaikum fil Kitaabi an izaa sami\'tum Aayaatil laahi yukfaru bihaa Wa-yustahza-oo bihaa falaa taq\'udoo ma\'ahum hattaa yakhoodoo fee hadeesin ghairih; innakum izam misluhum; innal laaha jaami\'ul munaafiqeena wal-kaafireena fee jahannama jamee\'aa','page_number'=>100,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>141,'arabic_text'=>'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا','transliteration'=>'Allazeena yatarab-basoona bikum fa-in kaana lakum fath-hum minal laahi qaalooo alam nakum ma\'akum Wa-in kaana lilkaafireena naseebun qaalooo alam nastah-wiz \'alaikum Wa-nammna\'kum minal mu\'mineen; fallaahu yahkumu bainakum Yawmal Qiyaamah; Wa-lain yaj\'alal laahu lilkaafireena \'alal mu\'mineena sabeelaa','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>142,'arabic_text'=>'إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا','transliteration'=>'Innal munaafiqeena yukhaadi\'oonal laaha Wa-huwa khaadi\'uhum Wa-izaa qaamooo ilas Salaati qaamoo kusaalaa yuraaa-oonan naasa Wa-laa yazkuroonal laaha illaa qaleelaa','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>143,'arabic_text'=>'مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا','transliteration'=>'Muzab-zabeena baina zaalika laaa ilaa haaa-ulaaa-e Wa-laaa ilaa haaa\'ulaaa\'; Wa-main yudli-lil laahu falan tajida lahoo sabeela','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>144,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tattakhizul kaafireena awliyaaa\'a min doonil mu\'mineen; aturee-doona an taj\'aloo lillaahi \'alaikum sultaanam mubeenaa','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>145,'arabic_text'=>'إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا','transliteration'=>'Innal munaafiqeena fid darkil asfali minan Naari Wa-lan tajida lahum naseeraa','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>146,'arabic_text'=>'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا','transliteration'=>'Illal lazeena taaboo Wa-aslahoo wa\'tasamoo billaahi Wa-akhlasoo deenahum lillaahi faulaaa\'ika ma\'al mu\'mineena Wa-sawfa yu\'til laahul mu\'mineena ajran \'azeemaa','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>147,'arabic_text'=>'مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا','transliteration'=>'Ma yafa\'lul laahu bi\'azaabikum in shakartum Wa-aamantum; Wa-kaanal laahu Shaakiran \'Aleema','page_number'=>101,'juz_number'=>5,'hizb_number'=>10,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>148,'arabic_text'=>'۞ لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا','transliteration'=>'La yuhibbul laahul jahra bis-sooo\'i minal qawli illaa man zulim; Wa-kaanal laahu Samee\'an \'Aleemaa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>149,'arabic_text'=>'إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا','transliteration'=>'in tubdoo khairann aw tukhfoohu aw ta\'foo \'an sooo\'in fa-innal laaha kaana \'afuwwan Qadeeraa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>150,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا','transliteration'=>'Innal lazeena yakkfuroona billaahi Wa-Rusulihee Wa-yureedoona aien yufarriqoo bainal laahi Wa-Rusulihee Wa-yaqooloona nu\'minu biba\'dinw Wa-nakfuru biba\'-dinw Wa-yureedoona aien yattakhizoo baina zaalika sabeelaa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>151,'arabic_text'=>'أُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا','transliteration'=>'Ulaaa\'ika humul kaafiroona haqqaaw; Wa-a\'tadnaa lilkaafireena \'azaabam muheenaa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>152,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wallazeena aamanoo billaahi Wa-Rusulihee Wa-lam yufarriqoo baina ahadim minhum ulaaa\'ika sawfa yu\'teehim ujoorahum; Wa-kaanal laahu Ghafoorar Raheema','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>153,'arabic_text'=>'يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا','transliteration'=>'Yas\'aluka Ahlul Kitaabi an tunazzila \'alaihim Kitaabam minas samaaa\'i faqad sa-aloo Moosaa akbara min zaalika faqaaloo arinal laaha jahratan fa-akhazat-humus saa\'iqatu bizulmihim; summat takhazul \'ijla mim ba\'di maa jaa\'at-humul baiy-yinaatu fa\'afawnaa \'ann zaalik; Wa-aatainaa Moosaa sultaanam mubeenaa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>154,'arabic_text'=>'وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا','transliteration'=>'Wa-rafa\'naa fawqahumut Toora bimeesaaqihim Wa-qulnaa lahumud khulu abaaba sujjadanw Wa-qulnaa lahum laa ta\'doo fis Sabti Wa-akhaznaa minhum meesaaqan ghaleezaa','page_number'=>102,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>155,'arabic_text'=>'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا','transliteration'=>'Fabimaa naqdihim meesaaqahum Wa-kufrihim bi-aayaatil laahi Wa-qatlihimul Ambiyaaa\'a bighairi haqqinw Wa-qawlihim quloobunaa ghulf; bal taba\'al laahu \'alaihaa bikufrihim falaa yu\'minoona illaa qaleelaa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>156,'arabic_text'=>'وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا','transliteration'=>'Wa-bikufrihim Wa-qawlihim \'alaa Maryama buh-taanan \'azeema','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>157,'arabic_text'=>'وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا','transliteration'=>'Wa qawlihim innaa qatal-nal maseeha \'Eesab na-Maryama Rasoolal laahi Wa-maa qataloohu Wa-maa sala-boohu Wa-laakin shubbiha lahum; Wa-innal lazeenakh talafoo feehee lafee shakkim minh; maa lahum bihee min \'ilmin illat tibaa\'az zann; Wa-maa qataloohu yaqeenaa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>158,'arabic_text'=>'بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا','transliteration'=>'Bal rafa\'ahul laahu ilayh; Wa-kaanal laahu \'Azeezan Hakeemaa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>159,'arabic_text'=>'وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا','transliteration'=>'Wa-im min Ahlil Kitaabi illaa layu\'minanna bihee qabla mawtihee Wa-Yawmal Qiyaamati yakoonu \'alaihim shaheedaa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>160,'arabic_text'=>'فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا','transliteration'=>'Fabizulmim minal lazeena haadoo harramnaa \'alaihim taiyibaatin uhillat lahum Wa-bisadihim \'an sabeelil laahi kaseeraa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>161,'arabic_text'=>'وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا','transliteration'=>'Wa-akhzihimur ribaa Wa-qad nuhoo \'anhu Wa-aklihim amwaalan naasi bilbaatil; Wa-a\'tadnaa lilkaafireena minhum \'azaaban aleema','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>162,'arabic_text'=>'لَّٰكِنِ ٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا','transliteration'=>'Laakinir raasikhoona fil \'ilmi minhum walmu\'minoona yu\'minoona bimaaa unzila ilaika Wa-maaa unzila min qablika walmuqeemeenas Salaata walmu-toonaz Zakaata walmu\'minoona billaahi wal-yawmil Aakhir; ulaaa\'ika sanu\'teehim ajran \'azeemaa','page_number'=>103,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>163,'arabic_text'=>'۞ إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا','transliteration'=>'Innaaa aw-hainaaa ilaika kamaaa awhainaaa ilaa Noohinw wan-nabiyyeena mim ba\'dih; Wa-awhainaaa ilaaa ibraaheema Wa-Ismaaa\'eela Wa-Ishaaqa Wa-Ya\'qooba wal-Asbaati Wa-\'Eesaa Wa-Ayyooba Wa-Yoonusa Wa-haaroona Wa-Sulaimaan; Wa-aatainaa Daawooda Zabooraa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>164,'arabic_text'=>'وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا','transliteration'=>'Wa-Rusulan qad qasas-naahum \'alaika min qablu Wa-Rusulal lam naqsushum \'alaik; Wa-kallamal laahu Moosaa takleemaa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>165,'arabic_text'=>'رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا','transliteration'=>'Rusulam mubashshireena Wa-munzireena li\'allaa yakoona linnaasi \'alal laahi hujjatum ba\'dar Rusul; Wa-kaanal laahu \'Azeezan Hakeema','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>166,'arabic_text'=>'لَّٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا','transliteration'=>'Laakinil laahu yashhadu bimaaa anzala ilaika anzalahoo bi\'ilmihee wal-malaaa\'ikatu yashhadoon; Wa-kafaa billaahi Shaheeda','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>167,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا','transliteration'=>'Innal lazeena kafaroo Wa-saddoo \'an sabeelil laahi qad dalloo dalaalam ba\'eedaa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>168,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا','transliteration'=>'Innal lazeena kafaroo Wa-zalamoo lam yakunil laahu liyaghfira lahum Wa-laa liyahdiyahum tareeqaa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>169,'arabic_text'=>'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا','transliteration'=>'Illaa tareeqa jahannamma khaalideena feehaa abadaa; Wa-kaana zaalika \'alal laahi yaseeraa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>170,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا','transliteration'=>'Yaaa-aiyyuhan naasu qad jaaa\'akumur Rasoolu bilhaqqi mir Rabbikum fa-ammminoo khairal lakum; Wa-in takfuroo fa-inna lillaahi ma fis samaawaati wal-ard; Wa-kaanal laahu \'Aleemann hakeemaa','page_number'=>104,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>171,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا','transliteration'=>'Ya-Ahlal Kitaabi la taghloo fee deenikum Wa-laa taqooloo \'alal laahi illal haqq; innamal Maseehu \'Eesab nu Maryama Rasoolul laahi Wa-Kalimatuhooo alqaahaaa ilaa Maryamma Wa-roohum minhum fa-aaminoo billaahi Wa-Rusulihee Wa-laa taqooloo salaasah; intahoo khairal lakum; innamal laahu Ilaahunw Waahid, Subhaanahooo aien yakoona lahoo walad; lahoo ma fis samaawaati Wa-ma fil ard; Wa-kafaa billaahi Wakeelaa','page_number'=>105,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>172,'arabic_text'=>'لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا','transliteration'=>'Laien yastankifal Maseehu aien yakoona \'abdal lillaahi Wa-lal malaaa\'ikatul muqarraboon; Wa-maien yastankif \'an ibaadatihee Wa-yastakbir fasa-yahshuruhum ilaihi jamee\'aa','page_number'=>105,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>173,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا','transliteration'=>'Fa-ammal lazeena aamanoo Wa-\'amilus saalihaati fa-yuwaffeehim ujoorahum Wa-yazeeduhum min fadlihee Wa-ammal lazeenas tankafoo wastakbaroo fa-yu\'azzibuhum \'azaaban aleemanw Wa-laa yajidoona lahum min doonil laahi waliyyanw Wa-laa naseeraa','page_number'=>105,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>174,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا','transliteration'=>'Ya-aiyyuhan naasu qad jaaa\'akum burhaanum mir Rabbikum Wa-anzalnaaa ilaikum Nooram Mubeena','page_number'=>105,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>175,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا','transliteration'=>'Fa-ammal lazeena aamanoo billaahi wa\'tasamoo bihee fasa-yudkhiluhum fee rahmatim minhu Wa-fadlinw Wa-yahdeehim ilaihi Siraatam Mustaqeema','page_number'=>105,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>4,'ayah_number'=>176,'arabic_text'=>'يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ','transliteration'=>'Yastaftoonaka qulil laahu yufteekum fil kalaalah; inim ru\'un halaka laisa lahoo waladunw Wa-lahoo ukhtun falahaa nisfu maa tarak; Wa-huwa yarisuhaaa il lam yakkul lahaa walad; fa-in kaanatas nataini falahumas sulusaani mimmmaa tarak; Wa-in kaanooo ikhwatar rijaalanw Wa-nisaaa\'an faliz-zakari mislu hazzil unsa-ya-iyn; yubaiyinul laahu lakum an tadilloo; wallaahu bikulli shai\'in Aleem','page_number'=>106,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            /* Surah 5: The Table Spread (Al-Ma'idah) */
            ['surah_id'=>5,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo awfoo bil\'uqood; uhillat lakum baheematul an\'aami illaa maa yutlaa \'alaikum ghaira muhillis saidi wa-antum hurum; innal laaha yahkumu maa yureed','page_number'=>106,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>2,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tuhilloo sha\'aaa-\'iral laahi wa-lash shahral haraama wa-lal hadya wa-lal qalaaa-ida wa-laa aaam-meenal baital haraama yabtaghoona fadlam mir Rabbihim wa-ridwaanaa; Wa-izaa halaltum fastaadoo; Wa-laa yajriman-nakum shana-aanu qawmin an saddookum \'anil Masjidil haraami an ta\'tadoo; wa-ta\'aawanoo \'alal birri wattaqwaa; wa-laa ta\'aawanoo \'alal ismi wal\'udwaan; wattaqul laaha; innal laaha shadeedul \'iqaab','page_number'=>106,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>3,'arabic_text'=>'حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Hurrimat \'alaikumul mai-tatu waddamu wa-lahmul khinzeeri wa-maaa uhilla lighairil laahi bihee walmun-khani-qatu wal-mawqoozatu wal-mutarad-diyatu wan-nateehatu wa-maaa akalas sabu\'u illaa maa zakkaitum wa-maa zubiha \'alan nusubi wa-an tastaq-simoo bil-azlaam; zaalikum fisq; alyauma ya-isal lazeena kafaroo min deenikum falaa takhshau-hum wakh-shaoun; alyauma akmaltu lakum deenakum wa-atmamtu \'alaikum ni\'matee wa-radeetu lakumul Islaama deenaa; famanid turra fee makh-masatin ghaira muta-jaa-nifil li-ismin fa-innal laaha Ghafoorur Raheem','page_number'=>107,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>4,'arabic_text'=>'يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Yas-aloonaka maazaaa uhilla lahum; qul uhilla lakumut taiyyibaatu wa-maa\' allamtum minal jawaarihi mukal-libeena tu\'allimoona-hunna mimmaa \'allama-kumul laah fakuloo mimmaaa amsakna \'alaikum wazkurus mal laahi \'alaih; wattaqul laah; innal laaha saree\'ul hisaab','page_number'=>107,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>5,'arabic_text'=>'ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Alyauma uhilla lakumut taiyyibaatu wa-ta\'aamul lazeena ootul kitaaba hillul lakum wa-ta\'aamukum hillul lahum wal-muhsanaatu minal mu-minaati wal-muhsanaatu minal lazeena ootul kitaaba min qablikum izaaa aatai-tumoohunna ujoorahunna muhsineena ghaira musaa-fiheena wa-laa muttakhizeee akhdaan; wa-main yakfur bil-eemaani faqad habita \'amaluhoo wa-huwa fil aaakhirati minal khaasireen','page_number'=>107,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>6,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo izaa qumtum ilas salaati fagh-siloo wujoohakum wa-aidiyakum ilal maraafiqi wam-sahoo biru-oosikum wa-arjulakum ilal ka\'bayn; wa-in kuntum junuban fattah-haroo; wa-in kuntum mardaaa aw \'alaa safarin aw jaaa-a ahadum minkum minal ghaaa-iti aw laamastumun nisaaa-a falam tajidoo maaa-an fatayam-mamoo sa\'eedan taiyyiban famsahoo biwujoohikum wa-aideekum minh; ma yureedul laahu liyaj\'ala \'alaikum min haraj(inw) wa-laakien yureedu liyutah-hirakum wa-liyutimma ni\'matahoo \'alaikum la\'allakum tashkuroon','page_number'=>108,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>7,'arabic_text'=>'وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Wazkuroo ni\'matal laahi \'alaikum wa-meesaaqahul lazee waasaqakum biheee iz qultum sami\'naa wa-ata\'naa wattaqul laah(a); innal laaha \'aleemum bizaatis sudoor','page_number'=>108,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>8,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamaanoo koonoo qawwaa-meena lillaahi shuhadaaa-a bilqist, wa-laa yajri-mannakum shana-aanu qawmin \'alaaa allaa ta\'diloo; i\'diloo; huwa aqrabu littaqwaa wattaqul laah(a); innal laaha khabeerum bimaa ta\'maloon','page_number'=>108,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>9,'arabic_text'=>'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ','transliteration'=>'Wa\'adal laahul lazeena aamanoo wa-\'amilus saalihaati lahum maghfiratunw wa-ajrun \'Azeem','page_number'=>108,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>10,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','transliteration'=>'Wallazeena kafaroo wa-kazzaboo bi-aayaatinaaa ulaaa-ika as-haabul jaheem','page_number'=>109,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>11,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Yaa-aiyyuhal lazeena aamanuz kuroo ni\'matal laahi \'alaikum iz hamma qawmun aien yabsutooo ilaikum ai-diyahum fakaffa ai-diyahum \'ankum wattaqul laah; wa\'alal laahi fal-yatawak-kalil mu-minoon','page_number'=>109,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>12,'arabic_text'=>'۞ وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','transliteration'=>'Wa-laqad akhazal laahu meesaaqa banee israaa-eela wa-ba\'s-naa minhumus nai \'ashara naqeeba(nw) wa-qaalal laahu innee ma\'akum la-in aqam-tumus salaata wa-aatai-tumuz zakaata wa-aamantum bi-Rusulee wa\'azzar-tumoohum wa-aqrad-tumul laaha qardan hasanal la-ukaffiranna \'ankum saiyyi-aatikum wa-la-udkhilan-nakum jannaatin tajree min tah-tihal anhaar; faman kafara ba\'da zaalika minkum faqad dalla sawaaa assabeel','page_number'=>109,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>13,'arabic_text'=>'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ','transliteration'=>'Fabimaa naq-dihim meesaa-qahum la\'an-naahum wa-ja\'alnaa quloobahum qaasiyah(tan) yuharrifoonal kalima \'amma waadi\'ihee wa-nasoo hazzam mimmaa zukkiroo bih; wa-laa tazaalu tattali\'u \'alaa khaaa-inatim minhum illaa qaleelam minhum fa\'fu \'anhum wasfah; innal laaha yuhibbul muhsineen','page_number'=>109,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>14,'arabic_text'=>'وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ','transliteration'=>'Wa-minal lazeena qaalooo innaa nasaaraaa akhaznaa mee-saaqahum fanasoo hazzam mimmaa zukkiroo bihee fa-aghrainaa baina-humul \'adaawata wal-baghdaaa-a ilaa yawmil qiyaamah; wa-sawfa yunabbi-uhumul laahu bimaa kaanoo yasna\'oon','page_number'=>110,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>15,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ','transliteration'=>'Yaaa-ahlal kitaabi qad jaaa-akum Rasoolunaa yubaiyyinu lakum kaseeram mimmmaa kuntum tukhfoona minal kitaabi wa-ya\'foo \'an kaseer; qad jaaa-akum minal laahi noorunw wa-kitaabum mubeen','page_number'=>110,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>16,'arabic_text'=>'يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Yahdee bihil laahu manit taba\'a ridwaanahoo subulas salaam(i) Wa-yukhrijuhum minaz zulumaati ilan noori bi-iznihee Wa-yahdeehim ilaa Siraatim Mustaqeem','page_number'=>110,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>17,'arabic_text'=>'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Laqad kafaral lazeena qaalooo innal laaha huwal maseehub nu Maryam(a); qul famaien yamliku minal laahi shai\'an in araada aien yuhlikal Maseehab na Maryama Wa-ummahoo Wa-man fil ardi jamee\'aa, Wa-lillaahi mulkus samaawaati wal-ardi Wa-maa bainahumaa; yakhluqu maa Yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer','page_number'=>110,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>18,'arabic_text'=>'وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ','transliteration'=>'Wa-qaalatil Yahoodu wan-Nasaaraa nahnu abnaaa\'ul laahi Wa-ahibbaaa\'uh; qul falima yu\'azzibukum bizunoobikum bal antum basharum mimman khalaq; yaghfiru limaien yashaaa\'u Wa-yu\'azzibu maien yashaaa\'; Wa-lillaahi mulkus samaawaati wal-ardi Wa-maa bainahumaa Wa-ilaihil maseer','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>19,'arabic_text'=>'يَٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Yaaa-Ahlal Kitaabi qad jaaa\'akum Rasoolunaa yubaiyinu lakum \'alaa fatratim minar Rusuli an taqooloo maa jaaa\'anaa mim basheerinw Wa-laa nazeerin faqad jaaa\'akum basheerunw Wa-nazeer; wallaahu \'alaa kulli shai\'in Qadeer','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>20,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-iz qaala Moosaa liqawmihee yaa-qawmiz kuroo ni\'matal laahi \'alaikum iz ja\'ala feekum ambiyaaa\'a Wa-ja\'alakum mulookanw Wa-aataakum maa lam yu\'ti ahadam minal \'aalameen','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>21,'arabic_text'=>'يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ','transliteration'=>'Yaa-qawmid khulul Ardal Muqaddasatal latee katabal laahu lakum Wa-laa tartaddoo \'alaaa adbaarikum fatan-qaliboo khaasireen','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>22,'arabic_text'=>'قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ','transliteration'=>'Qaaloo yaa-Moosaaa innaa feehaa qawman jabbaa-reena Wa-innaa lan nad-khulahaa hattaa yakhrujoo minhaa fa-ien yakhrujoo minhaa fa-innaa daa-khiloon','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>23,'arabic_text'=>'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Qaala rajulaani minal lazeena yakhaafoona an\'amal laahu \'alai-himad khuloo \'alai-himul baab, fa-izaa dakhal-tumoohu fa-innakum ghaaliboon; Wa-\'alal laahi fatawakkalooo in kuntum mu\'mineen','page_number'=>111,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>24,'arabic_text'=>'قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ','transliteration'=>'Qaaloo yaa-Moosaaa innaa lan nad-khulahaa aba-dam maa daamoo feehaa fazhab anta Wa-Rabbuka faqaa-tilaaa innaa haa-hunaa qaa\'idoon','page_number'=>112,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>25,'arabic_text'=>'قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ','transliteration'=>'Qaala Rabbi innee laaa amliku illaa nafsee Wa-akhee fafruq bainanaa Wa-bainal qawmil faasiqeen','page_number'=>112,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>26,'arabic_text'=>'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ','transliteration'=>'Qaala fa-innahaa muhar-ramatun \'alaihim arba\'eena sanah(taien); yateehoona fil ard; falaa ta-sa \'alal qawmil faasiqeen','page_number'=>112,'juz_number'=>6,'hizb_number'=>11,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>27,'arabic_text'=>'۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ','transliteration'=>'Watlu \'alaihim naba abnai Aadama bilhaqqi iz qarrabaa qurbaanan fatu-qubbila min ahadihimaa Wa-lam yutaqabbal minal aakhari qaala la-aqtu-lannaka qaala inna-maa yataqabbalul laahu minal muttaqeen','page_number'=>112,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>28,'arabic_text'=>'لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ','transliteration'=>'La\'im basatta ilaiyya yadaka litaq-tulanee maa ana bi-baasitien yadiya ilaika li-aqtulak(a) innee akhaaful laaha Rabbal \'aalameen','page_number'=>112,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>29,'arabic_text'=>'إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ','transliteration'=>'Inee ureedu an tabooo\'a bi-ismee Wa-ismika fatakoona min As-haabin Naar; Wa-zaalika jazaaa\'uz zaalimeen','page_number'=>112,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>30,'arabic_text'=>'فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Fatawwa\'at lahoo nafsu-hoo qatla akheehi faqatalahoo fa-asbaha minal khaasireen','page_number'=>112,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>31,'arabic_text'=>'فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّٰدِمِينَ','transliteration'=>'Faba\'asal laahu ghuraabaien yab-hasu fil ardi liyuriyahoo kaifa yuwaaree saw\'ata akheeh; qaala yaa-wailata-aa a\'ajaztu an akoona misla haazal ghuraabi fa-uwaariya saw-ata akhee fa-asbaha minan naadimeen','page_number'=>112,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>32,'arabic_text'=>'مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ','transliteration'=>'Min ajli zaalika katabnaa \'alaa Banee Israaa\'eela annahoo man qatala nafsam bighairi nafsin aw fasaadin fil ardi faka-annammaa qatalan naasa jamee\'a(nw) Wa-man ahyaahaa faka-annamaaa ahyan naasa jamee\'aa; Wa-laqad jaaa\'at-hum Rusulunaa bil-baiyyinaati summa inna kaseeram minhum ba\'da zaalika fil ardi la-musrifoon','page_number'=>113,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>33,'arabic_text'=>'إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ','transliteration'=>'Innamaa jazaaa\'ul lazeena yuhaariboonal laaha Wa-Rasoolahoo Wa-yas\'awna fil ardi fasaadan aien yuqattalooo aw yusallabooo aw tuqatta\'a aideehim Wa-arjuluhum min khilaafin aw yunfaw minal ard; zaalika lahum khizyun fid dunyaa Wa-lahum fil Aakhirati \'azaabun \'azeem','page_number'=>113,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>34,'arabic_text'=>'إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Illal lazeena taaboo min qabli an taqdiroo \'alaihim fa\'lamooo annnal laaha Ghafoorur Raheem','page_number'=>113,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>35,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanut taqul laaha wabtaghooo ilaihil waseelata Wa-jaahidoo fee sabeelihee la\'allakum tuflihoon','page_number'=>113,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>36,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Innal lazeena kafaroo law anna lahum maa fil ardi jamee\'anw Wa-mislahoo ma\'ahoo liyaftadoo bihee min \'azaabi Yawmil Qiyaamati maa tuqubbila minhum Wa-lahum azaabun aleem','page_number'=>113,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>37,'arabic_text'=>'يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ','transliteration'=>'Yureedoona aien yakhrujoo minan Naari Wa-maa hum bikhaari-jeena minhaa Wa-lahum \'azaabum muqeem','page_number'=>114,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>38,'arabic_text'=>'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wassaariqu wassaariqatu faqta\'oo aidi-yahumaa jazaaa\'am bimaa kasabaa nakaalam minal laah; wallaahu \'Azeezun hakeem','page_number'=>114,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>39,'arabic_text'=>'فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Faman taaba mim ba\'di zulmihee Wa-aslaha fa-innal laaha yatoobu \'alaih; innal laaha Ghafoorur Raheem','page_number'=>114,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>40,'arabic_text'=>'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Alam ta\'lam annal laaha lahoo mulkus samaawaati wal-ardi yu\'az-zibu maien yashaa\'u Wa-yaghfiru li-maien yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer','page_number'=>114,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>41,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّٰعُونَ لِلۡكَذِبِ سَمَّٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ','transliteration'=>'Yaaa-ayyuhar Rasoolu laa yahzunkal lazeena yusaa-ri\'oona fil kufri minal lazeena qaaloo aamannaa bi-afwaa-hi-him Wa-lam tu\'min quloobuhum; Wa-minal lazeena haadoo sammaa\'oona lil-kazibi sammaa\'oona liqawmin aakhareena lam ya\'tooka yuharri-foonal kalima mim ba\'di mawaadi\'ihee yaqooloona in ooteetum haazaa fakhuzoohu Wa-il lam tu\'tawhu fah-zaroo; Wa-maien yuridil laahu fitna-tahoo falan tamlika lahoo minal laahi shai\'aa; ulaaa-\'ikal lazeena lam yuridil laahu aien yutahhira quloobahum; lahum fid dunyaa khizyunw Wa-lahum fil Aakhirati azaabun \'azeem','page_number'=>114,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>42,'arabic_text'=>'سَمَّٰعُونَ لِلۡكَذِبِ أَكَّٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ','transliteration'=>'Sammaa\'oona lilkazibi akkaaloona lis-suht; fa-in jaaa\'ooka fahkum bainahum aw a\'rid anhum Wa-in tu\'rid \'anhum falaien yadurrooka shai-a(nw) Wa-in hakamta fahkum bainahum bilqist; innal laaha yuhibbul muqsiteen','page_number'=>115,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>43,'arabic_text'=>'وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-kaifa yuhakki-moonaka Wa-\'inda-humut Tawraatu feehaa hukmul laahi summa yatawallawna mim ba\'di zaalik; Wa-maaa ulaaa\'ika bilmu\'mineen','page_number'=>115,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>44,'arabic_text'=>'إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ','transliteration'=>'Innaaa anzalnat Tawraata feehaa hudanw Wa-noor(uien); yahkumu bihan Nabiyyoonal lazeena aslamoo lillazeena haadoo war-rabbaaniyyoona wal-ahbaaru bimas tuhfizoo min Kitaabil laahi Wa-kaanoo \'alaihi shuhadaaa\'; falaa takhshawun naasa wakhshawni Wa-laa tashtaroo bi-aayaatee samanan qaleelaa; Wa-mal lam yahkum bimaaa anzalal laahu fa-ulaaa\'ika humul kaafiroon','page_number'=>115,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>45,'arabic_text'=>'وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Wa-katabnaa \'alaihim feehaaa annan nafsa binnafsi wal\'aina bil\'aini wal-anfa bilanfi wal-uzuna bil-uzuni wassinna bissinni waljurooha qisaas; faman tasaddaqa bihee fahuwa kaffaaratul lah; Wa-mal lam yahkum bimaaa anzalal laahu fa-ulaaa\'ika humuz zalimoon','page_number'=>115,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>46,'arabic_text'=>'وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ','transliteration'=>'Wa-qaffainaa \'alaaa aasaaarihim bi-\'Eesab ni Maryama musaddiqal limaa baina yadaihi minat Tawraati Wa-aatainaahul Injeela feehi hudanw Wa-noorunw Wa-musaddiqal limaa baina yadaihi minat Tawraati Wa-hudanw Wa-maw\'izatal lilmuttaqeen','page_number'=>116,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>47,'arabic_text'=>'وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Walyahkum Ahlul Injeeli bimaaa anzalal laahu feeh; Wa-mal lam yahkum bimaaa anzalal laahu fa-ulaaa\'ika humul faasiqoon','page_number'=>116,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>48,'arabic_text'=>'وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','transliteration'=>'Wa-anzalnaa ilaikal Kitaaba bilhaqqi musaddiqal limaa baina yadaihi minal Kitaabi Wa-muhaiminan \'alaihi fahkum bainahum bimaa anzalal laahu Wa-laa tattabi\' ahwaaa\'ahum \'ammaa jaaa\'aka minal haqq; likullin ja\'alnaa minkum shir\'atanw Wa-minhaajaa; Wa-law shaaa\'al laahu laja\'alakum ummatanw waahidatanw Wa-laakil liyabluwakum fee maa aataakum fastabiqul khairaat; ilal laahi marji\'ukum jamee\'an fa-yunab-bi\'ukum bimaa kuntum feehi takhtalifoon','page_number'=>116,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>49,'arabic_text'=>'وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ','transliteration'=>'Wa-anih kum bainahum bimaaa anzalal laahu Wa-laa tattabi\' ahwaaa\'ahum wahzarhum aien yaftinooka \'am ba\'di maaa anzalal laahu ilaika fa-in tawallaw fa\'lam annamaa yureedul laahu aien yuseebahum biba\'di zunoobihim; Wa-inna kaseeram minan naasi lafaasiqoon','page_number'=>116,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>50,'arabic_text'=>'أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ','transliteration'=>'Afahukmal jaahiliyyati yabghoon; Wa-man ahsanu minal laahi hukmal liqawmien yooqinoon','page_number'=>116,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>51,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tattakhizul Yahooda wan-nasaaraaa awliyaaa\'; ba\'duhum awliyaaa\'u ba\'d; Wa-main yatawallahum minkum fa-innahoo minhum; innal laaha laa yahdil qawmaz zaalimeen','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>52,'arabic_text'=>'فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ','transliteration'=>'Fataral lazeena fee quloobihim maraduien yusaari\'oona feehim yaqooloona nakhshaaa an tuseebanaa daaa\'irah; fa\'asal laahu aien ya-tiya bilfathi aw amrim min \'indihee fa-yusbihoo \'alaa maaa asarroo feee anfusihim naadimeen','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>53,'arabic_text'=>'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ','transliteration'=>'Wa-yaqoolul lazeena aamanooo ahaaa\'ulaaa\'il lazeena aqsamoo billaahi jahda aimaanihim innahum lama\'akum; habitat a\'maaluhum fa-asbahoo khaasireen','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>54,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','transliteration'=>'Yaa-aiyyuhal lazeena aamanoo maien yartadda minkum \'an deenihee fasawfa ya\'til laahu biqawmien yuhibbuhum Wa-yuhibboonahoo azillatin \'alal mu\'mineena a\'izzatin \'alal kaafireena yujaahidoona fee sabeelil laahi Wa-laa yakhaafoona lawmata laaa\'im; zaalika fadlul laahi yu\'teehi maien yashaaa\'; wallaahu Waasi\'un \'Aleem','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>55,'arabic_text'=>'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ','transliteration'=>'Innamaa waliyyukumul laahu Wa-Rasooluhoo wal-lazeena aamanul lazeena yuqeemoonas Salaata Wa-yu\'toonaz Zakaata Wa-hum raaki\'oon','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>56,'arabic_text'=>'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ','transliteration'=>'Wa-maien yatawallal laaha Wa-Rasoolahoo wallazeena aamanoo fa-inna hizbal laahi humul ghaaliboon','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>57,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tattakhizul lazeenat takhazoo deenakum huzuwanw Wa-la\'ibam minal lazeena ootul Kitaaba min qablikum walkuffaara awliyaaa\'; wattaqul laaha in kuntum muu\'mineen','page_number'=>117,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>58,'arabic_text'=>'وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ','transliteration'=>'Wa-izaa naadaitum ilas Salaatit takhazoohaa huzu-wan\'w Wa-la\'ibaa; zaalika biannahum qawmul laa ya\'qiloon','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>59,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ','transliteration'=>'Qul yaaa-Ahlal Kitaabi hal tanqimoona minnaaa illaaa an aamannaa billaahi Wa-maaa unzila ilainaa Wa-maa unzila min qablu Wa-anna aksarakum faasiqoon','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>60,'arabic_text'=>'قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ','transliteration'=>'Qul hal unabbi\'ukum bisharrim min zaalika masoobatan \'indal laah(i); mal la\'ana-hul laahu Wa-ghadiba \'alaihi Wa-ja\'ala min-humul qiradata wal-khanaazeera Wa-\'abadat Taaghoot; ulaaa\'ika sharrum makaananw Wa-adallu \'an Sawaaa\'is Sabeel','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>61,'arabic_text'=>'وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ','transliteration'=>'Wa-izaa jaaa\'ookum qaalooo aamannaa Wa-qad dakhaloo bilkufri Wa-hum qad kharajoo bih; wallaahu a\'lamu bimaa kaanoo yaktumoon','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>62,'arabic_text'=>'وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-taraa kaseeram minhum yusaari\'oona fil ismi wal\'udwaani Wa-aklihimus suht; labi\'sa maa kaanoo ya\'maloon','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>63,'arabic_text'=>'لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ','transliteration'=>'Law-laa yanhaahumur rabbaaniyyoona wal-ahbaaru \'an qawlihimul ismaa Wa-aklihimus suht; labi\'sa maa kaanoo yasna\'oon','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>64,'arabic_text'=>'وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ','transliteration'=>'Wa-qaalatil Yahoodu Yadul laahi maghloolah; ghullat aideehim Wa-lu\'inoo bimaa qaaloo; bal yadaahu mabsoo-tataani yunfiqu kaifa yashaaa\'; Wa-la-yazeedanna kaseeramm minhum maaa unzila ilaika mir Rabbika tughyaananw Wa-kufraa; Wa-alqainaa bainahumul \'adaawata wal-baghdaaa a\'-ilaa Yawmil Qiyaamah; kullamaaa awqadoo naaral lilharbi at-fa-ahal laah; Wa-yas\'awna fil ardi fasaadaa(nw); wal-laahu laa yuhibbul mufsideen','page_number'=>118,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>65,'arabic_text'=>'وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّٰتِ ٱلنَّعِيمِ','transliteration'=>'Wa-law anna Ahlal Kitaabi aamanoo wattaqaw lakaffarnaa \'anhum saiyiaatihim Wa-la-adkhalnaahum Jannaatin Na\'eem','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>66,'arabic_text'=>'وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ','transliteration'=>'Wa-law annahum aqaamut Tawraata wal-Injeela Wa-maaa unzila ilaihim mir Rabbihim la-akaloo min fawqihim Wa-min tahti arjulihim; minhum ummatum muqta-sida(tunw) Wa-kaseerum minhum saaa\'a maa ya\'maloon','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>67,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','transliteration'=>'Yaaa-aiyyuhar Rasoolu balligh maaa unzila ilaika mir Rabbika Wa-il lam taf\'al famaaa ballaghta Risaalatah; wallaahu ya\'simuka minan naas; innal laaha laa yahdil qawmal kaafireen','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>68,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','transliteration'=>'Qul yaaa-Ahlal Kitaabi lastum \'alaa shai\'in hattaa tuqeemut Tawraata wal-Injeela Wa-maaa unzila ilaikum mir Rabbikum; Wa-layazeedanna kaseeram minhum maa unzila ilaika mir Rabbika tugh-yaananw Wa-kufra(n) falaa taasa \'alal qawmil kaafireen','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>69,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Innal lazeena aamanoo wallazeena haadoo was-saabi\'oona wan-Nasaaraa man aamana billaahi wal-yawmil Aakhiri Wa-\'amila saalihan falaa khawfun \'alaihim Wa-laa hum yahzanoon','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>70,'arabic_text'=>'لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ','transliteration'=>'Laqad akhaznaa meesaaqa Banee Israaa\'eela Wa-arsalnaaa ilaihim Rusula(n) kullamaa jaaa\'ahum Rasoolum bimaa laa tahwaaa anfusuhum fareeqan kazzaboo Wa-fareeqaien yaqtuloon','page_number'=>119,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>71,'arabic_text'=>'وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ','transliteration'=>'Wa-hasibooo allaa takoona fitnatun fa\'amoo Wa-sammoo summa taabal laahu \'alaihim summa \'amoo Wa-sammoo kaseerum minhum; wallaahu baseerum bimaa ya\'maloon','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>72,'arabic_text'=>'لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ','transliteration'=>'Laqad kafaral lazeena qaalooo innal laaha Huwal maseehub nu Maryama Wa-qaalal Maseehu yaa-Baneee Israaa\'eela u\'budul laaha Rabbee Wa-Rabbakum innahoo maien yushrik billaahi faqad harramal laahu \'alaihil janna(ta) Wa-ma-waahun Naar(u) Wa-maa lizzaalimeena min ansaar','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>73,'arabic_text'=>'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ','transliteration'=>'laqad kafaral lazeena qaalooo innal laaha saalisu salaasah; Wa-maa min ilaahin illaaa Ilaahunw Waahid; Wa-il lam yantahoo \'ammaa yaqooloona layamas-sannal lazeena kafaroo minhum \'azaabun aleem','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>74,'arabic_text'=>'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Afalaa yatooboona ilal laahi Wa-yastaghfiroonahu; wallaahu Ghafoorur Raheem','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>75,'arabic_text'=>'مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ','transliteration'=>'Mal Maseehub nu Maryama illaa Rasoolun qad khalat min qablihir Rusulu Wa-ummuhoo siddeeqatun kaanaa yaa-kulaanit ta\'aam; unzur kaifa nubaiyyinu lahumul Aayaati suman zur annaa yu\'fakoon','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>76,'arabic_text'=>'قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Qul ata\'budoona min doonil laahi maa laa yamliku lakum darranw Wa-laa naf\'aa; wallaahu Huwas Samee\'ul \'Aleem','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>77,'arabic_text'=>'قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ','transliteration'=>'Qul yaaa-Ahlal Kitaabi laa taghloo fee deenikum ghairal haqq(i) Wa-laa tattabi\'ooo ahwaaa\'a qawmin qad dalloo min qablu Wa-adalloo kaseeranw Wa-dalloo \'an Sawaaa\'is Sabeel','page_number'=>120,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>78,'arabic_text'=>'لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ','transliteration'=>'Lu\'inal lazeena kafaroo mim Baneee israa\'eela \'alaa lisaani Daawooda Wa-\'Eesab ni Maryam; zaalika bimaa \'asaw Wa-kaanoo ya\'tadoon','page_number'=>121,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>79,'arabic_text'=>'كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ','transliteration'=>'Kaanoo laa yatanaa-hawna \'am munkarin fa\'alooh; labi\'sa maa kaanoo yafa\'loon','page_number'=>121,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>80,'arabic_text'=>'تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ','transliteration'=>'Taraa kaseeram minhum yatawallawnal lazeena kafaroo; labi\'sa maa qaddamat lahum anfusuhum an sakhital laahu \'alaihim Wa-fil \'azaabi hum khaalidoon','page_number'=>121,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>81,'arabic_text'=>'وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ','transliteration'=>'Wa-law kaanoo yu\'minoona billaahi wan-nabiyyi Wa-maa unzila ilaihi mat takhazoohum awliyaaa\'a Wa-laakinna kaseeram minhum faasiqoon','page_number'=>121,'juz_number'=>6,'hizb_number'=>12,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>82,'arabic_text'=>'۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ','transliteration'=>'Latajidanna ashad-dan naasi \'adaawatal lillazeena aamanul Yahooda wallazeena ashrakoo Wa-latajidanna aqrabahum mawaddatal lil-lazeena aamanul lazeena qaalooo innaa Nasaaraa; zaalika bi-anna minhum qiseeseena Wa-ruh-baananw Wa-annahum laa yastakbiroon','page_number'=>121,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>83,'arabic_text'=>'وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ','transliteration'=>'Wa-izaa sami\'oo maa unzila ilar Rasooli taraa a\'yunahum tafeedu minad dam\'i mimmaa \'arafoo minal haqq; yaqooloona Rabbanaa aamannaa faktubnaa ma\'ash shaahideen','page_number'=>121,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>84,'arabic_text'=>'وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-maa lanaa laa nu\'minu billaahi Wa-maa jaaa\'anaa minal haqqi Wa-natma\'u aien yudkhilanaa Rabbunaa ma\'al qawmis saaliheen','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>85,'arabic_text'=>'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ','transliteration'=>'Fa-asaabahumul laahu bimaa qaaloo Jannaatin tajree min tahtihal anhaar(u) khaalideena feehaa; Wa-zaalika jazaaa\'ul muhsineen','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>86,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','transliteration'=>'Wallazeena kafaroo Wa-kazzaboo bi-Aayaatinaa ulaaa\'ika As-haabul Jaheem','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>87,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ','transliteration'=>'Yaa-aiyyuhal lazeena aamanoo laa tuharrimoo taiyyibaati maa ahallal laahu lakum Wa-laa ta\'tadooo; innal laaha laa yuhibbul mu\'tadeen','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>88,'arabic_text'=>'وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ','transliteration'=>'Wa-kuloo mimmaa raza-qakumul laahu halaalan taiyyibaa; wattaqul laahal lazeee antum bihee mu\'minoon','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>89,'arabic_text'=>'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Laa yu\'aakhizukumul laahu billaghwi fee aimaanikum Wa-laakien yu\'aakhizukum bimaa \'aqqattumul aimaan(a) fakaf-faaratuhoo it\'aamu \'asharati masaakeena min awsati maa tut\'imoona ahleekum aw kiswatuhum aw tahreeru raqaba(tin) famal lam yajid fa-Siyaamu salaasati aiy-yaam; zaalika kaffaaratu aimaanikum izaa halaftum; wahfazooo aimaanakum; kazaalika yubaiyyinul laahu lakum Aayaatihee la\'allakum tashkuroon','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>90,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanooo innamal khamru walmaisiru wal-ansaabu wal-azlaamu rijsum min \'amalish shaitaani fajtaniboohu la\'al-lakum tuflihoon','page_number'=>122,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>91,'arabic_text'=>'إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ','transliteration'=>'Innamaa yureedush Shaitaanu aien yooqi\'a bainakumul \'adaawata wal-baghdaaa\'a fil khamri wal-maisir(i) Wa-yasuddakum \'an zikril laahi Wa-\'anis Salaati fahal antum muntahoon','page_number'=>123,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>92,'arabic_text'=>'وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Wa-atee\'ul laaha Wa-atee\'ur Rasoola wahzaroo; fa-in tawal-laitum fa\'lamooo annamaa \'alaa Rasoolinal balaaghul mubeen','page_number'=>123,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>93,'arabic_text'=>'لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ','transliteration'=>'Laisa \'alal lazeena aamanoo Wa-\'amilus saalihaati junaahun feemaa ta\'imooo izaa mat taqaw Wa-aamanoo Wa-\'amilus saalihaati summat taqaw Wa-aamanoo summat taqaw Wa-ahsanoo; wallaahu yuhibbul muhsineen','page_number'=>123,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>94,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ','transliteration'=>'Yaa-aiyyuhal lazeena aamanoo la-yablu-wanna-kumul laahu bishai\'im minas saidi tanaa-luhooo aideekum Wa-rimaahukum liya\'lamal laahu maien yakhaafuhoo bilghaib; famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem','page_number'=>123,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>95,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ','transliteration'=>'Yaa-aiyyuhal lazeena aamanoo laa taqtulus saida Wa-antum hurum; Wa-man qatalahoo minkum mut\'am-midan fajazaaa\'um mislu maa qatala minan na\'am(i) yahkumu bihee zawaa \'adlim minkum hadyam baalighal Ka\'ba(ti) aw kaffaaratun ta\'aamu masaakeena aw \'adlu zaalika Siyaamal liyazooqa wabaala amrih; \'afal laahu \'ammaa salaf; Wa-man \'aada fayanta-qimul laahu minh; wallaahu \'azeezun zun tiqaam','page_number'=>123,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>96,'arabic_text'=>'أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Uhilla lakum saidul bahri Wa-ta\'aamuhoo mataa\'al lakum Wa-lis-saiyyaara(ti) Wa-hurrima \'alaikum saidul barri maa dumtum hurumaa; wattaqul laahal lazeee ilaihi tuh-sharoon','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>97,'arabic_text'=>'۞ جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ','transliteration'=>'Ja\'alal laahul Ka\'batal Baital Haraama qiyaamal linnaasi wash-Shahral Haraama wal-hadya wal-qalaaa\'id; zaalika lita\'lamooo annal laaha ya\'lamu maa fis samaawaati Wa-maa fil ardi Wa-annal laaha bikulli shai\'in \'Aleem','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>98,'arabic_text'=>'ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'I\'lamooo annal laaha shadeedul \'iqaabi Wa-annal laaha Ghafoorur Raheem','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>99,'arabic_text'=>'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ','transliteration'=>'Maa \'alar Rasooli illal balaaghu; wallaahu ya\'lamu maa tubdoona Wa-maa taktumoon','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>100,'arabic_text'=>'قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Qul laa yastawil khabeesu wattaiyyibu Wa-law a\'jabaka kasratul khabees; fattaqul laaha yaaa-ulil albaabi la\'allakum tuflihoon','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>101,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tas\'aloo \'an ashyaaa\'a in tubda lakum tasu\'kum Wa-in tas\'aloo \'anhaa heena yunazzalul Qur\'aanu tubda lakum; \'afal laahu \'anhaa; wallaahu Ghafoorun Haleem','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>102,'arabic_text'=>'قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ','transliteration'=>'Qad sa-alahaa qawmum min qablikum summa asbahoo bihaa kaafireen','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>103,'arabic_text'=>'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ','transliteration'=>'Maa ja\'alal laahu mim baheeratinw Wa-laa saaa\'ibatinw Wa-laa waseelatinw Wa-laa haaminw Wa-laakinnal lazeena kafaroo yaftaroona \'alal laahil kazib; Wa-aksaruhum laa ya\'qiloon','page_number'=>124,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>104,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ','transliteration'=>'Wa-izaa qeela lahum ta\'aalaw ilaa maaa anzalal laahu Wa-ilar Rasooli qaaloo hasbunaa maa wajadnaa \'alaihi aabaaa\'anaa; awa-law kaana aabaaa\'uhum laa ya\'lamoona shai\'anw Wa-laa yahtadoon','page_number'=>125,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>105,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo \'alaikum anfusakum laa yadurrukum man dalla izah tadaitum; ilal laahi marji\'ukum jamee\'an fayunabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>125,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>106,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo shahaadatu bainikum izaa hadara ahadakumul mawtu heenal wasiyyatis naani zawaa \'adlim minkum aw aakharaani min ghairikum in antum darabtum fil ardi fa-asaabatkum museebatul mawt; tahbi-soonahumaa mim ba\'dis Salaati fa-yuqsimaani billaahi inir tabtum laa nashtaree bihee samananw Wa-law kaana zaa qurbaa Wa-laa naktumu shahaadatal laahi innaaa izal laminal aasimeen','page_number'=>125,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>107,'arabic_text'=>'فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Fa-in \'usira \'alaaa annahumas tahaqqaaa isman fa-aakharaani yaqoomaani maqaama-humaa minal lazeenas tahaqqa \'alaihimul aw-layaani fa-yuqsimaani billaahi lashahaadatunaaa ahaqqu min shahaadati-himaaa Wa-ma\' tadainaaa innaaa izal laminaz zaalimeen','page_number'=>125,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>108,'arabic_text'=>'ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ','transliteration'=>'Zaalika adnaaa aien ya\'too bishshahaadati \'alaa wajhi-haaa aw yakhaafooo an turadda aimaanum ba\'da aimaanihim; wattaqul laaha wasma\'oo; wallaahu laa yahdil qawmal faasiqeen','page_number'=>125,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>109,'arabic_text'=>'۞ يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ','transliteration'=>'Yawma yajma\'ul laahur Rusula fa-yaqoolu maazaaa ujibtum qaaloo laa \'ilma lanaa innaka Anta \'Allaamul Ghuyoob','page_number'=>126,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>110,'arabic_text'=>'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ','transliteration'=>'Iz qaalal laahu yaa-\'Eesab na Maryamaz kur ni\'matee \'alaika Wa-\'alaa waalidatika; iz aiyyattuka bi-Roohil Qudus(i) tukallimun naasa fil mahdi Wa-kahla(nw) Wa-iz \'allamtukal kitaaba wal-Hikmata Wa-Tawraata wal-Injeel(a) Wa-iz takhluqu minat teeni kahai-\'atit tairi bi-iznee fatan-fukhu feeha fatakoonu tairam bi-iznee Wa-tubri\'ul akmaha wal-abrasa bi-iznee Wa-iz tukhrijul mawtaa bi-iznee Wa-iz kafaftu Baneee Israaa\'eela \'anka iz ji\'tahum bil-baiyyinaati fa-qaalal lazeena kafaroo minhum in haazaaa illaa sihrum mubeen','page_number'=>126,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>111,'arabic_text'=>'وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ','transliteration'=>'Wa-iz aw-haitu ilal hawaariy-yeena an aaminoo bee Wa-bi-Rasoolee qaalooo aamannaa wash-had bi-anna-naa muslimoon','page_number'=>126,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>112,'arabic_text'=>'إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Iz qaalal hawaariy-yoona yaa-\'Eesab na Maryama hal yastatee\'u Rabbuka aien yunaz-zila alainna maaa\'idatam minas samaaa\'(i) qaalat taqul laaha in kuntum mu\'mineen','page_number'=>126,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>113,'arabic_text'=>'قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّٰهِدِينَ','transliteration'=>'Qaaloo nureedu an na-kula minhaa Wa-tatama-\'inna quloo-bunaa Wa-na\'lama an qad sadaqtana Wa-nakoona \'alaihaa minash shaahideen','page_number'=>126,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>114,'arabic_text'=>'قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ','transliteration'=>'Qaala \'Eesab nu Maryamal laahumma Rabbanaaa anzil \'alainaa maaa\'idatam minas samaaa\'(i) takoonu lanaa \'eedal li-awwalinaa Wa-aakhirinaa Wa-Aayatam minka warzuqnaa Wa-Anta khairur raaziqeen','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>115,'arabic_text'=>'قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaalal laahu innee munaz-ziluhaa \'alaikum famaien yakfur ba\'du minkum fa-inneee u\'azzibuhoo \'azaabal laaa u\'azzibuhooo ahadam minal \'aalameen','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>116,'arabic_text'=>'وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ','transliteration'=>'Wa-iz qaalal laahu yaa-\'Eesab na Maryama \'a-anta qulta linnaasit takhizoonee Wa-ummiya ilaahaini min doonil laahi qaala Subhaanak(a) maa yakkoonu leee an aqoola maa laisa lee bihaqq; in kuntu qultuhoo faqad \'alimtah; ta\'lamu maa fee nafsee Wa-laaa a\'alamu maa fee nafsika; innaka Anta \'Allaamul Ghuyoob','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>117,'arabic_text'=>'مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ','transliteration'=>'Maa qultu lahum illaa maaa amartanee bihee ani\' budul laaha Rabbeee Wa-Rabbakum; Wa-kuntu \'alaihim shaheedam maa dumtu feehim falammaa tawaffai-tanee kunta Antar Raqeeba \'alaihim; Wa-Anta \'alaa kulli shai\'in Shaheed','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>118,'arabic_text'=>'إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'In tu\'azzibhum fa-innahum ibaaduka Wa-in taghfir lahum fa-innaka Antal \'Azzezul Hakeem','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>119,'arabic_text'=>'قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Qaalal laahu haaza yawmu yanfa\'us saadiqeena sidquhum; lahum janaatunn tajree min tah-tihal anhaaru khaalideena feehaaa abadaa; radiyal laahu \'anhum Wa-radoo \'anh; zaalikal fawzul \'azeem','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>5,'ayah_number'=>120,'arabic_text'=>'لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ','transliteration'=>'Lillaahi mulkus samaawaati wal-ardi Wa-maa feehinn; Wa-Huwa \'alaa kulli shai\'inn Qadeer','page_number'=>127,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            /* Surah 6: The Cattle (Al-An'am) */
            ['surah_id'=>6,'ayah_number'=>1,'arabic_text'=>'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ','transliteration'=>'Alhamdu lillaahil lazee khalaqas samaawaati wal-arda Wa-ja\'alaz zulumaati wannoor(a); summal lazeena kafaroo bi-Rabbihim ya\'diloon','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>2,'arabic_text'=>'هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ','transliteration'=>'Huwal lazee khalaqakum min teenin summa qadaaa ajalanw Wa-ajalum musamman \'indah(u) summa antum tamtaroon','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>3,'arabic_text'=>'وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ','transliteration'=>'Wa-Huwal laahu fis samaawaati Wa-fil ardi ya\'lamu sirrakum Wa-jahrakum Wa-ya\'lamu maa taksiboon','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>4,'arabic_text'=>'وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ','transliteration'=>'Wa-maa ta\'teehim min Aayatim min Aayaati Rabbihim illaa kaanoo \'anhaa mu\'rideen','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>5,'arabic_text'=>'فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Faqad kazzaboo bilhaqqi lammaa jaaa\'ahum fasawfa ya\'teehim ambaaa\'u maa kaanoo bihee yas-tahzi\'oon','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>6,'arabic_text'=>'أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ','transliteration'=>'Alam yarau kam ahlaknaa min qablihim min qarnim makkannaahum fil ardi maa lam numakkil lakum Wa-arsalnas samaaa\'a \'alaihim midraara(nw) Wa-ja\'alnal anhaara tajree min tah-tihim fa-ahlak-naahum bizunoobihim Wa-ansha\'naa mim ba\'dihim qarnan aakhareen','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>7,'arabic_text'=>'وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ','transliteration'=>'Wa-lau nazzalnaa \'alaika Kitaaban fee qirtaasin falama-soohu bi-aideehim laqaalal lazeena kafarooo in haazaaa illaa sihrum mubeen','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>8,'arabic_text'=>'وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ','transliteration'=>'Wa-qaaloo lau-laaa unzila alaihi malak(unw) Wa-lau anzalna malakal laqudiyal amru summa laa yunzaroon','page_number'=>128,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>9,'arabic_text'=>'وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ','transliteration'=>'Wa-lau ja\'alnaahu malakal laja\'alnaahu rajulanw Wa-la-labasnaa \'alaihim maa yalbisoon','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>10,'arabic_text'=>'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-laqadis tuhzi\'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi\'oon','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>11,'arabic_text'=>'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ','transliteration'=>'Qul seeroo fil ardi summan zuroo kaifa kaana \'aaqibatul mukazzibeen','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>12,'arabic_text'=>'قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Qul limam maa fis samaawaati wal-ardi qul lillaah; kataba \'alaa nafsihir rahmah; la-yajma-\'annakum ilaa Yawmil Qiyaamati laa raiba feeh; allazeena khasirooo an-fusahum fahum laa yu\'minoon','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>13,'arabic_text'=>'۞ وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-lahoo maa sakana fil lai-li wan-nahaari; Wa-Huwas Samee\'ul Aleem','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>14,'arabic_text'=>'قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Qul aghairal laahi attakhizu waliyyan faatiris samaawaati wal-ardi Wa-Huwa yut\'imu Wa-laa yut\'am; qul inneee umirtu an akoona awwala man aslama Wa-laa takoo-nanna minal mushrikeen','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>15,'arabic_text'=>'قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ','transliteration'=>'Qul inneee akhaafu in \'asaitu Rabbee \'azaaba Yawmin \'Azeem','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>16,'arabic_text'=>'مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ','transliteration'=>'Maien yusraf \'anhu Yawma\'izin faqad rahimahu; Wa-zaalikal fawzul mubeen','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>17,'arabic_text'=>'وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wa-ien yum-saskal laahu bidurrin falaaa kaashifa lahoo illaa Huw(a) Wa-ien yum-saska bikhairin fa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>18,'arabic_text'=>'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ','transliteration'=>'Wa-Huwal qaahiru fauqa \'ibaadihi; Wa-Huwal Hakeemul Khabeer','page_number'=>129,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>19,'arabic_text'=>'قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ','transliteration'=>'Qul ayyu shai\'in akbaru shahaada(tan) qulil laahu shaheedum bainee Wa-bainakum; Wa-oohiya ilaiyya haazal Qur\'aanu li-unzirakum bihee Wa-mam balagh; a\'innakum latash-hadoona anna ma\'al laahi aalihatan ukhraa; qul laaa ashhad; qul innamaa Huwa Ilaahunw Waahidunw Wa-innanee bareeee\'um mimmaa tushrikoon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>20,'arabic_text'=>'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Allazeena aatainaa-humul Kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum; allazeena khasirooo an-fusahum fahum laa yu\'minoon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>21,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ','transliteration'=>'Wa-man azlamu mim-manif tara \'alal laahi kaziban aw kazzaba bi-Aayaatih; innahoo laa yuflihuz zaalimoon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>22,'arabic_text'=>'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ','transliteration'=>'Wa-yawma nah-shuruhum jamee\'an summa naqoolu lil-lazeena ashrakooo aina shura-kaaa\'ukumul lazeena kuntum taz\'umoon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>23,'arabic_text'=>'ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ','transliteration'=>'Summa lam takun fitna-tuhum illaaa an qaaloo wallaahi Rabbinaa maa kunnaa mushrikeen','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>24,'arabic_text'=>'ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Unzur kaifa kazaboo \'alaaa an-fusihim, Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>25,'arabic_text'=>'وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Wa-minhum maien yastami\'u ilaik(a) wa-ja\'alnaa \'alaa quloobihim akin-natan aien yafqa-hoohu wa-feee aazaa-nihim waqraa; wa-in yarau kulla Aayatil laa yu\'minoo bihaa; hattaaa izaa jaaa\'ooka yujaadi-loonaka yaqoolul lazeena kafaroo in haazaa illaaa asaateerul awwaleen','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>26,'arabic_text'=>'وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ','transliteration'=>'Wa-hum yan-hauna \'anhu wa-yan-awna \'anh(u) wa-ien yuh-likoona illaa an-fusahum wa-maa yash\'uroon','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>27,'arabic_text'=>'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-lau taraaa iz wuqifoo \'alan Naari faqaaloo yaa-laitanaa nuraddu wa-laa nukaz-ziba bi-Aayaati Rabbinaa wa-nakoona minal mu\'mineen','page_number'=>130,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>28,'arabic_text'=>'بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Bal badaa lahum maa kaanoo yukhfoona min qabl(u) wa-lau ruddoo la\'aadoo limaa nuhoo \'anhu wa-innahum la-kaaziboon','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>29,'arabic_text'=>'وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ','transliteration'=>'Wa-qaalooo in hiya illaa hayaa-tunad dunyaa wa-maa nahnu bimab\'ooseen','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>30,'arabic_text'=>'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ','transliteration'=>'Wa-lau taraa iz wuqifoo \'alaa Rabbihim; qaala alaisa haazaa bilhaqqi; qaaloo balaa wa-Rabbinaa; qaala fazooqul \'azaaba bimaa kuntum takfuroon','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>31,'arabic_text'=>'قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ','transliteration'=>'Qad khasiral lazeena kazzaboo bil-liqaaa\'il laah(i) hattaaa izaa jaaa\'at-humus Saa\'atu bagh-tatan qaaloo yaa-hasratanaa \'alaa maa farratnaa feehaa wa-hum yah-miloona awzaarahum \'alaa zuhoorihim; alaa saaa\'a ma yaziroon','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>32,'arabic_text'=>'وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Wa-mal hayaatud dunyaaa illaa la\'ibunw Wa-lah-wunw wa-lad-daarul Aakhiratu khairul lillazeena yattaqoon; afalaa ta\'qiloon','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>33,'arabic_text'=>'قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ','transliteration'=>'Qad na\'lamu innahoo layah-zunukal lazee yaqooloona fa-innahum laa yukazzi-bunaka wa-laakinnaz zaalimeena bi-Aayaatil laahi yaj-hadoon','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>34,'arabic_text'=>'وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ','transliteration'=>'Wa-laqad kuzzibat Rusulum min qablika fasabaroo \'alaa maa kuzziboo Wa-oozoo hattaaa ataahum nasrunaa; wa-laa mubaddila li-kalimaatil laah; wa-laqad jaaa\'aka min naba\'il mursaleen','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>35,'arabic_text'=>'وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ','transliteration'=>'Wa-in kaana kabura \'alaika i\'raaduhum fa-inis tata\'ta an tabtaghiya nafaqan fil ardi aw sullaman fis samaaa\'i fata\'tiyahum bi-Aayah; Wa-lau shaaa\'al laahu lajama\'ahum \'alal hudaa; falaa takoo-nanna minal jaahileen','page_number'=>131,'juz_number'=>7,'hizb_number'=>13,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>36,'arabic_text'=>'۞ إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ','transliteration'=>'Innamaa yastajeebul lazeena yasma\'oon; wal-mawtaa yab\'asu-humul laahu summa ilaihi yurja\'oon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>37,'arabic_text'=>'وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-qaaloo lau-laa nuzzila \'alaihi Aayatum mir Rabbih; qul innal laaha qaadirun \'alaaa aien yunazzila Aayatanw walaa-kinna aksarahum laa ya\'lamoon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>38,'arabic_text'=>'وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ','transliteration'=>'Wa-maa min daaab-batin fil ardi Wa-laa taaa\'irien yateeru bijanaa-haihi illaaa umamun amsaalukum; maa farratnaa fil Kitaabi min shaiyy\' summa ilaa Rabbihim yuh-sharoon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>39,'arabic_text'=>'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wallazeena kazzaboo bi-Aayaatinaa summunw wa-bukmun fiz zulumaat(i); maien yasha-il laahu yud-lilhu; wa-maien yashaa yaj\'alhu \'alaa Siraatim Mustaqeem','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>40,'arabic_text'=>'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Qul ara\'aitakum in ataakum \'azaabul laahi aw atat-kumus Saa\'a(tu) a-ghairal laahi tad\'oona in kuntum saadiqeen','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>41,'arabic_text'=>'بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ','transliteration'=>'Bal iyyaahu tad\'oona fa-yak-shifu maa tad\'oona ilaihi in shaaa\'a wa-tansauna maa tushrikoon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>42,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ','transliteration'=>'Wa-laqad arsalnaaa ilaaa umamim min qablika fa-akhaz-naahum bil-ba\'saaa\'i wad-darraaa\'i la\'allahum yata-darra\'oon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>43,'arabic_text'=>'فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Falau-laaa iz jaaa\'ahum ba\'sunaa tadarra\'oo wa-laakin qasat quloobuhum wa-zaiyyana lahu-mush Shaitaanu maa kaanu ya\'maloon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>44,'arabic_text'=>'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ','transliteration'=>'Falammaa nasoo maa zukkiroo bihee fatahnaa \'alaihim abwaaba kulli shai(in) hattaaa izaa farihoo bimaaa ootooo akhaz-naahum baghta(tan) fa-izaa hum mublisoon','page_number'=>132,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>45,'arabic_text'=>'فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Faquti\'a daa-birul qawmil lazeena zalamoo; walhamdu lillaahi Rabbil \'aalameen','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>46,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ','transliteration'=>'Qul ara\'aitum in akhazal laahu sam\'akum wa-absaarakum wa-khatama \'alaa quloobikum man ilaahun ghairul laahi ya\'teekum bih; unzur kaifa nusarriful Aayaati summa hum yasdifoon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>47,'arabic_text'=>'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّٰلِمُونَ','transliteration'=>'Qul ara\'aitakum in ataakum \'azaabul laahi baghtatan aw jahra(tan) hal yuhlaku illal qawmuz zaalimoon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>48,'arabic_text'=>'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Wa-maa nursilul mursaleena illaa mubash-shireena wa-munzireen(a) faman aamana wa-aslaha falaa khaufun \'alaihim wa-laa hum yahzanoon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>49,'arabic_text'=>'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ','transliteration'=>'Wallazeena kazzaboo bi-Aayaatinaa yamas-suhumul \'azaabu bimaa kaanu yaf-suqoon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>50,'arabic_text'=>'قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ','transliteration'=>'Qul laaa aqoolu lakum \'indee khazaaa\'inul laahi wa-laaa a\'lamul ghaiba wa-laaa aqoolu lakum innee malak(un) in attabi\'u illaa maa yuhaaa ilaiy; qul hal yastawil a\'maa wal-baseeru; afalaa tata-fakkaroon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>51,'arabic_text'=>'وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ','transliteration'=>'Wa-anzir bihil lazeena yakhaa-foona aien yuh-sharooo ilaa Rabbihim laisa lahum min doonihee waliy-yunw wa-laa shafee\'ul la\'allahum yattaqoon','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>52,'arabic_text'=>'وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-laa tatrudil lazeena yad\'oona Rabbahum bil-ghadaati wal-\'ashiyyi yureedoona waj-ha(hu) ma \'alaika min hisaa-bihim min shai(inw) wa-maa min hisaabika \'alaihim min shai(in) fatat-rudahum fatakoona minaz zaalimeen','page_number'=>133,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>53,'arabic_text'=>'وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ','transliteration'=>'Wa-kazaalika fatan-naa ba\'dahum biba\'dil liya-qulooo ahaaa-ulaaa-e mannal laahu \'alaihim mim bai-ninaa; alaisal laahu bi-a\'lama bish-shaakireen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>54,'arabic_text'=>'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-izaa jaaa\'akal lazeena yu\'minoona bi-Aayaatinaa faqul salaamun \'alaikum kataba Rabbukum \'alaa nafsi-hir rahmata annahu man \'amila minkum sooo\'am bijahaalatin summa taaba mim ba\'dihee wa-aslaha fa-annahoo Ghafoorur Raheem','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>55,'arabic_text'=>'وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ','transliteration'=>'Wa-kazaalika nufassilul Aayaati Wali-tastabeena sabeelul mujrimeen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>56,'arabic_text'=>'قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ','transliteration'=>'Qul innee nuheetu an a\'budal lazeena tad\'oona min doonil laah; qul laaa attabi\'u ahwaaa\'akum qad dalaltu izanw wa-maaa ana minal muhtadeen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>57,'arabic_text'=>'قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ','transliteration'=>'Qul innee \'alaa baiyyi-natim mir Rabbee wa-kazzabtum bih; maa \'indee maa tasta\'jiloona bih; inil hukmu illaa lillaah(i) yaqussul haqqa wa-huwa khairul faasileen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>58,'arabic_text'=>'قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّٰلِمِينَ','transliteration'=>'Qul lau anna \'indee maa tasta\'jiloona bihee laqudiyal amru bainee wa-bainakum; wallaahu a\'lamu biz-zaalimeen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>59,'arabic_text'=>'۞ وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ','transliteration'=>'Wa-\'indahoo mafaa-tihul ghaibi laa ya\'lamuhaaa illaa hu; wa-ya\'lamu maa fil barri wal-bahr; wa-maa tasqutu minw waraqatin illaa ya\'lamuhaa wa-laa habbatin fee zulumaatil ardi wa-laa ratbinw wa-laa yaabisin illaa fee Kitaabim Mubeen','page_number'=>134,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>60,'arabic_text'=>'وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-huwal lazee yatawaf-faakum billaili wa-ya\'lamu maa jarahtum bin-nahaar(i) summa yab\'asukum feehee liyuqdaaa ajalum musamma(n) summa ilaihi marji\'ukum summa yunabbi-\'ukum bimaa kuntum ta\'maloon','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>61,'arabic_text'=>'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ','transliteration'=>'Wa-huwal qaahiru fawqa \'ibaadihee wa-yursilu \'alaikum hafaza(tan) hattaaa izaa jaaa\'a ahadakumul mawtu tawaffathu rusulunaa wa-hum laa yufarritoon','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>62,'arabic_text'=>'ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ','transliteration'=>'Summa ruddooo ilal laahi maulaahumul haqq; alaa lahul hukmu wa-huwa asra\'ul haasibeen','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>63,'arabic_text'=>'قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ','transliteration'=>'Qul maien yunaj-jeekum min zulumaatil barri walbahri tad\'oonahoo tadarru\'anw wa-khufyatal la\'in anjaanaa min haazihee lanaku-nanna minash shaakireen','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>64,'arabic_text'=>'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ','transliteration'=>'Qulil laahu yunaj-jeekum minhaa wa-min kulli karbin summa antum tushrikoon','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>65,'arabic_text'=>'قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ','transliteration'=>'Qul huwal Qaadiru \'alaaa aien yab\'asa \'alaikum \'azaabam min fawqikum aw min tahti arjulikum aw yalbisakum shiya\'anw wa-yuzeeqa ba\'dakum ba\'sa ba\'d; unzur kaifa nusarriful Aayaati la\'allahum yafqahoon','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>66,'arabic_text'=>'وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ','transliteration'=>'Wa-kaz-zaba bihee qaumuka wa-huwal haqq; qul lastu \'alaikum biwakeel','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>67,'arabic_text'=>'لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ','transliteration'=>'Likulli naba-im mustaqar(runw) wa-saufa ta\'lamoon','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>68,'arabic_text'=>'وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-izaa ra-aital lazeena yakhoodoona fee Aayaatinaa fa-a\'rid \'anhum hattaa yakhudu fee hadeesin ghairih; wa-immaa yunsi-yannakash shaitaanu falaa taq\'ud ba\'daz zikraa ma\'al qawmiz zaalimeen','page_number'=>135,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>69,'arabic_text'=>'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ','transliteration'=>'Wa-maa \'alal lazeena yattaqoona min hisaa-bihim min shai\'inw wa-laakin zikraa la\'allahum yattaqoon','page_number'=>136,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>70,'arabic_text'=>'وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ','transliteration'=>'Wa-zaril lazeenat takhazoo deenahum la\'ibanw wa-lah-wanw Wa-gharrat-humul hayaatud dunyaa; wa-zakkir bihee an tubsala nafsum bimaa kasabat laisa lahaa min doonil laahi waliyyunw wa-laa shafee\'(unw) wa-in ta\'dil kulla \'adlil laa yu\'khaz minhaa; ulaaa-\'ikal lazeena ubsiloo bimaa kasaboo lahum sharaabum min hamee-minw wa-\'azaabun aleemum bimaa kaanu yakkfuroon','page_number'=>136,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>71,'arabic_text'=>'قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qul anad\'oo min doonil laahi maa laa yanfa\'unaa wa-laa yadur-runaa wa-nuraddu \'alaaa a\'qaabina ba\'da iz hadaanal laahu kal-lazis tahwat-hush shayaateenu fil ardi hairaana lahooo as-haa-buien yad\'oo-nahooo ilal huda\' tinaa; qul inna hudal laahi huwal hudaa wa-umirnaa linus-lima li-Rabbil \'aalameen','page_number'=>136,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>72,'arabic_text'=>'وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Wa-an aqeemus salaata wattaqoohu; wa-huwal lazeee ilaihi tuh-sharoon','page_number'=>136,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>73,'arabic_text'=>'وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ','transliteration'=>'Wa-huwal lazee khalaqas samaawaati wal-arda bilhaqq; Wa-Yawma yaqoolu kun fa-yakoon; Qawluhul haqqu; Wa-lahul mulku Yawma yunfakhu fis Soor; \'Aalimul Ghaibi wash-shahaadati; wa-huwal Hakeemul Khabeer','page_number'=>136,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>74,'arabic_text'=>'۞ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Wa-iz qaala Ibraaheemu li-abeehi Aazara atat-takhizu asnaa-man aaliha(tan) inneee araaka wa-qawmaka fee dalaalim mubeen','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>75,'arabic_text'=>'وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ','transliteration'=>'Wa-kazaalika nureee Ibraaheema malakootas samaawaati wal-ardi wa-liyakoona minal mooqineen','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>76,'arabic_text'=>'فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ','transliteration'=>'Falammaa janna \'alaihil lailu ra-aa kau-kaban qaala haaza Rabbee falammaaa afala qaala laaa uhibbul aafileen','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>77,'arabic_text'=>'فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ','transliteration'=>'Falammaa ra-al qamara baazighan qaala haazaa Rabbee falammaaa afala qaala la\'il lam yahdinee Rabbee la-akunanna minal qawmid daaalleen','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>78,'arabic_text'=>'فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ','transliteration'=>'Falammaa ra ash-shamsa baazighatan qaala haazaa Rabbee haazaaa akbar(u) falammaaa afalat qaala yaa-qawmi innee bareee\'um mimmaa tushrikoon','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>79,'arabic_text'=>'إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Innee waj-jahtu wajhiya lillazee fataras samaawaati wal-arda haneefanw wa-maaa ana minal mushrikeen','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>80,'arabic_text'=>'وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ','transliteration'=>'Wa-haaj-jahoo qau-muh(u); qaala a-tuh-haaj-jooon-nee fil laahi wa-qad hadaan(i); wa-laaa akhaafu maa tushri-kuna bihee illaaa aien yashaaa\'a Rabbee shai\'a(nw) wasi\'a Rabbee kulla shai\'in \'ilman afalaa tata-zakkaroon','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>81,'arabic_text'=>'وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-kaifa akhaafu maa ashraktum wa-laa takhaa-foona annakum ashraktum billaahi maa lam yunazzil bihee \'alaikum sultaanaa; fa-aiyyul fareeqaini ahaqqu bil-amni in kuntum ta\'lamoon','page_number'=>137,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>82,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ','transliteration'=>'Allazeena aamanoo wa-lam yal-bisooo eemaanahum bizulmin ulaaa\'ika lahumul amnu wa-hum muhtadoon','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>83,'arabic_text'=>'وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ','transliteration'=>'Wa-tilka hujjatunaaa aatai-naahaaa Ibraaheema \'alaa qawmih; narfa\'u dara-jaatim man nashaaa\'; inna Rabbaka Hakeemun \'Aleem','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>84,'arabic_text'=>'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-wahabnaa lahoo Iss-haaqa wa-Ya\'qooba; kullan hadainaa; wa-Noohan hadainaa min qablu wa-min zurri-yatihee Daawooda wa-Sulaimaana wa-Ayyooba wa-Yoosufa wa-Moosaa wa-Haaroon; wa-kazaalika najzil muhsineen','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>85,'arabic_text'=>'وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-Zakariyyaa wa-Yahyaa wa-\'Eesaa wa-Illyaasa kullum minas saaliheen','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>86,'arabic_text'=>'وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-Ismaa\'eela wal-Yasa\'a wa-Yunusa wa-Lootan; wa-kullan faddalnaa \'alal \'aalameen','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>87,'arabic_text'=>'وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-min aabaaa\'ihim wa-zurri-yaatihim wa-ikhwaa-nihim waj-tabai-naahum wa-hadai-naahum ilaa Siraatim Mustaqeem','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>88,'arabic_text'=>'ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Zaalika hudal laahi yahdee bihee maien yashaaa\'u min \'ibaadih; wa-lau ashrakoo la-habita \'anhum maa kaanu ya\'maloon','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>89,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ','transliteration'=>'Ulaaa\'ikal lazeena aatai-naahumul Kitaaba wal-hukma wan-Nubuwwah; fa-ien yakfur bihaa haaa\'ulaaa\'i faqad wak-kalnaa bihaa qawmal laisoo bihaa bikaafireen','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>90,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ','transliteration'=>'Ulaaa\'ikal lazeena hadal laahu fabi-hudaa-humuq tadih; qul laaa as\'alukum \'alaihi ajran in huwa illaa zikraa lil-\'aalameen','page_number'=>138,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>91,'arabic_text'=>'وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ','transliteration'=>'Wa-maa qadarul laaha haqqa qadriheee iz qaaloo maaa anzalal laahu \'alaa basharim min shai\'; qul man anzalal Kitaabal lazee jaaa\'a bihee Moosaa nooranw Wa-hudal lin-naasi taj\'aloo-nahoo qaraa-teesa tubdoonahaa Wa-tukhfoona kaseera(nw) Wa-\'ullimtum maa lam ta\'lamooo antum Wa-laaa aabaaa\'ukum qulil laahu summa zarhum fee khawdihim yal\'aboon','page_number'=>139,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>92,'arabic_text'=>'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ','transliteration'=>'Wa-haazaa Kitaabun anzalnaahu Mubaarakum musaddiqul lazee bainaa yadaihi Wa-litunzira ummal Quraa Wa-man hawlahaa; wallazeena yu\'minoona bil-Aakhirati yu\'minoona bihee Wa-hum \'alaa Salaatihim yuhaafizoon','page_number'=>139,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>93,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ','transliteration'=>'Wa-man azlamu mimmanif taraa \'alal laahi kaziban aw qaala oohiya ilaiyya Wa-lam yooha ilaihi shai\'un Wa-man qaala sa-unzilu misla maaa anzalal laah; Wa-law taraaa iziz zaalimoona fee ghamaraatil mawti walmalaaa\'ikatu baasitooo aideehim akhrijooo anfusakum; al-yawma tujzawna \'azaabal hooni bimaa kuntum taqooloona \'alal laahi ghairal haqqi Wa-kuntum \'an aayaatihee tastakbiroon','page_number'=>139,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>94,'arabic_text'=>'وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ','transliteration'=>'Wa-laqad ji\'tumoonaa furaadaa kamaa khalaqnaakum awwala marra(tinw) Wa-taraktum maa khawwal-naakum waraaa\'a zuhoorikum Wa-maa naraa ma\'akum shufa\'aaa\'-akumul lazeena za\'amtum annahum feekum shurakaaa\'; laqat taqatta\'a bainakum Wa-dalla \'annkum maa kuntum taz\'umoon','page_number'=>139,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>95,'arabic_text'=>'۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ','transliteration'=>'Innal laaha faaliqul habbi wannawaa yukhrijul haiyya minal maiyyiti Wa-mukhrijul maiyyiti minal haiy; zaalikumul laahu fa-annaa tu\'fakoon','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>96,'arabic_text'=>'فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ','transliteration'=>'Faaliqul isbaahi Wa-ja\'alal laila sakananw wash-shamsa walqamara husbaanaa; zaalika taqdeerul \'Azeezil \'Aleem','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>97,'arabic_text'=>'وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Wa-Huwal lazee ja\'ala lakumun nujooma litahtadoo bihaa fee zulumaatil barri walbahr; qad fassalnal Aayaati liqaw-mien ya\'lamoon','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>98,'arabic_text'=>'وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ','transliteration'=>'Wa-huwal lazeee ansha-akum min nafsinw waahidatin famus-taqarrunw Wa-mustawda\'; qad fassalnal Aayaati liqaw mien-yafqahoon','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>99,'arabic_text'=>'وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Wa-Huwal lazeee anzala minas samaaa\'i maaa\'an fa-akhrajnaa bihee nabaata kulli shai(\'in) fa-akhrajnaa minhu khadiran nukhriju minhu habbam mutaraakiba(nw) Wa-minan nakhli min tal\'ihaa qin-waanun daaniyatunw Wa-jannaatim min a\'naab(inw) wazzaitoona warrummaana mushtabihanw Wa-ghaira mutashaabih; unzurooo ilaa samariheee izaaa asmara Wa-yan\'ih; inna fee zaalikum la-Aayaatil liqawmien yu\'minoon','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>100,'arabic_text'=>'وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ','transliteration'=>'Wa-ja\'aloo lillaahi shurakaaa\'al jinna Wa-khalaqa-hum Wa-kharaqoo lahoo baneena Wa-banaatim bighairi \'ilm Subhaanahoo Wa-Ta\'aalaa \'amma yasifoon','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>101,'arabic_text'=>'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Badee\'us samaawaati wal-ardi annnaa yakoonu lahoo waladunw Wa-lam takul lahoo saahiba(tunw) Wa-khalaqa kulla shain\'inw Wa-Huwa bikulli shai\'in \'Aleem','page_number'=>140,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>102,'arabic_text'=>'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ','transliteration'=>'Zaalikumul laahu Rabbukum laaa ilaaha illaa huwa khaaliqu kulli shai\'in fa\'budooh; Wa-huwa \'alaa kulli shai\'inw Wakeel','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>103,'arabic_text'=>'لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ','transliteration'=>'Laa tudrikuhul absaaru Wa-Huwa yudrikul absaara Wa-huwal Lateeful Khabeer','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>104,'arabic_text'=>'قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ','transliteration'=>'Qad jaaa\'akum basaaa\'iru mir Rabbikum faman absara fali-nafsihee Wa-man \'amiya fa\'alaihaa; Wa-maaa ana \'alaikum bihafeez','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>105,'arabic_text'=>'وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Wa-kazaalika nusarriful Aayaati Wa-liyaqooloo darasta Wali-nubaiyyi-nahoo liqawmien ya\'lamoon','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>106,'arabic_text'=>'ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ','transliteration'=>'Ittabi\' maaa oohiya ilaika mir Rabbika laaa ilaaha illaa Huwa Wa-a\'rid \'anil mushrikeen','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>107,'arabic_text'=>'وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ','transliteration'=>'Wa-law shaaa\'al laahu maaa ashrakoo; Wa-maa ja\'alnaaka \'alaihim hafeezanw Wa-maaa anta \'alaihim biwakeel','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>108,'arabic_text'=>'وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-laa tasubbul lazeena yad\'oona min doonil laahi fa-yasubbul laaha \'adwam bighairi \'ilm; kazaalika zaiyannaa likulli ummatin \'amalahum summa ilaa Rabbihim marji\'uhum fa-yunabbi\'uhum bimaa kaanoo ya\'maloon','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>109,'arabic_text'=>'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ','transliteration'=>'Wa-aqsamoo billaahi jahda aimaanihim la\'in jaaa\'at-hum Aayatul la-yu\'minunna bihaa; qul innamal Aayaatu \'indal laah(i) Wa-maa yush\'irukum annahaaa izaa jaaa\'at laa yu\'minoon','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>110,'arabic_text'=>'وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','transliteration'=>'Wa-nuqallibu af\'idatahum Wa-absaarahum kamaa lam yu\'minoo biheee awwala marratinw Wa-nazaruhum fee tughyaanihim ya\'mahoon','page_number'=>141,'juz_number'=>7,'hizb_number'=>14,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>111,'arabic_text'=>'۞ وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ','transliteration'=>'Wa-law annanaa nazzal-naaa ilaihimul malaaa\'ikata Wa-kallamahumul mawtaa Wa-hasharnaa \'alaihim kulla shai\'in qubulam maa kaanoo liyu\'minooo illaaa aien yashaaa\'al laah(u) Wa-laakinna aksarahum yajhaloon','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>112,'arabic_text'=>'وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ','transliteration'=>'Wa-kazaalika ja\'alnaa likulli nabiyyin \'aduwwan Shayaateenal insi waljinni yoohee ba\'duhum ilaa ba\'din zukhrufal qawli ghurooraa; Wa-law shaaa\'a Rabbuka maa fa\'aloohu fazarhum Wa-maa yaftaroon','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>113,'arabic_text'=>'وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ','transliteration'=>'Wa-litasghaaa ilaihi af\'idatul lazeena laa yu\'minoona bil-Aakhirati Wa-liyardawhu Wa-liyaqtarifoo maa hum muqtarifoon','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>114,'arabic_text'=>'أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ','transliteration'=>'Afaghairal laahi abtaghee hakamanw Wa-Huwal lazee anzala ilaikumul Kitaaba mufassalaa; wallazeena ataien-naahumul Kitaaba ya\'lamoona annahoo munazzalum mir Rabbika bilhaqqi falaa takoonanna minal mumtareen','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>115,'arabic_text'=>'وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-tammat Kalimatu Rabbika sidqanw Wa-\'adlaa; laa mubaddila li-Kalimaatih; Wa-Huwas Samee\'ul \'Aleem','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>116,'arabic_text'=>'وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ','transliteration'=>'Wa-in tuti\' aksara man fil ardi yudillooka \'an sabeelil laah; ien yattabi\'oona illaz zanna Wa-in hum illaa yakhrusoon','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>117,'arabic_text'=>'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ','transliteration'=>'Inna rabbaka Huwa a\'lamu maien yadillu \'an sabeelihee Wa-Huwa a\'lamu bilmuhtadeen','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>118,'arabic_text'=>'فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ','transliteration'=>'Fakuloo mimmmaa zukiras mul laahi \'alaihi in kuntum bi-Aayaatihee mu\'mineen','page_number'=>142,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>119,'arabic_text'=>'وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ','transliteration'=>'Wa-maa lakum allaa ta\'kuloo mimmaa zukiras mul laahi \'alaihi Wa-qad fassala lakum maa harrama \'alaikum illaa mad turirtum ilaih; Wa-inna kaseeral la-yudilloona bi-ahwaaa\'ihim bighairi \'ilm; inna Rabbaka Huwa a\'lamu bilmu\'tadeen','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>120,'arabic_text'=>'وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ','transliteration'=>'Wa-zaroo zaahiral ismi Wa-baatinah; innal lazeena yaksiboonal ismaa sa-yujzawna bimaa kaanoo yaqtarifoon','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>121,'arabic_text'=>'وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ','transliteration'=>'Wa-laa ta\'kuloo mimmaa lam yuzkaris mul laahi \'alaihi Wa-innahoo lafisq; Wa-innash Shayaateena la-yoohoona ilaaa awliyaaa\'ihim liyujaadilookum Wa-in ata\'tumoohum innakum lamushrikoon','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>122,'arabic_text'=>'أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Awa-man kaana maitan fa-ah-yaiynaahu Wa-ja\'alnaa lahoo nooraien yamshee bihee fin naasi kamamm masaluhoo fiz zulumaati laisa bikhaarijim minhaa; kazaalika zuyyina lilkaafireena maa kaanoo ya\'maloon','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>123,'arabic_text'=>'وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ','transliteration'=>'Wa-kazaalika ja\'alnaa fee kulli qaryatin akaa-bira mujri-meehaa liyamkuroo feehaa Wa-maa yamkuroona illaa bi-anfusihim Wa-maa yash\'uroon','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>124,'arabic_text'=>'وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ','transliteration'=>'Wa-izaa jaaa\'athum Aayatun qaaloo lan nu\'mina hatta nu\'taa misla maaa ootiya Rusulul laah; Allahu a\'almu haisu yaj\'alu Risaalatah; sa-yuseebul lazeena ajramoo saghaarun \'indal laahi Wa-\'azaabun shadeedum bimaa kaanoo yamkuroon','page_number'=>143,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>125,'arabic_text'=>'فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ','transliteration'=>'Famaien yuridil laahu aien yahdiyahoo yashrah sadrahoo lil-islaami Wa-maien yurid aien yudillahoo yaj\'al sadrahoo daiyyiqan harajan ka-annamaa yassa\'-adu fis samaaa\'; kazaalika yaj\'alul laahur rijsa \'alal lazeena laa yu\'minoon','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>126,'arabic_text'=>'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ','transliteration'=>'Wa-haazaa siraatu Rabbika Mustaqeemaa; qad fassalnal Aayaati liqawmien yazzakkaroon','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>127,'arabic_text'=>'۞ لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Lahum daarus salaami \'inda Rabbihim Wa-huwa waliyyuhum bimaa kaanoo ya\'maloon','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>128,'arabic_text'=>'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ','transliteration'=>'Wa-yawma yah-shuruhum jamee\'a(ien) yaa-ma\'sharal jinni qadis taksartum minal insi Wa-qaala awliyaa\'uhum minal insi Rabbanas tamta\'a ba\'dunaa biba\'dinw Wa-balaghnaaa ajalannal lazeee ajjalta lanaa; qaalan naaru maswaakum khaalideena feehaaa illaa maa shaaa \'allaah; inna Rabbaka Hakeemun \'Aleem','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>129,'arabic_text'=>'وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Wa-kazaalika nuwallee ba\'daz zaalimeena ba\'dam bimaa kaanoo yaksiboon','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>130,'arabic_text'=>'يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ','transliteration'=>'Yaa-ma\'sharal jinni wal-insi alam ya\'tikum Rusulum minkum yaqussoona \'alaikum Aayaatee Wa-yunziroonakum liqaaa\'a Yawmikum haazaa; qaaloo shahidnaa \'alaaa anfusinaa Wa-gharrat-humul hayaatud dunyaa Wa-shahidooo \'alaa anfusihim annahum kaanoo kaafireen','page_number'=>144,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>131,'arabic_text'=>'ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ','transliteration'=>'Zaalika al lam yakkur Rabbuka muhlikal quraa bizulminw Wa-ahluhaa ghaafiloon','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>132,'arabic_text'=>'وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ','transliteration'=>'Wa-likullin darajaatum mimmaa \'amiloo; Wa-maa Rabbuka bighaafilin \'ammaa ya\'maloon','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>133,'arabic_text'=>'وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ','transliteration'=>'Wa-Rabbukal ghaniyyu zur rahmah(ti); ien yasha\' yuz-hibkum Wa-yastakhlif mim ba\'dikum maa yashaaa(\'u) kamaaa ansha-akum min zurriyyati qawmin aakhareen','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>134,'arabic_text'=>'إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ','transliteration'=>'Inna maa too\'adoona la-aatinw Wa-maaa antum bimu\'jizeen','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>135,'arabic_text'=>'قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ','transliteration'=>'Qul yaa-qawmi\' maloo \'alaa makaanatikum innee \'aamil(un) fasawfa ta\'lamoona man takoonu lahoo \'aaqibatud daar; innahoo laa yuflihuz zaalimoon','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>136,'arabic_text'=>'وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ','transliteration'=>'Wa-ja\'aloo lillaahi mimmaa zara-a minal harsi walan\'aami naseeba(n) faqaaloo haazaa lillaahi biza\'mihim Wa-haaza lishurakaa\'inaa famaa kaana lishurakaaa\'ihim falaa yasilu ilal laah(i) Wa-maa kaana lillaahi fahuwa yasilu ilaa shurakaaa\'ihim; saaa\'a maa yahkumoon','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>137,'arabic_text'=>'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ','transliteration'=>'Wa-kazaalika zaiyyana likaseerim minal mushrikeena qatla awlaadihim shurakaaa\'uhum liyurdoohum Wa-liyalbisoo \'alaihim deenahum Wa-law shaaa\'al laahu maa fa\'aloohu fazarhum Wa-maa yaftaroon','page_number'=>145,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>138,'arabic_text'=>'وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Wa-qaaloo haaziheee an\'aamunw Wa-harsun hijrun laa yat\'amuhaaa illaa man nashaaa\'u biza\'mihim Wa-an\'aamun hurrimat zuhooruhaa Wa-an\'aamul laa yazkuroonas mal laahi \'alaihaf tiraaa\'an \'alaiyyh; sa-yajzeehim bimaa kaanoo yaftaroon','page_number'=>146,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>139,'arabic_text'=>'وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ','transliteration'=>'Wa-qaaloo maa fee butooni haazihil an\'aami khaalisatul lizukoorinaa Wa-muharramun \'alaaa azwaajinaa Wa-ien yakum maitatan fahum feehi shurakaaa\'; sa-yajzeehim wasfahum; innahoo Hakeemun \'Aleem','page_number'=>146,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>140,'arabic_text'=>'قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ','transliteration'=>'Qad khasiral lazeena qatalooo awlaadahum safaham bighairi \'ilminw Wa-harramoo maa razaqahumul laahuf tiraaa\'an \'alal laah; qad dalloo Wa-maa kaanoo muhtadeen','page_number'=>146,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>141,'arabic_text'=>'۞ وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ','transliteration'=>'Wa-Huwal lazee ansha-a jannaatim ma\'rooshaatinw Wa-ghaira ma\'rooshaa(tinw) wan-nakhla wazzar\'a mukhtalifan ukuluhoo wazzaitoona warrum-maana mutashaabiha(nw) Wa-ghaira mutashaabih; kuloo min samariheee izaaa asmara Wa-aatoo haqqahoo yawma hasaadihee Wa-laa tusrifoo; innahoo laa yuhibbul musrifeen','page_number'=>146,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>142,'arabic_text'=>'وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ','transliteration'=>'Wa-minal an\'aami hamoolatanw Wa-farshaa; kuloo mimmaa razaqakumul laahu Wa-laa tattabi\'oo khutuwaatish Shaitaan; innahoo lakum \'aduwwum mubeen','page_number'=>146,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>143,'arabic_text'=>'ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Samaaniyata azwaaj(im) minad da\'nis naini Wa-minal ma\'zis nain; qul \'aaaz-zaka-raini harrama amil unsa-yaiyni ammash tamalat \'alaihi arhaamul unsayaiyn(i) nabbi-\'oonee bi\'ilmin in kuntum saadiqeen','page_number'=>147,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>144,'arabic_text'=>'وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-minal ibilis naini Wa-minal baqaris nain; qul \'aaaz-zakaraini harrama amil unsa-yaiyni ammash tamalat \'alaihi arhaamul unsa-yaiyn(i) am kuntum shuhadaaa\'a iz wassaa-kumul laahu bihaazaa; faman azlamu mimmanif taraa \'alal laahi kazibal liyuddillan naasa bighairi \'ilm; innal laaha laa yahdil qawmaz zaalimeen','page_number'=>147,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>145,'arabic_text'=>'قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Qul laaa ajidu fee maaa oohiya ilaiyya muharraman \'alaa taa\'imien yat\'amuhooo illaaa aien yakoona maitatan aw damam masfoohan aw lahma khinzeerin fa-innahoo rijsun aw fisqan uhilla lighairil laahi bih; famanid turra ghaira baa-ghinw Wa-laa \'aadin fa-inna Rabbaka Ghafoorur Raheem','page_number'=>147,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>146,'arabic_text'=>'وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ','transliteration'=>'Wa-\'alal lazeena haadoo harramnaa kulla zee zufur(inw) Wa-minal baqari walghanami harramnaa \'alaihim shuhoo-mahumaaa illaa maa hamalat zuhoo-ruhumaaa awil hawaayaaa aw makh talata bi\'azm; zaalika jazainaahum bibagh-yihim Wa-innaa la-saadiqoon','page_number'=>147,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>147,'arabic_text'=>'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ','transliteration'=>'Fa-in kazzabooka faqur Rabbukum zoo rahmatinw waasi\'a(tinw) Wa-laa yuraddu ba\'suhoo \'anil qawmil mujrimeen','page_number'=>148,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>148,'arabic_text'=>'سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ','transliteration'=>'Sayaqoolul lazeena ashrakoo law shaaa\'al laahu maaa ashraknaa Wa-laaa aabaaa\'unaa Wa-laa harramnaa min shai\'; kazaalika kazzabal lazeena min qablihim hattaa zaaqoo ba\'sanaa; qul hal \'indakum min \'ilmin fatukh-rijoohu lanaa in tattabi\'oona illaz zanna wa-in antum illaa takhhrusoon','page_number'=>148,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>149,'arabic_text'=>'قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ','transliteration'=>'Qul falillaahil hujjatul baalighatu falaw shaaa\'a lahadaakum ajma\'een','page_number'=>148,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>150,'arabic_text'=>'قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ','transliteration'=>'Qul halumma shuhadaaa\'akumul lazeena yash-hadoona annal laaha harrama haazaa fa-in shahidoo falaa tashhad ma\'ahum; Wa-laa tattabi\' ahwaaa\'al lazeena kazzaboo bi-Aayaatinaa wallazeena laa yu\'minoona bil-Aakhira(ti) Wa-hum bi-Rabbihim ya\'diloon','page_number'=>148,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>151,'arabic_text'=>'۞ قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Qul ta\'aalaw atlu maa harrama Rabbukum \'alaikum allaa tushrikoo bihee shai\'anw Wa-bil-waalidaini ihsaana(nw) Wa-laa taqtulooo awlaadakum min imlaaqin nahnu narzuqukum Wa-iyyaahum Wa-laa taqrabul fawaahisha maa zahara minhaa Wa-maa batana Wa-laa taqtulun nafsal latee harramal laahu illaa bilhaqq; zaalikum wassaakum bihee la\'allakum ta\'qiloon','page_number'=>148,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>152,'arabic_text'=>'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Wa-laa taqraboo maalal yateemi illaa billatee hiyaa ahsanu hattaa yablugha ashudda(hoo) Wa-aoful kaila wal-meezaana bilqisti laa nukallifu nafsan illaa wus\'ahaa Wa-izaa qultum fa\'diloo Wa-law kaana zaa qurbaa Wa-bi-\'ahdil laahi awfoo; zaalikum wassaakum bihee la\'allakum tazakkaroon','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>153,'arabic_text'=>'وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Wa-annna haazaa Siraatee mustaqeeman fattabi\'oo(hu) Wa-laa tattabi\'us subula fata-farraqa bikum \'an sabeelih; zaalikum wassaakum bihee la\'allakum tattaqoon','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>154,'arabic_text'=>'ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ','transliteration'=>'Summa aatainaa Moosal Kitaaba tammaaman \'alal lazeee ahsana Wa-tafseelal likulli shai\'inw Wa-hudanw Wa-rahmatal la\'allahum bi-liqaaa\'i Rabbihim yu\'minoon','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>155,'arabic_text'=>'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Wa-haazaa Kitaabun anzalnaahu Mubaarakun fattabi\'oohu wattaqoo la\'al-lakum turhamoon','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>156,'arabic_text'=>'أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ','transliteration'=>'An taqooloo inna-maaa unzilal Kitaabu \'alaa taaa\'ifataini min qablinaa Wa-in kunnaa \'an diraa-satihim laghaafileen','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>157,'arabic_text'=>'أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ','transliteration'=>'Aw taqooloo law annaaa unzila \'alainal kitaabu lakunnaaa ahdaa minhum; faqad jaaa\'akum baiyyinatum mir Rabbikum Wa-hudanw Wa-rahmah; faman azlamu mimman kazzaba bi-Aayaatil laahi Wa-sadafa \'anhaa; sanajzil lazeena yasdifoona \'an Aayaatinaa sooo\'al \'azaabi bimaa kaanoo yasdifoon','page_number'=>149,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>158,'arabic_text'=>'هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ','transliteration'=>'Hal yanzuroona illaaa an ta\'tiyahumul malaaa\'ikatu aw ya\'tiya Rabbuka aw ya\'tiya ba\'du Aayaati Rabbik; yawma ya\'tee ba\'du Aayaati Rabbika laa yanfa\'u nafsan eemaanuhaa lam takun aamanat min qablu aw kasabat feee eemaanihaa khairaa; qulin tazirooo innaa muntaziroon','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>159,'arabic_text'=>'إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ','transliteration'=>'Innal lazeena farraqoo deenahum Wa-kaanoo shiya\'al lasta minhum fee shaiyy\'; innamaaa amruhum ilal laahi summa yunabbi\'uhum bimaa kaanoo yaf\'aloon','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>160,'arabic_text'=>'مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Man jaaa\'a bilhasanati falahoo \'ashru amsaalihaa Wa-man jaaa\'a bis-saiyyi\'ati falaa yujzaaa illaa mislahaa Wa-hum laa yuzlamoon','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>161,'arabic_text'=>'قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Qul innanee hadaanee Rabbeee ilaa Siraatim Mustaqeem(in) deenan qiyamam Millata Ibraaheema haneefa(wn); Wa-maa kaana minal mushrikeen','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>162,'arabic_text'=>'قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qul inna Salaatee Wa-nusukee Wa-mah-yaaya Wa-mamaa-tee lillaahi Rabbil aalameen','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>163,'arabic_text'=>'لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ','transliteration'=>'Laa shareeka lahoo Wa-bizaalika umirtu Wa-ana awwalul muslimeen','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>164,'arabic_text'=>'قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','transliteration'=>'Qul aghairal laahi abghee Rabbanw Wa-Huwa Rabbu kulli shaiy(inw); Wa-laa taksibu kullu nafsin illaa \'alaihaa; Wa-laa taziru waaziratunw wizra ukhraa; summa ilaa Rabbikum marji\'ukum fa-yunabbi\'ukum bimaa kuntum feehi takhtalifoon','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            ['surah_id'=>6,'ayah_number'=>165,'arabic_text'=>'وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ','transliteration'=>'Wa-Huwal lazee ja\'alakum khalaaa\'ifal ardi Wa-rafa\'a ba\'dakum fawqa ba\'din darajaatil liyabluwakum fee maaa aataakum; inna Rabbaka saree\'ul \'iqaabi Wa-innahoo la-Ghafoorur Raheem','page_number'=>150,'juz_number'=>8,'hizb_number'=>15,'is_sajdah'=>false],
            /* Surah 7: The Heights (Al-A'raf) */
            ['surah_id'=>7,'ayah_number'=>1,'arabic_text'=>'الٓمٓصٓ','transliteration'=>'Alif-laaam-meem-sad','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>2,'arabic_text'=>'كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ','transliteration'=>'Kitaabun unzila ilaika falaa yakun fee sadrika harajum minhu litunzira bihee Wa-zikraa lilmu\'mineen','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>3,'arabic_text'=>'ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ','transliteration'=>'Ittabi\'oo maaa unzila \'ilaikum mir Rabbikum Wa-laa tattabi\'oo min dooniheee awliyaaa\'; qaleelam maa tazakkaroon','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>4,'arabic_text'=>'وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ','transliteration'=>'Wa-kam min qaryatin ahlaknaahaa fajaaa\'ahaa ba\'sunaa bayaatan aw hum qaaa\'iloon','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>5,'arabic_text'=>'فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ','transliteration'=>'Famaa kaana da\'waahum iz jaaa\'ahum ba\'sunaa illaaa an qaalooo innaa kunnaa zaalimeen','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>6,'arabic_text'=>'فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ','transliteration'=>'Falanas\'alannal lazeena ursila ilaihim Wa-lanas\'alannal mursaleen','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>7,'arabic_text'=>'فَلَنَقُصَّنَّ عَلَيۡهِم بِعِلۡمٖۖ وَمَا كُنَّا غَآئِبِينَ','transliteration'=>'Falanaqus-sanna \'alaihim bi\'ilminw Wa-maa kunnaa ghaaa\'ibeen','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>8,'arabic_text'=>'وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Walwaznu Yawma\'izinil haqq(u), faman saqulat mawaa-zeenuhoo fa-ulaaa\'ika humul muflihoon','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>9,'arabic_text'=>'وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظۡلِمُونَ','transliteration'=>'Wa-man khaffat mawaazeenuhoo fa-ulaaa\'ikal lazeena khasirooo anfusahum bimaa kaanoo bi-Aayaatinaa yazlimoon','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>10,'arabic_text'=>'وَلَقَدۡ مَكَّنَّٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلٗا مَّا تَشۡكُرُونَ','transliteration'=>'Wa-laqad makkannaakum fil ardi Wa-ja\'alnaa lakum feehaa ma\'aayish; qaleelam maa tashkuroon','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>11,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ','transliteration'=>'Wa-laqad khalaqnaakum summa sawwar-naakum summa qulnaa lil-malaaa\'ikatis judoo li-Aadama fa-sajadooo illaaa Ibleesa lam yakum minas saajideen','page_number'=>151,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>12,'arabic_text'=>'قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ','transliteration'=>'Qaala maa mana\'aka allaa tasjuda iz amartuk(a) qaala ana khairum minhu khalaqtanee min naarinw Wa-khalaqtahoo min teen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>13,'arabic_text'=>'قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ','transliteration'=>'Qaala fahbit minhaa famaa yakoonu laka an ta-ta-kabbara feehaa fakhruj innaka minas saaghireen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>14,'arabic_text'=>'قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','transliteration'=>'Qaala anzirneee ilaa Yawmi yub\'asoon','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>15,'arabic_text'=>'قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ','transliteration'=>'Qaala innaka minal munzareen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>16,'arabic_text'=>'قَالَ فَبِمَآ أَغۡوَيۡتَنِي لَأَقۡعُدَنَّ لَهُمۡ صِرَٰطَكَ ٱلۡمُسۡتَقِيمَ','transliteration'=>'Qaala fabimaaa aghwai-tanee la-aq\'udanna lahum siraa-takal mustaqeem','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>17,'arabic_text'=>'ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ','transliteration'=>'Summa la-aatiyan-nahum mim baini aideehim Wa-min khalfihim Wa-\'an aimaa-nihim Wa-\'an shamaaa\'ilihim Wa-laa tajidu aksarahum shaakireen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>18,'arabic_text'=>'قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومٗا مَّدۡحُورٗاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِينَ','transliteration'=>'Qaala khruj minhaa maz\'oomam madhooraa(l); laman tabi\'aka minhum la-amla\'anna Jahannama minkum ajma\'een','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>19,'arabic_text'=>'وَيَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-yaaa-Aadamus kun anta Wa-zawjukal Jannata fakulaa min haisu shi\'tumaa Wa-laa taqrabaa haazihish shajarata fatakoonaa minaz zaalimeen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>20,'arabic_text'=>'فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ','transliteration'=>'Fawaswasa lahumash shaitaanu liyubdiya lahumaa maa wooriya \'anhumaa min saw-aatihimaa Wa-qaala maa nahaakumaa Rabbukumaa \'an haazihish shajarati illaaa an takoonaa malakaini aw takoonaa minal khaalideen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>21,'arabic_text'=>'وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ','transliteration'=>'Wa-qaasamahumaaa innee lakumaa laminan naasiheen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>22,'arabic_text'=>'فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ','transliteration'=>'Fadal-laahumaa bighuroor; falammaa zaaqash shajarata badat lahumaa saw-aatuhumaa Wa-tafiqaa yakh-sifaani \'alaihimaa minw waraqil jannah(ti) Wa-naadaa-humaa Rabbuhumaaa alam anha-kumaa \'an til-kumash shajarati Wa-aqul lakumaaa innash shaitaana lakumaa \'aduwwum mubeen','page_number'=>152,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>23,'arabic_text'=>'قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Qaalaa Rabbanaa zalamnaaa anfusanaa Wa-il lam taghfir lanaa Wa-tarhamnaa lana-koo-nanna minal khaasireen','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>24,'arabic_text'=>'قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ','transliteration'=>'Qaalah bitoo ba\'dukum liba\'din a\'duww(unw), Wa-lakum fil ardi mustaqarrunw Wa-mataa\'un ilaa heen','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>25,'arabic_text'=>'قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ','transliteration'=>'Qaala feehaa tah-yawna Wa-feehaa tamoo-toona Wa-minhaa tukhrajoon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>26,'arabic_text'=>'يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ','transliteration'=>'Yaa-Baneee Aadama qad anzalnaa \'alaikum libaa-saien yuwaaree saw-aatikum Wa-reesha(nw) Wa-libaasut taqwaa zaalika khair; zaalika min Aayaatil laahi la\'allahum yaz-zakkaroon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>27,'arabic_text'=>'يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ','transliteration'=>'Yaa-Banee Aadama laa yafti-nanna-kumush shaitaanu kamaaa akhraja aba-waikum minal Jannah(ti) yanzi\'u \'anhumaa libaasa-humaa liyuri-yahumaa saw-aati-himaaa; innahoo yaraakum huwa Wa-qabeeluhoo min haisu laa tarawnahum; innaa ja\'alnash shayaateena awliyaaa\'a lillazeena laa yu\'minoon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>28,'arabic_text'=>'وَإِذَا فَعَلُواْ فَٰحِشَةٗ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Wa-izaa fa\'aloo faahishatan qaaloo wajadnaa \'alaihaaa aabaaa\'ana wallaahu ama-ranaa bihaa; qul innal laaha laa ya\'muru bilfah-shaaa(i) a-taqooloona \'alal laahi maa laa ta\'lamoon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>29,'arabic_text'=>'قُلۡ أَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ','transliteration'=>'Qul amara Rabbee bil-qisti Wa-aqeemoo wujoohakum \'inda kulli masjid(inw) wad\'oohu mukhliseena lahud deen(a); kamaa bada-akum ta\'oodoon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>30,'arabic_text'=>'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ','transliteration'=>'Fareeqan hadaa Wa-fareeqan haqqa \'alaihimud dalaalah; innahumut takhazush shayaateena awliyaaa\'a min doonil laahi Wa-yah-saboona annahum muhtadoon','page_number'=>153,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>31,'arabic_text'=>'۞ يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ','transliteration'=>'Yaa-Banee Adama khuzoo zeenatakum \'inda kulli masjidinw Wa-kuloo wash-raboo Wa-laa tusrifoo; innahoo laa yuhibbul musrifeen','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>32,'arabic_text'=>'قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Qul man harrama zeenatal laahil lateee akhraja li\'ibaadihee wat-taiyyi-baati minar rizq; qul hiya lil-lazeena aamanoo fil hayaatid dunyaa khaali-sataien Yawmal Qiyaamah; kazaalika nufassilu(l) Aayaati liqaw-mien ya\'lamoon','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>33,'arabic_text'=>'قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Qul innamaa harrama Rabbiyal fawaa-hisha maa zahara minhaa wa-maa batana wal-isma wal-baghya bighairil haqqi Wa-an tushrikoo billaahi maa lam yunazzil bihee sultaananw wa-an taqooloo \'alal laahi maa laa ta\'lamoon','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>34,'arabic_text'=>'وَلِكُلِّ أُمَّةٍ أَجَلٞۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ','transliteration'=>'Wa-likulli ummatin ajal(un), fa-izaa jaaa\'a ajaluhum laa yasta\'-khiroona saa\'atanw wa-laa yastaq-dimoon','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>35,'arabic_text'=>'يَٰبَنِيٓ ءَادَمَ إِمَّا يَأۡتِيَنَّكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Yaa-Banee Aadama immaa ya\'ti-yannakum Rusulum minkum yaqus-soona \'alaikum Aayaatee famanit taqaa wa-aslaha falaa khawfun \'alaihim wa-laa hum yahzanoon','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>36,'arabic_text'=>'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wallazeena kazzaboo bi-Aayaatinaa wastakbaroo \'an-haaa ulaaa\'ika As-haabun naari hum feehaa khaalidoon','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>37,'arabic_text'=>'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ أُوْلَٰٓئِكَ يَنَالُهُمۡ نَصِيبُهُم مِّنَ ٱلۡكِتَٰبِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَالُوٓاْ أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ','transliteration'=>'Faman azlamu mimma-nif taraa \'alal laahi kaziban aw kazzaba bi-Aayaatih; ulaaa\'ika yanaa-luhum nasee-buhum minal Kitaab; hattaaa izaa jaaa\'at-hum rusulunaa yatawaf-fawnahum qaalooo ai-na maa kuntum tad\'oonaa min doonil laah(i); qaaloo dalloo \'annaa wa-shahidoo \'alaaa an-fusihim annahum kaanoo kaafireen','page_number'=>154,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>38,'arabic_text'=>'قَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ','transliteration'=>'Qaalad khuloo feee uma-min qad khalat min qab-likum minal jinni wal-insi fin naar(i); kullamaa dakhalat ummatul la\'anat ukhtaha; hattaaa izad daa-rakoo feehaa jamee\'an qaalat ukh-raahum li-oolaa-hum Rabbanaa haaa-u\'laaa\'i adal-loonaa fa-aatihim \'azaaban di\'fam minan naar(i); qaala likul-lin di\'funw wa-laakil laa ta\'lamoon','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>39,'arabic_text'=>'وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلٖ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ','transliteration'=>'Wa-qaalat oolaahum li-ukh-raahum famaa kaana lakum \'alainaa min fadlin fazoo-qul azaaba bimaa kuntum taksiboon','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>40,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ','transliteration'=>'Innal lazeena kazzaboo bi-Aayaatinaa wastak-baroo \'anhaa laa tufat-tahu lahum abwaabus samaaa(i) wa-laa yad-khuloonal jannata hattaa yalijal jamalu fee sammil khiyaat; wa-kazaalika najzil mujrimeen','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>41,'arabic_text'=>'لَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ','transliteration'=>'Lahum min jahannama mihaa-dunw wa-min faw-qihim ghawaash(i); wa-kazaalika najziz zaalimeen','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>42,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wal-lazeena aamanoo wa-\'amilus saalihaati la nukallifu nafsan illaa wus\'ahaaa ulaaa\'ika As-haabul jannati, hum feehaa khaalidoon','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>43,'arabic_text'=>'وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-naza\'naa maa fee sudoo-rihim min ghillin tajree min tah-ti-himul anhaar(u), wa-qaalul hamdu lil-laahil lazee hadaa-naa lihaaza wa-maa kunna linah-tadiya lau-laaa ann hadaanal laah(u), laqad jaaa\'at Rusulu Rabbinaa bilhaqq; Wa-noodoo an til-kumul jannatu ooris-tumoohaa bimaa kuntum ta\'maloon','page_number'=>155,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>44,'arabic_text'=>'وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ','transliteration'=>'Wa-naadaa As-haabul jannati as-haaban naari an qad wajadnaa maa wa\'ada-naa Rabbunaa haqqan fahal wajad-tum maa wa\'ada Rabbukum haqqa(n); qaaloo na\'am, fa-azzana mu\'azzinum bainahum al la\'natul laahi \'alaz zaalimeen','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>45,'arabic_text'=>'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ','transliteration'=>'Allazeena yasud-doona \'an sabeelil laahi wa-yabghoo-nahaa \'iwaja(nw), Wa-hum bil-aakhirati kaafiroon','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>46,'arabic_text'=>'وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ','transliteration'=>'Wa-baina-humaa hijaab(unw), Wa-\'alal A\'raafi rijaa-luien ya\'rifoona kullam bi-seemaahum; Wa-naadaw as-haabal jannati an salaamun \'alaikum; lam yad-khuloohaa wa-hum yatma\'oon','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>47,'arabic_text'=>'۞ وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-izaa surifat absaaruhum tilqaaa\'a as-haabin naari qaaloo Rabbanaa laa taj\'alnaa ma\'al qawmiz zaalimeen','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>48,'arabic_text'=>'وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ','transliteration'=>'Wa-naadaaa as-haabul a\'raafi rijaa-laien ya\'rifoonahum bi-seemaahum qaaloo maaa aghnaa \'ankum jam\'ukum wa-maa kuntum tastak-biroon','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>49,'arabic_text'=>'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ','transliteration'=>'A-haaa\'ulaaa\'il lazeena aqsamtum laa yanaa-luhumul laahu bi-rahmah(tin); ud-khulul Jannata laa khawfun \'alaikum wa-laaa antum tah-zanoon','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>50,'arabic_text'=>'وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-naadaaa as-haabun naari as-haabal Jannati an afeedoo \'alainaa minal maaa\'i aw mimma raza-qakumul laah(u); qaaloo innal laaha harrama-humaa \'alal kaafireen','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>51,'arabic_text'=>'ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوٗا وَلَعِبٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ','transliteration'=>'Allazeenat takhazoo deenahum lahwanw Wa-la\'i-banw Wa-gharrat-humul hayaatud dunyaa; fal-Yawma nannsaahum kamaa nasoo liqaaa\'a Yawmihim haazaa Wa-maa kaanoo bi-aayaatinaa yajhadoon','page_number'=>156,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>52,'arabic_text'=>'وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Wa-laqad ji\'naahum bi-Kitaabin fassalnaahu \'alaa \'ilmin hudanw Wa-rahmatal liqaw-mien yu\'minoon','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>53,'arabic_text'=>'هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Hal yanzuroona illaa ta\'weelah(u); yawma ya\'tee ta\'wee-luhoo yaqoolul lazeena nasoohu min qablu qad jaaa\'at Rusulu Rabbinaa bilhaqq; fahal lanaa min shufa\'aaa\'a fa-yashfa\'oo lanaaa aw nuraddu fana\'mala ghairal lazee kunnaa na\'mal; qad khasirooo an-fusahum Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>54,'arabic_text'=>'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ','transliteration'=>'Inna Rabbakumul laahul lazee khalaqas samaawaati wal-arda fee sittati ayyaamin summas tawaa \'alal \'arshi yughshil lailan nahaara yatlu-buhoo haseesanw wash-shamsa wal-qamara wan-nujooma musakh-khaa-raatim bi-amrih(i); alaa lahul khalqu wal-amr(u); tabaarakal laahu Rabbul \'aalameen','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>55,'arabic_text'=>'ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ','transliteration'=>'Ud\'oo Rabbakum tadarru\'anw Wa-khufyah(tan); innahoo laa yuhibbul mu\'tadeen','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>56,'arabic_text'=>'وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-laa tufsidoo fil ardi ba\'da islaahihaa wad\'oohu khawfanw Wa-tama\'aa; inna rahmatal laahi qareebum minal muhsineen','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>57,'arabic_text'=>'وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا ثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Wa-Huwal lazee yursilur riyaaha bushram baina yadai rahmatihee hattaaa izaaa aqallat sahaaban siqaalan suqnaahu libaladim maiyitin fa-annzalnaa bihil maaa\'a fa-akhrajnaa bihee minn kullis samaraat; kazaalika nukhrijul mawtaa la\'allakum tazakkaroon','page_number'=>157,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>58,'arabic_text'=>'وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ','transliteration'=>'Walbaladut taiyibu yakhruju nabaatuhoo bi-izni Rabbihee wallazee khabusa laa yakhruju illaa nakidaa; kazaalika nusarriful Aayaati liqawminy yashkuroon','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>59,'arabic_text'=>'لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ','transliteration'=>'Laqad arsalnaa noohan ilaa qawmihee faqaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuhoo inneee akhaafu \'alaikum \'azaaba Yawmin \'Azeem','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>60,'arabic_text'=>'قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Qaalal mala-u min qaw-miheee innaa lanaraaka fee dalaalim mubeen','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>61,'arabic_text'=>'قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaala yaa-qawmi laisa bee dalaalatunw Wa-laakinnee Rasoolum mir Rabbil \'aalameen','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>62,'arabic_text'=>'أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Uballighukum Risaalaati Rabbee Wa-ansahu lakum Wa-a\'lamu minal laahi maa laa ta\'lamoon','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>63,'arabic_text'=>'أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Awa\'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum Wa-litattaqoo Wa-la\'allakum turhamoon','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>64,'arabic_text'=>'فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ','transliteration'=>'Fakazzaboohu fa-anjai-naahu wallazeena ma\'ahoo fil fulki Wa-aghraqnal lazeena kazzaboo bi-Aayaatinaa; innahum kaanoo qawman \'ameen','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>65,'arabic_text'=>'۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','transliteration'=>'Wa-ilaa \'aadin akhaahum Hoodaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuh; afalaa tattaqoon','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>66,'arabic_text'=>'قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Qaalal mala-ul lazeena kafaroo min qawmiheee innaa lanaraaka fee safaahatinw Wa-innaa la-nazunnuka minal kaazibeen','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>67,'arabic_text'=>'قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaala yaa-qawmi laisa bee safaahatunw Wa-laakinnee Rasoolum mir Rabbil \'aalameen','page_number'=>158,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>68,'arabic_text'=>'أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ','transliteration'=>'Uballighukum Risaalaati Rabbee Wa-ana lakum naasihun ameen','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>69,'arabic_text'=>'أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Awa\'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum; wazkurooo iz ja\'alakum khulafaaa\'a mim ba\'di qawmi noohinw Wa-zaadakum fil khalqi bastatan fazkurooo aalaaa\'al laahi la\'allakum tuflihoon','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>70,'arabic_text'=>'قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaalooo aji\'tanaa lina\'budal laaha wahdahoo Wa-nazara maa kaana ya\'budu aabaaa\'unaa fa\'tinaa bimaa ta\'idunaaa in kunta minas saadiqeen','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>71,'arabic_text'=>'قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ','transliteration'=>'Qaala qad waqa\'a alaikum mir Rabbikum rijsunw Wa-ghadab, atujaadiloonanee feee asmaaa\'in sammaitumoohaaa antum Wa-aabaaa\'ukum maa nazzalal laahu bihaa min sultaan; fantazirooo innee ma\'akum minal muntazireen','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>72,'arabic_text'=>'فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ','transliteration'=>'Fa-anjainaahu wallazeena ma\'ahoo birahmatim minnaa Wa-qata\'naa daabiral lazeena kazzaboo bi-Aayaatinaa Wa-maa kaanoo mu\'mineen','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>73,'arabic_text'=>'وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wa-ilaa Samooda akhaahum Saalihaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum haazihee naaqatul laahi lakum Aayatan fazaroohaa ta\'kul feee ardil laahi Wa-laa tamassoohaa bisooo\'in fa-ya\'khuzakum \'azaabun aleem','page_number'=>159,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>74,'arabic_text'=>'وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','transliteration'=>'Wazkuroo iz ja\'alakum khulafaaa\'a mim ba\'di \'Aadinw Wa-bawwa-akum fil ardi tattakhizoona min suhoolihaa qusooranw Wa-tanhitoonal jibaala buyootan fazkurooo aalaaa\'al laahi Wa-laa ta\'saw fil ardi mufsideen','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>75,'arabic_text'=>'قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ','transliteration'=>'Qaalal mala-ul lazeenas takbaroo min qawmihee lillazeenas tud\'ifoo liman aamana minhum ata\'lamoona anna Saaliham mursalum mir Rabbih; qaalooo innaa bimaaa ursila bihee mu\'minoon','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>76,'arabic_text'=>'قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ','transliteration'=>'Qaalal lazeenas takbarooo innaa billazeee aamanntum bihee kaafiroon','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>77,'arabic_text'=>'فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ','transliteration'=>'Fa\'aqarun naaqata wa\'ataw \'an amri Rabbihim Wa-qaaloo yaa-Saalihu\' tinaa bimaa ta\'idunaaa in kunta minal mursaleen','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>78,'arabic_text'=>'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ','transliteration'=>'Fa-akhazat-humur rajfatu fa-asbahoo fee daarihim jaasimeen','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>79,'arabic_text'=>'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ','transliteration'=>'Fa-tawalla \'anhum Wa-qaala yaa-qawmi laqad ablaghtukum Risaalata Rabbee Wa-nasahtu lakum Wa-laakil laa tuhibboonan naasiheen','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>80,'arabic_text'=>'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-Lootan iz qaala liqawmiheee ata\'toonal faahishata maa sabaqakum bihaa min ahadim minal \'aalameen','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>81,'arabic_text'=>'إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ','transliteration'=>'Innakum lata\'toonar rijaala shahwatam min doonin nisaaa\'; bal antum qawmum musrifoon','page_number'=>160,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>82,'arabic_text'=>'وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ','transliteration'=>'Wa-maa kaana jawaaba qawmihee illaa an qaalooo akhrijoohum min qaryatikum innahum unaasuny yatatahharoon','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>83,'arabic_text'=>'فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ','transliteration'=>'Fa-anjainaahu Wa-ahlahooo illam ra-atahoo kaanat minal ghaabireen','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>84,'arabic_text'=>'وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ','transliteration'=>'Wa-\'amtarnaa \'alaihim mataran fanzur kaifa kaana aaqibatul mujrimeen','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>85,'arabic_text'=>'وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-ilaa Madyana akhaahum Shu\'aybaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum fa-awful kaila walmeezaana Wa-laa tabkhasun naasa ashyaa\'ahum Wa-laa tufsidoo fil ardi ba\'da islaahihaa; zaalikum khairul lakum in kuntum mu\'mineen','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>86,'arabic_text'=>'وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ','transliteration'=>'Wa-laa taq\'udoo bikulli siraatin too\'idoona Wa-tasuddoona \'an sabeelil laahi man aamana bihee Wa-tabghoonahaa \'iwajaa; waz-kurooo iz kuntum qaleelan fakassarakum wanzuroo kaifa kaana \'aaqibatul mufsideen','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>87,'arabic_text'=>'وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ','transliteration'=>'Wa-In kaana taaa\'ifatum minkum aamanoo billazeee ursiltu bihee Wa-taaa\'ifatul lam yu\'minoo fasbiroo hattaa yahkumal laahu bainanaa; Wa-Huwa khairul haakimeen','page_number'=>161,'juz_number'=>8,'hizb_number'=>16,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>88,'arabic_text'=>'۞ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ','transliteration'=>'Qaalal mala-ul lazeenas takbaroo min qawmihee lanukhrijannaka yaa-Shu\'aibu wallazeena aamanoo ma\'aka min qaryatinaaa aw lata\'oo-dunna fee millatinaa; qaala awa-law kunnaa kaariheen','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>89,'arabic_text'=>'قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ','transliteration'=>'Qadif tarainaa \'alal laahi kaziban in \'udnaa fee millatikum ba\'da iz najjaanal laahu minhaa; Wa-maa yakoonu lanaaa an na\'ooda feehaaa illaaa ai yashaaa\'al laahu Rabbunaa; wasi\'a Rabbunaa kulla shai\'in \'ilmaa; \'alal laahi tawakkalnaa; Rabbanaf tah bainanaa Wa-baina qawminaa bilhaqqi Wa-Anta khairul faatiheen','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>90,'arabic_text'=>'وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ','transliteration'=>'Wa-qaalal mala-ul lazeena kafaroo min qawmihee la\'init taba\'tum Shu\'aiban innakum izal lakhaasiroon','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>91,'arabic_text'=>'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ','transliteration'=>'Fa-akhazat-humur rajfatu fa-asbahoo fee daarihim jaasimeen','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>92,'arabic_text'=>'ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ','transliteration'=>'Allazeena kazzaboo Shu\'aiban ka-al lam yaghnaw feehaa; allazeena kazzaboo Shu\'aiban kaanoo humul khaasireen','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>93,'arabic_text'=>'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ','transliteration'=>'Fatawalla \'anhum Wa-qaala yaa-qawmi laqad ablaghtukum Risaalaati Rabbee Wa-nasahtu lakum fakaifa aasaa \'alaa qawmin kaafireen','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>94,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ أَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ','transliteration'=>'Wa-maaa arsalnaa fee qaryatim min Nabiyyin illaaa akhaznaaa ahlahaa bil-ba\'saaa\'i waddarraaa\'i la\'allahum yaddarra\'oon','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>95,'arabic_text'=>'ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Summa baddalnaa makaa-nas saiyi\'atil hasanata hattaa \'afaw Wa-qaaloo qad massa aabaa\'anad darraaa\'u wassarraaa\'u fa-akhaznaahum baghtatanw Wa-hum laa yash\'uroon','page_number'=>162,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>96,'arabic_text'=>'وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Wa-law anna ahlal quraaa aamanoo wattaqaw lafatahnaa \'alaihim barakaatim minas samaaa\'i wal-ardi Wa-laakin kazzaboo fa-akhaznaahum bimaa kaanoo yaksiboon','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>97,'arabic_text'=>'أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا وَهُمۡ نَآئِمُونَ','transliteration'=>'Afa-amina ahlul quraaa ai ya\'tiyahum ba\'sunaa bayaatanw Wa-hum naaa\'imoon','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>98,'arabic_text'=>'أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحٗى وَهُمۡ يَلۡعَبُونَ','transliteration'=>'Awa-amina ahlul quraaa ai ya\'tiyahum ba\'sunaa duhanw Wa-hum yal\'aboon','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>99,'arabic_text'=>'أَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Afa-aminoo makral laah; falaa ya\'manu makral laahi illal qawmul khaasiroon','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>100,'arabic_text'=>'أَوَلَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ','transliteration'=>'Awa-lam yahdi lillazeena yarisoonal arda mim ba\'di ahlihaaa al law nashaaa\'u asabnaahum bizunoobihim; Wa-natba\'u \'alaa quloobihim fahum laa yasma\'oon','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>101,'arabic_text'=>'تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآئِهَاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ مِن قَبۡلُۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَٰفِرِينَ','transliteration'=>'Tilkal quraa naqussu \'alaika min ambaaa\'ihaa; Wa-laqad jaaa\'at-hum Rusuluhum bilbaiyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo min qabl; kazaalika yatba\'ul laahu \'alaa quloobil kaafireen','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>102,'arabic_text'=>'وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدٖۖ وَإِن وَجَدۡنَآ أَكۡثَرَهُمۡ لَفَٰسِقِينَ','transliteration'=>'Wa-maa wajadnaa li-aksarihim min \'ahd; Wa-inw wajadnaaa aksarahum lafaasiqeen','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>103,'arabic_text'=>'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ','transliteration'=>'Summa ba\'asnaa mim ba\'dihim Moosaa bi-Aayaatinaaa ilaa Fir\'awana Wa-mala\'ihee fazalamoo bihaa fanzur kaifa kaana \'aaqibatul mufsideen','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>104,'arabic_text'=>'وَقَالَ مُوسَىٰ يَٰفِرۡعَوۡنُ إِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-qaala Moosaa yaa-Fir\'awnu inneee Rasoolum mir Rabbil \'aalameen','page_number'=>163,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>105,'arabic_text'=>'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'Haqeequn \'alaaa al laaa aqoola \'alal laahi illal haqq; qad ji\'tukum bibaiyinatim mir Rabbikum fa-arsil ma\'iya Baneee Israaa\'eel','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>106,'arabic_text'=>'قَالَ إِن كُنتَ جِئۡتَ بِـَٔايَةٖ فَأۡتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaala in kunnta ji\'ta bi-Aayatin fa\'ti bihaa in kunnta minas saadiqeen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>107,'arabic_text'=>'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ','transliteration'=>'Fa-alqaa \'asaahu fa-izaa hiya su\'baanum mubeen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>108,'arabic_text'=>'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ','transliteration'=>'Wa-naza\'a yadahoo fa-izaa hiya baidaaa\'u linnaazireen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>109,'arabic_text'=>'قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ','transliteration'=>'Qaalal mala-u min qawmi Fir\'awna inna haazaa lasaahirun \'aleem','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>110,'arabic_text'=>'يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ','transliteration'=>'Yureedu ai yukhrijakum min ardikum famaazaa ta\'muroon','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>111,'arabic_text'=>'قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ','transliteration'=>'Qaalooo arjih Wa-akhaahu Wa-arsil fil madaaa\'ini haashireen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>112,'arabic_text'=>'يَأۡتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٖ','transliteration'=>'Ya\'tooka bikulli saahirin \'aleem','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>113,'arabic_text'=>'وَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ','transliteration'=>'Wa-jaaa\'as saharatu Fir\'awna qaaloo inna lanaa la-ajjran in kunnaa nahnul ghaalibeen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>114,'arabic_text'=>'قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِينَ','transliteration'=>'Qaala na\'am Wa-innakum laminal muqarrabeen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>115,'arabic_text'=>'قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ','transliteration'=>'Qaaloo yaa-Moosaaa immaaa an tulqiya Wa-immaaa an nakoona nahnul mulqeen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>116,'arabic_text'=>'قَالَ أَلۡقُواْۖ فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ','transliteration'=>'Qaala alqoo falam-maaa alqaw saharooo a\'yunan naasi wastarhaboohum Wa-jaaa\'oo bisihrin \'azeem','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>117,'arabic_text'=>'۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ','transliteration'=>'Wa-awhainaaa ilaa Moosaaa an alqi \'asaaka fa-izaa hiya talqafu maa ya\'fikoon','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>118,'arabic_text'=>'فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Fawaqa\'al haqqu Wa-batala maa kaanoo ya\'maloon','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>119,'arabic_text'=>'فَغُلِبُواْ هُنَالِكَ وَٱنقَلَبُواْ صَٰغِرِينَ','transliteration'=>'Faghuliboo hunaalika wanqalaboo saaghireen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>120,'arabic_text'=>'وَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ','transliteration'=>'Wa-ulqiyas saharatu saajideen','page_number'=>164,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>121,'arabic_text'=>'قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaaloo aamannaa bi-Rabbil \'aalameen','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>122,'arabic_text'=>'رَبِّ مُوسَىٰ وَهَٰرُونَ','transliteration'=>'Rabbi Moosaa Wa-Haaroon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>123,'arabic_text'=>'قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ لِتُخۡرِجُواْ مِنۡهَآ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ','transliteration'=>'Qaala Fir\'awnu aamantum bihee qabla an aazana lakum; inna haaza lamakrum makartumoohu fil madeenati litukhrijoo minhaaa ahlahaa fasawfa ta\'lamoon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>124,'arabic_text'=>'لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ','transliteration'=>'La-uqatti\'anna aidiyakum Wa-arjulakum min khilaafin summa la-usallibannakum ajma\'een','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>125,'arabic_text'=>'قَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ','transliteration'=>'Qaaloo innaaa ilaa Rabbinaa munqaliboon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>126,'arabic_text'=>'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ','transliteration'=>'Wa-maa tanqimu minnaaa illaaa an aamannaa bi-Aayaati Rabbinaa lammaa jaaa\'atnaa; Rabbanaaa afrigh \'alainaa sabranw Wa-tawaffanaa muslimeen','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>127,'arabic_text'=>'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِيُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَآءَهُمۡ وَنَسۡتَحۡيِۦ نِسَآءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَٰهِرُونَ','transliteration'=>'Wa-qaalal mala-u min qawmi Fir\'awna atazaru Moosaa Wa-qawmahoo liyufsidoo fil ardi Wa-yazaraka Wa-aalihatak; qaala sanuqattilu abnaaa\'ahum Wa-nastahyee nisaaa\'ahum Wa-innaa fawqahum qaahiroon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>128,'arabic_text'=>'قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ','transliteration'=>'Qaala Moosaa liqawmihis ta\'eenoo billaahi wasbiroo innal arda lillaahi yoorisuhaa mai yashaaa\'u min \'ibaadihee wal-\'aaqibatu lilmuttaqeen','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>129,'arabic_text'=>'قَالُوٓاْ أُوذِينَا مِن قَبۡلِ أَن تَأۡتِيَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ فَيَنظُرَ كَيۡفَ تَعۡمَلُونَ','transliteration'=>'Qaaloo oozeenaa min qabli an ta\'tiyanaa Wa-mim ba\'di maa ji\'tanaa; qaala \'asaa Rabbukum ai yuhlika \'aduwwakum Wa-yastakhli-fakum fil ardi fayanzura kaifa ta\'maloon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>130,'arabic_text'=>'وَلَقَدۡ أَخَذۡنَآ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِينَ وَنَقۡصٖ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَذَّكَّرُونَ','transliteration'=>'Wa-laqad akhaznaaa Aala Fir\'awna bis-sineena Wa-naqsim minas samaraati la\'allahum yazzakkaroon','page_number'=>165,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>131,'arabic_text'=>'فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Fa-izaa jaaa\'at-humul hasanatu qaaloo lanaa haazihee Wa-in tusibhum saiyi\'atuny yattaiyaroo bi-Moosaa Wa-mam ma\'ah; alaaa innamaa taaa\'iruhum \'indal laahi Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>132,'arabic_text'=>'وَقَالُواْ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَايَةٖ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ','transliteration'=>'Wa-qaaloo mahmaa taatinaa bihee min Aayatil litas\'haranaa bihaa famaa nahnu laka bimu\'mineen','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>133,'arabic_text'=>'فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ','transliteration'=>'Fa-arsalnaa \'alaihimut toofaana waljaraada walqum-mala waddafaadi\'a waddama Aayaatim mufassalaatin fastakbaroo Wa-kaanoo qawmam mujrimeen','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>134,'arabic_text'=>'وَلَمَّا وَقَعَ عَلَيۡهِمُ ٱلرِّجۡزُ قَالُواْ يَٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَئِن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'Wa-lammaa waqa\'a \'alaihimur rijzu qaaloo ya-Moosad-u lanaa rabbaka bimaa \'ahida \'indaka la\'in kashafta \'annar rijza lanu \'minanna laka Wa-lanursilanna ma\'aka Banee Israaa\'eel','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>135,'arabic_text'=>'فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمۡ يَنكُثُونَ','transliteration'=>'Falammaa kashafnaa \'anhumur rijza ilaaa ajalin hum baalighoohu izaa hum yankusoon','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>136,'arabic_text'=>'فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ','transliteration'=>'Fantaqamnaa minhum fa\'aghraqnaahum Fil\' yammi bi-Annahum kazzaboo bi-Aayaatinaa Wa-kaanoo \'anhaa ghaafileen','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>137,'arabic_text'=>'وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ','transliteration'=>'Wa-awrasnal qawmal lazeena kaanoo yustad\'afoona mashaariqal ardi Wa-maghaari-bahal latee baaraknaa feehaa Wa-tammat kalimatu Rabbikal husnaa \'alaa Baneee Israaa\'eela bimaa sabaroo Wa-dammarnaa maa kaana yasna\'u Fir\'awnu Wa-qawmuhoo Wa-maa kaanoo ya\'rishoon','page_number'=>166,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>138,'arabic_text'=>'وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ','transliteration'=>'Wa-jaawaznaa bi-Banneee Israaa\'eelal bahra fa-ataw \'alaa qawminy ya\'kufoona \'alaaa asnaamil lahum; qaaloo yaa-Moosaj \'al lanaa ilaahan kamaa lahum aalihah; qaala innakum qawmun tajhaloon','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>139,'arabic_text'=>'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٞ مَّا هُمۡ فِيهِ وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Innaa haaa\'ulaaa\'i mutabbarum maa hum feehi Wa-baatilum maa kaanoo ya\'maloon','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>140,'arabic_text'=>'قَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Qaala a-ghairal laahi abgheekum ilaahanw Wa-Huwa faddalakum \'alal \'aalameen','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>141,'arabic_text'=>'وَإِذۡ أَنجَيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُقَتِّلُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ','transliteration'=>'Wa-iz anjainaakum min Aali Fir\'awna yasoomoo-nakum sooo\'al \'azaab, yuqattiloona abnaaa\'akum Wa-yastahyoona nisaaa\'akum; Wa-fee zaalikum balaaa\'um mir Rabbikum \'azeem','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>142,'arabic_text'=>'۞ وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ وَأَتۡمَمۡنَٰهَا بِعَشۡرٖ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرۡبَعِينَ لَيۡلَةٗۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ','transliteration'=>'Wa-waa\'adnaa Moosaa salaaseena lailatanw Wa-at-mamnaahaa bi\'ashrim fatamma meeqaatu Rabbihee arba\'eena lailah; Wa-qaala Moosaa liakheehi Haaroonakh lufnee fee qawmee Wa-aslih Wa-laa tattabi\' sabeelal mufsideen','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>143,'arabic_text'=>'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-lammaa jaaa\'a Moosa limeeqaatinaa Wa-kallamahoo Rabbuhoo qaala Rabbi arineee anzur ilaik; qaala lan taraanee Wa-laakinin zur ilal jabali fa-inis taqarra makaanahoo fasawfa taraanee; falammaa tajallaa Rabbuhoo liljabali ja\'alahoo dakkanw Wa-kharra Moosaa sa\'iqaa; falammaaa afaaqa qaala Subhaanaka tubtu ilaika Wa-ana awwalul mu\'mineen','page_number'=>167,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>144,'arabic_text'=>'قَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي فَخُذۡ مَآ ءَاتَيۡتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ','transliteration'=>'Qaala yaa-Moosaaa innis tafaituka \'alan naasi bi-Risaalaatee Wa-bi-kalaamee fakhuz maaa aataituka Wa-kum minash shaakireen','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>145,'arabic_text'=>'وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءٖ مَّوۡعِظَةٗ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ فَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ','transliteration'=>'Wa-katabnaa lahoo fil alwaahi min kulli shai\'im maw\'izaanw Wa-tafseelal likulli shai\'in fakhuzhaa biquwwatinw wa\'mur qawmaka ya\'khuzoo bi-ahsanihaa; sa\'ooreekum daaral faasiqeen','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>146,'arabic_text'=>'سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ','transliteration'=>'Sa-asrifu \'an Aayaatiyal lazeena yatakabbaroona fil ardi bighairil haqq; Wa-iny yaraw kulla Aayatil laa yu\'minoo bihaa Wa-iny yaraw sabeelar rushdi laa yattakhizoohu sabeelanw Wa-iny yaraw sabeelal ghaiyi yattakhizoohu sabeelaa; zaalika bi-annahum kazzaboo bi-Aayaatinaa Wa-kaanoo \'anhaa ghaafileen','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>147,'arabic_text'=>'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلۡأٓخِرَةِ حَبِطَتۡ أَعۡمَٰلُهُمۡۚ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wallazeena kazzaboo bi-Aayaatinaa Wa-liqaaa\'il Aakhirati habitat \'amaaluhum; hal yujzawna illaa maa kaanoo ya\'maloon','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>148,'arabic_text'=>'وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِيِّهِمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٌۚ أَلَمۡ يَرَوۡاْ أَنَّهُۥ لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ سَبِيلًاۘ ٱتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ','transliteration'=>'Wattakhaza qawmu Moosaa mim ba\'dihee min huliyyihim \'ijlan jasadal lahoo khuwaar; alam yaraw annahoo laa yukallimuhum Wa-laa yahdeehim sabeelaa; ittakhazoohu Wa-kaanoo zaalimeen','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>149,'arabic_text'=>'وَلَمَّا سُقِطَ فِيٓ أَيۡدِيهِمۡ وَرَأَوۡاْ أَنَّهُمۡ قَدۡ ضَلُّواْ قَالُواْ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Wa-lammaa suqita feee aideehim Wa-ra aw-annahum qad dalloo qaaloo la\'il lam yarhamnaa Rabbunaa Wa-yaghfir lanaa lanakoonanna minal khaasireen','page_number'=>168,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>150,'arabic_text'=>'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي فَلَا تُشۡمِتۡ بِيَ ٱلۡأَعۡدَآءَ وَلَا تَجۡعَلۡنِي مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-lammaa raja\'a Moosaaa ilaa qawmihee ghadbaana asifan qaala bi\'samaa khalaftumoonee min ba\'dee \'a-\'ajiltum amra Rabbikum Wa-alqal alwaaha Wa-akhaza bira\'si akheehi yajurruhoo ilaiyh; qaalab na umma innal qawmas tad\'afoonee Wa-kadoo yaqtu-loonanee; falaa tushmit biyal a\'daaa\'a Wa-laa taj\'alnee ma\'al qawmiz zaalimeen','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>151,'arabic_text'=>'قَالَ رَبِّ ٱغۡفِرۡ لِي وَلِأَخِي وَأَدۡخِلۡنَا فِي رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ','transliteration'=>'Qaala Rabbigh fir lee Wa-li-akhee Wa-adkhilnaa fee rahmatika Wa-Anta arhamur raahimeen','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>152,'arabic_text'=>'إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ','transliteration'=>'Innal lazeenat takhazul \'ijla-sa yanaaluhum ghadabum mir Rabbihim Wa-zillatun fil hayaatid dunyaa; Wa-kazaalika najzil muftareen','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>153,'arabic_text'=>'وَٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُواْ مِنۢ بَعۡدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ','transliteration'=>'Wallazeena \'amilus saiyiaati summa taaboo min ba\'dihaa Wa-aamanooo inna Rabbaka min ba\'dihaa la-Ghafoorur Raheem','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>154,'arabic_text'=>'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ','transliteration'=>'Wa-lammaa sakata \'an Moosal ghadabu akhazal alwaaha Wa-fee nuskhatihaa hudanw Wa-rahmatul lil-lazeena hum li-Rabbihim yarhaboon','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>155,'arabic_text'=>'وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِينَ رَجُلٗا لِّمِيقَٰتِنَاۖ فَلَمَّآ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِيَّٰيَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآۖ إِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي مَن تَشَآءُۖ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ','transliteration'=>'Wakhtaara Moosaa qawmahoo sab\'eena rajulal li-meeqaatinaa falammaa akhazat-humur rajfatu qaala Rabbi law shi\'ta ahlaktahum min qablu Wa-iyyaay; \'a-tuhlikuna bimaa fa\'alas sufahaaa\'u minaa in hiya illaa fitnatuka tudillu bihaa man tashaaa\'u Wa-tahdee man tashaaa; Anta waliyyunaa faghfir lanaa warhamnaa Wa-Anta khairul ghaafireen','page_number'=>169,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>156,'arabic_text'=>'۞ وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءٖۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ','transliteration'=>'Waktub lanaa fee haazi-hid dunyaa hasanatanw Wa-fil Aakhirati innaa hudnaaa ilaik; qaala \'azaabee useebu bihee man ashaaa\'u Wa-rahmatee wasi\'at kulla shai\'; fasa-aktubuhaa lil-lazeena yattaqoona Wa-yu\'toonaz Zakaata wal-lazeena hum bi-Aayaatinaa yu\'minoon','page_number'=>170,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>157,'arabic_text'=>'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Allazeena yattabi\'oonar Rasoolan Nabiyyal ummiyyal lazee yajidoonahoo maktooban \'indahum fit Tawraati wal-Injeeli ya\'muruhum bilma\'roofi Wa-yanhaahum \'anil munkari Wa-yuhillu lahumul taiyibaati Wa-yuharrimu \'alaihimul khabaaa\'isa Wa-yada\'u \'anhum israhum wal-aghlaalal latee kaanat \'alaihim; fallazeena aamanoo bihee Wa-\'azzaroohu Wa-nasaroohu wattaba\'un nooral lazeee unzila ma\'ahooo ulaaa\'ika humul muflihoon','page_number'=>170,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>158,'arabic_text'=>'قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ ٱلَّذِي يُؤۡمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Qul yaaa-aiyuhan naasu innee Rasoolul laahi ilaikum jamee\'anil lazee lahoo mulkus samaawaati wal-ardi laaa ilaaha illaa Huwa yuhyee Wa-yumeetu fa-aaminoo billaahi Wa-Rasoolihin Nabiyyil ummiy-yil lazee yu\'minu billaahi Wa-Kalimaatihee wattabi\'oohu la\'allakum tahtadoon','page_number'=>170,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>159,'arabic_text'=>'وَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ','transliteration'=>'Wa-min qawmi Moosaaa ummatuny yahdoona bilhaqqi Wa-bihee ya\'diloon','page_number'=>170,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>160,'arabic_text'=>'وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا أُمَمٗاۚ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Wa-qatta\'naahumus natai \'ashrata asbaatan umamaa; Wa-awhainaa ilaa Moosaaa izis tasqaahu qawmuhooo anid rib bi\'asaakal hajara fambajasat minhus nata \'ashrata \'ainan qad \'alima kullu unaasim mashrabahum; Wa-zallalnaa \'alaihimul ghamaama Wa-anzalnaa \'alaihimul manna was-Salwaa kuloo min taiyibaati maa razaqnaakum; Wa-maa zalamoonaa Wa-laakin kaanooo anfusahum yazlimoon','page_number'=>171,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>161,'arabic_text'=>'وَإِذۡ قِيلَ لَهُمُ ٱسۡكُنُواْ هَٰذِهِ ٱلۡقَرۡيَةَ وَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ وَقُولُواْ حِطَّةٞ وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا نَّغۡفِرۡ لَكُمۡ خَطِيٓـَٰٔتِكُمۡۚ سَنَزِيدُ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-iz qeela lahumus kunoo haazihil qaryata Wa-kuloo minhaa haisu shi\'tum Wa-qooloo hittatunw wadkhulul baaba sujjadan naghfir lakum khateee\'aatikum; sanazeedul muhsineen','page_number'=>171,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>162,'arabic_text'=>'فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ','transliteration'=>'Fabaddalal lazeena zalamoo minhum qawlan ghairal lazee qeela lahum fa-arsalnaa \'alaihim rijzan minas samaaa\'i bimaa kaanoo yazlimoon','page_number'=>171,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>163,'arabic_text'=>'وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ','transliteration'=>'Was\'alhum \'anil qaryatil latee kaanat haadiratal bahri iz ya\'doona fis Sabti iz ta\'teehim heetaanuhum yawma Sabtihim shurra\'anw Wa-yawma laa yasbitoona laa ta\'teehim; kazaalika nabloohum bimaa kaanoo yafsuqoon','page_number'=>171,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>164,'arabic_text'=>'وَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ','transliteration'=>'Wa-iz qaalat ummatum minhum lima ta\'izoona qaw-manil laahu muhlikuhum aw mu\'azzibuhum \'azaaban shadeedan qaaloo ma\'ziratan ilaa Rabbikum Wa-la\'allahum yattaqoon','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>165,'arabic_text'=>'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ وَأَخَذۡنَا ٱلَّذِينَ ظَلَمُواْ بِعَذَابِۭ بَـِٔيسِۭ بِمَا كَانُواْ يَفۡسُقُونَ','transliteration'=>'Falammaa nasoo maa zukkiroo bihee anjainal lazeena yanhawna \'anis sooo\'i Wa-akhaznal lazeena zalamoo bi\'azaabim ba\'eesim bimaa kaanoo yafsuqoon','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>166,'arabic_text'=>'فَلَمَّا عَتَوۡاْ عَن مَّا نُهُواْ عَنۡهُ قُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ','transliteration'=>'Falammaa \'ataw \'am maa nuhoo \'anhu qulna lahum koonoo qiradatan khaasi\'een','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>167,'arabic_text'=>'وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَبۡعَثَنَّ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَن يَسُومُهُمۡ سُوٓءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-iz ta-azzana Rabbuka la-yab\'asannna \'alaihim ilaa Yawmil Qiyaamati mai yasoomuhum sooo\'al \'azaab; inna Rabbaka lasaree\'ul \'iqaabi Wa-innahoo la-Ghafoorur Raheem','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>168,'arabic_text'=>'وَقَطَّعۡنَٰهُمۡ فِي ٱلۡأَرۡضِ أُمَمٗاۖ مِّنۡهُمُ ٱلصَّٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَٰلِكَۖ وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-qatta\'naahum fil ardi umaman min-humus saalihoona Wa-min-hum doona zaalika Wa-balawnaahum bil-hasanaati was-saiyi\'aati la\'allahum yarji\'oon','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>169,'arabic_text'=>'فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ وَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ وَٱلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Fakhalafa min ba\'dihim khalfunw warisul Kitaaba ya\'khuzoona \'arada haazal adnaa Wa-yaqooloona sayughfaru lanaa Wa-iny ya\'tihim \'aradun misluhoo ya\'khuzooh; alam yu\'khaz \'alaihim meesaaqul Kitaabi an laa yaqooloo \'alal laahi illal haqqa Wa-darasoo maa feeh; wad-Daarul Aakhirtu khairul lil-lazeena yattaqoon; afalaa ta\'qiloon','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>170,'arabic_text'=>'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ','transliteration'=>'Wallazeena yumas-sikoona bil-Kitaabi Wa-aqaamus Salaata innaa laa nudeeu \'ajral musliheen','page_number'=>172,'juz_number'=>9,'hizb_number'=>17,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>171,'arabic_text'=>'۞ وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ','transliteration'=>'Wa-iz nataqnal jabala fawqahum ka-annahoo zullatunw Wa-zannooo annahoo waaqi\'un bihim khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>172,'arabic_text'=>'وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ شَهِدۡنَآۚ أَن تَقُولُواْ يَوۡمَ ٱلۡقِيَٰمَةِ إِنَّا كُنَّا عَنۡ هَٰذَا غَٰفِلِينَ','transliteration'=>'Wa-iz akhaza Rabbuka min Baneee Aadama min zuhoorihim zurriyyatahum Wa-ashhadahum \'alaa anfusihim alastu bi-Rabbikum qaaloo balaa shahidnaaa; an taqooloo Yawmal Qiyaamati innaa kunnaa \'an haazaa ghaafileen','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>173,'arabic_text'=>'أَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ ءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ','transliteration'=>'Aw taqoolooo innamaaa ashraka aabaaa\'unaa min qablu Wa-kunnaa zurriyyatan min ba\'dihim \'a-fa-tuhlikunaa bi-maa fa\'alal mubtiloon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>174,'arabic_text'=>'وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-kazaalika nufassilul Aayaati Wa-la\'allahum yarji\'oon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>175,'arabic_text'=>'وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ','transliteration'=>'Watlu \'alaihim naba allazeee aatainaahu Aayaatinaa fansalakha minhaa fa-atba\'a hush-Shaytaanoo fakaana minal ghaaween','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>176,'arabic_text'=>'وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّرُونَ','transliteration'=>'Wa-law shi\'naa larafa\'naahu bihaa Wa-laakin-nahooo akhlada ilal ardi wattaba\'a hawaah; famasaluhoo kamasalil kalbi in tahmil \'alaihi yalhas aw tatruk-hu yalhas; zaalika masalul qawmil lazeena kazzaboo bi-Aayaatinaa; faqsusil qasasa la\'allahum yatafakkaroon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>177,'arabic_text'=>'سَآءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَأَنفُسَهُمۡ كَانُواْ يَظۡلِمُونَ','transliteration'=>'Saaa\'a masalanil qawmul lazeena kazzaboo bi-Aayaatinaa Wa-anfusahum kaanoo yazlimoon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>178,'arabic_text'=>'مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ وَمَن يُضۡلِلۡ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Mai yahdil laahu fa-huwal muhtadee Wa-mai yudlil fa-ulaaa\'ika humul khaasiroon','page_number'=>173,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>179,'arabic_text'=>'وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ','transliteration'=>'Wa-laqad zara\'naa li-jahannama kaseeran minal jinni wal-insi lahum quloobul laa yafqahoona bihaa Wa-lahum a\'yunul laa yubisiroona bihaa Wa-lahum aazaanul laa yasma\'oona bihaa; ulaaa\'ika kal-an\'aami bal hum adall; ulaaa\'ika humul ghaafiloon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>180,'arabic_text'=>'وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-lillaahil Asmaaa-\'ul Husnaa fad\'oohu bihaa Wa-zarul lazeena yulhidoona feee Asmaaa\'ih; sa-yujzawna maa kaanoo ya\'maloon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>181,'arabic_text'=>'وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ','transliteration'=>'Wa-mimman khalaqnaaa ummatuny yahdoona bilhaqqi Wa-bihee ya\'diloon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>182,'arabic_text'=>'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ','transliteration'=>'Wallazeena kazzaboo bi-Aayaatinaa sanastadrijuhum min haisu laa ya\'lamoon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>183,'arabic_text'=>'وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ','transliteration'=>'Wa-umlee lahum; inna kaidee mateen','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>184,'arabic_text'=>'أَوَلَمۡ يَتَفَكَّرُواْۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ مُّبِينٌ','transliteration'=>'Awalam yatafakkaroo maa bisaahibihim min jinnah; in huwa illaa nazeerun mubeen','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>185,'arabic_text'=>'أَوَلَمۡ يَنظُرُواْ فِي مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ','transliteration'=>'Awalam yanzuroo fee malakootis samaawaati wal-ardi Wa-maa khalaqal laahu min shai\'inw Wa-an \'asaaa ai yakoona qadiq taraba ajaluhum fa-bi-ayyi hadeesin ba\'dahoo yu\'minoon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>186,'arabic_text'=>'مَن يُضۡلِلِ ٱللَّهُ فَلَا هَادِيَ لَهُۥۚ وَيَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','transliteration'=>'Mai yudlil lillaahu falaa haadiya lah; Wa-yazaruhum fee tughyaanihim ya\'mahoon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>187,'arabic_text'=>'يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّيۖ لَا يُجَلِّيهَا لِوَقۡتِهَآ إِلَّا هُوَۚ ثَقُلَتۡ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَةٗۗ يَسۡـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Yas\'aloonaka \'anis Saa\'ati aiyaana mursaahaa qul innamaa \'ilmuhaa \'inda Rabbee laa yujalleehaa liwaqtihaaa illaa Hoo; saqulat fis samaawaati wal-ard; laa ta\'teekum illaa baghtah; yas\'aloonaka ka-annaka hafiyyun \'anhaa qul innamaa \'ilmuhaa \'indal laahi Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>174,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>188,'arabic_text'=>'قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Qul laaa amliku linafsee naf\'anw Wa-laa darran illaa maa shaaa\'al laah; Wa-law kuntu a\'lamul ghaiba lastaksartu minal khairi Wa-maa massaniyas soo\'; in ana illaa nazeerunw Wa-basheerul liqawminy yu\'minoon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>189,'arabic_text'=>'۞ هُوَ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِيفٗا فَمَرَّتۡ بِهِۦۖ فَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ','transliteration'=>'Huwal lazee khalaqakum min nafsinw waahidatinw Wa-ja\'ala minhaa zawjahaa liyas-kuna ilaihaa falammaa taghash-shaahaa hamalat hamlan khafeefan famarrat bihee falammaaa asqalad da\'a-wal laaha Rabbahumaa la\'in aataitana saalihal lanakoonanna minash shaakireen','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>190,'arabic_text'=>'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ','transliteration'=>'Falammaaa aataahumaa saalihan ja\'alaa lahoo shurakaaa\'a feemaaa aataahumaa; fata\'aalal laahu \'ammaa yushrikoon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>191,'arabic_text'=>'أَيُشۡرِكُونَ مَا لَا يَخۡلُقُ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ','transliteration'=>'A-yushrikoona maa laa yakhluqu shai\'anw Wa-hum yukhlaqoon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>192,'arabic_text'=>'وَلَا يَسۡتَطِيعُونَ لَهُمۡ نَصۡرٗا وَلَآ أَنفُسَهُمۡ يَنصُرُونَ','transliteration'=>'Wa-laa yastatee\'oona lahum nasranw Wa-laaa anfusahum yansuroon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>193,'arabic_text'=>'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَتَّبِعُوكُمۡۚ سَوَآءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَٰمِتُونَ','transliteration'=>'Wa-in tad\'oohum ilal hudaa laa yattabi\'ookum; sawaaa\'un \'alaikum a-da\'awtumoohum \'am antum saamitoon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>194,'arabic_text'=>'إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Innal lazeena tad\'oona min doonil laahi \'ibaadun amsaalukum fad\'oohum fal-yastajeeboo lakum in kuntum saadiqeen','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>195,'arabic_text'=>'أَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ','transliteration'=>'A-lahum arjuluny yamshoona bihaa \'am lahum \'aidiny yabtishoona bihaaa \'am lahum a\'yunuy yubsiroona bihaaa \'am lahum aazaanuny yasma\'oona bihaa; qulid \'oo shurakaaa\'akum thumma keedooni falaa tunziroon','page_number'=>175,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>196,'arabic_text'=>'إِنَّ وَلِـِّۧيَ ٱللَّهُ ٱلَّذِي نَزَّلَ ٱلۡكِتَٰبَۖ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ','transliteration'=>'Inna waliyyial laahul lazee nazzalal Kitaaba Wa-Huwa yatawallas saaliheen','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>197,'arabic_text'=>'وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ أَنفُسَهُمۡ يَنصُرُونَ','transliteration'=>'Wallazeena tad\'oona min doonihee laa yastatee\'oona nasrakum Wa-laaa anfusahum yansuroon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>198,'arabic_text'=>'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَسۡمَعُواْۖ وَتَرَىٰهُمۡ يَنظُرُونَ إِلَيۡكَ وَهُمۡ لَا يُبۡصِرُونَ','transliteration'=>'Wa-in tad\'oohum ilal hudaa laa yasma\'oo Wa-taraahum yanzuroona ilaika Wa-hum laa yubsiroon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>199,'arabic_text'=>'خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ','transliteration'=>'Khuzil \'afwa Wa-mur bil\'urfi Wa-A\'rid \'anil jaahileen','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>200,'arabic_text'=>'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ','transliteration'=>'Wa-immaa yanzaghannaka minash Shaitaani nazghun fasta\'iz billaah; innahoo Samee\'un Aleem','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>201,'arabic_text'=>'إِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ','transliteration'=>'Innal lazeenat taqaw izaa massahum taaa\'ifun minash Shaitaani tazakkaroo fa-izaa hum mubsiroon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>202,'arabic_text'=>'وَإِخۡوَٰنُهُمۡ يَمُدُّونَهُمۡ فِي ٱلۡغَيِّ ثُمَّ لَا يُقۡصِرُونَ','transliteration'=>'Wa-ikhwaanuhum yamuddoonahum fil ghayyi thumma laa yuqsiroon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>203,'arabic_text'=>'وَإِذَا لَمۡ تَأۡتِهِم بِـَٔايَةٖ قَالُواْ لَوۡلَا ٱجۡتَبَيۡتَهَاۚ قُلۡ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَيَّ مِن رَّبِّيۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Wa-izaa lam ta\'tihim bi-aayatin qaaloo law-laj tabai-tahaa; qul innamaaa attabi\'u maa yoohaaa ilaiya mir Rabbee; haazaa basaaa\'iru mir Rabbikum Wa-hudanw Wa-rahmatul liqawminy yu\'minoon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>204,'arabic_text'=>'وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Wa-izaa quri\'al Quraanu fastami\'oo lahoo Wa-ansitoo la-\'allakum turhamoon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>205,'arabic_text'=>'وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ','transliteration'=>'Wazkur Rabbaka fee nafsika tadarru\'anw Wa-kheefatanw Wa-doonal jahri minal qawli bilghuduwwi wal-aasali Wa-laa takum minal ghaafileen','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>7,'ayah_number'=>206,'arabic_text'=>'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسۡجُدُونَۤ','transliteration'=>'Innal lazeena \'inda Rabbika laa yastakbiroona \'an \'ibaadatihee Wa-yusabbihoonahoo Wa-lahoo yasjudoon','page_number'=>176,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>true],
            /* Surah 8: The Spoils of War (Al-Anfal) */
            ['surah_id'=>8,'ayah_number'=>1,'arabic_text'=>'يَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Yas\'aloonaka \'anil anfaali qulil anfaalu lillaahi war-Rasooli fattaqul laaha Wa-aslihoo zaata bainikum Wa-atee\'ul laaha Wa-Rasoolahooo in kuntum mu\'mineen','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>2,'arabic_text'=>'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','transliteration'=>'Innamal mu\'minoonal lazeena izaa zukiral laahu wajilat quloobuhum Wa-izaa tuliyat \'alaihim Aayaatuhoo zaadat-hum eemaananw Wa-\'alaa Rabbihim yatawakkaloon','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>3,'arabic_text'=>'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','transliteration'=>'Allazeena yuqeemoonas Salaata Wa-mimmaa razaqnaahum yunfiqoon','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>4,'arabic_text'=>'أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ','transliteration'=>'Ulaaa\'ika humul mu\'minoona haqqaa; lahum darajaatun \'inda Rabbihim Wa-magh-firatunw Wa-rizqun kareem','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>5,'arabic_text'=>'كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ','transliteration'=>'Kaamaaa akhrajaka Rabbuka mim baitika bilhaqq; Wa-inna fareeqam minal mu\'mineena lakaarihoon','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>6,'arabic_text'=>'يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ','transliteration'=>'Yujaadiloonaka fil haqqi ba\'da maa tabaiyana kaannamaa yasaaqoona ilal mawti Wa-hum yanzuroon','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>7,'arabic_text'=>'وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-iz ya\'idukumul laahu ihdat taaa\'ifataini annahaa lakum Wa-tawaddoona anna ghaira zaatish shawkati takoonu lakum Wa-yureedul laahu ai yuhiqqal haqqa bikalimaatihee Wa-yaqta\'a daabiral kaafireen','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>8,'arabic_text'=>'لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ','transliteration'=>'Liyuhiqqal haqqa Wa-tubtilal baatila Wa-law karihal mujrimoon','page_number'=>177,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>9,'arabic_text'=>'إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ','transliteration'=>'Iz tastagheesoona Rabbakum fastajaaba lakum annee mumiddukum bi-alfim minal malaaa\'ikati murdifeen','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>10,'arabic_text'=>'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','transliteration'=>'Wa-maa ja\'alahul laahu illaa bushraa Wa-litatma\'inna bihee quloobukum; Wa-man nasru illaa min \'indil laah; innal laaha Azeezun Hakeem','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>11,'arabic_text'=>'إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ','transliteration'=>'Iz yughashsheekumun nu\'assa amanatam minhu Wa-yunazzilu \'alaikum minas samaaa\'i maaa\'al liyutah-hirakum bihee Wa-yuzhiba \'ankum rijzash Shaitaani Wa-liyarbita \'ala quloobikum Wa-yusabbita bihil aqdaam','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>12,'arabic_text'=>'إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ','transliteration'=>'Iz yoohee Rabbuka ilal malaaa\'ikati annee ma\'akum fasabbitul lazeena aamanoo; sa-ulqee fee quloobil lazeena kafarur ru\'ba fadriboo fawqal a\'naaqi wadriboo minhum kulla banaan','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>13,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Zaalika bi-annahum shaaaqqul laaha Wa-Rasoolah; Wa-mai yushaqiqil laaha Wa-Rasoolahoo fa-innal laaha shadeedul \'iqaab','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>14,'arabic_text'=>'ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ','transliteration'=>'Zaalikum fazooqoohu Wa-anna lilkaafireena \'azaaban Naar','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>15,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo izaa laqeetumul lazeena kafaroo zahfan falaa tuwalloohumul adbaar','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>16,'arabic_text'=>'وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Wa-mai yuwallihim yawma\'izin duburahooo illaa mutaharrifal liqitaalin aw mutahaiyizan ilaa fi\'atin faqad baaa\'a bighadabim minal laahi Wa-ma\'waahu Jahannamu Wa-bi\'sal maseer','page_number'=>178,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>17,'arabic_text'=>'فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Falam taqtuloohum Wa-laakinnal laaha qatalahum; Wa-maa ramaita iz ramaita Wa-laakinnal laaha ramaa; Wa-liyubliyal mu\'mineena minhu balaaa\'an hasanaa; innal laaha Samee\'un Aleem','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>18,'arabic_text'=>'ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ','transliteration'=>'Zaalikum Wa-annal laaha moohinu kaidil kaafireen','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>19,'arabic_text'=>'إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'In tastaftihoo faqad jaaa\'akumul fathu Wa-in tantahoo fahuwa khairul lakum Wa-in ta\'oodoo na\'ud Wa-lan tughniya \'ankum fi\'atukum shai\'anw Wa-law kasurat Wa-annal laaha ma\'al mu\'mineen','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>20,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo atee\'ul laaha Wa-Rasoolahoo Wa-laa tawallaw \'anhu Wa-antum tasma\'oon','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>21,'arabic_text'=>'وَلَا تَكُونُواْ كَٱلَّذِينَ قَالُواْ سَمِعۡنَا وَهُمۡ لَا يَسۡمَعُونَ','transliteration'=>'Wa-laa takoonoo kallazeena qaaloo sami\'naa Wa-hum laa yasma\'oon','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>22,'arabic_text'=>'۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ','transliteration'=>'Inna sharrad dawaaabbi \'indal laahis summul bukmul lazeena laa ya\'qiloon','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>23,'arabic_text'=>'وَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ','transliteration'=>'Wa-law \'alimal laahu feehim khairal la-asma\'ahum; Wa-law asma\'ahum latawallaw Wa-hum mu\'ridoon','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>24,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥٓ إِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanus tajeeboo lillaahi Wa-lir-Rasooli izaa da\'aakum limaa yuhyeekum wa\'lamooo annal laaha yahoolu bainal mar\'i Wa-qalbihee Wa-anahooo ilaihi tuhsharoon','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>25,'arabic_text'=>'وَٱتَّقُواْ فِتۡنَةٗ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُواْ مِنكُمۡ خَآصَّةٗۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Wattaqoo fitnatal laa tuseebannal lazeena zalamoo minkum khaaaassatanw wa\'lamooo annal laaha shadeedul \'iqaab','page_number'=>179,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>26,'arabic_text'=>'وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ مُّسۡتَضۡعَفُونَ فِي ٱلۡأَرۡضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَيَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wazkurooo iz antum qaleelum mustad-\'afoona fil ardi takhaafoona ai yatakhat-tafakumun naasu fa-aawaakum Wa-aiyadakum binasrihee Wa-razaqakum minat taiyibaati la\'allakum tashkuroon','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>27,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanoo laa takhoonal laaha war-Rasoola Wa-takhoonooo amaanaatikum Wa-antum ta\'lamoon','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>28,'arabic_text'=>'وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ','transliteration'=>'Wa\'lamooo annamaaa amwaalukum Wa-awlaadukum fitnatunw Wa-annal laaha \'indahooo ajrun azeem','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>29,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Yaaa-aiyuhal lazeena aamanooo in tattaqul laaha yaj\'al lakum furqaananw Wa-yukaffir \'ankum saiyi-aatikum Wa-yaghfir lakum; wallaahu zul fadlil \'azeem','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>30,'arabic_text'=>'وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ','transliteration'=>'Wa-iz yamkuru bikal lazeena kafaroo liyusbitooka aw yaqtulooka aw yukhrijook; Wa-yamkuroona Wa-yamkurul laahu wallaahu khairul maakireen','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>31,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا قَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Wa-izaa tutlaa \'alaihim Aayaatunaa qaaloo qad sami\'naa law nashaaa\'u laqulnaa misla haazaaa in haazaaa illaaa asaateerul awwaleen','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>32,'arabic_text'=>'وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ','transliteration'=>'Wa-iz qaalul laahumma in kaana haazaa huwal haqqa min \'indika fa-amtir \'alainaa hijaaratam minas samaaa\'i awi \'tinaa bi-\'azaabin aleem','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>33,'arabic_text'=>'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ','transliteration'=>'Wa-maa kaanal laahu liyu\'az-zibahum Wa-anta feehim; Wa-maa kaanal laahu mu\'az-zibahum Wa-hum yastaghfiroon','page_number'=>180,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>34,'arabic_text'=>'وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-maa lahum allaa yu\'az-zibahumul laahu Wa-hum yasuddoona \'anil Masjidil Haraami Wa-maa kaanooo awliyaaa\'ah; in awliyaaa\'-uhooo illal muttaqoona Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>35,'arabic_text'=>'وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ','transliteration'=>'Wa-maa kaana Salaatuhum \'indal Baiti illa mukaaa-anw wa-tasdiyah; fazooqul \'azaaba bimaa kuntum takfuroon','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>36,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ','transliteration'=>'Innal lazeena kafaroo yunfiqoona amwaalahum liyasuddoo \'an sabeelil laah; fasayunfiqoonahaa summa takoonu \'alaihim hasratan summa yughlaboon; wal-lazeena kafarooo ilaa Jahannnama yuhsharoona','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>37,'arabic_text'=>'لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجۡعَلَ ٱلۡخَبِيثَ بَعۡضَهُۥ عَلَىٰ بَعۡضٖ فَيَرۡكُمَهُۥ جَمِيعٗا فَيَجۡعَلَهُۥ فِي جَهَنَّمَۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Liyameezal laahul khabeesa minat taiyibi Wa-yaj\'alal khabeesa ba\'dahoo \'ala ba\'din fayarkumahoo jamee\'an fayaj\'alahoo fee Jahannnam; ulaaa\'ika humul khaasiroon','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>38,'arabic_text'=>'قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ','transliteration'=>'Qul lillazeena kafarooo iny yantahoo yughfar lahum maa qad salafa Wa-iny ya\'oodoo faqad madat sunnatul awwaleen','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>39,'arabic_text'=>'وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Wa-qaatiloohum hattaa laa takoona fitnatunw Wa-yakoonad deenu kulluhoo lillaah; fainin tahaw fa-innal laaha bimaa ya\'maloona Baseer','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>40,'arabic_text'=>'وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ','transliteration'=>'Wa-in tawallaw fa\'lamooo annal laaha mawlaakum; ni\'mal mawlaa Wa-ni\'man naseer','page_number'=>181,'juz_number'=>9,'hizb_number'=>18,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>41,'arabic_text'=>'۞ وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Wa\'lamooo annamaa ghanimtum min sha\'in fa-anna lillaahi khumusahoo Wa-lir-Rasooli Wa-lizil qurba walyataamaa walmasaakeeni wabnis sabeeli in kuntum aamantum billaahi Wa-maaa anzalnaa \'ala \'abdinaa yawmal Furqaani yawmal taqal jam\'aan; wal-laahu \'alaa kulli shai\'in Qadeer','page_number'=>182,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>42,'arabic_text'=>'إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ','transliteration'=>'Iz antum bil\'udwatid dunyaa Wa-hum bil\'udwatil quswaa warrakbu asfala minkum; Wa-law tawaa\'attum lakhtalaftum fil mee\'aadi Wa-laakil liyaqdiyal laahu amran kaana maf\'oolal liyahlika man halaka \'am baiyinatinw Wa-yahyaa man haiya \'am baiyinah; Wa-innal laaha la-Samee\'un \'Aleem','page_number'=>182,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>43,'arabic_text'=>'إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Iz yureekahumul laahu fee manaamika qaleela; Wa-law araakahum kaseeral lafashiltum Wa-latanaaza\'tum fil amri Wa-laakinnal laaha sallam; innahoo \'aleemum bizaatis sudoor','page_number'=>182,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>44,'arabic_text'=>'وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ لِيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Wa-iz yureekumoohum izil taqaitum feee a\'yunikum qaleelanw Wa-yuqallilukum feee a\'yunihim liyaqdiyal laahu amran kaana maf\'oolaa; Wa-ilal laahi turja\'ul umoor','page_number'=>182,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>45,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-aiyuhal lazeena aamanooo izaa laqeetum fi\'atan fasbutoo wazkurul laaha kaseeral la\'allakum tuflihoon','page_number'=>182,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>46,'arabic_text'=>'وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ','transliteration'=>'Wa-atee\'ul laaha Wa-Rasoolahoo Wa-laa tanaaza\'oo fatafshaloo Wa-tazhaba reehukum wasbiroo; innal laaha ma\'as saabireen','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>47,'arabic_text'=>'وَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ','transliteration'=>'Wa-laa takoonoo kallazeena kharajoo min diyaarihim bataranw Wa-ri\'aaa\'an naasi Wa-yasuddoona \'an sabeelil laah; wallaahu bimaa ya\'maloona muheet','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>48,'arabic_text'=>'وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Wa-iz zaiyana lahumush shaitaanu a\'ma-alahum Wa-qaala laa ghaaliba lakumul yawma minan naasi Wa-innee jaarul lakum falammaa taraaa\'atil fi\'ataani nakasa \'alaa aqibaihi Wa-qaala innee bareee\'um minkum innee araa maa laa tarawna inneee akhaaful laah; wallaahu shadeedul \'iqaab','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>49,'arabic_text'=>'إِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمۡۗ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ','transliteration'=>'Iz yaqoolul munaafiqoona wallazeena fee quloobihim maradun gharra haaa\'ulaaa\'i deenuhum; Wa-mai yatawakkal \'alal laahi fa-innal laaha \'azee-zun Hakeem','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>50,'arabic_text'=>'وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ','transliteration'=>'Wa-law taraaa iz yatawaf-fal lazeena kafarul malaaa\'ikatu yadriboona wujoohahum Wa-adbaarahum Wa-zooqoo \'azaabal hareeq','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>51,'arabic_text'=>'ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمٖ لِّلۡعَبِيدِ','transliteration'=>'Zaalika bimaa qaddamat aideekum Wa-anal laaha laisa bizallaamil lil-\'abeed','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>52,'arabic_text'=>'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Kadaabi Aali Fir\'awna wal-lazeena min qablihim; kafaroo bi-Aayaatil laahi fa-akhazahu-mul laahu bizunoobihim; innal laaha qawiyyun shadeedul \'iqaab','page_number'=>183,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>53,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Zaalika bi-annal laaha lam yakumu ghaiyiran ni\'matan an\'amahaa \'alaa qawmin hattaa yughaiyiroo maa bianfusihim Wa-annal laaha samee\'un \'Aleem','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>54,'arabic_text'=>'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَۚ وَكُلّٞ كَانُواْ ظَٰلِمِينَ','transliteration'=>'Kadaabi Aali Fir\'awna wallazeena min qablihim; kazzaboo bi-Aayaati Rabbihim faahlaknaahum bizunoobihim Wa-aghraqnaa Aala Fir\'awn; Wa-kullun kaanoo zaalimeen','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>55,'arabic_text'=>'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Inna sharrad dawaaabbi \'indal laahil lazeena kafaroo fahum laa yu\'minoon','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>56,'arabic_text'=>'ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ','transliteration'=>'Allazeena \'aahatta min-hum summa yanqudoona \'ahdahum fee kulli marratinw Wa-hum laa yattaqoon','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>57,'arabic_text'=>'فَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ','transliteration'=>'Fa-immaa tasqafannahum fil harbi fasharrid bihim man khalfahum la\'allahum yazzakkaroon','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>58,'arabic_text'=>'وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ','transliteration'=>'Wa-immaa takhaafana min qawmin khiyaanatan fambiz ilaihim \'alaa sawaaa\'; innal laaha laa yuhibbul khaaa\'ineen','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>59,'arabic_text'=>'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ سَبَقُوٓاْۚ إِنَّهُمۡ لَا يُعۡجِزُونَ','transliteration'=>'Wa-laa yahsabannal lazeena kafaroo sabaqooo; innahum laa yu\'jizoon','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>60,'arabic_text'=>'وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ','transliteration'=>'Wa-a\'iddoo lahum mas tata\'tum min quwwatinw Wa-mir ribaatil khaili turhiboona bihee \'aduwwal laahi Wa-\'aduwwakum Wa-aakhareena min doonihim laa ta\'lamoo-nahum Allaahu ya\'lamuhum; Wa-maa tunfiqoo min shai\'in fee sabeelil laahi yuwaffa ilaikum Wa-antum laa tuzlamoon','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>61,'arabic_text'=>'۞ وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-in janahoo lissalmi fajnah lahaa Wa-tawakkal \'alal laah; innahoo Huwas Samee\'ul \'Aleem','page_number'=>184,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>62,'arabic_text'=>'وَإِن يُرِيدُوٓاْ أَن يَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِيٓ أَيَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-iny yureedooo any yakhda\'ooka fainna hasbakal laah; Huwal lazeee aiyadaka binasrihee Wa-bilmu\'mineen','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>63,'arabic_text'=>'وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wa-allafa baina quloobihim; law anfaqta maa fil ardi jamee\'am maaa allafta baina quloobihim Wa-laakinnal laaha allafa bainahum; innaahoo \'Azeezun Hakeem','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>64,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Yaaa-aiyuhan Nabiyyu hasbukal laahu Wa-manit taba\'aka minal mu\'mineen','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>65,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ','transliteration'=>'Yaaa-aiyuhan Nabiyyu harridil mu\'mineena \'alal qitaal; iny yakum minkum \'ishroona saabiroona yaghliboo mi\'atayn; Wa-iny yakum minkum min\'atuny yaghlibooo alfam minal lazeena kafaroo bi-anahum qawmul laa yafqahoon','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>66,'arabic_text'=>'ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ','transliteration'=>'Al\'aana khaffafal laahu \'ankum Wa-\'alima anna feekum da\'faa; fa-iny yakum minkum mi\'atun saabiratuny yaghliboo mi\'atayn; Wa-iny yakum minkum alfuny yaghlibooo alfaini bi-iznil laah; wallaahu ma\'as saabireen','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>67,'arabic_text'=>'مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ','transliteration'=>'Maa kaana li-Nabiyyin ai yakoona lahooo asraa hatta yuskhina fil ard; tureedoona aradad dunyaa wallaahu yureedul Aakhirah; wallaahu \'Azeezun Hakeem','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>68,'arabic_text'=>'لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Law-laa Kitaabum minal laahi sabaqa lamassakum fee-maaa akhaztum \'azaabun \'azeem','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>69,'arabic_text'=>'فَكُلُواْ مِمَّا غَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Fakuloo mimaa ghanimtum halaalan taiyibaa; watta qullaah; innal laaha Ghafoorur Raheem','page_number'=>185,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>70,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّمَن فِيٓ أَيۡدِيكُم مِّنَ ٱلۡأَسۡرَىٰٓ إِن يَعۡلَمِ ٱللَّهُ فِي قُلُوبِكُمۡ خَيۡرٗا يُؤۡتِكُمۡ خَيۡرٗا مِّمَّآ أُخِذَ مِنكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Yaaa-aiyuhan Nabiyyu qul liman feee aideekum minal asraaa iny ya\'lamil laahu fee quloobikum khairany yu\'tikum khayram mimmaaa ukhiza minkum Wa-yaghfir lakum; wallaahu Ghafoorur Raheem','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>71,'arabic_text'=>'وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','transliteration'=>'Wa-iny yureedoo khiyaa-nataka faqad khaanul laaha min qablu fa-amkana minhum; wallaahu \'Aleemun Hakeem','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>72,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Innal lazeena aamanoo Wa-haajaroo Wa-jaahadoo bi-amwaalihim Wa-anfusihim fee sabeelil laahi wallazeena aawaw Wa-nasarooo ulaaa\'ika ba\'duhum awliyaaa\'u ba\'d; wallazeena aamanoo Wa-lam yuhaajiroo maa lakum minw walaayatihim min shai\'in hatta yuhaajiroo; Wa-inis tansarookum fid deeni fa\'alaiku munnasru illaa \'alaa qawmin bainakum Wa-bainahum meesaaq; wallaahu bimaa ta\'maloona Baseer','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>73,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ','transliteration'=>'Wallazeena kafaroo ba\'duhum awliyaaa\'u ba\'d; illaa taf\'aloohu takun fitnatun fil ardi Wa-fasaadun kabeer','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>74,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ','transliteration'=>'Wallazeena aamanoo Wa-haajaroo Wa-jaahadoo fee sabeelil laahi wallazeena aawaw Wa-nasarooo ulaaa\'ika humul mu\'minoona haqqaa; lahum maghfiratunw Wa-rizqun kareem','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>8,'ayah_number'=>75,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ','transliteration'=>'Wallazeena aamanoo min ba\'du Wa-haajaroo Wa-jaahadoo ma\'akum fa-Ulaaa\'ika minkum; Wa-ulul arhaami baduhum awlaa biba\'din fee Kitaabil laah; innal laaha bikulli shai\'in \'Aleem','page_number'=>186,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            /* Surah 9: The Repentance (At-Tawbah) */
            ['surah_id'=>9,'ayah_number'=>1,'arabic_text'=>'بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Baraaa\'atum minal laahi Wa-Rasooliheee ilal lazeena \'aahattum minal mushrikeen','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>2,'arabic_text'=>'فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ','transliteration'=>'Faseehoo fil ardi arba\'ata ashhurinw wa\'lamooo annakum ghairu mu\'jizil laahi Wa-annal laaha mukhzil kaafireen','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>3,'arabic_text'=>'وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ','transliteration'=>'Wa azaanum minal laahi Wa-Rasooliheee ilan naasi yawmal Hajjil Akbari annal laaha bareee\'um minal mushrikeena Wa-Rasooluh; fa-in tubtum fahuwa khairullakum Wa-in tawallaitum fa\'lamooo annakum ghairu mu\'jizil laah; Wa-bashiril lazeena kafaroo biazaabin aleem','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>4,'arabic_text'=>'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ شَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ','transliteration'=>'Illal lazeena \'aahattum minal mushrikeena summa lam yanqusookum shai\'anw-wa lam yuzaahiroo \'alaikum ahadan fa-atimmooo ilaihim \'ahdahum ilaa muddatihim; innal laaha yuhibbul muttaqeen','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>5,'arabic_text'=>'فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Fa izansalakhal Ashhurul Hurumu faqtulul mushrikeena haisu wajattumoohum Wa-khuzoohum wahsuroohum waq\'udoo lahum kulla marsad; fa-in taaboo Wa-aqaamus Salaata Wa-aatawuz Zakaata fakhalloo sabeelahum; innal laaha Ghafoorur Raheem','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>6,'arabic_text'=>'وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ','transliteration'=>'Wa-in ahadum minal mushrikeenas tajaaraka fa-ajirhu hattaa yasma\'a Kalaamal laahi summa ablighhu ma-manah; zaalika bi-annahum qawmul laa ya\'lamoon','page_number'=>187,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>7,'arabic_text'=>'كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ','transliteration'=>'Kaifa yakoonu lilmush-rikeena \'ahdun \'indal laahi Wa-\'inda Rasoolihee illal lazeena \'aahattum \'indal Masjidil Haraami famas taqaamoo lakum fastaqeemoo lahum; innal laaha yuhibbul muttaqeen','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>8,'arabic_text'=>'كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا وَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَٰسِقُونَ','transliteration'=>'Kaifa Wa-iny-yazharoo \'alaikum laa yarquboo feekum illanw Wa-laa zimmah; yurdoo nakum biafwaahihim Wa-ta\'baa quloobuhum Wa-aksaruhum faasiqoon','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>9,'arabic_text'=>'ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ishtaraw bi-Aayaatil laahi samanan qaleelan fasaddoo \'an sabeelih; innahum saaa\'a maa kaanoo ya\'maloon','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>10,'arabic_text'=>'لَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ','transliteration'=>'Laa yarquboona fee mu\'minin illanw Wa-laa zimmah Wa-ulaaa\'ika humul mu\'tadoon','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>11,'arabic_text'=>'فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Fa-in taaboo Wa-aqaamus Salaata Wa-aatawuz Zakaata fa-ikhwaanukum fid deen; Wa-nufassilul Aayaati liqawminy ya\'lamoon','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>12,'arabic_text'=>'وَإِن نَّكَثُوٓاْ أَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ','transliteration'=>'Wa-in nakasooo aimaanahum mim ba\'di \'ahdihim Wa-ta\'anoo fee deenikum faqaatilooo a\'immatal kufri innahum laaa aimaana lahum la\'allahum yantahoon','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>13,'arabic_text'=>'أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Alaa tuqaatiloona qawman nakasooo aimaanahum Wa-hammoo bi-ikhraajir Rasooli Wa-hum bada\'ookum awwala marrah; atakhshawnahum; fallaahu ahaqqu an takhshawhu in kuntum mu\'mineen','page_number'=>188,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>14,'arabic_text'=>'قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ','transliteration'=>'Qaatiloohum yu\'az-zibhumul laahu bi-aideekum Wa-yukhzihim Wa-yansurkum \'alaihim Wa-yashfi sudoora qawmim mu-\'mineen','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>15,'arabic_text'=>'وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','transliteration'=>'Wa yuzhib ghaiza quloobihim; Wa-yatoobullaahu \'alaa mai yashaaa\'; wallaahu \'Aleemun Hakeem','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>16,'arabic_text'=>'أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ وَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Am hasibtum an tutrakoo Wa-lammaa ya\'lamil laahul lazeena jaahadoo minkum Wa-lam yattakhizoo min doonil laahi Wa-laa Rasoolihee Wa-lal mu\'mineena waleejah; wallaahu khabeerum bimaa ta\'maloon','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>17,'arabic_text'=>'مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ','transliteration'=>'maa kaana lilmushrikeena ai ya\'muroo masaajidal laahi shaahideena \'alaaa anfusihim bilkufr; ulaaa\'ika habitat a\'maaluhum Wa-fin naari hum khaalidoon','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>18,'arabic_text'=>'إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ','transliteration'=>'Innamaa ya\'muru masaa-jidal laahi man aamana billaahi wal-Yawmil Aakhiri Wa-aqaamas Salaata Wa-aataz Zakaata Wa-lam yakhshaa illal laaha fa\'asaaa ulaaa\'ika aien yakoonoo minal muhtadeen','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>19,'arabic_text'=>'۞ أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Aja\'altum siqaayatal haaajji Wa-\'imaaratal masjidil haraami kamman aamana billaahi wal-Yawmil Aakhiri Wa-jaahada fee sabeelil laah; laa yastawoona \'indal laah; wallaahu laa yahdil qawmaz zaalimeen','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>20,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ','transliteration'=>'Allazeena aamanoo Wa-haajaroo Wa-jaahadoo fee sabeelil laahi bi-amwaalihim Wa-anfusihim a\'zamu darajatan \'indal laah; Wa-ulaaa\'ika humul faaa\'izoon','page_number'=>189,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>21,'arabic_text'=>'يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ','transliteration'=>'Yubashshiruhum Rabbuhum birahmatim minhu Wa-ridwaaninw Wa-Jannaatil lahum feehaa na\'eemum muqeem','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>22,'arabic_text'=>'خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ','transliteration'=>'Khaalideena feehaaa abadaa; innal laaha \'indahooo ajrun \'azeem','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>23,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tattakhizooo aabaaa-\'akum Wa-ikhwaanakum awliyaaa\'a inis tahabbul kufra \'alal eemaan; Wa-maien yatawal-lahum minkum fa-ulaaa\'ika humuz zaalimoon','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>24,'arabic_text'=>'قُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ','transliteration'=>'Qul in kaana aabaaa\'ukum Wa-abnaaa\'ukum Wa-ikhwaanukum Wa-azwaajukum Wa-\'asheeratukum Wa-amwaaluniq taraftumoohaa Wa-tijaaratun takhshawna kasaadahaa Wa-masaakinu tardawnahaaa ahabba ilaikum minal laahi Wa-Rasoolihee Wa-Jihaadin fee Sabeelihee fatarabbasoo hattaa ya\'tiyallahu bi amrih; wallaahu laa yahdil qawmal faasiqeen','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>25,'arabic_text'=>'لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ','transliteration'=>'Laqad nasarakumul laahu fee mawaatina kaseeratinw Wa-yawma Hunainin iz a\'jabatkum kasratukum falam tughni \'ankum shai\'anw Wa-daaqat \'alaikumul ardu bimaa rahubat summa wallaitum mudbireen','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>26,'arabic_text'=>'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ','transliteration'=>'Summa anzalal laahu sakeenatahoo \'alaa Rasoolihee Wa-\'alalmu \'mineena Wa-anzala junoodal lam tarawhaa Wa-azzabal lazeena kafaroo; Wa-zaalika jazaaa\'ul kaafireen','page_number'=>190,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>27,'arabic_text'=>'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Summa yatoobul laahu mim ba\'di zaalika \'alaa mai yashaaa\'; wallaahu Ghafoorur Raheem','page_number'=>191,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>28,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanooo innamal mushrikoona najasun falaa yaqrabul Masjidal Haraama ba\'da \'aamihim haaza; Wa-in khiftum \'ailatan fasawfa yughnee kumul laahu min fadliheee in shaaa\'; innallaaha \'Aleemun hakeem','page_number'=>191,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>29,'arabic_text'=>'قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ','transliteration'=>'Qaatilul lazeena laa yu\'minoona billaahi Wa-laa bil-yawmil Aakhiri Wa-laa yuharrimoona maa harramal laahu Wa-Rasooluhoo Wa-laa yadeenoona deenal haqqi minal lazeena ootul Kitaaba hattaa yu\'tul jizyata aien yadinw Wa-hum saaghiroon','page_number'=>191,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>30,'arabic_text'=>'وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ','transliteration'=>'Wa-qaalatil yahoodu \'Uzairunib nul laahi Wa-qaalatin Nasaaral Maseehub nul laahi zaalika qawluhum bi-afwaahihim yudaahi\'oona qawlal lazeena kafaroo min qabl; qatalahumul laah; annaa yu\'fakoon','page_number'=>191,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>31,'arabic_text'=>'ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهٗا وَٰحِدٗاۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ','transliteration'=>'ittakhazooo ahbaarahum Wa-ruhbaanahum arbaabam min doonil laahi wal-Maseehab na Maryama Wa-maaa umirooo illaa liya\'budooo Ilaahanw Waa-hidan laaa ilaaha illaa Hoo; Subhaanahoo \'ammaa yushrikoon','page_number'=>191,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>32,'arabic_text'=>'يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ','transliteration'=>'Yureedoona aien yutfi\'oo nooral laahi bi\'afwaahihim Wa-ya\'bal laahu illaaa aien yutimma noorahoo Wa-law karihal kaafiroon','page_number'=>192,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>33,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ','transliteration'=>'huwal lazeee ar-sala Rasoolahoo bilhudaa Wa-deenil haqqi liyuzhirahoo \'alad deeni kullihee Wa-law karihal mushrikoon','page_number'=>192,'juz_number'=>10,'hizb_number'=>19,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>34,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanooo inna kaseeram minal ahbaari warruhbaani la-ya\'kuloona amwaalan naasi bil-baatili Wa-yasuddoona \'an sabeelil laah; wallazeena yaknizoonaz zahaba wal-fiddata Wa-laa yunfiqoonahaa fee sabeelil laahi fabashshirhum bi\'azaabin aleem','page_number'=>192,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>35,'arabic_text'=>'يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ','transliteration'=>'Yawma yuhmaa \'alaihaa fee naari jahannama fatukwaa bihaa jibaahuhum Wa-junoobuhum Wa-zuhooruhum haazaa maa kanaztum li-anfusikum fazooqoo maa kuntum taknizoon','page_number'=>192,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>36,'arabic_text'=>'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ','transliteration'=>'Inna \'iddatash shuhoori \'indal laahis naa \'ashara shahran fee Kitaabil laahi yawma khalaqas samaawaati wal-arda minhaaa arba\'atun hurum; zaalikad deenul qaiyyim; falaa tazlimoo feehinna anfusakum; Wa-qaatilul mushrikeena kaaaffatan kamaa yuqaati-loonakum kaaaffah; wa\'lamooo annal laaha ma\'al muttaqeen','page_number'=>192,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>37,'arabic_text'=>'إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','transliteration'=>'Inna-man naseee\'u ziyaadatun fil kufri yudallu bihil lazeena kafaroo yuhil-loonahoo \'aamanw Wa-yuhar-rimoonahoo \'aamal liyuwaati\'oo \'iddata maa harramal laahu fayuhilloo maa harramal laah; zuyyina lahum sooo\'u a\'maalihim; wallaahu laa yahdil qawmal kaafireen','page_number'=>193,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>38,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo maa lakum izaa qeela lakumun firoo fee sabeelil laahis saaqaltum ilal ard; aradeetum bilhayaatid dunyaa minal Aakhirah; famaa mataa\'ul hayaatid dunyaa fil Aakhirati illaa qaleel','page_number'=>193,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>39,'arabic_text'=>'إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Illaa tanfiroo yu\'az-zibkum \'azaaban aleemanw Wa-yastabdil qawman ghairakum Wa-laa tadurroohu shai\'aa; wal-laahu \'alaa kulli shai\'in Qadeer','page_number'=>193,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>40,'arabic_text'=>'إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','transliteration'=>'Illaa tansuroohu faqad nasarahul laahu iz akhrajahul lazeena kafaroo saaniyas naini iz humaa fil ghaari iz yaqoolu lisaahibihee laa tahzan innnal laaha ma\'anaa; fa-anzalal laahu sakeenatahoo \'alaihi Wa-aiyyadahoo bijunoodil lam tarawhaa Wa-ja\'ala kalimatal lazeena kafarus suflaa; Wa-Kalimatul laahi hiyal \'ulyaa; wallaahu \'Azeezun Hakeem','page_number'=>193,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>41,'arabic_text'=>'ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Infiroo khifaafanw Wa-siqaalanw Wa-jaahidoo bi-amwaalikum Wa-anfusikum fee sabeelil laah; zaalikum khairul lakum in kuntum ta\'lamoon','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>42,'arabic_text'=>'لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ عَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Law kaana \'aradan qareebanw Wa-safaran qaasidal lattaba\'ooka Wa-laakim ba\'udat \'alaihimush shuqqah; Wa-sayahlifoona billaahi lawis tata\'naa lakharajnaa ma\'akum; yuhlikoona anfusahum wal-laahu ya\'lamu innahum lakaa-ziboon','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>43,'arabic_text'=>'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ','transliteration'=>'Afal laahu \'anka lima azinta lahum hattaa yatabaiy-yana lakal lazeena sadaqoo Wa-ta\'lamal kaazibeen','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>44,'arabic_text'=>'لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ','transliteration'=>'Laa yastaazinukal lazeena yu\'minoona billaahi wal-Yawmil Aakhiri aien yujaa-hidoo bi-amwaalihim Wa-anfusihim; wallaahu \'aleemum bilmut-taqeen','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>45,'arabic_text'=>'إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِي رَيۡبِهِمۡ يَتَرَدَّدُونَ','transliteration'=>'Innamaa yastaazinukal lazeena laa yu\'minoona billaahi wal-Yawmil Aakhiri wartaabat quloobuhum fahum fee raibihim yataraddadoon','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>46,'arabic_text'=>'۞ وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ','transliteration'=>'Wa-law araadul khurooja la-\'addoo lahoo \'uddatanw Wa-laakin karihal laahum bi\'aasahum fasabbatahum Wa-qeelaq \'udoo ma\'al qaa\'ideen','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>47,'arabic_text'=>'لَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ','transliteration'=>'Law kharajoo feekum maa zaadookum ilaa Khabaalanw Wa-la-awda\'oo khilaalakum yabghoona-kumul fitnata Wa-feekum sammaa\'oona lahum; wallaahu \'aleemum biz-zaalimeen','page_number'=>194,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>48,'arabic_text'=>'لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ','transliteration'=>'Laqadib taghawul fitnata min qablu Wa-qallaboo lakal umoora hattaa jaaa\'al haqqu Wa-zahara amrul laahi Wa-hum kaarihoon','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>49,'arabic_text'=>'وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ','transliteration'=>'Wa-minhum maien yaqoolu\' zal lee Wa-laa taftinneee; alaa fil fitnati saqatoo; Wa-inna Jahannama lamuheetatum bil-kaafireen','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>50,'arabic_text'=>'إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ','transliteration'=>'In tusibka hasanatun tasu\'hum; Wa-in tusibka museebatuny yaqooloo qad akhaznaaa amranaa min qablu Wa-yatawallaw Wa-hum farihoon','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>51,'arabic_text'=>'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Qul laien yuseebanaaa illaa maa katabal laahu lanaa Huwa mawlaanaa; Wa-\'alal laahi fal-yatawakka-lil mu\'minoon','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>52,'arabic_text'=>'قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ','transliteration'=>'Qul hal tarabbasoona binaaa illaaa ihdal husnayayni Wa-nahnu natrabbasu bikum aien yus-eebakumul laahu bi\'azaa-bim min \'indiheee aw biaidee-naa fatarabbasooo innaa ma\'akum mutarabbisoon','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>53,'arabic_text'=>'قُلۡ أَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمٗا فَٰسِقِينَ','transliteration'=>'Qul anfiqoo taw\'an aw karhal laien yutaqabbala min-kum innakum kuntum qawman faasiqeen','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>54,'arabic_text'=>'وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ','transliteration'=>'Wa-maa mana\'ahum \'an tuqbala minhum nafaqaatuhum illaaa annahum kafaroo billaahi Wa-bi-Rasoolihee Wa-laa ya\'toonas Salaata illaa Wa-hum kusaalaa Wa-laa yunfiqoona illaa Wa-hum kaarihoon','page_number'=>195,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>55,'arabic_text'=>'فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ','transliteration'=>'Falaa tu\'jibka amwaaluhum Wa-laaa awlaaduhum; innamaa yureedul laahu liyu\'az-zibahum bihaa fil hayaatid dunyaa Wa-tazhaqa anfusuhum Wa-hum kaafiroon','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>56,'arabic_text'=>'وَيَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَٰكِنَّهُمۡ قَوۡمٞ يَفۡرَقُونَ','transliteration'=>'Wa-yahlifoona billaahi innnahum laminkum Wa-maa hum minkum Wa-laakinnahum qawmuien yafraqoon','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>57,'arabic_text'=>'لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ أَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ','transliteration'=>'Law yajidoona malja\'an aw maghaaraatin aw mudda-khalal lawallaw ilaihi Wa-hum yajmahoon','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>58,'arabic_text'=>'وَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ','transliteration'=>'Wa minhum maien yalmizuka fis sadaqaati fa-in u\'too minhaa radoo Wa-illam yu\'taw minhaaa izaa hum yaskhatoon','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>59,'arabic_text'=>'وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ','transliteration'=>'Wa-law annahum radoo maaa aataahumul laahu Wa-Rasooluhoo Wa-qaaloo hasbunal laahu sayu\'teenal laahu min fadlihee Wa-Rasooluhooo innaaa ilal laahi raaghiboon','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>60,'arabic_text'=>'۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Innamas sadaqaatu lilfuqaraaa\'i walmasaakeeni wal-\'aamileena \'alaihaa wal-mu\'al-lafati quloobuhum Wa-fir riqaabi walghaarimeena Wa-fee sabeelil laahi wabnis sabeeli fareedatam minal laah; wal-laahu \'Aleemun Hakeem','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>61,'arabic_text'=>'وَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ ءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wa-minhumul lazeena yu\'zoonan nabiyya Wa-yaqooloona huwa uzun; qul uzunu khairil lakum yu\'minu billaahi Wa-yu\'minu lil-mu\'mineena Wa-rahmatul lil-lazeena aamanoo minkum; wallazeena yu\'zoona Rasoolal laahi lahum \'azaabun \'aleem','page_number'=>196,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>62,'arabic_text'=>'يَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ','transliteration'=>'yahlifoona billaahi lakum liyurdookum wallaahu Wa-Rasooluhoo ahaqqu ai yurdoohu in kaanoo mu\'mineen','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>63,'arabic_text'=>'أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ ذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ','transliteration'=>'Alam ya\'lamooo annahoo maien yuhaadidil laaha Wa-Rasoolahoo faanna lahoo Naara jahannama khaalidan feehaa; zaalikal khizyul \'Azeem','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>64,'arabic_text'=>'يَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ','transliteration'=>'Yahzarul munaafiqoona an tunaz zala \'alaihim Sooratun tunabbi \'uhum bimaa feequloobihim; qulistahzi\'oo innal laaha mukhrijum maa tahzaroon','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>65,'arabic_text'=>'وَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ','transliteration'=>'Wala\'in sa-altahum layaqoolunna innamaa kunnaa nakhoodu Wa-nal\'ab; qul abillaahi Wa-\'Aayaatihee Wa-Rasoolihee kuntum tastahzi\'oon','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>66,'arabic_text'=>'لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ إِن نَّعۡفُ عَن طَآئِفَةٖ مِّنكُمۡ نُعَذِّبۡ طَآئِفَةَۢ بِأَنَّهُمۡ كَانُواْ مُجۡرِمِينَ','transliteration'=>'Laa ta\'taziroo qad kafartum ba\'da eemaanikum; in na\'fu \'an taaa\'ifatin minkum nu\'az-zib taaa\'ifatan bi-annahum kaanoo mujrimeen','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>67,'arabic_text'=>'ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمُنكَرِ وَيَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَيَقۡبِضُونَ أَيۡدِيَهُمۡۚ نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Almunaafiqoona wal-munaafiqaatu ba\'duhum mim ba\'d; yaamuroona bilmunkari Wa-yanhawna \'anil ma\'roofi Wa-yaqbidoona aidiyahum; nasul laaha fanasiyahum; innal munaafiqeena humul faasiqoon','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>68,'arabic_text'=>'وَعَدَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ','transliteration'=>'Wa\'adal laahul munafiqeena wal-munaafiqaati wal-kuffaara naara jahannnamma khaalideena feehaa; hiya hasbuhum; Wa-la\'annahumul laahu Wa-lahum \'azaabum muqeem','page_number'=>197,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>69,'arabic_text'=>'كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Kallazeena min qablikum kaanoo ashadda minkum quwwatanw Wa-aksara amwaalanw Wa-awlaadan fastamta\'oo bikhalaaqihim fastamta\'tum bikhalaaqikum kamas tamta\'al lazeena min qablikum bikhalaa-qihim Wa-khudtum kallazee khaadooo; ulaaa\'ika habitat a\'maaluhum fid dunyaa wal-Aakhirati Wa-ulaaa\'ika humul khaasiroon','page_number'=>198,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>70,'arabic_text'=>'أَلَمۡ يَأۡتِهِمۡ نَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ إِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Alam ya\'tihim naba ul-lazeena min qablihim qawmi Noohinw Wa-\'Aadinw Wa-Samooda Wa-qawmi Ibraaheema Wa-as-haabi Madyana wal-mu\'tafikaat; atathum Rusuluhum bilbaiy-yinaati famaa kaanal laahu liyazlimahum Wa-laakin kaanooo anfusahum yazlimoon','page_number'=>198,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>71,'arabic_text'=>'وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wal-mu\'minoona wal-mu\'minaatu ba\'duhum awliyaaa\'u ba\'d; ya\'muroona bilma\'roofi Wa-yanhawna \'anil munkari Wa-yuqeemoonas Salaata Wa-yu\'toonaz Zakaata Wa-yutee\'oonal laaha Wa-Rasoolah; ulaaa\'ika sayarhamu-humul laah; innal laaha \'Azeezun Hakeem','page_number'=>198,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>72,'arabic_text'=>'وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Wa\'adal laahul mu\'-mineena walmu\'minaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa Wa-masaakina taiyyibatan fee Jannnaati \'adn; Wa-ridwaanum minal laahi akbar; zaalika huwal fawzul \'azeem','page_number'=>198,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>73,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'yaaa-aiyyuhan Nabiyyu jaahidil kuffaara walmunaafiqeena waghluz \'alaihim; Wa-maawaahum jahannnamu Wa-bi\'sal maseer','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>74,'arabic_text'=>'يَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ وَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ مِن وَلِيّٖ وَلَا نَصِيرٖ','transliteration'=>'Yahlifoona billaahi Wa-qaaloo Wa-laqad qaaloo kalimatal kufri Wa-kafaroo ba\'da Islaamihim Wa-hammoo bimaa lam yanaaloo; Wa-maa naqamooo illaaa an aghnaa humullaahu Wa-Rasooluhoo min fadlih; fainy yatooboo yaku khairal lahum Wa-iny yatawal law yu\'az zibhumullaahu \'azaaban aleeman fiddunyaa wal Aakhirah; wamaa lahum fil ardi minw waliyyinw Wa-laa naseer','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>75,'arabic_text'=>'۞ وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-minhum man \'aaha-dal laaha la\'in aataanaa min fadlihee lanas-saddaqanna Wa-lanakoonanna minas saaliheen','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>76,'arabic_text'=>'فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ','transliteration'=>'Falammaaa aataahum min fadlihee bakhiloo bihee Wa-tawallaw Wa-hum mu\'ridoon','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>77,'arabic_text'=>'فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ','transliteration'=>'Fa-a\'qabahum nifaaqan fee quloobihim ilaa Yawmi yalqaw-nahoo bimaaa akhlaful laaha maa wa\'adoohu Wa-bimaa kaanoo yakhziboon','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>78,'arabic_text'=>'أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلۡغُيُوبِ','transliteration'=>'Alam ya\'lamooo annal laaha ya\'lamu sirrahum Wa-najwaahum Wa-annal laaha \'Allaamul Ghuyoob','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>79,'arabic_text'=>'ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ','transliteration'=>'Allazeena yalmizoonal mut tawwi\'eena minalmu\'mineena fis sadaqaati wallazeena laa yajidoona illaa juhdahum fayaskharoona minhum sakhiral laahu minhum Wa-lahum azaabun aleem','page_number'=>199,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>80,'arabic_text'=>'ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِينَ مَرَّةٗ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَٰلِكَ بِأَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ','transliteration'=>'Istaghfir lahum aw laa tastaghfir lahum in tastaghfir lahum sab\'eena marratan falaien yaghfiral laahu lahum; zaalika bi-annahum kafaroo billaahi Wa-Rasoolih; wallaahu laa yahdil qawmal faasiqeen','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>81,'arabic_text'=>'فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ','transliteration'=>'Farihal mukhallafoona bimaq\'adihim khilaafa Rasoolil laahi Wa-karihooo aien yujaahidoo bi-amwaalihim Wa-anfusihim fee sabeelil laahi Wa-qaaloo laa tanfiroo fil harr; qul Naaru jahannama ashaddu harraa; law kaanoo yafqahoon','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>82,'arabic_text'=>'فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Falyadhakoo qaleelanw walyabkoo kaseeran jazaaa\'an bimaa kaanoo yaksiboon','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>83,'arabic_text'=>'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٖ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُواْ مَعِيَ أَبَدٗا وَلَن تُقَٰتِلُواْ مَعِيَ عَدُوًّاۖ إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ','transliteration'=>'Fa-ir raja\'akal laahu ilaa taaa\'ifatim minhum fastaaa-zanooka lilkhurooji faqul lan takhrujoo ma\'iya abadanw Wa-lan tuqaatiloo ma\'iya \'aduwwan innakum radeetum bilqu\'oodi awwala marratin faq\'udoo ma\'al khaalifeen','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>84,'arabic_text'=>'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ','transliteration'=>'Wa-laa tusalli \'alaaa ahadim minhum maata abadanw Wa-laa taqum \'alaa qabriheee innahum kafaroo billaahi Wa-Rasoolihee Wa-maatoo Wa-hum faasiqoon','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>85,'arabic_text'=>'وَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ','transliteration'=>'Wa-laa tu\'jibka amwaaluhum Wa-awlaaduhum; innamaa yureedul laahu aien yu\'azzibahum bihaa fid dunyaa Wa-tazhaqa anfusuhum Wa-hum kaafiroon','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>86,'arabic_text'=>'وَإِذَآ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُواْ بِٱللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُواْ ذَرۡنَا نَكُن مَّعَ ٱلۡقَٰعِدِينَ','transliteration'=>'Wa-izaaa unzilat Sooratun an aaminoo billaahi Wa-jaahidoo ma\'a Rasoolihis taazanaka ulut tawli minhum Wa-qaaloo zarnaa nakum ma\'al qaa\'ideen','page_number'=>200,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>87,'arabic_text'=>'رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ','transliteration'=>'Radoo bi-aie yakoonoo ma\'al khawaalifi Wa-tubi\'a \'alaa quloobihim fahum laa yafqahoon','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>88,'arabic_text'=>'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُوْلَٰٓئِكَ لَهُمُ ٱلۡخَيۡرَٰتُۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Laakinir Rasoolu wal-lazeena aamanoo ma\'ahoo jaahadoo bi-amwaalihim Wa-anfusihim; Wa-ulaaa\'ika lahumul khairaatu Wa-ulaaa\'ika humul muflihoon','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>89,'arabic_text'=>'أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'A\'addal laahu lahum Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; zaalikal fawzul \'azeem','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>90,'arabic_text'=>'وَجَآءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ ٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wa-jaaa\'al mu\'az-ziroona minal A\'raabi liyu\'zana lahum Wa-qa\'adal lazeena kazabul laaha Wa-Rasoolah; sayuseebul lazeena kafaroo minhum \'azaabun aleem','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>91,'arabic_text'=>'لَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Laisa \'alad du\'aaa\'fai Wa-laa \'alal mardaa Wa-laa \'alal lazeena laa yajidoona maa yunfiqoona harajun izaa nasahoo lillaahi Wa-Rasoolih; maa \'alal muhsineena min sabeel; wallaahu Ghafoorur Raheem','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>92,'arabic_text'=>'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ','transliteration'=>'Wa-laa \'alal lazeena izaa maaa atawka litahmilahum qulta laaa ajidu maaa ahmilukum \'alaihi tawallaw Wa-a\'yunuhum tafeedu minad dam\'i hazanan allaa yajidoo maa yunfiqoon','page_number'=>201,'juz_number'=>10,'hizb_number'=>20,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>93,'arabic_text'=>'۞ إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Innamas sabeelu \'alal lazeena yasta\'zinoonaka Wa-hum aghniyaaa\'; radoo bi-aien yakoonoo ma\'al khawaalifi Wa-taba\'al laahu \'alaa quloobihim fahum laa ya\'lamoon','page_number'=>201,'juz_number'=>10,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>94,'arabic_text'=>'يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Ya\'taziroona ilaikum izaa raja\'tum ilaihim; qul laa ta\'taziroo lan nu\'mina lakum qad nabba-annal laahu min akhbaarikum; Wa-sa-yaral laahu \'amalakum Wa-Rasooluhoo thumma turaddoona ilaa \'Aalimil Ghaibi washshahaadati fa-yunabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>95,'arabic_text'=>'سَيَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Sa yahlifoona billaahi lakum izanqalabtum ilaihim litu\'ridoo \'anhum fa-a\'ridoo \'anhum innahum rijsunw Wa-ma\'waahum jahannamu jazaaa\'an bi maakaanoo yaksiboon','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>96,'arabic_text'=>'يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ','transliteration'=>'Yahlifoona lakum litardaw \'anhum fa-in tardaw \'anhum fa-innal laaha laa yardaa \'anil qawmil faasiqeen','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>97,'arabic_text'=>'ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Al-A\'raabu ashaddu kufranw Wa-nifaaqanw Wa-ajdaru allaa ya\'lamoo hudooda maaa anzalal laahu \'alaa Rasoolih; wallaahu \'Aleemun Hakeem','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>98,'arabic_text'=>'وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ','transliteration'=>'Wa-minal A\'raabi mai yattakhizu maa yunfiqu maghramanw Wa-yatarabbasu bikumud dawaaa\'ir; alaihim daaa\'iratus saw\'; wallaahu Samee\'un \'Aleem','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>99,'arabic_text'=>'وَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ لَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-minal A\'raabi maien yu\'minu billaahi wal-yawmil aakhiri Wa-yattakhizu maa yunfiqu qurubaatin \'indal laahi Wa-salawaatir Rasool; \'alaaa innahaa qurbatul lahum; sayudkhilu-humul laahu fee rahmatih; innal laaha Ghafoorur Raheem','page_number'=>202,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>100,'arabic_text'=>'وَٱلسَّٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Was-saabiqoonal awwaloona minal Muhaajireena wal-Ansaari wallazeenat taba\'oo-hum bi-ihsaanir radiyal laahu \'anhum Wa-radoo \'anhu Wa-a\'adda lahum jannaatin tajree tahtahal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul \'azeem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>101,'arabic_text'=>'وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ','transliteration'=>'Wa-mimmann hawlakum minal A\'raabi munaafiqoona Wa-min ahlil Madeenati maradoo \'alan nifaaq, laa ta\'lamuhum nahnu na\'lamuhum; sanu\'azzibuhum marrataini summa yuraddoona ilaa \'azaabin \'azeem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>102,'arabic_text'=>'وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Wa-aakharoo na\'tarafoo bizunoobihim khalatoo \'amalan saalihanw Wa-aakhara saiyyi\'an \'asal laahu \'aien yatooba \'alaihim; innal laaha Ghafoorur Raheem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>103,'arabic_text'=>'خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','transliteration'=>'Khuz min amwaalihim sadaqtan tutahhiruhum Wa-tuzakkeehim bihaa Wa-salli \'alaihim inna salaataka sakanul lahum; wallaahu Samee\'un \'Aleem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>104,'arabic_text'=>'أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Alam ya\'lamooo annal laaha huwa yaqbalut tawbata \'an ibaadihee Wa-ya\'khuzus sadaqaati Wa-annal laaha huwat Tawwaabur Raheem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>105,'arabic_text'=>'وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-qul i\'maloo fasayaral laahu \'amalakum Wa-Rasooluhoo wal-mu\'minoon; Wa-saturaddoona ilaa \'Aalimil Ghaibi washshahaadati fa-yunabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>106,'arabic_text'=>'وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Wa-aakharoona murjawna li-amril laahi immaa yu\'azzibuhum Wa-immaa yatoobu \'alaihim; wallaahu \'Aleemun Hakeem','page_number'=>203,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>107,'arabic_text'=>'وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Wallazeenat takhazoo masjidan diraaranw Wa-kufranw Wa-tafreeqan bainal mu\'mineena Wa-irsaadal liman haarabal laaha Wa-Rasoolahoo min qabl; Wa-la-yahlifunna in aradnaaa illal husnaa wallaahu yash-hadu innahum lakaaziboon','page_number'=>204,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>108,'arabic_text'=>'لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ','transliteration'=>'Laa taqum feehi abadaa; lamasjidun ussisa \'alat taqwaa min awwali yawmin ahaqqu \'an taqooma feeh; feehi rijaaluien yuhibbona \'aien yata-tah-haroo; wallaahu yuhibbul muttah-hireen','page_number'=>204,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>109,'arabic_text'=>'أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Afaman assasa bunyaanahoo \'alaa taqwaa minal laahi Wa-ridwaanin khairun am man assasa bunyaanahoo \'alaa shafaa jurufin haarin fanhaara bihee fee Naari Jahannam; wallaahu laa yahdil qawmaz zaalimeen','page_number'=>204,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>110,'arabic_text'=>'لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةٗ فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','transliteration'=>'Laa yazaalu bunyaanu-humul lazee banaw reebatan fee quloobihim illaaa an taqatta\'a quloobuhum; wal-laahu \'Aleemun Hakeem','page_number'=>204,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>111,'arabic_text'=>'۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Innal laahash taraa minal mu\'mineena anfusahum Wa-amwaalahum bi-anna lahumul jannah; yuqaatiloona fee sabeelil laahi fa-yaqtuloona Wa-yuqtaloona wa\'dan \'alaihi haqqan fit Tawraati wal-Injeeli wal-Qur\'aaan; Wa-man awfaa bi\'ahdihee minal laah; fastabshiroo bi-bay\'ikumul lazee baaya\'tum bih; Wa-zaalika huwal fawzul \'azeem','page_number'=>204,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>112,'arabic_text'=>'ٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'At-taaa\'iboonal \'aabidoonal haamidoonas saaa\'ihoonar raaki\'oonas saajidoonal aamiroona bilma\'roofi wannaahoona \'anil munkari walhaafizoona lihudoodil laah; Wa-bashshiril mu\'mineen','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>113,'arabic_text'=>'مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ','transliteration'=>'Maa kaana lin-nabiyyi wallazeena aamanooo \'aien yastaghfiroo lil-mushrikeena Wa-law kaanoo ulee qurbaa min ba\'di maa tabiyyana lahum annahum As-haabul jaheem','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>114,'arabic_text'=>'وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٞ','transliteration'=>'Wa-maa kaanas tighfaaru ibraaheema li-abeehi illaa \'an maw\'idatinw Wa-\'adahaaa iyyaahu falammaa tabaiyyana lahooo annahoo \'aduwwul lillaahi tabarra-a minh; inna Ibraaheema la-awwaahun haleem','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>115,'arabic_text'=>'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ','transliteration'=>'Wa-maa kaanal laahu liyudilla qawman ba\'da iz hadaahum hatta yubaiyyina lahum maa yattaqoon; innal laaha bikulli shai\'in \'Aleem','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>116,'arabic_text'=>'إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ','transliteration'=>'Innal laaha lahoo mulkus samaawaati wal-ardi yuhyee Wa-yumeet; Wa-maa lakum min doonil laahi minw waliyyinw Wa-laa naseer','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>117,'arabic_text'=>'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ','transliteration'=>'Laqat taabal laahu \'alan nabiyyi wal-Muhaajireena wal-Ansaaril lazeenat taba\'oohu fee saa\'atil \'usrati min ba\'di maa kaada yazeeghu quloobu fariqin minhum thumma taaba \'alaihim; innahoo bihim Ra\'oofur Raheem','page_number'=>205,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>118,'arabic_text'=>'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','transliteration'=>'Wa-\'alas salaasatil lazeena khullifoo hattaaa izaa daaqat \'alaihimul ardu bimaa rahubat Wa-daaqat \'alaihim anfusuhum Wa-zannnooo al laa malja-a minal laahi illaaa ilaihi summa taaba \'alaihim liyatooboo; innal laaha Huwat Tawwaabur Raheem','page_number'=>206,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>119,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّٰدِقِينَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanut taqul laaha Wa-koonoo ma\'as saadiqeen','page_number'=>206,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>120,'arabic_text'=>'مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Maa kaana li-ahlil Madeenati Wa-man hawlahum minal A\'raabi aien yatakhallafoo \'ar Rasoolil laahi Wa-laa yarghaboo bi-anfusihim \'an nafsih; zaalika bi-annahum laa yuseebuhum zama-unw Wa-laa nasabunw Wa-laa makhmasatun fee sabeelil laahi Wa-laa yata\'oona mawti\'ai yagheezul kuffaara Wa-laa yanaaloona min \'aduwwin nailan illaa kutiba lahum bihee \'amalun saalih; innal laaha laa yudee\'u ajral muhsineen','page_number'=>206,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>121,'arabic_text'=>'وَلَا يُنفِقُونَ نَفَقَةٗ صَغِيرَةٗ وَلَا كَبِيرَةٗ وَلَا يَقۡطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-laa yunfiqoona nafa-qatan sagheeratanw Wa-laa kabeeratanw Wa-laa yaqta\'oona waadiyan illaa kutiba lahum liyajziyahumul laahu ahsana maa kaanoo ya\'maloon','page_number'=>206,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>122,'arabic_text'=>'۞ وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ','transliteration'=>'Wa-maa kaanal mu\'minoona liyanfiroo kaaaffah; falaw-laa nafara min kulli firqatim minhum taaa\'ifatul liyatafaqqahoo fid deeni Wa-liyunziroo qawmahum izaa raja\'ooo ilaihim la\'allahum yahzaroon','page_number'=>206,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>123,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo qaatilul lazeena yaloonakum minal kuffaari walyajidoo feekum ghilzah; wa\'lamooo annal laaha ma\'al muttaqeen','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>124,'arabic_text'=>'وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ','transliteration'=>'Wa-izaa maaa unzilat Sooratun faminhum maien yaqoolu aiyyukum zaadat hu-haazihee eemaanaa; fa-ammal lazeena aamanoo fazaadat-hum eemaananw Wa-hum yastabshiroon','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>125,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ','transliteration'=>'Wa-ammal lazeena fee quloobihim maradun fazaadat-hum rijsan ilaa rijsihim Wa-maatoo Wa-hum kaafiroon','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>126,'arabic_text'=>'أَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ','transliteration'=>'A-Wa-laa yarawna annahum yuftanoona fee kulli \'aamin marratan \'aw marrataini thumma laa yatooboona Wa-laa hum yazzakkaroon','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>127,'arabic_text'=>'وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ','transliteration'=>'Wa-izaa maaa unzilat Sooratun nazara ba\'duhum ilaa ba\'din hal yaraakum min ahadin thumman sarafoo; sarafal laahu quloobahum bi-annahum qawmul laa yafqahoon','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>128,'arabic_text'=>'لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ','transliteration'=>'Laqad jaaa\'akum Rasoolum min anfusikum \'azeezun \'alaihi maa \'anittum hareesun \'alaikum bilmu\'mineena ra\'oofur raheem','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>9,'ayah_number'=>129,'arabic_text'=>'فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ','transliteration'=>'Fa-in tawallaw faqul hasbiyal laahu laaa ilaaha illaa Huwa \'alaihi tawakkkaltu Wa-Huwa Rabbul \'Arshil \'Azeem','page_number'=>207,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            /* Surah 10: Jonah (Yunus) */
            ['surah_id'=>10,'ayah_number'=>1,'arabic_text'=>'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ','transliteration'=>'Alif-Laaam-Raa; tilka Aayaatul Kitaabil Hakeem','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>2,'arabic_text'=>'أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٞ مُّبِينٌ','transliteration'=>'A-kaana linnaasi \'ajaaban \'an \'awhainaaa \'ilaa rajulin minhum \'an anzirin naasa Wa-bashshiril lazeena \'aamanoo \'anna lahum qadama sidqin \'inda Rabbihim; qaalal kaafiroona \'inna haazaa la-saahirun mubeen','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>3,'arabic_text'=>'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Inna Rabbakumul laahul lazee khalaqas samaawaati wal-arda fee sittati aiy-yaamin thummas tawaa \'alal \'Arshi yudabbirul amra maa min shafee\'in illaa min ba\'di iznih; zalikumul laahu Rabbukum fa\'budooh; afalaa tazakkaroon','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>4,'arabic_text'=>'إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ','transliteration'=>'Ilaihi marji\'ukum jamee-\'anw wa\'dal laahi haqqaa; innahoo yabda\'ul khalqa thumma yu\'eeduhoo liyajziyal lazeena aamanoo Wa-\'amilus saalihaati bilqist; wallazeena kafaroo lahum sharaabun min hamee-minw Wa-\'azaabun \'aleemun bimaa kaanoo yakfuroon','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>5,'arabic_text'=>'هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Huwal lazee ja\'alash shamsa diyaaa\'anw walqamara nooranw Wa-qaddarahoo manaazila li-ta\'lamoo \'adadas sineena walhisaab; maa khalaqal laahu zaalika illa bilhaqq; yufassilul aayaati li-qawminy ya\'lamoon','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>6,'arabic_text'=>'إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ','transliteration'=>'Inna fikh tilaafil laili wannahaari Wa-maa khalaqal laahu fis samaawaati wal-ardi la-aayaatin liqawmien yattaqoon','page_number'=>208,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>7,'arabic_text'=>'إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ','transliteration'=>'Innal lazeena laa yarjoona liqaaa\'anaa Wa-radoo bilhayaatid dunyaa watma\'-annoo bihaa wallazeena hum \'an Aayaatinaa ghaafiloon','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>8,'arabic_text'=>'أُوْلَٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Ulaaa\'ika ma\'waahumun Naaru bimaa kaanoo yaksiboon','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>9,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّٰتِ ٱلنَّعِيمِ','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati yahdeehim Rabbuhum bi-eemaanihim tajree min tahtihimul anhaaru fee jannaatin Na\'eem','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>10,'arabic_text'=>'دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Da\'waahum feehaa Subhaanakal laahumma Wa-tahiyyatuhum feehaa salaam; Wa-aakhiru da\'waahum anil hamdu lillaahi Rabbil \'aalameen','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>11,'arabic_text'=>'۞ وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','transliteration'=>'Wa-law yu\'ajjilul laahu linnaasish sharra sti\'-jaalahum bil-khairi laqudiya ilaihim \'ajaluhum fa-nazarul lazeena laa yarjoona liqaaa\'anaa fee tughyaanihim ya\'mahoon','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>12,'arabic_text'=>'وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-izaa massal insaanad durru da\'aanaa li-jambiheee aw qaa\'idan aw qaaa\'iman falammaa kashafnaa \'anhu durrahoo marra ka-an lam yad\'unaaa ilaa durrin massah; kazaalika zuyyina lilmusrifeena maa kaanoo ya\'maloon','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>13,'arabic_text'=>'وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ','transliteration'=>'Wa-laqad ahlaknal quroona min qablikum lammaa zalamoo Wa-jaaa\'at-hum Rusuluhum bil-baiy-yinaati Wa-maa kaanoo liyu\'minoo; kazaalika najzil qawmal mujrimeen','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>14,'arabic_text'=>'ثُمَّ جَعَلۡنَٰكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ','transliteration'=>'Thumma ja\'alnaakum khalaaa\'ifa fil ardi min ba\'dihim li-nanzura kaifa ta\'maloon','page_number'=>209,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>15,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ','transliteration'=>'Wa-izaa tutlaa \'alaihim aayaatunaa baiy-yinaatin qaalal lazeena laa yarjoona liqaaa\'a na\'ti bi-Qur\'aanin ghairi haazaaa aw baddilh; qul maa yakoonu leee \'an \'ubaddilahoo min tilqaaa\'i nafsee in attabi\'u illaa maa yoohaaa ilaiy-ya inneee akhaafu in \'asaytu Rabbee \'azaaba Yawmin \'Azeem','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>16,'arabic_text'=>'قُل لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Qul law shaaa\'al laahu maa talawtuhoo \'alaikum Wa-laaa adraakum bihee faqad labistu feekum \'umuran min qablih; afalaa ta\'qiloon','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>17,'arabic_text'=>'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ','transliteration'=>'Faman azlamu mimmanif taraa \'alal laahi kaziban aw kazzaba bi-Aayaatih; innahoo laa yuflihul mujrimoon','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>18,'arabic_text'=>'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Wa-ya\'budoona min doonil laahi maa laa yadurruhum Wa-laa yanfa\'uhum Wa-yaqooloona haaa\'ulaaa\'i shufa\'aaa-\'unaa \'indal laah; qul \'a-tunabbi-\'oonal laaha bi-maa laa ya\'lamu fis samaawaati Wa-laa fil ard; subhaanahoo Wa-Ta\'aalaa \'ammaa yushrikoon','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>19,'arabic_text'=>'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Wa-maa kaanan naasu illaaa ummatanw waahidatan fa-khtalafoo; Wa-law-laa kalimatun sabaqat mir Rabbika laqudiya bainahum fee-maa feehi yakhtalifoon','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>20,'arabic_text'=>'وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ','transliteration'=>'Wa-yaqooloona law-laaa unzila \'alaihi aayatun mir Rabbihee faqul innamal ghaibu lillaahi fantaziroo innee ma\'akum minal muntazireen','page_number'=>210,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>21,'arabic_text'=>'وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ','transliteration'=>'Wa-izaaa azaqnan naasa rahmatan min ba\'di darraaa\'a massat-hum izaa lahum makrun feee aayaatinaa; qulil laahu asra\'u makraa; inna rusulanaa yaktuboona maa tamkuroon','page_number'=>211,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>22,'arabic_text'=>'هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ','transliteration'=>'Huwal lazee yusayyirukum fil barri walbahri hattaaa izaa kuntum fil fulki Wa-jaraina bihim bi-reehin tayyibatinw Wa-farihoo bihaa jaaa\'at-haa reehun \'aasifunw Wa-jaaa\'ahumul mawju min kulli makaaninw Wa-zannooo \'annahum \'uheeta bihim da\'a wullaaha mukhliseena lahud deena la\'in anjaitanaa min haazihee la-nakoonanna minash shaakireen','page_number'=>211,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>23,'arabic_text'=>'فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۗ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Falammaaa anjaahum izaa hum yabghoona fil ardi bighairil haqq; yaaa-aiy-yuhan naasu innamaa bagh-yukum \'alaaa anfusikum mataa\'al hayaatid dunyaa thumma ilainaa marji\'ukum fanunabbi-\'ukum bimaa kuntum ta\'maloon','page_number'=>211,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>24,'arabic_text'=>'إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Innamaa masalul hayaatid dunyaa ka-maaa\'in anzalnaahu minas samaaa\'i fakhtalata bihee nabaatul ardi mimmaa ya\'kulun naasu wal-an\'aam; hattaaa izaaa akhazatil ardu zukhrufahaa wazzayyanat Wa-zanna ahluhaaa annahum qaadiroona \'alaihaaa ataahaaa amrunaa lailan aw nahaaran faja\'alnaahaa haseedan ka-\'an lam taghna bil-ams; kazaalika nufassilul aayaati liqawmien yatafakkaroon','page_number'=>211,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>25,'arabic_text'=>'وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wallaahu yad\'ooo ilaa daaris salaami Wa-yahdee many yashaaa\'u ilaa Siraatin Mustaqeem','page_number'=>211,'juz_number'=>11,'hizb_number'=>21,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>26,'arabic_text'=>'۞ لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Lil-lazeena ahsanul husnaa Wa-ziyaadatunw Wa-laa yarhaqu wujoohahum qatarunw Wa-laa zillah; ulaaa\'ika as-haabul jannati hum feehaa khaalidoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>27,'arabic_text'=>'وَٱلَّذِينَ كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wallazeena kasabus saiyi-aati jazaaa\'u saiyi\'atin bimislihaa Wa-tarhaquhum zillah; maa lahum minal laahi min \'aasimin ka-annamaaa ughshiyat wujoohuhum qita\'an minal laili muzlimaa; ulaaa\'ika As-haabun Naari hum feeha khaalidoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>28,'arabic_text'=>'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ','transliteration'=>'Wa-yawma nahshuruhum jamee\'an thumma naqoolu lil-lazeena ashrakoo makaanakum antum Wa-shurakaaa\'ukum; fazaiy-yalnaa bainahum Wa-qaala shurakaaa\'uhum maa kuntum iyyaanaa ta\'budoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>29,'arabic_text'=>'فَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ','transliteration'=>'Fakafaa billaahi shaheedan bainanaa Wa-bainakum in kunnaa \'an \'ibaadatikum laghaafileen','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>30,'arabic_text'=>'هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسٖ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Hunaalika tabloo kullu nafsin maaa \'aslafat; Wa-ruddoo ilal laahi mawlaahumul haqqi Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>31,'arabic_text'=>'قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ','transliteration'=>'Qul maien yarzuqukum minas samaaa\'i wal-ardi ammanien yamlikus sam\'a wal-absaara Wa-maien yukhrijul haiyya minal maiyyiti Wa-yukhrijul maiyyita minal haiyyi Wa-maien yudabbirul amr; fasa-yaqooloonal laah; faqul afalaa tattaqoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>32,'arabic_text'=>'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ','transliteration'=>'Fazaalikumul laahu Rabbukumul haqq; famaazaa ba\'dal haqqi illad dalaalu fa-anna tusrafoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>33,'arabic_text'=>'كَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Kazaalika haqqat Kalimatu Rabbika \'alal lazeena fasaqooo annahum laa yu\'minoon','page_number'=>212,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>34,'arabic_text'=>'قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ','transliteration'=>'Qul hal min shurakaaa-\'ikum maien yabda\'ul khalqa thumma yu\'eeduh; qulil laahu yabda\'ul khalqa thumma yu\'eeduhoo fa-annaa tu\'fakoon','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>35,'arabic_text'=>'قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ','transliteration'=>'Qul hal min shurakaaa-\'ikum maien yahdeee ilal haqq; qulil laahu yahdee lilhaqq; afamaien yahdeee ilal haqqi ahaqqu aien yuttaba\'a ammal laa yahiddeee illaaa aien yuhdaa famaa lakum kaifa tahkumoon','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>36,'arabic_text'=>'وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ','transliteration'=>'Wa-maa yattabi\'u aksaruhum illaa zannaa; innaz zanna laa yughnee minal haqqi shai\'aa; innal laaha \'Aleemun bimaa yaf\'aloon','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>37,'arabic_text'=>'وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-maa kaana haazal Qur\'aanu ai yuftaraa min doonil laahi Wa-laakin tasdeeqal lazee baina yadaihi Wa-tafseelal Kitaabi laa raiba fee mir Rabbil \'aalameen','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>38,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةٖ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Am yaqooloonaf taraahu qul fa\'too bi-sooratin mislihee wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>39,'arabic_text'=>'بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ','transliteration'=>'Bal kazzaboo bimaa lam yuheetoo bi\'ilmihee Wa-lammaa ya\'tihim ta\'weeluh; kazaalika kazzabal lazeena min qablihim fanzur kaifa kaana \'aaqibatuz zaalimeen','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>40,'arabic_text'=>'وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِينَ','transliteration'=>'Wa-minhum maien yu-\'minu bihee Wa-minhum mal laa yu\'minu bih; Wa-Rabbuka a\'lamu bilmufsideen','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>41,'arabic_text'=>'وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ','transliteration'=>'Wa-in kazzabooka faqul lee \'amalee Wa-lakum \'amalukum antum bareee\'oona mimmaaa a\'malu Wa-ana bareee\'um mimmaa ta\'maloon','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>42,'arabic_text'=>'وَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ','transliteration'=>'Wa-minhum maien yastami\'oona iliak; afa-anta tusmi\'us summa Wa-law kaanoo laa ya\'qiloon','page_number'=>213,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>43,'arabic_text'=>'وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ','transliteration'=>'Wa-minhum maien yanzuru ilaik; afa-anta tahdil \'umya Wa-law kaanoo laa yubsiroon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>44,'arabic_text'=>'إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Innal laaha laa yazlimun naasa shai\'anw Wa-laakin nannaasa anfusahum yazlimoon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>45,'arabic_text'=>'وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ مُهۡتَدِينَ','transliteration'=>'Wa-Yawma yahshuruhum ka-\'an lam yalbasooo illaa saa\'atan minan nahaari yata\'aarafoona bainahum; qad khasiral lazeena kazzaboo bi-liqaaa\'il laahi Wa-maa kaanoo muhtadeen','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>46,'arabic_text'=>'وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ','transliteration'=>'Wa-imma nuriyannaka ba\'dal lazee na\'iduhum aw natawaffayannaka fa-ilainaa marji\'uhum thummal laahu shaheedun \'alaa maa yaf\'aloon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>47,'arabic_text'=>'وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-likulli ummatir Rasoolun fa-izaa jaaa\'a Rasooluhum qudiya bainahum bilqisti Wa-hum laa yuzlamoon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>48,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>49,'arabic_text'=>'قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ','transliteration'=>'Qul laaa amliku linafsee darranw Wa-laa naf\'an illaa maa shaaa\'al laah; likulli ummatin ajalun izaa jaaa\'a ajaluhumfa laaa yasta\'khiroona saa\'atanw Wa-laa yastaqdimoon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>50,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ','transliteration'=>'Qul \'a-ra\'aytum in ataakum \'azaabuhoo bayaatan aw nahaaran maazaa yasta\'jilu minhul mujrimoon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>51,'arabic_text'=>'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ','transliteration'=>'A-thumma izaa maa waqa\'a aamantum bih; aaal-\'aana Wa-qad kuntum bihee tasta\'jiloon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>52,'arabic_text'=>'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ','transliteration'=>'Thumma qeela lil-lazeena zalamoo zooqoo \'azaabal khuldi hal tujzawna illaa bimaa kuntum taksiboon','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>53,'arabic_text'=>'۞ وَيَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ','transliteration'=>'Wa-yastanbi\'oonaka \'a-haqqun huwa qul ee Wa-Rabbeee innahoo lahaqq; Wa-maaa antum bimu\'jizeen','page_number'=>214,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>54,'arabic_text'=>'وَلَوۡ أَنَّ لِكُلِّ نَفۡسٖ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-law anna likulli nafsin zalamat maa fil ardi laftadat bih; Wa-asarrun nadaamata lammaa ra-awul \'azaab, Wa-qudiya bainahum bilqist; Wa-hum laa yuzlamoon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>55,'arabic_text'=>'أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Alaaa inna lillaahi maa fis samaawaati wal-ard; alaaa inna wa\'dal laahi haqqunw Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>56,'arabic_text'=>'هُوَ يُحۡيِۦ وَيُمِيتُ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Huwa yuhyee Wa-yumeetu Wa-ilaihi turja\'oon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>57,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ','transliteration'=>'Yaaa-aiyyuhan naasu qad jaaa\'atkum maw\'izatun mir Rabbikum Wa-shifaaa\'ul limaa fis sudoori Wa-hudanw Wa-rahmatul lil-mu\'mineen','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>58,'arabic_text'=>'قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ','transliteration'=>'Qul bi-fadlil laahi Wa-bi-rahmatihee fa-bi-zaalika fal-yafrahoo huwa khairun mimmaa yajma\'oon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>59,'arabic_text'=>'قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ فَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ','transliteration'=>'Qul ara\'aitum maaa anzalal laahu lakum mir rizqin faja\'altum minhu haraamanw Wa-halaalan qul aaallaahu azina lakum; am \'alal laahi taftaroon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>60,'arabic_text'=>'وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ','transliteration'=>'Wa-maa zannul lazeena yaftaroona \'alal laahil kaziba Yawmal Qiyaamah; innal laaha lazoo fadlin \'alan naasi Wa-laakinna aksarahum laa yashkuroon','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>61,'arabic_text'=>'وَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ','transliteration'=>'Wa-maa takoonu fee sha\'ninw Wa-maa tatloo minhu min qur\'aaninw Wa-laa ta\'maloona min \'amalin illaa kunnaa \'alaikum shuhoodan iz tufeedoona feeh; Wa-maa ya\'zubu \'ar Rabbika min misqaali zarratin fil ardi Wa-laa fis samaaa\'i Wa-laaa asghara min zaalika Wa-laaa akbara illaa fee Kitaabin Mubeen','page_number'=>215,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>62,'arabic_text'=>'أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Alaa innaa awliyaaa\'al laahi laa khawfun \'alaihim Wa-laa hum yahzanoon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>63,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ','transliteration'=>'Allazeena aamanoo Wa-kaanoo yattaqoon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>64,'arabic_text'=>'لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Lahumul bushraa fil hayaatid dunyaa Wa-fil Aakhirah; laa tabdeela li-kalimaatil laah; zaalika huwal fawzul \'azeem','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>65,'arabic_text'=>'وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-laa yahzunka qawluhum; innal \'izzata lillaahi jamee\'aa; Huwas Samee\'ul \'Aleem','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>66,'arabic_text'=>'أَلَآ إِنَّ لِلَّهِ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ','transliteration'=>'Alaaa inna lillaahi man fis samaawaati Wa-man fil ard; Wa-maa yattabi\'ul lazeena yad\'oona min doonil laahi shurakaaa\'; iny yattabi\'oona illaz zanna Wa-in hum illaa yakhrusoon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>67,'arabic_text'=>'هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ','transliteration'=>'Huwal lazee ja\'ala lakumul laila litaskunoo feehi wannahaara mubsiraa; inna fee zaalika la-Aayaatil li-qawmien yasma\'oon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>68,'arabic_text'=>'قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Qaalut takhazal laahu waladan Subhaanahoo Huwal Ghaniyyu lahoo maa fis samaawaati Wa-maa fil ard; in \'indakum min sultaanin bihaazaaa; a\'-taqooloona \'al allaahi maa laa ta\'lamoon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>69,'arabic_text'=>'قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ','transliteration'=>'Qul innal lazeena yaftaroona \'al allaahil kaziba laa yuflihoon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>70,'arabic_text'=>'مَتَٰعٞ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ','transliteration'=>'Mataa\'un fid dunyaa thumma ilainaa marji\'uhum thumma nuzeequhumul \'azaabash shadeeda bimaa kaanoo yakfuroon','page_number'=>216,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>71,'arabic_text'=>'۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ','transliteration'=>'Watlu \'alaihim naba-a-Noohin iz qaala liqawmihee yaa qawmi in kaana kabura \'alaikum maqaamee Wa-tazkeeree bi-Aayaatil laahi fa\'alal laahi tawakkaltu fa-ajmi\'ooo amrakum Wa-shurakaaa\'akum thumma laa yakun amrukum \'alaikum ghummatan thummaq dooo ilaiyya Wa-laa tunziroon','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>72,'arabic_text'=>'فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Fa-in tawallaitum famaa sa-altukum min ajrin; in ajriya illaa \'alal laahi Wa-umirtu an akoona minal muslimeen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>73,'arabic_text'=>'فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ','transliteration'=>'Fa-kazzaboohu fa-najjainaahu Wa-man ma\'ahoo fil fulki Wa-ja\'alnaahum khalaaa\'ifa Wa-aghraqnal lazeena kazzaboo bi-aayaatinaa fanzur kaifa kaana \'aaqibatul munzareen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>74,'arabic_text'=>'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ','transliteration'=>'Thumma ba\'asnaa min ba\'dihee Rusulan ilaa qawmihim fajaaa\'oohum bil-baiyyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo bihee min qabl; kazaalika natba\'u \'alaa quloobil mu\'tadeen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>75,'arabic_text'=>'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ','transliteration'=>'Thumma ba\'asnaa min ba\'dihim Moosaa Wa-Haaroona ilaa Fir\'awna Wa-mala\'ihee bi-aayaatinaa fastakbaroo Wa-kaanoo qawman mujrimeen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>76,'arabic_text'=>'فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرٞ مُّبِينٞ','transliteration'=>'Falammaa jaaa\'ahumul haqqu min \'indinaa qaalooo inna haazaa la-sihrun mubeen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>77,'arabic_text'=>'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ ٱلسَّٰحِرُونَ','transliteration'=>'Qaalaa Moosaaa \'a-taqooloona lil-haqqi lammmaa jaaa\'a-kum \'a-sihrun haazaa Wa-laa yuflihus saahiroon','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>78,'arabic_text'=>'قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ','transliteration'=>'Qaaloo aji\'tanaa litalfitanaa \'ammaa wajadnaa \'alaihi aabaaa\'anaa Wa-takoona lakumal kibriyaaa\'u fil ardi Wa-maa nahnu lakumaa bi-mu\'mineen','page_number'=>217,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>79,'arabic_text'=>'وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمٖ','transliteration'=>'Wa-qaala Fir\'awnu\' toonee bikulli saahirin \'aleem','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>80,'arabic_text'=>'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ','transliteration'=>'Falammaa jaaa\'assa haratu qaala lahum Moosaaa alqoo maaa antum mulqoon','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>81,'arabic_text'=>'فَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ','transliteration'=>'Falammaaa alqaw qaala Moosaa maa ji\'tum bihis sihr; innal laaha sa-yubtiluhoo; innal laaha laa yuslihu \'amalal mufsideen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>82,'arabic_text'=>'وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ','transliteration'=>'Wa-yuhiqqul laahul haqqa bi-Kalimaatihee Wa-law karihal mujrimoon','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>83,'arabic_text'=>'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفٖ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالٖ فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ','transliteration'=>'Famaaa aamana li-Moosaaa illaa zurriyyatun min qawmihee \'alaa khawfin min Fir\'awna Wa-mala\'ihim \'any yaftinahum; Wa-inna Fir\'awna la\'aalin fil ardi Wa-innahoo laminal musrifeen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>84,'arabic_text'=>'وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ','transliteration'=>'Wa-qaala Moosaa yaa-qawmi in kuntum aamantum billaahi fa\'alaihi tawakkalooo in kuntum muslimeen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>85,'arabic_text'=>'فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Faqaaloo \'alal laahi tawakkalnaa Rabbanaa laa taj\'alnaa fitnatal lilqawmiz zaalimeen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>86,'arabic_text'=>'وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-najjinaa birahmatika minal qawmil kaafireen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>87,'arabic_text'=>'وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-awhainaaa ilaa Moosaa Wa-akheehi an tabaw Wa-aali-qawmikuma bi-Misra buyootanw waj\'aloo buyootakum qiblatanw Wa-aqeemus Salaah; Wa-bashshiril mu\'mineen','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>88,'arabic_text'=>'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ','transliteration'=>'Wa-qaala Moosaa Rabbanaaa innaka aataita Fir\'awna Wa-mala ahoo zeenatanw Wa-amwaalan fil hayaatid dunyaa Rabbanaa liyudillo \'ansabeelika Rabbanat mis \'alaaa amwaalihim washdud \'alaa quloobihim falaa yu\'minoo hatta yarawul \'azaabal aleem','page_number'=>218,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>89,'arabic_text'=>'قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ','transliteration'=>'Qaala qad ujeebad da\'watukumaa fastaqeemaa Wa-laa tattabi\'aaanni sabeelal lazeena laa ya\'lamoon','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>90,'arabic_text'=>'۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Wa-jaawaznaa bi-Baneee Israaa\'eelal bahra fa-atba\'ahum Fir\'awnu Wa-junooduhoo baghyanw Wa-\'adwaa; hattaaa izaaa adrakahul gharaqu qaala aamantu annahoo laaa ilaaha illal lazeee aamanat bihee Banooo Israaa\'eela Wa-ana minal muslimeen','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>91,'arabic_text'=>'ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ','transliteration'=>'Aaal-\'aana Wa-qad \'asaita qablu Wa-kunta minal mufsideen','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>92,'arabic_text'=>'فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ','transliteration'=>'Falyawma nunajjeeka bibadanika litakoona liman khalfaka Aayah; Wa-inna kaseeran minan naasi \'an aayaatinaa laghaafiloon','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>93,'arabic_text'=>'وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Wa-laqad bawwa\'naa Baneee Israaa\'eela mubawwa \'a sidqinw Wa-razaqnaahum minat taiyibaati fa-makhtalafoo hattaa jaaa\'ahmul \'ilm; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>94,'arabic_text'=>'فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ','transliteration'=>'Fa-in kunta fee shakkin mimmaaa anzalnaaa ilaika fas\'alil lazeena yaqra\'oonal Kitaaba min qablik; laqad jaaa\'akal haqqu mir Rabbika fa-laa takoonanna minal mumtareen','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>95,'arabic_text'=>'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Wa-laa takoonanna minal lazeena kazzaboo bi-Aayaatil laahi fatakoona minal khaasireen','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>96,'arabic_text'=>'إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ','transliteration'=>'Innal lazeena haqqat \'alaihim Kalimatu Rabbika laa yu\'minoon','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>97,'arabic_text'=>'وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ','transliteration'=>'Wa-law jaaa\'at-hum kullu Aayatin hattaa yarawul \'azaabal aleem','page_number'=>219,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>98,'arabic_text'=>'فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ','transliteration'=>'Falaw-laa kaanat qaryatun aamanat fa-nafa\'ahaaa eemaanuhaaa illaa qawma Yoonusa lammaaa aamanoo kashafnaa \'anhum \'azaabal khizyi fil hayaatid dunyaa Wa-matta\'naahum ilaa heen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>99,'arabic_text'=>'وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ','transliteration'=>'Wa-law shaaa\'a Rabbuka la-aamana man fil ardi kulluhum jamee\'aa; afa-anta tukrihun naasa hattaa yakoonoo mu\'mineen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>100,'arabic_text'=>'وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ','transliteration'=>'Wa-maa kaana linafsin an tu\'mina illaa bi-iznil laah; Wa-yaj\'alur rijsa \'alal lazeena laa ya\'qiloon','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>101,'arabic_text'=>'قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمٖ لَّا يُؤۡمِنُونَ','transliteration'=>'Qulin zuroo maazaa fissamaawaati wal ard; Wa-maa tughnil Aayaatu wannuzuru \'an qawmil laa yu\'minoon','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>102,'arabic_text'=>'فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ','transliteration'=>'Fahal yantaziroona illaa misla ayyaamil lazeena khalaw min qablihim; qul fantazirooo innee ma\'akum minal muntazireen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>103,'arabic_text'=>'ثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Thumma nunajjee Rusulana wallazeena aamanoo; kazaalika haqqan \'alainaa nunjil mu\'mineen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>104,'arabic_text'=>'قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي شَكّٖ مِّن دِينِي فَلَآ أَعۡبُدُ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِي يَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Qul yaaa-ayyuhan naasu in kuntum fee shakk-in min deenee fa-laa a\'budul lazeena ta\'budoona min doonil laahi Wa-laakin a\'budul laahal lazee yatawaffaakum Wa-umirtu an akoona minal mu\'mineen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>105,'arabic_text'=>'وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Wa-an aqim wajhaka liddeeni Haneefanw Wa-laa takoonanna minal mushrikeen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>106,'arabic_text'=>'وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-laa tad\'u min doonil laahi maa laa yanfa\'uka Wa-laa yadurruk; fa-in fa\'alta fa-innaka izam minaz zaalimeen','page_number'=>220,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>107,'arabic_text'=>'وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Wa-ien yamsaskal laahu bidurrin falaa kaashifa lahoo illaa hoo;wa iny yuridka bikhairin falaa raaadda lifadlih; yuseebu bihee many yashaaa\'u min \'ibaadih; Wa-huwal Ghafoorur Raheem','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>108,'arabic_text'=>'قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلٖ','transliteration'=>'Qul yaaa-ayyuhan naasu qad jaaa\'akumul haqqu mir Rabbikum; famanih tadaa fa-innamaa yahtadee li-nafsih; Wa-man dalla fa-innamaa yadillu \'alaihaa; Wa-maaa ana \'alaikum bi-wakeel','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>10,'ayah_number'=>109,'arabic_text'=>'وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ','transliteration'=>'Wattabi\' maa yoohaaa ilaika wasbir hattaa yahkumal laah; Wa-Huwa khairul haakimeen','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            /* Surah 11: Hud (Hud) */
            ['surah_id'=>11,'ayah_number'=>1,'arabic_text'=>'الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ','transliteration'=>'Alif-Laaam-Raa; Kitaabun uhkimat Aayaatuhoo summa fussilat mil ladun Hakeemin Khabeer','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>2,'arabic_text'=>'أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرٞ وَبَشِيرٞ','transliteration'=>'Allaa ta\'budooo illal laah; innanee lakum minhu nazeerunw Wa-basheer','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>3,'arabic_text'=>'وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ','transliteration'=>'Wa-anis taghfiroo Rabbakum summa toobooo ilaihi yumatti\'kum mataa\'an hasanan ilaaa ajalim musammanw Wa-yu\'ti kulla zee fadlin fadlahoo Wa-in tawallaw fa-inneee akhaafu \'alaikum \'azaaba Yawmin Kabeer','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>4,'arabic_text'=>'إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Ilal laahi marji\'ukum Wa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>5,'arabic_text'=>'أَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Alaa innahum yasnoona sudoorahum liyastakhfoo minh; alaa heena yastaghshoona siyaabahum ya\'lamu maa yusirroona Wa-maa yu\'linoon; innahoo \'aleemun bizaatis sudoor','page_number'=>221,'juz_number'=>11,'hizb_number'=>22,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>6,'arabic_text'=>'۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ','transliteration'=>'Wa-maa min daaabbatin fil ardi illaa \'alal laahi rizquhaa Wa-ya\'lamu mustaqarrahaa Wa-mustawda\'ahaa; kullun fee Kitaabim Mubeen','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>7,'arabic_text'=>'وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ','transliteration'=>'Wa-Huwal lazee khalaqas samaawaati wal-arda fee sittati aiyaaminw Wa-kaana \'Arshuhoo alal maaa\'i liyabluwakum aiyyukum ahsanu \'amalaa; Wa-la\'in qulta innakum mab\'oosoona min ba\'dil mawti la-yaqoolannal lazeena kafaroo in haazaaa illaa sihrum mubeen','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>8,'arabic_text'=>'وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ أُمَّةٖ مَّعۡدُودَةٖ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wala\'in akharnaa \'anhumul \'azaaba ilaaa ummatim ma\'doodatil la-yaqoolunna maa yahbisuh; alaa yawma ya\'teehim laisa masroofan \'anhum Wa-haaqa bihim maa kaanoo bihee yastahzi\'oon','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>9,'arabic_text'=>'وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ','transliteration'=>'Wa-la\'in azaqnal insaana minnaa rahmatan summa naza\'naahaa minhu, innahoo laya\'oosun kafoor','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>10,'arabic_text'=>'وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ','transliteration'=>'Wala\'in azaqnaahu na\'maaa\'a ba\'da darraaa\'a massat-hu la-yaqoolanna zahabas saiyiaatu \'anneee; innahoo lafarihun fakhoor','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>11,'arabic_text'=>'إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ','transliteration'=>'Illal lazeena sabaroo Wa-\'amilus saalihaati ulaaa\'ika lahum maghfiratunw Wa-ajrun kabeer','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>12,'arabic_text'=>'فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرٞۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ','transliteration'=>'Fala\'allaka taarikum ba\'da maa yoohaaa ilaika Wa-daaa\'iqum bihee sadruka aien yaqooloo law-laaa unzila \'alaihi kanzun aw jaaa\'a ma\'ahoo malak; innamaa anta nazeer; wallaahu \'alaa kulli shai\'inw wakeel','page_number'=>222,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>13,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Am yaqooloonaf taraahu qul faatoo bi\'ashri Suwarim mislihee muftarayaatinw wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>14,'arabic_text'=>'فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ','transliteration'=>'Fa-il-lam yastajeeboo lakum fa\'lamooo annamaaa unzilla bi\'ilmil laahi Wa-al laaa ilaaha illaa Huwa fahal antum muslimoon','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>15,'arabic_text'=>'مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ','transliteration'=>'Man kaana yureedul hayaatad dunyaa zeenatahaa nuwaffi ilaihim a\'maa-lahum feehaa Wa-hum feehaa laa yubkhasoon','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>16,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ulaaa\'ikal lazeena laisa lahum fil Aakhirati illan Naaru Wa-habita maa sana\'oo feehaa Wa-baatilum maa kaanoo ya\'maloon','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>17,'arabic_text'=>'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ','transliteration'=>'Afaman kaana \'ala baiyyinatim mir Rabbihee Wa-yatloohu shaahidum minhu Wa-min qablihee Kitaabu Moosaaa imaamanw Wa-rahmah; ulaaa-\'ika yu\'minoona bih; Wa-main yakfur bihee minal Ahzaabi fan-naaru maw\'iduh; falaa taku fee miryatim minh; innahul haqqu mir Rabbika Wa-laakinna aksaran naasi laa yu\'minoon','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>18,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَٰٓئِكَ يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ','transliteration'=>'Wa-man azlamu mimmanif taraa \'alal laahi kazibaa; ulaaa\'ika yu\'radoona \'alaa Rabbihim Wa-yaqoolul ashhaa duhaaa\'ulaaa\'il lazeena kazaboo \'alaa Rabbihim; alaa la\'natul laahi alaz zaalimeen','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>19,'arabic_text'=>'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ','transliteration'=>'Allazeena yasuddoona \'an sabeelil laahi Wa-yabghoonahaa \'iwajanw Wa-hum bil Aakhiratihum kaafiroon','page_number'=>223,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>20,'arabic_text'=>'أُوْلَٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ','transliteration'=>'Ulaaa\'ika lam yakoonoo mu\'jizeena fil ardi Wa-maa kaana lahum min doonil laahi min awliyaaa\'; yudaa\'afu lahumul \'azaab; maa kaanoo yastatee\'oonas sam\'a Wa-maa kaanoo yubsiroon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>21,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Ulaaa\'ikal lazeena khasirooo anfusahum Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>22,'arabic_text'=>'لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ','transliteration'=>'Laa jarama annahum fil Aakhirati humul akhsaroon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>23,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati Wa-akhbatooo ilaa Rabbihim ulaaa\'ika Ashaabul Jannati hum feehaa khaalidoon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>24,'arabic_text'=>'۞ مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Masalul fareeqaini kal-a\'maa wal-asammi walbaseeri wassamee\'; hal yastawiyaani masalaa; afalaa tazakkaroon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>25,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ','transliteration'=>'Wa-laqad arsalnaa Noohan ilaa qawmihee innee lakum nazeerum mubeen','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>26,'arabic_text'=>'أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ','transliteration'=>'Al laa ta\'budooo illal laaha inneee akhaafu \'alaikum \'azaaba Yawmin aleem','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>27,'arabic_text'=>'فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ','transliteration'=>'Faqaalal mala-ul lazeena kafaroo min qawmihee ma naraaka illaa basharam mislanaa Wa-maa naraakat taba\'aka illal lazeena hum araazilunaa baadiyar raayi Wa-maa naraa lakum \'alainaa min fadlim bal nazunnukum kaazibeen','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>28,'arabic_text'=>'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ','transliteration'=>'Qaala yaa-qawmi ara\'aitum in kuntu \'alaa baiyyinatim mir Rabbee Wa-aataanee rahmatam min \'indihee fa\'um-miyat \'alaikum anulzimuku-moohaa Wa-antum lahaa kaarihoon','page_number'=>224,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>29,'arabic_text'=>'وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ','transliteration'=>'Wa-yaa-qawmi laaa as\'alukum \'alaihi maalan in ajriya illaa \'alal laah; Wa-maaa ana bitaaridil lazeena aamanoo; innahum mulaaqoo Rabbihim Wa-laakinneee araakum qawman tajhaloon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>30,'arabic_text'=>'وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Wa-yaa-qawmi main yansurunee minal laahi in tarattuhum; afalaa tazak-karoon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>31,'arabic_text'=>'وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-laa aqoolu lakum \'indee khazaa\'inul laahi Wa-laaa a\'lamul ghaiba Wa-laa aqoolu inee malakunw Wa-laaa aqoolu lillazeena tazdareee a\'yunukum lai yu\'tiyahumul laahu khairan Allaahu a\'lamu bimaa feee anfusihim innee izal laminaz zaalimeen','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>32,'arabic_text'=>'قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaaloo yaa-Noohu qad jaadaltanaa fa-aksarta jidaalanaa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>33,'arabic_text'=>'قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ','transliteration'=>'Qaala innamaa yaateekum bihil laahu in shaaa\'a Wa-maaa antum bimu\'jizeen','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>34,'arabic_text'=>'وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-laa yanfa\'ukum nusheee in arattu an ansaha lakum in kaanal laahu yureedu aien yughwi-yakum; Huwa Rabbukum Wa-ilaihi turja\'oon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>35,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ','transliteration'=>'Am yaqooloonaf taraahu qul inif taraituhoo fa\'alaiya ijraamee Wa-ana bareee\'um mimmaa tujrimoon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>36,'arabic_text'=>'وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ','transliteration'=>'Wa oohiya ilaa Noohin annahoo lany-yu\'mina min qawmika illaa man qad aamana falaa tabta\'is bimaa kaanoo yaf\'aloon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>37,'arabic_text'=>'وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ','transliteration'=>'Wasna\'il fulka bi-a\'yuninaa Wa-wahyinaa Wa-laa tukhaa-tibnee fil lazeena zalamoo; innahum mughraqoon','page_number'=>225,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>38,'arabic_text'=>'وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ','transliteration'=>'Wa-yasna\'ul fulka Wa-kullamaa marra \'alaihi mala\'um min qawmihee sakhiroo minh; qaala in taskharoo minnaa fa-innaa naskharu minkum kamaa taskharoon','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>39,'arabic_text'=>'فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ','transliteration'=>'Fasawfa ta\'lamoona mai ya\'teehi \'azaabuny yukhzeehi Wa-yahillu \'alaihi \'azaabun muqeem','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>40,'arabic_text'=>'حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ','transliteration'=>'Hattaaa izaa jaaa\'a amrunaa Wa-faarat tannooru qulnah mil feehaa min kullin zawjainis naini Wa-ahlaka illaa man sabaqa \'alaihil qawlu Wa-man aaman; Wa-maaa aamana ma\'ahooo illaa qaleel','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>41,'arabic_text'=>'۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-qaalar kaboo feehaa bismil laahi majraihaa Wa-mursaahaa; inna Rabbee la-Ghafoorur Raheem','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>42,'arabic_text'=>'وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-hiya tajree bihim fee mawjin kaljibaali Wa-naadaa Noohunib nahoo Wa-kaana fee ma\'zilien yaa-bunai yarkam ma\'anaa Wa-laa takum ma\'al kaafireen','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>43,'arabic_text'=>'قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ','transliteration'=>'Qaala sa-aaweee ilaa jabalien ya\'simunee minal maaa\'; qaala laa \'aasimal yawma min amril laahi illaa mar rahim; Wa-haala bainahumal mawju fakaana minal mughraqeen','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>44,'arabic_text'=>'وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-qeela yaaa ardubla\'ee maaa\'aki Wa-yaa-samaaa\'u aqli\'ee Wa-gheedal maaa\'u Wa-qudiyal amru wastawat \'alal joodiyyi Wa-qeela bu\'dal lilqawmiz zaalimeen','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>45,'arabic_text'=>'وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ','transliteration'=>'Wa naadaa noohur Rabbahoo faqaala Rabbi innabnee min ahlee Wa-inna wa\'dakal haqqu Wa-Anta ahkamul haakimeen','page_number'=>226,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>46,'arabic_text'=>'قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ','transliteration'=>'Qaala yaa-Noohu innahoo laisa min ahlika innahoo \'amalun ghairu saalihin falaa tas\'alni maa laisa laka bihee \'ilmun inneee a\'izuka an takoona minal jaahileen','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>47,'arabic_text'=>'قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Qaala rabbi inneee a\'oozu bika an as\'alaka maa laisa lee bihee \'ilmunw Wa-illaa taghfir lee Wa-tarhamneee akum minal khaasireen','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>48,'arabic_text'=>'قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ','transliteration'=>'Qeela yaa-Noohuh bit bisalaamim minnaa Wa-barakaatin \'alaika Wa-\'alaaa umamim mimmam ma\'ak; Wa-umamun sanumatti\'uhum summa yamassuhum minaa \'azaabun aleem','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>49,'arabic_text'=>'تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ','transliteration'=>'Tilka min ambaaa\'il ghaibi nooheehaaa ilaika maa kunta ta\'lamuhaaaa anta Wa-laa qawmuka min qabli haazaa fasbir innal \'aaqibata lilmuttaqeen','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>50,'arabic_text'=>'وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ','transliteration'=>'Wa-ilaa \'aadin akhaahum Hoodaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuhooo in antum illaa muftaroon','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>51,'arabic_text'=>'يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Yaa-qawmi laaa as\'alukum \'alaihi ajran in ajriya illaa \'alal lazee fataranee; afalaa ta\'qiloon','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>52,'arabic_text'=>'وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ','transliteration'=>'Wa-yaa-qawmis taghfiroo Rabbakum summa toobooo ilaihi yursilis samaaa\'a \'alaikum midraaranw Wa-yazidkum quwwatan ilaa quwwatikum Wa-laa tatawallaw mujrimeen','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>53,'arabic_text'=>'قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ','transliteration'=>'Qaaloo yaa-Hoodu maa ji\'tanaa bibaiyinatinw Wa-maa nahnu bitaarikeee aalihatinaa \'an qawlika Wa-maa nahnu laka bimu\'mineen','page_number'=>227,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>54,'arabic_text'=>'إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ','transliteration'=>'In naqoolu illa\' taraaka ba\'du aalihatinaa bisooo\'; qaala inneee ushhidul laaha wash-hadooo annee bareee\'um mimmaa tushrikoon','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>55,'arabic_text'=>'مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ','transliteration'=>'Min doonihee fakeedoonee jamee\'an summa laa tunziroon','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>56,'arabic_text'=>'إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Innee tawakkaltu \'alal laahi Rabbee Wa-Rabbikum; maa min daaabbatin illaa Huwa aakhizum binaasiyatihaa; inna Rabbee \'alaa Siraatim mustaqeem','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>57,'arabic_text'=>'فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ','transliteration'=>'Fa-in tawallaw faqad ablaghtukum maaa ursiltu biheee ilaikum; Wa-yastakhlifu Rabbee qawman ghairakum Wa-laa tadur-roonahoo shai\'aa; inna Rabbee \'alaa kulli shai\'in Hafeez','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>58,'arabic_text'=>'وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ','transliteration'=>'Wa-lammaa jaaa\'a amrunaa naj-jainaa Hoodanw wallazeena aamanoo ma\'ahoo birahmatim minnaa Wa-naj-jainaahum min \'azaabin ghaleez','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>59,'arabic_text'=>'وَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ','transliteration'=>'Wa-tilka \'aad, jahadoo bi-Aayaati Rabbihim Wa-\'asaw Rusulahoo wattaba\'ooo amra kulli jabbaarin \'aneed','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>60,'arabic_text'=>'وَأُتۡبِعُواْ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ','transliteration'=>'Wa-utbi\'oo fee haazihid dunyaa la\'natanw Wa-Yawmal Qiyaamah; alaaa inna \'Aadan kafaroo Rabbahum; alaa bu\'dal li-\'Aadin qawmin Hood','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>61,'arabic_text'=>'۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ','transliteration'=>'Wa-ilaa Samooda akhaahum Saalihaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahim ghairuhoo Huwa ansha-akum minal ardi wasta\'-marakum feehaa fastaghfiroohu summa toobooo ilaih; inna Rabbee Qareebum Mujeeb','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>62,'arabic_text'=>'قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ','transliteration'=>'Qaaloo yaa-Saalihu qad kunta feenaa marjuwwan qabla haazaaa atanhaanaaa an na\'bu-da maa ya\'budu aabaaa\'unaa Wa-innanaa lafee shakkim mimmaa tad\'oonaaa ilaihi mureeb','page_number'=>228,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>63,'arabic_text'=>'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ','transliteration'=>'Qaala yaa-qawmi ara\'aytum in kuntu \'alaa baiyinatim mir Rabbee Wa-aataanee minhu rahmatan famai yansurunee minal laahi in \'asaituhoo famaa tazeedoonanee ghaira takhseer','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>64,'arabic_text'=>'وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ','transliteration'=>'Wa-yaa-qawmi haazihee naaqatul laahi lakum aayatan fazaroohaa taakul feee ardil laahi Wa-laa tamassoohaa bisooo\'in fa-yaakhuzakum azaabun qareeb','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>65,'arabic_text'=>'فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ','transliteration'=>'Fa-\'aqaroohaa faqaala tamatta\'oo fee daarikum salaasata aiy-yaamin zaalika wa\'dun ghairu makzoob','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>66,'arabic_text'=>'فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ','transliteration'=>'Falammaa jaaa\'a amrunaa najjainaa Saalihanw wal-lazeena aamanoo ma\'ahoo birahmatim minnaa Wa-min khizyi Yawmi\'iz inna Rabbaka Huwal Qawiyyul \'Azeez','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>67,'arabic_text'=>'وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ','transliteration'=>'Wa-akhazal lazeena zalamus saihatu fa-asbahoo fee diyaarihim jaasimeen','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>68,'arabic_text'=>'كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ','transliteration'=>'Ka-al lam yaghnaw feehaaa; alaaa inna Samooda kafaroo Rabbahum; alaa bu\'dal li-Samood','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>69,'arabic_text'=>'وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ','transliteration'=>'Wa-laqad jaaa\'at Rusulunaaa Ibraaheema bilbushraa qaaloo salaaman qaala salaamun famaa labisa an jaaa\'a bi\'ij-lin haneez','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>70,'arabic_text'=>'فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ','transliteration'=>'Falammaa ra-aaa aidiyahum laa tasilu ilaihi nakirahum Wa-awjasa minhum kheefah; qaaloo laa takhaf innaaa ursilnaaa ilaa qawmi Loot','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>71,'arabic_text'=>'وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ','transliteration'=>'Wamra-atuhoo qaaa\'imatun fadahikat fabashsharnaahaa bi-Iss-haaqa Wa-minw waraaa\'i Iss-haaqa Ya\'qoob','page_number'=>229,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>72,'arabic_text'=>'قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ','transliteration'=>'Qaalat yaa-wailataaa \'aalidu Wa-ana \'ajoozunw Wa-haaza ba\'lee shaikhan inna haazaa lashai\'un \'ajeeb','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>73,'arabic_text'=>'قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ','transliteration'=>'Qaalooo ata\'jabeena min amril laahi rahmatul laahi Wa-barakaatuhoo \'alaikum Ahlal Bayt; innahoo Hameedun Majeed','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>74,'arabic_text'=>'فَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ','transliteration'=>'Falammaa zahaba an Ibraaheemar raw\'u Wa-jaaa\'at hul-bushraaa yujaadilunaa fee qawmi Loot','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>75,'arabic_text'=>'إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٞ مُّنِيبٞ','transliteration'=>'Inna Ibraaheema la-haleemun awwaahun muneeb','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>76,'arabic_text'=>'يَٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودٖ','transliteration'=>'Yaaa-Ibraaheemu a\'rid \'an haazaaa innahoo qad jaaa\'a amru Rabbika Wa-innahum aateehim \'azaabun ghairun mardood','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>77,'arabic_text'=>'وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ','transliteration'=>'Wa-lammaa jaaa\'at Rusulunaa Lootan seee\'a bihim Wa-daaqa bihim zar\'anw Wa-qaala haazaa yawmun \'aseeb','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>78,'arabic_text'=>'وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ','transliteration'=>'Wa-jaaa\'ahoo qawmuhoo yuhra\'oona ilaihi Wa-min qablu kaanoo ya\'maloonas saiyyiaat; qaala yaa-qawmi haaa\'ulaaa\'i banaatee hunna atharu lakum fattaqul laaha Wa-laa tukhzooni fee daifee alaisa minkum rajulur rasheed','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>79,'arabic_text'=>'قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ','transliteration'=>'Qaaloo laqad \'alimta maa lanaa fee banaatika min haqq, Wa-innaka lata\'lamu maa nureed','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>80,'arabic_text'=>'قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ','transliteration'=>'Qaala law anna lee bikum quwwatan aw aaweee ilaa ruknin shadeed','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>81,'arabic_text'=>'قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ','transliteration'=>'Qaaloo yaa-Lootu innaa Rusulu Rabbika lain yasiloo ilaika fa-asri bi-ahlika biqit-\'im minal laili Wa-laa yaltafit minkum ahadun illam ra-ataka innahoo museebuhaa maaa asaabahum; inna maw\'i-dahumus subh; alaisas subhu biqareeb','page_number'=>230,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>82,'arabic_text'=>'فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ','transliteration'=>'Falammaa jaaa\'a amrunaa ja\'alnaa \'aaliyahaa saafilahaa Wa-amtamaa \'alaihaa hijaaratam min sijjeelim mandood','page_number'=>231,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>83,'arabic_text'=>'مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ','transliteration'=>'Musawwamatan \'inda Rabbik; Wa-maa hiya minaz zaalimena biba\'eed','page_number'=>231,'juz_number'=>12,'hizb_number'=>23,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>84,'arabic_text'=>'۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ','transliteration'=>'Wa-ilaa Madyana akhaahum Shu\'aibaa; qaala yaa-qawmi\' budul laaha maa lakum min ilaahin ghairuhoo Wa-laa tanqusul mikyaala walmeezaan; inneee araakum bikhairinw Wa-innee akhaafu \'alaikum \'azaaba Yawmim muheet','page_number'=>231,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>85,'arabic_text'=>'وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','transliteration'=>'Wa-yaa-qawmi awful mikyaala walmeezaana bilqisti Wa-laa tabkhasun naasa ashyaaa\'ahum Wa-laa ta\'saw fil ardi mufsideen','page_number'=>231,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>86,'arabic_text'=>'بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ','transliteration'=>'Baqiyyatul laahi khairul lakum in kuntum mu\'mineen; Wa-maa ana \'alaikum bihafeez','page_number'=>231,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>87,'arabic_text'=>'قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ','transliteration'=>'Qaaloo yaa-Shu\'aybu \'a-salaatuka ta\'muruka an natruka maa ya\'budu aabaaa\'unaaa aw an naf\'ala feee amwaalinaa maa nashaaa\'oo innaka la-antal haleemur rasheed','page_number'=>231,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>88,'arabic_text'=>'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ','transliteration'=>'Qaala yaa qawmi ara\'aitum in kuntu \'alaa baiyinatim mir Rabbee Wa-razaqanee minhu rizqan hasanaa; Wa-maaa ureedu an ukhaalifakum ilaa maaa anhaakum \'anh; in ureedu illal islaaha mastata\'t; Wa-maa tawfeeqeee illaa billaah; \'alaihi tawakkaltu Wa-ilaihi uneeb','page_number'=>231,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>89,'arabic_text'=>'وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ','transliteration'=>'Wa-yaa-qawmi laa yajri-mannakum shiqaaqeee aien yuseebakum mislu maaa asaaba qawma Noohin aw qawma Hoodin aw qawma Saalih; Wa-maa qawmu Lootim minkum biba\'eed','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>90,'arabic_text'=>'وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ','transliteration'=>'Wastaghfiroo Rabbakum summa toobooo ilaih; inna Rabbee Raheemunw Wadood','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>91,'arabic_text'=>'قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ','transliteration'=>'Qaaloo yaa-Shu\'aibu maa nafqahu kaseeram mimmaa taqoolu Wa-innaa lanaraaka feenaa da\'eefanw Wa-law-laa rahtuka larajamnaaka Wa-maaa anta \'alainaa bi\'azeez','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>92,'arabic_text'=>'قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ','transliteration'=>'Qaala yaa-qawmi arahteee a\'azzu \'alaikum minal laahi wattakhaztumoohu waraaa\'akum zihriyyan inna Rabbee bimaa ta\'maloona muheet','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>93,'arabic_text'=>'وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ','transliteration'=>'Wa-yaa-qawmi\' maloo \'alaa makaanatikum innee \'aamilun sawfa ta\'lamoona many ya\'teehi \'azaabuny yukhzeehi Wa-man huwa kaazib; wartaqibooo innnee ma\'akum raqeeb','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>94,'arabic_text'=>'وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ','transliteration'=>'Wa-lammaa jaaa\'a amrunaa najjainaa shu\'aibanw wal-lazeena aamanoo ma\'ahoo birahmatim minnaa Wa-akhazatil lazeena zalamus saihatu fa-asbahoo fee diyaarihim jaasimeen','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>95,'arabic_text'=>'كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ','transliteration'=>'Ka-al lam yaghnaw feehaaa; alaa bu\'dal li-Madyana Kamaa ba\'idat Samood','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>96,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ','transliteration'=>'Wa-laqad arsalnaa Moosaa bi-Aayaatinaa Wa-sultaanim mubeen','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>97,'arabic_text'=>'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدٖ','transliteration'=>'Ilaa Fir\'awna Wa-mala\'ihee fattaba\'ooo amra Fir\'awna Wa-maaa amru Fir\'awna birasheed','page_number'=>232,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>98,'arabic_text'=>'يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ','transliteration'=>'Yaqdumu qawmahoo Yawmal Qiyaamati fa-awrada-humun Naara Wa-bi\'sal wirdul mawrood','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>99,'arabic_text'=>'وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ','transliteration'=>'Wa-utbi\'oo fee haazihee la\'natanw Wa-Yawmal Qiyaamah; bi\'sar rifdul marfood','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>100,'arabic_text'=>'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ مِنۡهَا قَآئِمٞ وَحَصِيدٞ','transliteration'=>'Zaalika min ambaaa\'il quraa naqussuhoo \'alaika minhaa qaaa\'imunw Wa-haseed','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>101,'arabic_text'=>'وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبٖ','transliteration'=>'Wa-maa zalamnaahum Wa-laakin zalamooo anfusahum famaaa aghnat \'anhum aalihatuhumul latee yad\'oona min doonil laahi min shai\'il lammaa jaaa\'a amru Rabbika Wa-maa zaadoohum ghaira tatbeeb','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>102,'arabic_text'=>'وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ','transliteration'=>'Wa-kazaalika akhzu Rabbika izaaa akhazal quraa Wa-hiya zaalimah; inna akhzahooo aleemun shadeed','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>103,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ ذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ','transliteration'=>'Inna fee zaalika la-aayatal liman khaafa \'azaabal Aakhirah; zaalika Yawmum majmoo\'ul lahun naasu Wa-zaalika Yawmum mashhood','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>104,'arabic_text'=>'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ','transliteration'=>'Wa-maa nu\'akhkhiruhooo illaa li-ajalim ma\'dood','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>105,'arabic_text'=>'يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيّٞ وَسَعِيدٞ','transliteration'=>'Yawma yaati laa takallamu nafsun illaa bi-iznih; faminhum shaqiyyunw Wa-sa\'eed','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>106,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ','transliteration'=>'Fa-ammal lazeena shaqoo fafin Naari lahum feehaa zafeerunw Wa-shaheeq','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>107,'arabic_text'=>'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ','transliteration'=>'Khaalideena feehaa maa daamatis samaawaatu wal-ardu illaa maa shaaa\'a Rabbuk; inna Rabbaka fa\'-\'aalul limaa yureed','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>108,'arabic_text'=>'۞ وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ','transliteration'=>'Wa-ammal lazeena su\'idoo fafil Jannati khaalideena feehaa maa daamatis samaawaatu wal-ardu illaa maa shaaa\'a Rabbuk; ataaa\'an ghaira majzooz','page_number'=>233,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>109,'arabic_text'=>'فَلَا تَكُ فِي مِرۡيَةٖ مِّمَّا يَعۡبُدُ هَٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصٖ','transliteration'=>'Falaa taku fee miryatim mimmmaa ya\'budu haaa\'ulaaa\'; maa ya\'budoona illaa kamaa ya\'budu aabaaa\'uhum min qabl; Wa-innaa lamuwaf-foohum naseebahum ghaira manqoos','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>110,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba fakhtulifa feeh; Wa-law-laa Kalimatun sabaqat mir Rabbika laqudiya bainahum; Wa-innahum lafee shakkim minhu mureeb','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>111,'arabic_text'=>'وَإِنَّ كُلّٗا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Wa-inna kullal lammaa la-yuwaffiyannahum Rabbuka a\'maalahum; innahoo bimaa ya\'maloona Khabeer','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>112,'arabic_text'=>'فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Fastaqim kamaaa umirta Wa-man taaba ma\'aka Wa-laa tatghaw; innahoo bimaa ta\'maloona Baseer','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>113,'arabic_text'=>'وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ','transliteration'=>'Wa-laa tarkanooo ilal lazeena zalamoo fatamassa-kumun Naaru Wa-maa lakum min doonil laahi min awliyaaa\'a summa laa tunsaroon','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>114,'arabic_text'=>'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّٰكِرِينَ','transliteration'=>'Wa-aqimis Salaata tarafayin nahaari Wa-zulafam minal layl; innal hasanaati yuzhibnas saiyi-aat; zaalika zikraa liz-zaakireen','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>115,'arabic_text'=>'وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wasbir fa-innal laaha laa yudee\'u ajral muhsineen','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>116,'arabic_text'=>'فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ','transliteration'=>'Falaw-laa kaana minal qurooni min qablikum ooloo baqiyyatiny yanhawna \'anil fasaadi fil ardi illaa qaleelam mimman anjainaa minhum; wattaba\'al lazeena zalamoo maaa utrifoo feehi Wa-kaanoo mujrimeen','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>117,'arabic_text'=>'وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ','transliteration'=>'Wa-maa kaana Rabbuka liyuhlikal quraa bizulminw Wa-ahluhaa muslihoon','page_number'=>234,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>118,'arabic_text'=>'وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ','transliteration'=>'Wa-law shaaa\'a Rabbuka laja\'al annnaasa ummatanw waa-hidatanw Wa-laa yazaaloona mukhtalifeen','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>119,'arabic_text'=>'إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ','transliteration'=>'Illaa mar rahima Rabbuk; Wa-lizaalika khalaqahum; Wa-tammat Kalimatu Rabbika la-amla\'ana Jahannama minal jinnati wannnaasi ajma\'een','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>120,'arabic_text'=>'وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةٞ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ','transliteration'=>'Wa-kullan naqussu \'alaika min ambaaa\'ir Rusuli maa nusabbitu bihee fu\'aadak; Wa-jaaa\'aka fee haazihil haqqu Wa-maw\'izatunw Wa-zikraa lilmu\'-mineen','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>121,'arabic_text'=>'وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ','transliteration'=>'Wa-qul lillazeena laa yu\'minoo na\'maloo \'alaa makaanatikum innaa \'aamiloon','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>122,'arabic_text'=>'وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ','transliteration'=>'Wantaziroo innaa mun-taziroon','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>11,'ayah_number'=>123,'arabic_text'=>'وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Wa-lillaahi ghaibus samaawaati wal-ardi Wa-ilaihi yurja\'ul amru kulluhoo fa\'bud-hu Wa-tawakkal \'alaih; Wa-maa Rabbuka bighaafilin \'ammaa ta\'maloon','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            /* Surah 12: Joseph (Yusuf) */
            ['surah_id'=>12,'ayah_number'=>1,'arabic_text'=>'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ','transliteration'=>'Alif-Laaam-Raa; tilka Aayaatul Kitaabil Mubeen','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>2,'arabic_text'=>'إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Innaaa anzalnaahu quraanan \'Arabiyyal la-\'allakum ta\'qiloon','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>3,'arabic_text'=>'نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَٰفِلِينَ','transliteration'=>'Nahnu naqussu \'alaika ahsanal qasasi bimaaa awhainaaa ilaika haazal quraana Wa-in kunta min qablihee laminal ghaafileen','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>4,'arabic_text'=>'إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ','transliteration'=>'Iz qaala Yoosufu li-abeehi yaaa-abati innee ra-aytu ahada \'ashara kawkabanw wash-shamsa walqamara ra-aytuhum lee saajideen','page_number'=>235,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>5,'arabic_text'=>'قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ','transliteration'=>'Qaala yaa-bunaiya laa taqsus ru\'yaaka \'alaaa ikhwatika fayakeedoo laka kaidaa; innash Shaitaana lil-insaani \'aduwwum mubeen','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>6,'arabic_text'=>'وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ','transliteration'=>'Wa-kazaalika yajtabeeka rabbuka Wa-yu\'allimuka min ta\'weelil ahaadeesi Wa-yutimmu ni\'matahoo \'alaika Wa-\'alaaa Aali Ya\'qooba kamaaa atammahaa \'alaaa abawaika min qablu Ibraaheema Wa-Ishaaq; inna Rabbaka \'Aleemun hakeem','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>7,'arabic_text'=>'۞ لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ','transliteration'=>'Laqad kaana fee Yoosufa Wa-ikhwatiheee Aayaatul lissaaa\'ileen','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>8,'arabic_text'=>'إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ','transliteration'=>'Iz qaaloo la-Yoosufu Wa-akhoohu ahabbu ilaaa Abeenaa minnaa Wa-nahnu \'usbatun; inna abaanaa lafee dalaalim mubeen','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>9,'arabic_text'=>'ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ','transliteration'=>'Uqtuloo Yoosufa awitra hoohu ardany yakhlu lakum wajhu abeekum Wa-takoonoo mim ba\'dihee qawman saaliheen','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>10,'arabic_text'=>'قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ','transliteration'=>'Qaalaa qaaa\'ilum minhum laa taqtuloo Yoosufa Wa-alqoohu fee ghayaabatil jubbi yaltaqithu badus sai-yaarati in kuntum faa-\'ileen','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>11,'arabic_text'=>'قَالُواْ يَٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ','transliteration'=>'Qaaloo yaaa-abaanaa maa laka laa ta\'mannaa \'alaa Yoosufa Wa-innaa lahoo lanaa-sihoon','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>12,'arabic_text'=>'أَرۡسِلۡهُ مَعَنَا غَدٗا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ','transliteration'=>'Arsillhu ma\'anaa ghadany yarta\'wa yal\'ab Wa-innaa lahoo lahaafizoon','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>13,'arabic_text'=>'قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ','transliteration'=>'Qaala innee la-yahzununeee an tazhaboo bihee Wa-akhaafu any ya\'kulahuz zi\'bu Wa-antum \'anhu ghaafiloon','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>14,'arabic_text'=>'قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ','transliteration'=>'Qaaloo la-in akalahuz zi\'bu Wa-nahnu \'usbatun innaaa izal lakhaasiroon','page_number'=>236,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>15,'arabic_text'=>'فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Falammaa zahaboo bihee Wa-ajma\'ooo aien yaj\'aloohu fee ghayaabatil jubb; Wa-awhainaaa ilaihi latunabbi-\'annahum bi-amrihim haaza Wa-hum laa yash\'uroon','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>16,'arabic_text'=>'وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ','transliteration'=>'Wa-jaaa\'ooo abaahum \'ishaaa-\'aien yabkoon','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>17,'arabic_text'=>'قَالُواْ يَٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ','transliteration'=>'Qaaloo yaaa-abaanaaa innaa zahabnaa nastabiqu Wa-taraknaa Yoosufa \'inda mataa\'inaa fa-akhalahuz zi\'b, Wa-maaa anta bimu\'minil lanaa Wa-law kunnaa saadiqeen','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>18,'arabic_text'=>'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ','transliteration'=>'Wa-jaaa\'oo \'alaa qameesi-hee bidamin kazib qaala bal sawwalat lakum anfusukum amraa; fasabrun jameel; wallaahul musta\'aanu \'alaa maa tasifoon','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>19,'arabic_text'=>'وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ','transliteration'=>'Wa-jaaa\'at saiyyaaratun fa-arsaloo waaridahum fa-adlaa dalwah; qaala yaa-bushraa haaza ghulaam; Wa-asarroohu bi-daa\'ah; wallaahu \'aleemum bimaa ya\'maloon','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>20,'arabic_text'=>'وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّٰهِدِينَ','transliteration'=>'Wa-sharawhu bisamanim bakhsin daraahima ma\'doo-datinw Wa-kaanoo feehi minaz zaahideen','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>21,'arabic_text'=>'وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Wa-qaalal lazish taraahu mim Misra limra atiheee akrimee maswaahu \'asaaa any-yanfa\'anaaa aw nattakhizahoo waladaa; Wa-kazaalika mak-kannaa li-Yoosufa fil ardi Wa-linu\'allimahoo min ta\'weelil ahaadees; wallaahu ghaalibun \'alaaa amrihee Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>22,'arabic_text'=>'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-lammaa balagha ashuddahooo aatainaahu hukmanw Wa-\'ilmaa; Wa-kazaa-lika najzil muhsineen','page_number'=>237,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>23,'arabic_text'=>'وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ','transliteration'=>'Wa-raawadat-hul latee huwa fee baitihaa \'an nafsihee Wa-ghallaqatil abwaaba Wa-qaalat haita lak; qaala ma\'aazal laahi innahoo rabbeee ahsana maswaay; innahoo laa yuflihuz zaalimoon','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>24,'arabic_text'=>'وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ','transliteration'=>'Wa-laqad hammat bihee Wa-hamma bihaa law-laaa ar ra-aa burhaana rabbih; kazaalika linasrifa \'anhu sooo\'a walfa-hshaaa\'; innahoo min \'ibaadi-nal mukhlaseen','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>25,'arabic_text'=>'وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wastabaqal baaba Wa-qaddat qameesahoo min duburinw Wa-alfayaa saiyidahaa ladal baab; qaalat maa jazaaa\'u man araada bi ahlika sooo\'an illaaa any-yusjana aw azaabun \'aleem','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>26,'arabic_text'=>'قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Qaala hiya raawadatnee \'an nafsee Wa-shahida shaahidum min ahlihaa in kaana qameesuhoo qudda min qubulin fasadaqat Wa-huwa minal kaazibeen','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>27,'arabic_text'=>'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Wa-in kaana qameesuhoo qudda min duburin fakazabat Wa-huwa minas saadiqeen','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>28,'arabic_text'=>'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ','transliteration'=>'Falammaa ra-aa qamee-sahoo qudda min duburin qaala innahoo min kaidikunna inna kaidakunna \'azeem','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>29,'arabic_text'=>'يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ','transliteration'=>'Yoosufu a\'rid \'an haaza wastaghfiree li-zanbiki innaki kunti minal khaati\'een','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>30,'arabic_text'=>'۞ وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Wa-qaala niswatun fil madeenatim ra-atul \'Azeezi turaawidu fataahaa \'an nafsihee qad shaghafahaa hubbaa; innaa lana-raahaa fee dalaalim mubeen','page_number'=>238,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>31,'arabic_text'=>'فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ','transliteration'=>'Falammaa sami\'at bimak-rihinna arsalat ilaihinna Wa-a\'tadat lahunna muttaka-anw Wa-aatat kulla waahidatim min-hunna sikkeenanw Wa-qaala-tikh ruj \'alaihinna falammaa ra-aynahooo akbarnahoo Wa-qatta\'na aydiyahunna Wa-qulna haasha lillaahi maa haaza basharaa; in haazaaa illaa malakun kareem','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>32,'arabic_text'=>'قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّٰغِرِينَ','transliteration'=>'Qaalat fazaalikunnal lazee lumtunnanee feeh; Wa-laqad raawattuhoo \'an nafsihee fasta\'sam; Wa-la\'il lam yaf\'al maaa aamuruhoo la-yusjananna Wa-la-yakoonam minas saaghireen','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>33,'arabic_text'=>'قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ','transliteration'=>'Qaala rabbis sijnu ahabbu ilaiyya mimma yad\'oo-naneee \'ilaihi Wa-illaa tasrif \'annee kaidahunna asbu ilaihinna Wa-akum minal jaahileen','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>34,'arabic_text'=>'فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Fastajaaba lahoo rabbuhoo fasarafa \'anhu kaidahunn; innahoo huwas Samee\'ul \'Aleem','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>35,'arabic_text'=>'ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ','transliteration'=>'Summa badaa lahum min ba\'di maa ra-awul Aayaati layasjununnahoo hatta heen','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>36,'arabic_text'=>'وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-dakhala ma\'a hussijna fata-yaan; qaala ahaduhumaaa inneee araaneee a\'siru khamranw Wa-qaalal aakharu inneee araaneee ahmilu fawqa ra\'see khubzan ta\'kulut tairu minhu; nabbi\'naa bi-ta\'weelih; innaa naraaka minal muhsineen','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>37,'arabic_text'=>'قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ','transliteration'=>'Qaala laa ya\'teekumaa ta\'aamun turzaqaaniheee illaa nabba\'tukumaa bi-ta\'weelihee; qabla aien ya\'ti-yakumaa; zaalikumaa mimmaa \'allamanee rabbee; innee taraktu millata qawmil laa yu\'minoona billaahi wahum bil-aakhirati hum kaafiroon','page_number'=>239,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>38,'arabic_text'=>'وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ','transliteration'=>'Wattaba\'tu millata aabaaa\'eee Ibraaheema Wa-Iss-haaqa Wa-Ya\'qoob; maa kaana lanaaa an nushrika billaahi min shai\'; zaalika min fadlil laahi \'alainaa Wa-\'alan naasi Wa-laakinna aksaran naasi laa yashkuroon','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>39,'arabic_text'=>'يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ','transliteration'=>'Yaa-saahibayis sijni \'a-arbaabum mutafarriqoona khayrun amil laahul waahidul qahhaar','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>40,'arabic_text'=>'مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Maa ta\'budoona min doonihee illaaa asmaaa\'an sam maitumoohaaa antum Wa-aabaaa\'ukum maaa anzalal laahu bihaa min sultan; inilhukmu illaa lillaah; amara allaa ta\'budooo illaaa iyyaah; zaalikad deenul qaiyimu Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>41,'arabic_text'=>'يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ','transliteration'=>'Yaa-saahibayis sijni ammaaa ahadukumaa fa-yasqee rabbahoo khamranw Wa-ammal aakharu fa-yuslabu fata\'kulut tairu mir ra\'sih; qudiyal amrul lazee feehi tastaftiyaan','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>42,'arabic_text'=>'وَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ','transliteration'=>'Wa-qaala lillazee zanna annahoo najim minhumaz kurnee \'inda rabbika fa-ansaahush Shaitaanu zikra Rabbihee falabisa fis sijni bid\'a sineen','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>43,'arabic_text'=>'وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ','transliteration'=>'Wa-qaalal maliku inneee araa sab\'a baqaraatin simaanien ya\'kuluhunna sab\'un \'ijaafunw Wa-sab\'a sumbulaatin khudrinw Wa-ukhara yaabisaat; yaaa-ayyuhal mala-u aftoonee fee ru\'yaaya in kuntum lirru\'yaa ta\'buroon','page_number'=>240,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>44,'arabic_text'=>'قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ','transliteration'=>'Qaalooo adghaasu ahlaa-minw Wa-maa nahnu bi-ta\'weelil ahlaami bi\'aalimeen','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>45,'arabic_text'=>'وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ','transliteration'=>'Wa-qaalal lazee najaa minhumaa waddakara ba\'da ummatin ana unabbi\'ukum bi-ta\'weelihee fa-arsiloon','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>46,'arabic_text'=>'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ','transliteration'=>'Yoosufu ayyuhas siddeequ aftinaa fee sab\'i baqaraatin simaaniny ya\'kuluhunna sab\'un \'ijaafunw Wa-sabi\'i sumbulaatin khudrinw Wa-ukhara yaabisaatil la\'alleee arji\'u ilan naasi la\'allahum ya\'lamoon','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>47,'arabic_text'=>'قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ','transliteration'=>'Qaala tazra\'oona sab\'a sineena da-aban famaa hasattum fazaroohu fee sumbu-liheee illaa qaleelam mimmaa ta\'kuloon','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>48,'arabic_text'=>'ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ','transliteration'=>'Thumma ya\'tee mim ba\'di zaalika sab\'un shidaaduny ya\'kulna maa qaddamtum lahunna illaa qaleelam mimma tuhsinoon','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>49,'arabic_text'=>'ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ','transliteration'=>'Thumma ya\'tee mim ba\'di zalika \'aamun feehi yughaa-sun naasu Wa-feehi ya\'siroon','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>50,'arabic_text'=>'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ','transliteration'=>'Wa-qaalal maliku \'toonee bihee falammaa jaaa\'ahur rasoolu qaalar ji ilaa rabbika fas\'alhu maa baalun niswatil laatee qatta\'na aydiyahunn; inna Rabbee bikaidihinna \'Aleem','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>51,'arabic_text'=>'قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaala maa khatbukunna iz raawattunna Yoosufa \'an nafsih; qulna haasha lillaahi maa \'alimnaa \'alaihi min sooo\'; qaalatim ra-atul \'Azeezil \'aana hashasal haqq, ana raawat-tuhoo \'an nafsihee Wa-innahoo laminas saadiqeen','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>52,'arabic_text'=>'ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ','transliteration'=>'Zaalika liya\'lama annee lam akhunhu bilghaibi Wa-annal laaha laa yahdee kaidal khaaa\'ineen','page_number'=>241,'juz_number'=>12,'hizb_number'=>24,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>53,'arabic_text'=>'۞ وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-maa ubarri\'u nafsee; innan nafsa la-ammaaratum bissooo\'i illaa maa rahima Rabbee; inna Rabbee Ghafoorur Raheem','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>54,'arabic_text'=>'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ','transliteration'=>'Wa-qaalal maliku\' toonee biheee astakhlishu linafsee falammaa kallamahoo qaala innakal yawma ladainaa makeenun ameen','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>55,'arabic_text'=>'قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ','transliteration'=>'Qaalaj \'alnee \'alaa khazaaa\'inil ardi innee hafeezun \'aleem','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>56,'arabic_text'=>'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-kazaalika makkannaa li-Yoosufa fil ardi yatabawwa\'u minhaa haisu yashaaaa\'; nuseebu birahmatinaa man nashaaa\'u Wa-laa nudee\'u ajral muhsineen','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>57,'arabic_text'=>'وَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ','transliteration'=>'Wa-la-ajrul Aakhirati khairul lillazeena aamanoo Wa-kaanoo yattaqoon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>58,'arabic_text'=>'وَجَآءَ إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ','transliteration'=>'Wa-jaaa\'a ikhwatu Yoosufa fadakhaloo \'alaihi fa\'arafahum Wa-hum lahoo munkiroon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>59,'arabic_text'=>'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ','transliteration'=>'Wa-lammaa jahhazahum bijahaazihim qaala\' toonee bi-akhil lakum min abeekum; alaa tarawna anneee oofil kaila Wa-ana khairul munzileen','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>60,'arabic_text'=>'فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ','transliteration'=>'Fa-il lam taatoonee bihee falaa kaila lakum \'indee Wa-laa taqraboon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>61,'arabic_text'=>'قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ','transliteration'=>'Qaaloo sanuraawidu \'anhu abaahu Wa-innaa lafaa\'iloon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>62,'arabic_text'=>'وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-qaala lifityaanihij \'aloo bidaa\'atahum fee rihaalihim la\'allahum ya\'rifoonahaaa izan qalabooo ilaaa ahlihim la\'allahum yarji\'oon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>63,'arabic_text'=>'فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ','transliteration'=>'Falammaa raja\'ooo ilaaa abeehim qaaloo yaaa-abaanaa muni\'a minnal kailu fa-arsil ma\'anaaa akhaanaa naktal Wa-innaa lahoo lahaafizoon','page_number'=>242,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>64,'arabic_text'=>'قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ','transliteration'=>'Qaala hal aamanukum \'alaihi illaa kamaa amintukum \'alaaa akheehi min qabl; fal-laahu khairun haafizanw Wa-Huwa arhamur Raahimeen','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>65,'arabic_text'=>'وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ','transliteration'=>'Wa-lammaa fatahoo mataa-\'ahum wajadoo bidaa\'atahum ruddat ilaihim qaaloo yaaa-abaanaa maa nabghee; haazihee bida-\'atunaa ruddat ilainaa Wa-nameeru ahlanaa Wa-nahfazu akhaanaa Wa-nazdaadu kaila ba\'eer; zaalika kailuien yaseer','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>66,'arabic_text'=>'قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ','transliteration'=>'Qaala lan ursilahoo ma\'akum hattaa tu\'tooni mawsiqam minal laahis lataa-tunnanee biheee illaaa aien yuhaata bikum falammaaa aatawhu mawsiqahum qaalal laahu \'alaa maa naqoolu Wakeel','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>67,'arabic_text'=>'وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ','transliteration'=>'Wa-qaala yaa-baniyya laa tadkhuloo mim baabinw waa-hidinw wadkhuloo min abwaabim mutafarriqah; Wa-maaa ughnee \'ankum minal laahi min shai\'in; inil hukmu illaa lillaahi \'alaihi tawakkaltu Wa-\'alaihi fal-yatawakkalil Mutawakkiloon','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>68,'arabic_text'=>'وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Wa-lammaa dakhaloo min haisu amarahum aboohum maa kaana yughnee \'anhum minal laahi min shai\'in illaa haajatan fee nafsi Ya\'qooba qadaahaa; Wa-innahoo lazoo \'ilmil limaa \'allamnaahu Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>69,'arabic_text'=>'وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-lammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi akhaahu qaala inneee ana akhooka falaa tabta\'is bimaa kaanoo ya\'maloon','page_number'=>243,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>70,'arabic_text'=>'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ','transliteration'=>'Falammaa jahhazahum bijahaazihim ja\'alas siqaayata fee rahli akheehi summa azzana mu\'azzinun ayyatuhal \'eeru innakum lasaariqoon','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>71,'arabic_text'=>'قَالُواْ وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ','transliteration'=>'Qaaloo Wa-aqbaloo \'alaihim maazaa tafqidoon','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>72,'arabic_text'=>'قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرٖ وَأَنَا۠ بِهِۦ زَعِيمٞ','transliteration'=>'Qaaloo nafqidu suwaa\'al maliki Wa-liman jaaa\'a bihee himlu ba\'eerinw Wa-ana bihee za\'eem','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>73,'arabic_text'=>'قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ','transliteration'=>'Qaaloo tallaahi laqad \'alimtum maa ji\'na linufsida fil ardi Wa-maa kunnaa saariqeen','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>74,'arabic_text'=>'قَالُواْ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ','transliteration'=>'Qaaloo famaa jazaaa\'u-hooo in kuntum kaazibeen','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>75,'arabic_text'=>'قَالُواْ جَزَٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ','transliteration'=>'Qaaloo jazaaa\'uhoo manw wujida fee rahlihee fahuwa jazaaa\'uh; kazaalika najziz zaalimeen','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>76,'arabic_text'=>'فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ','transliteration'=>'Fabada-a bi-aw\'iyatihim qabla wi\'aaa\'i akheehi summas takhrajahaa minw wi-\'aaa\'i akheeh; kazaalika kidnaa li-Yoosuf; maa kaana liyaakhuza akhaahu fee deenil maliki illaaa aien yashaaa\'al laah; narfa\'u darajaatim man nashaaa\'; Wa-fawqa kulli zee \'ilmin \'Aleem','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>77,'arabic_text'=>'۞ قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ','transliteration'=>'Qaaloo ien yasriq faqad saraqa akhul lahoo min qabl; fa-asarrahaa Yoosufu fee nafsihee Wa-lam yubdihaa lahum; qaala antum sharrum makaananw wallaahu a\'lamu bimaa tasifoon','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>78,'arabic_text'=>'قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Qaaloo yaaa-ayyuhal \'Azeezu inna lahooo aban shaikhan kabeeran fakhuz ahadanaa makaanahoo innaa naraaka minal muhsineen','page_number'=>244,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>79,'arabic_text'=>'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذٗا لَّظَٰلِمُونَ','transliteration'=>'Qaala ma\'aazal laahi an naakhuza illaa manw wajadnaa mataa\'anaa \'indahoo innaaa izal lazaalimoon','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>80,'arabic_text'=>'فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيّٗاۖ قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم مَّوۡثِقٗا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ','transliteration'=>'Falammas tay\'asoo minhu khalasoo najiyyan qaala kabeeruhum alam ta\'lamoon anna abaakum qad akhaza \'alaikum mawsiqam minal laahi Wa-min qablu maa farrattum fee Yoosufa falan abrahal arda hattaa yaazana leee abeee aw yahkumal laahu lee Wa-huwa khairul haakimeen','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>81,'arabic_text'=>'ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ','transliteration'=>'Irji\'ooo ilaaa abeekum faqooloo yaaa-abaanaaa innab naka saraq; Wa-maa shahidnaaa illaa bimaa \'alimnaa Wa-maa kunnaa lilghaibi haafizeen','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>82,'arabic_text'=>'وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ وَإِنَّا لَصَٰدِقُونَ','transliteration'=>'Was\'alil qaryatal latee kunnaa feehaa wal\'eeral lateee aqbalnaa feehaa Wa-innaa lasaadiqoon','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>83,'arabic_text'=>'قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ','transliteration'=>'Qaala bal sawwalat lakum anfusukum amran fasabrun jameelun \'asal laahu aien yaa-tiyanee bihim jamee\'aa; innahoo Huwal \'Aleemul Hakeem','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>84,'arabic_text'=>'وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ','transliteration'=>'Wa-tawallaa \'anhum Wa-qaala yaaa-asafaa \'alaa Yoosufa wabyaddat \'aynaahu minal huzni fahuwa kazeem','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>85,'arabic_text'=>'قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ','transliteration'=>'Qaaloo tallaahi tafta\'u tazkuru Yoosufa hattaa takoona haradan aw takoona minal haalikeen','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>86,'arabic_text'=>'قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Qaala innamaaa ashkoo bassee Wa-huzneee ilal laahi Wa-a\'lamu minal laahi maa laa ta\'lamoon','page_number'=>245,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>87,'arabic_text'=>'يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ','transliteration'=>'Yaa-baniyyaz haboo fatahassasoo mien Yoosufa Wa-akheehi Wa-laa tai\'asoo mir rawhil laahi innahoo laa yai\'asu mir rawhil laahi illal qawmul kaafiroon','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>88,'arabic_text'=>'فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ','transliteration'=>'Falammaa dakhaloo \'alaihi qaaloo yaaa-ayyuhal \'Azeezu massanaa Wa-ahlanad durru Wa-ji\'naa bibidaa \'timmuzjaatin fa-awfi lanal kaila Wa-tasaddaq \'alainaa innal laaha yajzil mutasaddiqeen','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>89,'arabic_text'=>'قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ','transliteration'=>'Qaala hal \'alimtum maa fa\'altum bi-Yoosufa Wa-akheehi iz antum jaahiloon','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>90,'arabic_text'=>'قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Qaaloo \'a-innaka la-anta Yoosufu qaala ana Yoosufu Wa-haazaaa akhee qad mannal laahu \'alainaa innahoo mai yattaqi Wa-yasbir fa-innal laaha laa yudee\'u ajral muhsineen','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>91,'arabic_text'=>'قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ','transliteration'=>'Qaaloo tallaahi laqad aasarakal laahu \'alainaa Wa-in kunnaa lakhaati\'een','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>92,'arabic_text'=>'قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ','transliteration'=>'Qaala laa tasreeba \'alaikumul yawma yaghfirul laahu lakum Wa-Huwa arhamur raahimeen','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>93,'arabic_text'=>'ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ','transliteration'=>'Izhaboo biqameesee haazaa fa-alqoohu \'alaa wajhi abee yaati baseeranw waatoonee bi-ahlikum ajma\'een','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>94,'arabic_text'=>'وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ','transliteration'=>'Wa-lammaa fasalatil \'eeru qaala aboohum innee la-ajidu reeha Yoosufa law-laaa an tufannidoon','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>95,'arabic_text'=>'قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ','transliteration'=>'Qaaloo tallaahi innaka lafee dalaalikal qadeem','page_number'=>246,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>96,'arabic_text'=>'فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ','transliteration'=>'Falammaaa an jaaa\' albasheeru alqaahu \'alaa wajhihee fartadda baseeran qaala alam aqul lakum inneee a\'lamu minal laahi maa laa ta\'lamoon','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>97,'arabic_text'=>'قَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ','transliteration'=>'Qaaloo yaaa-abaanas taghfir lanaa zunoo-banaaa innaa kunnaa khaati\'een','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>98,'arabic_text'=>'قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Qaala sawfa astaghfiru lakum Rabbeee innahoo Huwal Ghafoorur Raheem','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>99,'arabic_text'=>'فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ','transliteration'=>'Falammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi abayaihi Wa-qaalad khuloo Misra in shaaa\' al-laahu aamineen','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>100,'arabic_text'=>'وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ','transliteration'=>'Wa-raf\'a abawaihi \'alal \'arshi Wa-kharroo lahoo sujjadaa; Wa-qaala yaaa-abati haaza taaweelu ru\'yaaya min qablu qad ja\'alahaa Rabbee haqqaa; Wa-qad ahsana beee iz akhrajanee minas sijni Wa-jaaa\'a bikum minal badwi mim ba\'di an nazaghash Shaitaanu bainee Wa-baina ikhwatee; inna Rabbee lateeful limaa yashaaa\'; innahoo Huwal \'Aleemul Hakeem','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>101,'arabic_text'=>'۞ رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ','transliteration'=>'Rabbi qad aataitanee minal mulki Wa-\'allamtanee min taaweelil ahaadees; faati-ras samaawaati wal-ardi Anta waliyyee fid dunyaa wal-Aakhirati tawaffanee muslimanw Wa-alhiqnee bissaaliheen','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>102,'arabic_text'=>'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ وَهُمۡ يَمۡكُرُونَ','transliteration'=>'Zaalika min ambaaa\'il ghaibi nooheehi ilaika Wa-maa kunta ladaihim iz ajma\'ooo amrahum Wa-hum yamkuroon','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>103,'arabic_text'=>'وَمَآ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِينَ','transliteration'=>'Wa-maa aksarun naasi Wa-law harasta bimu\'mineen','page_number'=>247,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>104,'arabic_text'=>'وَمَا تَسۡـَٔلُهُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ','transliteration'=>'Wa-maa tas\'aluhum \'alaihi min ajr; in huwa illaa zikrul lil\'aalameen','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>105,'arabic_text'=>'وَكَأَيِّن مِّنۡ ءَايَةٖ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ','transliteration'=>'Wa-ka-ayyim min Aayatin fis samaawaati wal-ardi yamurroona \'alaihaa Wa-hum \'anhaa mu\'ridoon','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>106,'arabic_text'=>'وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ','transliteration'=>'Wa-maa yu\'minu aksaru-hum billaahi illaa Wa-hum mushrikoon','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>107,'arabic_text'=>'أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةٞ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Afa-aminooo an taatiya-hum ghaashiyatum min \'azaabil laahi aw taatiyahumus Saa\'atu baghtatanw Wa-hum laa yash\'uroon','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>108,'arabic_text'=>'قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Qul haazihee sabeeleee ad\'ooo ilal laah; \'alaa baseera-tin ana Wa-manit taba\'anee Wa-Subhaanal laahi Wa-maaa ana minal mushrikeen','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>109,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Wa-maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim min ahlil quraa; afalam yaseeroo fil ardi fa-yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; Wa-la-Daarul Aakhirati Khairul lillazeenat taqaw; afalaa ta\'qiloon','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>110,'arabic_text'=>'حَتَّىٰٓ إِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ جَآءَهُمۡ نَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ','transliteration'=>'Hattaaa izas tai\'asar Rusulu Wa-zannooo annahum qad kuziboo jaaa\'ahum nas-runaa fanujjiya man nashaaa\'u Wa-laa yuraddu baasunna \'anil qawmil mujrimeen','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>12,'ayah_number'=>111,'arabic_text'=>'لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Laqad kaana fee qasasihim \'ibratul li-ulil albaab; maa kaana hadeesany yuftaraa Wa-laakin tasdeeqal lazee baina yadihi Wa-tafseela kulli shai\'inw Wa-hudanw Wa-rahmatal liqawmien yu\'minoon','page_number'=>248,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            /* Surah 13: The Thunder (Ar-Ra'd) */
            ['surah_id'=>13,'ayah_number'=>1,'arabic_text'=>'الٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ','transliteration'=>'Alif-Laaam-Meeem-Raa; tilka Aayaatul Kitaab; wallazee unzila ilaika mir Rabbikal haqqu Wa-laakinna aksaran naasi laa yu\'minoon','page_number'=>249,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>2,'arabic_text'=>'ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ','transliteration'=>'Allaahul lazee raf\'as samaawaati bighairi \'amadin tarawnahaa summas tawaa \'alal \'Arshi Wa-sakhkharash shamsa walqamara kulluny yajree li-ajalim musammaa; yudabbirul amra yufassilil Aayaati la\'allakum biliqaaa\'i Rabbikum tooqinoon','page_number'=>249,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>3,'arabic_text'=>'وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Wa-Huwal lazee maddal arda Wa-ja\'ala feehaa rawaasiya Wa-anhaaraa; Wa-min kullis samaraati ja\'ala feehaa zawjainis naini Yughshil lailan nahaar; inna fee zaalika la-aayaatil liqawmien yatafakkaroon','page_number'=>249,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>4,'arabic_text'=>'وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wa-fil ardi qita\'um muta-jaawiraatunw Wa-jannaatum min a\'naabinw Wa-zar\'unw Wa-nakheelun sinwaanunw Wa-ghairu sinwaanien yusqaa bimaaa\'inw waahid; Wa-nufaddilu ba\'dahaa \'alaa ba\'din fil ukul; inna fee zaalika la-aayaatil liqawmien ya\'qiloon','page_number'=>249,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>5,'arabic_text'=>'۞ وَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ جَدِيدٍۗ أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَٰٓئِكَ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَاقِهِمۡۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Wa-in ta\'jab fa\'ajabun qawluhum \'a-izaa kunna turaaban \'a-inna lafee khalqin jadeed; ulaaa-\'ikal lazeena kafaroo bi-Rabbihim Wa-ulaaa\'ikal aghlaalu feee a\'naaqihim Wa-ulaaa\'ika As-haabun Naari hum feehaa khaalidoon','page_number'=>249,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>6,'arabic_text'=>'وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Wa-yasta\'jiloonaka bis-saiyi\'ati qablal hasanati Wa-qad khalat min qablihimul masulaat; Wa-inna Rabbaka lazoo maghfiratil linnaasi \'alaa zulmihim Wa-inna Rabbaka lashadeedul \'iqaab','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>7,'arabic_text'=>'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرٞۖ وَلِكُلِّ قَوۡمٍ هَادٍ','transliteration'=>'Wa-yaqoolul lazeena kafaroo law-laaa unzila \'alaihi Aayatum mir Rabbih; innamaaa anta munzirunw Wa-likulli qawmin haad','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>8,'arabic_text'=>'ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَيۡءٍ عِندَهُۥ بِمِقۡدَارٍ','transliteration'=>'Allaahu ya\'lamu maa tahmilu kullu unsaa Wa-maa tagheedul arhaamu Wa-maa tazdaad, Wa-kullu shai\'in \'indahoo bimiqdaar','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>9,'arabic_text'=>'عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ','transliteration'=>'Aalimul Ghaibi wash-shahaadatil Kaabeerul Muta\'aal','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>10,'arabic_text'=>'سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ بِٱلنَّهَارِ','transliteration'=>'Sawaaa\'um minkum man asarral qawla Wa-man jahara bihee Wa-man huwa mustakhfim billaili Wa-saaribum binnahaar','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>11,'arabic_text'=>'لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ','transliteration'=>'Lahoo mu\'aqqibaatum mim baini yadaihi Wa-min khalfihee yahfazoonahoo min amril laah; innal laaha laa yughaiyyiru maa biqawmin hattaa yughaiyiroo maa bianfusihim; Wa-izaaa araadal laahu biqawmin sooo\'an falaa maradda lah; Wa-maa lahum min doonihee minw waal','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>12,'arabic_text'=>'هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ','transliteration'=>'Huwal lazee yureekumul barqa khawfanw Wa-tama\'anw Wa-yunshi\'us sahaabas siqaal','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>13,'arabic_text'=>'وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ','transliteration'=>'Wa-yusabbihur ra\'du bihamdihee walmalaaa\'ikatu min kheefatihee Wa-yursilus sawaa\'iqa fa-yuseebu bihaa mai yashaaa\'u Wa-hum yujaadiloona fil laahi Wa-Huwa shadeedul mihaal','page_number'=>250,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>14,'arabic_text'=>'لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ','transliteration'=>'Lahoo da\'watul haqq; wallazeena yad\'oona min doonihee laa yastajeeboona lahum bishai\'in illaa kabaasiti kaffaihi ilal maaa\'i liyablugha faahu Wa-maa huwa bibaalighih; Wa-maa du\'aaa\'ul kaafireena illaa fee dalaal','page_number'=>251,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>15,'arabic_text'=>'وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ','transliteration'=>'Wa-lillaahi yasjudu man fis samaawaati wal-ardi taw-\'anw Wa-karhanw Wa-zilaaluhum bilghuduwwi wal-aasaal','page_number'=>251,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>true],
            ['surah_id'=>13,'ayah_number'=>16,'arabic_text'=>'قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّٰرُ','transliteration'=>'Qul mar Rabbus samaawaati wal-ard; qulil laah; qul afattakhaztum min dooniheee awliyaaa\'a laa yamlikoona li-anfusihim naf\'anw Wa-laa darraa; qul hal yastawil a\'maa wal-baseeru am hal tastawiz zulumaatu wannoor; am ja\'aloo lillaahi shurakaaa\'a khalaqoo kakhalqihee fatashaa-bahal khalqu \'alaihim; qulil laahu Khaaliqu kulli shai\'inw Wa-Huwal Waahidul Qahhar','page_number'=>251,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>17,'arabic_text'=>'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ','transliteration'=>'Anzala minas samaaa\'i maaa\'an fasaalat awdiyatum biqadarihaa fahtamalas sailu zabadar raabiyaa; Wa-mimmmaa yooqidoona \'alaihi fin naarib tighaaa\'a bilyatin aw mataa\'in zabadum misluh; kazaalika yadribul laahul haqqa wal-baatil; fa-ammaz zabadu fa-yazhabu jufaaa\'aa; Wa-ammaa maa yanfa\'un naasa fa-yamkusu fil ard; kazaalika yadribul laahul amsaal','page_number'=>251,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>18,'arabic_text'=>'لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ أُوْلَٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ','transliteration'=>'Lillazeenas tajaaboo lirabbihimul husnaa; wallazeena lam yastajeeboo lahoo law anna lahum maa fil ardi jamee\'anw Wa-mislahoo ma\'ahoo laftadaw bih; ulaaa\'ika lahum sooo\'ul hisaab; Wa-ma\'waahum Jahannamu Wa-bi\'sal mihaad','page_number'=>251,'juz_number'=>13,'hizb_number'=>25,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>19,'arabic_text'=>'۞ أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Afamai ya\'lamu annamaaa unzila ilaika mir Rabbikal haqqu kaman huwa a\'maa; innamaa yatazakkaru ulul albaab','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>20,'arabic_text'=>'ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ','transliteration'=>'Allazeena yoofoona bi\'ahdil laahi Wa-laa yanqu-doonal meesaaq','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>21,'arabic_text'=>'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ','transliteration'=>'Wallazeena yasiloona maaa amaral laahu bihee an yoosala Wa-yakhshawna Rabbahum Wa-yakhaafoona sooo\'al hisaab','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>22,'arabic_text'=>'وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ','transliteration'=>'Wallazeena sabarub tighaaa\'a Wajhi Rabbihim Wa-aqaamus Salaata Wa-anfaqoo mimmaa razaqnaahum sirranw Wa-\'alaaniyatanw Wa-yadra\'oona bilhasanatis saiyi\'ata ulaaa\'ika lahum \'uqbad daar','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>23,'arabic_text'=>'جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۖ وَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ','transliteration'=>'Jannaatu \'adnien yadkhu-loonahaa Wa-man salaha min aabaaa\'ihim Wa-azwaajihim Wa-zurriyyaatihim walmalaaa\'i-katu yadkhuloona \'alaihim min kulli baab','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>24,'arabic_text'=>'سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ','transliteration'=>'Salaamun \'alaikum bimaa sabartum; fani\'ma \'uqbad daar','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>25,'arabic_text'=>'وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَٰٓئِكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ','transliteration'=>'Wallazeena yanqudoona \'Ahdal laahi mim ba\'di meesaaqihee Wa-yaqta\'oona maaa amaral laahu biheee ai yoosala Wa-yufsidoona fil ardi ulaaa\'ika lahumul la\'natu Wa-lahum sooo\'ud daar','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>26,'arabic_text'=>'ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ','transliteration'=>'Allaahu yabsutur rizqa limai yashaaa\'u Wa-yaqdir; Wa-farihoo bilhayaatid dunyaa Wa-mal hayaatud dunya fil Aakhirati illaa mataa\'','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>27,'arabic_text'=>'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ','transliteration'=>'Wa-yaqoolul lazeena kafaroo law-laaa unzila \'alaihi Aayatum mir Rabbih; qul innal laaha yudillu maien yashaa\'u Wa-yahdeee ilaihi man anaab','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>28,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ','transliteration'=>'Allazeena aamanoo Wa-tatma\'innu quloobuhum bizikril laah; alaa bizikril laahi tatma\'innul quloob','page_number'=>252,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>29,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابٖ','transliteration'=>'Allazeena aamanoo Wa-a\'amilus saalihaati toobaa lahum Wa-husnu ma-aab','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>30,'arabic_text'=>'كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةٖ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمٞ لِّتَتۡلُوَاْ عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ قُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ','transliteration'=>'Kazaalika arsalnaaka feee ummatin qad khalat min qablihaaa umamul litatluwa \'alaihimul lazeee awhainaaa ilaika Wa-hum yakfuroona bir-Rahmaaan; qul Huwa Rabbee laaa ilaaha illaa Huwa \'alaihi tawakkaltu Wa-ilaihi mataab','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>31,'arabic_text'=>'وَلَوۡ أَنَّ قُرۡءَانٗا سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبٗا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ','transliteration'=>'Wa-law anna Quraanan suyyirat bihil jibaalu aw qutti\'at bihil ardu aw kullima bihil mawtaa; bal lillaahil amru jamee\'aa; afalam yai\'asil lazeena aamanooo al law yashaaa \'ullaahu lahadan naasa jamee\'aa; Wa-laa yazaalul lazeena kafaroo tuseebuhum bimaa sana\'oo qaari\'atun aw tahullu qareebam min daarihim hatta ya\'tiya wa\'dul laah; innal laaha laa yukhliful mee\'aad','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>32,'arabic_text'=>'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ','transliteration'=>'Wa-laqadis tuhzi\'a bi-Rusulim min qablika fa-amlaitu lillazeena kafaroo summa akhaztuhum fakaifa kaana \'iqaab','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>33,'arabic_text'=>'أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُواْ لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعۡلَمُ فِي ٱلۡأَرۡضِ أَم بِظَٰهِرٖ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُواْ مَكۡرُهُمۡ وَصُدُّواْ عَنِ ٱلسَّبِيلِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ','transliteration'=>'Afaman Huwa qaaa\'imun \'alaa kulli nafsim bimaa kasabat; Wa-ja\'aloo illlaahi shurakaaa\'a qul samoohum; am tunabbi\'oona-hoo bimaa laa ya\'lamu fil ardi; am bizaahirim minal qawl; bal zuyyina lillazeena kafaroo makruhum Wa-suddoo \'anis sabeel; Wa-mai yudlilil laaahu famaa lahoo min haad;','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>34,'arabic_text'=>'لَّهُمۡ عَذَابٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ','transliteration'=>'Lahum \'azaabun fil hayaatid dunyaa Wa-la\'azaabul Aakhirati ashaaq, Wa-maa lahum minal laahi min waaq','page_number'=>253,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>35,'arabic_text'=>'۞ مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ أُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى ٱلۡكَٰفِرِينَ ٱلنَّارُ','transliteration'=>'Masalul Jannatil latee wu\'idal muttaqoona tajree min tahtihal anhaaru ukuluhaa daaa\'imunw Wa-zilluhaa; tilka uqbal lazeenat taqaw Wa-\'uqbal kafireenan Naar','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>36,'arabic_text'=>'وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ','transliteration'=>'Wallazeena aatainaa-humul Kitaaba yafrahoona bimaa unzila ilaika Wa-minal Ahzaabi mai yunkiru ba\'dah; qul innamaa umirtu an a\'budal laaha Wa-laaa ushrika bih; ilaihi ad\'oo Wa-ilaihi maab','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>37,'arabic_text'=>'وَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيّٗاۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا وَاقٖ','transliteration'=>'Wa-kazaalika anzalnaahu hukman \'Arabiyyaa; Wa-la\'init taba\'ta ahwaaa-\'ahum ba\'da-maa jaaa\'aka minal \'ilmi maa laka minal laahi minw waliyinw Wa-laa waaq','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>38,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَٰجٗا وَذُرِّيَّةٗۚ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلٖ كِتَابٞ','transliteration'=>'Wa-laqad arsalnaa Rusulam min qablika Wa-ja\'alnaa lahum azwaajanw Wa-zurriyyah; Wa-maa kaana lirasoolin aien ya\'tiya bi-aayatin illaa bi-iznil laah; likulli ajalin kitaab','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>39,'arabic_text'=>'يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ','transliteration'=>'Yamhul laahu maa yashaaa\'u Wa-yusbitu Wa-\'indahooo ummul Kitaab','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>40,'arabic_text'=>'وَإِن مَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ','transliteration'=>'Wa-im maa nurriyannaka ba\'dal lazee na\'iduhum aw nata-waffayannaka fa-innamaa \'alaikal balaaghu Wa-\'alainal hisaab','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>41,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Awalam yaraw annaa na\'til arda nanqusuhaa min atraafihaa; wallaahu yahkumu laa mu\'aqqiba lihukmih; Wa-Huwa saree\'ul hisaab','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>42,'arabic_text'=>'وَقَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعٗاۖ يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسٖۗ وَسَيَعۡلَمُ ٱلۡكُفَّٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ','transliteration'=>'Wa-qad makaral lazeena min qablihim falillaahil makru jamee\'aa; ya\'lamu maa taksibu kullu nafs; Wa-sa-ya\'lamul kuffaaru liman \'uqbad daar','page_number'=>254,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>13,'ayah_number'=>43,'arabic_text'=>'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلٗاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ','transliteration'=>'Wa-yaqoolul lazeena kafaroo lasta mursalaa; qul kafaa billaahi shaheedam bainee Wa-bainakum Wa-man \'indahoo \'ilmul Kitaab','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            /* Surah 14: Abraham (Ibrahim) */
            ['surah_id'=>14,'ayah_number'=>1,'arabic_text'=>'الٓرۚ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ','transliteration'=>'Alif-Laaam-Raa; Kitaabun anzalnaahu ilaika litukhrijan naasa minaz zulumaati ilan noori bi-izni Rabbihim ilaa siraatil \'Azeezil Hameed','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>2,'arabic_text'=>'ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَوَيۡلٞ لِّلۡكَٰفِرِينَ مِنۡ عَذَابٖ شَدِيدٍ','transliteration'=>'Allaahil lazee lahoo maa fis samaawaati Wa-maa fill ard; Wa-wailul lilkaafireena min \'azaabin shadeed','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>3,'arabic_text'=>'ٱلَّذِينَ يَسۡتَحِبُّونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدٖ','transliteration'=>'Allazeena yastahibboo-nal hayaatad dunyaa \'alal aakhirati Wa-yasuddoona \'ansabeelil laahi Wa-yabghoonahaa \'iwajaa; ulaaa \'ika fee dalaalin ba\'eed','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>4,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Wa-maaa arsalnaa mir Rasoolin illaa bilisaani qawmihee liyubaiyina lahum fa-yudillul laahu mai yashaaa\'u Wa-yahdee mai yashaaa\'; Wa-Huwal \'Azeezul Hakeem','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>5,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ','transliteration'=>'Wa-laqad arsalnaa Moosaa bi-Aayaatinaa an akhrij qawmaka minaz zulumaati ilan noori Wa-zak-kirhum bi-ayyaamil laah; inna fee zaalika la-aayaatil likulli sabbaarin shakoor','page_number'=>255,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>6,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ','transliteration'=>'Wa-iz qaala Moosaa liqawmihiz kuroo ni\'matal laahi \'alaikum iz anjaakum min Aali Fir\'awna yasoomoo-nakum sooo\'al \'azaabi Wa-yuzabbihoona abnaaa\'akum Wa-yastahyoona nisaaa\'akum; Wa-fee zaalikum balaaa\'un mir Rabbikum \'azeem','page_number'=>256,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>7,'arabic_text'=>'وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ','transliteration'=>'Wa-iz ta-azzana Rabbukum la\'in shakartum la-azeedannakum Wa-la\'in kafartum inna \'azaabee lashadeed','page_number'=>256,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>8,'arabic_text'=>'وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ','transliteration'=>'Wa-qaala Moosaaa in takfurooo antum Wa-man fil ardi jamee\'an fa-innal laaha la-Ghaniyyun Hameed','page_number'=>256,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>9,'arabic_text'=>'أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ','transliteration'=>'Alam ya\'tikum naba\'ul lazeena min qablikum qawmi Noohinw Wa-\'Aadinw Wa-Samood, wallazeena mim ba\'dihim; laa ya\'lamuhum illallaah; jaaa\'at hum Rusuluhum bilbaiyinaati faraddooo aydiyahum feee afwaahihim Wa-qaalooo innaa kafarnaa bimaaa ursiltum bihee Wa-innaa lafee shakkim mimmaa tad\'oonanaaa ilaihi mureeb','page_number'=>256,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>10,'arabic_text'=>'۞ قَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَدۡعُوكُمۡ لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنٖ مُّبِينٖ','transliteration'=>'Qaalat Rusuluhum afil laahi shakkun faatiris samaawaati wal-ardi yad\'ookum liyaghfira lakum min zunoobikum Wa-yu\'akhirakum ilaaa ajalin musammaa; qaaloo in antum illaa basharum mislunaa tureedoona an tasuddoonaa \'ammaa kaana ya\'budu aabaaa\'unaa fa\'toonaa bi-sultaanin mubeen','page_number'=>256,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>11,'arabic_text'=>'قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرٞ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَآ أَن نَّأۡتِيَكُم بِسُلۡطَٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Qaalat lahum Rusuluhum in nahnu illaa basharum mislukum Wa-laakinnal laaha yamunnu \'alaa maien yashaaa\'u min \'ibaadihee Wa-maa kaana lanaaa an na\'tiyakum bisul-taanin illaa bi-iznil laah; Wa-\'alal laahi falyatawakkalil mu\'minoon','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>12,'arabic_text'=>'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ','transliteration'=>'Wa-maa lanaa allaa natawakkala \'alal laahi Wa-qad hadaanaa subulanaa; Wa-lanasbiranna \'alaa maaa aazaitumoonaa; Wa-\'alal laahi falyatawakkalil mutawakkiloon','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>13,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-qaalal lazeena kafaroo li-Rusulihim lanukhrijanna-kum min aardinaaa aw la-ta\'oodunna fee millatinaa fa-awhaaa ilaihim Rabbuhum lanuhlikannaz zaalimeen','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>14,'arabic_text'=>'وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ','transliteration'=>'Wa-lanuskinan-nakumul arda min ba\'dihim; zaalika liman khaafa maqaamee Wa-khaafa wa\'eed','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>15,'arabic_text'=>'وَٱسۡتَفۡتَحُواْ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٖ','transliteration'=>'Wastaftahoo Wa-khaaba kullu jabbaarin \'aneed','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>16,'arabic_text'=>'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسۡقَىٰ مِن مَّآءٖ صَدِيدٖ','transliteration'=>'Minw waraaa\'ihee jahannamu Wa-yusqaa min maaa\'in sadeed','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>17,'arabic_text'=>'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ وَمَا هُوَ بِمَيِّتٖۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٞ','transliteration'=>'Yatajarra\'uhoo Wa-laa yakaadu yuseeghuhoo Wa-ya\'teehil mawtu min kulli makaaninw Wa-maa huwa bimaiyitinw Wa-minw waraaa\'ihee \'azaabun ghaleez','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>18,'arabic_text'=>'مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ','transliteration'=>'Masalul lazeena kafaroo bi-Rabbihim; a\'maaluhum karamaadinish taddat bihir reehu fee yawmin \'aasifin; laa yaqdiroona mimmaa kasaboo \'alaa shai\'; zaalika huwad dalaalul ba\'eed','page_number'=>257,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>19,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ','transliteration'=>'Alam tara annal laaha khalaqas samaawaati wal-arda bilhaqq; iny yasha yuzhibkum Wa-ya\'ti bikhalqin jadeed','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>20,'arabic_text'=>'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ','transliteration'=>'Wa-maa zaalika \'alal laahi bi-\'azeez','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>21,'arabic_text'=>'وَبَرَزُواْ لِلَّهِ جَمِيعٗا فَقَالَ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَيۡءٖۚ قَالُواْ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَيۡنَٰكُمۡۖ سَوَآءٌ عَلَيۡنَآ أَجَزِعۡنَآ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِيصٖ','transliteration'=>'Wa-barazoo lillaahi jamee\'an faqaalad du\'afaaa\'u lil-lazeenas takbarooo innaa kunnaa lakum taba\'an fahal antum mughnoona \'annaa min \'azaabil laahi min shai\'; qaaloo law hadaanal laahu la-hadaynaakum sawaaa\'un \'alainaaa ajazi\'naa am sabarnaa maa lanaa min mahees','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>22,'arabic_text'=>'وَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ بِمَآ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wa-qaalash Shaitaanu lammaa qudiyal amru innal laaha wa\'adakum wa\'dal haqqi Wa-wa\'attukum fa-akhlaftukum Wa-maa kaana liya \'alaikum min sultaanin illaaa an da\'awtukum fastajabtum lee falaa taloomoonee Wa-loomooo anfusakum maaa ana bimusrikhikum Wa-maaa antum bimusrikhiyya innee kafartu bimaaa ashraktumooni min qabl; innaz zaalimeena lahum azaabun aleem','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>23,'arabic_text'=>'وَأُدۡخِلَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِيَّتُهُمۡ فِيهَا سَلَٰمٌ','transliteration'=>'Wa-udkhilal lazeena aamanoo Wa-\'amilus saalihaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa bi-izni Rabbihim tahiyyatuhum feeha salaam','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>24,'arabic_text'=>'أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ','transliteration'=>'Alam tara kaifa darabal laahu masalan kalimatan taiyibatan kashajaratin taiyibatin asluhaa saabitunw Wa-far\'uhaa fis samaaa\'','page_number'=>258,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>25,'arabic_text'=>'تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Tu\'teee ukulahaa kulla heenim bi-izni Rabbihaa; Wa-yadribul laahul amsaala linnaasi la\'allahum yatazak-karoon','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>26,'arabic_text'=>'وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ','transliteration'=>'Wa-masalu kalimatin khabeesatin kashajaratin khabee-satinij tussat min fawqil ardi maa lahaa min qaraar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>27,'arabic_text'=>'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ','transliteration'=>'Yusabbitul laahul lazeena aamanoo bilqawlis saabiti fil hayaatid dunyaa Wa-fil Aakhirati Wa-yudillul laahuz zaalimeen; Wa-yaf\'alul laahu maa yashaaa\'','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>28,'arabic_text'=>'۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ','transliteration'=>'Alam tara ilal lazeena baddaloo ni\'matal laahi kufranw Wa-ahalloo qawmahum daaral bawaar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>29,'arabic_text'=>'جَهَنَّمَ يَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ','transliteration'=>'Jahannama yaslawnahaa Wa-bi\'sal qaraar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>30,'arabic_text'=>'وَجَعَلُواْ لِلَّهِ أَندَادٗا لِّيُضِلُّواْ عَن سَبِيلِهِۦۗ قُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ','transliteration'=>'Wa-ja\'aloo lillaahi andaadal liyudilloo \'an sabeelih; qul tamatta\'oo fa-innaa maseerakum ilan Naar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>31,'arabic_text'=>'قُل لِّعِبَادِيَ ٱلَّذِينَ ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خِلَٰلٌ','transliteration'=>'Qul li\'ibaadiyal lazeena aamanoo yuqeemus Salaata Wa-yunfiqoo mimmaa razaqnaahum sirranw Wa-\'alaaniyatam min qabli any yaatiya Yawmul laa bai\'un feehi Wa-laa khilaal','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>32,'arabic_text'=>'ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ','transliteration'=>'Allaahul lazee khalaqas samaawaati wal-arda Wa-anzala minas samaaa\'i maaa\'an faakhraja bihee minas samaraati rizqal lakum Wa-sakhkhara lakumul fulka litajriya fil bahri bi-amrihee Wa-sakhkhara lakumul anhaar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>33,'arabic_text'=>'وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ','transliteration'=>'Wa-sakhkhara lakumush shamsa walqamara daaa\'ibaini Wa-sakhkhara lakumul laila wannahaar','page_number'=>259,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>34,'arabic_text'=>'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومٞ كَفَّارٞ','transliteration'=>'Wa-aataakum min kulli maa sa-altumooh; Wa-in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal insaana lazaloo-mun kaffaar','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>35,'arabic_text'=>'وَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ','transliteration'=>'Wa-iz qaala Ibraaheemu Rabbij \'al haazal balada aaminanw wajnubnee Wa-baniyya an na\'budal asnaam','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>36,'arabic_text'=>'رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Rabbi innahunna adlalna kaseeram minan naasi faman tabi\'anee fa-innahoo minnee Wa-man \'asaanee fa-innaka Ghafoorur Raheem','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>37,'arabic_text'=>'رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ','transliteration'=>'Rabbanaaa inneee askantu min zurriyyatee biwaadin ghairi zee zar\'in \'inda Baitikal Muharrami Rabbanaa liyuqeemus Salaata faj\'al af\'idatam minan naasi tahweee ilaihim warzuqhum minas samaraati la\'allahum yashkuroon','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>38,'arabic_text'=>'رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَيۡءٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ','transliteration'=>'Rabbanaaa innaka ta\'lamu maa nukhfee Wa-maa nu\'lin; Wa-maa yakhfaa \'alal laahi min shai\'in fil ardi Wa-laa fis samaaa\'','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>39,'arabic_text'=>'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ','transliteration'=>'Alhamdu lillaahil lazee wahaba lee \'alal kibari Ismaa\'eela Wa-Ishaaq; inna Rabbee lasamee\'ud du\'aaa','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>40,'arabic_text'=>'رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ','transliteration'=>'Rabbij \'alnee muqeemas Salaati Wa-min zurriyyatee Rabbanaa Wa-taqabbal du\'aaa\'','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>41,'arabic_text'=>'رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ','transliteration'=>'Rabbanagh fir lee Wa-liwaalidaiya Wa-lilmu\'mineena Yawma yaqoomul hisaab','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>42,'arabic_text'=>'وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ','transliteration'=>'Wa-laa tahsabannal laaha ghaafilan \'ammaa ya\'maluz zaalimoon; innamaa yu\'akh-khiruhum li-Yawmin tashkhasu feehil absaar','page_number'=>260,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>43,'arabic_text'=>'مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ','transliteration'=>'Muhti\'eena muqni\'ee ru\'oosihim laa yartaddu ilaihim tarfuhum Wa-af\'idatuhum hawaaa\'','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>44,'arabic_text'=>'وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالٖ','transliteration'=>'Wa-anzirin naasa Yawma yaateehimul \'azaabu fa-yaqoolul lazeena zalamoo Rabbanaaa akhkhirnaaa ilaaa ajalin qareebin nujib da\'wataka Wa-nattabi-\'ir Rusul; awalam takoonooo aqsamtum min qablu maa lakum min zawaal','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>45,'arabic_text'=>'وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ أَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ','transliteration'=>'Wa-sakantum fee masaakinil lazeena zalamooo anfusahum Wa-tabaiyana lakum kaifa fa\'alnaa bihim Wa-darabnaa lakumul amsaal','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>46,'arabic_text'=>'وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ','transliteration'=>'Wa-qad makaroo makrahum Wa-\'indal laahi makruhum Wa-in kaana makruhum litazoola minhul jibaal','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>47,'arabic_text'=>'فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ ذُو ٱنتِقَامٖ','transliteration'=>'Falaa tahsabannal laaha mukhlifa wa\'dihee Rusulah; innal laaha \'azeezun zun tiqaam','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>48,'arabic_text'=>'يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ','transliteration'=>'Yawma tubaddalul ardu ghairal ardi wassamaawaatu Wa-barazoo lillaahil Waahidil Qahhaar','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>49,'arabic_text'=>'وَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ','transliteration'=>'Wa-taral mujrimeena Yawma\'izim muqarraneena filas faad','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>50,'arabic_text'=>'سَرَابِيلُهُم مِّن قَطِرَانٖ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ','transliteration'=>'Saraabeeluhum min qatiraaninw Wa-taghshaa wujoohahumun Naar','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>51,'arabic_text'=>'لِيَجۡزِيَ ٱللَّهُ كُلَّ نَفۡسٖ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Liyajziyal laahu kulla nafsim maa kasabat; innal laaha saree\'ul hisaab','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            ['surah_id'=>14,'ayah_number'=>52,'arabic_text'=>'هَٰذَا بَلَٰغٞ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Haaza balaaghul linnaasi Wa-liyunzaroo bihee Wa-liya\'lamooo annamaa Huwa Illaahunw Waahidunw Wa-liyaz-zakkara ulul albaab','page_number'=>261,'juz_number'=>13,'hizb_number'=>26,'is_sajdah'=>false],
            /* Surah 15: The Rocky Tract (Al-Hijr) */
            ['surah_id'=>15,'ayah_number'=>1,'arabic_text'=>'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانٖ مُّبِينٖ','transliteration'=>'Alif-Laaam-Raa; tilka Aayaatul Kitaabi Wa-Qur-aa-nim Mubeen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>2,'arabic_text'=>'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ','transliteration'=>'Rubamaa yawaddul lazeena kafaroo law kaanoo muslimeen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>3,'arabic_text'=>'ذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ','transliteration'=>'Zarhum yaakuloo Wa-yatamatta\'oo Wa-yulhihimul amalu fasawfa ya\'lamoon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>4,'arabic_text'=>'وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ','transliteration'=>'Wa-maaa ahlaknaa min qaryatin illaa Wa-lahaa kitaabum ma\'loom','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>5,'arabic_text'=>'مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ','transliteration'=>'Maa tasbiqu min ummatin ajalahaa Wa-maa yastaakhiroon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>6,'arabic_text'=>'وَقَالُواْ يَٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونٞ','transliteration'=>'Wa-qaaloo yaaa-aiyuhal lazee nuzzila \'alaihiz Zikru innaka lamajnoon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>7,'arabic_text'=>'لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Law maa taateenaa bil-malaaa\'ikati in kunta minas saadiqeen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>8,'arabic_text'=>'مَا نُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ','transliteration'=>'Maa nunazzilul malaaa\'i-kata illaa bilhaqqi Wa-maa kaanooo izam munzareen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>9,'arabic_text'=>'إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ','transliteration'=>'Innaa Nahnu nazalnaz Zikra Wa-Innaa lahoo lahaa-fizoon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>10,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ','transliteration'=>'Wa-laqad arsalnaa min qablika fee shiya\'il awwaleen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>11,'arabic_text'=>'وَمَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-maa yaateehim mir Rasoolin illaa kaanoo bihee yastahzi\'oon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>12,'arabic_text'=>'كَذَٰلِكَ نَسۡلُكُهُۥ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ','transliteration'=>'kazaalika naslukuhoo fee quloobil mujrimeen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>13,'arabic_text'=>'لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ','transliteration'=>'Laa yu\'minoona bihee Wa-qad khalat sunnatul awwaleen','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>14,'arabic_text'=>'وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابٗا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ','transliteration'=>'Wa-law fatahnaa \'alaihim baabam minas samaaa\'i fazaloo feehi ya\'rujoon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>15,'arabic_text'=>'لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمٞ مَّسۡحُورُونَ','transliteration'=>'Laqaaloo innamaa sukkirat absaarunaa bal nahnu qawmum mashooroon','page_number'=>262,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>16,'arabic_text'=>'وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ','transliteration'=>'Wa-laqad ja\'alnaa fis samaaa\'i buroojanw Wa-zaiyannaahaa linnaazireen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>17,'arabic_text'=>'وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنٖ رَّجِيمٍ','transliteration'=>'Wa-hafiznaahaa min kulli Shaitaanir rajeem','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>18,'arabic_text'=>'إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابٞ مُّبِينٞ','transliteration'=>'Illaa manis taraqas sam\'a fa-atba\'ahoo shihaabum mubeen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>19,'arabic_text'=>'وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ','transliteration'=>'Wal-arda madadnaahaa Wa-alqainaa feehaa rawaasiya Wa-ambatnaa feehaa min kulli shai\'im mawzoon','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>20,'arabic_text'=>'وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ','transliteration'=>'Wa-ja\'alnaa lakum feehaa ma\'aayisha Wa-mal lastum lahoo biraaziqeen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>21,'arabic_text'=>'وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ','transliteration'=>'Wa-im min shai\'in illaa \'indanaa khazaaa-\'inuhoo Wa-maa nunazziluhooo illaa biqadarim ma\'loom','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>22,'arabic_text'=>'وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ','transliteration'=>'Wa-arsalnar riyaaha la-waaqiha fa-anzalnaa minas samaaa\'i maaa\'an fa-asqai-naakumoohu Wa-maaa antum lahoo bikhaazineen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>23,'arabic_text'=>'وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ','transliteration'=>'Wa-innnaa la-nahnu nuhyee Wa-numeetu Wa-nahnul waarisoon','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>24,'arabic_text'=>'وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ','transliteration'=>'Wa-la-qad \'alimnal mustaqdimeena minkum Wa-laqad \'alimnal mustaakhireen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>25,'arabic_text'=>'وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ','transliteration'=>'Wa-inna Rabbaka Huwa yahshuruhum; innahoo Hakeemun \'Aleem','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>26,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ','transliteration'=>'Wa-laqad khalaqnal insaana min salsaalim min hama-im masnoon','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>27,'arabic_text'=>'وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ','transliteration'=>'Waljaaanna khalaqnaahu min qablu min naaris samoom','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>28,'arabic_text'=>'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ','transliteration'=>'Wa-iz qaala Rabbuka lilmalaaa\'-ikati innee khaaliqum basharam min salsaalim min hama-im masnoon','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>29,'arabic_text'=>'فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ','transliteration'=>'Fa-izaa sawwaituhoo Wa-nafakhtu feehi mir roohee faqa\'oo lahoo saajideen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>30,'arabic_text'=>'فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ','transliteration'=>'Fasajadal malaaa\'ikatu kulluhum ajma\'oon','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>31,'arabic_text'=>'إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ','transliteration'=>'Illaaa ibleesa abaaa ai yakoona ma\'as saajideen','page_number'=>263,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>32,'arabic_text'=>'قَالَ يَٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ','transliteration'=>'Qaala yaaa-Ibleesu maa laka allaa takoona ma\'as saajideen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>33,'arabic_text'=>'قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ','transliteration'=>'Qaala lam akul li-asjuda libasharin khalaqtahoo min salsaalim min hama-im masnoon','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>34,'arabic_text'=>'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ','transliteration'=>'Qaala fakhruj minhaa fa-innaka rajeem','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>35,'arabic_text'=>'وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ','transliteration'=>'Wa-inna \'alaikal la\'nata ilaa Yawmid Deen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>36,'arabic_text'=>'قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','transliteration'=>'Qaala Rabbi fa-anzirneee ilaa Yawmi yub\'asoon','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>37,'arabic_text'=>'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ','transliteration'=>'Qaala fa-innaka minal munzareen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>38,'arabic_text'=>'إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ','transliteration'=>'Ilaa Yawmil waqtil ma\'loom','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>39,'arabic_text'=>'قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ','transliteration'=>'Qaala Rabbi bimaaa aghwaitanee la-uzayyin-anna lahum fil ardi Wa-la-ughwiyan-nahum ajma\'een','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>40,'arabic_text'=>'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ','transliteration'=>'Illaa \'ibaadaka minhumul mukhlaseen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>41,'arabic_text'=>'قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ','transliteration'=>'Qaala haaza Siraatun \'alaiya Mustaqeem','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>42,'arabic_text'=>'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ','transliteration'=>'Inna \'ibaadee laisa laka \'alaihim sultaanun illaa manit taba\'aka minal ghaaween','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>43,'arabic_text'=>'وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ','transliteration'=>'Wa-inna jahannama lamaw\'iduhum ajma\'een','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>44,'arabic_text'=>'لَهَا سَبۡعَةُ أَبۡوَٰبٖ لِّكُلِّ بَابٖ مِّنۡهُمۡ جُزۡءٞ مَّقۡسُومٌ','transliteration'=>'Lahaa sab\'atu abwaab; likulli baabim minhum juz\'um maqsoom','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>45,'arabic_text'=>'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ','transliteration'=>'Innal muttaqeena fee Jannaatinw Wa-\'uyoon','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>46,'arabic_text'=>'ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ','transliteration'=>'Udkhuloohaa bisalaamin aamineen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>47,'arabic_text'=>'وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ','transliteration'=>'Wa-naza\'naa ma fee sudoorihim min ghillin ikhwaanan \'alaa sururim mutaqaabileen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>48,'arabic_text'=>'لَا يَمَسُّهُمۡ فِيهَا نَصَبٞ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ','transliteration'=>'Laa yamas-suhum feehaa nasabunw Wa-maa hum minhaa bimukhrajeen','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>49,'arabic_text'=>'۞ نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Nabbi\' \'ibaadeee annneee an al-Ghafoorur Raheem','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>50,'arabic_text'=>'وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ','transliteration'=>'Wa-anna \'azaabee huwal \'azaabul aleem','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>51,'arabic_text'=>'وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ','transliteration'=>'Wa-nabbi\'hum \'an daifi Ibraaheem','page_number'=>264,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>52,'arabic_text'=>'إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ','transliteration'=>'Iz dakhaloo \'alaihi faqaaloo salaaman qaala innaa minkum wajiloon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>53,'arabic_text'=>'قَالُواْ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٖ','transliteration'=>'Qaaloo la tawjal innaa nubashshiruka bighulaamin \'aleem','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>54,'arabic_text'=>'قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ','transliteration'=>'Qaala abashshartumoonee \'alaaa am massaniyal kibaru fabima tubashshiroon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>55,'arabic_text'=>'قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ','transliteration'=>'Qaaloo bashsharnaaka bilhaqqi falaa takum minal qaaniteen','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>56,'arabic_text'=>'قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ','transliteration'=>'Qaala Wa-mai yaqnatu mir rahmati Rabbiheee illad daaaloon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>57,'arabic_text'=>'قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ','transliteration'=>'Qaala famaa khatbukum aiyuhal mursaloon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>58,'arabic_text'=>'قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ','transliteration'=>'Qaaloo innaaa ursilnaaa ilaa qawmim mujrimeen','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>59,'arabic_text'=>'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ','transliteration'=>'Illaaa Aala Loot; innaa lamunajjoohum ajma\'een','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>60,'arabic_text'=>'إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ','transliteration'=>'Illam ra-atahoo qaddarnaaa innahaa laminal ghaabireen','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>61,'arabic_text'=>'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ','transliteration'=>'Falamma jaaa\'a Aala Lootinil mursaloon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>62,'arabic_text'=>'قَالَ إِنَّكُمۡ قَوۡمٞ مُّنكَرُونَ','transliteration'=>'Qaala innakum qawmum munkaroon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>63,'arabic_text'=>'قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ يَمۡتَرُونَ','transliteration'=>'Qaaloo bal ji\'naaka bimaa kaanoo feehi yamtaroon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>64,'arabic_text'=>'وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ','transliteration'=>'Wa-atainaaka bilhaqqi Wa-innaa lasaadiqoon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>65,'arabic_text'=>'فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ','transliteration'=>'Fa-asri bi-ahlika biqit\'im minal laili wattabi\' adbaarahum Wa-laa yaltafit minkum ahadunw wamdoo haisu tu\'maroon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>66,'arabic_text'=>'وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقۡطُوعٞ مُّصۡبِحِينَ','transliteration'=>'Wa-qadainaaa ilaihi zaalikal amra anna daabira haaa\'ulaaa\'i maqtoo\'um musbiheen','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>67,'arabic_text'=>'وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ','transliteration'=>'Wa-jaaa\'a ahlul madeenati yastabshiroon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>68,'arabic_text'=>'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ','transliteration'=>'Qaala inna haaa\'ulaaa\'i daifee falaa tafdahoon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>69,'arabic_text'=>'وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ','transliteration'=>'Wattaqul laaha Wa-laa tukhzoon','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>70,'arabic_text'=>'قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaalooo awalam nanhaka \'anil \'aalameen','page_number'=>265,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>71,'arabic_text'=>'قَالَ هَٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ','transliteration'=>'Qaala haaa\'ulaaa\'i banaateee in kuntum faa\'ileen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>72,'arabic_text'=>'لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ يَعۡمَهُونَ','transliteration'=>'La\'amruka innahum lafee sakratihim ya\'mahoon','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>73,'arabic_text'=>'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ','transliteration'=>'Fa-akhazat-humus saihatu mushriqeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>74,'arabic_text'=>'فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ','transliteration'=>'Faja\'alnaa \'aaliyahaa saafilahaa Wa-amtamaa \'alaihim hijaaratam min sijjeel','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>75,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ','transliteration'=>'Inna fee zaalika la-Aayaatil lilmutawassimeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
