            ['surah_id'=>15,'ayah_number'=>77,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ','transliteration'=>'Inna fee zaalika la-Aayatal lilmu\'mineen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>78,'arabic_text'=>'وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ','transliteration'=>'Wa-in kaana Ashaabul Aikati lazaalimeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>79,'arabic_text'=>'فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ','transliteration'=>'Fantaqamnaa minhum Wa-innahumaa labi-imaamim mubeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>80,'arabic_text'=>'وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ','transliteration'=>'Wa-laqad kazzaba ashaabul Hijril mursaleen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>81,'arabic_text'=>'وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ','transliteration'=>'Wa-aatainaahum Aayaatinaa fakaanoo \'anhaa mu\'rideen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>82,'arabic_text'=>'وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ','transliteration'=>'Wa-kaanoo yanhitoona minal jibaali buyootan aamineen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>83,'arabic_text'=>'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ','transliteration'=>'Fa-akhazat-humus saihatu musbiheen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>84,'arabic_text'=>'فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Famaaa aghnaa \'anhum maa kaanoo yaksiboon','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>85,'arabic_text'=>'وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ','transliteration'=>'Wa-maa khalaqnas samaawaati wal-arda Wa-maa bainahumaaa illaa bilhaqq; Wa-innas Saa\'ata la-aatiyatun fasfahis safhal jameel','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>86,'arabic_text'=>'إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ','transliteration'=>'Inna Rabbaka Huwal khallaaqul \'aleem','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>87,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ','transliteration'=>'Wa-laqad aatainaaka sab\'am minal masaanee wal-Qur-aanal \'Azeem','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>88,'arabic_text'=>'لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ','transliteration'=>'Laa tamuddanna \'ainaika ilaa maa matta-\'naa biheee azwaajam minhum Wa-laa tahzan \'alaihim wakhfid janaahaka lilmu-\'mineen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>89,'arabic_text'=>'وَقُلۡ إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ','transliteration'=>'Wa-qul inneee anan nazeerul mubeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>90,'arabic_text'=>'كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ','transliteration'=>'Kamaaa anzalnaa \'alal muqtasimeen','page_number'=>266,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>91,'arabic_text'=>'ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ','transliteration'=>'Allazeena ja\'alul Quraana \'i-deen','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>92,'arabic_text'=>'فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ','transliteration'=>'Fawa-Rabbika lanas\'a-lannahum ajma\'een','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>93,'arabic_text'=>'عَمَّا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ammaa kaanoo ya\'maloon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>94,'arabic_text'=>'فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ','transliteration'=>'Fasda\' bimaa tu\'maru Wa-a\'rid anil mushrikeen','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>95,'arabic_text'=>'إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ','transliteration'=>'Innaa kafainaakal mustahzi\'een','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>96,'arabic_text'=>'ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ','transliteration'=>'Allazeena yaj\'aloona ma\'al laahi ilaahan aakhar; fasawfa ya\'lamoon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>97,'arabic_text'=>'وَلَقَدۡ نَعۡلَمُ أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ','transliteration'=>'Wa-laqad na\'lamu annaka yadeequ sadruka bimaa yaqooloon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>98,'arabic_text'=>'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ','transliteration'=>'Fasbbih bihamdi Rabbika Wa-kum minas saajideen','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>15,'ayah_number'=>99,'arabic_text'=>'وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ','transliteration'=>'Wa\'bud Rabbaka hattaa yaatiyakal yaqeen','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            /* Surah 16: The Bee (An-Nahl) */
            ['surah_id'=>16,'ayah_number'=>1,'arabic_text'=>'أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Ataaa amrul laahi falaa tasta\'jilooh; Subhaanahoo Wa-Ta\'aalaa \'ammaa yushrikoon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>2,'arabic_text'=>'يُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ','transliteration'=>'Yunazzilul malaaa-\'ikata birroohi min amrihee \'alaa mai yashaaa\'u min \'ibaadiheee an anzirooo annahoo laaa ilaaha illaaa ana fattaqoon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>3,'arabic_text'=>'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Khalaqas samaawaati wal-arda bilhaqq; Ta\'aalaa \'ammaa yushrikoon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>4,'arabic_text'=>'خَلَقَ ٱلۡإِنسَٰنَ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ','transliteration'=>'Khalaqal insaana min nutfatin fa-izaa huwa khaseemum mubeen','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>5,'arabic_text'=>'وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ','transliteration'=>'Wal-an-\'amaa khalaqahaa; lakum feehaa dif\'unw Wa-manaafi\'u Wa-minhaa taakuloon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>6,'arabic_text'=>'وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ','transliteration'=>'Wa-lakum feehaa jamaalun heena tureehoona Wa-heena tasrahoon','page_number'=>267,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>7,'arabic_text'=>'وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ','transliteration'=>'Wa-tahmilu asqaalakum ilaa baladil lam takoonoo baaligheehi illaa bishiqqil anfus; inna Rabbakum la-Ra\'oofur Raheem','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>8,'arabic_text'=>'وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ','transliteration'=>'Walkhaila wal-bighaala wal-hameera litarkaboohaa Wa-zeenah; Wa-yakhluqu maa laa ta\'lamoon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>9,'arabic_text'=>'وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ','transliteration'=>'Wa-\'alal laahi qasdus sabeeli Wa-minhaa jaaa\'ir; Wa-law shaaa\'a lahadaakum ajma\'een','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>10,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ شَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ','transliteration'=>'Huwal lazeee anzala minas samaaa\'i maaa\'al lakum minhu sharaabunw Wa-minhu shajarun feehi tuseemoon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>11,'arabic_text'=>'يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Yumbitu lakum bihiz zar\'a wazzaitoona wanna-kheela wal-a\'naaba Wa-min kullis samaraat, inna fee zaalika la-Aayatal liqawminy yatafakkaroon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>12,'arabic_text'=>'وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wa-sakkhkhara lakumul laila wannahaara wash-shamsa walqamara wannujoomu musakhkharaatum bi-amrih; inna fee zaalika la-Aayaatil liqawminy ya\'qiloon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>13,'arabic_text'=>'وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ','transliteration'=>'Wa-maa zara-a lakum fil ardi mukhtalifan alwaanuh; inna fee zaalika la-Aayatal liqawminy yazakkaroon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>14,'arabic_text'=>'وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wa-Huwal lazee sakhkharal bahra litaakuloo minhu lahman tariyyanw Wa-tastakhrijoo minhu hilyatan talbasoonahaa Wa-taral fulka mawaakhira feehi Wa-litabtaghoo min fadlihee Wa-la\'allakum tashkuroon','page_number'=>268,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>15,'arabic_text'=>'وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرٗا وَسُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Wa-alqaa fil ardi rawaasiya an tameeda bikum Wa-anhaaranw Wa-sublulal la-\'allakum tahtadoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>16,'arabic_text'=>'وَعَلَٰمَٰتٖۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ','transliteration'=>'Wa-\'alaamaat; Wa-bin-najmi hum yahtadoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>17,'arabic_text'=>'أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Afamany yakhluqu kamal laa yakhluq; afalaa tazak-karoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>18,'arabic_text'=>'وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal laaha la-Ghafoorur Raheem','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>19,'arabic_text'=>'وَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ','transliteration'=>'Wallaahu ya\'lamu maa tusirroona Wa-maa tu\'linoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>20,'arabic_text'=>'وَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ','transliteration'=>'Wallazeena yad\'oona min doonil laahi laa yakhluqoona shai\'anw Wa-hum yukhlaqoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>21,'arabic_text'=>'أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ','transliteration'=>'Amwaatun ghairu ahyaaa\'inw Wa-maa yash\'uroona aiyaana yub\'asoon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>22,'arabic_text'=>'إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ','transliteration'=>'Illahukum Ilaahunw Waahid; fallazeena laa yu\'minoona bil-Aakhirati quloobuhum munkiratunw Wa-hum mustakbiroon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>23,'arabic_text'=>'لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ','transliteration'=>'Laa jarama annal laaha ya\'lamu maa yusirrona Wa-ma yu\'linoon; innahoo laa yuhibbul mustakbireen','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>24,'arabic_text'=>'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Wa-izaa qeela lahum maazaaa anzala Rabbukum qaaloo asaateerul awwaleen','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>25,'arabic_text'=>'لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ','transliteration'=>'Liyahmilooo awzaarahum kaamilatany Yawmal Qiyaamati Wa-min awzaaril lazeena yudilloonahum bighairi \'ilm; alaa saaa\'a maa yaziroon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>26,'arabic_text'=>'قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ','transliteration'=>'Qad makaral lazeena min qablihim fa-atal laahu bunyaa-nahum minal qawaa\'idi fakharra \'alaihimus saqfu min fawqihim Wa-ataahumul \'azaabu min haisu laa yash\'uroon','page_number'=>269,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>27,'arabic_text'=>'ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تُشَٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ','transliteration'=>'Summa Yawmal Qiyaamati yukhzeehim Wa-yaqoolu aina shurakaaa\'iyal lazeena kuntum tushaaaqqoona feehim; qaalal lazeena ootul \'ilma innal khizyal Yawma wassooo\'a \'alal kaafireen','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>28,'arabic_text'=>'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Allazeena tatawaf-faahu-mul malaaa\'ikatu zaalimeee anfusihim fa-alqawus salama maa kunnaa na\'malu min sooo\'; balaaa innal laaha \'aleemum bimaa kuntum ta\'maloon','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>29,'arabic_text'=>'فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ','transliteration'=>'Fadkhulooo abwaaba jahannama khaalideena feeha falabi\'sa maswal mutakab-bireen','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>30,'arabic_text'=>'۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ','transliteration'=>'Wa-qeela lillazeenat taqaw maazaaa anzala Rabbukum; qaaloo khairaa; lillazeena ahsanoo fee haazihid dunyaa hasanah; Wa-la-Daarul Aakhirati khair; Wa-lani\'ma daarul muttaqeen','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>31,'arabic_text'=>'جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ','transliteration'=>'Jannaatu \'Adniny yadkhuloonahaa tajree min tahtihal anhaaru lahum feehaa maa yashaaa\'oon; kazaalika yajzil laahul muttaqeen','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>32,'arabic_text'=>'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Allazeena tatawaf-faahumul malaaa\'ikatu taiyibeena yaqooloona salaamun \'alai-kumud khulul Jannata bimaa kuntum ta\'maloon','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>33,'arabic_text'=>'هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Hal yanzuroona illaaa an taatiyahumul malaaa\'ikatu aw yaatiya amru Rabbik; kazaalika fa\'alal lazeena min qablihim; Wa-maa zalamahumul laahu Wa-laakin kaanoo anfusahum yazlimoon','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>34,'arabic_text'=>'فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Fa-asaabahum saiyi-aatu maa \'amiloo Wa-haaqa bihim maa kaano bihee yastahzi\'oon','page_number'=>270,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>35,'arabic_text'=>'وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٖ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءٖۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Wa-qaalal lazeena ashrakoo law shaaa\'al laahu ma \'abadnaa min doonihee min shai\'in nahnu Wa-laaa aabaaa\'unaa Wa-laa harramnaa min doonihee min shai\'; kazaalika fa\'alal lazeena min qablihim fahal \'alar Rusuli illal balaaghul mubeen','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>36,'arabic_text'=>'وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ','transliteration'=>'Wa-laqad ba\'asnaa fee kulli ummatir Rasoolan ani\' budul laaha wajtanibut Taaghoota faminhum man hadal laahu Wa-minhum man haqqat \'alaihid dalaalah; faseeroo fil ardi fanzuroo kaifa kaana \'aaqibatul mukazzibeen','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>37,'arabic_text'=>'إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّٰصِرِينَ','transliteration'=>'In tahris \'alaa hudaahum fa-innal laaha laa yahdee mai yudillu Wa-maa lahum min naasireen','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>38,'arabic_text'=>'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Wa-aqsamoo billaahi jahda aimaanihim laa yab\'asul laahu mai yamoot; balaa wa\'dan \'alaihi haqqanw Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>39,'arabic_text'=>'لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ','transliteration'=>'Liyubaiyina lahumul lazee yakhtalifoona feehi Wa-liya\'lamal lazeena kafarooo annahum kaanoo kaazibeen','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>40,'arabic_text'=>'إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Innamaa qawlunaa lishay\'in izaa aradnaahu an naqoola lahoo kun fa-yakoon','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>41,'arabic_text'=>'وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Wallazeena haajaroo fil laahi mim ba\'di maa zulimoo lanubawwi\'-annahum fid dunyaa hasanatanw Wa-la-ajrul Aakhirati akbar; law kaanoo ya\'lamoon','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>42,'arabic_text'=>'ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','transliteration'=>'Allazeena sabaroo Wa-\'alaa Rabbihim yatawak-kaloon','page_number'=>271,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>43,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Wa-maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim; fas\'alooo ahlaz zikri in kuntum laa ta\'lamoon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>44,'arabic_text'=>'بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ','transliteration'=>'Bilbaiyinaati waz-Zubur; Wa-anzalnaaa ilaikaz Zikra litubaiyina linnaasi maa nuzzila ilaihim Wa-la\'allahum yatafakkaroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>45,'arabic_text'=>'أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ','transliteration'=>'Afa-aminal lazeena makarus saiyi-aati ai yakhsifal laahu bihimul arda aw yaaa-tiyahumul \'azaabu min haisu laa yash\'uroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>46,'arabic_text'=>'أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ','transliteration'=>'Aw yaakhuzahum fee taqallubihim famaa hum bi-mu\'jizeen','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>47,'arabic_text'=>'أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ','transliteration'=>'Aw yaakhuzahum \'alaa takhawwuf; fa-inna Rabbakum la-Ra\'oofur Raheem','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>48,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدٗا لِّلَّهِ وَهُمۡ دَٰخِرُونَ','transliteration'=>'Awa-lam yaraw ilaa maa khalaqal laahu min shai\'iny yatafaiya\'u zilaaluhoo \'anil yameeni washshamaaa\'-ili sujjadal lillaahi Wa-hum daakhiroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>49,'arabic_text'=>'وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةٖ وَٱلۡمَلَٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ','transliteration'=>'Wa-lillaahi yasjudu maa fis samaawaati Wa-maa fil ardi min daaabbatinw walma-laaa\'ikatu Wa-hum laa yastakbiroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>50,'arabic_text'=>'يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ','transliteration'=>'yakhaafoona Rabbahum min fawqihim Wa-yaf\'aloona maa yu\'maroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>27,'is_sajdah'=>true],
            ['surah_id'=>16,'ayah_number'=>51,'arabic_text'=>'۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّٰيَ فَٱرۡهَبُونِ','transliteration'=>'Wa-qaalal laahu laa tatta-khizooo ilaahainis naini innamaa Huwa Ilaahunw Waahid; fa-iyyaaya farhaboon','page_number'=>272,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>52,'arabic_text'=>'وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ','transliteration'=>'Wa-lahoo maa fis samaawaati wal-ardi Wa-lahud deenu waasibaa; afaghairal laahi tattaqoon','page_number'=>272,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>53,'arabic_text'=>'وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ','transliteration'=>'Wa-maa bikum min ni\'matin faminal laahi summa izaa massakumud durru fa-ilaihi taj\'aroon','page_number'=>272,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>54,'arabic_text'=>'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ','transliteration'=>'Summaa izaa kashafad durra \'ankum izaa fareequm minkum bi-Rabbihim yushrikoon','page_number'=>272,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>55,'arabic_text'=>'لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ','transliteration'=>'Liyakfuroo bimaa aatainaahum; fatamatta\'oo, faswfa ta\'lamoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>56,'arabic_text'=>'وَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ','transliteration'=>'Wa-yaj\'aloona limaa laa ya\'lamoona naseebam mimmaa razaqnnaahum; tallaahi latus\'alunaa \'ammaa kuntum taftaroon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>57,'arabic_text'=>'وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ','transliteration'=>'Wa-yaj\'aloona lillaahil banaati Subhaanahoo Wa-lahum maa yashtahoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>58,'arabic_text'=>'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ','transliteration'=>'Wa-izaa bushshira ahaduhum bil-unsaa zalla wajhuhoo muswaddanw Wa-huwa kazeem','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>59,'arabic_text'=>'يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ','transliteration'=>'yatawaaraa minal qawmi min sooo\'i maa bushshira bih; a-yumsikuhoo \'alaa hoonin am yadussuhoo fit turaab; alaa saaa\'a maa yahkumoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>60,'arabic_text'=>'لِلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Lillazeena laa yu\'minoona bil-Aakhirati masalus saw\'i Wa-lillaahil masalul a\'laa; Wa-Huwal \'Azeezul Hakeem','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>61,'arabic_text'=>'وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ','transliteration'=>'Wa-law yu\'aakhizul laahun naasa bizulminhim maa taraka \'alaihaa min daaabbatinw Wa-laakiny yu\'akhkhiruhum ilaaa ajalim musamman fa-izaa jaaa\'a ajaluhum laa yastaakhiroona saa\'atanw Wa-laa yastaqdimoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>62,'arabic_text'=>'وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ','transliteration'=>'Wa-yaj\'aloona lillaahi maa yakrahoona Wa-tasifu alsinatuhumul kaziba anna lahumul husnaa laa jarama anna lahumun Naara Wa-annahum mufratoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>63,'arabic_text'=>'تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Tallaahi laqad arsalnaaa ilaaa umamim min qablika fazayyana lahumush Shaitaanu a\'maalahum fahuwa waliyyuhumul yawma Wa-lahum \'azaabun aleem','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>64,'arabic_text'=>'وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Wa-maaa anzalnaa \'alaikal Kitaaba illaa litubaiyina lahumul lazikh talafoo feehi Wa-hudanw Wa-rahmatal liqawminy yu\'minoon','page_number'=>273,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>65,'arabic_text'=>'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ','transliteration'=>'Wallaahu anzala minas samaaa\'i maaa\'an fa-ahyaa bihil arda ba\'da mawtihaa; inna fee zaalika la-aayatal liqaw-miny yasma\'oon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>66,'arabic_text'=>'وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ','transliteration'=>'Wa-inna lakum fil an\'aami la\'ibrah; nusqeekum mimmmaa fee butoonihee mim baini farsinw Wa-damil labanann khaalisan saaa\'ighallish shaaribeen','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>67,'arabic_text'=>'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wa-min samaraatin nakheeli wal-a\'nnaabi tattakhizoona minhu sakaranw Wa-rizqann hasanaa; inna fee zaalika la-Aayatal liqawmien ya\'qiloon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>68,'arabic_text'=>'وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ','transliteration'=>'Wa-awhaa Rabbuka ilan nahli anit takhizee minal jabaali buyootanw Wa-minash shajari Wa-mimmaa ya\'rishoon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>69,'arabic_text'=>'ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Summma kulee min kullis samaraati faslukee subula Rabbiki zululaa; yakhruju mim butoonihaa sharaabum mukh-talifun alwaanuhoo feehi shifaaa\'ul linnaas, innna fee zaalika la-Aayatal liqawmien yatafakkaroon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>70,'arabic_text'=>'وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ','transliteration'=>'Wallaahu khalaqakum suma tatawaffaakum; Wa-minkum maien yuradu ilaaa arzalil \'umuri likai laa ya\'lama ba\'da \'ilmin shai\'aa; innal laaha \'Aleemun Qadeer','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>71,'arabic_text'=>'وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ','transliteration'=>'Wallaahu faddala ba\'dakum \'alaa ba\'din fir rizq; famal lazeena fuddiloo biraaaddee rizqihim \'alaa maa malakat aimaanuhum fahum feehi sawaaa\'; afabini\'matil laahi yajhadoon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>72,'arabic_text'=>'وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ','transliteration'=>'Wallaahu ja\'ala lakum min anfusikum azwaajanw Wa-ja\'ala lakum min azwaajikum baneena Wa-hafadatanw Wa-razaqakum minat taiyyibaat; afabil-baatili yu\'minoona Wa-bini\'matil laahi hum yakkfuroon','page_number'=>274,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>73,'arabic_text'=>'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقٗا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـٔٗا وَلَا يَسۡتَطِيعُونَ','transliteration'=>'Wa-ya\'budoona min doonil laahi maa laa yamliku lahum rizqam minas samaawaati wal-ardi shai\'anw Wa-laa yastatee\'oon','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>74,'arabic_text'=>'فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Falaa tadriboo lillaahil amsaal; innal laaha ya\'lamu Wa-antum laa ta\'lamoon','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>75,'arabic_text'=>'۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Darabal laahu masalan \'abdam mammlookal laa yaqdiru \'alaa shai\'inw Wa-mar razaqnaahu mminnaa rizqan hasanan fahuwa yunfiqu minhu sirranw Wa-jahra; hal yasta-woon; alhamdu lillaah; bal aksaruhum laa ya\'lamoon','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>76,'arabic_text'=>'وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-darabal laahu masalar rajulaini ahaduhumaaa abkamu laa yaqdiru \'alaa shai\'inw Wa-huwa kallun \'alaa mawlaahu ainamaa yuwajjihhu laa yaati bikhairin hal yastawee huwa Wa-maien yaamuru bil\'adli Wa-huwa \'alaa Siraatim Mustaqeem','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>77,'arabic_text'=>'وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wa-lillaahi ghaibus samaawaati wal-ard; Wa-maaa amrus Saa\'ati illaa kalamhil basari aw huwa aqrab; innal laaha \'alaaa kulli shai\'in Qadeer','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>78,'arabic_text'=>'وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wallaahu akhrajakum mim butooni ummahaatikum laa ta\'lamoona shai\'anw Wa-ja\'ala lakumus sam\'a wal-absaara wal-af\'idata la\'allakum tashkuroon','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>79,'arabic_text'=>'أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Alam yaraw ilat tairi musakhkharaatin fee jawwis samaaa\'i maa yumsikuhunna illal laah; inna fee zaalika la-Aayaatil liqawminy yu\'minoon','page_number'=>275,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>80,'arabic_text'=>'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ','transliteration'=>'Wallaahu ja\'ala lakum mim buyootikum sakananw Wa-ja\'ala lakum min juloodil an\'aami buyootan tastakhif-foonahaa yawma za\'nikum Wa-yawma iqaamatikum Wa-min aswaafihaa Wa-awbaarihaa Wa-ash\'aarihaaa asaasanw Wa-mataa\'an ilaa heen','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>81,'arabic_text'=>'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ','transliteration'=>'Wallaahu ja\'ala lakum mimmaa khalaqa zilaalanw Wa-ja\'ala lakum minal jibaali aknaananw Wa-ja\'ala lakum saraabeela taqeekumul harra Wa-saraabeela taqeekum baasakum; kazaalika yutimmu ni\'matahoo alaikum la\'allakum tuslimoon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>82,'arabic_text'=>'فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Fa-in tawallaw fa-innamaa \'alaikal balaaghul mubeen','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>83,'arabic_text'=>'يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ','transliteration'=>'Ya\'rifoona ni\'matal laahi summa yunkiroonahaa Wa-aksaruhumul kaafiroon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>84,'arabic_text'=>'وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةٖ شَهِيدٗا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ','transliteration'=>'Wa-yawma nab\'asu min kulli ummatin shaheedan summa laa yu\'zanu lillazeena kafaroo Wa-laa hum yusta\'taboon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>85,'arabic_text'=>'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ','transliteration'=>'Wa-izaa ra al-lazeena zalamul \'azaaba falaa yukhaf-fafu \'anhum Wa-laa hum yunzaroon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>86,'arabic_text'=>'وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ','transliteration'=>'Wa-izaa ra al-lazeena ashrakoo shurakaaa\'ahum qaaloo Rabbana haaa\'ulaaa\'i shurakaaa\'unal lazeena kunnaa nad\'oo min doonika fa-alqaw ilaihimul qawla innakum lakaaziboon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>87,'arabic_text'=>'وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Wa-alqaw ilal laahi yawma\'izinis salama Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>276,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>88,'arabic_text'=>'ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ','transliteration'=>'Allazeena kafaroo Wa-saddoo \'an sabeelil laahi zidnaahum \'azaaban fawqal \'azaabi bimaa kaanoo yufsidoon','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>89,'arabic_text'=>'وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ','transliteration'=>'Wa-yawma nab\'asu fee kulli ummmatin shaheedan \'alaihim min anfusihim Wa-ji\'naa bika shaheedan \'alaa haaa\'ulaaa\'; Wa-nazzalnaa \'alaikal Kitaaba tibyaanal likulli shai\'inw Wa-hudanw Wa-rahmatanw Wa-bushraa lilmuslimeen','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>90,'arabic_text'=>'۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Innal laaha ya\'muru bil-\'adli wal-ihsaani Wa-eetaaa\'i zil qurbaa Wa-yanhaa \'anil fahshaaa\'i wal-munkari walbagh-i\' ya\'izukum la\'allakum tazakkaroon','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>91,'arabic_text'=>'وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ','transliteration'=>'Wa-awfoo bi-Ahdil laahi izaa \'aahattum Wa-laa tanqudul aimaana ba\'da tawkeedihaa Wa-qad ja\'altumul laaha \'alaikum kafeelaa; innal laaha ya\'lamu maa taf\'aloon','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>92,'arabic_text'=>'وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','transliteration'=>'Wa-laa takoonoo kallatee naqadat ghazlahaa mim ba\'di quwwatin ankaasaa; tattakhizoona aimaanakum dakhlalam bainakum an takoona ummatun hiya arbaa min ummah; innnamaa yablookumul laahu bih; Wa-la-yubaiyyinanna lakum yawmal Qiyaamati maa kuntum feehi takhtalifoon','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>93,'arabic_text'=>'وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-law shaaa\'al laahu laja\'alakum ummmatanw waahidatanw Wa-laakien yudillu maien yashaaa\'u Wa-yahdee maien yashaaa\'; Wa-latus\'alunna \'ammaa kuntum ta\'maloon','page_number'=>277,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>94,'arabic_text'=>'وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Wa-laa tattakhizooo aimaanakum dakhalam bainakum fatazilla qadamum ba\'da subootihaa Wa-tazooqus sooo\'a bimmaa sadattum \'an sabeelil laahi Wa-lakum \'azaabun \'azeem','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>95,'arabic_text'=>'وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-laa tashtaroo bi-\'ahdil laahi samanan qaleelaa; innamaa \'indal laahi huwa khairul lakum in kuntum ta\'lamoon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>96,'arabic_text'=>'مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'maa \'indakum yanfadu Wa-maa \'indal laahi baaq; Wa-lanajziyannal lazeena sabarooo ajjrahum bi-ahsani maa kaanoo ya\'maloon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>97,'arabic_text'=>'مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Man \'amila saaliham min zakarin aw unsaa Wa-huwa mu\'minun falanuhyiyannahoo hayaatan taiiyibatanw Wa-lanajzi-yannnahum ajrahum bi-ahsani maa kaanoo ya\'maloon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>98,'arabic_text'=>'فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ','transliteration'=>'Fa-izaa qara-tal Quraana fasta\'iz billaahi minashh Shai-taanir rajeem','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>99,'arabic_text'=>'إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','transliteration'=>'Innahoo laisa lahoo sultaanun \'alal lazeena aamanoo Wa-\'alaa Rabbihim yatawakkaloon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>100,'arabic_text'=>'إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ','transliteration'=>'Innnamaa sultaanuhoo \'alal lazeena yatawallawnahoo wallazeena hum bihee mushrikoon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>101,'arabic_text'=>'وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-izaa baddalnaaa Aayatam makaana Aayatinw wal-laahu a\'lamu bimaa yunazzilu qaalooo innamaa anta muftar; bal aksaruhum laa ya\'lamoon','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>102,'arabic_text'=>'قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ','transliteration'=>'Qul nazzalahoo Roohul Qudusi mir Rabbika bilhaqqi liyusabbital lazeena aamanoo Wa-hudanw Wa-bushraa lilmuslimeen','page_number'=>278,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>103,'arabic_text'=>'وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ','transliteration'=>'Wa-laqad na\'lamu annahum yaqooloona innamaa yu\'allimuhoo bashar; lisaanul lazee yulhidoona ilaihi a\'ja-miyyunw Wa-haaza lisaanun \'Arabiyyum mubeen','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>104,'arabic_text'=>'إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ','transliteration'=>'Innal lazeena laa yu\'minoona bi-Aayaatil laahi laa yahdehimul laahu Wa-lahum \'azaabun aleem','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>105,'arabic_text'=>'إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ','transliteration'=>'Innamaa yaftaril kazibal lazeena laa yu\'minoona bi-Aayaatil laahi Wa-ulaaa\'ika humul kaaziboon','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>106,'arabic_text'=>'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Man kafara billaahi mim ba\'di eemaanihee illaa man ukriha Wa-qalbuhoo mutmma\'innum bil-eemaani Wa-laakim man sharaha bilkufri sadran fa\'alaihim ghadabum minal laahi Wa-lahum \'azaabun \'azeem','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>107,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','transliteration'=>'Zaalika bi-annahumus tahabbul hayaatad dunyaa \'alal Aakhirati Wa-annal laaha laa yahdil qawmal kaafireen','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>108,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ','transliteration'=>'Ulaaa\'ikal lazeena taba\'al laahu \'alaa quloobihim Wa-sam\'ihim Wa-absaarihim Wa-ulaaa\'ika humul ghaafiloon','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>109,'arabic_text'=>'لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Laa jarama annnahum fil Aakhirati humul khassiroon','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>110,'arabic_text'=>'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ','transliteration'=>'Summa inna Rabbaka lillazeena haajaroo mim ba\'dimaa futinoo summma jaahadoo Wa-sabaroo inna Rabbaka mim ba\'dihaa la Ghafoorur Raheem','page_number'=>279,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>111,'arabic_text'=>'۞ يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Yawma taatee kullu nafsin tujaadilu \'an nafsihaa Wa-tuwaffaa kullu nafsim maa \'amilat Wa-hum laa yuzlamoon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>112,'arabic_text'=>'وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ','transliteration'=>'Wa-darabal laahu masalan qaryatan kaanat aaminatam mutma\'innataien yaaateehaa rizquhaa raghadam min kulli makaanin fakafarat bi-an\'umil laahi fa-azaaqahal laahu libaasal joo\'i walkhawfi bimaa kaanoo yasna\'oon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>113,'arabic_text'=>'وَلَقَدۡ جَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ','transliteration'=>'Wa-laqad jaaa\'ahum Rasoolum minhum fakazzaboohu fa-akhazahumul \'azaabu Wa-hum zaalimoon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>114,'arabic_text'=>'فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ','transliteration'=>'Fakuloo mimmaa razaqa-kumul laahu halaalan taiyyibanw washkuroo ni\'matal laahi in kuntum iyyaahu ta\'budoon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>115,'arabic_text'=>'إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Innamaa harama \'alai-kumul maitata waddama Wa-lahmal khinzeeri Wa-maaa uhilla lighairil laahi bihee famanid turra ghaira baaghinw Wa-laa \'aadin fa-innal laaha Ghafoorur Raheem','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>116,'arabic_text'=>'وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ','transliteration'=>'Wa-laa taqooloo limaa tasifu alsinatukumul kaziba haaza halaalunw Wa-haazaa haraamul litaftaroo \'alal laahil kazib; innal lazeena yaftaroona \'alal laahil kaziba laa yuflihoon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>117,'arabic_text'=>'مَتَٰعٞ قَلِيلٞ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Mata\'un qaleelunw Wa-lahum \'azaabun aleem','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>118,'arabic_text'=>'وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Wa-\'alal lazeena haadoo harramnaa ma qasasnaa \'alaika min qablu Wa-maa zalamanaahum Wa-laakin kaanoo anfusahum yazlimoon','page_number'=>280,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>119,'arabic_text'=>'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ','transliteration'=>'Summma inna Rabbaka lillazeena \'amilus sooo\'a bijahaalatin summa taaboo mim ba\'di zaaalika Wa-aslahoo inna Rabbaka mim ba\'dihaa la-Ghafoorur Raheem','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>120,'arabic_text'=>'إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Inna Ibraaheema kaana ummatan qaanital lillaahi Haneefanw Wa-lam yaku minal mushrikeen','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>121,'arabic_text'=>'شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Shaakiral li-an\'umih; ijtabaahu Wa-hadaahu ilaa Siraatim Mustaqeem','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>122,'arabic_text'=>'وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-aatainaahu fid dunyaa hasanah; Wa-innahoo fil Aakhirati laminas saaliheen','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>123,'arabic_text'=>'ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Summma awhainaa ilaika anit tabi\' Millata Ibraaheema haneefaa; Wa-maa kaana minal mushrikeen','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>124,'arabic_text'=>'إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Innnamaa ju\'ilas Sabtu \'alal lazeenakhtalafoo feeh; Wa-inna Rabbaka la yahkumu bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>125,'arabic_text'=>'ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ','transliteration'=>'Ud\'u ilaa sabeeli Rabbika bilhikmati walmaw-\'izatil hasanati Wa-jaadilhum billatee hiya ahsan; inna Rabbaka huwa a\'almu biman dalla \'an sabeelihee Wa-Huwa a\'lamu bilmuhtadeen','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>126,'arabic_text'=>'وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّٰبِرِينَ','transliteration'=>'Wa-in \'aaqabtum fa\'aaqiboo bimisli maa \'ooqibtum bihee Wa-la\'in sabartum lahuwa khairul lissaabireen','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>127,'arabic_text'=>'وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ','transliteration'=>'Wasbir Wa-maa sabruka illaa billaah; Wa-laa tahzan \'alaihim Wa-laa taku fee daiqim mimmaa yamkuroon','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            ['surah_id'=>16,'ayah_number'=>128,'arabic_text'=>'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ','transliteration'=>'Innal laaha ma\'al lazeenat taqaw wal-lazeena hum muhsinoon','page_number'=>281,'juz_number'=>14,'hizb_number'=>28,'is_sajdah'=>false],
            /* Surah 17: The Night Journey (Al-Israa) */
            ['surah_id'=>17,'ayah_number'=>1,'arabic_text'=>'سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ','transliteration'=>'Subhaanal lazeee asraa bi\'abdihee lailam minal Masjidil Haraami ilal Masjidil Aqsal lazee baaraknaa haw-lahoo linuriyahoo min aayaatinaa; innahoo Huwas Samee\'ul Baseer','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>2,'arabic_text'=>'وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا','transliteration'=>'Wa-aatainaa Moosal Kitaaba Wa-ja\'alnaahu hudal liBaneee Israaa\'eel; allaa tat-takhizoo min doonee wakeelaa.','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>3,'arabic_text'=>'ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا','transliteration'=>'Zurriyyata man hamalnaa ma\'a Nooh innahoo kaana \'abdan shakooraa','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>4,'arabic_text'=>'وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا','transliteration'=>'Wa qadainaaa ilaa Baneee Israaa\'eela fil Kitaabi latufsidunna fil ardi marratain; Wa-lata\'lunna\'uluwwan kabeeraa','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>5,'arabic_text'=>'فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا','transliteration'=>'Fa-izaa jaaa\'a wa\'du oolaahumaa ba\'asnaaa \'alykum \'ibaadal lanaaa ulee baasin shadeedin fajaasoo khilaalad diyaar; Wa-kaana wa\'dam maf\'oolaa','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>6,'arabic_text'=>'ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا','transliteration'=>'Summa radadnaa lakumul karrata \'alaihim Wa-amdad-naakum-bi amwaalinuw Wa-baneen; Wa-ja\'alnaakum aksara nafeeraa','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>7,'arabic_text'=>'إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا','transliteration'=>'In ahsantum ahsantum li-anfusikum Wa-in asaatum falahaa; fa-izaa jaaa\'a wa\'dul aakhirati liyasooo\'oo wujoo-hakum Wa-liyadkhulul masjida kamaa dakhaloohu awwala marratinw Wa-liyutabbiroo maa a\'law tatbeera','page_number'=>282,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>8,'arabic_text'=>'عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا','transliteration'=>'Asaa rabbukum aien yarhamakum; Wa-in \'uttum \'udnaa; Wa-ja\'alnaa jahannama lilkaafireena haseera','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>9,'arabic_text'=>'إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا','transliteration'=>'Inna haazal Quraana yahdee lillatee hiya aqwamu Wa-yubashshirul mu\'mineenal lazeena ya\'maloonas saalihaati anna lahum ajran kabeeraa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>10,'arabic_text'=>'وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا','transliteration'=>'Wa-annal lazeena laa yu\'minoona bil-aakhirati a\'tadnaa lahum \'azaaban aleemaa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>11,'arabic_text'=>'وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا','transliteration'=>'Wa-yad\'ul insaanu bishsharri du\'aaa-\'ahoo bilkhayr; Wa-kaanal insaanu \'ajoola','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>12,'arabic_text'=>'وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا','transliteration'=>'Wa-ja\'alnal laila wannahaara Aayatayni famahawnaaa Aayatal laili Wa-ja\'alnaaa Aayatan nahaari mubsiratal litabtaghoo fadlam mir Rabbikum Wa-lita\'lamoo \'adadas sineena walhisaab; Wa-kulla shai\'in fassalnaahu tafseelaa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>13,'arabic_text'=>'وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا','transliteration'=>'Wa-kulla insaanin alzamnaahu taaa\'irahoo fee \'unuqihee Wa-nukhriji lahoo Yawmal Qiyaamati kitaabany yalqaahu manshooraa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>14,'arabic_text'=>'ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا','transliteration'=>'Iqra kitaabaka kafaa bi-nafsikal Yawma \'alaika haseebaa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>15,'arabic_text'=>'مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا','transliteration'=>'Manih tadaa fa-innamaa yahtadee linafsihee Wa-man dalla fa-innamaa yadillu \'alaihaa; Wa-laa taziru waaziratunw wizra ukhraa; Wa-maa kunnaa mu\'azzibeena hatta nab\'asa Rasoola','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>16,'arabic_text'=>'وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا','transliteration'=>'Wa-izaaa aradnaaa an nuhlika qaryatan amarnaa mutrafeehaa fafasaqoo feehaa fahaqqa \'alaihal qawlu fadammarnaahaa tadmeeraa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>17,'arabic_text'=>'وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا','transliteration'=>'Wa-kam ahlaknaa minal qurooni min ba\'di Nooh; Wa-kafaa bi-Rabbika bizunoobi \'ibaadihee Khabeeram Baseeraa','page_number'=>283,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>18,'arabic_text'=>'مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا','transliteration'=>'Man kaana yureedul \'aajilata \'ajjalnaa lahoo feehaa maa nashaaa\'u liman nureedu summa ja\'alnaa lahoo Jahannama yaslaahaa mazmoomammad hooraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>19,'arabic_text'=>'وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا','transliteration'=>'Wa-man araadal Aakhirata Wa-sa\'aa lahaa sa\'yahaa Wa-huwa mu\'minun fa-ulaaa\'ika kaana sa\'yuhum mashkooraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>20,'arabic_text'=>'كُلّٗا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا','transliteration'=>'Kullan numiddu haaa-\'ulaaa\'i Wa-haaa\'ulaaa\'i min \'ataaa\'i rabbik; Wa-maa kaana \'ataaa\'u rabbika mahzooraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>21,'arabic_text'=>'ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا','transliteration'=>'Unzur kaifa faddalnaa ba\'dahum \'alaa ba\'d; Wa-lal-Aakhiratu akbaru darajaatinw Wa-akbaru tafdeelaa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>22,'arabic_text'=>'لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا','transliteration'=>'Laa taj\'al ma\'al laahi ilaahan aakhara fataq\'uda mazoomam makhzoolaa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>23,'arabic_text'=>'۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا','transliteration'=>'Wa qadaa Rabbuka allaa ta\'budooo illaaa iyyaahu Wa-bilwaalidaini ihsaanaa; immaa yablughanna \'indakal kibara ahaduhumaaa aw kilaahumaa falaa taqul lahumaaa uffinw Wa-laa tanharhumaa Wa-qullahumaa qawlan kareemaa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>24,'arabic_text'=>'وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا','transliteration'=>'Wakhfid lahumaa janaahaz zulli minar rahmati Wa-qur Rabbir hamhumaa kamaa rabbayaanee sagheera','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>25,'arabic_text'=>'رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورٗا','transliteration'=>'Rabbukum a\'lamu bimaa fee nufoosikum; in takoonoo saaliheena fa-innahoo kaana lil-awwaabeena Ghafoooraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>26,'arabic_text'=>'وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا','transliteration'=>'Wa-aati zal qurbaa haqqahoo walmiskeena wabnas sabeeli Wa-laa tubazzir tabzeeraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>27,'arabic_text'=>'إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا','transliteration'=>'Innal mubazzireena kaanoo ikhwaanash shayaateeni Wa-kaanash shaytaanu li-Rabbihee kafooraa','page_number'=>284,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>28,'arabic_text'=>'وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا','transliteration'=>'Wa-immaa tu\'ridanna \'anhum ubtighaaa\'a rahmatim mir rabbika tarjoohaa faqul lahum qawlam maisooraa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>29,'arabic_text'=>'وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا','transliteration'=>'Wa-laa taj\'al yadaka maghloolatan ilaa \'unuqika Wa-laa tabsut-haa kullal basti fataq\'uda maloomam mahsooraa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>30,'arabic_text'=>'إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا','transliteration'=>'Inna Rabbaka yabsutur rizqa limaien yashaaa\'u Wa-yaqdir; innahoo kaana bi\'ibaadihee Khabeeran Baseera','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>31,'arabic_text'=>'وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا','transliteration'=>'Wa-laa taqtulooo awlaadakum khashyata imlaaqin nahnu narzuquhum Wa-iyyaakum; inna qatlahum kaana khit-\'an kabeeraa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>32,'arabic_text'=>'وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا','transliteration'=>'Wa-laa taqrabuz zinaaa innahoo kaana faahishatanw Wa-saaa\'a sabeelaa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>33,'arabic_text'=>'وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا','transliteration'=>'Wa-laa taqtulun nafsal latee harramal laahu illaa bilhaqq; Wa-man qutila mazlooman faqad ja\'alnaa liwaliyyihee sultaanan falaa yusrif fil qatli innahoo kaana mansooraa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>34,'arabic_text'=>'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا','transliteration'=>'Wa-laa taqraboo maalal yateemi illaa billatee hiya ahsanu hattaa yablugha ashuddah; Wa-awfoo bil\'ahd, innal \'ahda kaana mas\'oolaa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>35,'arabic_text'=>'وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا','transliteration'=>'Wa-awful kaila izaa kiltum Wa-zinoo bilqistaasil mustaqeem; zaalika khairunw Wa-ahsanu ta\'weelaa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>36,'arabic_text'=>'وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا','transliteration'=>'Wa-laa taqfu maa laisa laka bihee \'ilm; innas sam\'a walbasara walfu\'aada kullu ulaaa\'ika kaana \'anhu mas\'oolaa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>37,'arabic_text'=>'وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا','transliteration'=>'Wa-laa tamshi fil ardi marahan innaka lan takhriqal arda Wa-lan tablughal jibaala toola','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>38,'arabic_text'=>'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا','transliteration'=>'Kullu zaalika kaana sayyi\'uhoo inda Rabbika makroohaa','page_number'=>285,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>39,'arabic_text'=>'ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا','transliteration'=>'Zaalika mimmaaa awhaaa ilaika Rabbuka minal hikmah; Wa-laa taj\'al ma\'al laahi ilaahan aakhara fatulqaa fee Jahannama maloomammad hooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>40,'arabic_text'=>'أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا','transliteration'=>'Afa-asfaakum rabbukum bilbaneena wattakhaza minal malaaa\'ikati inaasaa; innakum lataqooloona qawlan \'azeema','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>41,'arabic_text'=>'وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا','transliteration'=>'Wa-laqad sarrafnaa fee haazal Quraani liyazzakkaroo Wa-maa yazeeduhum illaa nufooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>42,'arabic_text'=>'قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا','transliteration'=>'Qul law kaana ma\'ahooo aalihatun kamaa yaqooloona izal labtaghaw ilaa zil \'Arshi Sabeela','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>43,'arabic_text'=>'سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا','transliteration'=>'Subhaanahoo Wa-Ta\'aalaa \'ammaa yaqooloona \'uluwwan kabeeraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>44,'arabic_text'=>'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا','transliteration'=>'Tusabbihu lahus samaawaatus sab\'u wal-ardu Wa-man feehinn; Wa-im min shai\'in illaa yusabbihu bihamdihee Wa-laakil laa tafqahoona tasbeehahum; innahoo kaana Haleeman Ghafooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>45,'arabic_text'=>'وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا','transliteration'=>'Wa-izaa qara\'-tal Quraana ja\'alnaa bainaka Wa-bainal lazeena laa yu\'minoona bil-aakhirati hijaabam mastooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>46,'arabic_text'=>'وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا','transliteration'=>'Wa-ja\'alnaa \'alaa quloo-bihim akinnatan any yafqahoohu Wa-feee aazaanihim waqraa; Wa-izaa zakarta Rabbaka fil Quraani wahdahoo wallaw \'alaaa adbaarihim nufooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>47,'arabic_text'=>'نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا','transliteration'=>'Nahnu a\'lamu bimaa yastami\'oona biheee iz yastami\'oona ilaika Wa-iz hum najwaaa iz yaqooluz zaalimoona in tattabi\'oona illaa rajulam mas-hooraa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>48,'arabic_text'=>'ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا','transliteration'=>'Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee\'oona sabeelaa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>49,'arabic_text'=>'وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا','transliteration'=>'Wa-qaalooo \'a-izaa kunnaa \'izaamanw Wa-rufaatan \'a-innaa lamab\'oosoona khalqan jadeedaa','page_number'=>286,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>50,'arabic_text'=>'۞ قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا','transliteration'=>'Qul koonoo hijaaratan aw hadeedaa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>51,'arabic_text'=>'أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا','transliteration'=>'Aw khalqam mimmaa yakburu fee sudoorikum; fasa-yaqooloona maien yu\'eedunaa qulil lazee fatarakum awwala marrah; fasa yunghidoona ilaika ru\'oosahum Wa-yaqooloona mataahoo; qul \'asaaa any yakoona qareeba','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>52,'arabic_text'=>'يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا','transliteration'=>'Yawma yad\'ookum fatastajeeboona bihamdihee Wa-tazunnoona il labistum illaa qaleela','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>53,'arabic_text'=>'وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا','transliteration'=>'Wa-qul li\'ibaadee yaqoolul latee hiya ahsan; innash shaitaana yanzaghu bainahum; innash shaitaana kaana lil-insaani \'aduwwam mubeenaa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>54,'arabic_text'=>'رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا','transliteration'=>'Rabbukum a\'lamu bikum iny yasha\' yarhamkum aw iny yasha\' yu\'azzibkum; Wa-maaa arsalnaaka \'alaihim wakeelaa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>55,'arabic_text'=>'وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا','transliteration'=>'Wa-Rabbuka a\'lamu biman fis samaawaati wal-ard; Wa-laqad faddalnaa ba\'dan Nabiyyeena \'alaa ba\'dinw Wa-aatainaaa Daawooda Zabooraa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>56,'arabic_text'=>'قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا','transliteration'=>'Qulid \'ul lazeena za\'amtum min doonihee falaa yamlikoona kashfad durri \'ankum Wa-laa tahweelaa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>57,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا','transliteration'=>'Ulaaa\'ikal lazeena yad\'oona yabtaghoona ilaa Rabbihimul waseelata ayyuhum aqrabu Wa-yarjoona rahmatahoo Wa-yakhaafoona \'azaabah; inna \'azaaba rabbika kaana mahzooraa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>58,'arabic_text'=>'وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا','transliteration'=>'Wa-in min qaryatin illaa Nahnu muhlikoohaa qabla Yawmil Qiyaamati aw mu\'az-ziboohaa \'azaaban shadeedaa; kaana zaalika fil Kitaabi mastooraa','page_number'=>287,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>59,'arabic_text'=>'وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا','transliteration'=>'Wa-maa mana\'anaaa an nursila bil-aayaati illaaa an kazzaba bihal awwaloon; Wa-aatainaa Samoodan naaqata mubsiratan fazalamoo bihaa; Wa-maa nursilu bil-aayaati illaa takhweefaa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>60,'arabic_text'=>'وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا','transliteration'=>'Wa-iz qulnaa laka inna rabbaka ahaata binnaas; Wa-maa ja\'alnar ru\'yal lateee arainaaka illaa fitnatal linnaasi washshajaratal mal\'oonata fil quraan; Wa-nukhaw-wifuhum famaa yazeeduhum illa tughyaanan kabeeraa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>61,'arabic_text'=>'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا','transliteration'=>'Wa-iz qulnaa lilma-laaa\'ikatis judoo li-Aadama fasajadooo illaaa Ibleesa qaala \'a-asjudu liman khalaqta teena','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>62,'arabic_text'=>'قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا','transliteration'=>'Qaala ara\'aytaka haazal lazee karramta \'alaiya la\'in akhartani ilaa Yawmil Qiyaamati la-ahtanikanna zurriyyatahooo illaa qaleelaa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>63,'arabic_text'=>'قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا','transliteration'=>'Qaalaz hab faman tabi\'aka minhum fa-inna Jahannama jazaaa\'ukum jazaaa\'am mawfooraa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>64,'arabic_text'=>'وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا','transliteration'=>'Wastafziz manis tata\'ta minhum bisawtika Wa-ajlib \'alaihim bikhailika Wa-rajilika Wa-shaarik-hum fil amwaali wal-awlaadi Wa-\'idhum; Wa-maa ya\'iduhumush Shaitaanu illaa ghurooraa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>65,'arabic_text'=>'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا','transliteration'=>'Inna \'ibaadee laisa laka \'alaihim sultaan; Wa-kafaa bi-Rabbika Wakeelaa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>66,'arabic_text'=>'رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا','transliteration'=>'Rabbukumul lazee yuzjee lakumul fulka fil bahri litabtaghoo min fadlih; innahoo kaana bikum Raheemaa','page_number'=>288,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>67,'arabic_text'=>'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا','transliteration'=>'Wa-izaa massakumud durru fil bahri dalla man tad\'oona illaaa iyyaahu falammaa najjaakum ilal barri a\'radtum; Wa-kaanal insaanu kafooraa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>68,'arabic_text'=>'أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا','transliteration'=>'Afa-amintum aien yakhsifa bikum jaanibal barri aw yursila \'alaikum haasiban summa laa tajidoo lakum wakeelaa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>69,'arabic_text'=>'أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا','transliteration'=>'Am amintum aien yu\'eedakum feehi taaratan ukhraa fa-yursila \'alaikum qaasifam minar reehi fa-yugh-riqakum bimaa kafartum summa laa tajidoo lakum \'alainaa bihee tabee\'aa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>70,'arabic_text'=>'۞ وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا','transliteration'=>'Wa-laqad karramnaa Baneee aadama Wa-hamalnaahum fil barri walbahri Wa-razaqnaahum minat taiyibaati Wa-faddalnaahum \'alaa kaseerim mimman khalaqnaa tafdeelaa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>71,'arabic_text'=>'يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا','transliteration'=>'Yawma nad\'oo kulla unaasim bi-imaamihim faman ootiya kitaabahoo bi-yameenihee fa-ulaaa\'ika yaqra\'oona kitaabahum Wa-laa yuzlamoona fateelaa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>72,'arabic_text'=>'وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا','transliteration'=>'Wa-man kaana fee haaziheee a\'maa fahuwa fil aakhirati a\'maa Wa-adallu sabeelaa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>73,'arabic_text'=>'وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا','transliteration'=>'Wa-in kaadoo la-yaftinoonaka \'anil lazeee awhainaaa ilaika litaftariya \'alainaaa ghairahoo Wa-izallat takhazooka khaleelaa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>74,'arabic_text'=>'وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا','transliteration'=>'Wa-law-laaa an sabbatnaaka laqad kitta tarkanu ilaihim shai\'an qaleela','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>75,'arabic_text'=>'إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا','transliteration'=>'Izal la-azaqnaaka di\'fal hayaati Wa-di\'fal mamaati summa laa tajidu laka \'alainaa naseeraa','page_number'=>289,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>76,'arabic_text'=>'وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا','transliteration'=>'Wa-in kaadoo la-yastafizzoonaka minal ardi liyukhri-jooka minhaa Wa-izal laa yalbasoona khilaafaka illaa qaleelaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>77,'arabic_text'=>'سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا','transliteration'=>'Sunnata man qad arsalnaa qablaka mir Rusulinaa Wa-laa tajidu lisunnatinaa tahweelaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>78,'arabic_text'=>'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا','transliteration'=>'Aqimis Salaata liduloo-kish shamsi ilaa ghasaqil laili Wa-quraanal Fajri inna quraa-nal Fajri kaana mashhoodaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>79,'arabic_text'=>'وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا','transliteration'=>'Wa-minal laili fatahajjad bihee naafilatal laka \'asaaa any yab\'asaka Rabbuka Maqaamam Mahmoodaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>80,'arabic_text'=>'وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا','transliteration'=>'Wa-qur Rabbi adkhilnee mudkhala sidqinw Wa-akhrijnee mukhraja sidqinw waj\'al lee mil ladunka sultaanan naseeraa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>81,'arabic_text'=>'وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا','transliteration'=>'Wa-qul jaaa\'al haqqu Wa-zahaqal baatil; innal baatila kaana zahooqaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>82,'arabic_text'=>'وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا','transliteration'=>'Wa-nunazzilu minal quraani maa huwa shifaaa\'unw Wa-rahmatullil mu\'mineena Wa-laa yazeeduz zaalimeena illaa khasaaraa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>83,'arabic_text'=>'وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا','transliteration'=>'Wa-izaaa an\'amnaa \'alal insaani a\'rada Wa-na-aa bijaani-bihee Wa-izaa massahush sharru kaana ya\'oosaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>84,'arabic_text'=>'قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا','transliteration'=>'Qul kulluny ya\'malu \'alaa shaakilatihee fa-rabbukum a\'lamu biman huwa ahdaa sabeelaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>85,'arabic_text'=>'وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا','transliteration'=>'Wa-yas\'aloonaka \'anir rooh; qulir roohu min amri rabbee Wa-maaa ooteetum minal \'ilmi illaa qaleelaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>86,'arabic_text'=>'وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا','transliteration'=>'Wa-la\'in shi\'naa lanaz-habanna billazeee awhainaaa ilaika summa laa tajidu laka bihee \'alainaa wakeelaa','page_number'=>290,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>87,'arabic_text'=>'إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا','transliteration'=>'Illaa rahmatam mir Rabbik; inna fadlahoo kaana \'alaika kabeeraa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>88,'arabic_text'=>'قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا','transliteration'=>'Qul la\'inij tama\'atil insu waljinnu \'alaaa aien ya\'too bimisli haazal quraani laa ya\'toona bimislihee Wa-law kaana ba\'duhum liba-\'din zaheeraa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>89,'arabic_text'=>'وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا','transliteration'=>'Wa-laqad sarrafnaa linnaasi fee haazal quraani min kulli masalin fa-abaaa aksarun naasi illaa kufooraa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>90,'arabic_text'=>'وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا','transliteration'=>'Wa-qaaloo lan nu\'mina laka hattaa tafjura lanaa minal ardi yamboo\'aa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>91,'arabic_text'=>'أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا','transliteration'=>'Aw takoona laka jannatum min nakheelinw Wa-\'inabin fatufajjiral anhaara khilaalahaa tafjeeraa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>92,'arabic_text'=>'أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ قَبِيلًا','transliteration'=>'Aw tusqitas samaaa\'a kamaa za\'amta \'alainaa kisafan aw ta\'tiya billaahi wal-malaaa\'ikati qabeelaa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>93,'arabic_text'=>'أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا','transliteration'=>'Aw yakoona laka baitum min zukhrufin aw tarqaa fis samaaa\'i Wa-lan nu\'mina liruqiyyika hatta tunazzila \'alainaa kitaaban naqra\'uh; qul Subhaana Rabbee hal kuntu illaa basharar Rasoolaa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>94,'arabic_text'=>'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا','transliteration'=>'Wa-maa mana\'an naasa any yu\'minooo iz jaaa\'ahumul hudaaa illaaa an qaalooo aba\'asal laahu basharar Rasoolaa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>95,'arabic_text'=>'قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا','transliteration'=>'Qul law kaana fil ardi malaaa-\'ikatuien yamshoona mutma\'in-neena lanazzalnaa \'alaihim minas samaaa\'i malakar Rasoolaa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>96,'arabic_text'=>'قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا','transliteration'=>'Qul kafaa billaahi shaheedam bainee Wa-bainakum; innahoo kaana bi\'ibaadihee Khabeeram Baseeraa','page_number'=>291,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>97,'arabic_text'=>'وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا','transliteration'=>'Wa-maien yahdil laahu fahuwal muhtad; Wa-mai yudlil falan tajida lahum awliyaaa\'a min doonih; Wa-nahshuruhum Yawmal Qiyaamati \'alaa wujoohihim umyanw Wa-bukmanw Wa-summaa; ma\'waahum Jahannamu kullamaa khabat zidnaahum sa\'eeraa','page_number'=>292,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>98,'arabic_text'=>'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا','transliteration'=>'Zaalika jazaa\'uhum bi-annahum kafaroo bi-aayaatinaa Wa-qaalooo \'a-izaa kunnaa \'izaamanw Wa-rufaatan \'a-innaa la-mab\'oosoona khalqan jadeedaa','page_number'=>292,'juz_number'=>15,'hizb_number'=>29,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>99,'arabic_text'=>'۞ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورٗا','transliteration'=>'Awalam yaraw annal laahal lazee khalaqas samaawaati wal-arda qaadirun \'alaaa aien yakhluqa mislahum Wa-ja\'ala lahum ajalal laa raiba fee; fa-abaz zaalimoona illaa kufooraa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>100,'arabic_text'=>'قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا','transliteration'=>'Qul law antum tamlikoona khazaaa\'ina rahmati Rabbeee izal la-amsaktum khash-yatal infaaq; Wa-kaanal insaanu qatooraa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>101,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا','transliteration'=>'Wa-laqad aatainaa Moosaa tis\'a Aayaatim baiyyinaatin fas\'al Baneee Israaa\'eela iz jaaa\'ahum faqaala lahoo Fir\'awnu inee la-azunnuka yaa-Moosaa mas-hooraa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>102,'arabic_text'=>'قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا','transliteration'=>'Qaala laqad \'alimta maaa anzala haaa\'ulaaa\'i illaa Rabbus samaawaati wal-ardi basaaa\'ira Wa-innee la-azun-nuka yaa-Fir\'awnu masbooraa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>103,'arabic_text'=>'فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا','transliteration'=>'Fa-araada aien yastafizzahum minal ardi fa-aghraqnaahu Wa-mam ma\'ahoo jamee\'aa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>104,'arabic_text'=>'وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا','transliteration'=>'Wa-qulnaa min ba\'dihee li-Baneee Israaa\'eelas kunul arda fa-izaa jaaa\'a wa\'dul aakhirati ji\'naa bikum lafeefaa','page_number'=>292,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>105,'arabic_text'=>'وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا','transliteration'=>'Wa-bilhaqqi anzalnaahu Wa-bilhaqqi nazal; Wa-maaa arsalnaaka illaa mubash-shiranw Wa-nazeeraa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>106,'arabic_text'=>'وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا','transliteration'=>'Wa-quraanan faraqnaahu litaqra-ahoo \'alan naasi \'alaa muksinw Wa-nazzalnaahu tanzeelaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>107,'arabic_text'=>'قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ','transliteration'=>'Qul aaminoo biheee aw laa tu\'minoo; innal lazeena ootul \'ilma min qabliheee izaa yutlaa \'alaihim yakhirroona lil-azqaani sujjadaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>108,'arabic_text'=>'وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا','transliteration'=>'Wa-yaqooloona Subhaana Rabbinaaa in kaana wa\'du Rabbinaa lamaf\'oolaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>109,'arabic_text'=>'وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا','transliteration'=>'Wa-yakhirroona lil-azqaani yabkoona Wa-yazeeduhum khushoo\'aa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>true],
            ['surah_id'=>17,'ayah_number'=>110,'arabic_text'=>'قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا','transliteration'=>'Qulid \'ul laaha awid \'ur Rahmaana ayyam maa tad\'oo falahul asmaaa\'ul Husnaa; Wa-laa tajhar bi-Salaatika Wa-laa tukhaafit bihaa wabtaghi baina zaalika sabeela','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>17,'ayah_number'=>111,'arabic_text'=>'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا','transliteration'=>'Wa-qulil hamdu lillaahil lazee lam yattakhiz waladanw Wa-lam yakul lahoo shareekun fil mulki Wa-lam yakul lahoo waliyyum minaz zulli Wa-kabbirhu takbeeraa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            /* Surah 18: The Cave (Al-Kahf) */
            ['surah_id'=>18,'ayah_number'=>1,'arabic_text'=>'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ','transliteration'=>'Alhamdu lillaahil lazeee anzala \'alaa \'abdihil kitaaba Wa-lam yaj\'al lahoo \'iwajaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>2,'arabic_text'=>'قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا','transliteration'=>'Qaiyimal liyunzira ba\'asan shadeedam mil ladunhu Wa-yubashshiral mu\'mineenal lazeena ya\'maloonas saalihaati anna lahum ajran hasanaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>3,'arabic_text'=>'مَّٰكِثِينَ فِيهِ أَبَدٗا','transliteration'=>'Maakiseena feehi abadaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>4,'arabic_text'=>'وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗا','transliteration'=>'Wa-yunziral lazeena qaalut takhazal laahu waladaa','page_number'=>293,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>5,'arabic_text'=>'مَّا لَهُم بِهِۦ مِنۡ عِلۡمٖ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبٗا','transliteration'=>'Maa lahum bihee min \'ilminw Wa-laa li-aabaaa\'ihim; kaburat kalimatan takhruju min afwaahihim; iny yaqooloona illaa kazibaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>6,'arabic_text'=>'فَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا','transliteration'=>'Fala\'allaka baakhi\'un nafsaka \'alaaa aasaarihim il lam yu\'minoo bihaazal hadeesi asafaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>7,'arabic_text'=>'إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا','transliteration'=>'Innaa ja\'alnaa ma \'alal ardi zeenatal lahaa linabluwahum ayyuhum ahsanu \'amalaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>8,'arabic_text'=>'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيۡهَا صَعِيدٗا جُرُزًا','transliteration'=>'Wa-innaa la-jaa\'iloona maa \'alaihaa sa\'eedan juruzaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>9,'arabic_text'=>'أَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا','transliteration'=>'Am hasibta anna Ashaabal Kahfi war-Raqeemi kaanoo min Aayaatinaa \'ajabaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>10,'arabic_text'=>'إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا','transliteration'=>'Iz awal fityatu ilal Kahfi faqaaloo Rabbanaaa aatinaa mil ladunka rahmatanw Wa-haiyi\' lanaa min amrinaa rashadaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>11,'arabic_text'=>'فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي ٱلۡكَهۡفِ سِنِينَ عَدَدٗا','transliteration'=>'Fadarabnaa \'alaaa aazaanihim fil Kahfi seneena \'adadaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>12,'arabic_text'=>'ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا','transliteration'=>'Summa ba\'asnaahum lina\'lama ayyul hizbaini ahsaa limaa labisooo amadaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>13,'arabic_text'=>'نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى','transliteration'=>'Nahnu naqussu \'alaika naba-ahum bilhaqq; innahum fityatun aamanoo bi-Rabbihim Wa-zidnaahum hudaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>14,'arabic_text'=>'وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ لَّقَدۡ قُلۡنَآ إِذٗا شَطَطًا','transliteration'=>'Wa-rabatnaa \'alaa quloo-bihim iz qaamoo faqaaloo Rabbunaa Rabbus samaawaati wal-ardi lan nad\'uwa min dooniheee ilaahal laqad qulnaaa izan shatataa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>15,'arabic_text'=>'هَٰٓؤُلَآءِ قَوۡمُنَا ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ لَّوۡلَا يَأۡتُونَ عَلَيۡهِم بِسُلۡطَٰنِۭ بَيِّنٖۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا','transliteration'=>'Haaa\'ulaaa\'i qawmunat takhazoo min dooniheee aalihatal law laa yaatoona \'alaihim bisultaanim baiyin; faman azlamu mimmaniftaraa \'alal laahi kazibaa','page_number'=>294,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>16,'arabic_text'=>'وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقٗا','transliteration'=>'Wa-izi\'tazal tumoohum Wa-maa ya\'budoona illal laaha faawooo ilal kahfi yanshur lakum Rabbukum mir rahmatihee Wa-yuhaiyi\' lakum min amrikum mirfaqa','page_number'=>295,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>17,'arabic_text'=>'۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيّٗا مُّرۡشِدٗا','transliteration'=>'Wa-tarash shamsa izaa tala\'at tazaawaru \'an kahfihim zaatal yameeni Wa-izaa gharabat taqriduhum zaatash shimaali Wa-hum fee fajwatim minh; zaalika min Aayaatil laah; maien yahdil laahu fahuwal muhtad, Wa-maien yudlil falan tajida lahoo waliyyam murshidaa','page_number'=>295,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>18,'arabic_text'=>'وَتَحۡسَبُهُمۡ أَيۡقَاظٗا وَهُمۡ رُقُودٞۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَارٗا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبٗا','transliteration'=>'Wa-tahsabuhum ayqaazanw Wa-hum ruqood; Wa-nuqallibuhum zaatal yameeni Wa-zaatash shimaali Wa-kalbuhum baasitun ziraa\'ayhi bilwaseed; lawit tala\'ta \'alaihim la-wallaita minhum firaaranw Wa-lamuli\'ta minhum rubaa','page_number'=>295,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>19,'arabic_text'=>'وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا','transliteration'=>'Wa-kazaalika ba\'asnaahum liyatasaaa\'aloo bainahum; qaala qaaa\'ilum minhum kam labistum qaaloo labisnaa yawman aw ba\'da yawm; qaaloo Rabbukum a\'lamu bimaa labistum fab\'asooo ahadakum biwariqikum haazihee ilal madeenati falyanzur ayyuhaaa azkaa ta\'aaman falyaatikum birizqim minhu walyatalattaf Wa-laa yush\'iranna bikum ahadaa','page_number'=>295,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>20,'arabic_text'=>'إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا','transliteration'=>'Innahum ien yazharoo \'alaikum yarjumookum aw yu\'eedookum fee millatihim Wa-lan tuflihooo izan abadaa','page_number'=>295,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>21,'arabic_text'=>'وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا','transliteration'=>'Wa-kazaalika a\'sarnaa \'alaihim liya\'lamooo anna wa\'dal laahi haqqunw Wa-annas Saa\'ata laa raiba feehaa iz yatanaaza\'oona bainahum amrahum faqaalub noo \'alaihim bunyaanaa; Rabbuhum a\'lamu bihim; qaalal lazeena ghalaboo \'alaaa amrihim lanat-takhizanna \'alaihim masjidaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>22,'arabic_text'=>'سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا','transliteration'=>'Sa-yaqooloona salaasatur raabi\'uhum kalbuhum Wa-yaqooloona khamsatun saadisuhum kalbuhum rajmam bilghaib; Wa-yaqooloona sab\'atunw Wa-saaminuhum kalbuhum; qur Rabbeee a\'lamu bi\'iddatihim maa ya\'lamuhum illaa qaleel; falaa tumaari feehim illaa miraaa\'an zaahiranw Wa-laa tastafti feehim minhum ahadaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>23,'arabic_text'=>'وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا','transliteration'=>'Wa-laa taqoolanna lishai\'in innee faa\'ilun zaalika ghadaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>24,'arabic_text'=>'إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا','transliteration'=>'Illaaa aien yashaaa\'al laah; wazkur Rabbaka izaa naseeta Wa-qul \'asaaa any yahdiyani Rabbee li-aqraba min haazaa rashadaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>25,'arabic_text'=>'وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةٖ سِنِينَ وَٱزۡدَادُواْ تِسۡعٗا','transliteration'=>'Wa-labisoo fee kahfihim salaasa mi\'atin sineena wazdaadoo tis\'aa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>26,'arabic_text'=>'قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا','transliteration'=>'Qulil laahu a\'lamu bimaa labisoo lahoo ghaibus samaawaati wal-ardi absir bihee Wa-asmi\'; maa lahum min doonihee minw waliyyinw Wa-laa yushriku fee hukmihee ahadaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>27,'arabic_text'=>'وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدٗا','transliteration'=>'Watlu maaa oohiya ilaika min Kitaabi Rabbika laa mubaddila li-Kalimaatihee Wa-lan tajida min doonihee multahadaa','page_number'=>296,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>28,'arabic_text'=>'وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا','transliteration'=>'Wasbir nafsaka ma\'al lazeena yad\'oona Rabbahum bilghadaati wal\'ashiyyi yureedoona Wajhahoo Wa-laa ta\'du \'aynaaka \'anhum tureedu zeenatal hayaatid dunyaa Wa-laa tuti\' man aghfalnaa qalbahoo \'an zikrinaa wattaba\'a hawaahu Wa-kaana amruhoo furutaa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>29,'arabic_text'=>'وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا','transliteration'=>'Wa-qulil haqqu mir Rabbikum faman shaaa\'a falyu\'minw Wa-man shaaa\'a falyakfur; innaaa a\'tadnaa lizzaalimeena Naaran ahaata bihim suraadiquhaa; Wa-ien yastagheesoo yughaasoo bimaaa\'in kalmuhli yashwil wujooh\' bi\'sash sharaab; Wa-saaa\'at murtafaqaa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>30,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati innaa laa nudee\'u ajra man ahsana \'amalaa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>31,'arabic_text'=>'أُوْلَٰٓئِكَ لَهُمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَيَلۡبَسُونَ ثِيَابًا خُضۡرٗا مِّن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقٗا','transliteration'=>'Ulaaa\'ika lahum Jannaatu \'Adnin tajree min tahtihimul anhaaru yuhallawna feehaa min asaawira min zahabinw Wa-yalbasoona siyaaban khudram min sundusinw Wa-istabraqim muttaki\'eena feehaa \'alal araaa\'ik; ni\'mas sawaab; Wa-hasunat murtafaqaa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>32,'arabic_text'=>'۞ وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا','transliteration'=>'Wadrib lahum masalar rajulaini ja\'alnaa li-ahadihimaa jannataini min a\'naabinw Wa-hafafnaahumaa binakhilinw Wa-ja\'alnaa bainahumaa zar\'aa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>33,'arabic_text'=>'كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا','transliteration'=>'Kiltal jannataini aatat ukulahaa Wa-lam tazlim minhu shai\'anw Wa-fajjarnaa khi-laalahumaa naharaa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>34,'arabic_text'=>'وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا','transliteration'=>'Wa-kaana lahoo samarun faqaala lisaahibihee Wa-huwa yuhaawiruhoo ana aksaru minka maalanw Wa-a\'azzu nafaraa','page_number'=>297,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>35,'arabic_text'=>'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا','transliteration'=>'Wa-dakhala jannatahoo Wa-huwa zaalimul linafsihee qaala maaa azunnu an tabeeda haaziheee abadaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>36,'arabic_text'=>'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا','transliteration'=>'Wa-maaa azunnus Saa\'ata qaaa\'imatanw Wa-la\'ir rudittu ilaa Rabbee la-ajidanna khairam minhaa munqalabaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>37,'arabic_text'=>'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرۡتَ بِٱلَّذِي خَلَقَكَ مِن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ سَوَّىٰكَ رَجُلٗا','transliteration'=>'Qaala lahoo saahibuhoo Wa-huwa yuhaawiruhooo akafarta billazee khalaqaka min turaabin summa min nutfatin summa sawwaaka rajulaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>38,'arabic_text'=>'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّي وَلَآ أُشۡرِكُ بِرَبِّيٓ أَحَدٗا','transliteration'=>'Laakinaa Huwal laahu Rabbee Wa-laa ushriku bi-Rabbeee ahadaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>39,'arabic_text'=>'وَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا','transliteration'=>'Wa-law-laaa iz dakhalta jannataka qulta maa shaaa\'al laahu laa quwwata illaa billaah; in tarani ana aqalla minka maalanw Wa-waladaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>40,'arabic_text'=>'فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَانٗا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدٗا زَلَقًا','transliteration'=>'Fa\'asaa Rabeee aien yu\'tiyani khairam min jannatika Wa-yursila \'alaihaa husbaanam minas samaaa\'i fatusbiha sa\'eedan zalaqaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>41,'arabic_text'=>'أَوۡ يُصۡبِحَ مَآؤُهَا غَوۡرٗا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبٗا','transliteration'=>'Aw yusbiha maaa\'uhaaa ghawran falan tastatee\'a lahoo talabaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>42,'arabic_text'=>'وَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا','transliteration'=>'Wa-uheeta bisamarihee faasbaha yuqallibu kaffaihi \'alaa maaa anfaqa feehaa Wa-hiya khaawiyatun \'alaa \'urooshihaa Wa-yaqoolu yaalaitanee lam ushrik bi-Rabbeee ahadaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>43,'arabic_text'=>'وَلَمۡ تَكُن لَّهُۥ فِئَةٞ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا','transliteration'=>'Wa-lam takul lahoo fi\'atuien yansuroonahoo min doonil laahi Wa-maa kaana muntasiraa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>44,'arabic_text'=>'هُنَالِكَ ٱلۡوَلَٰيَةُ لِلَّهِ ٱلۡحَقِّۚ هُوَ خَيۡرٞ ثَوَابٗا وَخَيۡرٌ عُقۡبٗا','transliteration'=>'Hunaalikal walaayatu lillaahil haqq; huwa khairun sawaabanw Wa-khairun \'uqbaa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>45,'arabic_text'=>'وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقۡتَدِرًا','transliteration'=>'Wadrib lahum masalal hayaatid dunyaa kamaaa\'in anzalnaahu minas samaaa\'i fakhtalata bihee nabaatul ardi fa-asbaha hasheeman tazroo-hur riyaah; Wa-kaanal laahu \'alaa kulli shai\'im muqtadiraa','page_number'=>298,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>46,'arabic_text'=>'ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا','transliteration'=>'Almaalu walbanoona zeenatul hayaatid dunya wal-baaqiyaatus saalihaatu khairun \'inda Rabbika sawaabanw Wa-khairun amalaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>47,'arabic_text'=>'وَيَوۡمَ نُسَيِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ وَحَشَرۡنَٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدٗا','transliteration'=>'Wa-yawma nusaiyirul jibaala Wa-taral arda baariza-tanw Wa-hasharnaahum falam nughaadir minhum ahadaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>48,'arabic_text'=>'وَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّٗا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدٗا','transliteration'=>'Wa \'uridoo \'alaa Rabbika saffaa, laqad ji\'tumoonaa kamaa khalaqnaakum awala marrah; bal za\'amtum allannaj\'ala lakum maw\'idaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>49,'arabic_text'=>'وَوُضِعَ ٱلۡكِتَٰبُ فَتَرَى ٱلۡمُجۡرِمِينَ مُشۡفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا','transliteration'=>'Wa-wudi\'al kitaabu fataral mujrimeena mushfiqeena mimmaa feehi Wa-yaqooloona yaa-wailatanaa maa lihaazal kitaabi laa yughaadiru saghee-ratanw Wa-laa kabeeratan illaaa ahsaahaa; Wa-wajadoo maa \'amiloo haadiraa; Wa-laa yazlimu Rabbuka ahadaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>50,'arabic_text'=>'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّٰلِمِينَ بَدَلٗا','transliteration'=>'Wa-iz qulnaa lilma-laaa\'ikatis judoo li-Aadama fasajadooo illaaa Ibleesa kaana minal jinni fafasaqa \'an amri Rabbih; afatattakhizoonahoo Wa-zurriyatahooo awliyaaa\'a min doonee Wa-hum lakum \'aduww; bi\'sa lizzaalimeena badalaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>51,'arabic_text'=>'۞ مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدٗا','transliteration'=>'Maaa ash-hattuhum khalqas samaawaati wal-ardi Wa-laa khalqa anfusihim Wa-maa kuntu muttakhizal mudilleena \'adudaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>52,'arabic_text'=>'وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ٱلَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَجَعَلۡنَا بَيۡنَهُم مَّوۡبِقٗا','transliteration'=>'Wa-Yawma yaqoolu naadoo shurakaaa\'i yal-lazeena za\'amtum fada\'awhum falam yastajeeboo lahum Wa-ja\'alnaa bainahum maw-biqaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>53,'arabic_text'=>'وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ يَجِدُواْ عَنۡهَا مَصۡرِفٗا','transliteration'=>'Wa-ra al-mujrimoonan Naara fazannooo annahum muwaaqi\'oohaa Wa-lam yajidoo \'anhaa masrifaa','page_number'=>299,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>54,'arabic_text'=>'وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا','transliteration'=>'Wa-laqad sarrafnaa fee haazal quraani linnaasi min kulli masal; Wa-kaanal insaanu aksara shai\'in jadalaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>55,'arabic_text'=>'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰ وَيَسۡتَغۡفِرُواْ رَبَّهُمۡ إِلَّآ أَن تَأۡتِيَهُمۡ سُنَّةُ ٱلۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ قُبُلٗا','transliteration'=>'Wa-maa mana\'an naasa any yu\'minooo iz jaaa\'ahumul hudaa Wa-yastaghfiroo Rabbahum illaaa an taatiyahum sunnatul awwaleena aw yaatiyahumul \'azaabu qubulaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>56,'arabic_text'=>'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا','transliteration'=>'Wa-maa nursilul mursaleena illaa mubashshireena Wa-munzireen; Wa-yujaadilul lazeena kafaroo bilbaatili liyudhidoo bihil haqqa wattakhazooo Aayaatee Wa-maaa unziroo huzuwaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>57,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا','transliteration'=>'Wa-man azlamu mimman zukkira bi-ayaati Rabbihee fa-a\'rada \'anhaa Wa-nasiya maa qaddamat yadaah; innaa ja\'alnaa \'alaa quloobihim akinnatan any yafqahoohu Wa-feee aazaanihim waqraa; Wa-in tad\'uhum ilal hudaa falany yahtadooo izan abadaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>58,'arabic_text'=>'وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدٞ لَّن يَجِدُواْ مِن دُونِهِۦ مَوۡئِلٗا','transliteration'=>'Wa-Rabbukal Ghafooru zur rahmati law yu\'aakhi-zuhum bimaa kasaboo la\'ajala lahumul \'azaab; bal lahum maw\'idul laien yajidoo min doonihee maw\'ilaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>59,'arabic_text'=>'وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدٗا','transliteration'=>'Wa-tilkal quraaa ahlak-nahum lammaa zulamoo Wa-ja\'alnaa limahlikihim maw\'idaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>60,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا','transliteration'=>'Wa-iz qaalaa Moosaa lifataahu laaa abrahu hattaaa ablugha majma\'al bahrayni aw amdiya huqubaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>61,'arabic_text'=>'فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا','transliteration'=>'Falammaa balaghaa majma\'a bainihimaa nasiyaa hootahumaa fattakhaza sabeelahoo fil bahri sarabaa','page_number'=>300,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>62,'arabic_text'=>'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا','transliteration'=>'Falammaa jaawazaa qaala lifataahu aatinaa ghadaaa\'anaa laqad laqeena min safarinaa haazaa nasabaa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>63,'arabic_text'=>'قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا','transliteration'=>'Qaala ara\'ayta iz awainaaa ilas sakhrati fa-innee naseetul hoota Wa-maaa ansaaneehu illash Shaitaanu an azkurah; wattakhaza sabeelahoo fil bahri \'ajabaa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>64,'arabic_text'=>'قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا','transliteration'=>'Qaala zaalika maa kunnaa nabghi; fartaddaa \'alaa aasaari-him-maa qasasaa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>65,'arabic_text'=>'فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا','transliteration'=>'Fa-wajadaa \'abdam min \'ibaadinaaa aatainaahu Rahmatam min \'indinaa Wa-\'allamnaahu mil ladunnaa \'ilmaa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>66,'arabic_text'=>'قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا','transliteration'=>'Qaala lahoo Moosaa hal attabi\'uka \'alaaa an tu\'allimani mimmaa \'ullimta rushdaa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>67,'arabic_text'=>'قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا','transliteration'=>'Qaalaa innaka lan tastatee\'a ma\'iya sabraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>68,'arabic_text'=>'وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا','transliteration'=>'Wa-kaifa tasbiru \'alaa maa lam tuhit bihee khubraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>69,'arabic_text'=>'قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا','transliteration'=>'Qaala satajiduneee in shaa \'al-laahu saabiranw Wa-laaa a\'see laka amraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>70,'arabic_text'=>'قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا','transliteration'=>'Qaala fa-init taba\'tanee falaa tas\'alnee \'an shai\'in hattaaa uhdisa laka minhu zikraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>71,'arabic_text'=>'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرٗا','transliteration'=>'Fantalaqaa hattaaa izaa rakibaa fis safeenati kharaqahaa qaala akharaqtahaa litughriqa ahlahaa laqad ji\'ta shai\'an imraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>72,'arabic_text'=>'قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا','transliteration'=>'Qaala alam aqul innaka lan tastatee\'a ma\'iya sabraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>73,'arabic_text'=>'قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرٗا','transliteration'=>'Qaala laa tu\'aakhiznee bimaa naseetu Wa-laa turhiqnee min amree \'usraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>74,'arabic_text'=>'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمٗا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسٗا زَكِيَّةَۢ بِغَيۡرِ نَفۡسٖ لَّقَدۡ جِئۡتَ شَيۡـٔٗا نُّكۡرٗا','transliteration'=>'Fantalaqaa hattaa izaa laqiyaa ghulaaman faqatalahoo qaala aqatalta nafsan zakiy-yatam bighairi nafs; laqad ji\'ta shai\'an nukraa','page_number'=>301,'juz_number'=>15,'hizb_number'=>30,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>75,'arabic_text'=>'۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا','transliteration'=>'Qaala alam aqul laka innaka lan tastatee\'a ma\'iya sabraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>76,'arabic_text'=>'قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا','transliteration'=>'Qaala in sa-altuka \'an shai\'im ba\'dahaa falaa tusaahibnee qad balaghta mil ladunnee \'uzraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>77,'arabic_text'=>'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا','transliteration'=>'Fantalaqaa hattaaa izaaa atayaaa ahla qaryatinis tat\'amaaa ahlahaa fa-abaw any yudaiyifoohumaa fawajadaa feehaa jidaarany yureedu any yanqadda fa-aqaamah; qaala law shi\'ta lattakhazta \'alaihi ajraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>78,'arabic_text'=>'قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا','transliteration'=>'Qaala haazaa firaaqu bainee Wa-bainik; sa-unabi-\'uka bitaaweeli maa lam tastati\' \'alaihi sabraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>79,'arabic_text'=>'أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا','transliteration'=>'Ammas safeenatu fakaanat limasaakeena ya\'maloona fil bahri fa-arattu an a\'eebahaa Wa-kaana waraaa\'-ahum malikuien yaakhuzu kulla safeenatin ghasbaa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>80,'arabic_text'=>'وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا','transliteration'=>'Wa-aammal ghulaamu fakaana abawaahu mu\'minaini fakhasheenaaa aien yurhiqa-humaa tughyaananw Wa-kufraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>81,'arabic_text'=>'فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا','transliteration'=>'Faradnaa aien yubdila-humaa Rabbuhumaa khairam minhu zakaatanw Wa-aqraba ruhmaa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>82,'arabic_text'=>'وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا','transliteration'=>'Wa-ammal jidaaru fakaana lighulaamaini yateemaini fil madeenati Wa-kaana tahtahoo kanzul lahumaa Wa-kaana aboohumaa saalihan fa-araada Rabbuka any yablughaaa ashuddahumaa Wa-yastakhrijaa kanzahumaa rahmatam mir Rabbik; Wa-maa fa\'altuhoo \'an amree; zaalika taaweelu maa lam tasti\' \'alaihi sabra','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>83,'arabic_text'=>'وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا','transliteration'=>'Wa-yas\'aloonaka \'an Zil Qarnaini qul sa-atloo \'alaikum minhu zikraa','page_number'=>302,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>84,'arabic_text'=>'إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا','transliteration'=>'Innaa makkannaa lahoo fil ardi Wa-aatainaahu min kulli shai\'in sababaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>85,'arabic_text'=>'فَأَتۡبَعَ سَبَبًا','transliteration'=>'Fa-atba\'a sababaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>86,'arabic_text'=>'حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا','transliteration'=>'Hattaaa izaa balagha maghribash shamsi wajadahaaa taghrubu fee \'aynin hami\'a-tinw Wa-wajada \'indahaa qawmaa; qulnaa yaa-Zal Qarnaini immaaa an tu\'az-ziba Wa-immaaa an tattakhiza feehim husnaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>87,'arabic_text'=>'قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا','transliteration'=>'Qaala amma man zalama fasawfa nu\'azzibuhoo summa yuraddu ilaa Rabbihee fa-yu-\'azzibuhoo azaaban nukraa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>88,'arabic_text'=>'وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا','transliteration'=>'Wa-ammaa man aamana Wa-\'amila saalihan falahoo jazaaa\'anil husnaa Wa-sanaqoolu lahoo min amrinaa yusraa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>89,'arabic_text'=>'ثُمَّ أَتۡبَعَ سَبَبًا','transliteration'=>'Summa atba\'a sababaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>90,'arabic_text'=>'حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا','transliteration'=>'Hattaaa izaa balagha matli\'ash shamsi wajdahaa tatlu\'u alaa qawmil lam naj\'al lahum min doonihaa sitraa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>91,'arabic_text'=>'كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا','transliteration'=>'Kazaalika Wa-qad ahatnaa bimaa ladaihi khubraa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>92,'arabic_text'=>'ثُمَّ أَتۡبَعَ سَبَبًا','transliteration'=>'Summa atba\'a sababaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>93,'arabic_text'=>'حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا','transliteration'=>'Hattaaa izaa balagha bainas saddaini wajada min doonihimaa qawmal laa yakaa-doona yafqahoona qawlaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>94,'arabic_text'=>'قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا','transliteration'=>'Qaaloo yaa-Zal qarnaini inna Yaajooja Wa-Maajooja mufsidoona fil ardi fahal naj\'alu laka kharjan \'alaaa an taj\'ala bainanaa Wa-bainahum saddaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>95,'arabic_text'=>'قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا','transliteration'=>'Qaala maa makkannee feehi Rabbee khairun fa-a\'eenoonee biquwwatin aj\'al bainakum Wa-bainahum radmaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>96,'arabic_text'=>'ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا','transliteration'=>'Aatoonee zubaral hadeed, hattaaa izaa saawaa bainas sadafaini qaalan fukhoo hattaaa izaa ja\'alahoo naaran qaala aatooneee ufrigh \'alaihi qitraa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>97,'arabic_text'=>'فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا','transliteration'=>'Famas taa\'ooo aien yazharoohu Wa-mas tataa\'oo lahoo naqbaa','page_number'=>303,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>98,'arabic_text'=>'قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا','transliteration'=>'Qaala haaza rahmatum mir Rabbee fa-izaa jaaa\'a wa\'du Rabbee ja\'alahoo dakkaaa\'a; Wa-kaana; Wa-du Rabbee haqqaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>99,'arabic_text'=>'۞ وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعٗا','transliteration'=>'Wa-taraknaa ba\'dahum Yawma\'izien yamooju fee ba\'dinw Wa-nufikha fis Soori fajama\'naahum jam\'aa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>100,'arabic_text'=>'وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا','transliteration'=>'Wa-\'aradnaa jahannama Yawma\'izil lilkaafireena \'ardaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>101,'arabic_text'=>'ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا','transliteration'=>'Allazeena kaanat a\'yunuhum fee ghitaaa\'in \'an zikree Wa-kaanoo la yastatee\'oona sam\'aa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>102,'arabic_text'=>'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا','transliteration'=>'Afahasibal lazeena kafarooo aien yattakhizoo \'ibaadee min dooneee awliyaaa\'; innaaa a\'tadnaa jahannama lil-kaafireena nuzulaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>103,'arabic_text'=>'قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا','transliteration'=>'Qul hal nunabbi\'ukum bilakhsareena a\'maalaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>104,'arabic_text'=>'ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا','transliteration'=>'Allazeena dalla sa\'yuhum fil hayaatid dunyaa Wa-hum yahsaboona annahum yuhsinoona sun\'aa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>105,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا','transliteration'=>'Ulaaa\'ikal lazeena kafaroo bi-aayaati Rabbihim Wa-liqaaa\'ihee fahabitat a\'maaluhum falaa nuqeemu lahum Yawmal Qiyaamati waznaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>106,'arabic_text'=>'ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا','transliteration'=>'Zaalika jazaaa\'uhum jahannamu bimaa kafaroo wattakhazooo Aayaatee Wa-Rusulee huzuwaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>107,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati kaanat lahum Jannaatul Firdawsi nuzulaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>108,'arabic_text'=>'خَٰلِدِينَ فِيهَا لَا يَبۡغُونَ عَنۡهَا حِوَلٗا','transliteration'=>'Khaalideena feeha la yabghoona \'anhaa hiwalaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>109,'arabic_text'=>'قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدٗا','transliteration'=>'Qul law kaanal bahru midaadal li-kalimaati Rabbee lanafidal bahru qabla an tanfada Kalimaatu Rabbee Wa-law ji\'naa bimislihee madadaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>18,'ayah_number'=>110,'arabic_text'=>'قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا','transliteration'=>'Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaa ilaahukum Ilaahunw Waahid; faman kaana yarjoo liqaaa\'a Rabbihee falya\'mal \'amalan saalihanw Wa-laa yushrik bi\'ibaadati Rabbiheee ahadaa','page_number'=>304,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            /* Surah 19: Mary (Maryam) */
            ['surah_id'=>19,'ayah_number'=>1,'arabic_text'=>'كٓهيعٓصٓ','transliteration'=>'Kaaaf-Haa-Yaa-\'Ayyyn-Saaad','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>2,'arabic_text'=>'ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ','transliteration'=>'Zikru rahmati Rabbika \'abdahoo Zakariyya','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>3,'arabic_text'=>'إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا','transliteration'=>'Iz naadaa Rabbahoo nidaaa\'an khafiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>4,'arabic_text'=>'قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا','transliteration'=>'Qaala Rabbi innee wahanal \'azmu minnee washta-\'alar ra\'su shaibanw Wa-lam akun bidu\'aaa\'ika Rabbi shaqiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>5,'arabic_text'=>'وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا','transliteration'=>'Wa-innee khiftul mawaaliya minw waraaa\'ee Wa-kaanat imra atee \'aqiran fa-hablee mil ladunka waliyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>6,'arabic_text'=>'يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا','transliteration'=>'Yarisunee Wa-yarisu min aali Ya\'qoob, waj\'alhu Rabbi radiyya','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>7,'arabic_text'=>'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا','transliteration'=>'Yaa-Zakariyyaaa innaa nubashshiruka bi-ghulaamin ismuhoo Yahyaa lam naj\'al lahoo min qablu samiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>8,'arabic_text'=>'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا','transliteration'=>'Qaala Rabbi annaa yakoonu lee ghulaamunw Wa-kaanat imra-atee \'aaqiranw Wa-qad balaghtu minal kibari \'itiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>9,'arabic_text'=>'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَيۡـٔٗا','transliteration'=>'Qaala kazaalika qaala Rabbuka huwa \'alaiya haiyinunw Wa-qad khalaqtuka min qablu Wa-lam taku shai\'aa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>10,'arabic_text'=>'قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا','transliteration'=>'Qaala Rabbij \'al leee Aayah; qaala Aayatuka allaa tukalliman naasa salaasa layaalin sawiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>11,'arabic_text'=>'فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا','transliteration'=>'Fakharaja \'alaa qawmihee minal mihraabi fa-awhaaa ilaihim an sabbihoo bukratanw Wa-\'ashiyyaa','page_number'=>305,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>12,'arabic_text'=>'يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا','transliteration'=>'Yaa-Yahyaa khuzil Kitaaba biquwwatinw Wa-aatainaahul hukma sabiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>13,'arabic_text'=>'وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا','transliteration'=>'Wa-hanaanam mil ladunnaa Wa-zakaatanw Wa-kaana taqiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>14,'arabic_text'=>'وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا','transliteration'=>'Wa-barram biwaalidayhi Wa-lam yakum jabbaaran \'asiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>15,'arabic_text'=>'وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا','transliteration'=>'Wa-salaamun \'alaihi yawma wulida Wa-yawma yamootu Wa-yawma yub\'asu haiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>16,'arabic_text'=>'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا','transliteration'=>'Wazkur fil Kitaabi Maryma; izin tabazat min ahlihaa makaanan sharqiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>17,'arabic_text'=>'فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا','transliteration'=>'Fattakhazat min doonihim hijaaban fa-arsalnaaa ilaihaa roohanaa fatamassala lahaa basharan sawiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>18,'arabic_text'=>'قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا','transliteration'=>'Qaalat inneee a\'oozu bir-Rahmaani minka in kunta taqiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>19,'arabic_text'=>'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا','transliteration'=>'Qaala innamaa ana rasoolu Rabbiki li-ahaba laki ghulaaman zakiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>20,'arabic_text'=>'قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا','transliteration'=>'Qaalat anna yakoonu lee ghulaamunw Wa-lam yamsasnee bashrunw Wa-lam aku baghiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>21,'arabic_text'=>'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا','transliteration'=>'Qaala kazaaliki qaala Rabbuki huwa \'alaiya haiyyimunw Wa-linaj-\'alahooo Aayatal linnaasi Wa-rahmatam minnaa; Wa-kaana amram maqdiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>22,'arabic_text'=>'۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا','transliteration'=>'Fahamalat-hu fantabazat bihee makaanan qasiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>23,'arabic_text'=>'فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا','transliteration'=>'Fa-ajaaa-\'ahal makhaadu ilaa jiz\'in nakhlati qaalat yaa-laitanee mittu qabla haazaa Wa-kuntu nasyam mansiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>24,'arabic_text'=>'فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا','transliteration'=>'Fanaadaahaa min tahtihaaa allaa tahzanee qad ja\'ala Rabbuki tahtaki sariyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>25,'arabic_text'=>'وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا','transliteration'=>'Wa-huzzeee ilaiki bijiz-\'in nakhlati tusaaqit \'alaiki rutaban janiyyaa','page_number'=>306,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>26,'arabic_text'=>'فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا','transliteration'=>'Fakulee washrabee Wa-qarree \'ainaa; fa-immaa tarayinnna minal bashari ahadan faqooleee innee nazartu lir-Rahmaani sawman falan ukallimal yawma insiyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>27,'arabic_text'=>'فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا','transliteration'=>'Fa-atat bihee qawmahaa tahmiluhoo qaaloo yaa-Maryamoo laqad ji\'ti shai\'an fariyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>28,'arabic_text'=>'يَٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا','transliteration'=>'Yaaa-ukhta Haaroona maa kaana abooki mra\'a saw\'inw Wa-maa kaanat ummuki baghiyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>29,'arabic_text'=>'فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا','transliteration'=>'Fa-ashaarat ilaih; qaaloo kaifa nukallimu man kaana fil mahdi sabiyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>30,'arabic_text'=>'قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا','transliteration'=>'Qaala innee \'abdul laahi aataaniyal Kitaaba Wa-ja\'alanee Nabiyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>31,'arabic_text'=>'وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا','transliteration'=>'Wa-ja\'alanee mubaarakan aina maa kuntu Wa-awsaanee bis-Salaati waz-Zakaati maa dumtu haiyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>32,'arabic_text'=>'وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا','transliteration'=>'Wa-barram biwaalidatee Wa-lam yaj\'alnee jabbaaran shaqiyyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>33,'arabic_text'=>'وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا','transliteration'=>'Wassalaamu \'alaiya yawma wulidtu Wa-yawma amootu Wa-yawma ub\'asu haiyaa','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>34,'arabic_text'=>'ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِي فِيهِ يَمۡتَرُونَ','transliteration'=>'Zaalika \'Eesab nu Maryama; qawlal haqqil lazee feehi yamtaroon','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>35,'arabic_text'=>'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Maa kaana lillaahi aien yattakhiza minw waladin Subhaanah; izaa qadaaa amran fa-innamaa yaqoolu lahoo kun fa-yakoon','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>36,'arabic_text'=>'وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ','transliteration'=>'Wa-innal laaha Rabbee Wa-Rabbukum fa\'budooh; haazaa Siraatum Mustaqeem','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>37,'arabic_text'=>'فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ','transliteration'=>'Fakhtalafal ahzaabu min bainihim fawailul lillazeena kafaroo min mashhadi Yawmin \'azeem','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>38,'arabic_text'=>'أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Asmi\' bihim Wa-absir Yawma ya\'toonanaa laakiniz zaalimoonal yawma fee dalaalin mubeen','page_number'=>307,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>39,'arabic_text'=>'وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Wa-anzirhum Yawmal hasrati iz qudiyal amr; Wa-hum fee ghaflatinw Wa-hum laa yu\'minoon','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>40,'arabic_text'=>'إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ','transliteration'=>'Innaa nahnu narisul arda Wa-man \'alaihaa Wa-ilainaa yurja\'oon','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>41,'arabic_text'=>'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا','transliteration'=>'Wazkur fil Kitaabi Ibraaheem; innahoo kaana siddeeqan Nabiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>42,'arabic_text'=>'إِذۡ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا','transliteration'=>'Iz qaala li-abeehi yaaa-abati lima ta\'budu maa laa yasma\'u Wa-laa yubsiru Wa-laa yughnee \'anka shai\'aa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>43,'arabic_text'=>'يَٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا','transliteration'=>'Yaaa-abati innee qad jaaa\'anee minal \'ilmi maa lam ya\'tika fattabi\'neee ahdika siraatan Sawiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>44,'arabic_text'=>'يَٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا','transliteration'=>'Yaaa-abati laa ta\'budish Shaitaan; innash Shaitaana kaana lir-Rahmaani \'asiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>45,'arabic_text'=>'يَٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا','transliteration'=>'Yaaa-abati innee akhaafu aien yamassaka \'azaabum minar Rahmaani fatakoona lish-Shaitaani waliyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>46,'arabic_text'=>'قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيّٗا','transliteration'=>'Qaala araaghibun anta \'an aalihatee yaaa-Ibraaheemu la-\'il lam tantahi la-arjumannaka wahjurnee maliyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>47,'arabic_text'=>'قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيّٗا','transliteration'=>'Qaala salaamun \'alaika sa-astaghfiru laka Rabbeee innahoo kaana bee hafiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>48,'arabic_text'=>'وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا','transliteration'=>'Wa-a\'tazilukum Wa-maa tad\'oona min doonil laahi Wa-ad\'oo Rabbee \'asaaa allaaa akoona bidu\'aaa\'i Rabbee shaqiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>49,'arabic_text'=>'فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا','transliteration'=>'Fa-lam ma\'tazalahum Wa-maa ya\'budoona min doonil laahi wahabnaa lahoo is-haaqa Wa-ya\'qoob; Wa-kullan ja\'alnaa Nabiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>50,'arabic_text'=>'وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيّٗا','transliteration'=>'Wa wahabnaa lahum mirrahmatinaa Wa-ja\'alnaa lahum lisaana sidqin \'aliyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>51,'arabic_text'=>'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا','transliteration'=>'Wazkur fil Kitaabi Moosaaa; innahoo kaana mukhlasanw Wa-kaana Rasoolan Nabiyyaa','page_number'=>308,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>52,'arabic_text'=>'وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيّٗا','transliteration'=>'Wa-naadainaahu min jaanibit Tooril aimani Wa-qarrabnaahu najiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>53,'arabic_text'=>'وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا','transliteration'=>'Wa-wahabnaa lahoo mir rahmatinaaa akhaahu Haaroona Nabiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>54,'arabic_text'=>'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا','transliteration'=>'Wazkur fil Kitaabi ismaa\'eel; innahoo kaana saadiqal wa\'di Wa-kaana Rasoolan Nabiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>55,'arabic_text'=>'وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا','transliteration'=>'Wa-kaana ya\'muru ahlahoo bis-Salaati waz-zakaati Wa-kaana \'inda Rabbihee mardiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>56,'arabic_text'=>'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا','transliteration'=>'Wazkur fil Kitaabi Idrees; innahoo kaana siddeeqan Nabiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>57,'arabic_text'=>'وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا','transliteration'=>'Wa-rafa\'naahu makaanan \'aliyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>58,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحٖ وَمِن ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا','transliteration'=>'Ulaaa\'ikal lazeena an\'amal laahu \'alaihim minan Nabiyyeena min zurriyyati Aadama Wa-mimman hamalnaa ma\'a Noohinw Wa-min zurriyyati Ibraaheema Wa-Israaa\'eela Wa-mimman hadainaa wajta-bainaaa; izaa tutlaa \'alaihim Aayaatur Rahmaani kharroo sujjadanw Wa-bukiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>true],
            ['surah_id'=>19,'ayah_number'=>59,'arabic_text'=>'۞ فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا','transliteration'=>'Fakhalafa min ba\'dihim khalfun adaa\'us Salaata wattaba\'ush shahawaati fasawfa yalqawna ghaiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>60,'arabic_text'=>'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ شَيۡـٔٗا','transliteration'=>'Illaa man taaba Wa-aamana Wa-\'amila saalihan fa-ulaaa\'ika yadkhuloonal jannata Wa-laa yuzlamoona shai\'aa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>61,'arabic_text'=>'جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ بِٱلۡغَيۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِيّٗا','transliteration'=>'Jannaati \'adninil latee wa\'adar Rahmaanu ibaadahoo bilghaib; innahoo kaana wa\'duhoo ma\'tiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>62,'arabic_text'=>'لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗاۖ وَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا','transliteration'=>'Laa yasma\'oona feehaa laghwan illaa salaamaa; Wa-lahum rizquhum feehaa bukratanw Wa-\'ashiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>63,'arabic_text'=>'تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِيّٗا','transliteration'=>'Tilkal jannatul latee noorisu min \'ibaadinaa man kaana taqiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>64,'arabic_text'=>'وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيّٗا','transliteration'=>'Wa-maa natanazzalu illaa bi-amri Rabbika lahoo maa baina aideenaa Wa-maa khalfanaa Wa-maa baina zaalik; Wa-maa kaana Rabbuka nasiyyaa','page_number'=>309,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>65,'arabic_text'=>'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا','transliteration'=>'Rabbus samaawaati wal-ardi Wa-maa bainahumaa fa\'bud-hu wastabir li\'ibaadatih; hal ta\'lamu lahoo samiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>66,'arabic_text'=>'وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا','transliteration'=>'Wa-yaqoolul insaanu \'a-izaa maa mittu lasawfa ukhraju haiyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>67,'arabic_text'=>'أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـٔٗا','transliteration'=>'A-Wa-laa yazkurul insaanu annaa khalaqnaahu min qablu Wa-lam yaku shai\'aa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>68,'arabic_text'=>'فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا','transliteration'=>'Fawa-Rabbika lanahshu-rannahum wash-shayaateena summa lanuhdirannahum hawla jahannama jisiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>69,'arabic_text'=>'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا','transliteration'=>'Summa lanan-zi\'anna min kulli shee\'atin aiyuhum ashaddu \'alar Rahmaani \'itiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>70,'arabic_text'=>'ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيّٗا','transliteration'=>'Summa lanahnu a\'lamu billazeena hum awlaa bihaa siliyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>71,'arabic_text'=>'وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا','transliteration'=>'Wa-in minkum illaa waariduhaa; kaana \'alaa Rabbika hatmam maqdiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>72,'arabic_text'=>'ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيّٗا','transliteration'=>'Summa nunajjil lazeenat taqaw Wa-nazaruz zaalimeena feehaa jisiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>73,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا','transliteration'=>'Wa-izaa tutlaa \'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lillazeena aamanooo aiyul fareeqaini khairum maqaamanw Wa-ahsanu nadiyyaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>74,'arabic_text'=>'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا','transliteration'=>'Wa-kam ahlaknaa qablahum min qarnin hum ahsanu asaasanw Wa-ri\'yaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>75,'arabic_text'=>'قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا','transliteration'=>'Qul man kaana fid da-laalati falyamdud lahur Rahmaanu maddaa; hattaaa izaa ra-aw maa yoo\'adoona immal \'azaaba Wa-immas Saa\'ata fasa-ya\'lamoona man huwa sharrum makaananw Wa-ad\'afu jundaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>76,'arabic_text'=>'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا','transliteration'=>'Wa-yazeedul laahul lazeenah tadaw hudaa; wal-baaqiyaatus saalihaatu khairun \'inda Rabbika sawaabanw Wa-khairum maraddaa','page_number'=>310,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>77,'arabic_text'=>'أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالٗا وَوَلَدًا','transliteration'=>'Afara\'aytal lazee kafara bi-Aayaatinaa Wa-qaala la-oota-yanna maalanw Wa-waladaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>78,'arabic_text'=>'أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا','transliteration'=>'At-tala\'al ghaiba \'amit takhaza \'indar Rahmaani \'ahdaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>79,'arabic_text'=>'كـَلَّاۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا','transliteration'=>'Kallaa; sanaktubu maa yaqoolu Wa-namuddu lahoo minal \'azaabi maddaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>80,'arabic_text'=>'وَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا','transliteration'=>'Wa-narisuhoo maa yaqoolu Wa-ya\'teenaa fardaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>81,'arabic_text'=>'وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا','transliteration'=>'Wattakhazoo min doonil laahi aalihatal liyakoonoo lahum \'izzaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>82,'arabic_text'=>'كـَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا','transliteration'=>'Kallaa; sa-yakfuroona bi\'ibaadatihim Wa-yakoonoona \'alaihim diddaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>83,'arabic_text'=>'أَلَمۡ تَرَ أَنَّآ أَرۡسَلۡنَا ٱلشَّيَٰطِينَ عَلَى ٱلۡكَٰفِرِينَ تَؤُزُّهُمۡ أَزّٗا','transliteration'=>'Alam tara annaaa arsalnash Shayaateena \'alal kaafireena ta\'uzzuhum azzaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>84,'arabic_text'=>'فَلَا تَعۡجَلۡ عَلَيۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدّٗا','transliteration'=>'Falaa ta\'jal alaihim innamaa na-\'uddu lahum \'addaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>85,'arabic_text'=>'يَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدٗا','transliteration'=>'Yawma nahshurul muttaqeena ilar Rahmaani wafdaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>86,'arabic_text'=>'وَنَسُوقُ ٱلۡمُجۡرِمِينَ إِلَىٰ جَهَنَّمَ وِرۡدٗا','transliteration'=>'Wa-nasooqul mujrimeena ilaa Jahannama wirdaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>87,'arabic_text'=>'لَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا','transliteration'=>'Laa yamlikoonash shafaa\'ata illaa manit takhaza \'indar Rahmaani \'ahdaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>88,'arabic_text'=>'وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗا','transliteration'=>'Wa-qaalut takhazar Rahmaanu waladaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>89,'arabic_text'=>'لَّقَدۡ جِئۡتُمۡ شَيۡـًٔا إِدّٗا','transliteration'=>'Laqad ji\'tum shai\'an iddaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>90,'arabic_text'=>'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا','transliteration'=>'Takaadus samaawaatu yatafattarna minhu Wa-tanshaq qul-ardu Wa-takhirrul jibaalu haddaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>91,'arabic_text'=>'أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا','transliteration'=>'An da\'aw lir-Rahmaani waladaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>92,'arabic_text'=>'وَمَا يَنۢبَغِي لِلرَّحۡمَٰنِ أَن يَتَّخِذَ وَلَدًا','transliteration'=>'Wa-maa yambaghee li-Rahmaani aien yattakhiza waladaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>93,'arabic_text'=>'إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا','transliteration'=>'In kullu man fis samaawaati wal-ardi illaaa aatir Rahmaani \'abdaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>94,'arabic_text'=>'لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدّٗا','transliteration'=>'Laqad ahsaahum Wa-addahum \'addaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>95,'arabic_text'=>'وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ ٱلۡقِيَٰمَةِ فَرۡدًا','transliteration'=>'Wa-kulluhum aateehi Yawmal Qiyaamati fardaa','page_number'=>311,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>96,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati sa-yaj\'alu lahumur Rahmaanu wuddaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>97,'arabic_text'=>'فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمٗا لُّدّٗا','transliteration'=>'Fa-innamaa yassarnaahu bilisaanika litubashshira bihil muttaqeena Wa-tunzira bihee qawmal luddaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            ['surah_id'=>19,'ayah_number'=>98,'arabic_text'=>'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا','transliteration'=>'Wa-kam ahlaknaa qabla-hum min qarnin hal tuhissu minhum min ahadin aw tasma\'u lahum rikzaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>31,'is_sajdah'=>false],
            /* Surah 20: Ta-Ha (Taha) */
            ['surah_id'=>20,'ayah_number'=>1,'arabic_text'=>'طه','transliteration'=>'Taa-Haa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>2,'arabic_text'=>'مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ','transliteration'=>'Maaa anzalnaa \'alaikal Qur-aana litashqaaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>3,'arabic_text'=>'إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ','transliteration'=>'Illaa tazkiratal limany yakhshaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>4,'arabic_text'=>'تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى','transliteration'=>'Tanzeelan mimman khalaqal arda was-samaawaatil \'ulaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>5,'arabic_text'=>'ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ','transliteration'=>'Ar-Rahmaanu \'alal \'Arshis tawaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>6,'arabic_text'=>'لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ','transliteration'=>'Lahoo maa fis samaawaati Wa-maa fil ardi Wa-maa bainahumaa Wa-maa tahtas saraa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>7,'arabic_text'=>'وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى','transliteration'=>'Wa-in tajhar bilqawli fainnahoo ya\'lamus sirra Wa-akhfaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>8,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ','transliteration'=>'Allaahu laaa ilaaha illaa huwa lahul asmaa\'ul husnaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>9,'arabic_text'=>'وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ','transliteration'=>'Wa-hal ataaka hadeesu Moosa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>10,'arabic_text'=>'إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى','transliteration'=>'Iz ra-aa naaran faqaala li-ahlihim kusooo inneee aanastu naaral la\'alleee aateekum minhaa biqabasin aw ajidu \'alan naari hudaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>11,'arabic_text'=>'فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ','transliteration'=>'Falammaaa ataahaa noodiya yaa-Moosaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>12,'arabic_text'=>'إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى','transliteration'=>'Inneee Ana Rabbuka fakhla\' na\'laika innaka bilwaadil muqaddasi Tuwaa','page_number'=>312,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>13,'arabic_text'=>'وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ','transliteration'=>'Wa anakhtartuka fastami\' limaa yoohaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>14,'arabic_text'=>'إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ','transliteration'=>'Innaneee Anal laahu laaa ilaaha illaa Ana fa\'budnee Wa-aqimis salaata lizikree','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>15,'arabic_text'=>'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ','transliteration'=>'Innas Saa\'ata aatiyatun akaadu ukhfeehaa litujzaa kullu nafsin bimaa tas\'aa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>16,'arabic_text'=>'فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ','transliteration'=>'Falaa yasuddannaka \'anhaa mal laa yu\'minu bihaa wattaba\'a hawaahu fatardaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>17,'arabic_text'=>'وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ','transliteration'=>'Wa-maa tilka bi-yamee-nika yaa-Moosaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>18,'arabic_text'=>'قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ','transliteration'=>'Qaala hiya \'asaaya atawakka\'u alaihaa Wa-ahushshu bihaa \'alaa ghanamee Wa-liya feehaa ma-aaribu ukhraa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>19,'arabic_text'=>'قَالَ أَلۡقِهَا يَٰمُوسَىٰ','transliteration'=>'Qaala alqihaa yaa-Moosaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>20,'arabic_text'=>'فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ','transliteration'=>'Fa-alqaahaa fa-izaa hiya haiyatun tas\'aa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>21,'arabic_text'=>'قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ','transliteration'=>'Qaala khuzhaa Wa-laa ta-khaf sanu\'eeduhaa seeratahal oolaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>22,'arabic_text'=>'وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ','transliteration'=>'Wadmum yadaka ilaa janaahika takhruj baidaaa\'a min ghairi sooo\'in Aayatan ukhraa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>23,'arabic_text'=>'لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى','transliteration'=>'Linuriyaka min Aayaatinal Kubra','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>24,'arabic_text'=>'ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ','transliteration'=>'Izhab ilaa Fir\'awna innahoo taghaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>25,'arabic_text'=>'قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي','transliteration'=>'Qaala Rabbish rah lee sadree','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>26,'arabic_text'=>'وَيَسِّرۡ لِيٓ أَمۡرِي','transliteration'=>'Wa-yassir leee amree','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>27,'arabic_text'=>'وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي','transliteration'=>'Wahlul \'uqdatan milli saanee','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>28,'arabic_text'=>'يَفۡقَهُواْ قَوۡلِي','transliteration'=>'Yafqahoo qawlee','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>29,'arabic_text'=>'وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي','transliteration'=>'Waj\'al lee wazeeran min ahlee','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>30,'arabic_text'=>'هَٰرُونَ أَخِي','transliteration'=>'Haaroona akhee','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>31,'arabic_text'=>'ٱشۡدُدۡ بِهِۦٓ أَزۡرِي','transliteration'=>'Ushdud biheee azree','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>32,'arabic_text'=>'وَأَشۡرِكۡهُ فِيٓ أَمۡرِي','transliteration'=>'Wa-ashrik-hu feee amree','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>33,'arabic_text'=>'كَيۡ نُسَبِّحَكَ كَثِيرٗا','transliteration'=>'Kai nusabbihaka kaseeraa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>34,'arabic_text'=>'وَنَذۡكُرَكَ كَثِيرًا','transliteration'=>'Wa-nazkuraka kaseeraa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>35,'arabic_text'=>'إِنَّكَ كُنتَ بِنَا بَصِيرٗا','transliteration'=>'Innaka kunta binaa baseeraa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>36,'arabic_text'=>'قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ','transliteration'=>'Qaala qad ooteeta su\'laka yaa-Moosaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>37,'arabic_text'=>'وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ','transliteration'=>'Wa-laqad manannaa \'alaika marratan ukhraaa','page_number'=>313,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>38,'arabic_text'=>'إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ','transliteration'=>'Iz awhainaaa ilaaa ummika maa yoohaaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>39,'arabic_text'=>'أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ','transliteration'=>'Ani qzifeehi fit Taabooti fa-qzifeehi fil yammi fal-yul-qihil yammu bis-saahili ya\'khuzhu \'aduwwul lee Wa-\'aduwwul lah; Wa-alqaitu \'alaika mahabbatan minnee Wa-litusna\'a \'alaa \'ainee','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>40,'arabic_text'=>'إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ','transliteration'=>'Iz tamsheee ukhtuka fataqoolu hal adullukum \'alaa maien yakfuluhoo faraja-\'naaka ilaaa ummika kai taqarra \'ainuhaa Wa-laa tahzan; Wa-qatalta nafsan fanajjainaaka minal ghammi Wa-fatannaaka futoonaa; falabista sineena feee ahli Madyana summa ji\'ta \'alaa qadarien yaa-Moosa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>41,'arabic_text'=>'وَٱصۡطَنَعۡتُكَ لِنَفۡسِي','transliteration'=>'Wastana\'-tuka linafsee','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>42,'arabic_text'=>'ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي','transliteration'=>'Izhab anta Wa-akhooka bi-Aayaatee Wa-laa taniyaa fee zikree','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>43,'arabic_text'=>'ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ','transliteration'=>'Izhabaaa ilaa Fir\'awna innahoo taghaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>44,'arabic_text'=>'فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ','transliteration'=>'Faqoolaa lahoo qawlal laiyinal la-allahoo yatazakkkaru \'aw yakhshaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>45,'arabic_text'=>'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ','transliteration'=>'Qaalaa Rabbanaaa innanaa nakhaafu aien yafruta \'alainaaa aw ai yatghaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>46,'arabic_text'=>'قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ','transliteration'=>'Qaala laa takhaafaaa innanee ma\'akumaa asma\'u Wa-araa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>47,'arabic_text'=>'فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ','transliteration'=>'Faatiyaahu faqoolaaa innaa Rasoolaa Rabbika fa-arsil ma\'anaa Banee Israaa\'eela Wa-laa tu\'azzibhum qad ji\'naaka bi-Aayatim mir Rabbika wassa-laamu \'alaa manit taba\'al hudaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>48,'arabic_text'=>'إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ','transliteration'=>'Innaa qad oohiya ilainaaa annnal \'azaaba \'alaa man kaz-zaba Wa-tawalla','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>49,'arabic_text'=>'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ','transliteration'=>'Qaala famar Rabbu-kumaa yaa-Moosa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>50,'arabic_text'=>'قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ','transliteration'=>'Qaala Rabbunal lazeee a\'taa kulla shai\'in khalqahoo summa hadaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>51,'arabic_text'=>'قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ','transliteration'=>'Qaala famaa baalul quroonil oolaa','page_number'=>314,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>52,'arabic_text'=>'قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى','transliteration'=>'Qaala \'ilmuhaa \'inda Rabee fee kitaab, laa yadillu Rabbee Wa-laa yansaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>53,'arabic_text'=>'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ','transliteration'=>'Allazee ja\'ala lakumul arda mahdanw Wa-salaka lakum feehaa subulanw Wa-anzala minas samaaa\'i maaa\'an fa-akhrajnaa biheee azwaajam min nabaatin shatta','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>54,'arabic_text'=>'كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ','transliteration'=>'Kuloo war\'aw an\'aamakum; inna fee zaalika la-Aayaatil li-ulin nuhaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>55,'arabic_text'=>'۞ مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ','transliteration'=>'Minhaa khalaqnaakum Wa-feehaa nu\'eedukum Wa-minhaa nukhrijukum taaratan ukhraa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>56,'arabic_text'=>'وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ','transliteration'=>'Wa-laqad arainaahu Aayaatinaa kullahaa fakaz-zaba Wa-abaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>57,'arabic_text'=>'قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ','transliteration'=>'Qaala aji\'tanaa litukhri-janaa min ardinaa bisihrika yaa-Moosa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>58,'arabic_text'=>'فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى','transliteration'=>'Falanaatiyannaka bisihrim mislihee faj\'al bainanaa Wa-bainaka maw\'idal laa nukhlifuhoo nahnu Wa-laaa anta makaanan suwaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>59,'arabic_text'=>'قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى','transliteration'=>'Qaala maw\'idukum yawmuz zeenati Wa-ai yuhsharan naasu duhaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>60,'arabic_text'=>'فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ','transliteration'=>'Fatawallaa Fir\'awnu fajjama\'a kaidahoo summa ataa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>61,'arabic_text'=>'قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ','transliteration'=>'Qaala lahum Moosaa wailakum laa taftaroo \'alal laahi kaziban fa-yus-hitakum bi-\'azaab, Wa-qad khaaba manif taraa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>62,'arabic_text'=>'فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ','transliteration'=>'Fatanaaza\'ooo amrahum bainahum Wa-asarrun najwaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>63,'arabic_text'=>'قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ','transliteration'=>'Qaalooo in haaazaani lasaahiraani yureedaani aien yukhrijaakum min ardikum bisihrihimaa Wa-yazhabaa bitareeqatikumul muslaa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>64,'arabic_text'=>'فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ','transliteration'=>'Fa-ajmi\'oo kaidakum summa\' too saffaa; Wa-qad aflahal yawma manis ta\'laa','page_number'=>315,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>65,'arabic_text'=>'قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ','transliteration'=>'Qaaloo yaa-Moosaaa immaaa an tulqiya Wa-immaaa an nakoona awala man alqaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>66,'arabic_text'=>'قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ','transliteration'=>'Qaala bal alqoo fa-izaa hibaaluhum Wa-\'isiyyuhum yukhaiyalu ilaihi min sihrihim annahaa tas\'aa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>67,'arabic_text'=>'فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ','transliteration'=>'Fa-awjasa fee nafsihee kheefatam Moosa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>68,'arabic_text'=>'قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ','transliteration'=>'Qulnaa laa takhaf innaka antal a\'laa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>69,'arabic_text'=>'وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ','transliteration'=>'Wa-alqi maa fee yamee-nika talqaf maa sana\'oo; innamaa sana\'oo kaidu saahir; Wa-laa yuflihus saahiru haisu ataa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>70,'arabic_text'=>'فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ','transliteration'=>'Fa-ulqiyas saharatu sujjadan qaalooo aamannaa bi-Rabbi Haaroona Wa-Moosa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>71,'arabic_text'=>'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ','transliteration'=>'Qaala aamantum lahoo qabla an aazana lakum; innahoo lakabeerukumul lazee \'allama-kumus sihra fala-uqatti\'anna aidiyakum Wa-arjulakum min khilaafinw Wa-la-usallibannakum fee juzoo\'in nakhli Wa-lata\'lamunna aiyunaaa ashaddu \'azaabanw Wa-abqaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>72,'arabic_text'=>'قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ','transliteration'=>'Qaaloo lan nu\'siraka \'alaa maa jaaa\'anaa minal baiyinaati wallazee fataranaa faqdi maaa anta qaad; innamaa taqdee haazihil hayaatad dunyaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>73,'arabic_text'=>'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ','transliteration'=>'Innaaa aamannaa bi-Rabbinaa liyaghfira lanaa khataayaanaa Wa-maaa akrahtanaa \'alaihi minas sihr; wallaahu khairunw Wa-abqaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>74,'arabic_text'=>'إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ','transliteration'=>'Innahoo mai ya\'ti Rabbahoo mujriman fa-inna lahoo Jahannama laa yamootu feehaa Wa-laa yahyaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>75,'arabic_text'=>'وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ','transliteration'=>'Wa-main ya\'tihee mu\'minan qad \'amilas saalihaati fa-ulaaa\'ika lahumud darajaatul \'ulaa','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>76,'arabic_text'=>'جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ','transliteration'=>'Jannaatu \'Adnin tajree min tahtihal anhaaru khaalideena feehaa; Wa-zaalika jazaaa\'u man tazakka','page_number'=>316,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>77,'arabic_text'=>'وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ','transliteration'=>'Wa-laqad awhainaaa ilaa Moosaaa an asri bi\'ibaadee fadrib lahum tareeqan fil bahri yabasal laa takhaafu darakanw Wa-laa takhshaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>78,'arabic_text'=>'فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ','transliteration'=>'Fa-atba\'ahum Fir\'awnu bijunoodihee faghashiyahum minal yammmi maa ghashi-yahum','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>79,'arabic_text'=>'وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ','transliteration'=>'wa-adalla fir\'awnu qawmahoo Wa-maa hadaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>80,'arabic_text'=>'يَٰبَنِيٓ إِسۡرَٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ','transliteration'=>'Yaa-Baneee Israaa\'eela qad anjainaakum min \'aduw-wikum Wa-wa\'adnaakum jaanibat Tooril aimana Wa-nazzalnaa \'alaikumul Manna was-Salwaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>81,'arabic_text'=>'كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ','transliteration'=>'Kuloo min taiyibaati maa razaqnaakum Wa-laa tatghaw feehi fa-yahilla \'alaikum ghadabee Wa-mai yahlil \'alaihi ghadabee faqad hawaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>82,'arabic_text'=>'وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ','transliteration'=>'Wa-innee la-Ghaffaarul liman taaba Wa-aamana Wa-\'amila saalihan summah tadaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>83,'arabic_text'=>'۞ وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ','transliteration'=>'Wa-maaa a\'jalaka \'an qawmika yaa-Moosa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>84,'arabic_text'=>'قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ','transliteration'=>'Qaala hum ulaaa\'i \'alaaa asaree Wa-\'ajiltu ilaika Rabbi litardaa','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>85,'arabic_text'=>'قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ','transliteration'=>'Qaala fa-innaa qad fatannaa qawmaka mim ba\'dika Wa-adallahumus Saamiriyy','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>86,'arabic_text'=>'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي','transliteration'=>'Faraja\'a Moosaaa ilaa qawmihee ghadbaana asifaa; qaala yaa-qawmi alam ya\'idkum Rabbukum wa\'dan hasanaa; afataala \'alaikumul \'ahdu am arattum ai yahilla \'alaikum ghadabum mir Rabbikum fa-akhlaftum maw\'idee','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>87,'arabic_text'=>'قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ','transliteration'=>'Qaaloo maaa akhlafnaa maw\'idaka bimalkinna Wa-laakinna hummilnaaa awzaaram min zeenatil qawmi faqazafnaahaa fakazaalika alqas Saamiriyy','page_number'=>317,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>88,'arabic_text'=>'فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ','transliteration'=>'Fa-akhraja lahum \'ijlan jasadal lahoo khuwaarun faqaaloo haazaaa ilaahukum Wa-ilaahu Moosaa fanasee','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>89,'arabic_text'=>'أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا','transliteration'=>'Afalaa yarawna allaa yarji\'u ilaihim qawlanw Wa-laa yamliku lahum darranw Wa-laa naf\'aa','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>90,'arabic_text'=>'وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي','transliteration'=>'Wa-laqad qaala lahum Haaroonu min qablu yaa-qawmi innamaa futintum bihee Wa-inna Rabbakumur Rahmaanu fattabi\'oonee Wa-atee\'ooo amree','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>91,'arabic_text'=>'قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ','transliteration'=>'Qaaloo lan nabraha \'alaihi \'aakifeena hattaa yarji\'a ilainaa Moosaa','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>92,'arabic_text'=>'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ','transliteration'=>'Qaala Yaa-Haaroonu maa mana-\'aka iz ra-aitahum dallooo','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>93,'arabic_text'=>'أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي','transliteration'=>'Allaa tattabi\'ani afa\'asaita amree','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>94,'arabic_text'=>'قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي','transliteration'=>'Qaala yabna\'umma laa ta\'khuz bi-lihyatee Wa-laa bi-ra\'see innee khasheetu an taqoola farraqta baina Baneee Israaa\'eela Wa-lam tarqub qawlee','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>95,'arabic_text'=>'قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ','transliteration'=>'Qaala famaa khatbuka yaa-Saamiriyy','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>96,'arabic_text'=>'قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي','transliteration'=>'Qaala basurtu bimaa lam yabsuroo bihee faqabadtu qabdatam min asarir Rasooli fanabaztuhaa Wa-kazaalika sawwalat lee nafsee','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>97,'arabic_text'=>'قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا','transliteration'=>'Qaala fazhab fa-inna laka fil hayaati an taqoola laa misaasa Wa-inna laka maw\'idal lan tukhlafahoo wanzur ilaaa ilaahikal lazee zalta \'alaihi \'aakifaa; la-nuharriqannahoo thumma la-nansifannahoo fil yammi nasfaa','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>98,'arabic_text'=>'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا','transliteration'=>'Innamaaa ilaahu-kumul laahul lazee laa ilaaha illaa Hoo; wasi\'a kulla shai\'in ilmaa','page_number'=>318,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>99,'arabic_text'=>'كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا','transliteration'=>'Kazaalika naqussu \'alaika min anbaaa\'i maa qad sabaq; Wa-qad aatainaaka mil ladunnaa Zikraa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>100,'arabic_text'=>'مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا','transliteration'=>'Man a\'rada \'anhu, fa-innahoo yahmilu Yawmal Qiyaamati wizraa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>101,'arabic_text'=>'خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا','transliteration'=>'Khaalideena feehi Wa-saaa\'a lahum Yawmal Qiyaamati himlaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>102,'arabic_text'=>'يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا','transliteration'=>'Yawma yunfakhu fissoori Wa-nahshurul mujrimeena Yawma \'izin zurqaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>103,'arabic_text'=>'يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا','transliteration'=>'Yatakhaafatoona bainahum il labistum illaa \'ashraa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>104,'arabic_text'=>'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا','transliteration'=>'nahnu a\'lamu bimaa yaqooloona iz yaqoolu amsaluhum tareeqatan il labistum illaa yawmaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>105,'arabic_text'=>'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا','transliteration'=>'Wa-yas\'aloonaka \'anil jibaali faqul yansifuhaa Rabbee nasfaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>106,'arabic_text'=>'فَيَذَرُهَا قَاعٗا صَفۡصَفٗا','transliteration'=>'Fa-yazaruhaa qaa\'an safsafaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>107,'arabic_text'=>'لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا','transliteration'=>'Laa taraa feehaa \'iwajanw Wa-laaa amtaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>108,'arabic_text'=>'يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا','transliteration'=>'Yawma-izien yattabi\'oonad daa\'iya laa \'iwaja lahoo Wa-khasha\'atil aswaatu lir-Rahmaani falaa tasma\'u illaa hamsaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>109,'arabic_text'=>'يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا','transliteration'=>'Yawma-\'izil laa tanfa\'ush shafaa\'atu illaa man azina lahur Rahmaanu Wa-radiya lahoo qawlaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>110,'arabic_text'=>'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا','transliteration'=>'Ya\'lamu maa bainaa aideehim Wa-maa khalfahum Wa-laa yuheetoona bihee \'ilmaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>111,'arabic_text'=>'۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا','transliteration'=>'Wa-\'anatil wujoohu lil-Haiiyil Qaiyoomi Wa-qad khaaba man hamala zulmaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>112,'arabic_text'=>'وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا','transliteration'=>'Wa-main ya\'mal minas saalihaati Wa-huwa mu\'minun falaa yakhaafu zulmanw Wa-laa hadmaa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>113,'arabic_text'=>'وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا','transliteration'=>'Wa-kazaalika anzalnaahu Qur-aanan \'Arabiyyanw Wa-sarrafnaa fee-hi minal wa\'eedi la\'allahum yattaqoona aw yuhdisu lahum zikraa','page_number'=>319,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>114,'arabic_text'=>'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا','transliteration'=>'Fata\'aalal laahul Malikul Haqq; Wa-laa ta\'jal bil-Quraani min qabli aien yuqdaaa ilaika wahyuhoo Wa-qur Rabbi zidnee \'ilmaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>115,'arabic_text'=>'وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا','transliteration'=>'Wa-laqad \'ahidnaaa ilaaa Aadama min qablu fanasiya Wa-lam najid lahoo \'azmaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>116,'arabic_text'=>'وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ','transliteration'=>'Wa-iz qulnaa lilma-laaa\'ikatis judoo li-Aadama fasajadooo illaaa Ibleesa; abaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>117,'arabic_text'=>'فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ','transliteration'=>'Faqulnaa yaaa-Aadamu inna haazaa \'aduwwul laka Wa-lizawjika falaa yukhrijan-nakumaa minal Jannati fatashqaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>118,'arabic_text'=>'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ','transliteration'=>'Innaa laka allaa tajoo\'a feeha Wa-laa ta\'raa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>119,'arabic_text'=>'وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ','transliteration'=>'Wa-annaka laa tazma\'u feehaa Wa-laa tadhaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>120,'arabic_text'=>'فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ','transliteration'=>'Fa-waswasa ilaihish Shaitaanu qaala yaaa-Aadamu hal adulluka \'alaa shajaratil khuldi Wa-mulkil laa yablaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>121,'arabic_text'=>'فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ','transliteration'=>'Fa-akalaa minhaa fabadat lahumaa saw-aatuhumaa Wa-tafiqaa yakhsifaani \'alaihimaa minw waraqil jannah; Wa-\'asaaa Aadamu Rabbahoo faghawaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>122,'arabic_text'=>'ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ','transliteration'=>'Summaj tabbahu Rabbuhoo fataaba \'alaihi Wa-hadaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>123,'arabic_text'=>'قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ','transliteration'=>'Qaalah bita minhaa jamee\'am ba\'dukum liba\'din \'aduww; fa-immaa ya\'tiyannakum minnee hudan famanit taba\'a hudaaya falaa yadillu Wa-laa yashqaa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>124,'arabic_text'=>'وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ','transliteration'=>'Wa-man a\'rada \'an Zikree fa-inna lahoo ma\'eeshatan dankanw Wa-nahshuruhoo Yawmal Qiyaamati a\'maa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>125,'arabic_text'=>'قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا','transliteration'=>'Qaala Rabbi lima hashar-tanee a\'maa Wa-qad kuntu baseeraa','page_number'=>320,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>126,'arabic_text'=>'قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ','transliteration'=>'Qaala kazaalika atatka Aayaatunaa fanaseetahaa Wa-kazaalikal Yawma tunsaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>127,'arabic_text'=>'وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ','transliteration'=>'Wa-kazaalika najzee man asrafa Wa-lam yu\'min bi-Aayaati Rabbih; Wa-la\'azaabul Aakhirati ashaddu Wa-abqaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>128,'arabic_text'=>'أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ','transliteration'=>'Afalam yahdi lahum kam ahlaknaa qablahum minal qurooni yamshoona fee masaakinihim; inna fee zaalika la-Aayaatil li-ulin nuhaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>129,'arabic_text'=>'وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى','transliteration'=>'Wa-law-laa Kalimatun sabaqat mir Rabbika lakaana lizaamanw Wa-\'ajalun musammaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>130,'arabic_text'=>'فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ','transliteration'=>'Fasbir \'alaa maa yaqooloona Wa-sabbih bihamdi Rabbika qabla tuloo\'ish shamsi Wa-qabla ghuroobihaa Wa-min aanaaa\'il laili fasabbih Wa-atraafan nahaari la-\'allaka tardaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>131,'arabic_text'=>'وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ','transliteration'=>'Wa-laa tamuddanna \'ainaika ilaa ma matta\'na biheee azwajam minhum zahratal hayaatid dunya linaftinahum feeh; Wa-rizqu Rabbika khairunw Wa-abqaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>132,'arabic_text'=>'وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ','transliteration'=>'Wa\'mur ahlaka bis-Salaati wastabir \'alaihaa laa nas\'aluka rizqaa; nahnu narzuquk; wal-\'aaqibatu littaqwaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>133,'arabic_text'=>'وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ','transliteration'=>'Wa-qaaloo law-laa ya\'teenaa bi-aayatin mir Rabbih; awa-lam ta\'tihim baiyyinatu maa fis suhufil oolaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>134,'arabic_text'=>'وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ','transliteration'=>'Wa-law annaaa ahlaknaahum bi-\'azaabin min qablihee laqaaloo Rabbanaa law-laaa arsalta ilainaa Rasoolan fanattabi\'a Aayaatika min qabli an nazilla Wa-nakhzaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            ['surah_id'=>20,'ayah_number'=>135,'arabic_text'=>'قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ','transliteration'=>'Qul kullum mutarabbisun fa-tarabbasoo fa-sa-ta\'lamoona man Ashaabus Siraatis Sawiyyi Wa-manih tadaa','page_number'=>321,'juz_number'=>16,'hizb_number'=>32,'is_sajdah'=>false],
            /* Surah 21: The Prophets (Al-Anbya) */
            ['surah_id'=>21,'ayah_number'=>1,'arabic_text'=>'ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ','transliteration'=>'Iqtaraba linnaasi hisaabuhum Wa-hum fee ghaflatim mu\'ridoon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>2,'arabic_text'=>'مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ','transliteration'=>'Maa ya\'teehim min zikrim mir Rabbihim muhdasin illas tama\'oohu Wa-hum yal\'aboon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>3,'arabic_text'=>'لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ','transliteration'=>'Laahiyatan quloobuhum; Wa-asarrun najwal lazeena zalamoo hal haazaaa illaa basharum mislukum \'afa-ta\'toonas sihra Wa-antum tubsiroon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>4,'arabic_text'=>'قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Qaala Rabbee ya\'lamul qawla fis samaaa\'i wal-ardi Wa-Huwas Samee\'ul \'Aleem','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>5,'arabic_text'=>'بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ','transliteration'=>'Bal qaalooo adghaasu ahlaamin bal iftaraahu bal huwa shaa\'irun fal-ya\'tinaa bi-Aayatin kamaa ursilal awwaloon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>6,'arabic_text'=>'مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ','transliteration'=>'Maaa aaamanat qablahum min qaryatin ahlaknaahaa a-fahum yu\'minoon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>7,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Wa-maaa arsalnaa qablaka illaa rijaalan nooheee ilaihim fas\'aloo ahlaz zikri in kuntum laa ta\'lamoon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>8,'arabic_text'=>'وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ','transliteration'=>'Wa-maa ja\'alnaahum jasadal laa ya\'kuloonat ta\'aama Wa-maa kaanoo khaalideen','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>9,'arabic_text'=>'ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ','transliteration'=>'Summa sadaqnaa-humul wa\'da fa-anjainaahum Wa-man nashaaa\'u Wa-ahlaknal musrifeen','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>10,'arabic_text'=>'لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Laqad anzalnaaa ilaikum Kitaaban feehi zikrukum afalaa ta\'qiloon','page_number'=>322,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>11,'arabic_text'=>'وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ','transliteration'=>'Wa-kam qasamnaa min qaryatin kaanat zaalimatanw Wa-ansha\'-naa ba\'dahaa qawman aakhareen','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>12,'arabic_text'=>'فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ','transliteration'=>'Falammaaa ahassoo ba\'sanaaa izaa hum minhaa yarkudoon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>13,'arabic_text'=>'لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ','transliteration'=>'Laa tarkudoo warji\'ooo ilaa maaa utriftum feehi Wa-masaakinikum la\'allakum tus\'aloon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>14,'arabic_text'=>'قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ','transliteration'=>'Qaaloo yaa-wailanaaa innaa kunnaa zaalimeen','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>15,'arabic_text'=>'فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ','transliteration'=>'Famaa zaalat tilka da\'waahum hattaa ja\'alnaahum haseedan khaamideen','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>16,'arabic_text'=>'وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ','transliteration'=>'Wa-maa khalaqnas samaaa\'a wal-arda Wa-maa bainahumaa laa\'ibeen','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>17,'arabic_text'=>'لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ','transliteration'=>'Law aradnaaa an nattakhiza lahwal lat-takhaznaahu mil ladunnaaa in kunnaa faa\'ileen','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>18,'arabic_text'=>'بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ','transliteration'=>'Bal naqzifu bilhaqqi \'alal baatili fa-yadmaghuhoo fa-izaa huwa zaahiq; Wa-lakumul wailu mimmaa tasifoon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>19,'arabic_text'=>'وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ','transliteration'=>'Wa-lahoo man fis samaawaati wal-ard; Wa-man \'indahoo laa yastakbiroona \'an \'ibaada-tihee Wa-laa yastahsiroon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>20,'arabic_text'=>'يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ','transliteration'=>'Yusabbihoona laila wannahaara laa yafturoon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>21,'arabic_text'=>'أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ','transliteration'=>'Amit takhazooo aalihatam minal ardi hum yunshiroon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>22,'arabic_text'=>'لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ','transliteration'=>'Law kaana feehimaaa aalihatun illal laahu lafasadataa; fa-Subhaanal laahi Rabbil \'Arshi \'ammaa yasifoon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>23,'arabic_text'=>'لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ','transliteration'=>'Laa yus\'alu \'ammaa yaf\'alu Wa-hum yus\'aloon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>24,'arabic_text'=>'أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ','transliteration'=>'Amit takhazoo min doonihee aalihatan qul haatoo burhaanakum haaza zikru mam ma\'iya Wa-zikru man qablee; bal aksaruhum laa ya\'lamoonal haqqa fahum mu\'ridoon','page_number'=>323,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>25,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ','transliteration'=>'Wa-maaa arsalnaa min qablika mir Rasoolin illaa nooheee ilaihi annahoo laaa ilaaha illaaa Ana fa\'budoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>26,'arabic_text'=>'وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ','transliteration'=>'Wa-qaalut takhazar Rahmaanu waladaa; Subhaanahu bal \'ibaadum mukramoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>27,'arabic_text'=>'لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ','transliteration'=>'Laa yasbiqoonahoo bil-qawli Wa-hum bi-amrihee ya\'maloon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>28,'arabic_text'=>'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ','transliteration'=>'Ya\'lamu maa baina aideehim Wa-maa khalfahum Wa-laa yashfa\'oona illaa limanir tadaa Wa-hum min khash-yatihee mushfiqoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>29,'arabic_text'=>'۞ وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ','transliteration'=>'Wa-main yaqul minhum inneee ilaahum min doonihee fazaalika najzeehi Jahannam; kazaalika najziz zaalimeen','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>30,'arabic_text'=>'أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ','transliteration'=>'Awalam yaral lazeena kafarooo annas samaawaati wal-arda kaanataa ratqan fafataqnaa-humaa Wa-ja\'alnaa minal maaa\'i kulla shai\'in haiyin afalaa yu\'minoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>31,'arabic_text'=>'وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ','transliteration'=>'Wa-ja\'alnaa fil ardi rawaasiya an tameeda bihim Wa-ja\'alnaa feehaa fijaajan subulal la\'allahum yahtadoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>32,'arabic_text'=>'وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ','transliteration'=>'Wa-ja\'alnas samaaa\'a saqfam mahfoozanw Wa-hum \'an Aayaatihaa mu\'ridoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>33,'arabic_text'=>'وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ','transliteration'=>'Wa-Huwal lazee khalaqal laila wannahaara washshamsa wal-qamara kullun fee falakiny yasbahoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>34,'arabic_text'=>'وَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ','transliteration'=>'Wa-maa ja\'alnaa libasharim min qablikal khuld; afa immitta fahumul khaalidoon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>35,'arabic_text'=>'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ','transliteration'=>'Kullu nafsin zaaa\'iqatul mawt; Wa-nablookum bi-sharri walkhairi fitnatanw Wa-ilainaa turja\'oon','page_number'=>324,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>36,'arabic_text'=>'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ','transliteration'=>'Wa-izaa ra-aakal lazeena kafarooo ien yattakhizoonaka illa huzuwan; ahaazal lazee yazkuru aalihatakum Wa-hum bi-zikrir Rahmaani hum kaafiroon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>37,'arabic_text'=>'خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ','transliteration'=>'Khuliqal insaanu min \'ajal; sa-ureekum Aayaatee falaa tasta\'jiloon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>38,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>39,'arabic_text'=>'لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Law ya\'lamul lazeena kafaroo heena laa yakuffoona \'anw wujoohihimun Naara Wa-laa \'an zuhoorihim Wa-laa hum yunsaroon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>40,'arabic_text'=>'بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ','transliteration'=>'Bal ta\'teehim baghtatan fatabhatuhum falaa yastatee\'oona raddahaa Wa-laa hum yunzaroon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>41,'arabic_text'=>'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-laqadis tuhzi\'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi\'oon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>42,'arabic_text'=>'قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ','transliteration'=>'Qul main yakla-\'ukum billaili wannahaari minar Rahmaan; bal hum \'an zikri Rabbihim mu\'ridoon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>43,'arabic_text'=>'أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ','transliteration'=>'Am lahum aalihatun tamna\'uhum min dooninaa; laa yastatee\'oona nasra anfusihim Wa-laa hum minna yus-haboon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>44,'arabic_text'=>'بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ','transliteration'=>'Bal matta\'naa haaa\'ulaaa\'i Wa-aabaaa\'ahum hattaa taala \'alaihimul \'umur; afalaa yarawna anna na\'til arda nanqusuhaa min atraafihaa; afahumul ghaaliboon','page_number'=>325,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>45,'arabic_text'=>'قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ','transliteration'=>'Qul innamaaa unzirukum bilwahyi; Wa-laa yasma\'us summud du\'aaa-\'a izaa maa yunzaroon','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>46,'arabic_text'=>'وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ','transliteration'=>'Wa-la\'in massat-hum nafhatun min \'azaabi Rabbika la-yaqoolunna yaawailanaaa innnaa kunnaa zaalimeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>47,'arabic_text'=>'وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ','transliteration'=>'Wa-nada\'ul mawaazeenal qista li-Yawmil Qiyaamati falaa tuzlamu nafsun shai\'aa; Wa-in kaana misqaala habbatim min khardalin atainaa bihaa; Wa-kafaa binaa haasibeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>48,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ','transliteration'=>'Wa-laqad aatainaa Moosa Wa-haaroonal Furqaana Wa-diyaa\'anw Wa-zikral lilmuttaqeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>49,'arabic_text'=>'ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ','transliteration'=>'Allazeena yakhshawna Rabbahum bilghaibi Wa-hum minas Saa\'ati mushfiqoon','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>50,'arabic_text'=>'وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ','transliteration'=>'Wa-haazaa Zikrum Mubaarakun anzalnaah; afa-antum lahoo munkiroon','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>51,'arabic_text'=>'۞ وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ','transliteration'=>'Wa-laqad aatainaaa Ibraaheema rushdahoo min qablu Wa-kunnaa bihee \'aalimeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>52,'arabic_text'=>'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ','transliteration'=>'Iz qaala li-abeehi Wa-qawmihee maa haazihit tamaaseelul lateee antum lahaa \'aakifoon','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>53,'arabic_text'=>'قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ','transliteration'=>'Qaaloo wajadnaaa aabaaa\'anaa lahaa \'aabideen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>54,'arabic_text'=>'قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Qaala laqad kuntum antum Wa-aabaaa\'ukum fee dalaalin mubeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>55,'arabic_text'=>'قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ','transliteration'=>'Qaalooo aji\'tanaa bil-haqqi am anta minal laa\'ibeen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>56,'arabic_text'=>'قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ','transliteration'=>'Qaala bar Rabbukum Rabbus samaawaati wal-ardil lazee fatarahunna Wa-ana \'alaa zaalikum minash shaahideen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>57,'arabic_text'=>'وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ','transliteration'=>'Wa-tallaahi la-akeedanna asnaamakum ba\'da an tuwalloo mudbireen','page_number'=>326,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>58,'arabic_text'=>'فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ','transliteration'=>'Faja\'alahum juzaazan illaa kabeeral lahum la\'allahum ilaihi yarji\'oon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>59,'arabic_text'=>'قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Qaaloo man fa\'ala haazaa bi-aalihatinaaa innahoo laminaz zaalimeen','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>60,'arabic_text'=>'قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ','transliteration'=>'Qaaloo sami\'naa fatany yazkuruhum yuqaalu lahooo ibraaheem','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>61,'arabic_text'=>'قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ','transliteration'=>'Qaaloo fa\'too bihee \'alaaa a\'yunin naasi la\'allahum yash-hadoon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>62,'arabic_text'=>'قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ','transliteration'=>'Qaalooo \'a-anta fa\'alta haazaa bi-aalihatinaa yaaa-ibraaheem','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>63,'arabic_text'=>'قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ','transliteration'=>'Qaala bal fa\'alahoo kabeeruhum haazaa fas\'aloohum in kaanoo yantiqoon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>64,'arabic_text'=>'فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Faraja\'ooo ilaaa anfusihim faqaalooo innakum antumuz zaalimoon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>65,'arabic_text'=>'ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ','transliteration'=>'Summa nukisoo \'alaa ru\'oosihim laqad \'alimta maa haaa\'ulaaa\'i yantiqoon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>66,'arabic_text'=>'قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ','transliteration'=>'Qaala afata\'budoona min doonil laahi maa laa yanfa\'ukum shai\'anw Wa-laa yadurrukum','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>67,'arabic_text'=>'أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Uffil lakum Wa-limaa ta\'budoona min doonil laah; afalaa ta\'qiloon','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>68,'arabic_text'=>'قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ','transliteration'=>'Qaaloo harriqoohu wansurooo aalihatakum in kuntum faa\'ileen','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>69,'arabic_text'=>'قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ','transliteration'=>'Qulnaa yaa-naaru koonee bardanw Wa-salaaman \'alaaa Ibraaheem','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>70,'arabic_text'=>'وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ','transliteration'=>'Wa-araadoo bihee kaidan faja\'alnaahumul akhsareen','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>71,'arabic_text'=>'وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ','transliteration'=>'Wa-najjainaahu Wa-Lootan ilal ardil latee baaraknaa feehaa lil-\'aalameen','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>72,'arabic_text'=>'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ','transliteration'=>'Wa-wahabnaa lahooo Ishaaqa; Wa-Ya\'qooba naafilah; Wa-kullan ja\'alnaa saaliheen','page_number'=>327,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>73,'arabic_text'=>'وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ','transliteration'=>'Wa-ja\'alnaahum a\'immataien yahdoona bi-amrinaa Wa-awhainaaa ilaihim fi\'lal khairaati Wa-iqaamas Salaati Wa-eetaaa\'az Zakaati Wa-kaanoo lanaa \'aabideen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>74,'arabic_text'=>'وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ','transliteration'=>'Wa-Lootan aatainaahu hukmanw Wa-\'ilmanw Wa-najjainaahu minal qaryatil latee kaanat ta\'malul khabaaa\'is; innahum kaanoo qawma saw\'in faasiqeen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>75,'arabic_text'=>'وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-adkhalnaahu fee rahmatinaa innahoo minas saaliheen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>76,'arabic_text'=>'وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ','transliteration'=>'Wa-noohan iz naadaa min qablu fastajabnaa lahoo fanajjainaahu Wa-ahlahoo minal karbil \'azeem','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>77,'arabic_text'=>'وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ','transliteration'=>'Wa-nasarnaahu minal qawmil lazeena kazzaboo bi-Aayaatinaa; innahum kaanoo qawma saw\'in fa-aghraq-naahum ajma\'een','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>78,'arabic_text'=>'وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ','transliteration'=>'Wa-Daawooda Wa-Sulaimaana iz yahkumaani fil harsi iz nafashat feehi ghanamul qawmi Wa-kunnaa lihukmihim shaahideen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>79,'arabic_text'=>'فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ','transliteration'=>'Fafahhamnaahaa sulaimaan; Wa-kullan aatainaa hukmanw wa\'ilmanw Wa-sakh-kharnaa ma\'a Daawoodal jibaala yusabbihna wattayr; Wa-kunnaa faa\'ileen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>80,'arabic_text'=>'وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ','transliteration'=>'Wa-\'allamanaahu san\'ata laboosil lakum lituhsinakum min ba\'sikum fahal antum shaakiroon','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>81,'arabic_text'=>'وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ','transliteration'=>'Wa-li-Sulaimaanar reeha \'aasifatan tajree bi-amriheee ilal ardil latee baaraknaa feehaa; Wa-kunnaa bikulli shai\'in \'aalimeen','page_number'=>328,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>82,'arabic_text'=>'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ','transliteration'=>'Wa-minash Shayaateeni maien yaghoosoona lahoo Wa-ya\'maloona \'amalan doona zaalika Wa-kunna lahum haafizeen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>83,'arabic_text'=>'۞ وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ','transliteration'=>'Wa-Ayyooba iz naadaa Rabbahooo annee massaniyad durru Wa-Anta arhamur raahimeen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>84,'arabic_text'=>'فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ','transliteration'=>'Fastajabnaa lahoo fakashaf-naa maa bihee min durrinw Wa-aatainaahu ahlahoo Wa-mislahum ma\'ahum rahmatan min \'indinaa Wa-zikraa lil\'aabideen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>85,'arabic_text'=>'وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ','transliteration'=>'Wa-Ismaa\'eela Wa-Idreesa Wa-Zal Kifli kullum minas saabireen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>86,'arabic_text'=>'وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-adkhalnaahum fee rahmatinaa innahum minas saaliheen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>87,'arabic_text'=>'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-Zan Nooni iz zahaba mughaadiban fa-zannaa al lan naqdira \'alaihi fanaadaa fiz zulumaati al laaa ilaaha illaaa Anta Subhaanaka innee kuntu minaz zaalimeen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>88,'arabic_text'=>'فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ','transliteration'=>'Fastajabnaa lahoo Wa-najjainaahu minal ghamm; Wa-kazaalika nunjil mu\'mineen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>89,'arabic_text'=>'وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ','transliteration'=>'Wa-Zakariyyaaa iz naadaa Rabbahoo Rabbi laa tazarnee fardanw Wa-Anta khairul waariseen','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>90,'arabic_text'=>'فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ','transliteration'=>'Fastajabnaa lahoo Wa-wahabnaa lahoo Yahyaa Wa-aslahnaa lahoo zawjah; innahum kaanoo yusaari\'oona fil khairaati Wa-yad\'oonanaa raghabanw Wa-rahabaa; Wa-kaanoo lanaa khaashi\'een','page_number'=>329,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>91,'arabic_text'=>'وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ','transliteration'=>'Wallateee ahsanat farjahaa fanafakhnaa feehaa min roohinaa Wa-ja\'alnaahaa wabnahaaa Aayatan lil\'aalameen','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>92,'arabic_text'=>'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ','transliteration'=>'Inna haaziheee ummatukum ummatanw waahidatanw Wa-Ana Rabbukum fa\'budoon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>93,'arabic_text'=>'وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ','transliteration'=>'Wa-taqatta\'ooo amrahum bainahum kullun ilainaaa raaji\'oon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>94,'arabic_text'=>'فَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ','transliteration'=>'Famaien ya\'mal minas saalihaati Wa-huwa mu\'minun falaa kufraana lisa\'yihee Wa-innaa lahoo kaatiboon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>95,'arabic_text'=>'وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ','transliteration'=>'Wa-haraamun \'alaa qaryatin ahlaknaahaaa annahum laa yarji\'oon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>96,'arabic_text'=>'حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ','transliteration'=>'Hattaaa izaa futihat Ya\'jooju Wa-Ma\'jooju Wa-hum min kulli hadabien yansiloon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>97,'arabic_text'=>'وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ','transliteration'=>'Waqtarabal wa\'dul haqqu fa-izaa hiya shaakhisatun absaarul lazeena kafaroo yaawailanaa qad kunna fee ghaflatin min haaza bal kunnaa zaalimeen','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>98,'arabic_text'=>'إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ','transliteration'=>'Innakum Wa-maa ta\'budoona min doonil laahi hasabu Jahannama antum lahaa waaridoon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>99,'arabic_text'=>'لَوۡ كَانَ هَٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ','transliteration'=>'Law kaana haaa\'ulaaa\'i aalihatan maa waradoohaa Wa-kullun feehaa khaalidoon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>100,'arabic_text'=>'لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ','transliteration'=>'Lahum feehaa zafeerunw Wa-hum feehaa laa yasma\'oon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>101,'arabic_text'=>'إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَٰٓئِكَ عَنۡهَا مُبۡعَدُونَ','transliteration'=>'Innal lazeena sabaqat lahum minnal husnaaa ulaaa\'ika \'anhaa mub\'adoon','page_number'=>330,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>102,'arabic_text'=>'لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ','transliteration'=>'Laa yasma\'oona hasee-sahaa Wa-hum fee mash tahat anfusuhum khaalidoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>103,'arabic_text'=>'لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ','transliteration'=>'Laa yahzunuhumul faza\'ul akbaru Wa-tatalaq-qaahumul malaaa\'ikatu haazaa Yawmukumul lazee kuntum too\'adoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>104,'arabic_text'=>'يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ','transliteration'=>'Yawma natwis samaaa\'a kataiyis sijilli lilkutub; kamaa bada\'naa awwala khalqin nu\'eeduh; wa\'dan \'alainaa; innaa kunna faa\'ileen','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>105,'arabic_text'=>'وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ','transliteration'=>'Wa-laqad katabnaa fiz Zaboori min ba\'diz zikri annal arda yarisuhaa \'ibaadi-yas saalihoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>106,'arabic_text'=>'إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ','transliteration'=>'Inna fee haaza labalaa-ghal liqawmin \'aabideen','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>107,'arabic_text'=>'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ','transliteration'=>'Wa-maaa arsalnaaka illaa rahmatal lil\'aalameen','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>108,'arabic_text'=>'قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ','transliteration'=>'Qul innamaa yoohaa ilaiya annamaaa ilaahukum illaahunw Waahid, fahal antum muslimoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>109,'arabic_text'=>'فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ','transliteration'=>'Fa-in tawallaw faqul aazantukum \'alaa sawaaa\'; Wa-in adreee aqareebun am ba\'eedun maa too\'adoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>110,'arabic_text'=>'إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ','transliteration'=>'Innahoo ya\'lamul jahra minal qawli Wa-ya\'lamu maa taktumoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>111,'arabic_text'=>'وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ','transliteration'=>'Wa-in adree la\'allahoo fitnatul lakum Wa-mataa\'un ilaa heen','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            ['surah_id'=>21,'ayah_number'=>112,'arabic_text'=>'قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ','transliteration'=>'Qaala Rabbih kum bil-haqq; Wa-Rabbunar Rahmaa-nul musta\'aanu \'alaa maa tasifoon','page_number'=>331,'juz_number'=>17,'hizb_number'=>33,'is_sajdah'=>false],
            /* Surah 22: The Pilgrimage (Al-Hajj) */
            ['surah_id'=>22,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ','transliteration'=>'Yaaa ayyuhan naasuttaqoo Rabbakum; inna zalzalatas Saa\'ati shai\'un \'azeem','page_number'=>332,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>2,'arabic_text'=>'يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ','transliteration'=>'Yawma tarawnahaa tazhalu kullu murdi\'atin \'ammaaa arda\'at Wa-tada\'u kullu zaati hamlin hamlahaa Wa-tarannaasa sukaaraa Wa- maa hum bisukaaraa Wa-lakinaa \'azaabal laahi shadeed','page_number'=>332,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>3,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ','transliteration'=>'Wa-minan naasi maien yujaadilu fil laahi bighairi \'ilminw Wa-yattabi\'u kullaa shaitaanim mareed','page_number'=>332,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>4,'arabic_text'=>'كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ','transliteration'=>'Kutiba \'alaihi annahoo man tawallaahu fa-annahoo yudilluhoo Wa-yahdeehi ilaa \'azaabis sa\'eer','page_number'=>332,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>5,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ','transliteration'=>'Yaaa-ayyuhan naasu in kuntum fee raibin minal ba\'thi fa-innaa khalaqnaakum min turaabin thumma min nutfatin thumma min \'alaqatin thumma min mudghatin mukhallaqatinw Wa-ghairi mukhallaqatin linubaiyina lakum; Wa-nuqirru fil arhaami maa nashaaa\'u ilaaa ajalin musamman thumma nukhrijukum tiflan thumma litablughooo ashuddakum Wa-minkum mai yutawaffa Wa-minkum mai yuraddu ilaaa arzalil \'umuri likailaa ya\'lama min ba\'di \'ilmin shai\'aa; Wa-taral arda haamidatan fa-izaaa anzalnaa \'alaihal maaa\'ah tazzat Wa-rabat Wa-ambatat min kulli zawjin baheej','page_number'=>332,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>6,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Zaalika bi annal laaha Huwal haqqu Wa-annahoo yuhyil mawtaa Wa-annahoo \'alaakulli shai\'in Qadeer','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>7,'arabic_text'=>'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ','transliteration'=>'Wa-annas Saa\'ata aatiya tul laa raiba feeha Wa-annal laaha yab\'asuman fil quboor','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>8,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ','transliteration'=>'Wa-minan naasi maien yujaadilu fil laahi bighairi \'ilminw Wa-laa hudanw Wa-laa Kitaabim Muneer','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>9,'arabic_text'=>'ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ','transliteration'=>'Saaniya \'itfihee liyudilla \'an sabeelil laahi lahoo fiddun yaa khizyunw Wa-nuzeequhoo Yawmal Qiyaamati azaabal hareeq','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>10,'arabic_text'=>'ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمٖ لِّلۡعَبِيدِ','transliteration'=>'Zaalika bimaa qaddamat yadaaka Wa-annal laaha laisa bizallaamil lil\'abeed','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>11,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ','transliteration'=>'Wa-minan naasi maien ya\'budul laaha \'alaa harfin fa-in asaabahoo khairunit maanna bihee Wa-in asaabat-hu fitnatunin qalaba \'alaa wajhihee khasirad dunyaa wal-aakhirah; zaalika huwal khusraanul mubeen','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>12,'arabic_text'=>'يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ','transliteration'=>'Yad\'oo min doonil laahi maa laa yadurruhoo Wa-maa laa yanfa\'uh\' zaalika huwad dalaalul ba\'ed','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>13,'arabic_text'=>'يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ','transliteration'=>'Yad\'oo laman darruhooo aqrabu min naf\'ih; labi\' salmawlaa Wa-labi\'sal \'asheer','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>14,'arabic_text'=>'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ','transliteration'=>'Innal laaha yudkhilul lazeena aamanoo Wa-\'amilus saalihaati jannaatin tajree min tahtihal anhaar; innal laaha yaf\'alu maa yureed','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>15,'arabic_text'=>'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ','transliteration'=>'Man kaana yazunnu al laien yansurahul laahu fid dunyaa wal-aakhirati fal-yamdud bisababin ilas samaaa\'i summal yaqta\' falyanzur hal yuzhibanna kaiduhoo maa yagheez','page_number'=>333,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>16,'arabic_text'=>'وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ','transliteration'=>'Wa-kazaalika anzalnaahu aayaatim baiyinaatinw Wa-annal laaha yahdee mai yureed','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>17,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ','transliteration'=>'Innal lazeena aamanoo wallazeena haadoo was-saabi\'eena wan-nasaaraa wal-Majoosa wallazeena ashrakooo innal laaha yafsilu bainahum yawmal qiyaamah; innal laaha \'alaa kulli shai\'in shaheed','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>18,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ','transliteration'=>'Alam tara annal laaha yasjudu lahoo man fis samaawaati Wa-man fil ardi wash-shamsu walqamaru wan-nu-joomu wal-jibaalu wash-shajaru wad-dawaaabbu Wa-kaseerum minan naasi Wa-kaseerun haqqa \'alaihil \'azaab; Wa-maien yuhinil laahu famaa lahoo mim mukrim; innal laaha yaf\'alu maa yashaaa','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>true],
            ['surah_id'=>22,'ayah_number'=>19,'arabic_text'=>'۞ هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ','transliteration'=>'Haazaani khasmaanikh tasamoo fee Rabbihim fal-lazeena kafaroo qutti\'at lahum siyaabum min naar; yusabbu min fawqi ru\'oosihimul hameem','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>20,'arabic_text'=>'يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ','transliteration'=>'Yusharu bihee maa fee butoonihim waljulood','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>21,'arabic_text'=>'وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ','transliteration'=>'Wa-lahum maqaami\'u min hadeed','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>22,'arabic_text'=>'كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ','transliteration'=>'Kullamaa araadooo any yakhrujoo minhaa min ghammin u\'eedoo feeha Wa-zooqoo \'azaabal hareeq','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>23,'arabic_text'=>'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ','transliteration'=>'Innal laaha yudkhilul lazeena aamanoo Wa-\'amilus saalihaati jannaatin tajree min tahtihal anhaaru yuhallawna feehaa min asaawira min zahabinw Wa-lu\'lu\'aa; Wa-libaasuhum feehaa hareer','page_number'=>334,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>24,'arabic_text'=>'وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ','transliteration'=>'Wa-hudooo ilat taiyibi minal qawli Wa-hudooo ilaaa siraatil hameed','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>25,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ','transliteration'=>'Innal lazeena kafaroo Wa-yasuddoona \'an sabeelil laahi wal-Masjidil Haraamil lazee ja\'alnaahu linnaasi sawaaa\'anil \'aakifu feehi walbaad; Wa-maien yurid feehi bi-ilhaadim bizulmin nuziqhu min \'azaabin aleem','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>26,'arabic_text'=>'وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ','transliteration'=>'Wa-iz bawwaanaa li-Ibraaheema makaanal Baiti al laa tushrik bee shai\'anw Wa-tahhir Baitiya litaaa\'ifeena walqaaa\'-imeena warrukka-\'is sujood','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>27,'arabic_text'=>'وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ','transliteration'=>'Wa-azzin fin naasi bil-Hajji yaatooka rijaalanw Wa-\'alaa kulli daamirien yaateena min kulli fajjin \'ameeq','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>28,'arabic_text'=>'لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ','transliteration'=>'Li yashhadoo manaafi\'a lahum Wa-yazkurus mal laahi feee ayyaamimma\'loomaatin \'alaa maa razaqahum mim baheematil an\'aami fakuloo minhaa Wa-at\'imul baaa\'isal faqeer','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>29,'arabic_text'=>'ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ','transliteration'=>'Summal yaqdoo tafasahum wal-yoofoo nuzoorahum wal-yattawwafoo bil-Baitil \'Ateeq','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>30,'arabic_text'=>'ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ','transliteration'=>'Zaalika Wa-maien yu\'azzim hurumaatil laahi fahuwa khairul lahoo \'inda Rabbih; Wa-uhillat lakumul an\'aamu illaa maa yutlaa \'alaikum fajtanibur rijsa minal awsaani wajtaniboo qawlaz zoor','page_number'=>335,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>31,'arabic_text'=>'حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ','transliteration'=>'Hunafaaa\'a lillaahi ghaira mushrikeena bih; Wa-maien yushrik billaahi faka-annamaa kharra minas samaaa\'i fatakh-tafuhut tairu aw tahwee bihir reehu bee makaanin saheeq','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>32,'arabic_text'=>'ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ','transliteration'=>'Zaalika Wa-mai yu\'azzim sha\'aaa\'iral laahi fa-innahaa min taqwal quloob','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>33,'arabic_text'=>'لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ','transliteration'=>'Lakum feehaa manaafi\'u ilaaa ajalim musamman summa mahilluhaaa ilal Baitil \'Ateeq','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>34,'arabic_text'=>'وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ','transliteration'=>'Wa-likulli ummatin ja\'alnaa mansakal liyazkurus mal laahi \'alaa maa razaqahum mim baheematil an\'aam; failaahukum ilaahunw Waahidun falahooo aslimoo; Wa-bashshiril mukhbiteen','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>35,'arabic_text'=>'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','transliteration'=>'Allazeena izaa zukiral laahu wajilat quloobuhum wassaabireena \'alaa maaa asaabahum walmuqeemis Salaati Wa-mimmaa razaqnaahum yunfiqoon','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>36,'arabic_text'=>'وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Walbudna ja\'alnaahaa lakum min sha\'aaa\'iril laahi lakum feehaa khairun fazkurus mal laahi \'alaihaa sawaaff; fa-izaa wajabat junoobuhaa fakuloo minhaa Wa-at\'imul qaani\'a walmu\'tarr; kazaalika sakhkharnaahaa lakum la\'allakum tashkuroon','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>37,'arabic_text'=>'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ','transliteration'=>'Laien yanaalal laaha luhoo-muhaa Wa-laa dimaaa\'uhaa Wa-laakiny yanaaluhut taqwaa minkum; kazaalika sakhkharhaa lakum litukabbirul laaha \'alaa ma hadaakum; Wa-bashshirul muhsineen','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>38,'arabic_text'=>'۞ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ','transliteration'=>'Innal laaha yudaafi\' \'anil lazeena aamanoo; innal laaha laa yuhibbu kulla khawwaanin kafoor','page_number'=>336,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>39,'arabic_text'=>'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ','transliteration'=>'Uzina lillazeena yuqaataloona bi-annahum zulimoo; Wa-innal laaha \'alaa nasrihim la-Qaderr','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>40,'arabic_text'=>'ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ','transliteration'=>'Allazeena ukhrijoo min diyaarihim bighairi haqqin illaaa any yaqooloo rabbunallaah; Wa-law laa daf\'ul laahin naasa ba\'dahum biba\'dil lahuddimat sawaami\'u Wa-biya\'unw Wa-salawaatunw Wa-masaajidu yuzkaru feehasmul laahi kaseeraa; Wa-layansurannal laahu mai yansuruh; innal laaha la qawiyyun \'Azeez','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>41,'arabic_text'=>'ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ','transliteration'=>'Allazeena im makkan-naahum fil ardi aqaamus Salaata Wa-aatawuz Zakaata Wa-amaroo bilma\'roofi Wa-nahaw \'anil munkar; Wa-lillaahi \'aaqibatul umoor','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>42,'arabic_text'=>'وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ','transliteration'=>'Wa-ien yukazzibooka faqad kazzabat qablahum qawmu Nooinw Wa-Aadunw Wa-Samood','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>43,'arabic_text'=>'وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ','transliteration'=>'Wa-qawmu Ibraaheema Wa-qawmu Loot','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>44,'arabic_text'=>'وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ','transliteration'=>'Wa-as-haabu Madyana Wa-kuzziba Moosaa fa-amlaitu lilkaafireena summa akhaztuhum fakaifa kaana nakeer','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>45,'arabic_text'=>'فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ','transliteration'=>'Faka-ayyim min qaryatin ahlaknaahaa Wa-hiya zaalimatun fahiya khaawiyatun \'alaa \'urooshihaa Wa-bi\'rim mu\'at-talatinw Wa-qasrim masheed','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>46,'arabic_text'=>'أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ','transliteration'=>'Afalam yaseeroo fil ardi fatakoona lahum quloobuien ya\'qiloona bihaaa aw aazaanunien yasma\'oona bihaa fa-innahaa laa ta\'mal absaaru Wa-laakin ta\'mal quloobul latee fis sudoor','page_number'=>337,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>47,'arabic_text'=>'وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ','transliteration'=>'Wa-yasta\'juloonaka bil\'azaabi Wa-lany yukhlifal laahu wa\'dah; Wa-inna yawman \'inda Rabbika ka\'alfi sanatim mimmaa ta\'uddoon','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>48,'arabic_text'=>'وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ','transliteration'=>'Wa-ka-ayyim min qaryatin amlaitu lahaa Wa-hiya zaalimatun summa akhaztuhaa Wa-ilaiyal maseer','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>49,'arabic_text'=>'قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ','transliteration'=>'Qul yaaa-ayyuhan naasu innamaaa ana lakum nazeerum mubeen','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>50,'arabic_text'=>'فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ','transliteration'=>'Fallazeena aamanoo Wa-\'amilu saalihaati lahum maghfiratunw Wa-rizqun kareem','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>51,'arabic_text'=>'وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','transliteration'=>'Wallazeena sa\'aw feee Aayaatinaa mu\'aajizeena ulaaa-ika As-haabul jaheem','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>52,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Wa-maaa arsalnaa min qablika mir Rasoolinnw Wa-laa Nabiyyin illaaa izaaa tamannaaa alqash Shaitaanu feee umniy-yatihee fa-yansakhul laahu maa yulqish Shaitaanu summa yuhkimul laahu aayaatih; wallaahu \'Aleemun Hakeem','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>53,'arabic_text'=>'لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ','transliteration'=>'Liyaj\'ala maa yulqish Shaitaanu fitnatal lillazeena fee quloobihim maradunw walqaasiyati quloobuhum; Wa-innaz zaalimeena lafee shiqaaqim ba\'eed','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>54,'arabic_text'=>'وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-liya\'lamal lazeena ootul \'ilma annahul haqqu mir Rabbika fa-yu\'minoo bihee fatukhbita lahoo quloobuhum; Wa-innal laaha lahaadil lazeena aamanoo ilaa Siraatim Mustaqeem','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>55,'arabic_text'=>'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ','transliteration'=>'Wa-laa yazaalul lazeena kafaroo fee miryatim minhu hattaa taatiyahumus Saa\'atu baghtatan aw yaatiyahum \'azaabu Yawmin \'aqeem','page_number'=>338,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>56,'arabic_text'=>'ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي جَنَّٰتِ ٱلنَّعِيمِ','transliteration'=>'Almulku Yawma\'izil lillaahi yahkumu bainahum; fallazeena aamanoo Wa-\'amilus saalihaati fee jannaatin Na\'eem','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>57,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ','transliteration'=>'Wallazeena kafaroo Wa-kazzaboo bi-Aayaatinaa fa-ulaaa\'ika lahum \'azaabum muheen','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>58,'arabic_text'=>'وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ','transliteration'=>'Wallazeena haajaroo fee sabeelil laahi summa qutilooo aw maatoo la-yarzuqan-nahumul laahu rizqan hasanaa; Wa-innal laaha la-Huwa khairur raaziqeen','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>59,'arabic_text'=>'لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٞ','transliteration'=>'La-yudkhilan-nahum mud-khalaien yardawnah; Wa-innal laaha la-\'Aleemun Haleem','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>60,'arabic_text'=>'۞ ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ','transliteration'=>'Zaalika Wa-man \'aaqaba bimisli maa \'ooqiba bihee summa bughiya \'alaihi la-yansurannahul laah; innal laaha la-\'Afuwwun Ghafoor','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>61,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ','transliteration'=>'Zaalika bi-annal laaha yoolijul laila fin nahaari Wa-yoolijun nahaara fil laili Wa-annal laaha Samee\'um Baseer','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>62,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ','transliteration'=>'Zaalika bi-annal laaha Huwal haqqu Wa-anna maa yad\'oona min doonihee huwal baatilu Wa-annal laaha Huwal \'Aliyyul kabeer','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>63,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ','transliteration'=>'Alam tara annal laaha anzala minas samaaa\'i maaa\'an fatusbihul ardu mukhdarrah; innal laaha Lateefun Khabeer','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>64,'arabic_text'=>'لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','transliteration'=>'Lahoo ma fis samaawaati Wa-ma fil ard; Wa-innal laaha la-Huwal Ghaniyyul Hameed','page_number'=>339,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>65,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ','transliteration'=>'Alam tara annal laaha sakhkhara lakum maa fil ardi wal-fulka tajree fil bahri bi-amrihee Wa-yumsikus samaaa\'a an taqa\'a \'alal ardi illaa biiznih; innal laaha binnaasi la-Ra\'oofur Raheem','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>66,'arabic_text'=>'وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ','transliteration'=>'Wa-Huwal lazee ahyaakum summa yumeetukum summa yuhyeekum; innal insaana la-kafoor','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>67,'arabic_text'=>'لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ','transliteration'=>'Likulli ummatin ja\'alnaa mansakan hum naasikoohu falaa yunaazi-\'unnaka fil amr; wad\'u ilaa Rabbika innaka la-\'alaa hudan mustaqeem','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>68,'arabic_text'=>'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ','transliteration'=>'Wa-in jaadalooka faqulil laahu a\'lamu bimaa ta\'maloon','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>69,'arabic_text'=>'ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','transliteration'=>'Allaahu yahkumu bainakum Yawmal Qiyaamati feemaa kuntum feehi takhtalifoon','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>70,'arabic_text'=>'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ','transliteration'=>'Alam ta\'lam annal laaha ya\'lamu maa fis samaaa\'i wal-ard; inna zaalika fee kitaab; inna zaalika \'alal laahi yaseer','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>71,'arabic_text'=>'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٖ','transliteration'=>'Wa-ya\'budoona min doonil laahi maa lam yunazzil bihee sultaananw Wa-maa laisa lahum bihee \'ilm; Wa-maa lizzaalimeena min naseer','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>72,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Wa-izaa tutlaa \'laihim Aayaatunaa baiyyinaatin ta\'rifu fee wujoohil lazeena kafarul munkara yakaadoona yastoona bil-lazeena yatloona \'alaihim Aayaatinaa; qul afa-unab-bi\'ukum bisharrim min zaalikum; an-Naaru Wa-\'adahal laahul lazeena kafaroo Wa-bi\'sal maseer','page_number'=>340,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>73,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ','transliteration'=>'Yaaa-ayyuhan naasu duriba masalun fastami\'oo lah; innal lazeena tad\'oona min doonil laahi laien yakhluqoo zubaabanw Wa-lawi ijtama\'oo lahoo Wa-ien yaslub-humuz zubaabu shai\'an laa yastanqizoohu minh; da\'ufat taalibu wal-matloob','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>74,'arabic_text'=>'مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ','transliteration'=>'Maa qadrul laaha haqqa qadrih; innal laaha la-Qawiyyun \'Azeez','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>75,'arabic_text'=>'ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ','transliteration'=>'Allahu yastafee minal malaaa\'ikati Rusulanw Wa-minan naas; innal laaha Samee\'un Baseer','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>76,'arabic_text'=>'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Ya\'lamu maa baina aydeehim Wa-maa khalfahum; Wa-ilal laahi turja\'ul umoor','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            ['surah_id'=>22,'ayah_number'=>77,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanur ka\'oo wasjudoo wa\'budoo Rabbakum waf\'alul khaira la\'allakum tuflihoon','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>true],
            ['surah_id'=>22,'ayah_number'=>78,'arabic_text'=>'وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ','transliteration'=>'Wa-jaahidoo fil laahi haqqa jihaadih; Huwaj tabaakum Wa-maa ja\'ala \'alaikum fid deeni min haraj; Millata abeekum Ibraaheem; Huwa sammaakumul muslimeena min qablu Wa-fee haaza li-yakoonar Rasoolu shaheedan \'alaikum Wa-takoonoo shuhadaaa\'a \'alan naas; fa-aqeemus salaata Wa-aatuz zakaata wa\'tasimoo billaahi Huwa mawlaakum fani\'mal mawlaa Wa-ni\'man naseer','page_number'=>341,'juz_number'=>17,'hizb_number'=>34,'is_sajdah'=>false],
            /* Surah 23: The Believers (Al-Mu'minun) */
            ['surah_id'=>23,'ayah_number'=>1,'arabic_text'=>'قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Qad aflahal mu\'minoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>2,'arabic_text'=>'ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ','transliteration'=>'Allazeena hum fee Salaatihim khaashi\'oon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>3,'arabic_text'=>'وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ','transliteration'=>'Wallazeena hum \'anil laghwi mu\'ridoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>4,'arabic_text'=>'وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ','transliteration'=>'Wallazeena hum liz-Zakaati faa\'iloon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>5,'arabic_text'=>'وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ','transliteration'=>'Wallazeena hum lifuroo-jihim haafizoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>6,'arabic_text'=>'إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ','transliteration'=>'Illaa \'alaaa azwaajihim aw maa malakat aimaanuhum fa-innahum ghairu maloomeen','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>7,'arabic_text'=>'فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ','transliteration'=>'Famanib taghaa waraaa\'a zaalika fa-ulaaa\'ika humul \'aadoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>8,'arabic_text'=>'وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ','transliteration'=>'Wallazeena hum li-amaanaatihim Wa-\'ahdihim raa\'oon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>9,'arabic_text'=>'وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ','transliteration'=>'Wallazeena hum \'alaa Salawaatihim yuhaafizoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>10,'arabic_text'=>'أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ','transliteration'=>'Ulaaa\'ika humul waarisoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>11,'arabic_text'=>'ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Allazeena yarisoonal Firdawsa hum feehaa khaalidoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>12,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ','transliteration'=>'Wa-laqad khalaqnal insaana min sulaalatim min teen','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>13,'arabic_text'=>'ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ','transliteration'=>'Summa ja\'alnaahu nutfatan fee qaraarim makeen','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>14,'arabic_text'=>'ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ','transliteration'=>'Summa khalaqnan nutfata \'alaqatan fakhalaqnal \'alaqata mudghatan fakhalaq-nal mudghata \'izaaman fakasawnal \'izaama lahman summa anshaanaahu khalqan aakhar; fatabaarakal laahu ahsanul khaaliqeen','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>15,'arabic_text'=>'ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ','transliteration'=>'Summa innakum ba\'da zaalika la-maaiyitoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>16,'arabic_text'=>'ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ','transliteration'=>'Summa innakum Yawmal Qiyaamati tub\'asoon','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>17,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ','transliteration'=>'Wa-laqad khalaqnaa fawqakum sab\'a taraaa\'iqa Wa-maa kunnaa \'anil khalqi ghaafileen','page_number'=>342,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>18,'arabic_text'=>'وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ','transliteration'=>'Wa-anzalnaa minas samaaa\'i maaa\'am biqadarin fa-askannaahu fil ardi Wa-innaa \'alaa zahaabim bihee laqaa-diroon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>19,'arabic_text'=>'فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ','transliteration'=>'Fa-anshaanaa lakum bihee Jannaatim min nakheelinw Wa-a\'naab; lakum feehaa fawaakihu kaseeratunw Wa-minhaa taakuloon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>20,'arabic_text'=>'وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ','transliteration'=>'Wa-shajaratan takhruju min Toori Sainaaa\'a tambutu bidduhni Wa-sibghil lil-aakileen','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>21,'arabic_text'=>'وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ','transliteration'=>'Wa-inna lakum fil an\'aami la\'ibrah; nusqeekum mimmaa fee butoonihaa Wa-lakum feehaa manaafi\'u kaseeratunw Wa-minhaa taakuloon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>22,'arabic_text'=>'وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ','transliteration'=>'Wa-\'alaihaa wa\'alal fulki tuhmaloon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>23,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','transliteration'=>'Wa-laqad arsalnaa Noohan ilaa qawmihee faqaala yaa qawmi\'budul laaha maa lakum min ilahin ghairuhoo afalaa tattaqoon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>24,'arabic_text'=>'فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ','transliteration'=>'Faqaalal mala\'ul lazeena kafaroo min qawmihee maa haazaaa illaa basharum mislukum yureedu aien yatafaddala \'alaikum Wa-law shaaa\'al laahu la-anzala malaaa\'ikatam maa sami\'naa bihaazaa feee aabaaa\'inal awwaleen','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>25,'arabic_text'=>'إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ','transliteration'=>'In huwa illaa rajulum bihee jinnatun fatarabbasoo bihee hattan heen','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>26,'arabic_text'=>'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ','transliteration'=>'Qaala Rabbin surnee bimaa kazzaboon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>27,'arabic_text'=>'فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ','transliteration'=>'Fa-awhainaaa ilaihi anis na\'il fulka bi-a\'yuninaa Wa-wahyinaa fa-izaa jaaa\'a amrunaa Wa-faarat tannooru fasluk feehaa min kullin zawjainis naini Wa-ahlaka illaa man sabaqa \'alaihil qawlu minhum Wa-laa tukhaat-ibnee fil lazeena zalamooo innaahum mughraqoon','page_number'=>343,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>28,'arabic_text'=>'فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Fa-izas tawaita ata Wa-mam ma\'aka \'alal fulki faqulil hamdu lillaahil lazee najjaanaa minal qawmiz zalimeen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>29,'arabic_text'=>'وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ','transliteration'=>'Wa-qur Rabbi anzilnee munzalam mubaarakanw Wa-Anta khairul munzileen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>30,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ','transliteration'=>'Inna fee zaalika la-Aayaatinw Wa-in kunnaa lamubtaleen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>31,'arabic_text'=>'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ','transliteration'=>'Summaa anshaana mim ba\'dihim qarnan aakhareen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>32,'arabic_text'=>'فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','transliteration'=>'Fa-arsalnaa feehim Rasoolam minhum ani \'budul laaha maa lakum min ilaahin ghairuhoo afalaa tattaqoon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>33,'arabic_text'=>'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ','transliteration'=>'Wa-qaalal mala-u min qawmihil lazeena kafaroo Wa-kazzaboo bi-liqaaa\'il Aakhirati Wa-atrafnaahum fil hayaatid dunyaa maa haazaaa illaa basharum mislukum yaakulu mimmaa taakuloona minhu Wa-yashrabu mimmaa tashraboon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>34,'arabic_text'=>'وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ','transliteration'=>'Wa-la\'in at\'atum basharam mislakum innakum izal lakhaasiroon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>35,'arabic_text'=>'أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ','transliteration'=>'A-Ya\'idukum annakum izaa mittum Wa-kuntum turaabanw Wa-izaaman annakum mukhrajoon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>36,'arabic_text'=>'۞ هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ','transliteration'=>'Haihaata haihaata limaa too\'adoon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>37,'arabic_text'=>'إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ','transliteration'=>'In hiya illaa hayaatunad dunyaa namootu Wa-nahyaa Wa-maa nahnu bimab\'ooseen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>38,'arabic_text'=>'إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ','transliteration'=>'In huwa illaa rajulunif taraa \'alal laahi kazibanw Wa-maa nahnuu lahoo bimu\'mineen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>39,'arabic_text'=>'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ','transliteration'=>'Qaala Rabbin surnee bimaa kazzaboon','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>40,'arabic_text'=>'قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ','transliteration'=>'Qaala \'ammaa qaleelil la-yusbihunna naadimeen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>41,'arabic_text'=>'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Fa-akhazat-humus saihatu bilhaqqi faja\'alnaahum ghusaaa\'aa; fabu;dal lilqaw-miz zaalimeen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>42,'arabic_text'=>'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ','transliteration'=>'Summa anshaanaa mim ba\'dihim quroonan aakhareen','page_number'=>344,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>43,'arabic_text'=>'مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ','transliteration'=>'Maa tasbiqu min ummatin ajalahaa Wa-maa yastaakhiroon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>44,'arabic_text'=>'ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ','transliteration'=>'Summa arsalnaa Rusulanaa tatraa kulla maa jaaa\'a ummatar Rasooluhaa kazzabooh; fa-atba\'naa ba\'dahum ba\'danw Wa-ja\'alnaahum ahaadees; fabu\'dal liqawmil laa yu\'minoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>45,'arabic_text'=>'ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ','transliteration'=>'Summa arsalnaa Moosaa Wa-akhaahu Haaroona bi-Aayaatinaa Wa-sultaanim mubeen','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>46,'arabic_text'=>'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ','transliteration'=>'Ilaa Fir\'awna Wa-mala\'ihee fastakbaroo Wa-kaanoo qawman \'aaleen','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>47,'arabic_text'=>'فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ','transliteration'=>'Faqaaloo annu\'minu libasharaini mislinaa Wa-qawmuhumaa lanaa \'aabidoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>48,'arabic_text'=>'فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ','transliteration'=>'Fakazzaboohumaa fakaanoo minal muhlakeen','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>49,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba la\'allahum yahtadoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>50,'arabic_text'=>'وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ','transliteration'=>'Wa-ja\'alnab na Maryama Wa-ummahooo aayatannw Wa-aawainaahumaaa ilaa rabwatin zaati qaraarinw Wa-ma\'een','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>51,'arabic_text'=>'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ','transliteration'=>'Yaaa-aiyuhar Rusulu kuloo minat taiyibaati wa\'maloo saalihan innee bimaa ta\'maloona \'Aleem','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>52,'arabic_text'=>'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ','transliteration'=>'Wa-inna haaziheee ummatukum ummatanw waahidatanw Wa-Ana Rabbukum fattaqoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>53,'arabic_text'=>'فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ','transliteration'=>'Fataqatta\'ooo amrahum bainahum zuburaa; kullu hizbim bimaa ladaihim farihoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>54,'arabic_text'=>'فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ','transliteration'=>'Fazarhum fee ghamratihim hattaa heen','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>55,'arabic_text'=>'أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ','transliteration'=>'A-yahsaboona annnamaa numiduhum bihee mim maalinw Wa-baneen','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>56,'arabic_text'=>'نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ','transliteration'=>'Nusaari\'u lahum fil khairaat; bal laa yash\'uroon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>57,'arabic_text'=>'إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ','transliteration'=>'Innal lazeena hum min khashyati Rabbihim mushfiqoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>58,'arabic_text'=>'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ','transliteration'=>'Wallazeena hum bi-Aayaati Rabbihim yu\'minoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>59,'arabic_text'=>'وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ','transliteration'=>'Wallazeena hum bi-Rabbihim laa yushrikoon','page_number'=>345,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>60,'arabic_text'=>'وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ','transliteration'=>'Wallazeena yu\'toona maaa aataw Wa-quloobuhum wajilatun annahum ilaa Rabbihim raaji\'oon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>61,'arabic_text'=>'أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ','transliteration'=>'Ulaaa\'ika yusaari\'oona fil khairaati Wa-hum lahaa saabiqoon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>62,'arabic_text'=>'وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-laa nukallifu nafsan illaa wus\'ahaa Wa-ladainaa kitaabuny yantiqu bilhaqqi Wa-ahum la yuzlamoon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>63,'arabic_text'=>'بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ','transliteration'=>'Bal quloobuhum fee ghamratim min haazaa Wa-lahum a\'maalum min dooni zaalika hum lahaa \'aamiloon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>64,'arabic_text'=>'حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ','transliteration'=>'Hattaaa izaaa akhaznaa mutrafeehim bil\'azaabi izaa hum yaj\'aroon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>65,'arabic_text'=>'لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ','transliteration'=>'Laa taj\'arul yawma innakum minnaa laa tunsaroon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>66,'arabic_text'=>'قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ','transliteration'=>'Qad kaanat Aayaatee tutlaa \'alaikum fakuntum \'alaaa a\'qaabikum tankisoon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>67,'arabic_text'=>'مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ','transliteration'=>'Mustakbireena bihee saamiran tahjuroon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>68,'arabic_text'=>'أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ','transliteration'=>'Afalam yaddabbarrul qawla am jaaa\'ahum maa lam yaati aabaaa\'ahumul awwaleen','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>69,'arabic_text'=>'أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ','transliteration'=>'Am lam ya\'rifoo Rasoolahum fahum lahoo munkiroon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>70,'arabic_text'=>'أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ','transliteration'=>'Am yaqooloona bihee jinnnah; bal jaaa\'ahum bilhaqqi Wa-aksaruhum lil-haqqi kaarihoon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>71,'arabic_text'=>'وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ','transliteration'=>'Wa-lawit taba\'al haqqu ahwaaa\'ahum lafasadatis samaawaatu wal-ardu Wa-man feehinnn; bal atainaahum bizikrihim fahum \'an zikrihim mu\'ridoon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>72,'arabic_text'=>'أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ','transliteration'=>'Am tas\'aluhum kharjan fakharaaju Rabbika khairunw Wa-Huwa khairur raaziqeen','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>73,'arabic_text'=>'وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-innaka latad\'oohum ilaa Siraatim Mustaqeem','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>74,'arabic_text'=>'وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ','transliteration'=>'Wa-innnal lazeena laa yu\'minoona bil-Aakhirati \'anis siraati lanaakiboon','page_number'=>346,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>75,'arabic_text'=>'۞ وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','transliteration'=>'Wa-law rahimnaahum Wa-kashafnaa maa bihim min durril lalajjoo fee tughyaanihim ya\'mahoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>76,'arabic_text'=>'وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ','transliteration'=>'Wa-laqad akhaznaahum bil\'azaabi famas takaanoo li-Rabbihim Wa-maa yatadarra\'oon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>77,'arabic_text'=>'حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ','transliteration'=>'Hattaaa izaa fatahnaa \'alaihim baaban zaa \'azaabin shadeedin izaa hum feehi mublisoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>78,'arabic_text'=>'وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ','transliteration'=>'Wa-Huwal lazeee ansha-a lakumus sam\'a wal-absaara wal-af\'idah; qaleelam maa tashkuroon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>79,'arabic_text'=>'وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Wa-Huwal lazee zara-akum fil ardi Wa-ilaihi tuhsharoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>80,'arabic_text'=>'وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Wa-Huwal lazee yuhyee Wa-yumeetu Wa-lahukh tilaaful laili wannahaar; afalaa ta\'qiloon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>81,'arabic_text'=>'بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ','transliteration'=>'Bal qaaloo misla maa qaalal awwaloon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>82,'arabic_text'=>'قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ','transliteration'=>'Qaalooo \'a-izaa mitnaa Wa-kunnaa turaabanw Wa-\'izaaman \'a-innaa lamab-\'oosoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>83,'arabic_text'=>'لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Laqad wu\'idnaa nahnu Wa-aabaaa\'unaa haazaa min qablu in haazaaa illaaa asaateerul awwaleen','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>84,'arabic_text'=>'قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Qul limanil ardu Wa-man feehaaa in kuntum ta\'lamoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>85,'arabic_text'=>'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Sa-yaqooloona lillaah; qul afalaa tazakkkaroon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>86,'arabic_text'=>'قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ','transliteration'=>'Qul mar Rabbus samaawaatis sab\'i Wa-Rabbul \'Arshil \'Azeem','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>87,'arabic_text'=>'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ','transliteration'=>'Sa-yaqooloona lillaah; qul afalaa tattaqoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>88,'arabic_text'=>'قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Qul mam bi-yadihee malakootu kulli shai\'inw Wa-Huwa yujeeru Wa-laa yujaaru \'alaihi in kuntum ta\'lamoon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>89,'arabic_text'=>'سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ','transliteration'=>'Sa-yaqooloona lillaah; qul fa-annaa tus-haroon','page_number'=>347,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>90,'arabic_text'=>'بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Bal atainaahum bil-haqqi Wa-innahum lakaaziboon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>91,'arabic_text'=>'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ','transliteration'=>'Mat takhazal laahu minw waladinw Wa-maa kaana ma\'ahoo min ilaah; izal lazahaba kullu ilaahim bimaa khalaqa Wa-la\'alaa ba\'duhum \'alaa ba\'d; Subhaannal laahi \'ammaa yasifoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>92,'arabic_text'=>'عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Aalimil Ghaibi wash-shahhaadati fata\'aalaa \'ammaa yushrikoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>93,'arabic_text'=>'قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ','transliteration'=>'Qur Rabbi immmaa turiyannee maa yoo\'adoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>94,'arabic_text'=>'رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Rabbi falaa taj\'alnee fil qawmiz zaalimeen','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>95,'arabic_text'=>'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ','transliteration'=>'Wa-innaa \'alaaa an nuriyaka maa na\'iduhum laqaadiroon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>96,'arabic_text'=>'ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ','transliteration'=>'Idfa\' billate hiya ahsanus saiyi\'ah; nahnu a\'lamu bimaa yasifoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>97,'arabic_text'=>'وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ','transliteration'=>'Wa-qur Rabbi a\'oozu bika min hamazaatish Shayaateen','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>98,'arabic_text'=>'وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ','transliteration'=>'Wa-a\'oozu bika Rabbi aien yahduroon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>99,'arabic_text'=>'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ','transliteration'=>'Hattaaa izaa jaaa\'a ahada-humul mawtu qaala Rabbir ji\'oon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>100,'arabic_text'=>'لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كـَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','transliteration'=>'La\'alleee a\'malu saalihan feemaa taraktu kallaa; innahaa kalimatun huwa qaaa\'iluhaa Wa-minw waraaa\'ihim barzakhun ilaa Yawmi yub\'asoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>101,'arabic_text'=>'فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ','transliteration'=>'Fa-izaa nufikha fis Soori falaaa ansaaba bainahum yawma\'izinw Wa-laa yatasaaa\'aloon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>102,'arabic_text'=>'فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Faman saqulat mawaazee-nuhoo fa-ulaaa\'ika humul muflihoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>103,'arabic_text'=>'وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ','transliteration'=>'Wa-man khaffat mawaa-zeenuhoo fa-ulaaa\'ikal lazeena khasiroo \'anfusahum fee Jahannama khaalidoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>104,'arabic_text'=>'تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ','transliteration'=>'Talfahu wujoohahumun Naaru Wa-hum feehaa kaalihoon','page_number'=>348,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>105,'arabic_text'=>'أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ','transliteration'=>'Alam takun Aayaatee tutlaa \'alaikum fakuntum bihaa tukazziboon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>106,'arabic_text'=>'قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ','transliteration'=>'Qaaloo Rabbanaa ghalabat \'alainaa shiqwatunaa Wa-kunnaa qawman daaalleen','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>107,'arabic_text'=>'رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ','transliteration'=>'Rabbanaa akhrijnaa minhaa fa-in \'udnaa fa-innaa zaalimoon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>108,'arabic_text'=>'قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ','transliteration'=>'Qaalakh sa\'oo feehaa Wa-laa tukallimoon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>109,'arabic_text'=>'إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ','transliteration'=>'Innahoo kaana fareequm min \'ibaadee yaqooloona Rabbanaaa aamannaa faghfir lanaa warhamnaa Wa-Anta khairur raahimeen','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>110,'arabic_text'=>'فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ','transliteration'=>'Fattakhaztumoohum sikhriyyan hattaaa ansawkum zikree Wa-kuntum minhum tadhakoon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>111,'arabic_text'=>'إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ','transliteration'=>'Inee jazaituhumul Yawma bimaa sabarooo annahum humul faaa\'izoon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>112,'arabic_text'=>'قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ','transliteration'=>'Qaala kam labistum fil ardi \'adada sineen','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>113,'arabic_text'=>'قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ','transliteration'=>'Qaaloo labisnaa yawman aw ba\'da yawmin fas\'alil \'aaaddeen','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>114,'arabic_text'=>'قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Qaala il labistum illaa qaleelal law annakum kuntum ta\'lamoon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>115,'arabic_text'=>'أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ','transliteration'=>'Afahsibtum annamaa khalaqnaakum \'abasanw Wa-annakum ilainaa laa turja\'oon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>116,'arabic_text'=>'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ','transliteration'=>'Fata\'aalal laahul Malikul Haqq; laaa ilaaha illaa Huwa Rabbul \'Arshil Kareem','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>117,'arabic_text'=>'وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ','transliteration'=>'Wa-maien yad\'u ma\'allaahi ilaahan aakhara laa burhaana lahoo bihee fa-inna maa hisaabuhoo \'inda Rabbih; innahoo laa yuflihul kaafiroon','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>23,'ayah_number'=>118,'arabic_text'=>'وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ','transliteration'=>'Wa-qul Rabbigh fir warham Wa-Anta khairur raahimeen','page_number'=>349,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            /* Surah 24: The Light (An-Noor) */
            ['surah_id'=>24,'ayah_number'=>1,'arabic_text'=>'سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتٖ لَّعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Sooratun anzalnaahaa Wa-faradnaahaa Wa-anzalnaa feehaaa Aayaatim baiyinaatil la\'allakum tazakkaroon','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>2,'arabic_text'=>'ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Azzaaniyatu wazzaanee fajlidoo kulla waahidim minhumaa mi\'ata jaldatinw Wa-laa taakhuzkum bihimaa raafatun fee deenil laahi in kuntum tu\'minoona billaahi wal-Yawmil Aakhiri wal-yashhad \'azaabahumaa taaa\'ifatum minal mu\'mineen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>3,'arabic_text'=>'ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ','transliteration'=>'Azzaanee laa yankihu illaa zaaniyatan aw mushrikatanw wazzaaniyatu laa yankihuhaaa illaa zaanin aw mushrik; Wa-hurrima zaalika \'alal mu\'mineen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>4,'arabic_text'=>'وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Wallazeena yarmoonal muhsanaati summa lam yaatoo bi-arba\'ati shuhadaaa\'a fajlidoohum samaaneena jaldatanw Wa-laa taqbaloo lahum shahaadatan abadaa; Wa-ulaaa\'ika humul faasiqoon','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>5,'arabic_text'=>'إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Illal lazeena taaboo mim ba\'di zaalika Wa-aslahoo fa-innal laaha Ghafoorur Raheem','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>6,'arabic_text'=>'وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Wallazeena yarmoona azwaajahum Wa-lam yakul lahum shuhadaaa\'u illaaa anfusuhum fashahaadatu ahadihim arba\'u shahaadaatim billaahi innahoo laminas saadiqeen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>7,'arabic_text'=>'وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Wal-khaamisatu anna la\'natal laahi \'alaihi in kaana minal kaazibeen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>8,'arabic_text'=>'وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Wa-yadra\'u anhal \'azaaba an tashhada arba\'a shahaa-daatim billaahi innahoo laminal kaazibeen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>9,'arabic_text'=>'وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Wal-khaamisata anna ghadabal laahi \'alaihaaa in kaana minas saadiqeen','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>10,'arabic_text'=>'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ','transliteration'=>'Wa-law-laa fadlul laahi \'alaikum Wa-rahmatuhoo Wa-annal laaha Tawwaabun Hakeem','page_number'=>350,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>11,'arabic_text'=>'إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ','transliteration'=>'Innal lazeena jaaa\'oo bilifki \'usbatum minkum; laa tahsaboohu sharral lakum bal huwa khairul lakum; likul limri\'im minhum mak tasaba minal ism; wallazee tawallaa kibrahoo minhum lahoo \'azaabun \'azeem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>12,'arabic_text'=>'لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ','transliteration'=>'Law-laaa iz sami\'tumoohu zannal mu\'minoona walmu\'minaatu bi-anfusihim khairanw Wa-qaaloo haazaaa ifkum mubeen','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>13,'arabic_text'=>'لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ','transliteration'=>'Law-laa jaaa\'oo \'alaihi bi-arba\'ati shuhadaaa\'; fa-iz lam yaatoo bishshuhadaaa\'i fa-ulaaa-\'ika \'indal laahi humul kaaziboon','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>14,'arabic_text'=>'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ','transliteration'=>'Wa-law-laa fadlul laahi \'alaikum Wa-rahmatuhoo fiddunyaa wal aakhirati lamassakum fee maaa afadtum feehi \'azaabun \'azeem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>15,'arabic_text'=>'إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ','transliteration'=>'Iz talaqqawnahoo bi-alsinatikum Wa-taqooloona bi-afwaahikum maa laisa lakum bihee \'ilmunw Wa-tahsaboo-nahoo haiyinanw Wa-huwa \'indal laahi \'azeem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>16,'arabic_text'=>'وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ','transliteration'=>'Wa-law-laaa iz sami\'tu-moohu qultum maa yakoonu lanaaa an natakallama bihaazaa Subhaanaka haaza buhtaanun \'azeem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>17,'arabic_text'=>'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Ya\'izukumul laahu an ta\'oodoo limisliheee abadan in kuntum mu\'mineen','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>18,'arabic_text'=>'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','transliteration'=>'Wa-yubaiyinul laahu lakumul Aayaat; wallaahu \'Aleemun Hakeem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>19,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Innal lazeena yuhibboona an tashee\'al faahishatu fil lazeena aamanoo lahum \'azaabun aleemun fid dunyaa wal-Aakhirah; wallaahu ya\'lamu Wa-antum laa ta\'lamoon','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>20,'arabic_text'=>'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٞ رَّحِيمٞ','transliteration'=>'Wa-law-laa fadlul laahi \'alaikum Wa-rahmatuhoo Wa-annal laaha Ra\'oofur Raheem','page_number'=>351,'juz_number'=>18,'hizb_number'=>35,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>21,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ','transliteration'=>'Yaaa aiyyuhal lazeena aamanoo laa tattabi\'oo khutuwaatish Shaitaan; Wa-many-yattabi\' khutuwaatish Shaitaani fa-innahoo yaamuru bilfahshaaa\'i walmunkar; Wa-law laa fadlul laahi \'alaikum Wa-rahmatuhoo maa zakaa minkum min ahadin abadanw Wa-laakinnal laaha yuzakkee many-yashaaa\'; wallaahu Samee\'un \'Aleem','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>22,'arabic_text'=>'وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ','transliteration'=>'Wa-laa yaatali ulul fadli minkum wassa\'ati ai yu\'tooo ulil qurbaa walmasaakeena walmuhaajireena fee sabeelillaahi walya\'foo walyasfahoo; alaa tuhibboona aien yaghfiral laahu lakum; wal laahu Ghafoorur Raheem','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>23,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ','transliteration'=>'Innal lazeena yarmoonal muhsanaatil ghaafilaatil mu\'minaati lu\'inoo fid dunyaa wal-Aakhirati Wa-lahum \'azaabun \'azeem','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>24,'arabic_text'=>'يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Yawma tashhhadu \'alaihim alsinatuhum Wa-aideehim Wa-arjuluhum bimaa kaanoo ya\'maloon','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>25,'arabic_text'=>'يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ','transliteration'=>'Yawma\'izien yuwaf-feehimul laahu deenahumul haqqa Wa-ya\'lamoona annal laaha Huwal Haqqul Mubeen','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>26,'arabic_text'=>'ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ','transliteration'=>'Al-khabeesaatu lil-khabeeseena wal-khabeesoona lil-khabeesaati wat-taiyibaatu lit-taiyibeena wat-taiyiboona lit-taiyibaat; ulaaa\'ika mubarra\'oona mimma yaqooloona lahum maghfiratunw Wa-rizqun kareem','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>27,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tadkhuloo buyootan ghaira buyootikum hatta tastaanisoo Wa-tusallimoo \'allaa ahlihaa; zaalikum khairul lakum la\'allakum tazakkaroon','page_number'=>352,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>28,'arabic_text'=>'فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ','transliteration'=>'Fa-il lam tajidoo feehaaa ahadan falaa tadkhuloohaa hattaa yu\'zana lakum Wa-in qeela lakumur ji\'oo farji\'oo huwa azkaa lakum; wallaahu bimaa ta\'maloona \'Aleem','page_number'=>353,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>29,'arabic_text'=>'لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ فِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ','transliteration'=>'Laisa \'alaikum junaahun ann tadkhuloo buyootan ghaira maskoonatin feeha mataa\'ul lakum; wallaahu ya\'lamu maa tubdoona Wa-maa taktumoon','page_number'=>353,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>30,'arabic_text'=>'قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ','transliteration'=>'Qul lilmu\' mineena yaghuuddoo min absaarihim Wa-yahfazoo furoojahum; zaalika azkaa lahum; innallaaha khabeerum bimaa yasna\'oon','page_number'=>353,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>31,'arabic_text'=>'وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Wa qul lilmu\'minaati yaghdudna min absaarihinna Wa-yahfazna furoojahunna Wa-laa yubdeena zeenatahunna illaa maa zahara minhaa walyadribna bikhumurihinna \'alaa juyoobihinna Wa-laa yubdeena zeenatahunna illaa libu\'oolatihinna aw aabaaa\'i hinna aw aabaaa\'i bu\'oolati hinna aw abnaaa\'ihinaa aw abnaaa\'i bu\'oolatihinnna aw ikhwaanihinnna aw baneee ikhwaanihinna aw banee akhawaatihinna aw nisaaa\'i hinna aw maa malakat aimaanuhunna awit taabi\'eena ghairi ilil irbati minar rijaali awit tiflillazeena lam yazharoo \'alaa \'awraatin nisaaa\'i wala yadribnna bi arjulihinna min zeenatihinn; Wa-toobooo ilallaahi jammee\'an aiyuhal mu\'minoona la\'allakum tuflihoon','page_number'=>353,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>32,'arabic_text'=>'وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ','transliteration'=>'Wa-ankihul ayaamaa minkum was-saaliheena min \'ibaadikum Wa-imaa\'kum; ien yakoonoo fuqaraaa\'a yughni-himul laahu min fadlih; wal-laahu Waasi\'un \'Aleem','page_number'=>354,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>33,'arabic_text'=>'وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wal-yasta\'fifil lazeena laa yajidoona nikaahan hatta yughniyahumul laahu min fadlih; wallazeena yabtaghoonal kitaaba mimmaa malakat aimaanukum fakaatiboohum in \'alimtum feehim khairanw Wa-aatoohum mim maalil laahil lazeee aataakum; Wa-laa tukrihoo fatayaatikum \'alal bighaaa\'i in aradna tahassunal litabtaghoo \'aradal hayaatid dunyaa; Wa-mai yukrihhunna fa-innal laaha mim ba\'di ikraahihinna Ghafoorur Raheem','page_number'=>354,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>34,'arabic_text'=>'وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتٖ مُّبَيِّنَٰتٖ وَمَثَلٗا مِّنَ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۡ وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ','transliteration'=>'Wa-laqad anzalnaaa ilaikum Aayaatim mubaiyinaatinw Wa-masalam minnal lazeena khalaw min qablikum Wa-maw\'izatal lilmuttaqeen','page_number'=>354,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>35,'arabic_text'=>'۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Allaahu noorus samaawaati wal-ard; masalu noorihee kamishkaatin feehaa misbaah; almisbaahu fee zujaajatin azzujaajatu ka-annahaa kawkabun durriyyuien yooqadu min shajaratim mubaarakatin zaitoonatil laa shariqiyyatinw Wa-laa gharbiyyatien yakaadu zaituhaa yudeee\'u Wa-law lam tamsashu naar; noorun \'alaa noor; yahdil laahu linoorihee mai yashaaa\'; Wa-yadribul laahul amsaala linnaas; wallaahu bikulli shai\'in Aleem','page_number'=>354,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>36,'arabic_text'=>'فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ','transliteration'=>'Fee buyootin azinal laahu an turfa\'a Wa-yuzkara feehas muhoo yusabbihu lahoo feehaa bilghuduwwi wal-aasaal','page_number'=>354,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>37,'arabic_text'=>'رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ','transliteration'=>'Rijaalul laa tulheehim tijaaratunw Wa-laa bai\'un \'an zikril laahi Wa-iqaamis Salaati Wa-eetaaa\'iz Zakaati yakhaafoona Yawman tataqallabu feehil quloobu wal-absaar','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>38,'arabic_text'=>'لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ','transliteration'=>'Liyajziyahumul laahu ahsana maa \'amiloo Wa-yazeedahum min fadlih; wal-laahu yarzuqu maien yashaaa\'u bighairi hisaab','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>39,'arabic_text'=>'وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Wallazeena kafarooo a\'maaluhum kasaraabim biqee\'atien yahsabuhuz zamaanu maaa\'an hattaaa izaa jaaa\'ahoo lam yajid-hu shai\'anw Wa-wajadal laaha \'indahoo fa-waffaahu hisaabah; wallaahu saree\'ul hisaab','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>40,'arabic_text'=>'أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن فَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ','transliteration'=>'Aw kazulumaatin fee bahril lujjiyyiny yaghshaahu mawjun min fawqihee mawjun min fawqihee sahaab; zulumatun ba\'duhaa fawqa ba\'din izaaa akhraja yadahoo lam yakad yaraahaa Wa-man lam yaj\'alil laahu lahoo nooran famaa lahoo min noor','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>41,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ','transliteration'=>'Alam tara annal laaha yusabbihu lahoo man fissamaawaati wal-ardi wat tairu saaaffaatim kullun qad \'alima Salaatahoo Wa-tasbeehah; wallaahu \'aleemum bimaa yaf\'aloon','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>42,'arabic_text'=>'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ','transliteration'=>'Wa-lillaahi mulkus samaawaati wal-ardi Wa-ilal laahil maseer','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>43,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي سَحَابٗا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٖ فِيهَا مِنۢ بَرَدٖ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ','transliteration'=>'Alam tara annal laaha yuzjee sahaaban summa yu\'allifu bainahoo summa yaj\'aluhoo rukaaman fataral wadqa yakhruju min khilaalihee Wa-yunazzilu minas samaaa\'i min jibaalin feehaa mim baradin fa-yuseebu bihee maien yashaaa\'u Wa-yasrifuhoo \'am maien yashaaa\'u yakaadu sanaa barqihee yazhabu bil-absaar','page_number'=>355,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>44,'arabic_text'=>'يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ','transliteration'=>'Yuqallibul laahul laila wannahaar; inna fee zaalika la\'ibratal li-ulil absaar','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>45,'arabic_text'=>'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wallaahu khalaqa kulla daaabbatim mim maaa\'in faminhum mai yamshee \'alaa batnihee Wa-minhum mai yamshee \'alaa rijlaine Wa-minhum maien yamshee \'alaaa arba\'; yakhluqul laahu maa yashaaa\'; innal laaha \'alaa kulli shai\'in Qadeer','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>46,'arabic_text'=>'لَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Laqad anzalnaaa Aayaatim mubaiyinaat; wallaahu yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>47,'arabic_text'=>'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-yaqooloona aamannaa billaahi Wa-bir-Rasooli Wa-ata\'naa summa yatawallaa fareequm minhum mim ba\'di zaalik; Wa-maaa ulaaa\'ika bilmu\'mineen','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>48,'arabic_text'=>'وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ','transliteration'=>'Wa-izaa du\'ooo ilal laahi Wa-Rasoolihee li-yahkuma bainahum izaa fareequm minhum mu\'ridoon','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>49,'arabic_text'=>'وَإِن يَكُن لَّهُمُ ٱلۡحَقُّ يَأۡتُوٓاْ إِلَيۡهِ مُذۡعِنِينَ','transliteration'=>'Wa-ien yakul lahumul haqqu yaatooo ilaihi muz\'ineen','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>50,'arabic_text'=>'أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Afee quloobihim ma-radun amir taabooo am yakhaafoona aien yaheefal laahu \'alaihim Wa-Rasooluh; bal ulaaa\'ika humuz zaalimoon','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>51,'arabic_text'=>'إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Innamaa kaana qawlal mu\'mineena izaa du\'ooo ilal laahi Wa-Rasoolihee li-yahkuma bainahum ai yaqooloo sami\'naa Wa-ata\'naa; Wa-ulaaa\'ika humul muflihoon','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>52,'arabic_text'=>'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ','transliteration'=>'Wa-maien yuti\'il laaha Wa-Rasoolahoo Wa-yakhshal laaha Wa-yattaqhi fa-ulaaa\'ika humul faaa\'izoon','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>53,'arabic_text'=>'۞ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Wa-aqsamoo billaahi jahda aimaanihim la\'in amartahum la-yakhrujunna qul laa tuqsimoo taa\'atum ma\'roofah innal laaha khabeerum bimaa ta\'maloon','page_number'=>356,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>54,'arabic_text'=>'قُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Qul atee\'ul laaha Wa-atee\'ur Rasoola fa-in tawallaw fa-innamaa \'alaihi maa hummila Wa-\'alaikum maa hummiltum Wa-in tutee\'oohu tahtadoo; Wa-maa \'alar Rasooli illal balaaghul mubeen','page_number'=>357,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>55,'arabic_text'=>'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي شَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Wa\'adal laahul lazeena aamanoo minkum Wa-\'amilus saalihaati la-yastakh-lifan-nahum fil ardi kamastakh lafal lazeena min qablihim Wa-la-yumakki-nanna lahum deenahumul lazir tadaa lahum Wa-la-yubaddi-lannahum mim ba\'di khawfihim amnaa; ya\'budoona-nee laa yushrikoona bee shai\'aa; Wa-man kafara ba\'da zaalika fa-ulaaa\'ika humul faasiqoon','page_number'=>357,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>56,'arabic_text'=>'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Wa-aqeemus Salaata Wa-aatuz Zakaata Wa-atee\'ur Rasoola la\'allakum turhamoon','page_number'=>357,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>57,'arabic_text'=>'لَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Laa tahsabannal lazeena kafaroo mu\'jizeena fil ard; Wa-maawaahumun Naaru Wa-labi\'sal maseer','page_number'=>357,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>58,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّٰتٖۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتٖ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضٖۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo li-yasta\'zinkumul lazeena malakat aimaanukum wallazeena lam yablughul huluma minkum salaasa marraat; min qabli Salaatil Fajri Wa-heena tada\'oona siyaa-bakum minaz zaheerati Wa-min ba\'di Salaatil Ishaaa\'; salaasu \'awraatil lakum; laisa \'alaikum Wa-laa \'alaihim junaahun ba\'dahunn; tawwaafoona \'alaikum ba\'dukum \'alaa ba\'d; kazaalika yubaiyyinul laahu lakumul aayaat; wallahu \'Aleemun Hakeem','page_number'=>357,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>59,'arabic_text'=>'وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Wa-izaa balaghal atfaalu minkumul huluma fal-yasta\'zinoo kamas ta\'zanal lazeena min qablihim; kazaalika yubaiyinul laahu lakum Aayaatih; wallaahu \'Aleemun Hakeem','page_number'=>358,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>60,'arabic_text'=>'وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ','transliteration'=>'Walqawaa\'idu minan nisaaa\'il laatee laa yarjoona nikaahan fa-laisa \'alaihinna junaahun aien yada\'na siyaabahunna ghaira mutabarrijaatin bi-zeenah; Wa-aien yasta\'fif-na khairul lahunn; wallaahu Samee\'un \'Aleem','page_number'=>358,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>61,'arabic_text'=>'لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Laisa \'alal a\'maa harajunw Wa-laa \'alal a\'raji harajunw Wa-laa \'alal mareedi harajun Wa-laa \'alaa anfusikum \'an ta\'kuloo min buyootikum aw buyooti aabaaa\'ikum aw buyooti ummahaatikum aw buyooti ikhwaanikum aw buyooti akhawaatikum aw buyooti a\'maamikum aw buyooti \'ammaatikum aw buyooti akhwaalikum aw buyooti khaalaatikum aw maa malaktum mafaatihahooo aw sadeeqikum; laisa \'alaikum junaahun \'an ta\'kuloo jamee\'an aw ashtaata; fa-izaa dakhaltum buyootan fa-sallimoo \'alaaa anfusikum tahiyyatan min \'indil laahi mubaarakatan taiyyibah; kazaalika yubai-yyinul laahu lakumul Aayaati la\'allakum ta\'qiloon','page_number'=>358,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>62,'arabic_text'=>'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Innamal mu\'minoonal lazeena aamanoo billaahi Wa-Rasoolihee Wa-izaa kaanoo ma\'ahoo \'alaaa amrin jaami\'il lam yazhaboo hattaa yasta\'zinooh; innal lazeena yasta\'zinoonaka ulaaa\'ikal lazeena yu\'minoona billaahi Wa-Rasoolih; fa-izas ta\'zanooka li-ba\'di sha\'nihim fa\'zal liman shi\'ta minhum wastaghfir lahumul laah; innal laaha Ghafoorur Raheem','page_number'=>359,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>63,'arabic_text'=>'لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ','transliteration'=>'Laa taj\'aloo du\'aaa\'ar Rasooli bainakum ka-du\'aaa\'i ba\'dikum ba\'daa; qad ya\'lamul laahul lazeena yatasallaloona minkum liwaazaa; fal-yahzaril lazeena yukhaalifoona \'an amriheee \'an tuseebahum fitnatun aw yuseebahum \'azaabun aleem','page_number'=>359,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>24,'ayah_number'=>64,'arabic_text'=>'أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ','transliteration'=>'Alaaa inna lillaahi maa fis samaawaati wal-ardi qad ya\'lamu maaa antum \'alaihi Wa-Yawma yurja\'oona ilaihi fa-yunabbi\'uhum bimaa \'amiloo; wallaahu bikulli shai\'in \'Aleem','page_number'=>359,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            /* Surah 25: The Criterion (Al-Furqan) */
            ['surah_id'=>25,'ayah_number'=>1,'arabic_text'=>'تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا','transliteration'=>'Tabaarakal lazee nazzalal Furqaana \'alaa \'abdihee li-yakoona lil\'aalameena nazeera','page_number'=>359,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>2,'arabic_text'=>'ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا','transliteration'=>'Allazee lahoo mulkus samaawaati wal ardi Wa-lam yattakhiz waladanw Wa-lam yakul lahoo shareekun filmulki Wa-khalaqa kulla shai\'in faqaddarahoo taqdeeraa','page_number'=>359,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>3,'arabic_text'=>'وَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا','transliteration'=>'Wattakhazoo min dooniheee aalihatal laa yakhluqoona shai\'anw Wa-hum yukhlaqoona Wa-laa yamlikoona li-anfusihim darranw Wa-laa naf\'anw Wa-laa yamlikoona mawtanw Wa-laa hayaatanw Wa-laa nushooraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>4,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمٗا وَزُورٗا','transliteration'=>'Wa-qaalal lazeena kafarooo in haazaaa illaaa ifkunif taraahu Wa-a\'aanahoo \'alaihi qawmun aakharoona faqad jaaa\'oo zulmanw Wa-zooraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>5,'arabic_text'=>'وَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا','transliteration'=>'Wa-qaalooo asaateerul awwaleenak tatabahaa fahiya tumlaa \'alaihi bukratanw Wa-aseelaa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>6,'arabic_text'=>'قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Qul anzalhul lazee ya\'lamus sirra fis samaawaati wal-ard; innahoo kaana Ghafoorar Raheemaa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>7,'arabic_text'=>'وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ لَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكٞ فَيَكُونَ مَعَهُۥ نَذِيرًا','transliteration'=>'Wa-qaaloo maa-li haazar Rasooli ya\'kulut ta\'aama Wa-yamshee fil aswaaq; law-laaa unzila ilaihi malakun fa-yakoona ma\'ahoo nazeeraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>8,'arabic_text'=>'أَوۡ يُلۡقَىٰٓ إِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةٞ يَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا','transliteration'=>'Aw yulqaaa ilaihi kanzun aw takoonu lahoo jannatuien ya\'kulu minhaa; Wa-qaalaz zaalimoona in tattabi\'oona illaa rajulan mas-hooraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>9,'arabic_text'=>'ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَٰلَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا','transliteration'=>'Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee\'oona sabeelaa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>10,'arabic_text'=>'تَبَارَكَ ٱلَّذِيٓ إِن شَآءَ جَعَلَ لَكَ خَيۡرٗا مِّن ذَٰلِكَ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَيَجۡعَل لَّكَ قُصُورَۢا','transliteration'=>'Tabaarakal lazeee in shaaa\'a ja\'ala laka khairan min zaalika jannaatin tajree min tahtihal anhaaru Wa-yaj\'al laka qusooraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>11,'arabic_text'=>'بَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا','transliteration'=>'Bal kazzaboo bis-Saa\'ati Wa-a\'tadnaa liman kazzaba bis-Saa\'ati sa\'eeraa','page_number'=>360,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>12,'arabic_text'=>'إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا','transliteration'=>'Izaa ra\'at-hum min makaanin ba\'eedin sami\'oo lahaa taghaiyuzanw Wa-zafeeraa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>13,'arabic_text'=>'وَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورٗا','transliteration'=>'Wa-izaaa ulqoo minhaa makaanan daiyyiqam muqar-raneena da\'aw hunaalika thuboora','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>14,'arabic_text'=>'لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورٗا وَٰحِدٗا وَٱدۡعُواْ ثُبُورٗا كَثِيرٗا','transliteration'=>'Laa tad\'ul yawma thubooranw waahidanw wad\'oo thubooran kaseeraa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>15,'arabic_text'=>'قُلۡ أَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَآءٗ وَمَصِيرٗا','transliteration'=>'Qul azaalika khairun am Jannatul khuldil latee wu\'idal muttaqoon; kaanat lahum jazaaa\'anw Wa-maseeraa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>16,'arabic_text'=>'لَّهُمۡ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدٗا مَّسۡـُٔولٗا','transliteration'=>'Lahum feehaa maa yashaaa\'oona khaalideen; kaana \'alaa Rabbika wa\'dan mas\'oolaa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>17,'arabic_text'=>'وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ','transliteration'=>'Wa-Yawma yahshuruhum Wa-maa ya\'budoona min doonil laahi fa-yaqoolu \'a-antum adlaltum \'ibaadee haaa\'ulaaa\'i am hum dallus sabeel','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>18,'arabic_text'=>'قَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا','transliteration'=>'Qaaloo Subhaanaka maa kaana yanbaghee lanaaa an nattakhiza min doonika min awliyaaa\'a Wa-laakin matta\'tahum Wa-aabaaa\'ahum hattaa nasooz zikra Wa-kaanoo qawman booraa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>19,'arabic_text'=>'فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفٗا وَلَا نَصۡرٗاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابٗا كَبِيرٗا','transliteration'=>'Faqad kazzabookum bimaa taqooloona famaa tastatee\'oona sarfanw Wa-laa nasraa; Wa-many yazlim minkum nuziqhu \'azaaban kabeeraa','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>20,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِينَ إِلَّآ إِنَّهُمۡ لَيَأۡكُلُونَ ٱلطَّعَامَ وَيَمۡشُونَ فِي ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا','transliteration'=>'Wa-maaa arsalnaa qablaka minal mursaleena illaaa innahum la-ya\'kuloonat ta\'aama Wa-yamshoona fil aswaaq; Wa-ja\'alnaa ba\'dakum liba\'din fitnatan atasbiroon; Wa-kaana Rabbuka Baseera','page_number'=>361,'juz_number'=>18,'hizb_number'=>36,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>21,'arabic_text'=>'۞ وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَٰٓئِكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوّٗا كَبِيرٗا','transliteration'=>'Wa-qaalal lazeena laa yarjoona liqaaa\'anaa law-laaa unzila \'alainal malaaa\'ikatu aw naraa Rabbanaa; laqadis takbaroo feee anfusihim Wa-\'ataw \'utuwwan kabeeraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>22,'arabic_text'=>'يَوۡمَ يَرَوۡنَ ٱلۡمَلَٰٓئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِذٖ لِّلۡمُجۡرِمِينَ وَيَقُولُونَ حِجۡرٗا مَّحۡجُورٗا','transliteration'=>'Yawma yarawnal malaaa-\'ikata laa bushraa Yawmaizin lil-mujrimeena Wa-yaqooloona hijran mahjooraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>23,'arabic_text'=>'وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا','transliteration'=>'Wa qadimnaaa ilaa maa \'amiloo min \'amalin faja\'alnaahuhabaaa\'an manthooraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>24,'arabic_text'=>'أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرٞ مُّسۡتَقَرّٗا وَأَحۡسَنُ مَقِيلٗا','transliteration'=>'As-haabul jannati yawma\'izin khairun mustaqar-ranw Wa-ahsanu maqeela','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>25,'arabic_text'=>'وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَٰمِ وَنُزِّلَ ٱلۡمَلَٰٓئِكَةُ تَنزِيلًا','transliteration'=>'Wa-Yawma tashaqqaqus samaaa\'u bilghamaami Wa-nuzzilal malaaa\'ikatu tanzeela','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>26,'arabic_text'=>'ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ وَكَانَ يَوۡمًا عَلَى ٱلۡكَٰفِرِينَ عَسِيرٗا','transliteration'=>'Almulku Yawma\'izinil haqqu lir Rahmaan; Wa-kaana Yawman\'alal kaafireena \'aseeraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>27,'arabic_text'=>'وَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا','transliteration'=>'Wa-Yawma ya\'adduz zaalimu \'alaa yadaihi yaqoolu yaa-laitanit takhaztu ma\'ar Rasooli sabeelaa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>28,'arabic_text'=>'يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا','transliteration'=>'Yaa-wailataa laitanee lam attakhiz fulaanan khaleelaa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>29,'arabic_text'=>'لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا','transliteration'=>'Laqad adallanee \'aniz zikri ba\'da iz jaaa\'anee; Wa-kaanash Shaitaanu lil-insaani khazoolaa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>30,'arabic_text'=>'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورٗا','transliteration'=>'Wa-qaalar Rasoolu yaa-Rabbi inna qawmit takhazoo haazal Qur\'aana mahjooraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>31,'arabic_text'=>'وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا','transliteration'=>'Wa-kazaalika ja\'alnaa likulli Nabiyyin \'aduwwan minal mujrimeen; Wa-kafaa bi-Rabbika haadiyanw Wa-naseeraa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>32,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا','transliteration'=>'Wa-qaalal lazeena kafaroo law-laa nuzzila \'alaihil Qur\'aanu jumlatanw waahidah; kazaalika linusabbita bihee fu\'aadaka Wa-rattalnaahu tarteelaa','page_number'=>362,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>33,'arabic_text'=>'وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا','transliteration'=>'Wa-laa ya\'toonaka bi-masalin illaa ji\'naaka bilhaqqi Wa-ahsana tafseeraa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>34,'arabic_text'=>'ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا','transliteration'=>'Allazeena yuhsharoona \'alaa wujoohihim ilaa jahannama ulaaa\'ika sharrun makaananw Wa-adallu sabeelaa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>35,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرٗا','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba Wa-ja\'alnaa ma\'ahooo akhaahu Haaroona wazeeraa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>36,'arabic_text'=>'فَقُلۡنَا ٱذۡهَبَآ إِلَى ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا فَدَمَّرۡنَٰهُمۡ تَدۡمِيرٗا','transliteration'=>'Faqulnaz habaaa ilal qawmil lazeena kazzaboo bi-Aayaatinaa fadammarnaahum tadmeeraa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>37,'arabic_text'=>'وَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمٗا','transliteration'=>'Wa-qawma Noohin lammaa kazzabur Rusula aghraqnaahum Wa-ja\'alnaahum linnaasi Aayatanw Wa-a\'tadnaa lizzaalimeena \'azaaban aleemaa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>38,'arabic_text'=>'وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا','transliteration'=>'Wa-\'Aadanw Wa-Samooda Wa-As-haabar Rassi Wa-quroonan baina zaalika katheeraa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>39,'arabic_text'=>'وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا','transliteration'=>'Wa-kullan darabnaa lahul amsaala Wa-kullan tabbarnaa tatbeera','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>40,'arabic_text'=>'وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا','transliteration'=>'Wa-laqad ataw \'alal qaryatil lateee umtirat mataras saw\'; afalam yakoonoo yarawnahaa; bal kaanoo laa yarjoona nushooraa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>41,'arabic_text'=>'وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا','transliteration'=>'Wa-izaa ra-awka ien yattakhizoonaka illaa huzuwan ahaazal lazee ba\'asal laahu Rasoolaa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>42,'arabic_text'=>'إِن كَادَ لَيُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَآ أَن صَبَرۡنَا عَلَيۡهَاۚ وَسَوۡفَ يَعۡلَمُونَ حِينَ يَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِيلًا','transliteration'=>'In kaada la-yudillunaa \'an aalihatinaa law-laaa an sabarnaa \'alaihaa; Wa-sawfa ya\'lamoona heena yarawnal \'azaaba man adallu sabeela','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>43,'arabic_text'=>'أَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا','transliteration'=>'Ara\'aita manit takhaza ilaahahoo hawaahu afa-anta takoonu \'alaihi wakeelaa','page_number'=>363,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>44,'arabic_text'=>'أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا','transliteration'=>'Am tahsabu anna aksarahum yasma\'oona aw ya\'qiloon; in hum illaa kal-an\'aami bal hum adallu sabeelaa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>45,'arabic_text'=>'أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا','transliteration'=>'Alam tara ilaa Rabbika kaifa maddaz zilla Wa-law shaaa\'a la-ja\'alahoo saakinan thumma ja\'alnash shamsa \'alaihi daleelaa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>46,'arabic_text'=>'ثُمَّ قَبَضۡنَٰهُ إِلَيۡنَا قَبۡضٗا يَسِيرٗا','transliteration'=>'Thumma qabadnaahu ilainaa qabdany yaseeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>47,'arabic_text'=>'وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِبَاسٗا وَٱلنَّوۡمَ سُبَاتٗا وَجَعَلَ ٱلنَّهَارَ نُشُورٗا','transliteration'=>'Wa-Huwal lazee ja\'ala lakumul laila libaasanw wannawma subaatanw Wa-ja\'alan nahaara nushooraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>48,'arabic_text'=>'وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا','transliteration'=>'Wa-Huwal lazeee arsalar riyaaha bushran baina yadai rahmatih; Wa-anzalnaa minas samaaa\'i maaa\'an tahooraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>49,'arabic_text'=>'لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةٗ مَّيۡتٗا وَنُسۡقِيَهُۥ مِمَّا خَلَقۡنَآ أَنۡعَٰمٗا وَأَنَاسِيَّ كَثِيرٗا','transliteration'=>'Linuhyiya bihee baldatan maitanw-wa nusqiyahoo mimmaa khalaqnaaa an\'aamanw Wa-anaasiyya katheeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>50,'arabic_text'=>'وَلَقَدۡ صَرَّفۡنَٰهُ بَيۡنَهُمۡ لِيَذَّكَّرُواْ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا','transliteration'=>'Wa-laqad sarrafnaahu bainahum li-yazzakkaroo fa-abaaa aksarun naasi illaa kufooraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>51,'arabic_text'=>'وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا','transliteration'=>'Wa-law shi\'naa laba\'asnaa fee kulli qaryatin nazeeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>52,'arabic_text'=>'فَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا','transliteration'=>'Falaa tuti\'il kaafireena Wa-jaahidhum bihee jihaadan kabeeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>53,'arabic_text'=>'۞ وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا وَحِجۡرٗا مَّحۡجُورٗا','transliteration'=>'Wa-Huwal lazee marajal bahraini haazaa \'azbun furaatunw Wa-haazaa milhun ujaaj; Wa-ja\'ala bainahumaa barzakhanw Wa-hijran mahjooraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>54,'arabic_text'=>'وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرٗا فَجَعَلَهُۥ نَسَبٗا وَصِهۡرٗاۗ وَكَانَ رَبُّكَ قَدِيرٗا','transliteration'=>'Wa-Huwal lazee khalaqa minal maaa\'i basharan fa-ja\'alahoo nasaban Wa-sihraa; Wa-kaana Rabbuka Qadeeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>55,'arabic_text'=>'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا','transliteration'=>'Wa-ya\'budoona min doonil laahi maa laa yanfa\'uhum Wa-laa yadurruhum; Wa-kaanal kaafiru \'alaa Rabbihee zaheeraa','page_number'=>364,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>56,'arabic_text'=>'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا','transliteration'=>'Wa-maa arsalnaaka illaa mubashshiranw Wa-nazeeraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>57,'arabic_text'=>'قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا','transliteration'=>'Qul maaa as\'alukum \'alaihi min ajrin illaa man shaaa\'a ai yattakhiza ilaa Rabbihee sabeelaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>58,'arabic_text'=>'وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا','transliteration'=>'Wa-tawakkal \'alal Haiyil lazee laa yamootu Wa-sabbih bihamdih; Wa-kafaa bihee bizunoobi \'ibaadihee khabeeraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>59,'arabic_text'=>'ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ فَسۡـَٔلۡ بِهِۦ خَبِيرٗا','transliteration'=>'Allazee khalaqas samaawaati wal-arda Wa-maa bainahumaa fee sittati aiyaamin thumma stawaa \'alal \'Arsh; ar-Rahmaanu fas\'al bihee khabeeraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>60,'arabic_text'=>'وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا','transliteration'=>'Wa-izaa qeela lahumus judoo lir-Rahmaani qaaloo Wa-mar Rahmaanu \'a-nasjudu limaa ta\'murunaa Wa-zaadahum nufooraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>true],
            ['surah_id'=>25,'ayah_number'=>61,'arabic_text'=>'تَبَارَكَ ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجٗا وَجَعَلَ فِيهَا سِرَٰجٗا وَقَمَرٗا مُّنِيرٗا','transliteration'=>'Tabaarakal lazee ja\'ala fis samaaa\'i buroojanw Wa-ja\'ala feehaa siraajanw Wa-qamaran muneeraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>62,'arabic_text'=>'وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا','transliteration'=>'Wa-huwal lazee ja\'alal laila wannahaara khilfatan liman araada \'any yazzakkara aw araadaa shukooraa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>63,'arabic_text'=>'وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا','transliteration'=>'Wa-\'ibaadur Rahmaanil lazeena yamshoona \'alal ardi hawnanw Wa-izaa khaata-bahumul jaahiloona qaaloo salaamaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>64,'arabic_text'=>'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا','transliteration'=>'Wallazeena yabeetoona li-Rabbihim sujjadanw Wa-qiyaamaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>65,'arabic_text'=>'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا','transliteration'=>'Wallazeena yaqooloona Rabbanas rif \'annaa \'azaaba Jahannama inna \'azaabahaa kaana gharaamaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>66,'arabic_text'=>'إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا','transliteration'=>'Innahaa saaa\'at mustaqarranw Wa-muqaamaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>67,'arabic_text'=>'وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا','transliteration'=>'Wallazeena izaaa anfaqoo lam yusrifoo Wa-lam yaqturoo Wa-kaana baina zaalika qawaamaa','page_number'=>365,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>68,'arabic_text'=>'وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا','transliteration'=>'Wallazeena laa yad\'oona ma\'al laahi ilaahan aakhara Wa-laa yaqtuloonan nafsal latee harramal laahu illaa bilhaqqi Wa-laa yaznoon; Wa-mai yaf\'al zaalika yalqa \'athaamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>69,'arabic_text'=>'يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا','transliteration'=>'Yudaa\'af lahul \'azaabu Yawmal Qiyaamati Wa-yakhlud feehee muhaanaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>70,'arabic_text'=>'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Illaa man taaba Wa-\'aamana Wa-\'amila \'amalan saalihan fa-ulaaa\'ika yubad-dilul laahu saiyyi-aatihim hasanaat; Wa-kaanal laahu Ghafoorar Raheemaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>71,'arabic_text'=>'وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا','transliteration'=>'Wa-man taaba Wa-\'amila saalihan fa-innahoo yatoobu ilal laahi mataabaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>72,'arabic_text'=>'وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا','transliteration'=>'Wallazeena laa yash-hadoonaz zoora Wa-izaa marroo billaghwi marroo kiraamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>73,'arabic_text'=>'وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا','transliteration'=>'Wallazeena izaa zukkiroo bi-Aayaati Rabbihim lam yakhirroo \'alaihaa summanw wa\'umyaanaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>74,'arabic_text'=>'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا','transliteration'=>'Wallazeena yaqooloona Rabbanaa hab lanaa min azwaajinaa Wa-zurriyaatinaa qurrata a\'yuninw waj-\'alnaa lilmuttaqeena Imaamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>75,'arabic_text'=>'أُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا','transliteration'=>'Ulaaa\'ika yujzawnal ghurfata bimaa sabaroo Wa-yulaqqawna feehaa tahiyyatanw Wa-salaamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>76,'arabic_text'=>'خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا','transliteration'=>'Khaalideena feehaa; hasunat mustaqarranw Wa-muqaamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>25,'ayah_number'=>77,'arabic_text'=>'قُلۡ مَا يَعۡبَؤُاْ بِكُمۡ رَبِّي لَوۡلَا دُعَآؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا','transliteration'=>'Qul maa ya\'ba\'u bikum Rabbee law-laa du\'aaa\'ukum faqad kazzabtum fasawfa yakoonu lizaamaa','page_number'=>366,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            /* Surah 26: The Poets (Ash-Shu'ara) */
            ['surah_id'=>26,'ayah_number'=>1,'arabic_text'=>'طسٓمٓ','transliteration'=>'Taa-Seeen-Meeem','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>2,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ','transliteration'=>'Tilka Aayaatul Kitaabil Mubeen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>3,'arabic_text'=>'لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ','transliteration'=>'La\'allaka baakhi\'un nafsaka allaa yakoonoo mu\'mineen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>4,'arabic_text'=>'إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ','transliteration'=>'In nashaa nunazzil \'alaihim minas samaaa\'i Aayatan fazallat a\'naaquhum lahaa khaadi\'een','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>5,'arabic_text'=>'وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ','transliteration'=>'Wa-maa yaateehim min zikrim minar Rahmaani muhdasin illaa kaanoo \'anhu mu\'rideen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>6,'arabic_text'=>'فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Faqad kazzaboo fasa-yaateehim ambaaa\'u maa kaanoo bihee yastahzi\'oon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>7,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ','transliteration'=>'Awa-lam yaraw ilal ardi kam ambatnaa feehaa min kulli zawjin kareem','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>8,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ','transliteration'=>'Inna fee zaalika la-Aayah; Wa-maa kaana aksaruhum mu\'mineen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>9,'arabic_text'=>'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ','transliteration'=>'Wa-inna Rabbaka la-Huwal \'Azeezur Raheem','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>10,'arabic_text'=>'وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-iz naadaa Rabbuka Moosaaa ani\' til qawmaz zaalimeen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>11,'arabic_text'=>'قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ','transliteration'=>'Qawma Fir\'awn; alaa yattaqoon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>12,'arabic_text'=>'قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ','transliteration'=>'Qaala Rabbi inneee akhaafu ai yukazziboon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>13,'arabic_text'=>'وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ','transliteration'=>'Wa-yadeequ sadree Wa-laa yantaliqu lisaanee fa-arsil ilaa Haaroon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>14,'arabic_text'=>'وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ','transliteration'=>'Wa-lahum \'alaiya zambun fa-akhaafu ai yaqtuloon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>15,'arabic_text'=>'قَالَ كـَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ','transliteration'=>'Qaala kallaa fazhabaa bi-Aayaatinaaa innaa ma\'akum mustami\'oon','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>16,'arabic_text'=>'فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Faatiyaa Fir\'awna faqoolaaa innaa Rasoolu Rabbil \'aalameen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>17,'arabic_text'=>'أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'An arsil ma\'anaa Baneee Israaa\'eel','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>18,'arabic_text'=>'قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ','transliteration'=>'Qaala alam nurabbika feenaa waleedanw Wa-labista feenaa min \'umurika sineen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>19,'arabic_text'=>'وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-fa\'alta fa\'latakal latee fa\'alta Wa-anta minal kaafireen','page_number'=>367,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>20,'arabic_text'=>'قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ','transliteration'=>'Qaala fa\'altuhaaa izanw Wa-ana minad daaaleen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>21,'arabic_text'=>'فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ','transliteration'=>'Fafarartu minkum lam-maa khiftukum fawahaba lee Rabbee hukmanw Wa-ja\'alanee minal mursaleen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>22,'arabic_text'=>'وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'Wa-tilka ni\'matun tamun-nuhaa \'alaiya an \'abbatta Baneee Israaa\'eel','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>23,'arabic_text'=>'قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaala Fir\'awnu Wa-maa Rabbul \'aalameen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>24,'arabic_text'=>'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ','transliteration'=>'Qaala Rabbus samaawaati wal-ardi Wa-maa bainahumaa in kuntum mooqineen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>25,'arabic_text'=>'قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ','transliteration'=>'Qaala liman hawlahooo alaa tastami\'oon','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>26,'arabic_text'=>'قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ','transliteration'=>'Qaala Rabbukum Wa-Rabbu aabaaa\'ikumul awwaleen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>27,'arabic_text'=>'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ','transliteration'=>'Qaala inna Rasoolakumul lazee ursila ilaikum lamajnoon','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>28,'arabic_text'=>'قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ','transliteration'=>'Qaala Rabbul mashriqi wal-maghribi Wa-maa baina-humaa in kuntum ta\'qiloon','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>29,'arabic_text'=>'قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ','transliteration'=>'Qaala la\'init takhazta ilaahan ghairee la-aj\'alannaka minal masjooneen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>30,'arabic_text'=>'قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ','transliteration'=>'Qaala awalaw ji\'tuka bishai\'im mubeen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>31,'arabic_text'=>'قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaala faati biheee in kunta minas saadiqeen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>32,'arabic_text'=>'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ','transliteration'=>'Fa-alqaa \'asaahu fa-izaaa hiya su\'baanum mubeen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>33,'arabic_text'=>'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ','transliteration'=>'Wa-naza\'a yadahoo faizaa hiya baidaaa\'u linnaa-zireen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>34,'arabic_text'=>'قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ','transliteration'=>'Qaala lilmala-i hawlahooo inna haazaa lasaahirun \'aleem','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>35,'arabic_text'=>'يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ','transliteration'=>'Yureedu aien yukhrijakum min ardikum bisihrihee famaazaa taamuroon','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>36,'arabic_text'=>'قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ','transliteration'=>'Qaalooo arjih Wa-akhaahu wab\'as fil madaaa\'ini haashireen','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>37,'arabic_text'=>'يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ','transliteration'=>'Yaatooka bikulli sah-haarin \'aleem','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>38,'arabic_text'=>'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ','transliteration'=>'Fa-jumi\'as saharatu limeeqaati Yawmim ma\'loom','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>39,'arabic_text'=>'وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ','transliteration'=>'Wa-qeela linnaasi hal antum mujtami\'oon','page_number'=>368,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>40,'arabic_text'=>'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ','transliteration'=>'La\'allanaa nattabi\'us saharata in kaanoo humul ghaalibeen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>41,'arabic_text'=>'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ','transliteration'=>'Falammaa jaaa\'as saharatu qaaloo li-Fir\'awna a\'inna lanaa la-ajjran in kunnaa nahnul ghaalibeen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>42,'arabic_text'=>'قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ','transliteration'=>'Qaala na\'am Wa-innakum izal laminal muqarrabeen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>43,'arabic_text'=>'قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ','transliteration'=>'Qaala lahum Moosaaa alqoo maaa antum mulqoon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>44,'arabic_text'=>'فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ','transliteration'=>'Fa-alqaw hibaalahum Wa-\'isiyyahum Wa-qaaloo bi\'izzati Fir\'awna innaa lanahnul ghaaliboon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>45,'arabic_text'=>'فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ','transliteration'=>'Fa-alqaa Moosaa \'asaahu fa-izaa hiya talqafu maa yaafikoon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>46,'arabic_text'=>'فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ','transliteration'=>'Fa-ulqiyas saharatu saajideen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>47,'arabic_text'=>'قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qaalooo aamannaa bi-Rabbil \'aalameen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>48,'arabic_text'=>'رَبِّ مُوسَىٰ وَهَٰرُونَ','transliteration'=>'Rabbi Moosaa Wa-Haaroon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>49,'arabic_text'=>'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ','transliteration'=>'Qaala aamantum lahoo qabla an aazana lakum innahoo lakabeerukumul lazee \'alla-makumus sihra falasawfa ta\'lamoon; la-uqatti\'anna aidiyakum Wa-arjulakum min khilaafinw Wa-la-usallibanna-kum ajma\'een','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>50,'arabic_text'=>'قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ','transliteration'=>'Qaaloo la daira innaaa ilaa Rabbinaa munqalliboon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>51,'arabic_text'=>'إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Innaa natma\'u aien yaghfira lanaa Rabbunna khataa-yaanaaa an kunnaaa awwalal mu\'mineen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>52,'arabic_text'=>'۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ','transliteration'=>'Wa-awhainaaa ilaa Moosaaa an asri bi\'ibaadeee innakum muttaba\'oon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>53,'arabic_text'=>'فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ','transliteration'=>'Fa-arsala Fir\'awnu fil madaaa\'ini haashireen','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>54,'arabic_text'=>'إِنَّ هَٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ','transliteration'=>'Inna haaa\'ulaaa\'i lashir-zimatun qaleeloon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>55,'arabic_text'=>'وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ','transliteration'=>'Wa-innahum lanaa laghaaa\'izoon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>56,'arabic_text'=>'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ','transliteration'=>'Wa-innaa lajamee\'un haaziroon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
            ['surah_id'=>26,'ayah_number'=>57,'arabic_text'=>'فَأَخۡرَجۡنَٰهُم مِّن جَنَّٰتٖ وَعُيُونٖ','transliteration'=>'Fa-akhrajnaahum min Jannaatinw Wa-\'uyoon','page_number'=>369,'juz_number'=>19,'hizb_number'=>37,'is_sajdah'=>false],
