            ['surah_id'=>27,'ayah_number'=>2,'arabic_text'=>'هُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ','transliteration'=>'Hudanw Wa-bushraa lil-mu\'mineen','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>3,'arabic_text'=>'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ','transliteration'=>'Allazeena yuqeemoonas Salaata Wa-yu\'toonaz Zakaata Wa-hum bil-Aakhirati hum yooqinoon','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>4,'arabic_text'=>'إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ','transliteration'=>'Innal lazeena laa yu\'minoona bil-Aakhirati zaiyannaa lahum a\'maalahum fahum ya\'mahoon','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>5,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ وَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ','transliteration'=>'Ulaaa\'ikal lazeena lahum sooo\'ul \'azaabi Wa-hum fil Aakhirati humul akhsaroon','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>6,'arabic_text'=>'وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِيمٍ عَلِيمٍ','transliteration'=>'Wa-innaka latulaqqal Qur-aana mil ladun Hakeemin \'Aleem','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>7,'arabic_text'=>'إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦٓ إِنِّيٓ ءَانَسۡتُ نَارٗا سَـَٔاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيكُم بِشِهَابٖ قَبَسٖ لَّعَلَّكُمۡ تَصۡطَلُونَ','transliteration'=>'Iz qaala Moosaa li-ahliheee inneee aanastu naaran saaateekum minhaa bikhabarin aw aateekum bishihaabin qabasil la\'allakum tastaloon','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>8,'arabic_text'=>'فَلَمَّا جَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِي ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Falammaa jaaa\'ahaa noodiya am boorika man fin naari Wa-man hawlahaa Wa-Subhaanal laahi Rabbil \'aalameen','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>9,'arabic_text'=>'يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Yaa-Moosaaa innahooo Anal laahul \'Azeezul Hakeem','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>10,'arabic_text'=>'وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ','transliteration'=>'Wa-alqi \'asaak; falammmaa ra-aahaa tahtazzu ka-annahaa jaaannunw wallaa mudbiranw Wa-lam yu\'aqqib; yaa-Moosaa laa takhaf innee laa yakhaafu ladaiyal mursaloon','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>11,'arabic_text'=>'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوٓءٖ فَإِنِّي غَفُورٞ رَّحِيمٞ','transliteration'=>'Illaa man zalama summa baddala husnam ba\'da sooo\'in fa-innee Ghafoorur Raheem','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>12,'arabic_text'=>'وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ','transliteration'=>'Wa-adkhil yadaka fee jaibika takhruj baidaaa\'a min ghairi sooo\'in fee tis\'i Aayaatin ilaa Fir\'awna Wa-qawmih; innahum kaanoo qawman faasiqeen','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>13,'arabic_text'=>'فَلَمَّا جَآءَتۡهُمۡ ءَايَٰتُنَا مُبۡصِرَةٗ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ','transliteration'=>'Falammaa jaaa\'at-hum Aayaatunaa mubsiratan qaaloo haazaa sihrum mubeen','page_number'=>377,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>14,'arabic_text'=>'وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمٗا وَعُلُوّٗاۚ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ','transliteration'=>'Wa-jahadoo bihaa wastaiqanat-haaa anfusuhum zulmanw wa-\'uluwwaa; fanzur kaifa kaana \'aaqibatul mufsideen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>15,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمٗاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-laqad aatainaa Daawooda Wa-sulaimaana \'ilmaa; Wa-qaalal hamdu lil-laahil lazee faddalanaa \'alaa kaseerim min \'ibaadihil mu\'mineen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>16,'arabic_text'=>'وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ','transliteration'=>'Wa-warisa Sulaimaanu Daawooda Wa-qaala yaaa-aiyuhan naasu \'ullimnaa mantiqat tairi Wa-ooteenaa min kulli shai\'in inna haazaa lahuwal fadlul mubeen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>17,'arabic_text'=>'وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ','transliteration'=>'Wa-hushira Sulaimaana junooduhoo minal jinni wal-insi wattairi fahum yooza\'oon','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>18,'arabic_text'=>'حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةٞ يَٰٓأَيُّهَا ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'hattaaa izaaa ataw \'alaa waadin namli qaalat namlatuien yaaa-aiyuhan namlud khuloo masaakinakum laa yahtimannakum Sulaimaanu Wa-junooduhoo Wa-hum laa yash\'uroon','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>19,'arabic_text'=>'فَتَبَسَّمَ ضَاحِكٗا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ','transliteration'=>'Fatabassama daahikam min qawlihaa Wa-qaala Rabbi awzi\'nee an ashkura ni\'mata-kal lateee an\'amta \'alaiyya Wa-\'alaa waalidaiyya Wa-an a\'mala saalihan tardaahu Wa-adkhilnee birahmatika fee \'ibaadikas saaliheen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>20,'arabic_text'=>'وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَالِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَآئِبِينَ','transliteration'=>'Wa-tafaqqadat taira faqaala maa liya laaa araa al-hudhuda, am kaana minal ghaaa\'ibeen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>21,'arabic_text'=>'لَأُعَذِّبَنَّهُۥ عَذَابٗا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنٖ مُّبِينٖ','transliteration'=>'La-u\'azzibanahoo \'azaaban shadeedan aw la-azbahannahoo aw layaatiyannee bisultaanim mubeen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>22,'arabic_text'=>'فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ','transliteration'=>'Famakasa ghaira ba\'eedin faqaala ahattu bimaa lam tuhit bihee Wa-ji\'tuka min Sabaim binaba-iny yaqeen','page_number'=>378,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>23,'arabic_text'=>'إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ','transliteration'=>'Innee wajattum ra-atan tamlikuhum Wa-ootiyat min kulli shai\'inw Wa-lahaa \'arshun \'azeem','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>24,'arabic_text'=>'وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ','transliteration'=>'Wajattuhaa Wa-qawmahaa yasjudoona lishshamsi min doonil laahi Wa-zaiyana lahumush Shaitaanu a\'maalahum fasaddahum \'anis sabeeli fahum laa yahtadoon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>25,'arabic_text'=>'أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ','transliteration'=>'Allaa yasjudoo lillaahil lazee yukhrijul khab\'a fis samaawaati wal-ardi Wa-ya\'lamu maa tukhfoona Wa-maa tu\'linoon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>26,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ','transliteration'=>'Allaahu laaa ilaaha illaa Huwa Rabbul \'Arshil Azeem','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>true],
            ['surah_id'=>27,'ayah_number'=>27,'arabic_text'=>'۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Qaala sananzuru asadaqta am kunta minal kaazibeen','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>28,'arabic_text'=>'ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ','transliteration'=>'Izhab bikitaabee haaza fa-alqih ilaihim summma tawalla \'anhum fanzur maazaa yarji\'oon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>29,'arabic_text'=>'قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ','transliteration'=>'Qaalat yaaa-aiyyuhal mala\'u innee ulqiya ilaiya kitaabun kareem','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>30,'arabic_text'=>'إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ','transliteration'=>'Innahoo min Sulaimaana Wa-innahoo bismil laahir Rahmaanir Raheem','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>31,'arabic_text'=>'أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ','transliteration'=>'Allaa ta\'loo \'alaiya waa-toonee muslimeen','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>32,'arabic_text'=>'قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ','transliteration'=>'Qaalat yaaa-aiyyuhal mala\'u aftoonee fee amree maa kuntu qaati\'atan amran hattaa tashhhaddon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>33,'arabic_text'=>'قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ','transliteration'=>'Qaaloo nahnu uloo quwwatinw Wa-uloo baasin shadeed; wal-amru ilaiki fanzuree maazaa taamureen','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>34,'arabic_text'=>'قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ','transliteration'=>'Qaalat innal mulooka izaa dakhaloo qaryatan afsadoohaa Wa-ja\'alooo a\'izzata ahlihaaa azillah; Wa-kazaalika yaf\'aloon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>35,'arabic_text'=>'وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ','transliteration'=>'Wa-innee mursilatun ilaihim bihadiyyatin fanaaziratum bima yarji\'ul mursaloon','page_number'=>379,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>36,'arabic_text'=>'فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ','transliteration'=>'Falammaa jaaa\'a Sulaimaana qaala atumiddoonani bimaalin famaaa aataaniyal laahu khairum mimmmaaa aataakum bal antum bihadiy-yatikum tafrahoon','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>37,'arabic_text'=>'ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ','transliteration'=>'Irji\' ilaihim falanaatiyan-nahum bijunoodil laa qibala lahum bihaa Wa-lanukhri-jannahum minhaaa azillatanw Wa-hum saaghiroon','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>38,'arabic_text'=>'قَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ','transliteration'=>'Qaala yaaa-aiyyuhal mala\'u aiyyukum yaateenee bi\'arshihaa qabla aien yaatoonee muslimeen','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>39,'arabic_text'=>'قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ','transliteration'=>'Qaala \'ifreetum minal jinni ana aateeka bihee qabla an taqooma mim maqaamika Wa-innee \'alaihi laqawiyyun ameen','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>40,'arabic_text'=>'قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ','transliteration'=>'Qaalal lazee indahoo \'ilmum minal Kitaabi ana aateeka bihee qabla aien yartadda ilaika tarfuk; falammaa ra-aahu mustaqirran \'indahoo qaala haazaa min fadli Rabbee li-yabluwaneee \'a-ashkuru am akfuru Wa-man shakara fa-innamaa yashkuru linafsihee Wa-man kafara fa-inna Rabbee Ghaniyyun Kareem','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>41,'arabic_text'=>'قَالَ نَكِّرُواْ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ','transliteration'=>'Qaala nakkiroo lahaa \'arshahaa nanzur atahtadeee am takoonu minal lazeena laa yahtadoon','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>42,'arabic_text'=>'فَلَمَّا جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ','transliteration'=>'Falammaa jaaa\'at qeela ahaakaza \'arshuki qaalat kaanna hoo; Wa-ooteenal \'ilma min qablihaa Wa-kunnaa muslimeen','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>43,'arabic_text'=>'وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ','transliteration'=>'Wa-saddahaa maa kaanat ta\'budu min doonil laahi innahaa kaanat min qawmin kaafireen','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>44,'arabic_text'=>'قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qeela lahad khulis sarha falammaa ra-at-hu hasibat-hu lujjatanw Wa-khashafat \'an saaqaihaa; qaala innahoo sarhum mumarradum min qawaareer; qaalat Rabbi innee zalamtu nafsee Wa-aslamtu ma\'a Sulaimaana lillaahi Rabbil \'aalameen','page_number'=>380,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>45,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحًا أَنِ ٱعۡبُدُواْ ٱللَّهَ فَإِذَا هُمۡ فَرِيقَانِ يَخۡتَصِمُونَ','transliteration'=>'Wa laqad arsalnaaa ilaa Samooda akhaahum Saalihan ani\'budul lahha fa-izaa hum fareeqaani yakhtasimoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>46,'arabic_text'=>'قَالَ يَٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Qaala yaa-qawmi lima tasta\'jiloona bissaiyi\'ati qablal hasanati law-laa tas-taghfiroonal laaha la\'allakum turhamoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>47,'arabic_text'=>'قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمٞ تُفۡتَنُونَ','transliteration'=>'Qaalut taiyyarnaa bika Wa-bimam ma\'ak; qaala taaa\'irukum \'indal laahi bal antum qawmun tuftanoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>48,'arabic_text'=>'وَكَانَ فِي ٱلۡمَدِينَةِ تِسۡعَةُ رَهۡطٖ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ','transliteration'=>'Wa-kaana fil madeenati tis\'atu rahtien yufsidoona fil ardi Wa-laa yuslihoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>49,'arabic_text'=>'قَالُواْ تَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ','transliteration'=>'Qaaloo taqaasamoo billaahi lanubaiyyitannahoo Wa-ahlahoo summaa lanaqoolana liwaliy-yihee maa shahidnaa mahlika ahliee Wa-innaa lasaadiqoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>50,'arabic_text'=>'وَمَكَرُواْ مَكۡرٗا وَمَكَرۡنَا مَكۡرٗا وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Wa-makaroo makranw Wa-makarnaa makranw Wa-hum laa yash\'uroon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>51,'arabic_text'=>'فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِينَ','transliteration'=>'Fanzur kaifa kaana \'aaqibatu makrihim annaa dammar-naahum Wa-qawmahum ajma\'een','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>52,'arabic_text'=>'فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Fatilka buyootuhum khaa-wiyatam bimaa zalamoo; inna fee zaalika la-Aayatal liqaw-mien ya\'lamoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>53,'arabic_text'=>'وَأَنجَيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ','transliteration'=>'Wa-anjainal lazeena aamanoo Wa-kaanoo yattaqoon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>54,'arabic_text'=>'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ','transliteration'=>'Wa-lootan iz qaala liqawmiheee ataatoonal faa-hishata Wa-antum tubsiroon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>55,'arabic_text'=>'أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ تَجۡهَلُونَ','transliteration'=>'A\'innakum lataatoonar rijaala shahwatam min doonin nisaaa\'; bal antum qawmun tajhaloon','page_number'=>381,'juz_number'=>19,'hizb_number'=>38,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>56,'arabic_text'=>'۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ','transliteration'=>'Famaa kaana jawaaba qawmiheee illaaa an qaalooo akhrijooo aalaa Lootim min qaryatikum innahum unaasuny yatatahharoon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>57,'arabic_text'=>'فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ','transliteration'=>'Fa-anjainaahu Wa-ahlahooo illam ra-atahoo qaddarnaahaa minal ghaabireen','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>58,'arabic_text'=>'وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ','transliteration'=>'Wa-amtarnaa \'alaihimm mataran fasaaa\'a matarul munzareen','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>59,'arabic_text'=>'قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ','transliteration'=>'Qulil hamdu lillaahi Wa-salaamun \'alaa \'ibaadihil lazeenas tafaa; aaallaahu khairun ammmaa yushrikoon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>60,'arabic_text'=>'أَمَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهۡجَةٖ مَّا كَانَ لَكُمۡ أَن تُنۢبِتُواْ شَجَرَهَآۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمٞ يَعۡدِلُونَ','transliteration'=>'Amman khalaqas samaawaati wal-arda Wa-anzala lakum minas samaaa\'i maaa\'an fa-anbatnaa bihee hadaaa\'iqa zaata bahjah; maa kaana lakum an tunbitoo shajarahaa; \'a-ilaahun ma\'al laah; bal hum qawmuien ya\'diloon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>61,'arabic_text'=>'أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارٗا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرٗا وَجَعَلَ لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Ammann ja\'alal arda qaraaranw Wa-ja\'ala khilaalahaaa anhaaranw Wa-ja\'ala lahaa rawaasiya Wa-ja\'ala bainal bahraini haajizaa; \'a-ilaahun ma\' allah; bal aksaruhum laa ya\'lamoon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>62,'arabic_text'=>'أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قَلِيلٗا مَّا تَذَكَّرُونَ','transliteration'=>'Ammaien yujeebul mud-tarra izaa da\'aahu Wa-yakshifus sooo\'a Wa-yaj\'alukum khula-faaa\'al ardi \'a-ilaahun ma\' allaah qaleelan maa tazak-karoon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>63,'arabic_text'=>'أَمَّن يَهۡدِيكُمۡ فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦٓۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ تَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ','transliteration'=>'Ammaien yahdeekum fee zulumaatil barri wal bahri Wa-maien yursilu riyaaha bushran baina yadai rahmatih; \'a-ilaahun ma\'allah; Ta\'aalal laahu \'ammaa yushrikoon','page_number'=>382,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>64,'arabic_text'=>'أَمَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۗ أَءِلَٰهٞ مَّعَ ٱللَّهِۚ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Ammaien yabda\'ul khalqa thumma yu\'eeduhoo Wa-maien yarzuqukum minas sammaaa\'i wal ard; \'a-ilaahun ma\'allah; qul haatoo burhaanakum in kuntum saadiqeen','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>65,'arabic_text'=>'قُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ','transliteration'=>'Qul laa ya\'lamu man fis sammaawaati wal-ardil ghaiba illal laah; Wa-maa yash\'uroona aiyaana yub\'asoon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>66,'arabic_text'=>'بَلِ ٱدَّٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي شَكّٖ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ','transliteration'=>'Balid daaraka \'ilmuhum fil Aakhirah; bal hum fee shakkin minhaa bal hum minhaa \'amoon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>67,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ أَءِذَا كُنَّا تُرَٰبٗا وَءَابَآؤُنَآ أَئِنَّا لَمُخۡرَجُونَ','transliteration'=>'Wa-qaalal lazeena kafarooo \'a-izaa kunnaa turaabanw Wa-aabaaa\'unaaa a\'innaa lamukhrajoon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>68,'arabic_text'=>'لَقَدۡ وُعِدۡنَا هَٰذَا نَحۡنُ وَءَابَآؤُنَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Laqad wu\'idnaa haazaa nahnu Wa-aabaaa\'unaa min qablu in haazaaa illaaa asaateerul awwaleen','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>69,'arabic_text'=>'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ','transliteration'=>'Qul seeroo fil ardi fanzuroo kaifa kaana \'aaqibatul mujrimeen','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>70,'arabic_text'=>'وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُن فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ','transliteration'=>'Wa-laa tahzan \'alaihim Wa-laa takun fee daiqin mimmaa yamkuroon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>71,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>72,'arabic_text'=>'قُلۡ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِي تَسۡتَعۡجِلُونَ','transliteration'=>'Qul \'asaaa aien yakoona radifa lakum ba\'dul lazee tasta\'jiloon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>73,'arabic_text'=>'وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ','transliteration'=>'Wa-inna Rabbaka lazoo fadlin \'alan naasi Wa-laakinna aksarahum laa yashkuroon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>74,'arabic_text'=>'وَإِنَّ رَبَّكَ لَيَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ','transliteration'=>'Wa-inna Rabbaka la-ya\'lamu maa tukinnu sudooruhum Wa-maa yu\'linoon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>75,'arabic_text'=>'وَمَا مِنۡ غَآئِبَةٖ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِلَّا فِي كِتَٰبٖ مُّبِينٍ','transliteration'=>'Wa-maa min ghaaa\'ibatin fis samaaa\'i wal-ardi illaa fee kitaabin mubeen','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>76,'arabic_text'=>'إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَقُصُّ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَكۡثَرَ ٱلَّذِي هُمۡ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Inna haazal Qur-aana yaqussu \'alaa Baneee israaa\'eela aksaral lazee hum feehi yakhtalifoon','page_number'=>383,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>77,'arabic_text'=>'وَإِنَّهُۥ لَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ','transliteration'=>'Wa-innahoo lahudanw Wa-rahmatul lilmu\'mineen','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>78,'arabic_text'=>'إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُم بِحُكۡمِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡعَلِيمُ','transliteration'=>'Inna Rabbaka yaqdee bainahum bihukmih; Wa-Huwal \'Azeezul \'Aleem','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>79,'arabic_text'=>'فَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِينِ','transliteration'=>'Fatawakkal \'alal laahi innaka \'alal haqqil mubeen','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>80,'arabic_text'=>'إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ','transliteration'=>'Innaka laa tusmi\'ul mawtaa Wa-laa tusmi\'us summad du\'aaa izaa wallaw mudbireen','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>81,'arabic_text'=>'وَمَآ أَنتَ بِهَٰدِي ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ','transliteration'=>'Wa-maaa anta bihaadil-\'umyi \'an dalaalatihim in tusmi\'u illaa mai yu\'minu bi aayaatinaa fahum muslimoon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>82,'arabic_text'=>'۞ وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةٗ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ','transliteration'=>'Wa-izaa waqa\'al qawlu \'alaihim akhrajnaa lahum daaabbatan minal ardi tukal-limuhum annan naasa kaanoo bi-aayaatinaa laa yooqinoon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>83,'arabic_text'=>'وَيَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةٖ فَوۡجٗا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمۡ يُوزَعُونَ','transliteration'=>'Wa-Yawma nahshuru min kulli ummatin fawjan mimmaien yukazzibu bi-Aayaatinaa fahum yooza\'oon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>84,'arabic_text'=>'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبۡتُم بِـَٔايَٰتِي وَلَمۡ تُحِيطُواْ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Hattaaa izaa jaaa\'oo qaala akazzabtum bi-Aayaatee Wa-lam tuheetoo bihaa \'ilman ammaazaa kuntum ta\'maloon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>85,'arabic_text'=>'وَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ','transliteration'=>'Wa-waqa\'al qawlu \'alaihim bimaa zalamoo fahum laa yantiqoon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>86,'arabic_text'=>'أَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا ٱلَّيۡلَ لِيَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Alam yaraw annaa ja\'alnal laila li-yaskunoo feehi wannahaara mubsiraa; inna fee zaalika la-Aayaatil liqaw-mien yu\'minoon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>87,'arabic_text'=>'وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَٰخِرِينَ','transliteration'=>'Wa-Yawma yunfakhu fis Soori fafazi\'a man fis samaawaati Wa-man fil ardi illaa man shaaa\'al laah; Wa-kullun atawhu daakhireen','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>88,'arabic_text'=>'وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةٗ وَهِيَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ','transliteration'=>'Wa-taral jibaala tahsabuhaa jaamidatanw Wa-hiya tamurru marras sahaab; sun\'al laahil lazeee atqana kulla shai\'; innahoo khabeerun bimaa taf\'aloon','page_number'=>384,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>89,'arabic_text'=>'مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَا وَهُم مِّن فَزَعٖ يَوۡمَئِذٍ ءَامِنُونَ','transliteration'=>'Man jaaa\'a bil-hasanati falahoo khairun minhaa Wa-hum min faza\'ien Yawma\'izin aaminoon','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>90,'arabic_text'=>'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-man jaaa\'a bissai-yi\'ati fakubbat wujoohuhum fin Naari hal tujzawna illaa maa kuntum ta\'maloon','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>91,'arabic_text'=>'إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِي حَرَّمَهَا وَلَهُۥ كُلُّ شَيۡءٖۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Innamaaa umirtu an a\'buda Rabba haazihil baldatil lazee harramahaa Wa-lahoo kullu shai\'inw Wa-umirtu an akoona minal muslimeen','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>92,'arabic_text'=>'وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ','transliteration'=>'Wa-an atluwal Qur-aana famanih tadaa fa-innamaa yahtadee linafsihee Wa-man dalla faqul innamaaa ana minal munzireen','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>27,'ayah_number'=>93,'arabic_text'=>'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ سَيُرِيكُمۡ ءَايَٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','transliteration'=>'Wa-qulil hamdu lillaahi sa-yureekum Aayaatihee fa-ta\'rifoonahaa; Wa-maa Rabbuka bighaafilin \'ammaa ta\'maloon','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            /* Surah 28: The Stories (Al-Qasas) */
            ['surah_id'=>28,'ayah_number'=>1,'arabic_text'=>'طسٓمٓ','transliteration'=>'Taa-Seeen-Meeem','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>2,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ','transliteration'=>'Tilka Aayaatul Kitaabil mubeen','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>3,'arabic_text'=>'نَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Natloo \'alaika min naba-i Moosaa Wa-Fir\'awna bilhaqqi liqawminy yu\'miinoon','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>4,'arabic_text'=>'إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ','transliteration'=>'Inna Fir\'awna \'alaa fil ardi Wa-ja\'ala ahlahaa shiya\'ai yastad\'ifu taaa\'ifatam minhum yuzabbihu abnaaa\'ahum Wa-yastahyee nisaaa\'ahum; innahoo kaana minal mufsideen','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>5,'arabic_text'=>'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ','transliteration'=>'Wa-nureedu an namunna \'alal lazeenas tud\'ifoo fil ardi Wa-naj\'alahum a\'immatanw Wa-naj\'alahumul waariseen','page_number'=>385,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>6,'arabic_text'=>'وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ','transliteration'=>'Wa-numakkina lahum fil ardi Wa-nuriya Fir\'awna Wa-Haamaana Wa-junoodahumaa minhum maa kaanoo yahzaroon','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>7,'arabic_text'=>'وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ','transliteration'=>'Wa-awhainaaa ilaaa ummi Moosaaa an ardi\'eehi faizaa khifti \'alaihi fa-alqeehi fil yammi Wa-laa takhaafee Wa-laa tahzaneee innaa raaaddoohu ilaiki Wa-jaa\'iloohu minal mursaleen','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>8,'arabic_text'=>'فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ','transliteration'=>'Faltaqatahooo Aalu Fir\'awna li-yakoona lahum \'aduwwanw Wa-hazanaa; inna Fir\'awna Wa-Haamaana Wa-junooda-humaa kaanoo khaati\'een','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>9,'arabic_text'=>'وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Wa-qaalatim ra-atu Fir\'awna qurratu \'aynil lee Wa-lak; laa taqtuloohu \'asaaa aien yanfa\'anaa aw nattakhizahoo waladanw Wa-hum laa yash\'uroon','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>10,'arabic_text'=>'وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-asbaha fu\'aadu ummi Moosaa faarighan in kaadat latubdee bihee law laaa arrabatnaa \'alaa qalbihaa litakoona minal mu\'mineen','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>11,'arabic_text'=>'وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Wa-qaalat li-ukhtihee qusseehi fabasurat bihee \'an junubinw wahum laa yash\'uroon','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>12,'arabic_text'=>'۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ','transliteration'=>'Wa-harramnaa \'alaihil maraadi\'a min qablu faqaalat hal adullukum \'alaaa ahli baitiny yakfuloonahoo lakum Wa-hum lahoo naasihoon','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>13,'arabic_text'=>'فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Faradadnaahu ilaa ummihee kai taqarra \'ainuhaa Wa-laa tahzana Wa-lita\'lama anna wa\'dal laahi haqqunw Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>386,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>14,'arabic_text'=>'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ','transliteration'=>'Wa-lammaa balagha ashuddahoo wastawaaa aatai-naahu hukmanw Wa-\'ilmaa; Wa-kazaalika najzil muhsineen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>15,'arabic_text'=>'وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ','transliteration'=>'Wa-dakhalal madeenata \'alaa heene ghaflatim min ahlihaa fawajada feeha raju-laini yaqtatilaani haazaa min shee\'atihee Wa-haaza min \'aduwwihee fastaghaasahul lazee min shee\'atihee \'alal lazee min \'aduwwihee fawakazahoo Moosaa faqadaa \'alaihi qaala haaza min \'amalish Shaitaani innahoo \'aduwwum mmudillum mubeen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>16,'arabic_text'=>'قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Qaala Rabbi innee zalamtu nafsee faghfir lee faghafara lah; innahoo Huwal Ghafoorur Raheem','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>17,'arabic_text'=>'قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ','transliteration'=>'Qaala Rabbi bimaaa an\'amta \'alaiya falan akoona zaheeral lilmujrimeen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>18,'arabic_text'=>'فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفٗا يَتَرَقَّبُ فَإِذَا ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيّٞ مُّبِينٞ','transliteration'=>'Fa-asbaha fil madeenati khaaa\'ifaien yataraqqabu fa-izal lazis tansarahoo bil-amsi yastasrikhuh; qaala lahoo moosaaa innaka laghawiyyum mubeen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>19,'arabic_text'=>'فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوّٞ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارٗا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِينَ','transliteration'=>'Falammaaa an araada aien yabtisha billazee huwa \'aduwwul lahumaa qaala yaa-Moosaaa atureedu an taqtulanee kamaa qatalta nafsam bil-amsi in tureedu illaaa an takoona jabbaaram fil ardi Wa-maa tureedu an takoona minal musliheen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>20,'arabic_text'=>'وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّٰصِحِينَ','transliteration'=>'Wa-jaaa\'a rajulum min aqsal madeenati yas\'aa qaala yaa-Moosaaa innal mala-a yaa-tamiroona bika liyaqtulooka fakhruj innee laka minan naasiheen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>21,'arabic_text'=>'فَخَرَجَ مِنۡهَا خَآئِفٗا يَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Fakharaja minhaa khaaa \'ifany-yataraqqab; qaala Rabbi najjinee minal qawmiz zaalimeen','page_number'=>387,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>22,'arabic_text'=>'وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ ٱلسَّبِيلِ','transliteration'=>'Wa-lammaa tawajjaha tilqaaa\'a Madyana qaala \'asaa Rabbeee aien yahdiyanee Sawaaa\'as Sabeel','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>23,'arabic_text'=>'وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ','transliteration'=>'Wa-lammaa warada maaa\'a Madyana wajada \'alaihi ummatam minannaasi yasqoona Wa-wajada min doonihimum ra ataini tazoodaani qaala maa khatubkumaa qaalataa laa nasqee hataa yusdirar ri\'aaa\'u Wa-aboonaa shaikhun kabeer','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>24,'arabic_text'=>'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ','transliteration'=>'Fasaqaa lahumaa summa tawallaaa ilaz zilli faqaala Rabbi innee limaaa anzalta ilaiya min khairin faqeer','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>25,'arabic_text'=>'فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Fajaaa\'at-hu ihdaahumaa tamshee \'alas tihyaaa\'in qaalat inna abee yad\'ooka li-yajziyaka ajra maa saqaita lanaa; falammaa jaaa\'ahoo Wa-qassa \'alaihil qasasa qaala laa takhaf najawta minal qawmiz zaalimeen','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>26,'arabic_text'=>'قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ','transliteration'=>'Qaalat ihdaahumaa yaaa abatis taajirhu inna khaira manistaajartal qawiyyul ameen','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>27,'arabic_text'=>'قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Qaala innee ureedu an unkihaka ihdab nataiya haataini \'alaaa an taajuranee samaaniya hijaj; fa-in atmamta \'ashran famin \'indika Wa-maaa ureedu an ashuqqa \'alaik; satajiduneee in shaaa\'al laahu minas saaliheen','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>28,'arabic_text'=>'قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ','transliteration'=>'Qaala zaalika bainee Wa-bainaka aiyamal ajalaini qadaitu falaa \'udwaana \'alaiya wallaahu \'alaa ma naqoolu Wakeel','page_number'=>388,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>29,'arabic_text'=>'۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ','transliteration'=>'Falammmaa qadaa Moosal ajala Wa-saara bi-ahliheee aanasa min jaanibit Toori naaran qaala li-ahlihim kusooo inneee aanastu naaral la-\'alleee aateekum minhaa bikhabarin aw jazwatim minan naari la-\'allakum tastaloon','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>30,'arabic_text'=>'فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ','transliteration'=>'Falammaaa ataahaa noodiya min shaati\'il waadil aimani fil buq\'atil muubaarakati minash shajarati aien yaa-Moosaaa inneee Anal laahu Rabbul \'aalameen','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>31,'arabic_text'=>'وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ','transliteration'=>'Wa-an alqi \'asaaka falam-maa ra-aahaa tahtazzu ka-annnahaa jaaannunw wallaa mudbiranw Wa-lam yu\'aqqib; yaa-Moosaa aqbil Wa-laa takhaf innaka minal aamineen','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>32,'arabic_text'=>'ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ','transliteration'=>'Usluk yadaka fee jaibika takhruj baidaaa\'a min ghairi sooo\'inw wadmum ilaika janaahaka minar rahbi fazaanika burhaanaani mir Rabbika ilaa Fir\'awna Wa-mala\'ih; innahum kaanoo qawman faasiqeen','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>33,'arabic_text'=>'قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ','transliteration'=>'Qaala Rabbi innee qataltu minhum nafsan fa-akhaafu aien yaqtuloon','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>34,'arabic_text'=>'وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ','transliteration'=>'Wa-akhee Haaroonu huwa afsahu minnee lisaanan fa-arsilhu ma\'iya rid-aien yusaddiquneee innee akhaafu aien yukazziboon','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>35,'arabic_text'=>'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ','transliteration'=>'Qaala sanashuddu \'adudaka bi-akheeka Wa-naj\'alu lakumaa sultaanan falaa yasiloona ilaikumaa; bi-Aayaatinaa antumaa Wa-manit taba\'akumal ghaaliboon','page_number'=>389,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>36,'arabic_text'=>'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ','transliteration'=>'Falammaa jaaa\'ahum Moosaa bi-Aayaatinaa baiyinaatin qaaloo maa haazaaa illaa sihrum muftaranw Wa-maa sami\'naa bihaazaa feee aabaaa\'inal awwaleen','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>37,'arabic_text'=>'وَقَالَ مُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ','transliteration'=>'Wa-qaala Moosaa Rabbeee a\'alamu biman jaaa\'a bilhudaa min \'indihee Wa-man takoonu lahoo \'aaqibatud daari innahoo laa yuflihuz zaalimoon','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>38,'arabic_text'=>'وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ','transliteration'=>'Wa-qaala Fir\'awnu yaaa-aiyyuhal mala-u maa \'alimtu lakum min ilaahin ghairee fa-awqid lee yaa-Haamaanu \'alatteeni faj\'al lee sarhal la\'alleee attali\'u ilaaa ilaahi Moosaa Wa-innee la azunnuhoo minal kaazibeen','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>39,'arabic_text'=>'وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ','transliteration'=>'Wastakbara huwa Wa-junooduhoo fil ardi bighairil haqqi Wa-zannooo annahum ilainaa laa yurja\'oon','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>40,'arabic_text'=>'فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ','transliteration'=>'Fa-akhaznaahu Wa-junoo-dahoo fanabaznaahum fil yammi fanzur kaifa kaana \'aaqibatuz zaalimeen','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>41,'arabic_text'=>'وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ','transliteration'=>'Wa-ja\'alnaahum a\'immataien yad\'oona ilan Naari Wa-Yawmal Qiyaamati laa yunsaroon','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>42,'arabic_text'=>'وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ','transliteration'=>'Wa-atba\'naahum fee haazihid dunyaa la\'natanw Wa-Yawmal Qiyaamati hum minal maqbooheen','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>43,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba mim ba\'di maaa ahlaknal quroonal oolaa basaaa\'ira linnaasi Wa-hudanw Wa-rahmatal la\'allahum yata-zakkkaroon','page_number'=>390,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>44,'arabic_text'=>'وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ','transliteration'=>'Wa-maa kunta bijaanibil gharbiyyi iz qadainaaa ilaa Moosal amra Wa-maa kunta minash shaahideen','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>45,'arabic_text'=>'وَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ','transliteration'=>'Wa-laakinnaa anshaanaa quroonan fatataawala \'alaihimul \'umur; Wa-maa kunta saawiyan feee ahli Madyana tatloo \'alaihim Aayaatinaa Wa-laakinnaa kunnaa mursileen','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>46,'arabic_text'=>'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَيۡنَا وَلَٰكِن رَّحۡمَةٗ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Wa-maa kunta bijaanibit Toori iz naadainaa Wa-laakir rahmatam mir Rabbika litunzira qawmam maaa ataahum min nazeerim min qablika la\'allahum yatazakkaroon','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>47,'arabic_text'=>'وَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-law-laaa an tuseebahum museebatum bimaa qaddamat aideehim fa-yaqooloo Rabbanaa law-laaa arsalta ilainaa Rasoolan fanattabi\'a Aayaatika Wa-nakoona minal mu\'mineen','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>48,'arabic_text'=>'فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُواْ لَوۡلَآ أُوتِيَ مِثۡلَ مَآ أُوتِيَ مُوسَىٰٓۚ أَوَلَمۡ يَكۡفُرُواْ بِمَآ أُوتِيَ مُوسَىٰ مِن قَبۡلُۖ قَالُواْ سِحۡرَانِ تَظَٰهَرَا وَقَالُوٓاْ إِنَّا بِكُلّٖ كَٰفِرُونَ','transliteration'=>'Falammaa jaaa\'ahumul haqqu min \'indinaa qaaloo law-laa ootiya misla maaa ootiyaa Moosaa; awalam yakfuroo bimaaa ootiya Moosaa min qablu qaaloo sihraani tazaaharaa Wa-qaalooo innaa bikullin kaafiroon','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>49,'arabic_text'=>'قُلۡ فَأۡتُواْ بِكِتَٰبٖ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَآ أَتَّبِعۡهُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Qul faatoo bi-Kitaabim min \'indil laahi huwa ahdaa minhu-maaa attabi\'hu in kuntum saadiqeen','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>50,'arabic_text'=>'فَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Fa-il lam yastajeeboo laka fa\'lam annamaa yattabi\'oona ahwaaa\'ahum; Wa-man adallu mimmanit taba\'a hawaahu bighari hudam minal laah; innal laaha laa yahdil qawmaz zaalimeen','page_number'=>391,'juz_number'=>20,'hizb_number'=>39,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>51,'arabic_text'=>'۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Wa-laqad wassalnaa lahumul qawla la\'allahum yatazakkaroon','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>52,'arabic_text'=>'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ يُؤۡمِنُونَ','transliteration'=>'Allazeena aatainaahu-mul Kitaaba min qablihee hum bihee yu\'minoon','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>53,'arabic_text'=>'وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِينَ','transliteration'=>'Wa-izaa yutlaa \'alaihim qaaloo aamannaa biheee innahul haqqu mir rabbinaaa innaa kunnaa min qablihee muslimeen','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>54,'arabic_text'=>'أُوْلَٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','transliteration'=>'Ulaaa\'ika yu\'tawna ajrahum marratayni bimaa sabaroo Wa-yadra\'oona bil-hasanatis saiyyi\'ata Wa-mimmmaa razaq-naahum yunfiqoon','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>55,'arabic_text'=>'وَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ','transliteration'=>'Wa-izaa sami\'ul laghwa a\'radoo \'anhu Wa-qaaloo lanaaa a\'maalunaa Wa-lakum a\'maalukum salaamun \'alaikum laa nabtaghil jaahileen','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>56,'arabic_text'=>'إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ','transliteration'=>'Innaka laa tahdee man ahbata Wa-laakinna laaha yahdee maien yashaaa\'; Wa-Huwaa \'lamu bilmuhtadeen','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>57,'arabic_text'=>'وَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-qaalooo in nattabi\'il hudaa ma\'aka nutakhattaf min ardinaa; awalam numakkkil lahum haraman aaminany yujbaaa ilaihi samaraatu kulli shai\'ir rizqam mil ladunnaa Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>58,'arabic_text'=>'وَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۭ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ','transliteration'=>'Wa-kam ahlaknaa min qaryatim batirat ma\'eeshatahaa fatilka masaakinuhum lam tuskam mim ba\'dihim illaa qaleelaa; Wa-kunnaa Nahnul waariseen','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>59,'arabic_text'=>'وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ','transliteration'=>'Wa-maa kaana Rabbuka muhlikal quraa hattaa yab\'asa feee ummihaa Rasoolany yatloo \'alaihim aayaatina; Wa-maa kunnaa muhlikil quraaa illaa Wa-ahluhaa zaalimoon','page_number'=>392,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>60,'arabic_text'=>'وَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ','transliteration'=>'Wa-maaa ooteetum min shai\'in famataa\'ul hayaatid dunyaa Wa-zeenatuhaa; Wa-maa \'indal laahi khairunw Wa-abqaa; afalaa ta\'qiloon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>61,'arabic_text'=>'أَفَمَن وَعَدۡنَٰهُ وَعۡدًا حَسَنٗا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعۡنَٰهُ مَتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا ثُمَّ هُوَ يَوۡمَ ٱلۡقِيَٰمَةِ مِنَ ٱلۡمُحۡضَرِينَ','transliteration'=>'Afamanw wa\'adnaahu wa\'dan hasanan fahuwa laaqeehi kamam matta\'naahu mataa\'al hayaatid dunyaa summa huwa Yawmal Qiyaamati minal muhdareen','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>62,'arabic_text'=>'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ','transliteration'=>'Wa-Yawma yunaadeehim fa-yaqoolu aina shurakaaa-\'iyal lazeena kuntum taz\'umoon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>63,'arabic_text'=>'قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ','transliteration'=>'Qaalal lazeena haqqa \'alaihimul qawlu Rabbanaa haaa\'ulaaa\'il lazeena aghwainaa aghwainaahu kamaa ghawainaa tabarraanaaa ilaika maa kaanoo iyyaanaa ya\'budoon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>64,'arabic_text'=>'وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ','transliteration'=>'Wa-qeelad \'oo shurakaaa\'akum fada\'awhum falam yastajeeboo lahum Wa-ra-awul \'azaab; law annahum kaanoo yahtadoon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>65,'arabic_text'=>'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ','transliteration'=>'Wa-Yawma yunaadeehim fa-yaqoolu maazaaa ajabtumul mursaleen','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>66,'arabic_text'=>'فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ','transliteration'=>'Fa\'amiyat \'alaihimul ambaaa\'u Yawma\'izin fahum laa yatasaaa\'aloon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>67,'arabic_text'=>'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ','transliteration'=>'Fa-ammaa man taaba Wa-aamana Wa-\'amila saalihan fa\'asaaa ai yakoona minal mufliheen','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>68,'arabic_text'=>'وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Wa-Rabbuka yakhuluqu maa yashaaa\'u Wa-yakhtaar; maa kaana lahumul khiyarah; Subhannal laahi Wa-Ta\'aalaa \'ammmaa yushrikoon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>69,'arabic_text'=>'وَرَبُّكَ يَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ','transliteration'=>'Wa-Rabbuka ya\'lamu maa tukinnu sudooruhum Wa-maa yu\'linoon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>70,'arabic_text'=>'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-Huwal laahu laaa ilaaha illaa Huwa lahul hamdu fil oolaa wal-Aakhirati Wa-lahul hukmu Wa-ilaihi turja\'oon','page_number'=>393,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>71,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ','transliteration'=>'Qul ara\'aitum in ja\'alal laahu \'alaikumul laila sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaa-teekum bidiyaaa\'in afalaa tasma\'oon','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>72,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِلَيۡلٖ تَسۡكُنُونَ فِيهِۚ أَفَلَا تُبۡصِرُونَ','transliteration'=>'Qul ara\'aitum in ja\'alal laahu \'alaikumun nahaara sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaateekum bilailin taskunoona feehi afalaa tubsiroon','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>73,'arabic_text'=>'وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wa-mir rahmatihee ja\'ala lakumul laila wannahaara litaskunoo feehi Wa-litabtaghoo min fadlihee Wa-la\'allakum tashkuroon','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>74,'arabic_text'=>'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ','transliteration'=>'Wa-Yawma yunaadeehim fa-yaqoolu aina shurakaaa\'iyal lazeena kuntum tazz\'umoon','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>75,'arabic_text'=>'وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ شَهِيدٗا فَقُلۡنَا هَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Wa-naza\'naa min kulli ummatin shaheedan faqulnaa haatoo burhaanakum fa\'alimooo annal haqqa lillaahi Wa-dalla \'anhum maa kaanoo yaftaroon','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>76,'arabic_text'=>'۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ','transliteration'=>'Inna Qaaroona kaana min qawmi Moosaa fabaghaaa \'alaihim Wa-aatainaahu minal kunoozi maaa inna mafaati-hahoo latanooo\'u bil\'usbati ulil quwwati iz qaala lahoo qawmuhoo laa tafrah innal laahaa laa yuhibbul fariheen','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>77,'arabic_text'=>'وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ','transliteration'=>'Wabtaghi feemaaa aataakal laahud Daaral Aakhirata Wa-laa tansa naseebaka minad dunyaa Wa-ahsin kamaaa ahsanal laahu ilaika Wa-laa tabghil fasaada fil ardi innal laaha laa yuhibbul mufsideen','page_number'=>394,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>78,'arabic_text'=>'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ','transliteration'=>'Qaala innamaaa ootee-tuhoo \'alaa \'ilmin \'indeee; awalam ya\'lam annal laaha qad ahlaka min qablihee minal qurooni man huwa ashaddu minhu quwwatanw Wa-aksaru jam\'aa; Wa-laa yus\'alu \'an zunoobihimul mujrimoon','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>79,'arabic_text'=>'فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ','transliteration'=>'Fakharaja \'alaa qawmihee fee zeenatih; qaalal lazeena yureedoonal hayaatad dunyaa yaalaita lanaa misla maaa ootiya Qaaroonu innahoo lazoo hazzin \'azeem','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>80,'arabic_text'=>'وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ','transliteration'=>'Wa-qaalal lazeena ootul \'ilma wailakum sawaabul laahi khairul liman aamana Wa-\'amila saalihaa; Wa-laa yulaq-qaahaaa illas saabiroon','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>81,'arabic_text'=>'فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ','transliteration'=>'Fakhasafnaa bihee Wa-bidaarihil arda famaa kaana laho min fi\'atien yansuroo-nahoo min doonil laahi Wa-maa kaana minal muntasireen','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>82,'arabic_text'=>'وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ','transliteration'=>'Wa-asbahal lazeena tamannaw makaanahoo bil-amsi yaqooloona waika-annal laaha yabsutur rizqa limaien ya-shaaa\'u min \'ibaadihee Wa-yaqdiru law-laaa am mannal laahu \'alainaa lakhasafa binaa waika-annahoo laa yuflihul kaafiroon','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>83,'arabic_text'=>'تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ','transliteration'=>'Tilkad Daarul Aakhiratu naj\'aluhaa lillazeena laa yureedoona \'uluwwan fil ardi Wa-laa fasaadaa; wal-\'aaqibatu lilmuttaqeen','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>84,'arabic_text'=>'مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Man jaaa\'a bilhasanati falahoo khairum minhaa Wa-man jaaa\'a bissaiyi\'ati falaa yujzal lazeena \'amilus saiyiaati illaa maa kaanoo ya\'maloon','page_number'=>395,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>85,'arabic_text'=>'إِنَّ ٱلَّذِي فَرَضَ عَلَيۡكَ ٱلۡقُرۡءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٖۚ قُل رَّبِّيٓ أَعۡلَمُ مَن جَآءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Innal azee farada \'alaikal Qur-aana laraaadduka ilaa ma\'aad; qur Rabbeee a\'lamu man jjaaa\'a bil-hudaa Wa-man huwa fee dalaalim mubeen','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>86,'arabic_text'=>'وَمَا كُنتَ تَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِيرٗا لِّلۡكَٰفِرِينَ','transliteration'=>'Wa-maa kunta tarjooo aien yulqaaa ilaikal Kitaabu illaa rahmatam mir Rabbika falaa takoonanna zaheeral lilkaafireen','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>87,'arabic_text'=>'وَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Wa-laa yasuddunnaka \'an Aayaatil laahi ba\'da iz unzilat ilaika wad\'u ilaa Rabbika Wa-laa takonanna minal mushrikeen','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>28,'ayah_number'=>88,'arabic_text'=>'وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-laa tad\'u ma\'al laahi ilaahan aakhar; laaa ilaaha illaa Hoo; kullu shai\'in haalikun illaa Wajhah; lahul hukkmu Wa-ilaihi turja\'oon','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            /* Surah 29: The Spider (Al-'Ankabut) */
            ['surah_id'=>29,'ayah_number'=>1,'arabic_text'=>'الٓمٓ','transliteration'=>'Alif-Laaam-Meeem','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>2,'arabic_text'=>'أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ','transliteration'=>'Ahasiban naasu any yutrakooo any yaqoolooo aamannaa Wa-hum la yuftanoon','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>3,'arabic_text'=>'وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ','transliteration'=>'Wa-laqad fatannal lazeena min qablihim fala-ya\'lamannal laahul lazeena sadaqoo Wa-la-ya\'lamannal kaazibeen','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>4,'arabic_text'=>'أَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ سَآءَ مَا يَحۡكُمُونَ','transliteration'=>'Am hasibal lazeena ya\'maloonas sayyiaati any yasbiqoonaa; saaa\'a maa yahkumoon','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>5,'arabic_text'=>'مَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Man kaana yarjoo liqaaa \'allaahi fa-inna ajalal laahi laaat; Wa-Huwass Sameeul \'Aleem','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>6,'arabic_text'=>'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفۡسِهِۦٓۚ إِنَّ ٱللَّهَ لَغَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-man jaahada fainnamaa yujaahidu linafsih; innal laaha laghaniyyun \'anil \'aalameen','page_number'=>396,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>7,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wallazeena aamanoo Wa-\'amilus saalihaati lanukaf-firanna \'anhum saiyiaatihim Wa-lanajziyannahum ahsanal lazee kaanoo ya\'maloon','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>8,'arabic_text'=>'وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حُسۡنٗاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-wassainal insaana biwaalidaihi husnanw Wa-in jaahadaaka litushrika bee maa laisa laka bihee \'ilmun falaa tuti\'humaa; ilaiya marji\'ukum fa-unabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>9,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّٰلِحِينَ','transliteration'=>'Wallazeena aamanoo wa\'amilus saalihaati lanudkhilan-nahum fis saaliheen','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>10,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَئِن جَآءَ نَصۡرٞ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِي صُدُورِ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-minan naasi maien yaqoolu aamannaa billaahi faizaaa ooziya fil laahi ja\'ala fitnatan naasi ka\'azaabil laahi Wa-la\'in jaaa\'a nasrum mir Rabbika la-yaqoolunna innaa kunnaa ma\'akum; awa-laisal laahu bi-a\'lama bimaa fee sudooril \'aalameen','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>11,'arabic_text'=>'وَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَلَيَعۡلَمَنَّ ٱلۡمُنَٰفِقِينَ','transliteration'=>'Wa-la-ya\'lamannal laahul lazeena aamanoo Wa-la-ya\'lamannal munaafiqeen','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>12,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ ٱتَّبِعُواْ سَبِيلَنَا وَلۡنَحۡمِلۡ خَطَٰيَٰكُمۡ وَمَا هُم بِحَٰمِلِينَ مِنۡ خَطَٰيَٰهُم مِّن شَيۡءٍۖ إِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Wa-qaalal lazeena kafaroo lillazeena aamanut tabi\'oo sabeelanaa walnahmil khataayaakum Wa-maa hum bihaamileena min khataa-yaahum min shai\'in innahum lakaaziboon','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>13,'arabic_text'=>'وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Wa-la-yahmilunna asqaa-lahum Wa-asqaalam ma\'a asqaalihim Wa-la-yus\'alunna Yawmal Qiyaamati \'ammaa kaanoo yaftaroon','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>14,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ','transliteration'=>'Wa-laqad arsalnaa Noohan ilaa qawmihee falabisa feehim alfa sanatin illaa khamseena \'aaman fa-akhazahumut toofaanu Wa-hum zaalimoon','page_number'=>397,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>15,'arabic_text'=>'فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ','transliteration'=>'Fa-anjainaahu Wa-as-haabas safeenati Wa-ja\'alnaahaaa Aayatal lil\'aalameen','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>16,'arabic_text'=>'وَإِبۡرَٰهِيمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُۖ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Wa-Ibraheema iz qaala liqawmihi\' budul laaha wattaqoohu zaalikum khayrul lakum in kuntum ta\'lamoon','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>17,'arabic_text'=>'إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡقٗا فَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Innamaa ta\'budoona min doonil laahi awsaananw-wa takhluqoona ifkaa; innal lazeena ta\'budoona min doonil laahi laa yamlikoona lakum rizqan fabtaghoo \'indal laahir rizqa wa\'budoohu washkuroo lahooo ilaihi turja\'oon','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>18,'arabic_text'=>'وَإِن تُكَذِّبُواْ فَقَدۡ كَذَّبَ أُمَمٞ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Wa-in tukazziboo faqad kazzaba umamum min qablikum Wa-maa\' alar Rasooli illal balaaghul mubeen','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>19,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ كَيۡفَ يُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥٓۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ','transliteration'=>'Awa-lam yaraw kaifa yubdi\'ul laahul khalqa summa yu\'eeduh; inna zaalika \'alal laahi yaseer','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>20,'arabic_text'=>'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Qul seeroo fil ardi fanzuroo kaifa bada\'a al-khalqa summal laahu yunshi\'-\'un nash-atal Aakhirah; innal laaha \'alaa kulli shai\'in Qadeer','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>21,'arabic_text'=>'يُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ','transliteration'=>'Yu\'azzibu many yashaaa\'u Wa-yarhamu many yashaaa\'; Wa-ilaihi tuqlaboon','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>22,'arabic_text'=>'وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ','transliteration'=>'Wa-maaa antum bimu\'jizeena fil ardi Wa-laa fis samaaa\'i Wa-maa lakum min doonil laahi minw waliyyinw Wa-laa naseer','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>23,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Wallazeena kafaroo bi-Aayaatil laahi Wa-liqaaa\'iheee ulaaa\'ika ya\'isoo mir rahmatee Wa-ulaaa\'ika lahum \'azaabun aleem','page_number'=>398,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>24,'arabic_text'=>'فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Famaa kaana jawaaba qawmiheee illaaa an qaaluqtuloohu aw harriqoohu fa-anjaahul laahu minan naar; inna fee zaalika la Aayaatil laqawmien yu\'minoon','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>25,'arabic_text'=>'وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ','transliteration'=>'Wa-qaala innamat takhaz-tum min doonil laahi awsaanam mawaddata bainikum fil hayaatid dunyaa summa Yawmal Qiyaamati yakfuru ba\'dukum biba\'dinw Wa-yal\'anu ba\'dukum ba\'danw Wa-ma\'waakumun Naaru Wa-maa lakum min naasireen','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>26,'arabic_text'=>'۞ فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Fa-aamana lahoo Loot; Wa-qaala innee muhajirun ilaa Rabbee innahoo Huwal \'Azeezul Hakeem','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>27,'arabic_text'=>'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-wahabnaa lahoo Iss-haaqa Wa-Ya\'Qooba Wa-ja\'alnaa fee zurriyyatihin Nubuwwata wal-Kitaaba Wa-aatainaahu ajrahoo fid dunyaa Wa-innahoo fil aakhirati laminas saaliheen','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>28,'arabic_text'=>'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-Lootan iz qaala liqawmiheee innakum ta\'toonal faahishata maa sabaqakum bihaa min ahadin minal \'aalameen','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>29,'arabic_text'=>'أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِيلَ وَتَأۡتُونَ فِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'A\'innakum la-ta\'toonar rijaala Wa-taqta\'oonas sabeela Wa-ta\'toona fee naadeekumul munkara famaa kaana jawaaba qawmiheee illaaa an qaalu\' tinaaa bi\'azaabil laahi in kunta minas saadiqeen','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>30,'arabic_text'=>'قَالَ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ','transliteration'=>'Qaala Rabbin surnee \'alal qawmil mufsideen','page_number'=>399,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>31,'arabic_text'=>'وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ','transliteration'=>'Wa-lammaa jaaa\'at Rusulunaaa Ibraaheema bil-bushraa qaalooo innaa muhlikoo ahli haazihil qaryati inna ahlahaa kaanoo zaalimeen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>32,'arabic_text'=>'قَالَ إِنَّ فِيهَا لُوطٗاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ','transliteration'=>'Qaala inna feeha Lootaa; qaaloo nahnu a\'lamu biman feehaa lanunajjjiyannahoo Wa-ahlahooo illam ra-atahoo kaanat minal ghaabireen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>33,'arabic_text'=>'وَلَمَّآ أَن جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗاۖ وَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ','transliteration'=>'Wa-lammaaa an jaaa\'at Rusulunaa Lootan seee\'a bihim Wa-daaqa bihim zar\'anw Wa-qaaloo laa takhaf Wa-laa tahzan innaa munajjooka Wa-ahlaka illam ra-ataka kaanat minal ghaabireen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>34,'arabic_text'=>'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ','transliteration'=>'Innaa munziloona \'alaaa ahli haazihil qaryati rijzan minas samaaa\'i bimaa kaanoo yafsuqoon','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>35,'arabic_text'=>'وَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wa-laqad taraknaa min-haaa aayatan baiyyinatan liqawmien ya\'qiloon','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>36,'arabic_text'=>'وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','transliteration'=>'Wa-ilaa Madyana akhaahum Shu\'ayban faqaala yaa-qawmi\' budul laaha warjul yawmal aakhira Wa-laa ta\'saw fil ardi mufsideen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>37,'arabic_text'=>'فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ','transliteration'=>'Fakazzaboohu fa-akhazat-humur rajfatu fa-asbahoo fee daarihim jaasimeen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>38,'arabic_text'=>'وَعَادٗا وَثَمُودَاْ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ','transliteration'=>'Wa-\'Aadanw Wa-Samooda Wa-qad tabaiyana lakum min masaakinihim Wa-zaiyana lahumush Shaitaanu a\'maalahum fasaddahum \'anis sabeeli Wa-kaanoo mustabsireen','page_number'=>400,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>39,'arabic_text'=>'وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ','transliteration'=>'Wa-Qaaroona Wa-Fir\'awna Wa-haamaana Wa-laqad jaaa\'ahum Moosa bilbaiyinaati fastakbaroo fil ardi Wa-maa kaanoo saabiqeen','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>40,'arabic_text'=>'فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبٗا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Fakullan akhaznaa bi-zanbihee faminhum man arsalnaa \'alaihi haasibaa; Wa-minhum man akhazat-hus saihatu Wa-minhum man khasafnaa bihil arda Wa-minhum man aghraqnaa; Wa-maa kaanal laahu li-yazlimahum Wa-laakin kaanoo anfusahum yazlimoon','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>41,'arabic_text'=>'مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Masalul lazeenat takhazoo min doonil laahi awliyaaa\'a kamasalil \'ankaboot, ittakhazat baitaa; Wa-inna awhanal buyooti la-baitul \'ankaboot; law kaanoo ya\'lamoon','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>42,'arabic_text'=>'إِنَّ ٱللَّهَ يَعۡلَمُ مَا يَدۡعُونَ مِن دُونِهِۦ مِن شَيۡءٖۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Innal laaha ya\'lamu maa yad\'oona min doonihee min shai\'; Wa-Huwal \'Azeezul Hakeem','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>43,'arabic_text'=>'وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ','transliteration'=>'Wa-tilkal amsaalu nadribuhaa linnaasi Wa-maa ya\'qiluhaaa illal \'aalimoon','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>44,'arabic_text'=>'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ','transliteration'=>'Khalaqal laahus samaawaati wal-arda bilhaqq; inna fee zaalika la-aayatan lil-mu\'mineen','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>45,'arabic_text'=>'ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ','transliteration'=>'Utlu maaa oohiya ilaika minal Kitaabi Wa-aqimis Salaata innas Salaata tanhaa \'anil fahshaaa\'i wal-munkar; Wa-lazikrul laahi akbar; wal-laahu ya\'lamu maa tasna\'oon','page_number'=>401,'juz_number'=>20,'hizb_number'=>40,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>46,'arabic_text'=>'۞ وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ','transliteration'=>'Wa-laa tujaadilooo Ahlal Kitaabi illaa billatee hiya ahsanu illal lazeena zalamoo minhum Wa-qoolooo aamannaa billazeee unzila ilainaa Wa-unzila ilaikum Wa-illaahunna Wa-illahukum waahidunw-wa nahnu lahoo muslimoon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>47,'arabic_text'=>'وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ','transliteration'=>'Wa-kazaalika anzalnaaa ilaikal Kitaab; fallazeena aatainaahumul kitaaba yu\'minoona bihee Wa-min haaa\'ulaaa\'i many yu\'minu bih; Wa-maa yajhadu bi\'Aayaatinaa illal kaafiroon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>48,'arabic_text'=>'وَمَا كُنتَ تَتۡلُواْ مِن قَبۡلِهِۦ مِن كِتَٰبٖ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذٗا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ','transliteration'=>'Wa-maa kunta tatloo min qablihee min kitaabinw Wa-laa takhuttubhoo bi-yameenika izal lartaabal mubtiloon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>49,'arabic_text'=>'بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ','transliteration'=>'Bal huwa aayaatum baiyinaatun fee sudooril lazeena ootul \'ilm; Wa-maa yajhadu bi-aayaatinaa illaz zaalimoon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>50,'arabic_text'=>'وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ','transliteration'=>'Wa-qaaloo law-laaa unzila \'alaihi aayaatum mir Rabbihee qul innamal aayaatu \'indal laahi Wa-innamaaa ana nazeerum mubeen','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>51,'arabic_text'=>'أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Awa-lam yakfihim annaaa anzalnaa \'alaikal kitaaba yutlaa \'alaihim; inna fee zaalika larahmatanw Wa-zikraa liqawmien yu\'minoon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>52,'arabic_text'=>'قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ بِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Qul kafaa billaahi bainee Wa-bainakum shaheedaa; ya\'lamu maa fis samaawaati wal-ard; wallazeena aamanoo bil-baatili Wa-kafaroo billaahi ulaaa\'ika humul khaasiroon','page_number'=>402,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>53,'arabic_text'=>'وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَآ أَجَلٞ مُّسَمّٗى لَّجَآءَهُمُ ٱلۡعَذَابُۚ وَلَيَأۡتِيَنَّهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Wa-yasta\'jiloonaka bil\'azaab; Wa-law-laaa ajalum musammal lajaaa\'ahumul a\'zaab; Wa-la-ya\'tiannahum baghta-tanw Wa-hum laa yash\'uroon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>54,'arabic_text'=>'يَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ','transliteration'=>'Yasta\'jiloonaka bil\'azaab; Wa-inna Jahannama la-muheetatum bil-kaafireen','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>55,'arabic_text'=>'يَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Yawma yaghshaahumul \'azaabu min fawqihim Wa-min tahti arjulihim Wa-yaqoolu zooqoo maa kuntum ta\'maloon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>56,'arabic_text'=>'يَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ','transliteration'=>'Yaa-\'ibaadiyal lazeena aamanooo inna ardee waasi-\'atun fa-iyyaaya fa\'budoon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>57,'arabic_text'=>'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ','transliteration'=>'Kullu nafsin zaaa\'iqatul mawti summa ilainaa turja\'oon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>58,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ','transliteration'=>'Wallazeena aamanoo Wa-\'amilus saalihaati la-nubawwi-\'annahum minal Jannati ghurafan tajree min tahtihal anhaaru khaalideena feehaa; ni\'ma ajrul \'aamileen','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>59,'arabic_text'=>'ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','transliteration'=>'Allazeena sabaroo Wa-\'alaa Rabbihim yatawakkaloon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>60,'arabic_text'=>'وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-ka-ayyim min daaabbatil laa tahmilu rizqahaa; al-laahu yarzuquhaa Wa-iyyaakum; Wa-Huwas Samee\'ul Aleem','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>61,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ','transliteration'=>'Wa-la\'in sa-altahum man khalaqas samaawaati wal-arda Wa-sakhkharash shamsa wal-qamara la-yaqoolunnal laahu fa-anna yu\'fakoon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>62,'arabic_text'=>'ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥٓۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Allaahu yabsutur rizqa limaien yashaaa\'u min \'ibaadihee Wa-yaqdiru lah; innal laaha bikulli shai\'in Aleem','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>63,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ','transliteration'=>'Wa-la\'in sa-altahum man nazzala minas samaaa\'i maaa\'an fa-ahyaa bihil arda min ba\'di mawtihaa la-yaqoolunnal laah; qulil hamdu lillah; bal aksaruhum laa ya\'qiloon','page_number'=>403,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>64,'arabic_text'=>'وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Wa-maa haazihil hayaa-tud dunyaaa illaa lahwunw wa-la\'ib; Wa-innad Daaral Aakhirata la-hiyal ha-yawaan; law kaano ya\'lamoon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>65,'arabic_text'=>'فَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ','transliteration'=>'Fa-izaa rakiboo fil fulki da\'awul laaha mukhliseena lahud deena falammaa najjaa-hum ilal barri izaa hum yushrikoon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>66,'arabic_text'=>'لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ يَعۡلَمُونَ','transliteration'=>'Li-yakfuroo bimaaa aatainaahum Wa-li-yatamatta\'oo fasawfa ya\'lamoon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>67,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ','transliteration'=>'Awalam yaraw annaa ja\'alnaa haraman aaminanw Wa-yutakhattafun naasu min haw-lihim; afabil-baatili yu\'minoona Wa-bini\'matil laahi yakfuroon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>68,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ','transliteration'=>'Wa-man azlamu mimma nif-taraa \'alal laahi kaziban aw kazzaba bilhaqqi lammaa jaaa\'ah; alaisa fee jahannama maswal lil-kaafireen','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>29,'ayah_number'=>69,'arabic_text'=>'وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Wallazeena jaahadoo feenaa lanahdiyannahum subulana; Wa-innal laaha lama\'al muhsineen','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            /* Surah 30: The Romans (Ar-Rum) */
            ['surah_id'=>30,'ayah_number'=>1,'arabic_text'=>'الٓمٓ','transliteration'=>'Alif-Laaam-Meeem','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>2,'arabic_text'=>'غُلِبَتِ ٱلرُّومُ','transliteration'=>'Ghulibatir Room','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>3,'arabic_text'=>'فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ','transliteration'=>'Feee adnal ardi Wa-hum mim ba\'di ghalabihim sa-yaghliboon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>4,'arabic_text'=>'فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Fee bid\'i sineen; lillaahil amru min qablu Wa-mim ba\'d; Wa-yawma\'izien yafrahul mu\'minoon','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>5,'arabic_text'=>'بِنَصۡرِ ٱللَّهِۚ يَنصُرُ مَن يَشَآءُۖ وَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ','transliteration'=>'Binasril laa; yansuru maien yashaaa\'u Wa-Huwal \'Azeezur Raheem','page_number'=>404,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>6,'arabic_text'=>'وَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Wa\'dal laahi laa yukhliful laahu wa\'dahoo Wa-laakin-na aksaran naasi laa ya\'lamoon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>7,'arabic_text'=>'يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ','transliteration'=>'Ya\'lamoona zaahiram minal hayaatid dunya Wa-hum \'anil Aakhirati hum ghaafiloon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>8,'arabic_text'=>'أَوَلَمۡ يَتَفَكَّرُواْ فِيٓ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ بِلِقَآيِٕ رَبِّهِمۡ لَكَٰفِرُونَ','transliteration'=>'Awalam yatafakkaroo feee anfusihim; maa khalaqal laahus samaawaati wal-arda Wa-maa bainahumaaa illaa bil-haqqi Wa-ajalim musammaa; Wa-inna kaseeram minan naasi biliqaaa\'i Rabbihim lakaafiroon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>9,'arabic_text'=>'أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','transliteration'=>'Awalam yaseeroo fil ardi fa-yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; kaanooo ashadda minhhum quwwatanw Wa-asaarul arda Wa-\'amaroohaaa aksara mimmaa \'amaroohaa Wa-jaaa\'athum Rusuluhum bil-baiyyinaati famaa kaanal laahu liyazli-mahum Wa-laakin kaanooo anfusahum yazlimoon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>10,'arabic_text'=>'ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا يَسۡتَهۡزِءُونَ','transliteration'=>'Summa kaana \'aaqibatal lazeena asaaa\'us sooo-aaa an kazzaboo bi-aayaatil laahi Wa-kaanoo bihaa yastahzi\'oon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>11,'arabic_text'=>'ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Allaahu yabda\'ul khalqa summa yu\'eeduhoo summa ilaihi turja\'oon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>12,'arabic_text'=>'وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُبۡلِسُ ٱلۡمُجۡرِمُونَ','transliteration'=>'Wa-yawma taqoomus Saa\'atu yublisul mujrimoon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>13,'arabic_text'=>'وَلَمۡ يَكُن لَّهُم مِّن شُرَكَآئِهِمۡ شُفَعَٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمۡ كَٰفِرِينَ','transliteration'=>'Wa-lam yakul lahum min shurakaaa\'ihim shufa\'aaa\'u Wa-kaanoo bishurakaaa\'ihim kaafireen','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>14,'arabic_text'=>'وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَتَفَرَّقُونَ','transliteration'=>'Wa-Yawma taqoomus Saa\'atu Yawma\'izien yatafarraqoon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>15,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ','transliteration'=>'Fa-ammal lazeena aamanoo Wa-\'amilus saalihaati fahum fee rawdatien yuhbaroon','page_number'=>405,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>16,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ فَأُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ','transliteration'=>'Wa-ammal lazeena kafaroo Wa-kazzaboo bi-Aayaatinaa Wa-liqaaa\'il Aakhirati faulaaa\'ika fil \'azaabi muhdaroon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>17,'arabic_text'=>'فَسُبۡحَٰنَ ٱللَّهِ حِينَ تُمۡسُونَ وَحِينَ تُصۡبِحُونَ','transliteration'=>'Fa-Subhaanal laahi heena tumsoona Wa-heena tusbihoon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>18,'arabic_text'=>'وَلَهُ ٱلۡحَمۡدُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَعَشِيّٗا وَحِينَ تُظۡهِرُونَ','transliteration'=>'Wa-lahul hamdu fis samaawaati wal-ardi Wa-\'ashiyyanw Wa-heena tuzhiroon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>19,'arabic_text'=>'يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَيُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَٰلِكَ تُخۡرَجُونَ','transliteration'=>'Yukhrijul haiyya minal maiyyiti Wa-yukhrijul maiyyita minal haiyyi Wa-yuhyil arda ba\'da mawtihaa; Wa-kazaalika tukhrajoon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>20,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَكُم مِّن تُرَابٖ ثُمَّ إِذَآ أَنتُم بَشَرٞ تَنتَشِرُونَ','transliteration'=>'Wa-min Aayaatiheee an khalaqakum min turaabin summa izaaa antum basharun tantashiroon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>21,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Wa-min Aayaatiheee an khalaqa lakum min anfusikum azwaajal litaskunooo ilaihaa Wa-ja\'ala bainakum mawad-datanw Wa-rahmah; inna fee zaalika la-Aayaatil liqawmien yatafakkaroon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>22,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡعَٰلِمِينَ','transliteration'=>'Wa-min Aayaatihee khalqus samaawaati wal-aardi wakhtilaafu alsinatikum Wa-alwaanikum; inna fee zaalika la-Aayaatil lil\'aalimeen','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>23,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ','transliteration'=>'Wa-min Aayaatihee manaamukum bil-laili wannahaari wabtighaaa\'ukum min fadlih; inna fee zaalika la-Aayaatil liqawmien yasma\'oon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>24,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءٗ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wa-min Aayaatihee yureekumul barqa khawfanw Wa-tama\'anw Wa-yunazzilu minas samaaa\'i maaa\'an fa-yuhyee bihil arda ba\'da mawtihaaa inna fee zaalika la-Aayaatil liqawmien ya\'qiloon','page_number'=>406,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>25,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةٗ مِّنَ ٱلۡأَرۡضِ إِذَآ أَنتُمۡ تَخۡرُجُونَ','transliteration'=>'Wa-min Aayaatihee an taqoomas samaaa\'u wal-ardu bi-amrih; summa izaa da\'aakum da\'watam minal ardi izaaa antum takhrujoon','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>26,'arabic_text'=>'وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ','transliteration'=>'Wa-lahoo man fis samaawaati wal-ardi kullul lahoo qaanitoon','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>27,'arabic_text'=>'وَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Wa-Huwal lazee yabda\'ul khalqa summa yu\'eeduhoo Wa-huwa ahwanu \'alaih; Wa-lahul masalul la\'laa fis samaawaati wal-ard; Wa-Huwal \'Azeezul Hakeem','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>28,'arabic_text'=>'ضَرَبَ لَكُم مَّثَلٗا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن شُرَكَآءَ فِي مَا رَزَقۡنَٰكُمۡ فَأَنتُمۡ فِيهِ سَوَآءٞ تَخَافُونَهُمۡ كَخِيفَتِكُمۡ أَنفُسَكُمۡۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Daraba lakum masalam min anfusikum hal lakum mimmaa malakat aymaanukum min shurakaaa\'a fee maa razaqnaakum fa-antum feehi sawaaa\'un takhaafoonahum kakheefa tikum anfusakum; kazaalika nufassilul Aayaati liqawminy ya\'qiloon','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>29,'arabic_text'=>'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓاْ أَهۡوَآءَهُم بِغَيۡرِ عِلۡمٖۖ فَمَن يَهۡدِي مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّٰصِرِينَ','transliteration'=>'Balit taba\'al lazeena zalamooo ahwaaa\'ahum bighairi \'ilmin famai yahdee man adallal laahu Wa-maa lahum min naasireen','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>30,'arabic_text'=>'فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Fa-aqim wajhaka liddeeni Haneefaa; fitratal laahil latee fataran naasa \'alaihaa; laa taabdeela likhalqil laah; zaalikad deenul qaiyimu Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>31,'arabic_text'=>'۞ مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ','transliteration'=>'Muneebeena ilaihi wattaqoohu Wa-aqeemus Salaata Wa-laa takoonoo minal mushrikeen','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>32,'arabic_text'=>'مِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ','transliteration'=>'Minal lazeena farraqoo deenahum Wa-kaanoo shiya\'an kullu hizbim bimaa ladaihim farihoon','page_number'=>407,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>33,'arabic_text'=>'وَإِذَا مَسَّ ٱلنَّاسَ ضُرّٞ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِيقٞ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ','transliteration'=>'Wa-izaa massan naasa durrun da\'aw Rabbahum muneebeena ilaihi summa izaaa azaqahum minhu rahmatan izaa fareequm minhum bi-Rabbihim yushrikoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>34,'arabic_text'=>'لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ','transliteration'=>'Li-yakfuroo bimaaa aatainaahum; fatamatta\'oo fasawfa ta\'lamoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>35,'arabic_text'=>'أَمۡ أَنزَلۡنَا عَلَيۡهِمۡ سُلۡطَٰنٗا فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِۦ يُشۡرِكُونَ','transliteration'=>'Am anzalnaa \'alaihim sultaanan fahuwa yatakallamu bimaa kaanoo bihee yushrikoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>36,'arabic_text'=>'وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ','transliteration'=>'Wa-izaaa azaqnan naasa rahmatan farihoo bihaa Wa-in tusibhum sayyi\'atum bimaa qaddamat aydeehim izaa hum yaqnatoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>37,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Awalam yaraw annal laaha yabsutur rizqa limaien yashaaa\'u Wa-yaqdir; inna fee zaalika la-Aayaatil liqawmien yu\'minoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>38,'arabic_text'=>'فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرٞ لِّلَّذِينَ يُرِيدُونَ وَجۡهَ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Fa-aati zal qurbaa haqqahoo walmiskeena wabnassabeel; zaalika khairul lil lazeena yureedoona Wajhal laahi Wa-ulaaa\'ika humul muflihoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>39,'arabic_text'=>'وَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ','transliteration'=>'Wa-maaa aataitum mir ribal li-yarbuwa feee amwaalin naasi falaa yarboo \'indal laahi Wa-maaa aataitum min zaakaatin tureedoona wajhal laahi fa-ulaaa\'ika humul mud\'ifoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>40,'arabic_text'=>'ٱللَّهُ ٱلَّذِي خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۖ هَلۡ مِن شُرَكَآئِكُم مَّن يَفۡعَلُ مِن ذَٰلِكُم مِّن شَيۡءٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Allaahul lazee khalaqa-kum summa razaqakum summa yumeetukum summa yuhyeekum hal min shurakaaa\'ikum maien yaf\'alu min zaalikum min shai\'; Sub-haanahoo Wa-Ta\'aalaa \'ammaa yushrikoon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>41,'arabic_text'=>'ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Zaharal fasaadu fil barri wal-bahri bimaa kasabat aydin naasi li-yuzeeqahum ba\'dal lazee \'amiloo la\'allahum yarji\'oon','page_number'=>408,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>42,'arabic_text'=>'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ','transliteration'=>'Qul seeroo fil ardi fanzuroo kaifa kaana \'aaqibatul lazeena min qabl; kaana aksaruhum mushrikeen','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>43,'arabic_text'=>'فَأَقِمۡ وَجۡهَكَ لِلدِّينِ ٱلۡقَيِّمِ مِن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ يَوۡمَئِذٖ يَصَّدَّعُونَ','transliteration'=>'Fa-aqim wajhaka lid-deenil qaiyyimi min qabli aien yaatiya Yawmul laa maradda lahoo minal laahi Yawma\'izien yassadda\'oon','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>44,'arabic_text'=>'مَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَٰلِحٗا فَلِأَنفُسِهِمۡ يَمۡهَدُونَ','transliteration'=>'Man kafara fa\'alaihi kufruhoo Wa-man \'amila saalihan fali-anfusihim yamhadoon','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>45,'arabic_text'=>'لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡكَٰفِرِينَ','transliteration'=>'Li-yajziyal lazeena aamanoo Wa-\'amilus saalihaati min fadlih; innahoo laa yuhibbul kaafireen','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>46,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٖ وَلِيُذِيقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِيَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wa-min Aayaatiheee aien yursilar riyaaha mubashshi-raatinw Wa-li-yuzeeqakum mir rahmatihee Wa-litajriyal fulku bi-amrihee Wa-litabtaghoo min fadlihee Wa-la\'allakum tashkuroon','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>47,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-laqad arsalnaa min qablika Rusulan ilaa qawmihim fajaaa\'oohum bil-baiyyinaati fantaqamnaa minal lazeena ajramoo Wa-kaana haqqan \'alainaa nasrul mu\'mineen','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>48,'arabic_text'=>'ٱللَّهُ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَيَبۡسُطُهُۥ فِي ٱلسَّمَآءِ كَيۡفَ يَشَآءُ وَيَجۡعَلُهُۥ كِسَفٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ','transliteration'=>'Allaahul lazee yursilur riyaaha fatuseeru sahaaban fa-yabsutuhoo fis samaaa\'i kaifa yashaaa\'u Wa-yaj\'aluhoo kisafan fataral wadqa yakhruju min khilaalihee fa-izaaa asaaba bihee mai yashaaa\'u min \'ibaadiheee izaa hum yastabshiroon','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>49,'arabic_text'=>'وَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ','transliteration'=>'Wa-in kaanoo min qabli aien yunazzala \'alaihim min qablihee lamubliseen','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>50,'arabic_text'=>'فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Fanzur ilaaa aasaari rahmatil laahi kaifa yuhyil arda ba\'da mawtihaa; inna zaalika lamuhyil mawtaa Wa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>409,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>51,'arabic_text'=>'وَلَئِنۡ أَرۡسَلۡنَا رِيحٗا فَرَأَوۡهُ مُصۡفَرّٗا لَّظَلُّواْ مِنۢ بَعۡدِهِۦ يَكۡفُرُونَ','transliteration'=>'Wa-la\'in arsalnaa reehan fara-awhu musfarral lazalloo mim ba\'dihee yakfuroon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>52,'arabic_text'=>'فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ مُدۡبِرِينَ','transliteration'=>'Fa-innaka laa tusmi\'ul mawtaa Wa-laa tusmi\'us summad du\'aaa\'a izaa wallaw mudbireen','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>53,'arabic_text'=>'وَمَآ أَنتَ بِهَٰدِ ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ','transliteration'=>'Wa-maa anta bihaadil \'umyi \'an dalaalatihim in tusmi\'u illaa maien yuminu bi-aayaatinaa fahum muslimoon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>54,'arabic_text'=>'۞ ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ','transliteration'=>'Allahul lazee khalaqa-kum min du\'fin summa ja\'ala mim ba\'di du\'fin quwwatan summa ja\'ala mim ba\'di quwwatin du\'fanw Wa-shaibah; yakhluqu maa yashaaa\'u Wa-Huwal \'Aleemul Qadeer','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>55,'arabic_text'=>'وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ كَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ','transliteration'=>'Wa-Yawma taqoomus Saa\'atu yuqsimul mujrimoona maa labisoo ghaira saa\'ah; kazaalika kaanoo yu\'fakoon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>56,'arabic_text'=>'وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ','transliteration'=>'Wa-qaalal lazeena ootul \'ilma wal-eemaana laqad labistum fee kitaabil laahi ilaa yawmil ba\'si fahaazaa yawmul ba\'si Wa-laakinnakum kuntum laa ta\'lamoon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>57,'arabic_text'=>'فَيَوۡمَئِذٖ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ','transliteration'=>'Fa-Yawma\'izil laa yanfa\'ul lazeena zalamoo ma\'ziratu-hum Wa-laa hum yusta\'taboon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>58,'arabic_text'=>'وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖۚ وَلَئِن جِئۡتَهُم بِـَٔايَةٖ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ','transliteration'=>'Wa-laqad darabnaa linnaasi fee haazal Quraani min kulli masal; Wa-la\'in ji\'tahum bi-aayatil la-yaqoolannal lazeena kafaroo in antum illaa mubtiloon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>59,'arabic_text'=>'كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ','transliteration'=>'Kazaalika yatba\'ul laahu \'alaa quloobil lazeena laa ya\'lamoon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>30,'ayah_number'=>60,'arabic_text'=>'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ','transliteration'=>'Fasbir inna wa\'dal laahi haqqunw Wa-laa yastakhif-fannakal lazeena laa yooqinoon','page_number'=>410,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            /* Surah 31: Luqman (Luqman) */
            ['surah_id'=>31,'ayah_number'=>1,'arabic_text'=>'الٓمٓ','transliteration'=>'Alif-Laaam-Meeem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>2,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ','transliteration'=>'Tilka Aayaatul Kitaabil Hakeem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>3,'arabic_text'=>'هُدٗى وَرَحۡمَةٗ لِّلۡمُحۡسِنِينَ','transliteration'=>'Hudanw Wa-rahmatal lilmuhsineen','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>4,'arabic_text'=>'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ','transliteration'=>'Allazeena yuqeemoonas Salaata Wa-yu\'toonaz Zakaata Wa-hum bil-Aakhirati hum yooqinoon','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>5,'arabic_text'=>'أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Ulaaa\'ika \'alaa hudam mir Rabbihim Wa-ulaaa\'ika humul muflihoon','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>6,'arabic_text'=>'وَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ','transliteration'=>'Wa-minan naasi maien yashtaree lahuwal hadeesi li-yudilla \'an sabeelil laahi bighairi \'ilminw Wa-yattakhizahaa huzuwaa; ulaaa\'ika lahum \'azaabum muheen','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>7,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا وَلَّىٰ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَا كَأَنَّ فِيٓ أُذُنَيۡهِ وَقۡرٗاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٍ','transliteration'=>'Wa-izaa tutlaa \'alayhi Aayaatunaa wallaa mustakbiran ka-al lam yasma\'haa ka-anna feee uzunaihi waqran fabash-shiru bi\'azaabin aleem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>8,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتُ ٱلنَّعِيمِ','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati lahum Janaatun Na\'eem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>9,'arabic_text'=>'خَٰلِدِينَ فِيهَاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Khaalideena feeha wa\'dal laahi haqqaa; Wa-Huwal \'Azeezul Hakeem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>10,'arabic_text'=>'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ','transliteration'=>'Khalaqas samaawaati bi-ghairi \'amadin tarawnahaa Wa-alqaa fil ardi rawaasiya an tameeda bikum Wa-bassa feehaa min kulli daaabbah; Wa-anzalnaa minas samaaa\'i maaa\'an fa-ambatnaa feeha min kulli zawjin kareem','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>11,'arabic_text'=>'هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّٰلِمُونَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Haazaa khalqul laahi fa-aroonee maazaa khalaqal lazeena min doonih; baliz zaalimoona fee dalalim Mubeen','page_number'=>411,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>12,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ','transliteration'=>'Wa-laqad aatainaa Luqmaanal hikmata anish kur lillaah; Wa-maien yashkur fa-innamaa yashkuru linafsihee Wa-man kafara fa-innal laaha Ghaniyyun Hameed','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>13,'arabic_text'=>'وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ','transliteration'=>'Wa-iz qaala luqmaanu libnihee Wa-huwa ya\'izuhoo ya-bunaiya laa tushrik billaah; innash shirka lazulmun \'azeem','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>14,'arabic_text'=>'وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ','transliteration'=>'Wa-wassainal insaana bi-waalidaihi hamalat hu ummuhoo wahnan \'alaa wahninw Wa-fisaaluhoo fee \'aamaini anishkur lee Wa-liwaalidaika ilaiyal maseer','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>15,'arabic_text'=>'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-in jaahadaaka \'alaaa an tushrika bee maa laisa laka bihee \'ilmun falaa tuti\'humaa Wa-saahib-humaa fid dunyaa ma\'roofanw wattabi\' sabeela man anaaba ilayy; summa ilaiyya marji\'ukum fa-unabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>16,'arabic_text'=>'يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٖ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ','transliteration'=>'Ya-bunaiya innahaaa in taku misqaala habbatim min khardalin fatakun fee sakhratin aw fis samaawaati aw fil ardi yaati bihal laa; innal laaha lateefun Khabeer','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>17,'arabic_text'=>'يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ','transliteration'=>'Yaa bunaiya aqimis-Salaata waamur bilma\'roofi wanha \'anil munkari wasbir \'alaa maaa asaabaka inna zaalika min \'azmil umoor','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>18,'arabic_text'=>'وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ','transliteration'=>'Wa-laa tusa\'-ir khaddaka linnaasi Wa-laa tamshi fil ardi maarahan innal laaha laa yuhibbu kulla mukhtaalin fakhoor','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>19,'arabic_text'=>'وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ','transliteration'=>'Waqsid fee mashyika waghdud min sawtik; inna ankaral aswaati lasawtul hameer','page_number'=>412,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>20,'arabic_text'=>'أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ','transliteration'=>'Alam taraw annal laaha sakhkhara lakum maa fis sa-maawaati Wa-maa fil ardi Wa-asbaha \'alaikum ni\'amahoo zaahiratanw Wa-baatinah; Wa-minan naasi many yujaadilu fil laahi bighayri \'ilminw Wa-laa hudanw Wa-laa Kitaabim muneer','page_number'=>413,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>21,'arabic_text'=>'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ','transliteration'=>'Wa-izaa qeela lahumut tabi\'oo maaa anzalal laahu qaaloo bal nattabi\'u maa wajadnaa \'alaihi aabaaa\'anaa; awalaw kaanash Shaitaanu yad\'oohum ilaa \'azaabis sa\'eer','page_number'=>413,'juz_number'=>21,'hizb_number'=>41,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>22,'arabic_text'=>'۞ وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ','transliteration'=>'Wa-maien yuslim wajha-hooo ilal laahi Wa-huwa muhsinun faqadistamsaka bil\'ur watil wusqaa; Wa-ilal laahi \'aaqibatul umoor','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>23,'arabic_text'=>'وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Wa-man kafara falaa yahzunka kufruh; ilainaa marji\'uhum fanunabbi\'uhum bimaa \'amiloo; innal laaha \'aleemum bizaatis sudoor','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>24,'arabic_text'=>'نُمَتِّعُهُمۡ قَلِيلٗا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظٖ','transliteration'=>'Numatti\'uhum qaleelan summa nadtarruhum ilaa \'azaabin ghaleez','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>25,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-la\'in sa-altahum man khalaqas samaawaati wal-arda la-yaqoolunnal laah; qulil hamdu lillaah; bal aksaruhum laa ya\'lamoon','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>26,'arabic_text'=>'لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','transliteration'=>'Lilaahi ma fis samaa-waati wal-ard; innal laaha Huwal Ghaniyyul Hameed','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>27,'arabic_text'=>'وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ','transliteration'=>'Wa-law annamaa fil ardi min shajaratin aqlaamunw wal-bahru yamudduhoo mim ba\'dihee sab\'atu abhurim maa nafidat Kalimaatul laah; innal laaha \'azeezun Hakeem','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>28,'arabic_text'=>'مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسٖ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ','transliteration'=>'Maa khalqukum Wa-laa ba\'sukum illaa kanafsinw-waa hidah; innal laaha Samee\'um Baseer','page_number'=>413,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>29,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Alam tara annal laaha yoolijul laila fin nahaari Wa-yoolijun nahaara fil laili Wa-sakhkharash shamsa wal-qamara kulluny yajreee ilaaa ajalim musammanw Wa-annal laaha bimaa ta\'maloona Khabeer','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>30,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ','transliteration'=>'Zaalika bi-annal laaha Huwal Haqqu Wa-anna maa yad\'oona min doonihil baatilu Wa-annal laaha Huwal \'Aliyyul Kabeer','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>31,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ','transliteration'=>'Alam tara annal fulka tajree fil bahri bini\'matil laahi li-yuriyakum min Aayaatih; inna fee zaalika la-Aayaatil likulli sabbaarin shakoor','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>32,'arabic_text'=>'وَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ','transliteration'=>'Wa-izaa ghashiyahum mawjun kazzulali da\'a-wul laaha mukhliseena lahud deena fa-lammaa najjaahum ilal barri faminhum muqtasid; Wa-maa yajhadu bi-Aayaatinaa illaa kullu khattaarin kafoor','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>33,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ','transliteration'=>'Yaaa-ayyuhan naasut taqoo Rabbakum wakhshaw Yawmal laa yajzee waalidun \'anw waladihee Wa-laa mawloodun huwa jaazin \'anw waalidihee shai\'aa; innaa wa\'dal laahi haqqun falaa taghurran-nakumul hayaatud dunyaa Wa-laa yaghur-rannakum billaahil gharoor','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>31,'ayah_number'=>34,'arabic_text'=>'إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ','transliteration'=>'Innal laaha \'indahoo \'ilmus saa\'ati Wa-yunazzilul ghaisa Wa-ya\'lamu maa fil arhaami Wa-maa tadree nafsum maazaa taksibu ghadaa; Wa-maa tadree nafsum bi-ayyi ardin tamoot; innal laaha \'Aleemun Khabeer','page_number'=>414,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            /* Surah 32: The Prostration (As-Sajdah) */
            ['surah_id'=>32,'ayah_number'=>1,'arabic_text'=>'الٓمٓ','transliteration'=>'Alif-Laaam-Meeem','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>2,'arabic_text'=>'تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Tanzeelul Kitaabi laa raiba feehi mir rabbil \'aalameen','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>3,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ','transliteration'=>'Am yaqooloonaf taraahu bal huwal haqqu mir rabbika litunzira qawma maaa ataahum min nazeerim min qablika la\'allahum yahtadoon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>4,'arabic_text'=>'ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ','transliteration'=>'Allaahul lazee khalaqas samaawaati wal-arda Wa-maa bainahumaa fee sittati ayyaamin thummas tawaa \'alal \'arsh; maa lakum min doonihee minw waliyyinw wala shafee\'; afalaa tatazakkaroon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>5,'arabic_text'=>'يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ','transliteration'=>'Yudabbirul amra minas samaaa\'i ilal ardi thumma ya\'ruju ilaihi fee yawmin kaana miqdaaruhooo alfa sanatim mimmaa ta\'uddoon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>6,'arabic_text'=>'ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ','transliteration'=>'Zaalika \'aalimul ghaybi Wa-shahaadatil \'azeezur raheem','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>7,'arabic_text'=>'ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينٖ','transliteration'=>'Allazee ahsana kulla shai-in khalaqa; Wa-bada-a khalqal insaani min teen','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>8,'arabic_text'=>'ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةٖ مِّن مَّآءٖ مَّهِينٖ','transliteration'=>'Thumma ja\'ala naslahoo min sulaalatim mim maaa\'im maheen','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>9,'arabic_text'=>'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ','transliteration'=>'Thumma sawwaahu Wa-nafakha feehi mir roohihih; Wa-ja\'ala lakumus sam\'a wal-absaara wal-af\'idah; qaleelam maa tashkuroon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>10,'arabic_text'=>'وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي خَلۡقٖ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ','transliteration'=>'Wa-qaalooo \'a-izaa dalalnaa fil ardi \'a-innaa lafee khalqin jadeed; bal hum biliqaaa\'i rabbihim kaafiroon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>11,'arabic_text'=>'۞ قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ','transliteration'=>'Qul yatawaffaakum malakul mawtil lazee wukkila bikum Thumma ilaa rabbikum turja\'oon','page_number'=>415,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>12,'arabic_text'=>'وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ','transliteration'=>'Wa-law taraaa izil mujrimoona naakisoo ru\'oosihim \'inda rabbihim rabbanaaa absarnaa Wa-sami\'naa farji\'naa na\'mal saalihan innaa mooqinoon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>13,'arabic_text'=>'وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ','transliteration'=>'Wa-law shi\'naa la-aatainaa kulla nafsin hudaahaa Wa-laakin haqqal qawlu minnee la-amla\'anna jahannama minal jinnati wannaasi ajma\'een','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>14,'arabic_text'=>'فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Fazooqoo bimaa naseetum liqaaa\'a yawminkum haaza innaa naseenaakum Wa-zooqoo \'azaabal khuldi bimaa kuntum ta\'maloon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>15,'arabic_text'=>'إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ','transliteration'=>'Innamaa yu\'minu bi-aayaatinal lazeena izaa zukkiroo bihaa kharroo sujjadanw Wa-sabbahoo bihamdi rabbihim Wa-hum laa yastakbiroon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>true],
            ['surah_id'=>32,'ayah_number'=>16,'arabic_text'=>'تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','transliteration'=>'Tatajaafaa junoobuhum \'anil madaaji\'i yad\'oona rabbahum khawfanw Wa-tama\'anw Wa-mimmaa razaqnaahum yunfiqoon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>17,'arabic_text'=>'فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Falaa ta\'lamu nafsum maaa ukhfiya lahum min qurrati a\'yunin jazaaa\'am bimaa kaanoo ya\'maloon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>18,'arabic_text'=>'أَفَمَن كَانَ مُؤۡمِنٗا كَمَن كَانَ فَاسِقٗاۚ لَّا يَسۡتَوُۥنَ','transliteration'=>'Afaman kaana mu\'minan kaman kaana faasiqaa; laa yasta-woon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>19,'arabic_text'=>'أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ جَنَّٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ammal lazeena aamanoo Wa-\'amilus saalihaati falahum jannaatul ma\'waa nuzulam bimaa kaanoo ya\'maloon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>20,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ','transliteration'=>'Wa-ammal lazeena fasaqoo fama\'waahumun Naaru kullamaaa araadooo any yakhrujoo minhaaa u\'eedoo feehaa Wa-qeela lahum zooqoo \'azaaaban Naaril lazee kuntum bihee tukazziboon','page_number'=>416,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>21,'arabic_text'=>'وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-lanuzeeqan-nahum minal \'azaabil ladnaa doonal \'azaabil akbari la\'allahum yarji\'oon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>22,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ','transliteration'=>'Wa-man azlamu mimman zukkira bi-aayaati rabbihee summa a\'rada \'anhaa; innaa minal mujrimeena muntaqimoon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>23,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةٖ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba falaa takun fee miryatim mil liqaaa\'ihee Wa-ja\'alnaahu hudal li-Baneee Israaa\'eel','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>24,'arabic_text'=>'وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ','transliteration'=>'Wa-ja\'alnaa minhum a\'immataien yahdoona bi-amrinaa lammaa sabaroo Wa-kaanoo bi-aayaatinaa yooqinoon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>25,'arabic_text'=>'إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Inna rabbaka huwa yafsilu bainahum yawmal qiyaamati feemaa kaanoo feehi yakhtalifoon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>26,'arabic_text'=>'أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ','transliteration'=>'Awalam yahdi lahum kam ahlaknaa min qablihim minal qurooni yamshoona fee masaakinihim; inna fee zaalika la-aayaatin afalaa yasma\'oon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>27,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعٗا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ','transliteration'=>'Awalam yaraw annaa nasooqul maaa\'a ilal ardil juruzi fanukhriju bihee zar\'an ta\'kulu minhu an\'aamuhum Wa-anfusuhum afalaa yubsiroon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>28,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal fath-hu in kuntum saadiqeen','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>29,'arabic_text'=>'قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ','transliteration'=>'Qul yawmal fath-hi laa yanfa\'ul lazeena kafarooo eemaanuhum Wa-laa hum yunzaroon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>32,'ayah_number'=>30,'arabic_text'=>'فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ','transliteration'=>'Fa-a\'rid \'anhum wantazir innahum muntaziroon','page_number'=>417,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            /* Surah 33: The Combined Forces (Al-Ahzab) */
            ['surah_id'=>33,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا','transliteration'=>'Yaa-aiyuhan Nabiyyut taqil laaha Wa-laa tuti\'il kaafireena wal-munaafiqeen; innal laaha kaana \'aleeman Hakeemaa','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>2,'arabic_text'=>'وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا','transliteration'=>'Wattabi\' maa yoohaaa ilaika mir Rabbik; innal laaha kaana bimaa ta\'maloona Khabeera','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>3,'arabic_text'=>'وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا','transliteration'=>'Wa-tawakkal \'alal laah; Wa-kafaa billaahi Wakeelaa','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>4,'arabic_text'=>'مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ','transliteration'=>'Maa ja\'alal laahu lirajulim min qalbaini fee jawfih; Wa-maa ja\'ala azwaajakumul laaa\'ee tuzaahiroona minhunna ummahaatikum; Wa-maa ja\'ala ad\'iyaaa\'akum abnaaa\'akum; zaalikum qawlukum bi-afwaa-hikum wallaahu yaqoolul haqqa Wa-Huwa yahdis sabeel','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>5,'arabic_text'=>'ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا','transliteration'=>'Ud\'oohum li-aabaaa\'ihim huwa aqsatu \'indal laah; fa-il lam ta\'lamooo aabaaa\'ahum fa-ikhwaanukum fid deeni Wa-mawaaleekum; Wa-laisa \'alaikum junaahun feemaaa akhtaatum bihee Wa-laakim maa ta\'ammadat quloobukum; Wa-kaanal laahu Ghafoorar Raheemaa','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>6,'arabic_text'=>'ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا','transliteration'=>'An-Nabiyyu awlaa bil-mu\'mineena min anfusihim Wa-azwaajuhoo ummahatuhum Wa-ulul arhaami ba\'duhum awlaa biba\'din fee Kitaabil laahi minal mu\'meneena wal-Muhaajireena illaaa an taf\'alooo ilaaa awliyaaa\'ikum ma\'roofaa; kaana zaalika fil kitaabi mastooraa','page_number'=>418,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>7,'arabic_text'=>'وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا','transliteration'=>'Wa-iz akhaznaa minan Nabiyyeena meesaaqahum Wa-minka Wa-min Noohinw Wa-Ibraaheema Wa-Moosaa Wa-Eesab ni Maryama Wa-akhaznaa minhum meesaaqan ghaleezaa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>8,'arabic_text'=>'لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا','transliteration'=>'Liyas\'alas saadiqeena \'an sidqihim; Wa-a\'adda lilkaa-fireena \'azaaban aleemaa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>9,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanuz kuroo ni\'matal laahi \'alaikum iz jaaa\'atkum junoodun fa-arsalnaa \'alaihim reehanw Wa-junoodal lam tarawhaa; Wa-kaanal laahu bimaa ta\'maloona Baseera','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>10,'arabic_text'=>'إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠','transliteration'=>'Iz jaaa\'ookum min fawqikum Wa-min asfala minkum Wa-iz zaaghatil absaaru Wa-balaghatil quloobul hanaajira Wa-tazunnoona billaahiz zunoonaa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>11,'arabic_text'=>'هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا','transliteration'=>'Hunaalikab tuliyal mu\'minoona Wa-zulziloo zilzaalan shadeedaa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>12,'arabic_text'=>'وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا','transliteration'=>'Wa-iz yaqoolul munaafiqoona wallazeena fee quloobihim maradum maa wa\'adanal laahu Wa-Rasooluhooo illaa ghurooraa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>13,'arabic_text'=>'وَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا','transliteration'=>'Wa-iz qaalat taaa\'ifatum minhum yaaa-ahla Yasriba laa muqaamaa lakum farji\'oo; Wa-yastaazinu fareequm minhumun Nabiyya yaqooloona inna buyootanaa \'awrah; Wa-maa hiya bi\'awratin iny yureedoona illaa firaaraa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>14,'arabic_text'=>'وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرٗا','transliteration'=>'wa-law dukhilat \'alaihim min aqtaarihaa summa su\'ilul fitnata la-aatawhaa Wa-maa talabbasoo bihaaa illaa yaseeraa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>15,'arabic_text'=>'وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولٗا','transliteration'=>'Wa-laqad kaanoo \'aahadul laaha min qablu laa yuwal-loonal adbaar; Wa-kaana \'ahdul laahi mas\'oolaa','page_number'=>419,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>16,'arabic_text'=>'قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا','transliteration'=>'Qul laien yanfa\'akumul firaaru in farartum minal mawti awil qatli Wa-izal laa tumatta\'oona illaa qaleelaa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>17,'arabic_text'=>'قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةٗۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا','transliteration'=>'Qul man zal lazee ya\'simukum minal laahi in araada bikum sooo\'an aw araada bikum rahmah; Wa-laa yajidoona lahum min doonil laahi waliyyanw Wa-laa naseeraa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>18,'arabic_text'=>'۞ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا','transliteration'=>'Qad ya\'lamul laahul mu\'awwiqeena minkum walqaaa\'ileena li-ikhwaanihim halumma ilainaa, Wa-laa yaatoonal baasa illaa qaleelaa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>19,'arabic_text'=>'أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا','transliteration'=>'Ashihhatan \'alaikum faizaa jaaa\'al khawfu ra-aytahum yanzuroona ilaika tadooru a\'yunuhum kallazee yughshaa \'alaihi minal mawti fa-izaa zahabal khawfu salqookum bi-alsinatin hidaadin ashibbatan \'alal khayr; ulaaa\'ika lam yu\'minoo fa-ahbatal laahu a\'maalahum; Wa-kaana zaalika \'alal laahi yaseeraa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>20,'arabic_text'=>'يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلٗا','transliteration'=>'Yahsaboonal Ahzaaba lam yazhaboo Wa-ien yaatil Ahzaabu yawaddoo law annahum baadoona fil A\'raabi yasaloona \'an ambaaa\'ikum Wa-law kaanoo feekum maa qaatalooo illaa qaleela','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>21,'arabic_text'=>'لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا','transliteration'=>'Laqad kaana lakum fee Rasoolil laahi uswatun hasanatul liman kaana yarjul laaha wal-yawmal Aakhira Wa-azkaral laaha kaseeraa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>22,'arabic_text'=>'وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا','transliteration'=>'Wa-lammaa ra al-mu\'minoonal Ahzaaba qaaloo haazaa maa wa\'adanal laahu Wa-Rasooluh; Wa-sadaqal laahu Wa-Rasooluh; Wa-maa zaadahum illaaa eemaananw Wa-tasleemaa','page_number'=>420,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>23,'arabic_text'=>'مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا','transliteration'=>'Minal mu\'mineena rijaalun sadaqoo maa \'aahadul laaha \'alaihi faminhum man qadaa nahbahoo Wa-minhum mai yantaziru Wa-maa baddaloo tabdeelaa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>24,'arabic_text'=>'لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا','transliteration'=>'Li-yajziyal aahus saadiqeena bisidqihim Wa-yu\'azzibal munaafiqeena in shaaa\'a aw yatooba \'alaihim; innal laaha kaana Ghafoorar Raheemaa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>25,'arabic_text'=>'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرٗاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا','transliteration'=>'Wa-raddal laahul lazeena kafaroo bighaizihim lam yanaaloo khairaa; Wa-kafal laahul mu\'mineenal qitaal; Wa-kaanal laahu Qawiyyan \'Azeezaa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>26,'arabic_text'=>'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا','transliteration'=>'Wa-anzalal lazeena zaaha-roohum min Ahlil Kitaabi min sa-yaaseehim Wa-qazafa fee quloobihimm mur-ru\'ba fareeqan taqtuloona Wa-taasiroona fareeqaaa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>27,'arabic_text'=>'وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا','transliteration'=>'Wa-awrasakum ardahum Wa-diyaarahum Wa-amwaalahum Wa-ardal lam tata\'oohaa; Wa-kaanal laahu \'alaa kulli shai\'in Qadeeraa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>28,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا','transliteration'=>'Yaaa-aiyyuhan Nabiyyu qul li-azwaajika in kuntunna turidnal hayaatad dunyaa Wa-zeenatahaa fata\'aalaina umatti\'kunna Wa-usarrihkunna saraahan jameela','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>29,'arabic_text'=>'وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا','transliteration'=>'Wa-in kuntunna turidnal laaha Wa-Rasoolahoo wad-Daaral Aakhirata fa-innal laaha a\'adda lil-muhsinaati min-kunna ajjran \'azeemaa','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>30,'arabic_text'=>'يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا','transliteration'=>'Yaa-nisaaa\'an Nabiyyi maien yaati minkunna bifaa-hishatim mubaiyyinatien yudaa\'af lahal \'azaabu di\'faini Wa-kaana zaalika \'alal laahi yaseera','page_number'=>421,'juz_number'=>21,'hizb_number'=>42,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>31,'arabic_text'=>'۞ وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا','transliteration'=>'Wa-maien yaqnut minkunna lillaahi Wa-Rasoolihee Wa-ta\'mal saalihan nu\'tihaaa ajrahaa marratayni Wa-a\'tadnaa lahaa rizqan kareema','page_number'=>422,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>32,'arabic_text'=>'يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا','transliteration'=>'Yaa-nisaaa\'an Nabiyyi lastunna ka-ahadim minan nisaaa\'i init taqaitunna falaa takhda\'na bilqawli fa-yatma\'al lazee fee qalbihee maradunw Wa-qulna qawlam ma\'roofaa','page_number'=>422,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>33,'arabic_text'=>'وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا','transliteration'=>'Wa-qarna fee bu-yoo-tikunna Wa-laa tabarrajna tabarrujal Jaahiliyyatil oolaa Wa-aqimnas Salaata Wa-aaateenaz Zakaata Wa-ati\'nal laaha Wa-Rasoolah; innamaa yureedul laahu liyuzhiba \'ankumur rijsa Ahlal Bayti Wa-yutahhirakum tatheeraa','page_number'=>422,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>34,'arabic_text'=>'وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا','transliteration'=>'Wazkurna maa yutlaa fee bu-yootikunna min aayaatil laahi wal-Hikmah; innal laaha kaana lateefan Khabeera','page_number'=>422,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>35,'arabic_text'=>'إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا','transliteration'=>'Innal muslimeena wal-muslimaati wal-mu\'mineena wal-mu\'minaati walqaaniteena walqaanitaati wassaadiqeena wassaadiqaati wassaabireena wassaabiraati walkhaashi\'eena walkhaashi\'aati walmutasaddiqeena walmutasaddiqaati wassaaa\'imeena wassaaa\'imaati walhaafizeena furoojahum walhaafizaati waz-zaakireenal laaha kaseeranw waz-zaakiraati a\'addal laahu lahum maghfiratanw Wa-ajran \'azeemaa','page_number'=>422,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>36,'arabic_text'=>'وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا','transliteration'=>'Wa-maa kaana limu\'mininw Wa-laa mu\'minatin izaa qadal laahu Wa-Rasooluhooo amran aien yakoona lahumul khiyaratu min amrihim; Wa-maien ya\'sil laaha Wa-Rasoolahoo faqad dalla dalaalam mubeenaa','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>37,'arabic_text'=>'وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولٗا','transliteration'=>'Wa-iz taqoolu lillazeee an\'amal laahu \'alaihi Wa-an\'amta \'alaihi amsik \'alaika zawjaka wattaqil laaha Wa-tukhfee fee nafsika mal laahu mubdeehi Wa-takhshan naasa wallaahu ahaqqu an takhshaah; falammaa qadaa Zaidum minhaa wataran zawwajnaa-kahaa likay laa yakoona \'alal mu\'mineena harajun feee azwaaji ad\'iyaaa\'ihim izaa qadaw minhunna wataraa; Wa-kaana amrul laahi maf\'oolaa','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>38,'arabic_text'=>'مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجٖ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرٗا مَّقۡدُورًا','transliteration'=>'Maa kaana \'alan nabiyyyi min harajin feemaa faradal laahu lahoo sunnatal laahi fil lazeena khalaw min qabl; Wa-kaana amrul laahi qadaram maqdooraa','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>39,'arabic_text'=>'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا','transliteration'=>'Allazeena yuballighoona Risaalaatil laahi Wa-yakhshaw-nahoo Wa-laa yakkhshawna ahadan illal laah; Wa-kafaa billaahi Haseebaa','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>40,'arabic_text'=>'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا','transliteration'=>'Maa kaana Muhammmadun abaaa ahadim mir rijaalikum Wa-laakir Rasoolal laahi Wa-Khaataman Nabiyyeen; Wa-kaanal laahu bikulli shai\'in \'Aleema','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>41,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanuz kurul laaha zikran kaseera','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>42,'arabic_text'=>'وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا','transliteration'=>'Wa-sabbihoohu bukratanw Wa-aseela','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>43,'arabic_text'=>'هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا','transliteration'=>'Huwal lazee yusallee \'alaikum Wa-malaaa\'ikatuhoo liyukhrijakum minaz zulumaati ilan noor Wa-kaana bilmu\'mineena Raheemaa','page_number'=>423,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>44,'arabic_text'=>'تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمٞۚ وَأَعَدَّ لَهُمۡ أَجۡرٗا كَرِيمٗا','transliteration'=>'Tahiyyatuhum Yawma yalqawnahoo salaamunw Wa-a\'adda lahum ajran kareemaa','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>45,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا','transliteration'=>'Yaaa-aiyyuhan Nabiyyu innaaa arsalnaaka shaahidanw Wa-mubashshiranw Wa-nazeeraa','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>46,'arabic_text'=>'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا','transliteration'=>'Wa-daa\'iyan ilal laahi bi-iznihee Wa-siraajam muneeraa','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>47,'arabic_text'=>'وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا','transliteration'=>'Wa-bashshiril mu\'mineena bi-annna lahum minal laahi fadlan kabeera','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>48,'arabic_text'=>'وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا','transliteration'=>'Wa-laa tuti\'il kaafireena walmunaafiqeena Wa-da \'azaahum Wa-tawakkal \'alal laah; Wa-kafaa billaahi Wakeelaa','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>49,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanooo izaa nakahtumul mu\'minaati summa tallaqtu-moohunna min qabli an tamas-soohunna famaa lakum \'alaihinna min \'iddatin ta\'taddoonahaa famatti\'oohunna Wa-sarri-hoohunna saraahan jameelaa','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>50,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةٗ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا خَالِصَةٗ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا يَكُونَ عَلَيۡكَ حَرَجٞۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Yaaa-aiyyuhan Nabiyyu innaaa ahlalnaa laka azwaa-jakal laatee aataiyta ujoora-hunna Wa-maa malakat yameenuka mimmaaa afaaa\'al laahu \'alaika Wa-banaati \'ammika Wa-banaati \'ammaatika Wa-banaati khaalika Wa-banaati khaalaa-tikal laatee haajarna ma\'aka wamra\'-atan mu\'minatan inw wahabat nafsahaa lin-Nabiyyi in araadan Nabiyyu aien yastan-kihahaa khaalisatan laka min doonil mu\'mineen; qad \'alimnaa maa faradnaa \'alaihim feee azwaajihim Wa-maa malakat aimaanuhum li-kailaa yakoona \'alaika haraj; Wa-kaanal laahu Ghafoorar Raheema','page_number'=>424,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>51,'arabic_text'=>'۞ تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ وَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ مَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا','transliteration'=>'Turjee man tashaaa\'u minhunna Wa-tu\'weee ilaika man tashaaa\'u Wa-manib ta-ghaita mimman \'azalta falaa junaaha \'alaik; zaalika adnaaa an taqarra a\'yunuhunna Wa-laa yahzanna Wa-yardaina bimaa aataitahunna kulluhunn; wal-laahu ya\'lamu maa fee quloo-bikum; Wa-kaanal laahu \'Aleeman haleemaa','page_number'=>425,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>52,'arabic_text'=>'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ رَّقِيبٗا','transliteration'=>'Laa yahillu lakan nisaaa\'u mim ba\'du Wa-laaa an tabaddala bihinna min azwaajinw Wa-law ajabaka husnuhunna illaa maa malakat yameenukk; Wa-kaanal laahu \'alaa kulli shai\'ir Raqeeba','page_number'=>425,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>53,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanoo laa tadkhuloo bu-yootan Nabiyyi ilaaa aien yu\'zana lakum ilaa ta\'aamin ghaira naazireena inaahu Wa-laakin izaa du\'eetum fadkhuloo fa-izaa ta\'imtum fantashiroo Wa-laa mustaaniseena lihadees; inna zaalikum kaana yu\'zin Nabiyya fa-yastahyee minkum wallaahu laa yastahyee minal haqq; Wa-izaa sa-altumoohunna mataa\'an fas\'aloohunna minw waraaa\'i hijaab; zaalikum atharu liquloobikum Wa-quloobihinn; Wa-maa kaana lakum an tu\'zoo Rasoolal laahi Wa-laaa an tankihooo azwaajahoo mim ba\'diheee abadaa; inna zaalikum kaana \'indal laahi \'azeema','page_number'=>425,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>54,'arabic_text'=>'إِن تُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا','transliteration'=>'In tubdoo shai\'an aw tukhfoohu fa-innal laaha kaana bikulli shai\'in \'Aleemaa','page_number'=>425,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>55,'arabic_text'=>'لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا','transliteration'=>'Laa junaaha \'alaihinna feee aabaaa\'ihinna Wa-laaa abnaaa\'ihinna Wa-laaa ikhwaanihinnna Wa-laaa abnaaa\'i ikhwaanihinna Wa-laaa abnaaa\'i akhawaatihinna Wa-laa nisaaa\'i-hinna Wa-laa Maa malakat aimaanuhunn; wattaqeenal laah; innal laaha kaana \'alaa kulli shai\'in Shaheedaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>56,'arabic_text'=>'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا','transliteration'=>'Innal laaha Wa-malaaa\'i-katahoo yusalloona \'alan Nabiyy; yaaa-aiyyuhal lazeena aamanoo salloo \'alaihi Wa-sallimoo tasleemaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>57,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا','transliteration'=>'Innal lazeena yu\'zoonal laaha Wa-Rasoolahoo la\'anahumul laahu fid dunyaa wal-Aakhirati Wa-a\'adda lahum \'azaabam muheenaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>58,'arabic_text'=>'وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا','transliteration'=>'Wallazeena yu\'zoonal mu\'mineena almu\'manaati bighairi mak tasaboo faqadih tamaloo buhtaananw Wa-ismam mubeenaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>59,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Yaaa-aiyyuhan Nabiyyu qul li-azwaajika Wa-banaatika Wa-nisaaa\'il mu\'mineena yudneena \'alaihinna min jalaabee-bihinn; zaalika adnaaa aien yu\'rafna falaa yu\'zain; Wa-kaanal laahu Ghafoorar Raheemaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>60,'arabic_text'=>'۞ لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا','transliteration'=>'La\'il lam yantahil munaafiqoona wallazeena fee quloobihim maradunw walmur-jifoona fil madeenati lanughri-yannaka bihim summa laa yujaawiroonaka feehaaa illaa qaleela','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>61,'arabic_text'=>'مَّلۡعُونِينَۖ أَيۡنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقۡتِيلٗا','transliteration'=>'Mal\'ooneena ainamaa suqifoo ukhizoo Wa-quttiloo taqteelaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>62,'arabic_text'=>'سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا','transliteration'=>'Sunnatal laahi fil lazeena khalaw min qablu Wa-lan tajida lisunnatil laahi tabdeelaa','page_number'=>426,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>63,'arabic_text'=>'يَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا','transliteration'=>'Yas\'alukan naasu \'anis Saa\'ati qul innamaa \'ilmuhaa \'indal laah; Wa-maa yudreeka la\'allas Saa\'ata takoonu qareebaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>64,'arabic_text'=>'إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا','transliteration'=>'Innal laaha la\'anal kaafireena Wa-a\'adda lahum sa\'eeraa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>65,'arabic_text'=>'خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا','transliteration'=>'Khaalideena feehaaa abadaa, laa yajidoona waliyyanw Wa-laa naseeraa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>66,'arabic_text'=>'يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠','transliteration'=>'Yawma tuqallabu wujoohuhum fin Naari yaqooloona yaa-laitanaaa ata\'nal laaha Wa-ata\'nar Rasoolaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>67,'arabic_text'=>'وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعۡنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠','transliteration'=>'Wa-qaaloo Rabbanaaa innaaa ata\'naa saadatanaa Wa-kubaraaa\'anaa fa-adalloonas sabeelaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>68,'arabic_text'=>'رَبَّنَآ ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنٗا كَبِيرٗا','transliteration'=>'Rabbanaaa aatihim di\'fai-ni minal \'azaabi wal\'anhum la-nan kabeera','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>69,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ ءَاذَوۡاْ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا','transliteration'=>'yaa-aiyyuhal lazeena aamanoo las takoonoo kalla-zeena aazaw Moosaa fa-barra-ahul laahu mimmmaa qaaloo; Wa-kaana \'indal laahi wajeehaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>70,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا','transliteration'=>'Yaaa-aiyyuhal lazeena aamanut taqul laaha Wa-qooloo qawlan sadeedaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>71,'arabic_text'=>'يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا','transliteration'=>'Yuslih lakum a\'maalakum Wa-yaghfir lakum zunoobakum; Wa-mai yuti\'il laaha Wa-Rasoolahoo faqad faaza fawzan \'azeemaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>72,'arabic_text'=>'إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا','transliteration'=>'Innaa \'aradnal amaanata \'alas samaawaati walardi wal-jibaali fa-abaina aien yahmil-nahaa Wa-ashfaqna minhaa Wa-hamalahal insaanu innahoo kaana zalooman jahoolaa','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>33,'ayah_number'=>73,'arabic_text'=>'لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا','transliteration'=>'Liyu-\'azzibal laahul munaafiqeena wal-munaafiqaati walmushrikeena wal-mushrikaati Wa-yatoobal laahu \'alal mu\'mineena walmu\'minaat; Wa-kaanal laahu Ghafoorar Raheema','page_number'=>427,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            /* Surah 34: Sheba (Saba) */
            ['surah_id'=>34,'ayah_number'=>1,'arabic_text'=>'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِي ٱلۡأٓخِرَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ','transliteration'=>'Alhamdu lillaahil lazee lahoo maa fis samaawaati Wa-maa fil ardi Wa-lahul hamdu fil aakhirah; Wa-Huwal Hakeemul Khabeer','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>2,'arabic_text'=>'يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ ٱلرَّحِيمُ ٱلۡغَفُورُ','transliteration'=>'Ya\'lamu maa yaliju fil ardi Wa-maa yakhruju minhaa Wa-maa yanzilu minas samaaa\'i Wa-maa ya\'ruju feehaa; Wa-Huwar Raheemul Ghafoor','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>3,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَأۡتِينَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّي لَتَأۡتِيَنَّكُمۡ عَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبٖ مُّبِينٖ','transliteration'=>'Wa-qaalal lazeena kafaroo laa taateenas Saa\'ah; qul balaa Wa-Rabbee lataatiyannakum \'Aalimul Ghaib; laa ya\'zubu \'anhu misqaalu zarratin fis samaawaati Wa-laa fil ardi Wa-laaa asgharu min zaalika Wa-laaa akbaru illaa fee kitaabim mubeen','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>4,'arabic_text'=>'لِّيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۚ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ','transliteration'=>'Liyajziyal lazeena aamanoo Wa-\'amilus saalihaat; ulaaa\'ika lahum maghfiratunw Wa-rizqun kareem','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>5,'arabic_text'=>'وَٱلَّذِينَ سَعَوۡ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٞ','transliteration'=>'Wallazeena sa\'aw feee aayaatinaa mu\'aajizeena ulaaa-\'ika lahum \'azaabum mir rijzin aleem','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>6,'arabic_text'=>'وَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ','transliteration'=>'Wa-yaral lazeena ootul \'ilmal lazeee unzila ilaika mir Rabbika huwal haqqa Wa-yahdeee ilaaa siraatil \'Azeezil Hameed','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>7,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلٖ يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقٖ جَدِيدٍ','transliteration'=>'Wa-qaalal lazeena kafaroo hal nadullukum \'alaa rajuliny yanabbi-\'ukum izaa muzziqtum kulla mumazzaqin innakum lafee khalqin jadeed','page_number'=>428,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>8,'arabic_text'=>'أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ فِي ٱلۡعَذَابِ وَٱلضَّلَٰلِ ٱلۡبَعِيدِ','transliteration'=>'Aftaraa \'alal laahi kaziban am bihee jinnah; balil lazeena laa yu\'minoona bil-Aakhirati fil\'azaabi wad dalaalil ba\'eed','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>9,'arabic_text'=>'أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفٗا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّكُلِّ عَبۡدٖ مُّنِيبٖ','transliteration'=>'Afalam yaraw ilaa maa baina aydeehim Wa-maa khalfahum minas samaaa\'i wal-ard; in nashad nakhsif bihimul arda aw nusqit \'alaihim kisafam minas samaaa\'; inna fee zaalika la-Aayatal likulli \'abdim muneeb','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>10,'arabic_text'=>'۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ','transliteration'=>'Wa-laqad aatainaa Daawooda minnaa fadlaien yaa-jibaalu awwibee ma\'ahoo wattaira Wa-alannaa lahul hadeed','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>11,'arabic_text'=>'أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Ani \'mal saabighaatinw Wa-qaddir fis sardi wa\'maloo saalihan innee bimaa ta\'maloona Baseer','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>12,'arabic_text'=>'وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ','transliteration'=>'Wa-li-Sulaimaanar reeha ghuduwwuhaa shahrunw Wa-ra-waahuhaa shahrunw Wa-asalnaa lahoo \'ainal qitr; Wa-minal jinni maien ya\'malu baina yadaihi bi-izni Rabbih; Wa-maien yazigh minhum \'an amrinaa nuziqhu min \'azaabis sa\'eer','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>13,'arabic_text'=>'يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٖ كَٱلۡجَوَابِ وَقُدُورٖ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ','transliteration'=>'Ya\'maloona lahoo ma yashaaa\'u mim mahaareeba Wa-tamaaseela Wa-jifaanin kaljawaabi Wa-qudoorir raasiyaat; i\'maloo aala Daawooda shukraa; Wa-qaleelum min \'ibaadiyash shakoor','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>14,'arabic_text'=>'فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ','transliteration'=>'Falammaa qadainaa \'alaihil mawta ma dallahum \'alaa mawtiheee illaa daaabbatul ardi taakulu minsa-atahoo falammaa kharra tabaiyyanatil jinnu al law kaanoo ya\'lamoonal ghaiba maa labisoo fil \'azaabil muheen','page_number'=>429,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>15,'arabic_text'=>'لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ','transliteration'=>'Laqad kaana li-Saba-in fee maskanihim Aayatun jannataani \'aien yameeninw Wa-shimaalin kuloo mir rizq Rabbikum washkuroo lah; baldatun taiyyibatunw Wa-Rabbun Ghafoor','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>16,'arabic_text'=>'فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ','transliteration'=>'Fa-a\'radoo fa-arsalnaa \'alaihim Sailal \'Arimi Wa-baddalnaahum bijannataihim jannataini zawaatai ukulin khamtinw Wa-aslinw Wa-shai\'im min sidrin qaleel','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>17,'arabic_text'=>'ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ','transliteration'=>'Zaalika jazainaahum bimaa kafaroo Wa-hal nujaazeee illal kafoor','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>18,'arabic_text'=>'وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ','transliteration'=>'Wa-ja\'alnaa bainahum Wa-bainal qural latee baaraknaa feehaa quran zaahiratanw Wa-qaddamaa feehas sayr; seeroo feehaa la-yaalirya Wa-aiyaaman aamineen','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>19,'arabic_text'=>'فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ','transliteration'=>'Faqaaloo Rabbanaa baa\'id baina asfaarinaa Wa-zalamooo anfusahum faja\'alnaahum ahaadeesa Wa-mazzaq-naahum kulla mumazzaq; inna fee zaalika la-Aayaatil likulli sabbaarin shakoor','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>20,'arabic_text'=>'وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-laqad saddaq \'alaihim Ibleesu zannnabhoo fattaba\'oohu illaa fareeqam minal mu\'mineen','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>21,'arabic_text'=>'وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ','transliteration'=>'Wa-maa kaana lahoo \'alaihim min sultaanin illaa lina\'lama maien yu-minu bil-Aakhirati mimman huwa minhaa fee shakk; Wa-Rabbuka \'alaa kulli shai\'in Hafeez','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>22,'arabic_text'=>'قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّةٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِن شِرۡكٖ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِيرٖ','transliteration'=>'Qulid \'ul lazeena za\'amtum min doonil laahi laa yamlikoona misqaala zarratin fis samaawaati Wa-laa fil ardi Wa-maa lahum feehimaa min shirkinw Wa-maa lahoo minhum min zaheer','page_number'=>430,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>23,'arabic_text'=>'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ','transliteration'=>'Wa-laa tanfa\'ush shafaa\'atu \'indahooo illaa liman azina lah; hattaaa izaa fuzzi\'a \'an quloobihim qaaloo maazaa qaala Rabbukum; qaalul haqq, Wa-Huwal \'Aliyul Kabeer','page_number'=>431,'juz_number'=>22,'hizb_number'=>43,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>24,'arabic_text'=>'۞ قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Qul maien yarzuqukum minas samaawaati wal-ardi qulil laahu Wa-innaaa aw iyyaakum la\'alaa hudan aw fee dalaalim mubeen','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>25,'arabic_text'=>'قُل لَّا تُسۡـَٔلُونَ عَمَّآ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ','transliteration'=>'Qul laa tus\'aloona \'ammaaa ajramnaa Wa-laa nus\'alu \'ammaa ta\'maloon','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>26,'arabic_text'=>'قُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ','transliteration'=>'Qul yajma\'u bainanaa Rabbunaa summa yaftahu bainanaa bilhaqq; Wa-Huwal Fattaahul \'Aleem','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>27,'arabic_text'=>'قُلۡ أَرُونِيَ ٱلَّذِينَ أَلۡحَقۡتُم بِهِۦ شُرَكَآءَۖ كـَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Qul arooniyal lazeena alhaqtum bihee shurakaaa\'a kallaa; bal Huwal Laahul \'Azeezul Hakeem','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>28,'arabic_text'=>'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Wa-maaa arsalnaaka illaa kaaffatal linnaasi basheeranw Wa-nazeeranw Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>29,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>30,'arabic_text'=>'قُل لَّكُم مِّيعَادُ يَوۡمٖ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةٗ وَلَا تَسۡتَقۡدِمُونَ','transliteration'=>'Qul lakum mee\'aadu Yawmil laa tasta\'khiroona \'anhu saa\'atanw Wa-laa tastaqdimoon','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>31,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لَن نُّؤۡمِنَ بِهَٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِي بَيۡنَ يَدَيۡهِۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ','transliteration'=>'Wa-qaalal lazeena kafaroo lan nu\'mina bihaazal Quraani Wa-laa billazee baina yadayh; Wa-law taraaa iziz zaalimoona mawqoofoona \'inda Rabbihim yarji\'u ba\'duhum ilaa ba\'dinil qawla yaqoolul lazeenas tud\'ifoo lillazeenas takbaroo law-laaa antum lakunnaa mu\'mineen','page_number'=>431,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>32,'arabic_text'=>'قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ','transliteration'=>'Qaalal lazeenas takbaroo lillazeenas tud\'ifooo anahnu sadadnaakum \'anil hudaa ba\'da iz jaaa\'akum bal kuntum mujrimeen','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>33,'arabic_text'=>'وَقَالَ ٱلَّذِينَ ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادٗاۚ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَٰلَ فِيٓ أَعۡنَاقِ ٱلَّذِينَ كَفَرُواْۖ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Wa-qaalal lazeenastud\'ifoo lillazeenas takbaroo bal makrul laili wannahaari iz ta\'muroonanaaaa an nakfura billaahi Wa-naj\'ala lahooo andaadaa; Wa-asarrun nadaamata lammaa ra awul \'azaab; Wa-ja\'alnal aghlaala feee a\'naaqil lazeena kafaroo; hal yujzawna illaa maa kaanoo ya\'maloon','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>34,'arabic_text'=>'وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ','transliteration'=>'Wa-maaa arsalnaa\' fee qaryatim min nazeerin illaa qaala mutrafooaa innaa bimaaa ursiltum bihee kaafiroon','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>35,'arabic_text'=>'وَقَالُواْ نَحۡنُ أَكۡثَرُ أَمۡوَٰلٗا وَأَوۡلَٰدٗا وَمَا نَحۡنُ بِمُعَذَّبِينَ','transliteration'=>'Wa-qaaloo nahnu aksaru amwaalanw Wa-awlaadanw Wa-maa nahnu bimu-\'azzabeen','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>36,'arabic_text'=>'قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Qul inna Rabbee yabsutur rizqa limaien yashaaa\'u Wa-yaqdiru Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>37,'arabic_text'=>'وَمَآ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُم بِٱلَّتِي تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰٓ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَٰٓئِكَ لَهُمۡ جَزَآءُ ٱلضِّعۡفِ بِمَا عَمِلُواْ وَهُمۡ فِي ٱلۡغُرُفَٰتِ ءَامِنُونَ','transliteration'=>'Wa-maaa amwaalukum Wa-laaa awlaadukum billatee tuqarribukum \'indanaa zulfaaa illaa man aamana Wa-\'amila saalihan fa-ulaaa\'ika lahum jazaaa\'ud di\'fi bimaa \'amiloo Wa-hum fil ghurufaati aaminoon','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>38,'arabic_text'=>'وَٱلَّذِينَ يَسۡعَوۡنَ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ','transliteration'=>'Wallazeena yas\'awna feee Aayaatinaa mu\'aajizeena ulaaa\'ika fil \'azaabi muhdaroon','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>39,'arabic_text'=>'قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥۚ وَمَآ أَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ','transliteration'=>'Qul inna Rabbee yabsutur rizqa limai yashaaa\'u min \'ibaadihee Wa-yaqdiru lah; Wa-maaa anfaqtum min shai\'in fahuwa yukhlifuhoo Wa-Huwa khairur raaziqeen','page_number'=>432,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>40,'arabic_text'=>'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ','transliteration'=>'Wa-yawma yahshuruhum jamee\'an summa yaqoolu lilmalaaa\'ikati a-haaa\'ulaaa\'i iyyaakum kaanoo ya\'budoon','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>41,'arabic_text'=>'قَالُواْ سُبۡحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِمۖ بَلۡ كَانُواْ يَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ','transliteration'=>'Qaaloo Subhaanaka Anta waliyyunaa min doonihim bal kaanoo ya\'budoonal jinna aksaruhum bihim mu\'minoon','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>42,'arabic_text'=>'فَٱلۡيَوۡمَ لَا يَمۡلِكُ بَعۡضُكُمۡ لِبَعۡضٖ نَّفۡعٗا وَلَا ضَرّٗا وَنَقُولُ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ','transliteration'=>'Fal-Yawma laa yamliku ba\'dukum liba\'din naf\'anw Wa-laa darraa; Wa-naqoolu lil-lazeena zalamoo zooqoo \'azaaban Naaril latee kuntum bihaa tukazziboon','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>43,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا رَجُلٞ يُرِيدُ أَن يَصُدَّكُمۡ عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُكُمۡ وَقَالُواْ مَا هَٰذَآ إِلَّآ إِفۡكٞ مُّفۡتَرٗىۚ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ','transliteration'=>'Wa-izaa tutlaa \'alaihim Aayaatunaa baiyinaatin qaaloo maa haazaa illaa rajuluien yureedu aien yasuddakum \'ammaa kaana ya\'budu aabaaa\'ukum Wa-qaaloo maa haazaaa illaaa ifkum muftaraa; Wa-qaalal lazeena kafaroo lilhaqqi lammaa jaaa\'ahum in haazaaa illaa sihrum mubeen','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>44,'arabic_text'=>'وَمَآ ءَاتَيۡنَٰهُم مِّن كُتُبٖ يَدۡرُسُونَهَاۖ وَمَآ أَرۡسَلۡنَآ إِلَيۡهِمۡ قَبۡلَكَ مِن نَّذِيرٖ','transliteration'=>'Wa-maaa aatainaahum min Kutubiny yadrusoonahaa Wa-maaa arsalnaaa ilaihim qablaka min nazeer','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>45,'arabic_text'=>'وَكَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ','transliteration'=>'Wa-kazzabal lazeena min qablihim Wa-maa balaghoo mi\'shaara maaa aatainaahum fakazzaboo Rusulee; fakaifa kaana nakeer','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>46,'arabic_text'=>'۞ قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ لَّكُم بَيۡنَ يَدَيۡ عَذَابٖ شَدِيدٖ','transliteration'=>'Qul innamaaa a\'izukum biwaahidatin an taqoomoo lillaahi masnaa Wa-furaadaa summa tatafakkaroo; maa bisaahibikum min jinnah; in huwa illaa nazeerul lakum baina yadai \'azaabin shadeed','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>47,'arabic_text'=>'قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرٖ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٞ','transliteration'=>'Qul maa sa-altukum min ajrin fahuwa lakum in ajriya illaa \'alal laahi Wa-Huwa \'alaa kullin shai-in Shaheed','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>48,'arabic_text'=>'قُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّٰمُ ٱلۡغُيُوبِ','transliteration'=>'Qul inna Rabbee yaqzifu bilhaqq \'Allaamul Ghuyoob','page_number'=>433,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>49,'arabic_text'=>'قُلۡ جَآءَ ٱلۡحَقُّ وَمَا يُبۡدِئُ ٱلۡبَٰطِلُ وَمَا يُعِيدُ','transliteration'=>'Qul jaaa\'al haqqu Wa-maa yubdi\'ul baatilu Wa-maa yu\'eed','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>50,'arabic_text'=>'قُلۡ إِن ضَلَلۡتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفۡسِيۖ وَإِنِ ٱهۡتَدَيۡتُ فَبِمَا يُوحِيٓ إِلَيَّ رَبِّيٓۚ إِنَّهُۥ سَمِيعٞ قَرِيبٞ','transliteration'=>'Qul in dalaltu fainnamaaa adillu \'alaa nafsee Wa-inih tadaitu fabimaa yoohee ilaiyya Rabbee; innahoo Samee\'un Qareeb','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>51,'arabic_text'=>'وَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن مَّكَانٖ قَرِيبٖ','transliteration'=>'Wa-law taraaa iz fazi\'oo falaa fawta Wa-ukhizoo mim makaanin qareeb','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>52,'arabic_text'=>'وَقَالُوٓاْ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِيدٖ','transliteration'=>'Wa-qaaloo aamannaa bihee Wa-annaa lahumut tanaawushu min makaanin ba\'eed','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>53,'arabic_text'=>'وَقَدۡ كَفَرُواْ بِهِۦ مِن قَبۡلُۖ وَيَقۡذِفُونَ بِٱلۡغَيۡبِ مِن مَّكَانِۭ بَعِيدٖ','transliteration'=>'Wa-qad kafaroo bihee min qablu Wa-yaqzifoona bilghaibi min makaanin ba\'eed','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>34,'ayah_number'=>54,'arabic_text'=>'وَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكّٖ مُّرِيبِۭ','transliteration'=>'Wa-heela bainahum Wa-baina maa yashtahoona kamaa fu\'ila bi-ashyaa\'ihim min qabl; innahum kaanoo fee shakkin mureeb','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            /* Surah 35: Originator (Fatir) */
            ['surah_id'=>35,'ayah_number'=>1,'arabic_text'=>'ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Alhamdu lillaahi faatiris samaawaati wal-ardi jaa\'ilil malaaa\'ikati rusulan uleee ajnihatim masnaa Wa-sulaasa Wa-rubaa\'; yazeedu fil khalqi maa yashaaa\'; innal laaha \'alaa kulli shai\'in Qadeer','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>2,'arabic_text'=>'مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Maa yaftahil laahu linnaaasi mir rahmatin falaa mumsika lahaa Wa-maa yumsik falaa mursila lahoo mim ba\'dihi; Wa-Huwal \'Azeezul Hakeem','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>3,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ','transliteration'=>'Yaaa-ayyuhan naasuzkuroo ni\'matal laahi \'alaikum; hal min khaaliqin ghairul laahi yarzuqukum minas samaaa\'i wal ard; laaa ilaaha illaa Huwa fa-annaa tu\'fakoon','page_number'=>434,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>4,'arabic_text'=>'وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Wa-ien yukazzibooka faqad kuzzibat Rusulum min qablik; Wa-ilal laahi turja\'ul umoor','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>5,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ','transliteration'=>'Yaaa-ayyuhan naasu inna wa\'dal laahi haqqun falaa taghurrannakumul hayaatud dunyaa; Wa-laa yaghurran-nakum billaahil gharoor','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>6,'arabic_text'=>'إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوّٞ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ','transliteration'=>'Innash shaitaana lakum \'aduwwun fattakhizoohu \'aduwwaa; innamaa yad\'oo hizbahoo liyakoonoo min ashaabis sa\'eer','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>7,'arabic_text'=>'ٱلَّذِينَ كَفَرُواْ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٌ','transliteration'=>'Allazeena kafaroo lahum \'azaabun shadeed; wallazeena aamanoo Wa-\'amilus saalihaati lahum maghfiratunw Wa-ajrun kabeer','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>8,'arabic_text'=>'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ','transliteration'=>'Afaman zuyyina lahoo sooo\'u \'amalihee fara-aahu hasanaa; fa-innal laaha yudillu mai yashaaa\'u Wa-yahdee mai yashaaa\'u falaa tazhab nafsuka \'alaihim hasaraat; innal laaha \'aleemun bimaa yasna\'oon','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>9,'arabic_text'=>'وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابٗا فَسُقۡنَٰهُ إِلَىٰ بَلَدٖ مَّيِّتٖ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ','transliteration'=>'Wallaahul lazeee arsalar riyaaha fatuseeru sa-haaban fasuqnaahu ilaa baladim maiyitin fa-ahyaynaa bihil arda ba\'da mawtihaa; kazaalikan nushoor','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>10,'arabic_text'=>'مَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ إِلَيۡهِ يَصۡعَدُ ٱلۡكَلِمُ ٱلطَّيِّبُ وَٱلۡعَمَلُ ٱلصَّٰلِحُ يَرۡفَعُهُۥۚ وَٱلَّذِينَ يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمۡ عَذَابٞ شَدِيدٞۖ وَمَكۡرُ أُوْلَٰٓئِكَ هُوَ يَبُورُ','transliteration'=>'Man kaana yureedul \'izzata falillaahil \'izzatu jamee\'aa; ilaihi yas\'adul kalimut taiyibu wal\'amalus saalihu yarfa\'uh; wallazeena yamkuroonas sayyiaati lahum \'azaabun shadeed; Wa-makru ulaaa\'ika huwa yaboor','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>11,'arabic_text'=>'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجٗاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٖ وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ','transliteration'=>'Wallaahu khalaqakum min turaabin summa min nutfatin summa ja\'alakum azwaajaa; Wa-maa tahmilu min unsaa Wa-laa tada\'u illaa bi\'ilmih; Wa-maa yu\'ammaru mim mu\'ammarinw Wa-laa yunqasu min \'umuriheee illaa fee kitaab; inna zaalika \'alal laahi yaseer','page_number'=>435,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>12,'arabic_text'=>'وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبٞ فُرَاتٞ سَآئِغٞ شَرَابُهُۥ وَهَٰذَا مِلۡحٌ أُجَاجٞۖ وَمِن كُلّٖ تَأۡكُلُونَ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُونَ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Wa-maa yastawil bahraani haaza \'azbun furaatun saaa\'ighun sharaabuhoo Wa-haazaa milhun ujaaj; Wa-min kullin ta\'kuloona lahman tariyyanw Wa-tastakhrijoona hilyatan talbasoonahaa Wa-taral fulka feehi mawaakhira litabtaghoo min fadlihee Wa-la\'allakum tashkuroon','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>13,'arabic_text'=>'يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ','transliteration'=>'Yoolijul laila fin nahaari Wa-yoolijun nahaara fil laili Wa-sakhkharash shamsa wal-qamara kulluien yajree li-ajalim musammaa; zaalikumul laahu Rabbukum lahul mulk; wallazeena tad\'oona min doonihee maa yamlikoona min qitmeer','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>14,'arabic_text'=>'إِن تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرٖ','transliteration'=>'In tad\'oohum laa yasma\'oo du\'aaa\'akum Wa-law sami\'oo mas tajaaboo lakum; Wa-Yawmal Qiyaamati Yakfuroona bishirkikum; Wa-laa yunabbi\'uka mislu khabeer','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>15,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','transliteration'=>'Yaaa-ayyunhan naasu antumul fuqaraaa\'u ilal laahi wallaahu Huwal Ghaniyyul Hameed','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>16,'arabic_text'=>'إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ','transliteration'=>'Ien yasha\' yuzhibkum Wa-ya\'ti bikhalqin jadeed','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>17,'arabic_text'=>'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ','transliteration'=>'Wa-maa zaalika \'alal laahi bi\'azeez','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>18,'arabic_text'=>'وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءٞ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ','transliteration'=>'Wa-laa taziru waaziratun wizra ukhraa; Wa-in tad\'u musqalatun ilaa himlihaa laa yuhmal minhu shai\'unw Wa-law kaana zaa qurbaa; innamaa tunzirul lazeena yakhshawna Rabbahum bilghaibi Wa-aqaamus Salaah; Wa-man tazakkaa fa-innamaa yatazakkaa linafsih; Wa-ilal laahil maseer','page_number'=>436,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>19,'arabic_text'=>'وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ','transliteration'=>'Wa-maa yastawil a\'maa wal-baseer','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>20,'arabic_text'=>'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ','transliteration'=>'Wa-laz zulumaatu Wa-lan noor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>21,'arabic_text'=>'وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ','transliteration'=>'Wa-laz zillu Wa-lal haroor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>22,'arabic_text'=>'وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعٖ مَّن فِي ٱلۡقُبُورِ','transliteration'=>'Wa-maa yastawil ahyaaa\'u Wa-lal amwaat; innal laaha yusmi\'u maien yashaaa\'u Wa-maaa anta bi-musmi\'im man fil quboor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>23,'arabic_text'=>'إِنۡ أَنتَ إِلَّا نَذِيرٌ','transliteration'=>'In anta illaa nazeer','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>24,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ','transliteration'=>'Innaa arsalnaaka bil-haqqi basheeranw Wa-nazeeraa; Wa-im min ummatin illaa khalaa feehaa nazeer','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>25,'arabic_text'=>'وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ ٱلۡمُنِيرِ','transliteration'=>'Wa-ien yukazzibooka faqad kazzabal lazeena min qablihim jaaa\'at-hum Rusuluhum bilbaiyyinaati Wa-biz-Zuburi Wa-bil-Kitaabil Muneer','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>26,'arabic_text'=>'ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ فَكَيۡفَ كَانَ نَكِيرِ','transliteration'=>'Summa akhaztul lazeena kafaroo fakaifa kaana nakeer','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>27,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ','transliteration'=>'Alam tara annal laaha anzala minas samaaa\'i maaa\'an fa-akhrajnaa bihee samaraatim mukhtalifan alwaanuhaa; Wa-minal jibaali judadum beedunw Wa-humrum mukhtalifun alwaanuhaa Wa-gharaabeebu sood','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>28,'arabic_text'=>'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ','transliteration'=>'Wa-minan naasi wadda-waaabbi wal-an\'aami mukhtalifun alwaanuhoo kazalik; innamaa yakhshal laaha min \'ibaadihil \'ulamaaa\'; innal laaha \'Azeezun Ghafoor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>29,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ','transliteration'=>'Innal lazeena yatloona Kitabbal laahi Wa-aqaamus Salaata Wa-anfaqoo mimmaa razaqnaahum sirranw Wa-\'alaa-niyataien yarjoona tijaaratal lan taboor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>30,'arabic_text'=>'لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ','transliteration'=>'Liyuwaffiyahum ujoorahum Wa-yazeedahum min fadlih; innahoo Ghafoorun Shakoor','page_number'=>437,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>31,'arabic_text'=>'وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرٞ','transliteration'=>'Wallazeee awhainaaa ilaika minal Kitaabi huwal haqqu musaddiqal limaa baina yadayh; innal laaha bi\'ibaadihee la-khabeerum Baseer','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>32,'arabic_text'=>'ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ','transliteration'=>'Summa awrasnal Kitaabal lazeenas tafainaa min \'ibaadinaa faminhum zaalimul linafsihee Wa-minhum muqtasidu, Wa-minhum saabiqum bilkhairaati bi-iznil laah; zaalika huwal fadlul kabeer','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>33,'arabic_text'=>'جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ','transliteration'=>'Jannaatu \'adnien yad-khuloonahaa yuhallawna feeha min asaawira min zahabinw Wa-lu\'lu\'anw Wa-libaa-suhum feehaa hareer','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>34,'arabic_text'=>'وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورٞ شَكُورٌ','transliteration'=>'Wa-qaalul hamdu lillaahil lazeee azhaba \'annal hazan; inna Rabbanaa la-Ghafoorun Shakoor','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>35,'arabic_text'=>'ٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٞ وَلَا يَمَسُّنَا فِيهَا لُغُوبٞ','transliteration'=>'Allazeee ahallanaa daaral muqaamati min fadlihee laa yamassunaa feehaa nasabunw Wa-laa yamassunaa feehaa lughoob','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>36,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ لَهُمۡ نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورٖ','transliteration'=>'Wallazeena kafaroo lahum naaru Jahannama laa yuqdaa \'alaihim fa-yamootoo Wa-laa yukhaffafu \'anhum min \'azaabihaa; kazaalika najzee kulla kafoor','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>37,'arabic_text'=>'وَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ فَذُوقُواْ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ','transliteration'=>'Wa-hum yastarikhoona feehaa Rabbanaa akhrijnaa na\'mal saalihan ghairal lazee kunnaa na\'mal; awa-lamnu \'ammirkum maa yatazak-karu feehi man tazakkara Wa-jaaa\'akumun nazeeru fazooqoo famaa lizzaalimeena min naseer','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>38,'arabic_text'=>'إِنَّ ٱللَّهَ عَٰلِمُ غَيۡبِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Innal laaha \'aalimu ghaibis samaawaati wal-ard; innahoo \'aleemum bizaatis sudoor','page_number'=>438,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>39,'arabic_text'=>'هُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتٗاۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ إِلَّا خَسَارٗا','transliteration'=>'Huwal lazee ja\'alakum khalaaa\'ifa fil ard; faman kafara fa\'alaihi kufruhoo; Wa-laa yazeedul kaafireena kufruhum \'inda Rabbihim illaa maqtanw Wa-laa yazeedul kaafireena kufruhum illaa khasaaraa','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>40,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ شُرَكَآءَكُمُ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِ أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا فَهُمۡ عَلَىٰ بَيِّنَتٖ مِّنۡهُۚ بَلۡ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا','transliteration'=>'Qul ara\'aytum shurakaaa\'a-kumul lazeena tad\'oona min doonil laahi; aroonee maazaa khalaqoo minal ardi am lahum shirkun fis samaawaati am aatainaahum Kitaaban fahum \'alaa baiyyinatim minh; bal ien ya\'iduz zaalimoona ba-\'duhum ba\'dan illaa ghurooraa','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>41,'arabic_text'=>'۞ إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدٖ مِّنۢ بَعۡدِهِۦٓۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا','transliteration'=>'Innal laaha yumsikus samaawaati wal-arda an tazoolaaa; Wa-la\'in zaalataaa in amsa-kahumaa min ahadim mim ba\'dih; innahoo kaana Haleeman Ghafooraa','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>42,'arabic_text'=>'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ نَذِيرٞ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرٞ مَّا زَادَهُمۡ إِلَّا نُفُورًا','transliteration'=>'Wa-aqsamoo billaahi jahda aymaanihim la\'in jaaa\'ahum nazeerul layakoonunna ahdaa min ihdal umami falam-maa jaaa\'ahum nazeerum maa zaadahum illaa nufooraa','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>43,'arabic_text'=>'ٱسۡتِكۡبَارٗا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلٗاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا','transliteration'=>'Istikbaaran fil ardi Wa-makras sayyi\'; Wa-laa yaheequl makrus sayyi\'u illaa bi-ahlih; fahal yanzuroona illaa sunnatal awwaleen; falan tajida lisunnatil laahi tabdeelanw Wa-lan tajida lisunnatil laahi tahweela','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>44,'arabic_text'=>'أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَكَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗۚ وَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءٖ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمٗا قَدِيرٗا','transliteration'=>'Awalam yaseeroo fil ardi fa-yanzuroo kaifa kaana \'aaqibatul lazeena min Qablihim Wa-kaanoo ashadda minhum quwwah; Wa-maa kaanal laahu liyu\'jizahoo min shai\'in fis samaawaati Wa-laa fil ard; innahoo kaana \'Aleeman Qadeeraa','page_number'=>439,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>35,'ayah_number'=>45,'arabic_text'=>'وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا','transliteration'=>'Wa-law yu\'aakhizul laahun naasa bima kasaboo maa taraka \'alaa zahrihaa min daaabbatinw Wa-laakiny yu\'akhkhiruhum ilaaa ajalim musamman fa-izaa jaaa\'a ajaluhum fa-innal laaha kaana bi\'ibaadihee Baseeraa','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            /* Surah 36: Ya Sin (Ya-Sin) */
            ['surah_id'=>36,'ayah_number'=>1,'arabic_text'=>'يسٓ','transliteration'=>'Yaa-Seeen','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>2,'arabic_text'=>'وَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ','transliteration'=>'Wal-Qur-aanil Hakeem','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>3,'arabic_text'=>'إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ','transliteration'=>'Innaka laminal mursaleen','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>4,'arabic_text'=>'عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Alaa Siraatim Mustaqeem','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>5,'arabic_text'=>'تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ','transliteration'=>'Tanzeelal \'Azeezir Raheem','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>6,'arabic_text'=>'لِتُنذِرَ قَوۡمٗا مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ','transliteration'=>'Litunzira qawmam maaa unzira aabaaa\'uhum fahum ghaafiloon','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>7,'arabic_text'=>'لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Laqad haqqal qawlu \'alaaa aksarihim fahum laa yu\'minoon','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>8,'arabic_text'=>'إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلٗا فَهِيَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ','transliteration'=>'Innaa ja\'alnaa feee a\'naaqihim aghlaalan fahiya ilal azqaani fahum muqmahoon','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>9,'arabic_text'=>'وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدّٗا وَمِنۡ خَلۡفِهِمۡ سَدّٗا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ','transliteration'=>'Wa-ja\'alnaa mim baini aydeehim saddanw wa-min khalfihim saddan fa-aghshai-naahum fahum laa yubsiroon','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>10,'arabic_text'=>'وَسَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ','transliteration'=>'Wa-sawaaa\'un \'alaihim \'a-anzartahum am lam tunzirhum laa yu\'minoon','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>11,'arabic_text'=>'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةٖ وَأَجۡرٖ كَرِيمٍ','transliteration'=>'Innamaa tunziru manit taba \'az-Zikra Wa-khashiyar Rahmaana bilghaib, fabashshirhu bimaghfiratinw-wa ajrin kareem','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>12,'arabic_text'=>'إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ','transliteration'=>'Innaa Nahnu nuhyil mawtaa Wa-naktubu maa qaddamoo Wa-aasaarahum; Wa-kulla shai\'in ahsainaahu feee Imaamim Mubeen','page_number'=>440,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>13,'arabic_text'=>'وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ','transliteration'=>'Wadrib lahum masalan Ashaabal Qaryatih; iz jaaa\'ahal mursaloon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>14,'arabic_text'=>'إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ','transliteration'=>'Iz arsalnaaa ilaihimus naini fakazzaboohumaa fa\'azzaznaa bisaalisin faqaalooo innaaa ilaikum mursaloon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>15,'arabic_text'=>'قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ','transliteration'=>'Qaaloo maaa antum illaa basharum mislunaa Wa-maaa anzalar Rahmaanu min shai\'in in antum illaa takziboon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>16,'arabic_text'=>'قَالُواْ رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ','transliteration'=>'Qaaloo Rabbunaa ya\'lamu innaaa ilaikum lamursaloon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>17,'arabic_text'=>'وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Wa-maa \'alainaaa illal balaaghul mubeen','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>18,'arabic_text'=>'قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٞ','transliteration'=>'Qaaloo innaa tataiyarnaa bikum la\'il lam tantahoo lanar-jumannakum Wa-la-yamassan-nakum minnaa \'azaabun aleem','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>19,'arabic_text'=>'قَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ','transliteration'=>'Qaaloo taaa\'irukum ma\'akum; a\'in zukkirtum; bal antum qawmum musrifoon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>20,'arabic_text'=>'وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ','transliteration'=>'Wa-jaaa\'a min aqsal madeenati rajuluien yas\'aa qaala yaa-qawmit tabi\'ul mursaleen','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>21,'arabic_text'=>'ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ','transliteration'=>'Ittabi\'oo mal laa yas\'alukum ajranw wa-hum muhtadoon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>22,'arabic_text'=>'وَمَالِيَ لَآ أَعۡبُدُ ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-maa liya laaa a\'budul lazee fataranee Wa-ilaihi turja\'oon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>23,'arabic_text'=>'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرّٖ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـٔٗا وَلَا يُنقِذُونِ','transliteration'=>'A-attakhizu min dooniheee aalihatan ien yuridnir Rahmaanu bidurril laa tughni \'annee shafaa-\'atuhum shai-\'anw wa-laa yunqizoon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>24,'arabic_text'=>'إِنِّيٓ إِذٗا لَّفِي ضَلَٰلٖ مُّبِينٍ','transliteration'=>'Inneee izal lafee dalaa-lim mubeen','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>25,'arabic_text'=>'إِنِّيٓ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ','transliteration'=>'Inneee aamantu bi-Rabbikum fasma\'oon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>26,'arabic_text'=>'قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي يَعۡلَمُونَ','transliteration'=>'Qeelad khulil Jannnah; qaala yaa-laita qawmee ya\'lamoon','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>27,'arabic_text'=>'بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ','transliteration'=>'Bimaa ghafara lee Rabbee Wa-ja\'alanee minal mukrameen','page_number'=>441,'juz_number'=>22,'hizb_number'=>44,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>28,'arabic_text'=>'۞ وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندٖ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ','transliteration'=>'Wa-maaa anzalnaa \'alaa qawmihee mim ba\'dihee min jundim minas samaaa\'i Wa-maa kunnaa munzileen','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>29,'arabic_text'=>'إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ خَٰمِدُونَ','transliteration'=>'In kaanat illaa saihatanw waahidatan fa-izaa hum khaamidoon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>30,'arabic_text'=>'يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Yaa-hasratan \'alal \'ibaaad; maa ya\'teehim mir Rasoolin illaa kaanoo bihee yastahzi-\'oon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>31,'arabic_text'=>'أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ','transliteration'=>'Alam yaraw kam ahlak-naa qablahum minal qurooni annahum ilaihim laa yarji\'oon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>32,'arabic_text'=>'وَإِن كُلّٞ لَّمَّا جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ','transliteration'=>'Wa-in kullul lammaa jamee\'ul ladainaa muhdaroon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>33,'arabic_text'=>'وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ','transliteration'=>'Wa-Aayatul lahumul ardul maitatu ahyainaahaa Wa-akhrajnaa minhaa habban faminhu ya\'kuloon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>34,'arabic_text'=>'وَجَعَلۡنَا فِيهَا جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ','transliteration'=>'Wa-ja\'alnaa feehaa jannaatim min nakheelinw Wa-a\'naabinw Wa-fajjarnaa feeha minal \'uyoon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>35,'arabic_text'=>'لِيَأۡكُلُواْ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ','transliteration'=>'Li-ya\'kuloo min samarihee Wa-maa \'amilat-hu aideehim; afalaa yashkuroon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>36,'arabic_text'=>'سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ','transliteration'=>'Subhaanal lazee khalaqal azwaaja kullahaa mimmaa tumbitul ardu Wa-min anfusihim Wa-mimmaa laa ya\'lamoon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>37,'arabic_text'=>'وَءَايَةٞ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ','transliteration'=>'Wa-Aayatul lahumul lailu naslakhu minhun nahaara fa-izaa hum muzlimoon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>38,'arabic_text'=>'وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ','transliteration'=>'Wash-shamsu tajree limustaqarril lahaa; zaalika taqdeerul \'Azeezil Aleem','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>39,'arabic_text'=>'وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ','transliteration'=>'Walqamara qaddarnaahu manaazila hattaa \'aada kal\'ur-joonil qadeem','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>40,'arabic_text'=>'لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ','transliteration'=>'Lash shamsu yambaghee lahaaa an tudrikal qamara walal lailu saabiqun nahaar; Wa-kullun fee falaki yasbahoon','page_number'=>442,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>41,'arabic_text'=>'وَءَايَةٞ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ','transliteration'=>'Wa-Aayatul lahum annaa hamalnaa zurriyatahum fil fulkil mashhoon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>42,'arabic_text'=>'وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ','transliteration'=>'Wa-khalaqnaa lahum mim mislihee maa yarkaboon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>43,'arabic_text'=>'وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُنقَذُونَ','transliteration'=>'Wa-in nashaa nughriqhum falaa sareekha lahum Wa-laa hum yunqazoon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>44,'arabic_text'=>'إِلَّا رَحۡمَةٗ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٖ','transliteration'=>'Illaa rahmatam minnaa Wa-mataa\'an ilaa heen','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>45,'arabic_text'=>'وَإِذَا قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Wa-izaa qeela lahumut taqoo maa baina aideekum Wa-maa khalfakum la\'allakum turhamoon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>46,'arabic_text'=>'وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ','transliteration'=>'Wa-maa ta\'teehim min aayatim min Aayaati Rabbihim illaa kaanoo \'anhaa mu\'rideen','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>47,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Wa-izaa qeela lahum anfiqoo mimmaa razaqakumul laahu qaalal lazeena kafaroo lillazeena aamanooo anut\'imu mal law yashaaa\'ul laahu at\'amahooo in antum illaa fee dalaalim mubeen','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>48,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>49,'arabic_text'=>'مَا يَنظُرُونَ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ تَأۡخُذُهُمۡ وَهُمۡ يَخِصِّمُونَ','transliteration'=>'Maa yanzuroona illaa saihatanw waahidatan ta\'khuzuhum Wa-hum yakhissimoon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>50,'arabic_text'=>'فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةٗ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ يَرۡجِعُونَ','transliteration'=>'Falaa yastatee\'oona taw-siyatanw wa-laaa ilaaa ahlihim yarji\'oon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>51,'arabic_text'=>'وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ','transliteration'=>'Wa-nufikha fis soori faizaa hum minal ajdaasi ilaa Rabbihim yansiloon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>52,'arabic_text'=>'قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ','transliteration'=>'Qaaloo yaa-wailanaa mam ba\'asanaa mim marqadinaa; haaza maa wa\'adar Rahmanu Wa-sadaqal mursaloon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>53,'arabic_text'=>'إِن كَانَتۡ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ فَإِذَا هُمۡ جَمِيعٞ لَّدَيۡنَا مُحۡضَرُونَ','transliteration'=>'In kaanat illaa saihatanw waahidatan fa-izaa hum jamee\'ul ladainaa muhdaroon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>54,'arabic_text'=>'فَٱلۡيَوۡمَ لَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Fal-Yawma laa tuzlamu nafsun shai\'anw-wa laa tujzawna illaa maa kuntum ta\'maloon','page_number'=>443,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>55,'arabic_text'=>'إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلٖ فَٰكِهُونَ','transliteration'=>'Inna Ashaabal jannatil Yawma fee shughulin faakihoon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>56,'arabic_text'=>'هُمۡ وَأَزۡوَٰجُهُمۡ فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ','transliteration'=>'Hum Wa-azwaajuhum fee zilaalin \'alal araaa\'iki muttaki\'oon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>57,'arabic_text'=>'لَهُمۡ فِيهَا فَٰكِهَةٞ وَلَهُم مَّا يَدَّعُونَ','transliteration'=>'Lahum feehaa faakiha-tunw wa-lahum maa yadda\'oon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>58,'arabic_text'=>'سَلَٰمٞ قَوۡلٗا مِّن رَّبّٖ رَّحِيمٖ','transliteration'=>'Salaamun qawlam mir Rabbir Raheem','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>59,'arabic_text'=>'وَٱمۡتَٰزُواْ ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ','transliteration'=>'Wamtaazul Yawma ayyuhal mujrimoon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>60,'arabic_text'=>'۞ أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ','transliteration'=>'Alam a\'had ilaikum yaa Baneee Aadama al-laa ta\'budush Shaitaana innahoo lakum \'aduwwum mubeen','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>61,'arabic_text'=>'وَأَنِ ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ','transliteration'=>'Wa-ani \'budoonee; haazaa Siraatum Mustaqeem','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>62,'arabic_text'=>'وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلّٗا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ','transliteration'=>'Wa-laqad adalla minkum jibillan kaseeraa; afalam takoonoo ta\'qiloon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>63,'arabic_text'=>'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي كُنتُمۡ تُوعَدُونَ','transliteration'=>'Haazihee Jahannamul latee kuntum too\'adoon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>64,'arabic_text'=>'ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ','transliteration'=>'Islawhal Yawma bimaa kuntum takfuroon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>65,'arabic_text'=>'ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Al-Yawma nakhtimu \'alaaa afwaahihim Wa-tukallimunaaa aideehim Wa-tashhadu arjuluhum bimaa kaanoo yaksiboon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>66,'arabic_text'=>'وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ','transliteration'=>'Wa-law nashaaa\'u lata-masna \'alaaa aiyyunihim fasta-baqus siraata fa-annaa yubsiroon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>67,'arabic_text'=>'وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيّٗا وَلَا يَرۡجِعُونَ','transliteration'=>'Wa-law nashaaa\'u lamasakhnaahum \'alaa makaanatihim famas tataa\'oo mudiyyanw-wa laa yarji\'oon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>68,'arabic_text'=>'وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ','transliteration'=>'Wa-man nu-\'ammirhu nunakkishu fil khalq; afalaa ya\'qiloon','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>69,'arabic_text'=>'وَمَا عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ وَقُرۡءَانٞ مُّبِينٞ','transliteration'=>'Wa-maa \'allamnaahush shi\'ra Wa-maa yambaghee lah; in huwa illaa zikrunw-wa Qur-aanum mubeen','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>70,'arabic_text'=>'لِّيُنذِرَ مَن كَانَ حَيّٗا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ','transliteration'=>'Liyunzira man kaana haiyyanw wa-yahiqqal qawlu \'alal kaafireen','page_number'=>444,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>71,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمٗا فَهُمۡ لَهَا مَٰلِكُونَ','transliteration'=>'Awalam yaraw annaa khalaqnaa lahum mimmaa \'amilat aideenaaa an\'aaman fahum lahaa maalikoon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>72,'arabic_text'=>'وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُلُونَ','transliteration'=>'Wa-zallalnaahaa lahum faminhaa rakoobuhum Wa-minhaa ya\'kuloon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>73,'arabic_text'=>'وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ أَفَلَا يَشۡكُرُونَ','transliteration'=>'Wa-lahum feehaa manaa-fi\'u Wa-mashaarib; afalaa yashkuroon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>74,'arabic_text'=>'وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لَّعَلَّهُمۡ يُنصَرُونَ','transliteration'=>'Wattakhazoo min doonil laahi aalihatal la\'allahum yunsaroon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>75,'arabic_text'=>'لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندٞ مُّحۡضَرُونَ','transliteration'=>'Laa yastatee\'oona nasrahum Wa-hum lahum jundum muhdaroon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>76,'arabic_text'=>'فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ','transliteration'=>'Falaa yahzunka qawluhum; innaa na\'lamu maa yusirroona Wa-maa yu\'linoon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>77,'arabic_text'=>'أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ','transliteration'=>'Awalam yaral insaanu annaa khalaqnaahu min nutfatin fa-izaa huwa khaseemum mubeen','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>78,'arabic_text'=>'وَضَرَبَ لَنَا مَثَلٗا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمٞ','transliteration'=>'Wa-daraba lanaa maslanw wa-nasiya khalqahoo qaala maien yuhyil \'izaama Wa-hiya rameem','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>79,'arabic_text'=>'قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةٖۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ','transliteration'=>'Qul yuh-yeehal lazeee ansha-ahaaa awwala marrah; Wa-Huwa bikulli khalqin \'Aleem','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>80,'arabic_text'=>'ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ','transliteration'=>'Allazee ja\'ala lakum minash shajaril akhdari naaran fa-izaaa antum minhu tooqidoon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>81,'arabic_text'=>'أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ','transliteration'=>'Awa-laisal lazee khalaqas samaawaati wal arda biqaadirin \'alaaa ai-yakhluqa mislahum; balaa Wa-Huwal Khallaaqul \'Aleem','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>82,'arabic_text'=>'إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Innamaa amruhooo izaaa araada shai\'an aien yaqoola lahoo kun fa-yakoon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>36,'ayah_number'=>83,'arabic_text'=>'فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Fa-Subhaanal lazee biyadihee malakootu kulli shai-inw wa-ilaihi turja\'oon','page_number'=>445,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            /* Surah 37: Those who set the Ranks (As-Saffat) */
            ['surah_id'=>37,'ayah_number'=>1,'arabic_text'=>'وَٱلصَّٰٓفَّٰتِ صَفّٗا','transliteration'=>'Wassaaaffaati saffaa','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>2,'arabic_text'=>'فَٱلزَّٰجِرَٰتِ زَجۡرٗا','transliteration'=>'Fazzaajiraati zajraa','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>3,'arabic_text'=>'فَٱلتَّٰلِيَٰتِ ذِكۡرًا','transliteration'=>'Fattaaliyaati Zikra','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>4,'arabic_text'=>'إِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ','transliteration'=>'Inna Illaahakum la-Waahid','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>5,'arabic_text'=>'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ','transliteration'=>'Rabbus samaawaati wal-ardi Wa-maa bainahumaa Wa-Rabbul mashaariq','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>6,'arabic_text'=>'إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ','transliteration'=>'Innaa zaiyannas samaaa \'ad-dunyaa bizeenatinil kawaakib','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>7,'arabic_text'=>'وَحِفۡظٗا مِّن كُلِّ شَيۡطَٰنٖ مَّارِدٖ','transliteration'=>'Wa-hifzam min kulli Shaitaanim maarid','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>8,'arabic_text'=>'لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبٖ','transliteration'=>'Laa yassamma-\'oona ilal mala-\'il a\'alaa Wa-yuqzafoona min kulli jaanib','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>9,'arabic_text'=>'دُحُورٗاۖ وَلَهُمۡ عَذَابٞ وَاصِبٌ','transliteration'=>'Duhooranw Wa-lahum \'azaabunw waasib','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>10,'arabic_text'=>'إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابٞ ثَاقِبٞ','transliteration'=>'Illaa man khatifal khatfata fa-atba\'ahoo shihaabun saaqib','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>11,'arabic_text'=>'فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينٖ لَّازِبِۭ','transliteration'=>'Fastaftihim ahum ashaddu khalqan am man khalaqnaa; innaa khalaqnaahum min teenil laazib','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>12,'arabic_text'=>'بَلۡ عَجِبۡتَ وَيَسۡخَرُونَ','transliteration'=>'Bal \'ajibta Wa-yaskharoon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>13,'arabic_text'=>'وَإِذَا ذُكِّرُواْ لَا يَذۡكُرُونَ','transliteration'=>'Wa-izaa zukkiroo laa yazkuroon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>14,'arabic_text'=>'وَإِذَا رَأَوۡاْ ءَايَةٗ يَسۡتَسۡخِرُونَ','transliteration'=>'Wa-izaa ra-aw Aayataien yastaskhiroon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>15,'arabic_text'=>'وَقَالُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٌ','transliteration'=>'Wa-qaalooo in haazaa illaa sihrum mubeen','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>16,'arabic_text'=>'أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ','transliteration'=>'A-izaa mitnaa Wa-kunnaa turaabanw Wa-\'izaaman \'a-innaa lamab\'oosoon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>17,'arabic_text'=>'أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ','transliteration'=>'Awa-aabaa\'unal awwaloon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>18,'arabic_text'=>'قُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ','transliteration'=>'Qul na\'am Wa-antum daakhiroon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>19,'arabic_text'=>'فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ فَإِذَا هُمۡ يَنظُرُونَ','transliteration'=>'Fa-innamaa hiya zajra-tunw waahidatun fa-izaa hum yanzuroon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>20,'arabic_text'=>'وَقَالُواْ يَٰوَيۡلَنَا هَٰذَا يَوۡمُ ٱلدِّينِ','transliteration'=>'Wa-qaaloo yaa-wailanaa haazaa Yawmud Deen','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>21,'arabic_text'=>'هَٰذَا يَوۡمُ ٱلۡفَصۡلِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ','transliteration'=>'Haazaa Yawmul Faslil lazee kuntum bihee tukaziboon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>22,'arabic_text'=>'۞ ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ','transliteration'=>'Uhshurul lazeena zalamoo Wa-azwaajahum Wa-maa kaanoo ya\'budoon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>23,'arabic_text'=>'مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ','transliteration'=>'Min doonil laahi fahdoohum ilaa siraatil Jaheem','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>24,'arabic_text'=>'وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ','transliteration'=>'Wa-qifoohum innahum mas\'ooloon','page_number'=>446,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>25,'arabic_text'=>'مَا لَكُمۡ لَا تَنَاصَرُونَ','transliteration'=>'Maa lakum laa tanaasaroon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>26,'arabic_text'=>'بَلۡ هُمُ ٱلۡيَوۡمَ مُسۡتَسۡلِمُونَ','transliteration'=>'Bal humul Yawma mustaslimoon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>27,'arabic_text'=>'وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ','transliteration'=>'Wa-aqbala ba\'duhum \'alaa ba\'diny yatasaaa\'aloon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>28,'arabic_text'=>'قَالُوٓاْ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡيَمِينِ','transliteration'=>'Qaalooo innakum kuntum taatoonanaa \'anil yameen','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>29,'arabic_text'=>'قَالُواْ بَل لَّمۡ تَكُونُواْ مُؤۡمِنِينَ','transliteration'=>'Qaaloo bal lam takoonoo mu\'mineen','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>30,'arabic_text'=>'وَمَا كَانَ لَنَا عَلَيۡكُم مِّن سُلۡطَٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمٗا طَٰغِينَ','transliteration'=>'Wa-maa kaana lanaa \'alaikum min sultaanim bal kuntum qawman taagheen','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>31,'arabic_text'=>'فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّنَآۖ إِنَّا لَذَآئِقُونَ','transliteration'=>'Fahaqqa \'alainaa qawlu Rabbinaaa innaa lazaaa\'iqoon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
