            ['surah_id'=>37,'ayah_number'=>33,'arabic_text'=>'فَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ','transliteration'=>'Fa-innahum Yawma\'izin fil \'azaabi mushtarikoon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>34,'arabic_text'=>'إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ','transliteration'=>'Innaa kazaalika naf\'alu bil-mujrimeen','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>35,'arabic_text'=>'إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ لَهُمۡ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ','transliteration'=>'Innahum kaanooo izaa qeela lahum laaa ilaaha illal laahu yastakbiroon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
            ['surah_id'=>37,'ayah_number'=>36,'arabic_text'=>'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا لِشَاعِرٖ مَّجۡنُونِۭ','transliteration'=>'Wa-yaqooloona a\'innaa lataarikooo aalihatinaa lishaa\'irim majnoon','page_number'=>447,'juz_number'=>23,'hizb_number'=>45,'is_sajdah'=>false],
