            ['surah_id'=>38,'ayah_number'=>1,'arabic_text'=>'صٓۚ وَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ','transliteration'=>'Saaad; wal-Qur-aani ziz zikr','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>2,'arabic_text'=>'بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ','transliteration'=>'Balil lazeena kafaroo fee \'izzatinw Wa-shiqaaq','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>3,'arabic_text'=>'كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصٖ','transliteration'=>'Kam ahlaknaa min qablihim min qarnin fanaadaw Wa-laata heena manaas','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>4,'arabic_text'=>'وَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ','transliteration'=>'Wa-\'ajibooo an jaaa\'a-hum munzirum minhum Wa-qaalal kaafiroona haazaa saahirun kazzaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>5,'arabic_text'=>'أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهٗا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابٞ','transliteration'=>'Aja\'alal aalihata Ilaahanw Waahidan inna haazaa lashai\'un \'ujaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>6,'arabic_text'=>'وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ','transliteration'=>'Wantalaqal mala-u minhum anim shoo wasbiroo \'alaaa aalihatikum innna haazaa lashai-\'uien yuraad','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>7,'arabic_text'=>'مَا سَمِعۡنَا بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ','transliteration'=>'Maa sami\'naa bihaazaa fil millatil aakhirati in haazaaa illakh tilaaq','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>8,'arabic_text'=>'أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ','transliteration'=>'A-unzila \'alaihiz zikru min baininaa; bal hum fee shakkin min Zikree bal lammaa yazooqoo \'azaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>9,'arabic_text'=>'أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ','transliteration'=>'Am\'indahum khazaaa \'inu rahmati Rabbikal \'Azeezil Wahhab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>10,'arabic_text'=>'أَمۡ لَهُم مُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ','transliteration'=>'Am lahum mulkus samaawaati wal-ardi Wa-maa bainahumaa falyartaqoo fil asbaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>11,'arabic_text'=>'جُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ','transliteration'=>'Jundum maa hunaalika mahzoomum minal Ahzaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>12,'arabic_text'=>'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ','transliteration'=>'Kazzabat qablahum qawmu Noohinw Wa-\'Aadunw Wa-Fir\'awnu zul awtaad','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>13,'arabic_text'=>'وَثَمُودُ وَقَوۡمُ لُوطٖ وَأَصۡحَٰبُ لۡـَٔيۡكَةِۚ أُوْلَٰٓئِكَ ٱلۡأَحۡزَابُ','transliteration'=>'Wa-Samoodu Wa-qawmu Lootinw Wa-As-haabul \'Aykah; ulaaa\'ikal Ahzaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>14,'arabic_text'=>'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ','transliteration'=>'In kullun illaa kazzabar Rusula fahaqqa \'iqaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>15,'arabic_text'=>'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيۡحَةٗ وَٰحِدَةٗ مَّا لَهَا مِن فَوَاقٖ','transliteration'=>'Wa-maa yanzuru haaa-ulaaa\'i illaa saihatanw waahidatam maa lahaa min fawaaq','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>16,'arabic_text'=>'وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ يَوۡمِ ٱلۡحِسَابِ','transliteration'=>'Wa-qaaloo Rabbanaa \'ajjil lanaa qittanaa qabla Yawmil Hisaab','page_number'=>453,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>17,'arabic_text'=>'ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ','transliteration'=>'Isbir \'alaa maa yaqooloona wazkur \'abdanaa Daawooda zal aidi innahooo awwaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>18,'arabic_text'=>'إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ','transliteration'=>'Innaa sakhkharnal jibaala ma\'ahoo yusabbihna bil\'ashiyyi wal-ishraaq','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>19,'arabic_text'=>'وَٱلطَّيۡرَ مَحۡشُورَةٗۖ كُلّٞ لَّهُۥٓ أَوَّابٞ','transliteration'=>'Wattayra mahshoorah; kullul lahooo awwaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>20,'arabic_text'=>'وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ','transliteration'=>'Wa-shadadnaa mulkahoo Wa-aatainaahul Hikmata Wa-faslal khitaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>21,'arabic_text'=>'۞ وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ ٱلۡمِحۡرَابَ','transliteration'=>'Wa-hal ataaka naba\'ul khasm; iz tasawwarul mihraab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>22,'arabic_text'=>'إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضٖ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ','transliteration'=>'Iz dakhaloo \'alaa Daawooda fafazi\'a minhum qaaloo laa takhaf khasmaani baghaa ba\'dunaa \'alaa ba\'din fahkum bainanaaa bilhaqqi Wa-laa tushtit wahdinaaa ilaa Sawaaa\'is Siraat','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>23,'arabic_text'=>'إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ','transliteration'=>'Inna haazaaa akhee lahoo tis\'unw Wa-tis\'oona na\'jatanw Wa-liya na\'jatunw waahidah; faqaala akfilneeha Wa-\'azzanee fil khitaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>24,'arabic_text'=>'قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ','transliteration'=>'Qaala laqad zalamaka bisu-\'aali na\'jatika ilaa ni\'aajih; Wa-inna kaseeran minal khulataaa\'i la-yabghee ba\'duhum \'alaa ba\'din illal lazeena aamanoo Wa-\'amilus saalihaati Wa-qaleelun maa hum; Wa-zanna Daawoodu annamaa fatannaahu fastaghfara Rabbahoo Wa-kharra raaki\'anw Wa-anaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>true],
            ['surah_id'=>38,'ayah_number'=>25,'arabic_text'=>'فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ','transliteration'=>'Faghafarnaa lahoo zaalik; Wa-inna lahoo \'indanaa lazulfaa Wa-husna ma-aab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>26,'arabic_text'=>'يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ','transliteration'=>'Yaa-Daawoodu innaa ja\'alnaaka khaleefatan fil ardi fahkum bainan naasi bilhaqqi Wa-laa tattabi\'il hawaa fayudillaka \'an sabeelil laah; innal lazeena yadilloona \'an sabeelil laah; lahum \'azaabun shadeedum bimaa nasoo Yawmal Hisaab','page_number'=>454,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>27,'arabic_text'=>'وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلٗاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ','transliteration'=>'Wa-maa khalaqnas samaaa\'a wal-arda Wa-maa bainahumaa baatilaa; zaalika zannul lazeena kafaroo; fa-waylul lil-lazeena kafaroo minan Naar','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>28,'arabic_text'=>'أَمۡ نَجۡعَلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ كَٱلۡمُفۡسِدِينَ فِي ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِينَ كَٱلۡفُجَّارِ','transliteration'=>'Am naj\'alul lazeena aamanoo Wa-\'amilus saalihaati kalmufisdeena fil ardi am naj\'alul muttaqeena kalfujjaar','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>29,'arabic_text'=>'كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Kitaabun anzalnaahu ilaika mubaarakul liyaddabbarooo Aayaatihee Wa-liyatazakkara ulul albaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>30,'arabic_text'=>'وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ','transliteration'=>'Wa-wahabnaa li-Daawooda Sulaimaan; ni\'mal \'abd; innahoo awwaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>31,'arabic_text'=>'إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ','transliteration'=>'Iz \'urida \'alaihi bil\'ashiy-yis saafinaatul jiyaad','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>32,'arabic_text'=>'فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ','transliteration'=>'Faqaala inneee ahbabtu hubbal khairi \'an zikri Rabbee hattaa tawaarat bilhijaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>33,'arabic_text'=>'رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ','transliteration'=>'Ruddoohaa \'alaiya fa-tafiqa mas-ham bissooqi wal-a\'naaq','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>34,'arabic_text'=>'وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدٗا ثُمَّ أَنَابَ','transliteration'=>'Wa-laqad fatannaa Sulaimaana Wa-alqainaa \'alaa kursiyyihee jasadan summa anaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>35,'arabic_text'=>'قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ','transliteration'=>'Qaala Rabbigh fir lee Wa-hab lee mulkal laa yambaghee li-ahadin min ba\'dee innaka Antal Wahhaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>36,'arabic_text'=>'فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ','transliteration'=>'Fa-sakharnaa lahur reeha tajree bi-amrihee rukhaaa\'an haisu asaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>37,'arabic_text'=>'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٖ وَغَوَّاصٖ','transliteration'=>'Wash-Shayaateena kulla bannaaa\'inw Wa-ghawwaas','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>38,'arabic_text'=>'وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ','transliteration'=>'Wa-aakhareena muqarraneena fil asfaad','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>39,'arabic_text'=>'هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ','transliteration'=>'Haazaa \'ataaa\'unaa famnun aw amsik bighairi hisaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>40,'arabic_text'=>'وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابٖ','transliteration'=>'Wa-inna lahoo \'indanaa lazulfaa Wa-husna ma-aab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>41,'arabic_text'=>'وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ','transliteration'=>'Wazkur \'abdanaaa Ayyoob; iz naada Rabbahooo annee massaniyash Shaitaanu bi-nusbinw Wa-\'azaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>42,'arabic_text'=>'ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ','transliteration'=>'Urkud bi-rijlika haaza mughtasalun baaridunw Wa-sharaab','page_number'=>455,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>43,'arabic_text'=>'وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ','transliteration'=>'Wa-wahabnaa lahoo ahlahoo Wa-mislahum ma\'ahum rahmatan minna Wa-zikraa li-ulil albaab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>44,'arabic_text'=>'وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ','transliteration'=>'Wa-khuz biyadika dighsan fadrib bihee Wa-laa tahnas, innaa wajadnaahu saabiraa; ni\'mal \'abd; innahooo awwaab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>45,'arabic_text'=>'وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ','transliteration'=>'Wazkur \'ibaadanaaa Ibraaheema Wa-Is-haaqa Wa-Ya\'qooba ulil aydee walabsaar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>46,'arabic_text'=>'إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةٖ ذِكۡرَى ٱلدَّارِ','transliteration'=>'Innaaa akhlasnaahum bi-khaalisatin zikrad daar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>47,'arabic_text'=>'وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ','transliteration'=>'Wa-innahum \'indanaa laminal mustafainal akhyaar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>48,'arabic_text'=>'وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ','transliteration'=>'Wazkur Ismaa\'eela wal Yasa\'a Wa-Zal-Kifli Wa-kullun minal akhyaar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>49,'arabic_text'=>'هَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ','transliteration'=>'Haazaa zikrun Wa-inna lil-muttaqeena la-husna ma-aab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>50,'arabic_text'=>'جَنَّٰتِ عَدۡنٖ مُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ','transliteration'=>'Jannaati \'adnin mufattahatan lahumul abwaab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>51,'arabic_text'=>'مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةٖ كَثِيرَةٖ وَشَرَابٖ','transliteration'=>'Muttaki\'eena feehaa yad\'oona feehaa bifaakihatin kaseeratinw Wa-sharaab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>52,'arabic_text'=>'۞ وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ','transliteration'=>'Wa-\'indahum qaasiraatut tarfi atraab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>53,'arabic_text'=>'هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ ٱلۡحِسَابِ','transliteration'=>'Haazaa maa too\'adoona li-Yawmil Hisaab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>54,'arabic_text'=>'إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ','transliteration'=>'Inna haazaa larizqunaa maa lahoo min nafaad','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>55,'arabic_text'=>'هَٰذَاۚ وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٖ','transliteration'=>'Haazaa; Wa-inna littaagheena lasharra ma-aab','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>56,'arabic_text'=>'جَهَنَّمَ يَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ','transliteration'=>'Jahannama yaslawnahaa fa-bi\'sal mihaad','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>57,'arabic_text'=>'هَٰذَا فَلۡيَذُوقُوهُ حَمِيمٞ وَغَسَّاقٞ','transliteration'=>'Haazaa falyazooqoohu hameemunw Wa-ghassaaq','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>58,'arabic_text'=>'وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ','transliteration'=>'Wa-aakharu min shakliheee azwaaj','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>59,'arabic_text'=>'هَٰذَا فَوۡجٞ مُّقۡتَحِمٞ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ','transliteration'=>'Haazaa fawjun muqtahimun ma\'akum laa marhaban bihim; innahum saalun Naar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>60,'arabic_text'=>'قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ','transliteration'=>'Qaaloo bal antum laa marhaban bikum; antum qaddamtumoohu lanaa fabi\'sal qaraar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>61,'arabic_text'=>'قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابٗا ضِعۡفٗا فِي ٱلنَّارِ','transliteration'=>'Qaaloo Rabbanaa man qaddama lanaa haazaa fa-zidhu \'azaaban di\'fan fin Naar','page_number'=>456,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>62,'arabic_text'=>'وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ','transliteration'=>'Wa-qaaloo maa lanaa laa naraa rijaalan kunnaa na\'udduhum minal ashraar','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>63,'arabic_text'=>'أَتَّخَذۡنَٰهُمۡ سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَٰرُ','transliteration'=>'Attakhaznaahum sikh-riyyan am zaaghat \'anhumul absaar','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>64,'arabic_text'=>'إِنَّ ذَٰلِكَ لَحَقّٞ تَخَاصُمُ أَهۡلِ ٱلنَّارِ','transliteration'=>'Inna zaalika lahaqqun takhaasumu Ahlin Naar','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>65,'arabic_text'=>'قُلۡ إِنَّمَآ أَنَا۠ مُنذِرٞۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ','transliteration'=>'Qul innamaaa ana munzirunw Wa-maa min laahin illal laahul Waahidul Qahhaar','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>66,'arabic_text'=>'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ','transliteration'=>'Rabbus samaawaati wal-ardi Wa-maa bainahumal \'Azeezul Ghaffaar','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>67,'arabic_text'=>'قُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ','transliteration'=>'Qul huwa naba\'un \'azeem','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>68,'arabic_text'=>'أَنتُمۡ عَنۡهُ مُعۡرِضُونَ','transliteration'=>'Antum \'anhu mu\'ridoon','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>69,'arabic_text'=>'مَا كَانَ لِيَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ إِذۡ يَخۡتَصِمُونَ','transliteration'=>'Maa kaana liya min \'ilmin bil-mala\'il a\'laaa iz yakhtasimoon','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>70,'arabic_text'=>'إِن يُوحَىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ','transliteration'=>'Ien-yoohaaa ilaiya illaaa anna maaa ana nazeerun mubeen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>71,'arabic_text'=>'إِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن طِينٖ','transliteration'=>'Iz qaala Rabbuka lilmalaaa\'ikati innee khaaliqun basharan min teen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>72,'arabic_text'=>'فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ','transliteration'=>'Fa-iza sawwaituhoo Wa-nafakhtu feehi mir roohee faqa\'oo lahoo saajideen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>73,'arabic_text'=>'فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ','transliteration'=>'Fasajadal malaaa\'ikatu kulluhum ajma\'oon','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>74,'arabic_text'=>'إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ','transliteration'=>'Illaaa Iblees; stakbara Wa-kaana minal kaafireen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>75,'arabic_text'=>'قَالَ يَٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ','transliteration'=>'Qaala yaaa-Ibleesu maa mana\'aka an tasjuda limaa khalaqtu bi-yadaiyya-\'a stakbarta am kunta min al-\'aaleen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>76,'arabic_text'=>'قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ','transliteration'=>'Qaala ana khairum minhu; khalaqtanee min naarinw Wa-khalaqtahoo min teen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>77,'arabic_text'=>'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ','transliteration'=>'Qaala fakhruj minhaa fa-innaka rajeem','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>78,'arabic_text'=>'وَإِنَّ عَلَيۡكَ لَعۡنَتِيٓ إِلَىٰ يَوۡمِ ٱلدِّينِ','transliteration'=>'Wa-inna \'alaika la\'nateee ilaa Yawmid Deen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>79,'arabic_text'=>'قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','transliteration'=>'Qaala Rabbi fa-anzirneee ilaa Yawmi yub\'asoon','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>80,'arabic_text'=>'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ','transliteration'=>'Qaala fa-innaka minal munzareen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>81,'arabic_text'=>'إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ','transliteration'=>'Ilaa Yawmil waqtil ma\'loom','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>82,'arabic_text'=>'قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ','transliteration'=>'Qaala fa-bi-\'izzatika la-ughwiyannahum ajma\'een','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>83,'arabic_text'=>'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ','transliteration'=>'Illaa \'ibaadaka minhumul mukhlaseen','page_number'=>457,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>84,'arabic_text'=>'قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ','transliteration'=>'Qaala falhaqq, walhaqqa aqool','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>85,'arabic_text'=>'لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِينَ','transliteration'=>'La-amla\'anna Jahannama minka Wa-mimman tabi\'aka minhum ajma\'een','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>86,'arabic_text'=>'قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ','transliteration'=>'Qul maaa as\'alukum \'alaihi min ajrinw Wa-maaa ana minal mutakallifeen','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>87,'arabic_text'=>'إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ','transliteration'=>'In huwa illaa zikrul lil\'aalameen','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>38,'ayah_number'=>88,'arabic_text'=>'وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ','transliteration'=>'Wa-lata\'lamunna naba-ahoo ba\'da heen','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            /* Surah 39: The Troops (Az-Zumar) */
            ['surah_id'=>39,'ayah_number'=>1,'arabic_text'=>'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','transliteration'=>'Tanzeelul Kitaabi minal laahil \'Azeezil Hakeem','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>2,'arabic_text'=>'إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ','transliteration'=>'Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi fa\'budil laaha mukhlisal lahud deen','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>3,'arabic_text'=>'أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ','transliteration'=>'Alaa lillaahid deenul khaalis; wallazeenat takhazoo min dooniheee awliyaaa\'a maa na\'buduhum illaa liyuqar-riboonaaa ilal laahi zulfaa; innal laaha yahkumu baina-hum fee maa hum feehi yakhtalifoon; innal laaha laa yahdee man huwa kaazibun kaffaar','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>4,'arabic_text'=>'لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ','transliteration'=>'Law araadal laahu aien yattakhiza waladal lastafaa mimmaa yakhluqu maa yashaaa\'; Subhaanahoo Huwal laahul Waahidul Qahhaar','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>5,'arabic_text'=>'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ','transliteration'=>'Khalaqas samaawaati wal-arda bilhaqq; yukawwirul laila \'alan nahaari Wa-yukawwirun nahaara \'alaal laili Wa-sakhkharash shamsa walqamara kulluny yajree li-ajalim musammaa; alaa Huwal \'Azeezul Ghaffaar','page_number'=>458,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>6,'arabic_text'=>'خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ','transliteration'=>'Khalaqakum min nafsinw waahidatin summa ja\'ala minhaa zawjahaa Wa-anzala lakum minal an\'aami samaani-yata azwaaj; yakhlu-qukum fee butooni ummahaatikum khalqam mim ba\'di khalqin fee zulumaatin salaas; zaalikumul laahu Rabbukum lahul mulk; laaa ilaaha illaa Huwa fa-annaa tusrafoon','page_number'=>459,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>7,'arabic_text'=>'إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'In takfuroo fa-innal laaha ghaniyyun \'ankum; Wa-laa yardaa li\'ibaadihil kufra Wa-in tashkuroo yardahu lakum; Wa-laa taziru waaziratunw wizra ukhraa; summa ilaa Rabikum marji\'ukum fa-yunabbi\'ukum bimaa kuntum ta\'maloon; innahoo \'aleemum bizaatis sudoor','page_number'=>459,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>8,'arabic_text'=>'۞ وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةٗ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادٗا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ','transliteration'=>'Wa-izaa massal insaana durrun da\'aa Rabbahoo muneeban ilaihi summa izaa khawwalahoo ni\'matam minhu nasiya maa kaana yad\'ooo ilaihi min qablu Wa-ja\'ala lillaahi andaadal liyudilla \'an sabeelih; qul tamatta\' bikufrika qaleelan innaka min Ashaabin Naar;','page_number'=>459,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>9,'arabic_text'=>'أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Amman huwa qaanitun aanaaa\'al laili saajidanw Wa-qaaa\'imai yahzarul Aakhirata Wa-yarjoo rahmata Rabbih; qul hal yastawil lazeena ya\'lamoona wallazeena laa ya\'lamoon; innamaa yatazakkaru ulul albaab','page_number'=>459,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>10,'arabic_text'=>'قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ','transliteration'=>'Qul yaa-\'ibaadil lazeena aamanut taqoo Rabbakum; lillazeena ahsanoo fee haazihid dunyaa hasanah; Wa-ardul laahi waasi\'ah; innamaa yuwaffas saabiroona ajrahum bighayri hisab','page_number'=>459,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>11,'arabic_text'=>'قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ','transliteration'=>'Qul inneee umirtu an a\'budal laaha mukhlisal lahud deen','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>12,'arabic_text'=>'وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Wa-umirtu li-an akoona awwalal muslimeen','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>13,'arabic_text'=>'قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ','transliteration'=>'Qul inneee akhaafu in \'asaitu Rabbee \'azaaba Yawmin \'azeem','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>14,'arabic_text'=>'قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصٗا لَّهُۥ دِينِي','transliteration'=>'Qulil laaha a\'budu mukhlisal lahoo deenee','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>15,'arabic_text'=>'فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ','transliteration'=>'Fa\'budoo maa shi\'tum min doonih; qul innal khaasireenal lazeena khasirooo anfusahum Wa-ahleehim yawmal qiyaamah; alaa zaalika huwal khusraanul mubeen','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>16,'arabic_text'=>'لَهُم مِّن فَوۡقِهِمۡ ظُلَلٞ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلٞۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ','transliteration'=>'Lahum min fawqihim zulalum minan Naari Wa-min tahtihim zulal; zaalika yukhaw-wiful laahu bihee \'ibaadah; yaa-\'ibaadi fattaqoon','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>17,'arabic_text'=>'وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ','transliteration'=>'Wallazeenaj tanabut Taaghoota aien ya\'budoohaa Wa-anaabooo ilal laahi lahumul bushraa; fabashshir \'ibaad','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>18,'arabic_text'=>'ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ','transliteration'=>'Allazeena yastami\'oonal qawla fayattabi\'oona ahsanah; ulaaa\'ikal lazeena hadaahumul laahu Wa-ulaaa\'ika hum ulul albaab','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>19,'arabic_text'=>'أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ','transliteration'=>'Afaman haqqa \'alaihi kalimatul \'azaab; afa-anta tunqizu man fin Naar','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>20,'arabic_text'=>'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفٞ مِّن فَوۡقِهَا غُرَفٞ مَّبۡنِيَّةٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ','transliteration'=>'Laakinil lazeenat taqaw Rabbahum lahum ghurafum min fawqihaa ghurafum mabniyyatun tajree min tahtihal anhaar; wa\'dal laah; laa yukhliful laahul mee\'aad','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>21,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ','transliteration'=>'Alam tara annal laaha anzala minas samaaa\'i maaa\'an fasalakahoo yanaabee\'a fil ardi summa yukhriju bihee zar\'am mukhtalifan alwaanuhoo summa yaheeju fatarahu musfarran summa yaj\'aluhoo hutaamaa; inna fee zaalika lazikraa li-ulil albaab','page_number'=>460,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>22,'arabic_text'=>'أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ فَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ','transliteration'=>'Afaman sharahal laahu sadrahoo lil-Islaami fahuwa \'alaa noorim mir Rabbih; fa-wailul lilqaasiyati quloobuhum min zikril laah; ulaaa\'ika fee dalaalim mubeen','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>23,'arabic_text'=>'ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ','transliteration'=>'Allahu nazzala ahsanal hadeesi Kitaabam mutashaa-biham masaaniya taqsha\'irru minhu juloodul lazeena yakhshawna Rabbahum summa taleenu julooduhum Wa-quloo-buhum ilaa zikril laah; zaalika hudal laahi yahdee bihee maien yashaaa\'; Wa-maien yudlilil laahu famaa lahoo min haad','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>24,'arabic_text'=>'أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ','transliteration'=>'Afamaien yattaqee biwaj-hihee sooo\'al \'azaabi Yawmal Qiyaamah; Wa-qeela lizzaali-meena zooqoo maa kuntum taksiboon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>25,'arabic_text'=>'كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ','transliteration'=>'Kazzabal lazeena min qablihim fa-ataahumul \'azaabu min haisu laa yash\'uroon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>26,'arabic_text'=>'فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Fa-azaaqahumul laahul khizya fil hayaatid dunyaa Wa-la\'azaabul Aakhirati akbar; law kaanoo ya\'lamoon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>27,'arabic_text'=>'وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Wa-laqad darabnaa linnaasi fee haazal Qur-aani min kulli masalil la\'allahum yatazakkaroon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>28,'arabic_text'=>'قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ','transliteration'=>'Qur-aanan \'Arabiyyan ghaira zee \'iwajil la\'allahum yattaqoon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>29,'arabic_text'=>'ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Darabal laahu masalar rajulan feehi shurakaaa\'u mutashaakisoona Wa-rajulan salamal lirajulin hal yastawi-yaani masalaa; alhamdu lillaah; bal aksaruhum laa ya\'lamoon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>30,'arabic_text'=>'إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ','transliteration'=>'Innaka maiyitunw Wa-inna-hum maiyitoon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>31,'arabic_text'=>'ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ','transliteration'=>'Summa innakum Yawmal Qiyaamati \'inda Rabbikum takhtasimoon','page_number'=>461,'juz_number'=>23,'hizb_number'=>46,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>32,'arabic_text'=>'۞ فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ','transliteration'=>'Faman azlamu mimman kazaba \'alal laahi Wa-kazzaba bissidqi iz jaaa\'ah; alaisa fee Jahannama maswal lilkaafireen','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>33,'arabic_text'=>'وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ','transliteration'=>'Wallazee jaaa\'a bissidqi Wa-saddaqa biheee ulaaa\'ika humul muttaqoon','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>34,'arabic_text'=>'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ','transliteration'=>'Lahum maa yashaaa\'oona \'inda Rabbihim; zaalika jazaaa\'ul muhsineen','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>35,'arabic_text'=>'لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ','transliteration'=>'Liyukaffiral laahu \'anhum aswa allazee \'amiloo Wa-yajziyahum ajrahum bi-ahsanil lazee kaano ya\'maloon','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>36,'arabic_text'=>'أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ','transliteration'=>'Alaisal laahu bikaafin \'abdahoo Wa-yukhawwi-foonaka billazeena min doonih; Wa-maien yudlilil laahu famaa lahoo min haad','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>37,'arabic_text'=>'وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ','transliteration'=>'Wa-maien yahdil laahu famaa lahoo min mudil; alai-sal laahu bi\'azeezin zin tiqaam','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>38,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ','transliteration'=>'Wa-la\'in sa-altahum man khalaqas samaawaati wal-arda la-yaqoolunal laah; qul afara\'aitum maa tad\'oona min doonil laahi in araadaniyal laahu bidurrin hal hunna kaashi-faatu durriheee aw araadanee birahmatin hal hunna mumsikaatu rahmatih; qul hasbiyal laahu \'alaihi yatawakkalul mutawakkiloon','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>39,'arabic_text'=>'قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ','transliteration'=>'Qul yaa qawmi\'maloo \'alaa makaanatikum innee \'aamilun fasawfa ta\'lamoon','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>40,'arabic_text'=>'مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ','transliteration'=>'Maien yaateehi \'azaabunien yukhzeehi Wa-yahillu \'alaihi \'azaabum muqeem','page_number'=>462,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>41,'arabic_text'=>'إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ','transliteration'=>'Innaa anzalnaa \'alaikal Kitaaba linnaasi bilhaqq; famanih tadaa falinafsihee Wa-man dalla fa-innamaa yadillu \'alaihaa Wa-maaa anta \'alaihim biwakeel','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>42,'arabic_text'=>'ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Allaahu yatawaffal anfusa heena mawtihaa wallatee lam tamut fee manaamihaa fa-yumsikul latee qadaa \'alaihal mawta Wa-yursilul ukhraaa ilaaa ajalim musammaa; inna fee zaalika la-Aayaatil liqawmaien yatafakkarroon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>43,'arabic_text'=>'أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ','transliteration'=>'Amit takhazoo min doonil laahi shufa\'aaa\'; qul awalaw kaanoo laa yamlikoona shai\'aw Wa-laa ya\'qiloon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>44,'arabic_text'=>'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Qul lillaahish shafaa\'atu jamee\'aa; lahoo mulkus samaawaati wal-ardi summa ilaihi turja\'oon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>45,'arabic_text'=>'وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ','transliteration'=>'Wa-izaa zukiral laahu wahdahush ma-azzat quloobul lazeena laa yu\'minoona bil-Aakhirati Wa-izaa zukiral lazeena min dooniheee izaa hum yastabshiroon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>46,'arabic_text'=>'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Qulil laahumma faatiras samaawaati wal-ardi \'Aalimal Ghaibi washshahaadati Anta tahkumu baina \'ibaadika fee maa kaanoo feehee yakhtalifoon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>47,'arabic_text'=>'وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ','transliteration'=>'Wa-law anna lillazeena zalamoo maa fil ardi jamee\'anw Wa-mislahoo ma\'ahoo laftadaw bihee min sooo\'il azaabi Yawmal Qiyaamah; Wa-badaa lahum minal laahi maa lam yakkoonoo yahtasiboon','page_number'=>463,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>48,'arabic_text'=>'وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-badaa lahum saiyiaatu maa kasaboo Wa-haaqa bihim maa kaanoo bihee yastahzi\'oon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>49,'arabic_text'=>'فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Fa-izaa massal insaana durrun da\'aanaa summa izaa khawwalnaahu ni\'matam minna qaala innamaaa ootee-tuhoo \'alaa \'ilm; bal hiya fitna-tunw Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>50,'arabic_text'=>'قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Qad qaalahal lazeena min qablihim famaaa aghnaa \'anhum maa kaanoo yaksiboon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>51,'arabic_text'=>'فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ','transliteration'=>'Fa-asaabahum saiyyi-aatu maa kasaboo; wallazeena zalamoo min haaa\'ulaaa\'i sa-yuseebuhum saiyyi-aatu maa kasaboo Wa-maa hum bimu\'jizeen','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>52,'arabic_text'=>'أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ','transliteration'=>'Awalam ya\'lamooo annal laaha yabsutur rizqa limai yashaaa\'u Wa-yaqdir; inna fee zaalika la-Aayaatil liqawmien yu\'minoon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>53,'arabic_text'=>'۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Qul yaa\'ibaadiyal lazeena asrafoo \'alaaa anfusihim laa taqnatoo mir rahmatil laah; innal laaha yaghfiruz zunooba jamee\'aa; innahoo Huwal Ghafoorur Raheem','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>54,'arabic_text'=>'وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ','transliteration'=>'Wa-aneebooo ilaa Rabbikum Wa-aslimoo lahoo min qabli ai yaatiyakumul \'azaabu summa laa tunsaroon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>55,'arabic_text'=>'وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ بَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ','transliteration'=>'Wattabi\'ooo ahsana maaa unzila ilaikum mir Rabbikum min qabli aien yaatiyakumal \'azaabu baghtatanw Wa-antum laa tash\'uroon','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>56,'arabic_text'=>'أَن تَقُولَ نَفۡسٞ يَٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ','transliteration'=>'An taqoola nafsuien yaahasrataa \'alaa maa farrattu fee jambil laahi Wa-in kuntu laminas saakhireen','page_number'=>464,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>57,'arabic_text'=>'أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ','transliteration'=>'Aw taqoola law annal laaha hadaanee lakuntu minal muttaqeen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>58,'arabic_text'=>'أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ','transliteration'=>'Aw taqoola heena taral \'azaaba law anna lee karratan fa-akoona minal muhsineen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>59,'arabic_text'=>'بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ','transliteration'=>'Balaa qad jaaa\'atka aayaatee fa-kazzabta bihaa Wa-stakbarta Wa-kunta minal kaafireen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>60,'arabic_text'=>'وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ','transliteration'=>'Wa-Yawmal Qiyaamati taral lazeena kazaboo \'alal laahi wujoohuhum muswaddah; alaisa fee Jahannama maswal lilmutakabbireen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>61,'arabic_text'=>'وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Wa-yunajjil laahul lazee-nat taqaw bimafaazatihim laa yamassuhumus sooo\'u Wa-laa hum yahzanoon','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>62,'arabic_text'=>'ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ','transliteration'=>'Allaahu khaaliqu kulli shai\'inw Wa-Huwa \'alaa kulli shai\'inw Wakeel','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>63,'arabic_text'=>'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Lahoo maqaaleedus sa-maawaati wal-ard; wallazeena kafaroo bi-ayaatil laahi ulaaa\'ika humul khaasiroon','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>64,'arabic_text'=>'قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ','transliteration'=>'Qul afaghairal laahi taamurooonneee a\'budu ayyuhal jaahiloon','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>65,'arabic_text'=>'وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Wa-laqad oohiya ilaika Wa-ilal lazeena min qablika la-in ashrakta la-yahbatanna \'amalu-ka Wa-latakoonanna minal khaasireen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>66,'arabic_text'=>'بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ','transliteration'=>'Balil laahha fa\'bud Wa-kum minash shaakireen','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>67,'arabic_text'=>'وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطۡوِيَّٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ','transliteration'=>'Wa-maa qadarul laaha haqqa qadrihee wal-ardu jamee-\'an qabdatuhoo Yawmal Qiyaamati wassamaawaatu matwiyyaatum biyameenih; Subhaanahoo Wa-Ta\'aalaa \'amma yushrikoon','page_number'=>465,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>68,'arabic_text'=>'وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامٞ يَنظُرُونَ','transliteration'=>'Wa-nufikha fis Soori fasa\'iqa man fis samaawaati Wa-man fil ardi illaa man shaa\'al lahu summa nufikha feehi ukhraa fa-izaa hum qiyaamuny yanzuroon','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>69,'arabic_text'=>'وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-ashraqatil ardu binoori Rabbihaa Wa-wudi\'al Kitaabu Wa-jeee\'a bin-nabiyyeena wash-shuhadaaa\'i Wa-qudiya bainahum bilhaqqi Wa-hum laa yuzlamoon','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>70,'arabic_text'=>'وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ','transliteration'=>'Wa-wuffiyat kullu nafsim maa \'amilat Wa-Huwa a\'lamu bimaa yaf\'aloon','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>71,'arabic_text'=>'وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ','transliteration'=>'Wa-seeqal lazeena kafaroo ilaa jahannama zumaraa hattaaa izaa jaaa\'oohaa futihat abwaabuhaa Wa-qaala lahum khazanatuhaaa alam ya\'tikum Rusulun minkum yatloona \'alaikum Aayaati Rabbikum Wa-yunziroonakum liqaaa\'a Yawmikum haazaa; qaaloo balaa Wa-laakin haqqat kalimatul \'azaabi \'alal kaafireen','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>72,'arabic_text'=>'قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ','transliteration'=>'Qeelad khuloo abwaaba jahannama khaalideena feeha fabi\'sa maswal mutakabbireen','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>73,'arabic_text'=>'وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ','transliteration'=>'Wa-seeqal lazeenat taqaw Rabbahum ilal Jannati zumaraa hattaaa izaa jaaa\'oohaa Wa-futihat abwaabuhaa Wa-qaala lahum khazanatuhaa salaamun \'alaikum tibtum fadkhuloohaa khaalideen','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>74,'arabic_text'=>'وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ','transliteration'=>'Wa-qaalull hamdulillaahil lazee sadaqanaa wa\'dahoo Wa-awrasanal arda natabaw wa-u minal jannati haisu nashaaa\'u fani\'ma ajrul \'aamileen','page_number'=>466,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>39,'ayah_number'=>75,'arabic_text'=>'وَتَرَى ٱلۡمَلَٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-taral malaaa\'ikata haaaffeena min hawlil \'Arshi yusabbihoona bihamdi Rabbihim Wa-qudiya bainahum bilhaqqi Wa-qeelal hamdu lillaahi Rabbil \'aalameen','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            /* Surah 40: The Forgiver (Ghafir) */
            ['surah_id'=>40,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>2,'arabic_text'=>'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ','transliteration'=>'Tanzeelul Kitaabi minal laahil Azeezil \'Aleem','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>3,'arabic_text'=>'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ','transliteration'=>'Ghaafiriz zambi Wa-qaabilit tawbi shadeedil \'iqaabi zit tawli laaa ilaaha illaa Huwa ilaihil maseer','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>4,'arabic_text'=>'مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ','transliteration'=>'Maa yujaadilu feee Aayaatil laahi illal lazeena kafaroo falaa yaghrurka taqallubuhum fil bilaad','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>5,'arabic_text'=>'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ','transliteration'=>'Kazzabat qablahum qawmu Noohinw wal-Ahzaabu min ba\'dihim Wa-hammat kullu ummatin bi-Rasoolihim li-ya\'khuzoohu Wa-jaadaloo bilbaatili li-yud-hidoo bihil haqqa fa-akhaztuhum fa-kaifa kaana \'iqaab','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>6,'arabic_text'=>'وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ','transliteration'=>'Wa-kazaalika haqqat Kalimatu Rabbika \'alal lazeena kafarooo annahum Ashaabun Naar','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>7,'arabic_text'=>'ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ','transliteration'=>'Allazeena yahmiloonal \'Arsha Wa-man hawlahoo yusabbihoona bihamdi Rabbihim Wa-yu\'minoona bihee Wa-yastaghfiroona lillazeena aamanoo Rabbanaa wasi\'ta kulla shai\'ir rahmatanw Wa-\'ilman faghfir lillazeena taaboo wattaba\'oo sabeelaka Wa-qihim \'azaabal Jaheem','page_number'=>467,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>8,'arabic_text'=>'رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Rabbannaa Wa-adkhilhum Jannaati \'adninil latee wa\'attahum Wa-man salaha min aabaaa\'ihim Wa-azwaajihim Wa-zurriyyaatihim; innaka Antal \'Azeezul Hakeem','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>9,'arabic_text'=>'وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Wa-qihimus saiyi-aat; Wa-man taqis saiyi-aati Yawma\'izin faqad rahimtah; Wa-zaalika huwal fawzul \'azeem','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>10,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ','transliteration'=>'Innal lazeena kafaroo yunaadawna lamaqtul laahi akbaru mim maqtikum anfusakum iz tud\'awna ilal eemaani fatakfuroon','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>11,'arabic_text'=>'قَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ','transliteration'=>'Qaaloo Rabbanaaa amat tanasnataini Wa-ahyaitanas nataini fa\'tarafnaa bizunoo-binaa fahal ilaa khuroojim min sabeel','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>12,'arabic_text'=>'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِيِّ ٱلۡكَبِيرِ','transliteration'=>'Zaalikum bi-annahooo izaa du\'iyal laahu wahdahoo kafartum Wa-ien yushrak bihee tu\'minoo; falhukmu lillaahil \'Aliyyil Kabeer','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>13,'arabic_text'=>'هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزۡقٗاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ','transliteration'=>'Huwal lazee yureekum Aayaatihee Wa-yunazzilu lakum minas samaaa\'i rizqaa; Wa-maa tatazakkaru illaa maien yuneeb','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>14,'arabic_text'=>'فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ','transliteration'=>'Fad\'ul laaha mukhliseena lahud deena Wa-law karihal kaafiroon','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>15,'arabic_text'=>'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ','transliteration'=>'Rafee\'ud darajaati zul \'Arshi yulqir rooha min amrihee \'alaa mai yashaaa\'u min \'ibaadihee liyunzira yawmat talaaq','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>16,'arabic_text'=>'يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءٞۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ','transliteration'=>'Yawma hum baarizoona laa yakhfaa \'alal laahi minhum shai; limanil mulkul Yawma lillaahil Waahidil Qahaar','page_number'=>468,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>17,'arabic_text'=>'ٱلۡيَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡيَوۡمَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ','transliteration'=>'Al-Yawma tujzaa kullu nafsim bimaa kasabat; laa zulmal Yawm; innal laaha saree\'ul hisaab','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>18,'arabic_text'=>'وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ مَا لِلظَّٰلِمِينَ مِنۡ حَمِيمٖ وَلَا شَفِيعٖ يُطَاعُ','transliteration'=>'Wa-anzirhum yawmal aazifati izil quloobu ladal hanaajiri kaazimeen; maa lizzaalimeena min hameeminw Wa-laa shafee\'ien yutaa\'','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>19,'arabic_text'=>'يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ','transliteration'=>'Ya\'lamu khaaa\'inatal a\'yuni Wa-maa tukhfis sudoor','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>20,'arabic_text'=>'وَٱللَّهُ يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ بِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ','transliteration'=>'Wallaahu yaqdee bilhaqq, wallazeena yad\'oona min doonihee laa yaqdoona bishai\'; innal laaha Huwas Samee\'ul Baseer','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>21,'arabic_text'=>'۞ أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ','transliteration'=>'Awalam yaseeroo fil ardi fa-yanzuroo kaifa kaana \'aaqibatul lazeena kaanoo min qablihim; kaanoo hum ashadda minhum quwwatanw Wa-aasaaran fil ardi fa-akhazahumul laahu bizunoobihim Wa-maa kaana lahum minal laahi minw waaq','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>22,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Zaalika bi-annahum kaanat taateehim Rusuluhum bilbaiyinaati fakafaroo fa-akhazahumul laah; innahoo qawiyyun shadeedul \'iqaab','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>23,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ','transliteration'=>'Wa-laqad arsalnaa Moosaa bi-Aayaatinaa Wa-sultaanim mubeen','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>24,'arabic_text'=>'إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ','transliteration'=>'Ilaa Fir\'awna Wa-Haamaana Wa-Qaaroona faqaaloo saahirun kazzaab','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>25,'arabic_text'=>'فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ','transliteration'=>'Falama jaaa\'ahum bil-haqqi min \'indinaa qaaluq tulooo abnaaa\'al lazeena aamanoo ma\'ahoo wastahyoo nisaaa\'ahum; Wa-maa kaidul kaafireena illaa fee dalaal','page_number'=>469,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>26,'arabic_text'=>'وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ','transliteration'=>'Wa-qaala Fir\'awnu zarooneee aqtul Moosaa walyad\'u Rabbahoo inneee akhaafu ai yubaddila deenakum aw aien yuzhira fil ardil fasaad','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>27,'arabic_text'=>'وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ','transliteration'=>'Wa-qaala Moosaaaa innee \'uztu bi-Rabbee Wa-Rabbikum min kulli mutakabbiril laayu\'minu bi Yawmil Hisaab','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>28,'arabic_text'=>'وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ','transliteration'=>'Wa-qaala rajulum mu\'minummin Aali Fir\'awna yaktumu eemaanahooo ataqtuloona rajulan aien yaqoola Rabbi-yal laahu Wa-qad jaaa\'akum bil baiyinaati mir Rabbikum Wa-iny yaku kaaziban fa\'alaihi kazibuh Wa-ien yaku saadiqaien yasibkum ba\'dul lazee ya\'idukum innal laaha laa yahdee man huwa musrifun kazzaab','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>29,'arabic_text'=>'يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ','transliteration'=>'Yaa-qawmi lakumul mulkul yawma zaahireena fil ardi famaien yansurunaa mim baasil laahi in jaaa\'anaa; qaala Fir\'awnu maaa ureekum illaa maaa araa Wa-maaa ahdeekum illaa sabeelar Rashaad','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>30,'arabic_text'=>'وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ','transliteration'=>'Wa-qaalal lazee aamana yaa-qawmi inneee akhaafu \'alaikum misla yawmil Ahzaab','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>31,'arabic_text'=>'مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ','transliteration'=>'Misla daabi qawmi Noohinw Wa-\'aadinw Wa-Samooda wallazeena mim ba\'dihim; Wa-mal laahu yureedu zulmal lil\'ibaad','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>32,'arabic_text'=>'وَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ','transliteration'=>'Wa-yaa-qawmi inneee akhaafu \'alaikum yawmat tanaad','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>33,'arabic_text'=>'يَوۡمَ تُوَلُّونَ مُدۡبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ','transliteration'=>'Yawma tuwalloona mud-bireena maa lakum minal laahi min \'aasim; Wa-maien yudlilil laahu famaa lahoo min haad','page_number'=>470,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>34,'arabic_text'=>'وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ','transliteration'=>'Wa-laqad jaaa\'akum Yoosufu min qablu bil-baiyyinaati famaa ziltum fee shakkim mimaa jaaa\'akum bihee hattaaa izaa halaka qultum laien yab-asal laahu mim ba\'dihee Rasoolaa; kazaalika yudillul laahu man huwa Musrifum murtaab','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>35,'arabic_text'=>'ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرٖ جَبَّارٖ','transliteration'=>'Allazeena yujaadiloona feee Aaayaatil laahi bighairi sultaanin ataahum kabura maqtan \'indal laahi Wa-\'indal lazeena aamanoo; kazaalika yatbahul laahu \'alaa kulli qalbi mutakabbirin jabbaar','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>36,'arabic_text'=>'وَقَالَ فِرۡعَوۡنُ يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحٗا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ','transliteration'=>'Wa-qaala Fir\'awnu yaa Haamaanub-ni lee sarhal la\'alleee ablughul asbaab','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>37,'arabic_text'=>'أَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ','transliteration'=>'Asbaabas samaawaati faattali\'a ilaaa ilaahi Moosaa Wa-innee la-azunnuhoo kaazibaa; Wa-kazaalika zuyyina li-Fir\'awna sooo\'u \'amalihee Wa-sudda \'anis sabeel; Wa-maa kaidu Fir\'awna illaa fee tabaab','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>38,'arabic_text'=>'وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ','transliteration'=>'Wa-qaalal lazeee aamana yaa-qawmit tabi\'ooni ahdikum sabeelar rashaad','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>39,'arabic_text'=>'يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ','transliteration'=>'Yaa-qawmi innamaa haazihil hayaatud dunyaa mataa\'unw Wa-innal Aakhirata hiya daarul qaraar','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>40,'arabic_text'=>'مَنۡ عَمِلَ سَيِّئَةٗ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ','transliteration'=>'Man \'amila saiyi\'atan falaa yujzaaa illaa mislahaa Wa-man \'amila saaliham min zakarin aw unsaa Wa-huwa mu\'minun fa-ulaaa\'ika yadkhuloonal Jannata yurzaqoona feehaa bighairi hisaab','page_number'=>471,'juz_number'=>24,'hizb_number'=>47,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>41,'arabic_text'=>'۞ وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ','transliteration'=>'Wa-yaa-qawmi maa leee ad\'ookum ilan najaati Wa-tad\'oonaneee ilan Naar','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>42,'arabic_text'=>'تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّٰرِ','transliteration'=>'Tad\'oonanee li-akfura billaahi Wa-ushrika bihee maa laisa lee bihee \'ilmunw Wa-ana ad\'ookum ilal \'Azeezil Ghaffaar','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>43,'arabic_text'=>'لَا جَرَمَ أَنَّمَا تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةٞ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ','transliteration'=>'Laa jarama annamaa tad\'oonanee ilaihi laisa lahoo da\'watun fid dunyaa Wa-laa fil Aakhirati Wa-anna maraddanaaa ilal laahi Wa-annal musrifeena hum Ashaabun Naar','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>44,'arabic_text'=>'فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ','transliteration'=>'Fasatazkuroona maaa aqoolu lakum; Wa-ufawwidu amreee ilal laah; innal laaha baseerum bil\'ibaad','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>45,'arabic_text'=>'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ','transliteration'=>'Fa-waqaahul laahu saiyyiaati maa makaroo Wa-haaqa bi Aali-Fir\'awna sooo\'ul \'azaab','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>46,'arabic_text'=>'ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ','transliteration'=>'An-Naaru yu\'radoona \'alaihaa ghuduwwanw Wa-\'ashiyyanw Wa-Yawma taqoomus Saa\'aatu adkhilooo Aala Fir\'awna ashaddal \'azaab','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>47,'arabic_text'=>'وَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ','transliteration'=>'Wa-iz yatahaaajjoona fin Naari fa-yaqoolud du\'afaaa\'u lillazeenas takbarooo innaa kunnaa lakum taba\'an fahal antum mughnoona annaa naseebam minan Naar','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>48,'arabic_text'=>'قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ','transliteration'=>'Qaalal lazeenas takbarooo innaa kullun feehaaa innal laaha qad hakama baynal \'ibaad','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>49,'arabic_text'=>'وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ','transliteration'=>'Wa-qaalal lazeena fin Naari likhazanati Jahannamad \'oo Rabbakum yukhaffif \'annaa yawmam minal \'azaab','page_number'=>472,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>50,'arabic_text'=>'قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ','transliteration'=>'Qaalooo awalam taku taateekum Rusulukum bilbaiyinaati qaaloo balaa\' qaaloo fad\'oo; Wa-maa du\'aaa\'ul kaafireena illaa fee dalaal','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>51,'arabic_text'=>'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ','transliteration'=>'Innaa lanansuru Rusulanaa wallazeena aamanoo fil hayaatid dunyaa Wa-Yawma yaqoomul ashhaad','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>52,'arabic_text'=>'يَوۡمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ','transliteration'=>'Yawma laa yanfa\'uz zaalimeena ma\'ziratuhum Wa-lahumul la\'natu Wa-lahum soooud daar','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>53,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ','transliteration'=>'Wa-laqad aatainaa Moosal hudaa Wa-awrasnaa Baneee Israaa-\'eelal Kitaab','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>54,'arabic_text'=>'هُدٗى وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ','transliteration'=>'Hudanw Wa-zikraa li-ulil albaab','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>55,'arabic_text'=>'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ','transliteration'=>'Fasbir inna wa\'dal laahi haqqunw wastaghfir lizambika Wa-sabbih bihamdi Rabbika bil\'ashiyyi wal-ibkaar','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>56,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ','transliteration'=>'Innal lazeena yujaadi-loona feee Aayaatil laahi bighairi sultaanin ataahum in fee sudoorihim illaa kibrum maa hum bibaaligheeh; fasta\'iz billaahi innahoo Huwas Samee\'ul Baseer','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>57,'arabic_text'=>'لَخَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Lakhalqus samaawaati wal-ardi akbaru min khalqin naasi Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>58,'arabic_text'=>'وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ','transliteration'=>'Wa-maa yastawil a\'maa walbaseeru wallazeena aamanoo Wa-\'amilus saalihaati Wa-lal museee\'; qaleelam maa tatazakkaroon','page_number'=>473,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>59,'arabic_text'=>'إِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞ لَّا رَيۡبَ فِيهَا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ','transliteration'=>'Innas Saa\'ata la-aatiyatul laa raiba feehaa Wa-laakinna aksaran naasi laa yu\'minoon','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>60,'arabic_text'=>'وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ','transliteration'=>'Wa-qaala Rabbukumud \'ooneee astajib lakum; innal lazeena yastakbiroona an \'ibaadatee sa-yadkhuloona jahannama daakhireen','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>61,'arabic_text'=>'ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ','transliteration'=>'Allaahul lazee ja\'ala lakumul laila littaskunoo feehi wannahaara mubsiraa; innal laaha lazoo fadlin \'alan naasi Wa-laakinna aksaran naasi laa yashkuroon','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>62,'arabic_text'=>'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ خَٰلِقُ كُلِّ شَيۡءٖ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ','transliteration'=>'Zaalikumul laahu Rabbukum khaaliqu kulli shai\'in; laaa ilaaha illaa Huwa fa-annaa tu\'fakoon','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>63,'arabic_text'=>'كَذَٰلِكَ يُؤۡفَكُ ٱلَّذِينَ كَانُواْ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ','transliteration'=>'Kazaalika yu\'fakul lazeena kaanoo bi-Aayaatil laahi yajhadoon','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>64,'arabic_text'=>'ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ','transliteration'=>'Allaahul lazee ja\'ala lakumul arda qaraaranw wassa-maaa\'a binaaa\'anw Wa-sawwarakum fa-ahsana suwarakum Wa-razaqakum minat taiyibaat; zaalikumul laahu Rabbukum fatabaarakal laahu Rabbul \'aalameen','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>65,'arabic_text'=>'هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Huwal Hayyu laaa ilaaha illaa Huwa fad\'oohu mukh liseena lahudeen; alhamdu lillaahi Rabbil \'aalameen','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>66,'arabic_text'=>'۞ قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ ٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qul innee nuheetu an a\'budal lazeena tad\'oona min doonil laahi lammaa jaaa\'a-niyal baiyinaatu mir Rabbee Wa-umirtu an uslima li-Rabbil \'aalameen','page_number'=>474,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>67,'arabic_text'=>'هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ يُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى وَلَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Huwal lazee khalaqakum min turaabin summa min nutfatin summa min \'alaqatin summa yukhrijukum tiflan summa litablughooo ashuddakum summa litakoonoo shuyookhaa; Wa-minkum maien yutawaffaa min qablu Wa-litablughooo ajalam musam-manw wa-la\'allakum ta\'qiloon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>68,'arabic_text'=>'هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','transliteration'=>'Huwal lazee yuhyee Wa-yumeetu fa-izaa qadaaa amran fa-innamaa yaqoolu lahoo kun fa-yakoon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>69,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ','transliteration'=>'Alam tara ilal lazeena yujaadiloona feee Aayaatil laahi annaa yusrafoon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>70,'arabic_text'=>'ٱلَّذِينَ كَذَّبُواْ بِٱلۡكِتَٰبِ وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ','transliteration'=>'Allazeena kazzaboo bil-Kitaabi Wa-bimaa arsalnaa bihee Rusulanaa fasawfa ya\'lamoon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>71,'arabic_text'=>'إِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ','transliteration'=>'Izil aghlaalu feee a\'naaqi-him wassalaasilu yushaboon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>72,'arabic_text'=>'فِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ','transliteration'=>'Fil hameemi summa fin Naari Yasjaroon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>73,'arabic_text'=>'ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ','transliteration'=>'Summaa qeela lahum ayna maa kuntum tushrikoon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>74,'arabic_text'=>'مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ','transliteration'=>'Min doonil laahi qaaloo dalloo \'annaa bal lam nakun nad\'oo min qablu shai\'aa; kazaalika yudillul laahul kaafireen','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>75,'arabic_text'=>'ذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ','transliteration'=>'Zaalikum bimaa kuntum tafrahoona fil ardi bighairil haqqi Wa-bimaa kuntum tamrahoon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>76,'arabic_text'=>'ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ','transliteration'=>'Udkhulooo abwaaba Jahannama khaalideena feehaa fabi\'sa maswal mutakabbireen','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>77,'arabic_text'=>'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ','transliteration'=>'Fasbir inna wa\'dal laahi haqq; fa-immaa nuriyannak ba\'dal lazee na\'i-duhum aw natawaffayannaka fa-ilainaa yurja\'oon','page_number'=>475,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>78,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ','transliteration'=>'Wa-laqad arsalnaa Rusulam min qablika minhum man qasasnaa \'alaika Wa-minhum mal lam naqsus \'alaik; Wa-maa kaana li-Rasoolin any yaatiya bi-Aayatin illaa bi-iznil laah; fa-izaa jaaa\'a amrul laahi qudiya bilhaqqi Wa-khasira hunaalikal mubtiloon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>79,'arabic_text'=>'ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ','transliteration'=>'Allaahul lazee ja\'ala lakumul an\'aama litarkaboo minhaa Wa-minhaa taakuloon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>80,'arabic_text'=>'وَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ','transliteration'=>'Wa-lakum feehaa manaafi\'u Wa-litablughoo \'alaihaa haajatan fee sudoorikum Wa-\'alaihaa Wa-\'alal fulki tuhmaloon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>81,'arabic_text'=>'وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ','transliteration'=>'Wa-yureekum Aayaatihee fa-ayya Aayaatil laahi tunkiroon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>82,'arabic_text'=>'أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Afalam yaseeroo fil ardi fa-yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; kaanoo aksara minhum Wa-ashadda quwwatanw Wa-aasaaran fil ardi famaaa aghnaa \'anhum maa kaanoo yaksiboon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>83,'arabic_text'=>'فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Falammaa jaaa\'at-hum Rusuluhum bilbaiyinaati farihoo bimaa \'indahum minal \'ilmi Wa-haaqa bihim maa kaanoo bihee yastahzi\'oon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>84,'arabic_text'=>'فَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ','transliteration'=>'Falammaa ra-aw baasanaa qaalooo aamannaa billaahi wahdahoo Wa-kafarnaa bimaa kunnaa bihee mushrikeen','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>40,'ayah_number'=>85,'arabic_text'=>'فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ','transliteration'=>'Falam yaku tanfa-\'uhum eemaanuhum lammaa ra-aw ba\'sana sunnatal laahil latee qad khalat fee \'ibaadihee Wa-khasira hunaalikal kaafiroon','page_number'=>476,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            /* Surah 41: Explained in Detail (Fussilat) */
            ['surah_id'=>41,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>2,'arabic_text'=>'تَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ','transliteration'=>'Tanzeelum Minar Rahmaanir Raheem','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>3,'arabic_text'=>'كِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ قُرۡءَانًا عَرَبِيّٗا لِّقَوۡمٖ يَعۡلَمُونَ','transliteration'=>'Kitaabun fussilat Aayaatuhoo Qur-aanan \'Arabiyyal liqawmien ya\'lamoon','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>4,'arabic_text'=>'بَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ','transliteration'=>'Basheeranw Wa-nazeeran fa-a\'rada aksaruhum fahum laa yasma\'oon','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>5,'arabic_text'=>'وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ','transliteration'=>'Wa-qaaloo quloobunaa feee akinnatim mimmaa tad\'oonaaa ilaihi Wa-feee aazaaninaa waqrunw Wa-mim baininaa Wa-bainika hijaabun fa\'mal innanaa \'aamiloon','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>6,'arabic_text'=>'قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ','transliteration'=>'Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaaa ilaahukum Ilaahunw Waahidun fastaqeemooo ilaihi wastaghfirooh; Wa-wailul lil-mushrikeen','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>7,'arabic_text'=>'ٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ','transliteration'=>'Allazeena laa yu\'toonaz Zakaata Wa-hum bil-Aakhirati hum kaafiroon','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>8,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ','transliteration'=>'Innal lazeena aamanoo Wa-\'amilus saalihaati lahum ajrun ghairu mamnoon','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>9,'arabic_text'=>'۞ قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ','transliteration'=>'Qul a\'innakum latakfuroona billazee khalaqal arda fee yawmaini Wa-taj\'aloona lahooo andaadaa; zaalika Rabbul \'aalameen','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>10,'arabic_text'=>'وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ','transliteration'=>'Wa-ja\'ala feehaa rawaa-siya min fawqihaa Wa-baaraka feehaa Wa-qaddara feehaaaa aqwaatahaa feee arba\'ati ayyaamin sawaaa\'al lissaaa\'ileen','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>11,'arabic_text'=>'ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ','transliteration'=>'Summas tawaaa ilas samaaa\'i Wa-hiya dukhaanun faqaala lahaa Wa-lil ardi\'tiyaaa taw\'an aw karhan qaalataaa atainaa taaa\'i\'een','page_number'=>477,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>12,'arabic_text'=>'فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَاۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَحِفۡظٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ','transliteration'=>'Faqadaahunna sab\'a samaawaatin fee yawmaini Wa-awhaa fee kulli samaaa\'in amarahaa; Wa-zaiyannassa maaa\'ad dunyaa bimasaabeeha Wa-hifzaa; zaalika taqdeerul \'Azeezil \'Aleem','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>13,'arabic_text'=>'فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ عَادٖ وَثَمُودَ','transliteration'=>'Fa-in a\'radoo faqul anzartukum saa\'iqatam misla saa\'iqati \'Aadinw Wa-Samood','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>14,'arabic_text'=>'إِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ','transliteration'=>'Iz jaaa\'at-humur Rusulu mim baini aydeehim Wa-min khalfihim allaa ta\'budooo illal laaha qaaloo law shaaa\'a Rabunaa la-anzala malaaa-\'ikatan fa-innaa bimaaa ursiltum bihee kaafiroon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>15,'arabic_text'=>'فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ','transliteration'=>'Fa-ammaa \'Aadun fastak-baroo fil ardi bighairul haqqi Wa-qaaloo man ashaddu minnaa quwwatan awalam yaraw annal laahal lazee khalaqahum Huwa ashaddu minhum quwwatanw Wa-kaanoo bi-Aayaatinaa yajhadoon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>16,'arabic_text'=>'فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ','transliteration'=>'Fa-arsalnaa \'alaihim reehan sarsaran feee ayyaamin nahisaatil linuzeeqahum \'azaabal khizyi fil hayaatid dunyaa Wa-la\'azaabul Aakhirati akhzaa Wa-hum laa yunsaroon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>17,'arabic_text'=>'وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Wa-ammaa Samoodu fahadinaahum fastahabbul \'ama \'alal huda fa-akhazathum saa\'iqatul \'azaabil hooni bimaa kaanoo yaksiboon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>18,'arabic_text'=>'وَنَجَّيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ','transliteration'=>'Wa-najjainal lazeena aamanoo Wa-kaanoo yattaqoon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>19,'arabic_text'=>'وَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ','transliteration'=>'Wa-yawma yuhsharu a\'daaa\'ul laahi ilan Naari fahum yooza\'oon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>20,'arabic_text'=>'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Hattaaa izaa maa jaaa\'oohaa shahida \'alaihim samu\'uhum Wa-absaaruhum Wa-julooduhum bimaa kaanoo ya\'maloon','page_number'=>478,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>21,'arabic_text'=>'وَقَالُواْ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَيۡنَاۖ قَالُوٓاْ أَنطَقَنَا ٱللَّهُ ٱلَّذِيٓ أَنطَقَ كُلَّ شَيۡءٖۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةٖ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-qaaloo lijuloodihim lima shahittum \'alainaa qaaloo antaqanal laahul lazeee antaqa kulla shai\'inw Wa-Huwa khalaqakum awwala marratinw Wa-ilaihi turja\'oon','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>22,'arabic_text'=>'وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرٗا مِّمَّا تَعۡمَلُونَ','transliteration'=>'Wa-maa kuntum tastatiroona aien yashhada \'alaikum sam\'ukum Wa-laaa absaarukum Wa-laa juloodukum Wa-laakin zanantum annal laaha laa ya\'lamu kaseeram mimmaa ta\'maloon','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>23,'arabic_text'=>'وَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ','transliteration'=>'Wa-zaalikum zannukumul lazee zanantum bi-Rabbikum ardaakum fa-asbahtum minal khaasireen','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>24,'arabic_text'=>'فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوٗى لَّهُمۡۖ وَإِن يَسۡتَعۡتِبُواْ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ','transliteration'=>'Fa-ien yasbiroo fan-naaru maswal lahum Wa-ien yasta\'tiboo famaa hum minal mu\'tabeen','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>25,'arabic_text'=>'۞ وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ','transliteration'=>'Wa-qaiyadnaa lahum quranaaa\'a fazaiyyanoo lahum maa baina aideehim Wa-maa khalfahum Wa-haqqa \'alaihimul qawlu feee umamin qad khalat min qablihim minal jinni wal-insi innahum kaanoo khaasireen','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>26,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ','transliteration'=>'Wa-qaalal lazeena kafaroo laa tasma\'oo lihaazal Quraani walghaw feehi la\'allakum taghliboon','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>27,'arabic_text'=>'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابٗا شَدِيدٗا وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ','transliteration'=>'Falanuzeeqannal lazeena kafaroo \'azaaban shadeedanw Wa-lanajziyannahum aswal lazee kaanoo ya\'maloon','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>28,'arabic_text'=>'ذَٰلِكَ جَزَآءُ أَعۡدَآءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ','transliteration'=>'Zaalika jazaaa\'u a\'daaa\'il laahin Naaru lahum feehaa daarul khuld, jazaaa\'am bimaa kaanoo bi-aayaatinaa yajhadoon','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>29,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ','transliteration'=>'Wa-qaalal lazeena kafaroo Rabbanaaa arinal lazaini adal-laanaa minal jinni wal-insi naj\'alhumaa tahta aqdaaminaa liyakoonaa minal asfaleen','page_number'=>479,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>30,'arabic_text'=>'إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ ٱلَّتِي كُنتُمۡ تُوعَدُونَ','transliteration'=>'Innal lazeena qaaloo Rabbunal laahu summas taqaamoo tatanazzalu \'alaihimul malaaa-\'ikatu allaa takhaafoo Wa-laa tahzanoo Wa-abshiroo bil-Jannnatil latee kuntum too\'adoon','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>31,'arabic_text'=>'نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّعُونَ','transliteration'=>'Nahnu awliyaaa\'ukum fil hayaatid dunyaa Wa-fil Aakhirati Wa-lakum feehaa maa tashtaheee anfusukum Wa-lakum feehaa ma tadda\'oon','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>32,'arabic_text'=>'نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ','transliteration'=>'Nuzulam min Ghafoorir Raheem','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>33,'arabic_text'=>'وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Wa-man ahsanu qawlam mimman da\'aaa ilal laahi Wa-\'amila saalihanw Wa-qaala innanee minal muslimeen','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>34,'arabic_text'=>'وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ','transliteration'=>'Wa-laa tastawil hasanatu Wa-las saiyi\'ah; idfa\' billatee hiya ahsanu fa\'izal lazee bainaka Wa-bainahoo \'adaawatun ka\'annahoo waliyun hameem','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>35,'arabic_text'=>'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ','transliteration'=>'Wa-maa yulaqqaahaaa illal lazeena sabaroo Wa-maa yulaqqaahaaa illaa zoo hazzin \'azeem','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>36,'arabic_text'=>'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Wa-immaa yanzaghannaka minash Shaitaani nazghun fasta\'iz billaahi innahoo Huwas Samee\'ul \'Aleem','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>37,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِ ٱلَّيۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ','transliteration'=>'Wa-min Aayaatihil lailu wannahaaru washshamsu walqamar; laa tasjudoo lishshamsi Wa-laa lilqamari wasjudoo lillaahil lazee khala-qahunna in kuntum iyyaahu ta\'budoon','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>38,'arabic_text'=>'فَإِنِ ٱسۡتَكۡبَرُواْ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيۡلِ وَٱلنَّهَارِ وَهُمۡ لَا يَسۡـَٔمُونَ','transliteration'=>'Fa-inis takbaroo fallazee-na \'inda Rabbika yusabbihoona lahoo billaili wannnahaari Wa-hum laa yas\'amoon','page_number'=>480,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>true],
            ['surah_id'=>41,'ayah_number'=>39,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Wa-min Aayaatiheee annaka taral arda khaashi\'atan fa-izaaa anzalna \'alaihal maaa\'ah tazzat Wa-rabat; innal lazeee ahyaahaa lamuhiyil mawtaa; innahoo \'alaa kulli shai-in Qadeer','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>40,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ أَفَمَن يُلۡقَىٰ فِي ٱلنَّارِ خَيۡرٌ أَم مَّن يَأۡتِيٓ ءَامِنٗا يَوۡمَ ٱلۡقِيَٰمَةِۚ ٱعۡمَلُواْ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٌ','transliteration'=>'Innal lazeena yulhidoona feee Aayaatina laa yakhfawna \'alainaa\' afamai yulqaa fin Naari khayrun am maien yaateee aaminai Yawmal Qiyaamah; i\'maloo ma shi\'tum innahoo bimaa ta\'maloona Baseer','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>41,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ','transliteration'=>'Inna Lazeena kafaroo biz-Zikri lammaa jaa\'ahum Wa-innahoo la-Kitaabun \'Azeez','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>42,'arabic_text'=>'لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِيلٞ مِّنۡ حَكِيمٍ حَمِيدٖ','transliteration'=>'Laa yaateehil baatilu mim baini yadaihi Wa-laa min khalfihee tanzeelum min Hakeemin Hameed','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>43,'arabic_text'=>'مَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ','transliteration'=>'Maa yuqaalu laka illaa maa qad qeela lir-Rusuli min qablik; inna Rabbaka lazoo maghfiratinw Wa-zoo \'iqaabin aleem','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>44,'arabic_text'=>'وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيّٗا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ ءَا۬عۡجَمِيّٞ وَعَرَبِيّٞۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ وَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ','transliteration'=>'Wa-law ja\'alnaahu Qur-aanan A\'jamiyyal laqaaloo law-laa fussilat Aayaatuhoo \'a-A\'jamiyyunw Wa-\'Arabiyy; qul huwa lillazeena aamanoo hudanw Wa-shifaaa\'unw wallazeena la yu\'minoona feee aazaanihim waqrunw Wa-huwa \'alaihim \'amaa; ulaaa\'ika yunaadawna mim maakaanim ba\'eed','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>45,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ','transliteration'=>'Wa-laqad aatainaa Moosal Kitaaba fakhtulifa fee; Wa-lawlaa Kalimatun sabaqat mir Rabbika laqudiya bainahum; Wa-innahum lafee shakkim minhu mureeb','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>46,'arabic_text'=>'مَّنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّٰمٖ لِّلۡعَبِيدِ','transliteration'=>'Man \'amila salihan falinafsihee Wa-man asaaa\'a fa\'alaihaa; wamaa rabbuka bizallaamil lil-\'abeed','page_number'=>481,'juz_number'=>24,'hizb_number'=>48,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>47,'arabic_text'=>'۞ إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتٖ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ شُرَكَآءِي قَالُوٓاْ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٖ','transliteration'=>'Ilaihi yuraddu \'ilmus Saaa\'ah; Wa-maa takhruju min samaraatim min akmaamihaa Wa-maa tahmilu min unsaa Wa-laa tada\'u illaa bi\'ilmih; Wa-Yawma yunaadeehim aina shurakaaa\'ee qaalooo aazannaaka maa minnaa min shaheed','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>48,'arabic_text'=>'وَضَلَّ عَنۡهُم مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصٖ','transliteration'=>'Wa-dalla \'anhum maa kaanoo yad\'oona min qablu Wa-zannoo maa lahum mim mahees','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>49,'arabic_text'=>'لَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٞ قَنُوطٞ','transliteration'=>'Laa yas\'amul insaanu min du\'aaa\'il khairi Wa-im massa hush-sharru fa-ya\'oosun qanoot','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>50,'arabic_text'=>'وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةٗ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّجِعۡتُ إِلَىٰ رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ وَلَنُذِيقَنَّهُم مِّنۡ عَذَابٍ غَلِيظٖ','transliteration'=>'Wa-la-in azaqnaahu rahmatam minnaa mim ba\'di dar-raaa\'a massat-hu la-yaqoolanna haazaa lee Wa-maaa azunnus Saa\'ata qaaa\'imatanw Wa-la\'in ruji\'tu ilaa Rabbeee inna lee \'indahoo lalhusnaa; falanu-nabbi\'annal lazeena kafaroo bimaa \'amiloo Wa-lanuzeeqan-nahum min \'azaabin ghaleez','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>51,'arabic_text'=>'وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٖ','transliteration'=>'Wa-izaaa an\'amnaa \'alal insaani a\'rada Wa-na-aa bijaani-bihee Wa-izaa massahush sharru fazoo du\'aaa\'in \'areed','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>52,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدٖ','transliteration'=>'Qul araaitum in kaana min \'indil laahi summa kafar-tum bihee man adallu mimman huwa fee shiqaqim ba\'eed','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>53,'arabic_text'=>'سَنُرِيهِمۡ ءَايَٰتِنَا فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ','transliteration'=>'Sanureehim Aayaatinaa fil aafaaqi Wa-feee anfusihim hattaa yatabaiyana lahum annahul haqq; awa-lam yakfi bi-Rabbika annahoo \'alaa kulli shai-in Shaheed','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>41,'ayah_number'=>54,'arabic_text'=>'أَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءٖ مُّحِيطُۢ','transliteration'=>'Alaaa innahum fee miryatim mil liqaaa\'i Rabbihim; alaaa innahoo bikulli shai\'im muheet','page_number'=>482,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            /* Surah 42: The Consultation (Ash-Shuraa) */
            ['surah_id'=>42,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>2,'arabic_text'=>'عٓسٓقٓ','transliteration'=>'Ayyyn-Seeen-Qaaaf','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>3,'arabic_text'=>'كَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Kazaalika yooheee ilaika Wa-ilal lazeena min qablikal laahul \'Azeezul Hakeem','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>4,'arabic_text'=>'لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ','transliteration'=>'Lahoo maa fis samaa-waati Wa-maa fil ardi Wa-Huwal \'Aliyul \'Azeem','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>5,'arabic_text'=>'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي ٱلۡأَرۡضِۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Takaadus samaawaatu yatafattarna min fawqihinn; walmalaaa\'ikatu yusabbihoona bihamdi Rabbihim Wa-yastaghfiroona liman fil ard; alaaa innal laaha huwal Ghafoorur Raheem','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>6,'arabic_text'=>'وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ','transliteration'=>'Wallazeenat takhazoo min dooniheee awliyaaa\'al laahu hafeezun \'alaihim Wa-maaa anta \'alaihim biwakeel','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>7,'arabic_text'=>'وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ قُرۡءَانًا عَرَبِيّٗا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ يَوۡمَ ٱلۡجَمۡعِ لَا رَيۡبَ فِيهِۚ فَرِيقٞ فِي ٱلۡجَنَّةِ وَفَرِيقٞ فِي ٱلسَّعِيرِ','transliteration'=>'Wa-kazaalika awhainaaa ilaika Qur-aanan \'Arabiyyal litunzira Ummal Quraa Wa-man hawlahaa Wa-tunzira Yawmal Jam\'i laa raiba feeh; fareequn fil jannati Wa-fareequn fis sa\'eer','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>8,'arabic_text'=>'وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِيّٖ وَلَا نَصِيرٍ','transliteration'=>'Wa-law shaaa\'al laahu laja\'alahum ummatanw waahi-datanw walaakien yudkhilu maien yashaaa\'u fee rahmatih; waz-zaalimoona maa lahum minw waliyyinw Wa-laa naseer','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>9,'arabic_text'=>'أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Amit takhazoo min dooniheee awliyaaa\'a fallaahu Huwal Waliyyu Wa-Huwa yuhyil mawtaa Wa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>10,'arabic_text'=>'وَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءٖ فَحُكۡمُهُۥٓ إِلَى ٱللَّهِۚ ذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ','transliteration'=>'Wa-makh talaftum feehi min shai\'in fahukmuhooo ilal laah; zaalikumul laahu Rabbee \'alaihi tawakkaltu Wa-ilaihi uneeb','page_number'=>483,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>11,'arabic_text'=>'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ','transliteration'=>'Faatirus samaawaati wal-ard; ja\'ala lakum min anfusikum azwaajanw Wa-minal an\'aami azwaajai yazra\'ukum feeh; laisa kamislihee shai\'unw Wa-Huwas Samee\'ul Baseer','page_number'=>484,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>12,'arabic_text'=>'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Lahoo maqaaleedus samaawaati wal-ardi yabsutur rizqa limaien yashaaa\'u Wa-yaqdir; innahoo bikulli shai\'in \'Aleem','page_number'=>484,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>13,'arabic_text'=>'۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ','transliteration'=>'Shara\'a lakum minad deeni maa wassaa bihee Noohanw wallazeee awhainaaa ilaika Wa-maa wassainaa biheee Ibraaheema Wa-Moosa Wa-\'Eesaaa an aqeemud deena Wa-laa tatafarraqoo feeh; kabura \'alal mushrikeena maa tad\'oohum ilaih; Allaahu yajtabee ilaihi mai yashaaa\'u Wa-yahdeee ilaihi mai yuneeb','page_number'=>484,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>14,'arabic_text'=>'وَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰٓ أَجَلٖ مُّسَمّٗى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ أُورِثُواْ ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ','transliteration'=>'Wa-maa tafarraqooo illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; Wa-law-laa Kalimatun sabaqat mir Rabbika ilaaa ajalim musammal laqudiya bainahum; Wa-innal lazeena oorisul Kitaaba mim ba\'dihim lafee shakkim minhu mureeb','page_number'=>484,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>15,'arabic_text'=>'فَلِذَٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٖۖ وَأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ لَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ','transliteration'=>'Falizaalika fad\'u wastaqim kamaaa umirta Wa-laa tattabi\' ahwaaa\'ahum Wa-qul aamantu bimaaa anzalal laahu min Kitaab, Wa-umirtu li-a\'dila bainakum Allaahu Rabbunaa Wa-Rabbukum lanaaa a\'maa-lunaa Wa-lakum a\'maalukum laa hujjata bainanaa Wa-baina-kumul laahu yajma\'u bainanaa Wa-ilaihil maseer','page_number'=>484,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>16,'arabic_text'=>'وَٱلَّذِينَ يُحَآجُّونَ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَبٞ وَلَهُمۡ عَذَابٞ شَدِيدٌ','transliteration'=>'Wallazeena yuhaaajjoona fil laahi mim ba\'di mas tujeeba lahoo hujjatuhum daahidatun \'inda Rabbihim Wa-\'alaihim ghadabunw Wa-lahum \'azaabun shadeed','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>17,'arabic_text'=>'ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ','transliteration'=>'Allahul lazeee anzalal Kitaaba bilhaqqi wal-Meezaan; Wa-ma yudreeka la\'allas Saa\'ata qareeb','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>18,'arabic_text'=>'يَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِي ٱلسَّاعَةِ لَفِي ضَلَٰلِۭ بَعِيدٍ','transliteration'=>'Yasta\'jilu bihal lazeena laa yu\'minoona bihaa wallazeena aamanoo mushfiqoona minhaa Wa-ya\'lamoona annahal haqq; alaaa innal lazeena yumaaroona fis Saa\'ati lafee dalaalin ba\'eed','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>19,'arabic_text'=>'ٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ','transliteration'=>'Allahu lateefum bi\'ibaadihee yarzuqu maien yashaaa\'u Wa-Huwal Qawiyyul \'Azeez','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>20,'arabic_text'=>'مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِن نَّصِيبٍ','transliteration'=>'Man kaana yureedu harsal Aakhirati nazid lahoo fee harsihee Wa-man kaana yureedu harsad dunyaa nu\'tihee minhaa Wa-maa lahoo fil Aakhirati min naseeb','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>21,'arabic_text'=>'أَمۡ لَهُمۡ شُرَكَٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ٱلدِّينِ مَا لَمۡ يَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِيَ بَيۡنَهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Am lahum shurakaaa\'u shara\'oo lahum minad deeni maa lam ya\'zan bihil laah; Wa-law-laa kalimatul fasli laqudiya bainahum; Wa-innaz zaalimeena lahum \'azaabun aleem','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>22,'arabic_text'=>'تَرَى ٱلظَّٰلِمِينَ مُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ','transliteration'=>'Taraz zaalimeena mushfiqeena mimmaa kasaboo Wa-huwa waaqi\'um bihim; wallazeena aamanoo Wa-\'amilus saalihaati fee rawdaatil jannaati lahum maa yashaaa\'oona \'inda Rabbihim; zaalika huwal fadlul kabeer','page_number'=>485,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>23,'arabic_text'=>'ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورٞ شَكُورٌ','transliteration'=>'Zaalikal lazee yubash-shirul laahu \'ibaadahul lazeena aamanoo Wa-\'amilus saalihaat; qul laaa as\'alukum \'alaihi ajran illal mawaddata fil qurbaa; Wa-mai yaqtarif hasanatan nazid lahoo feehaa husnaa; innal laaha Ghafoorun Shakoor','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>24,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Am yaqooloonaf tara \'alal laahi kaziban fa-ien yasha\' illaahu yakhtim \'alaa qalbik; Wa-yamhul laahul baatila Wa-yuhiqqul haqqa bi-Kalimaatih; innahoo \'Aleemun bizaatis sudoor','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>25,'arabic_text'=>'وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ','transliteration'=>'Wa-Huwal lazee yaqbalut tawbata \'an \'ibaadihee Wa-ya\'foo \'anis saiyiaati Wa-ya\'lamu maa taf\'aloon','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>26,'arabic_text'=>'وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابٞ شَدِيدٞ','transliteration'=>'Wa-yastajeebul lazeena aamanoo Wa-\'amilu saalihaati Wa-yazeeduhum min fadlih; wal-kaafiroona lahum \'azaabun shadeed','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>27,'arabic_text'=>'۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ','transliteration'=>'Wa-law basatal laahur rizqa li\'ibaadihee labaghaw fil ardi Wa-laakiny yunazzilu biqadarim maa yashaaa\'; innahoo bi\'ibaadihee Khabeerun Baseer','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>28,'arabic_text'=>'وَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ','transliteration'=>'Wa-Huwal lazee yunazzilul ghaisa min ba\'di maa qanatoo Wa-yanshuru rahmatah; Wa-Huwal Waliyyul Hameed','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>29,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٖۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرٞ','transliteration'=>'Wa-min Aayaatihee khalqus samaawaati wal-ardi Wa-maa bassa feehimaa min daaabbah; Wa-Huwa \'alaa jam\'ihim izaa yashaaa\'u Qadeer','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>30,'arabic_text'=>'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ','transliteration'=>'Wa-maaa asaabakum min museebatin fabimaa kasabat aydeekum Wa-ya\'foo \'an kaseer','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>31,'arabic_text'=>'وَمَآ أَنتُم بِمُعۡجِزِينَ فِي ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ','transliteration'=>'Wa-maaa antum bimu\'jizeena fil ardi Wa-maa lakum min doonil laahi minw Wa-liyyinw Wa-laa naseer','page_number'=>486,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>32,'arabic_text'=>'وَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ','transliteration'=>'Wa-min Aayaatihil ja waarifil bahri kal-a\'lam','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>33,'arabic_text'=>'إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ','transliteration'=>'Iny yashaaa yuskinir reeha fa-yazlalna rawaakida \'alaa zahrihi; inna fee zaalika la-Aayaatil likulli sabbaarin shakoor','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>34,'arabic_text'=>'أَوۡ يُوبِقۡهُنَّ بِمَا كَسَبُواْ وَيَعۡفُ عَن كَثِيرٖ','transliteration'=>'Aw yoobiqhunna bimaa kasaboo Wa-ya\'fu \'an kaseer','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>35,'arabic_text'=>'وَيَعۡلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٖ','transliteration'=>'Wa-ya\'lamal lazeena yujaadiloona feee Aayaatinaa maa lahum min mahees','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>36,'arabic_text'=>'فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','transliteration'=>'Famaa ooteetum min shai\'in famataa\'ul hayaatid dunyaa Wa-maa \'indal laahi khairunw Wa-abqaa lillazeena aamanoo Wa-\'alaa Rabbihim yatawakkaloon','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>37,'arabic_text'=>'وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ','transliteration'=>'Wallazeena yajtaniboona kabaaa\'iral ismi wal-fawaahisha Wa-izaa maa ghadiboo hum yaghfiroon','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>38,'arabic_text'=>'وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','transliteration'=>'Wallazeenas tajaaboo li-Rabbihim Wa-aqaamus Salaata Wa-amruhum shooraa bainahum Wa-mimmaa razaqnaahum yunfiqoon','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>39,'arabic_text'=>'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ','transliteration'=>'Wallazeena izaa asaabahumul baghyu hum yantasiroon','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>40,'arabic_text'=>'وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-jazaaa\'u saiyi\'atin saiyi\'atum misluha faman \'afaa Wa-aslaha fa-ajruhoo \'alal laah; innahoo laa yuhibbuz zaalimeen','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>41,'arabic_text'=>'وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ','transliteration'=>'Wa-lamanin tasara ba\'da zulmihee fa-ulaaa\'ika maa \'alaihim min sabeel','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>42,'arabic_text'=>'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Innamas sabeelu \'alal lazeena yazlimoonan naasa Wa-yabghoona fil ardi bighairil haqq; ulaaa\'ika lahum \'azaabun aleem','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>43,'arabic_text'=>'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ','transliteration'=>'Wa-laman sabara Wa-ghafara inna zaalika lamin \'azmil umoor','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>44,'arabic_text'=>'وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيّٖ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدّٖ مِّن سَبِيلٖ','transliteration'=>'Wa-maien yudli lillaahu famaa lahoo minw waliyyin min ba\'dih; Wa-taraz zaalimeena lammaa ra-awul \'azaaba yaqooloona hal ilaa maraddin min sabeel','page_number'=>487,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>45,'arabic_text'=>'وَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرۡفٍ خَفِيّٖۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ','transliteration'=>'Wa-taraahum yu\'radoona \'alaihaa khaashi\'eena minaz zulli yanzuroona min tarfin khaifiyy; Wa-qaalal lazeena aamanooo innal khaasireenal lazeena khasirooo anfusahum Wa-ahleehim Yawmal Qiyaamah; alaaa innaz zaalimeena fee \'azaabin muqeem','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>46,'arabic_text'=>'وَمَا كَانَ لَهُم مِّنۡ أَوۡلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ','transliteration'=>'Wa-maa kaana lahum min awliyaaa\'a yansuroonahum min doonil laah; Wa-mai yudlilil laahu famaa lahoo min sabeel','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>47,'arabic_text'=>'ٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ','transliteration'=>'Istajeeboo li-Rabbikum min qabli aien yaatiya Yawmul laa maradda lahoo min Allah; maa lakum min malja\'-ien yawma\'izinw Wa-maa lakum min nakeer','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>48,'arabic_text'=>'فَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ وَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ','transliteration'=>'Fa-in a\'radoo famaaa arsalnaaka \'alaihim hafeezan in \'alaika illal balaagh; Wa-innaaa izaaa azaqnal insaana minnaa rahmatan fariha bihaa Wa-in tusibhum saiyi\'atun bimaa qaddamat aydeehim fa-innal insaana kafoor','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>49,'arabic_text'=>'لِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ','transliteration'=>'Lillaahi mulkus samaawaati wal-ard; yakhluqu maa yashaaa\'; yahabu limai yashaaa\'u inaasanw Wa-yahabu limai yashaaa\'uz zukoor','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>50,'arabic_text'=>'أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانٗا وَإِنَٰثٗاۖ وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمٞ قَدِيرٞ','transliteration'=>'Aw yuzawwijuhum zukraananw Wa-inaasanw Wa-yaj\'alu mai yashaaa\'u \'aqeemaa; innahoo \'Aleemun Qadeer','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>51,'arabic_text'=>'۞ وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ رَسُولٗا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمٞ','transliteration'=>'Wa-maa kaana libasharin aien yukallimahul laahu illaa wahyan aw minw waraaa\'i hijaabin aw yursila Rasoolan fa-yoohiya bi-iznihee maa yashaaa\'; innahoo \'Aliyyun Hakeem','page_number'=>488,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>52,'arabic_text'=>'وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Wa-kazaalika awhainaaa ilaika roohan min amrinaa; maa kunta tadree mal Kitaabu Wa-lal eemaanu Wa-laakin ja\'alnaahu nooran nahdee bihee man nashaaa\'u min \'ibaadinaa; Wa-innaka latahdeee ilaaa Saraatin Mustaqeem','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>42,'ayah_number'=>53,'arabic_text'=>'صِرَٰطِ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ','transliteration'=>'Siraatil laahil lazee lahoo maa fis samaawaati Wa-maa fil ard; alaaa ilal laahi taseerul umoor','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            /* Surah 43: The Ornaments of Gold (Az-Zukhruf) */
            ['surah_id'=>43,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>2,'arabic_text'=>'وَٱلۡكِتَٰبِ ٱلۡمُبِينِ','transliteration'=>'Wal-Kitaabil Mubeen','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>3,'arabic_text'=>'إِنَّا جَعَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'Innaa ja\'alnaahu Quraanan \'Arabiyyal la\'allakum ta\'qiloon','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>4,'arabic_text'=>'وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ','transliteration'=>'Wa-innahoo feee Ummil Kitaabi Ladainaa la\'aliyyun hakeem','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>5,'arabic_text'=>'أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ','transliteration'=>'Afa-nadribu \'ankumuz Zikra safhan an kuntum qawman musrifeen','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>6,'arabic_text'=>'وَكَمۡ أَرۡسَلۡنَا مِن نَّبِيّٖ فِي ٱلۡأَوَّلِينَ','transliteration'=>'Wa-kam arsalnaa min Nabiyyin fil awwaleen','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>7,'arabic_text'=>'وَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-maa ya\'teehim min Nabiyyin illaa kaanoo bihee yastahzi\'oon','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>8,'arabic_text'=>'فَأَهۡلَكۡنَآ أَشَدَّ مِنۡهُم بَطۡشٗا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِينَ','transliteration'=>'Fa-ahlaknaaa ashadda minhum batshanw Wa-madaa masalul awwaleen','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>9,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِيزُ ٱلۡعَلِيمُ','transliteration'=>'Wa-la\'in sa-altahum man khalaqas samaawaati wal-arda la-yaqoolunna khalaqa-hunnal \'Azeezul \'Aleem','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>10,'arabic_text'=>'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَجَعَلَ لَكُمۡ فِيهَا سُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ','transliteration'=>'Allazee ja\'ala lakumul arda mahdanw Wa-ja\'ala lakum feehaa subulan la\'allakum tahtadoon','page_number'=>489,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>11,'arabic_text'=>'وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ','transliteration'=>'Wallazee nazzala minas samaaa\'i maaa\'an biqadarin fa-ansharnaa bihee baldatan maitaa\' kazaalika tukhrajoon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>12,'arabic_text'=>'وَٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ','transliteration'=>'Wallazee khalaqal azwaaja kullahaa Wa-ja\'ala lakum minal fulki wal-an\'aami maa tarkaboon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>13,'arabic_text'=>'لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ','transliteration'=>'Litastawoo \'alaa zuhoorihee summa tazkuroo ni\'mata Rabbikum izas tawaitum \'alaihi Wa-taqooloo Subhaanal lazee sakhkhara lana haaza Wa-maa kunnaa lahoo muqrineen','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>14,'arabic_text'=>'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ','transliteration'=>'Wa-innaaa ilaa Rabbinaa lamunqaliboon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>15,'arabic_text'=>'وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ مُّبِينٌ','transliteration'=>'Wa-ja\'aloo lahoo min \'ibaadihee juz\'aa; innal insaana la-kafoorun mubeen','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>16,'arabic_text'=>'أَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَأَصۡفَىٰكُم بِٱلۡبَنِينَ','transliteration'=>'Amit takhaza mimmaa yakhluqu banaatinw Wa-asfaakum bilbaneen','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>17,'arabic_text'=>'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَٰنِ مَثَلٗا ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٌ','transliteration'=>'Wa-izaa bushshira ahaduhum bimaa daraba lir-Rahmaani masalan zalla wajhuhoo muswaddanw Wa-huwa kazeem','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>18,'arabic_text'=>'أَوَمَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ','transliteration'=>'Awa-maien yunashsha\'u fil hilyati Wa-huwa fil khisaami ghairu mubeen','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>19,'arabic_text'=>'وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ أَشَهِدُواْ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَٰدَتُهُمۡ وَيُسۡـَٔلُونَ','transliteration'=>'Wa-ja\'alul malaaa\'ikatal lazeena hum \'ibaadur Rahmaani inaasaa; \'a-shahidoo khalqahum; satuktabu shahaadatuhum Wa-yus\'aloon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>20,'arabic_text'=>'وَقَالُواْ لَوۡ شَآءَ ٱلرَّحۡمَٰنُ مَا عَبَدۡنَٰهُمۗ مَّا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَخۡرُصُونَ','transliteration'=>'Wa-qaaloo law shaaa\'ar Rahmaanu maa \'abadnaahum; maa lahum bizaalika min \'ilmin in hum illaa yakhrusoon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>21,'arabic_text'=>'أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبٗا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ','transliteration'=>'Am aatainaahum Kitaaban min qablihee fahum bihee mustamsikoon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>22,'arabic_text'=>'بَلۡ قَالُوٓاْ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ','transliteration'=>'Bal qaalooo innaa wajadnaaa aabaaa\'anaa \'alaaa ummatinw Wa-innaa \'alaaa aasaarihim muhtadoon','page_number'=>490,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>23,'arabic_text'=>'وَكَذَٰلِكَ مَآ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي قَرۡيَةٖ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ','transliteration'=>'Wa-kazaalika maaa arsalnaa min qablika fee qaryatim min nazeerin illaa qaala mutrafoohaaa innaa wajadnaaa aabaaa\'anaa \'alaaa ummatinw Wa-innaa \'alaaa aasaarihim muqtadoon','page_number'=>491,'juz_number'=>25,'hizb_number'=>49,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>24,'arabic_text'=>'۞ قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ','transliteration'=>'Qaala awa-law ji\'tukum bi-ahdaa mimmaa wajatdtum \'alaihi aabaaa\'akum qaalooo innaa bimaaa ursiltum bihee kaafiroon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>25,'arabic_text'=>'فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ','transliteration'=>'Fantaqamnaa minhum fanzur kaifa kaana \'aaqibatul mukazzibeen','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>26,'arabic_text'=>'وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ','transliteration'=>'Wa-iz qaala Ibraaheemu li-abeehi Wa-qawmiheee innanee baraaa\'un mimmaa ta\'budoon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>27,'arabic_text'=>'إِلَّا ٱلَّذِي فَطَرَنِي فَإِنَّهُۥ سَيَهۡدِينِ','transliteration'=>'Illal lazee fataranee fa-innahoo sa-yahdeen','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>28,'arabic_text'=>'وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-ja\'alahaa kalimatan baaqiyatan fee \'aqibihee la-\'allahum yarji\'oon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>29,'arabic_text'=>'بَلۡ مَتَّعۡتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ جَآءَهُمُ ٱلۡحَقُّ وَرَسُولٞ مُّبِينٞ','transliteration'=>'Bal matta\'tu haaa\'ulaaa\'i Wa-aabaaa\'ahum hattaa jaaa\'a-humul haqqu Wa-Rasoolun mubeen','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>30,'arabic_text'=>'وَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ','transliteration'=>'Wa-lammaa jaaa\'ahumul haqqu qaaloo haazaa sihrunw Wa-innaa bihee kaafiroon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>31,'arabic_text'=>'وَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ','transliteration'=>'Wa-qaaloo law-laa nuzzila haazal Quraanu \'alaa rajulin minal qaryataini \'azeem','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>32,'arabic_text'=>'أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ','transliteration'=>'A-hum yaqsimoona rahmata Rabbik; Nahnu qasamnaa bainahum ma\'eeshatahum fil hayaatid dunyaa Wa-rafa\'naa ba\'dahum fawqa ba\'din darajaatin li-yattakhiza ba\'duhum ba\'dan sukhriyyaa; Wa-rahmatu Rabbika khairun mimmaa yajma\'oon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>33,'arabic_text'=>'وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ','transliteration'=>'Wa-law-laaa aien yakoonan naasu ummatanw waahidatan laja\'alnaa limaien yakfuru bir-Rahmaani li-buyootihim suqufan min fiddatinw Wa-ma\'aarija \'alaihaa yazharoon','page_number'=>491,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>34,'arabic_text'=>'وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ','transliteration'=>'Wa-li-buyootihim abwaabanw Wa-sururan \'alaihaa yattaki\'oon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>35,'arabic_text'=>'وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِينَ','transliteration'=>'Wa-zukhrufaa; Wa-in kullu zaalika lammaa mataa\'ul hayaatid dunyaa; wal-aakhiratu \'inda Rabbika lilmuttaqeen','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>36,'arabic_text'=>'وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ','transliteration'=>'Wa-maien ya\'shu \'an zikrir Rahmaani nuqaiyid lahoo Shaitaanan fahuwa lahoo qareen','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>37,'arabic_text'=>'وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ','transliteration'=>'Wa-innahum la-yasuddoo-nahum \'anis sabeeli Wa-yahsaboona annahum muhtadoon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>38,'arabic_text'=>'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيۡتَ بَيۡنِي وَبَيۡنَكَ بُعۡدَ ٱلۡمَشۡرِقَيۡنِ فَبِئۡسَ ٱلۡقَرِينُ','transliteration'=>'Hattaaa izaa jaaa\'anaa qaala yaa-laita bainee Wa-bainaka bu\'dal mashriqaini fabi\'sal qareen','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>39,'arabic_text'=>'وَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ','transliteration'=>'Wa-lai yanfa\'akumul Yawma iz zalamtum annakum fil \'azaabi mushtarikoon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>40,'arabic_text'=>'أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Afa-anta tusmi\'us summa aw tahdil \'umya Wa-man kaana fee dalaalin mubeen','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>41,'arabic_text'=>'فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ','transliteration'=>'Fa-immaa nazhabanna bika fa-innaa minhum muntaqimoon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>42,'arabic_text'=>'أَوۡ نُرِيَنَّكَ ٱلَّذِي وَعَدۡنَٰهُمۡ فَإِنَّا عَلَيۡهِم مُّقۡتَدِرُونَ','transliteration'=>'Aw nuriyannakal lazee wa\'adnaahum fa-innaa \'alaihim muqtadiroon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>43,'arabic_text'=>'فَٱسۡتَمۡسِكۡ بِٱلَّذِيٓ أُوحِيَ إِلَيۡكَۖ إِنَّكَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Fastamsik billazeee oohiya ilaika innaka \'alaa Siraatin Mustaqeem','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>44,'arabic_text'=>'وَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ','transliteration'=>'Wa-innahoo la-zikrun laka Wa-liqawmika Wa-sawfa tus\'aloon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>45,'arabic_text'=>'وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَآ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَٰنِ ءَالِهَةٗ يُعۡبَدُونَ','transliteration'=>'Was\'al man arsalnaa min qablika mir Rusulinaaa \'a-ja\'alnaa min doonir Rahmaani aalihatany yu\'badoon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>46,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-laqad arsalnaa Moosaa bi-aayaatinaaa ilaa Fir\'awna Wa-mala\'ihee faqaala innee Rasoolu Rabbil \'aalameen','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>47,'arabic_text'=>'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ','transliteration'=>'Falamma jaaa\'ahum bi-aayaatinaaa izaa hum minhaa yadhakoon','page_number'=>492,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>48,'arabic_text'=>'وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-maa nureehim min aayatin illaa hiya akbaru min ukhtihaa Wa-akhaznaahum bil\'azaabi la\'allahum yarji\'oon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>49,'arabic_text'=>'وَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ','transliteration'=>'Wa-qaaloo yaaa ayyuhas saahirud\'u lanaa Rabbaka bimaa \'ahida \'indaka innanaa lamuhtadoon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>50,'arabic_text'=>'فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ','transliteration'=>'Falammaa kashafnaa \'anhumul \'azaaba izaa hum yankusoon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>51,'arabic_text'=>'وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ','transliteration'=>'Wa-naadaa Fir\'awnu fee qawmihee qaala yaa-qawmi alaisa lee mulku Misra Wa-haazihil anhaaru tajree min tahtee afalaa tubsiroon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>52,'arabic_text'=>'أَمۡ أَنَا۠ خَيۡرٞ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينٞ وَلَا يَكَادُ يُبِينُ','transliteration'=>'Am ana khairun min haazal lazee huwa maheenunw Wa-laa yakaadu yubeen','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>53,'arabic_text'=>'فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ','transliteration'=>'Falaw-laa ulqiya \'alaihi aswiratun min zahabin aw jaaa\'a ma\'ahul malaaa\'ikatu muqtarineen','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>54,'arabic_text'=>'فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ','transliteration'=>'Fastakhaffa qawmahoo fa-ataa\'ooh; innahum kaanoo qawman faasiqeen','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>55,'arabic_text'=>'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ','transliteration'=>'Falammaaa aasafoonan taqamnaa minhum fa-aghraqnaahum ajma\'een','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>56,'arabic_text'=>'فَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ','transliteration'=>'Faja\'alnaahum salafanw Wa-masalan lil-aakhireen','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>57,'arabic_text'=>'۞ وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ','transliteration'=>'Wa-lammaa duribab nu Maryama masalan izaa qawmuka minhu yasiddoon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>58,'arabic_text'=>'وَقَالُوٓاْ ءَأَٰلِهَتُنَا خَيۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ','transliteration'=>'Wa-qaalooo \'a-aalihatunaa khairun am hoo; maa daraboohu laka illaa jadalaa; bal hum qawmun khasimoon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>59,'arabic_text'=>'إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ','transliteration'=>'In huwa illaa \'abdun an\'amnaa \'alaihi Wa-ja\'alnaahu masalan li-Baneee Israaa\'eel','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>60,'arabic_text'=>'وَلَوۡ نَشَآءُ لَجَعَلۡنَا مِنكُم مَّلَٰٓئِكَةٗ فِي ٱلۡأَرۡضِ يَخۡلُفُونَ','transliteration'=>'Wa-law nashaaa\'u laja\'alnaa minkum malaaa\'ikatan fil ardi yakhlufoon','page_number'=>493,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>61,'arabic_text'=>'وَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ','transliteration'=>'Wa-innahoo la-\'ilmun lis-Saa\'ati fa-laa tamtarunna bihaa wattabi\'oon; haazaa Siraatun Mustaqeem','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>62,'arabic_text'=>'وَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ','transliteration'=>'Wa-laa yasuddan-nakumush Shaitaanu innahoo lakum \'aduwwun mubeen','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>63,'arabic_text'=>'وَلَمَّا جَآءَ عِيسَىٰ بِٱلۡبَيِّنَٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَيِّنَ لَكُم بَعۡضَ ٱلَّذِي تَخۡتَلِفُونَ فِيهِۖ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ','transliteration'=>'Wa-lammaa jaaa\'a \'Eesaa bilbaiyinaati qaala qad ji\'tukum bil-Hikmati Wa-li-ubaiyyina lakum ba\'dal lazee takhtalifoona feehi fattaqul laaha Wa-atee\'oon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>64,'arabic_text'=>'إِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ','transliteration'=>'Innal laaha Huwa Rabbee Wa-Rabbukum fa\'budooh; haaza Siraatum Mustaqeem','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>65,'arabic_text'=>'فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ ظَلَمُواْ مِنۡ عَذَابِ يَوۡمٍ أَلِيمٍ','transliteration'=>'Fakhtalafal ahzaabu min bainihim fa-wailun lil-lazeena zalamoo min \'azaabi Yawmin aleem','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>66,'arabic_text'=>'هَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ','transliteration'=>'Hal yanzuroona illas Saa\'ata an ta\'tiyahum baghtatanw Wa-hum laa yash\'uroon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>67,'arabic_text'=>'ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ','transliteration'=>'Al-akhillaaa\'u Yawma\'izin ba\'duhum liba\'din \'aduwwun illal muttaqeen','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>68,'arabic_text'=>'يَٰعِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ','transliteration'=>'Yaa-\'ibaadi laa khawfun \'alaikumul Yawma Wa-laaa antum tahzanoon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>69,'arabic_text'=>'ٱلَّذِينَ ءَامَنُواْ بِـَٔايَٰتِنَا وَكَانُواْ مُسۡلِمِينَ','transliteration'=>'Allazeena aamanoo bi-Aayaatinaa Wa-kaanoo muslimeen','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>70,'arabic_text'=>'ٱدۡخُلُواْ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَٰجُكُمۡ تُحۡبَرُونَ','transliteration'=>'Udkhulul Jannata antum Wa-azwaajukum tuhbaroon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>71,'arabic_text'=>'يُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Yutaafu \'alaihim bi-sihafin min zahabinw Wa-akwaab, Wa-feehaa maa tashtaheehil anfusu Wa-talazzul a\'yunu Wa-antum feehaa khaalidoon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>72,'arabic_text'=>'وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-tilkal jannatul lateee ooristumoohaa bimaa kuntum ta\'maloon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>73,'arabic_text'=>'لَكُمۡ فِيهَا فَٰكِهَةٞ كَثِيرَةٞ مِّنۡهَا تَأۡكُلُونَ','transliteration'=>'Lakum feehaa faakihatun kaseeratun minhaa ta\'kuloon','page_number'=>494,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>74,'arabic_text'=>'إِنَّ ٱلۡمُجۡرِمِينَ فِي عَذَابِ جَهَنَّمَ خَٰلِدُونَ','transliteration'=>'Innal mujrimeena fee \'azaabi jahannama khaalidoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>75,'arabic_text'=>'لَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ','transliteration'=>'Laa yufattaru \'anhum Wa-hum feehi mublisoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>76,'arabic_text'=>'وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُواْ هُمُ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-maa zalamnaahum Wa-laakin kaanoo humuz zaalimeen','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>77,'arabic_text'=>'وَنَادَوۡاْ يَٰمَٰلِكُ لِيَقۡضِ عَلَيۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّٰكِثُونَ','transliteration'=>'Wa-naadaw yaa-Maaliku liyaqdi \'alainaa Rabbuka qaala innakum maakithoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>78,'arabic_text'=>'لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ','transliteration'=>'Laqad ji\'naakum bilhaqqi Wa-laakinna aksarakum lil-haqqi kaarihoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>79,'arabic_text'=>'أَمۡ أَبۡرَمُوٓاْ أَمۡرٗا فَإِنَّا مُبۡرِمُونَ','transliteration'=>'Am abramooo amran fainnaa mubrimoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>80,'arabic_text'=>'أَمۡ يَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُبُونَ','transliteration'=>'Am yahsaboona annaa laa nasma\'u sirrahum Wa-najwaahum; balaa Wa-Rusulunaa ladaihim yaktuboon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>81,'arabic_text'=>'قُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدٞ فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ','transliteration'=>'Qul in kaana lir-Rahmaani walad; fa-ana awwalul \'aabideen','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>82,'arabic_text'=>'سُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ','transliteration'=>'Subhaana Rabbis samaawaati wal-ardi Rabbil Arshi \'ammaa yasifoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>83,'arabic_text'=>'فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ','transliteration'=>'Fazarhum yakhoodoo Wa-yal\'aboo hattaa yulaaqoo Yawmahumul lazee yoo\'adoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>84,'arabic_text'=>'وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ','transliteration'=>'Wa-Huwal lazee fis samaaa\'i ilaahunw Wa-fil ardi ilaah; Wa-Huwal Hakeemul \'Aleem','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>85,'arabic_text'=>'وَتَبَارَكَ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَيۡهِ تُرۡجَعُونَ','transliteration'=>'Wa-tabaarakal lazee lahoo mulkus samaawaati wal-ardi Wa-maa bainahumaa Wa-\'indahoo \'ilmus Saa\'ati Wa-ilaihi turja\'oon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>86,'arabic_text'=>'وَلَا يَمۡلِكُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'Wa-laa yamlikul lazeena yad\'oona min doonihish shafaa\'ata illaa man shahida bilhaqqi Wa-hum ya\'lamoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>87,'arabic_text'=>'وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ','transliteration'=>'Wa-la\'in sa-altahum man khalaqahum la-yaqoolun nallaahu fa-annaa yu\'fakoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>88,'arabic_text'=>'وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوۡمٞ لَّا يُؤۡمِنُونَ','transliteration'=>'Wa-qeelihee yaa-Rabbi inna haaa\'ulaaa\'i qawmul laa yu\'minoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>43,'ayah_number'=>89,'arabic_text'=>'فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمٞۚ فَسَوۡفَ يَعۡلَمُونَ','transliteration'=>'Fasfah \'anhum Wa-qul salaam; fasawfa ya\'lamoon','page_number'=>495,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            /* Surah 44: The Smoke (Ad-Dukhan) */
            ['surah_id'=>44,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>2,'arabic_text'=>'وَٱلۡكِتَٰبِ ٱلۡمُبِينِ','transliteration'=>'Wal-Kitaabil Mubeen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>3,'arabic_text'=>'إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ','transliteration'=>'Innaaa anzalnaahu fee lailatim mubaarakah; innaa kunnaa munzireen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>4,'arabic_text'=>'فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ','transliteration'=>'Feehaa yufraqu kullu amrin hakeem','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>5,'arabic_text'=>'أَمۡرٗا مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ','transliteration'=>'Amram min \'indinaaa; innaa kunnaa mursileen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>6,'arabic_text'=>'رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','transliteration'=>'Rahmatam mir rabbik; innahoo Huwas Samee\'ul \'Aleem','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>7,'arabic_text'=>'رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ','transliteration'=>'Rabbis samaawaati wal-ardi Wa-maa bainahumaa; in kuntum mooqineen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>8,'arabic_text'=>'لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ','transliteration'=>'Laaa ilaaha illaa Huwa yuhyee Wa-yumeetu Rabbukum Wa-Rabbu aabaaa\'ikumul awwaleen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>9,'arabic_text'=>'بَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ','transliteration'=>'Bal hum fee shakkien yal\'aboon','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>10,'arabic_text'=>'فَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ','transliteration'=>'Fartaqib Yawma ta\'tis samaaa\'u bi-dukhaanin mubeen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>11,'arabic_text'=>'يَغۡشَى ٱلنَّاسَۖ هَٰذَا عَذَابٌ أَلِيمٞ','transliteration'=>'Yaghshan naasa haazaa \'azaabun aleem','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>12,'arabic_text'=>'رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ','transliteration'=>'Rabbanak shif \'annal \'azaaba innaa mu\'minoon','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>13,'arabic_text'=>'أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولٞ مُّبِينٞ','transliteration'=>'Annaa lahumuz zikraa Wa-qad jaaa\'ahum Rasoolum mubeen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>14,'arabic_text'=>'ثُمَّ تَوَلَّوۡاْ عَنۡهُ وَقَالُواْ مُعَلَّمٞ مَّجۡنُونٌ','transliteration'=>'Summaa tawallaw \'anhu Wa-qaaloo mu\'allamum majnoon','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>15,'arabic_text'=>'إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ إِنَّكُمۡ عَآئِدُونَ','transliteration'=>'Innaa kaashiful \'azaabi qaleelaa; innakum \'aaa\'idoon','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>16,'arabic_text'=>'يَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰٓ إِنَّا مُنتَقِمُونَ','transliteration'=>'Yawma nabtishul batsha-tal kubraa innaa muntaqimoon','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>17,'arabic_text'=>'۞ وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ','transliteration'=>'Wa-laqad fatannaa qablahum qawma Fir\'awna Wa-jaaa\'ahum Rasoolun kareem','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>18,'arabic_text'=>'أَنۡ أَدُّوٓاْ إِلَيَّ عِبَادَ ٱللَّهِۖ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ','transliteration'=>'An addooo ilaiya \'ibaadal laahi innee lakum Rasoolun ameen','page_number'=>496,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>19,'arabic_text'=>'وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِۖ إِنِّيٓ ءَاتِيكُم بِسُلۡطَٰنٖ مُّبِينٖ','transliteration'=>'Wa-al laa ta\'loo \'alal laahi innee aateekum bisultaanim mubeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>20,'arabic_text'=>'وَإِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ','transliteration'=>'Wa-innee \'uztu bi-Rabbee Wa-rabbikum an tarjumoon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>21,'arabic_text'=>'وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ','transliteration'=>'Wa-il lam tu\'minoo lee fa\'taziloon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>22,'arabic_text'=>'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ','transliteration'=>'Fada\'aa rabbahooo anna haaa\'ulaaa\'i qawmum mujrimoon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>23,'arabic_text'=>'فَأَسۡرِ بِعِبَادِي لَيۡلًا إِنَّكُم مُّتَّبَعُونَ','transliteration'=>'Fa-asri bi\'ibaadee lailan innakum muttaba\'oon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>24,'arabic_text'=>'وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندٞ مُّغۡرَقُونَ','transliteration'=>'Watrukil bahra rahwan innahum jundum mughraqoon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>25,'arabic_text'=>'كَمۡ تَرَكُواْ مِن جَنَّٰتٖ وَعُيُونٖ','transliteration'=>'Kam tarakoo min jannaatinw Wa-\'uyoon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>26,'arabic_text'=>'وَزُرُوعٖ وَمَقَامٖ كَرِيمٖ','transliteration'=>'Wa-zuroo\'inw Wa-maqaa-min kareem','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>27,'arabic_text'=>'وَنَعۡمَةٖ كَانُواْ فِيهَا فَٰكِهِينَ','transliteration'=>'Wa-na\'matin kaanoo feehaa faakiheen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>28,'arabic_text'=>'كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ','transliteration'=>'Kazaalika Wa-awrasnaahaa qawman aakhareen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>29,'arabic_text'=>'فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ','transliteration'=>'Famaa bakat \'alaihimus samaaa\'u wal-ardu Wa-maa kaanoo munzareen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>30,'arabic_text'=>'وَلَقَدۡ نَجَّيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِينِ','transliteration'=>'Wa-laqad najjainaa Baneee Israaa\'eela minal \'azaabil muheen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>31,'arabic_text'=>'مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِيٗا مِّنَ ٱلۡمُسۡرِفِينَ','transliteration'=>'Min Fir\'awn; innahoo kaana \'aaliyam minal musrifeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>32,'arabic_text'=>'وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-laqadikh tarnaahum \'alaa \'ilmin \'alal \'aalameen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>33,'arabic_text'=>'وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَٰٓؤٞاْ مُّبِينٌ','transliteration'=>'Wa-aatainaahum minal aayaati maa feehi balaaa\'um mubeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>34,'arabic_text'=>'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ','transliteration'=>'Inna haaa\'ulaaa\'i la-yaqooloon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>35,'arabic_text'=>'إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِينَ','transliteration'=>'In hiya illaa mawtatunal oolaa Wa-maa nahnu bimun-shareen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>36,'arabic_text'=>'فَأۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Fa\'too bi-aabaaa\'inaaa in kuntum saadiqeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>37,'arabic_text'=>'أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ','transliteration'=>'Ahum khayrun am qawmu Tubba\'inw wallazeena min qablihim; ahlaknaahum innahum kaanoo mujrimeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>38,'arabic_text'=>'وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ','transliteration'=>'Wa-maa khalaqnas samaawaati wal-arda Wa-maa baina-humaa laa\'ibeen','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>39,'arabic_text'=>'مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Maa khalaqnaahumaaa illaa bilhaqqi Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>497,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>40,'arabic_text'=>'إِنَّ يَوۡمَ ٱلۡفَصۡلِ مِيقَٰتُهُمۡ أَجۡمَعِينَ','transliteration'=>'Inna yawmal fasli meeqaatuhum ajma\'een','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>41,'arabic_text'=>'يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Yawma laa yughnee mawlan \'am mawlan shai\'anw Wa-laa hum yunsaroon','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>42,'arabic_text'=>'إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ','transliteration'=>'Illaa mar rahimal laah\' innahoo huwal \'azeezur raheem','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
