            ['surah_id'=>44,'ayah_number'=>56,'arabic_text'=>'لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ','transliteration'=>'Laa yazooqoona feehal mawtaa illal mawtatal oolaa Wa-waqaahum \'azaabal jaheem','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>57,'arabic_text'=>'فَضۡلٗا مِّن رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Fadlam mir rabbik; zaalika huwal fawzul \'azeem','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>58,'arabic_text'=>'فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ','transliteration'=>'Fa-innamaa yassarnaahu bilisaanika la\'allahum yatazakkaroon','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>44,'ayah_number'=>59,'arabic_text'=>'فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ','transliteration'=>'Fartaqib innahum murta-qiboon','page_number'=>498,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            /* Surah 45: The Crouching (Al-Jathiyah) */
            ['surah_id'=>45,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>2,'arabic_text'=>'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','transliteration'=>'Tanzeelul Kitaabi minal laahil \'Azeezil Hakeem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>3,'arabic_text'=>'إِنَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ','transliteration'=>'Innaa fis samaawaati wal-ardi la-Aayaatil lilmu\'mineen','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>4,'arabic_text'=>'وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ','transliteration'=>'Wa-fee khalaqikum Wa-maa yabussu min daaabbatin Aayaatul liqawmien yooqinoon','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>5,'arabic_text'=>'وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ','transliteration'=>'Wakhtilaafil laili wannahaari Wa-maaa anzalal laahu minas samaaa\'i mir rizqin fa-ahyaa bihil arda ba\'da mawtihaa Wa-tasreefir riyaahi Aayaatul liqawminy ya\'qiloon','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>6,'arabic_text'=>'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤۡمِنُونَ','transliteration'=>'Tilka Aayatul laahi natloohaa \'alaika bil-haqq, fabiayyi hadeesim ba\'dal laahi Wa-Aayaatihee yu\'minoon','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>7,'arabic_text'=>'وَيۡلٞ لِّكُلِّ أَفَّاكٍ أَثِيمٖ','transliteration'=>'Wailul likulli affaakin aseem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>8,'arabic_text'=>'يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ','transliteration'=>'Yasma\'u Aayaatil laahi tutlaa \'alaihi summa yusirru mustakbiran ka-al lam yasma\'haa fabashshirhu bi\'azaabin aleem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>9,'arabic_text'=>'وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ','transliteration'=>'Wa-izaa \'alima min Aayaatinaa shai\'-\'anit takhazahaa huzuwaa; ulaaa\'ika lahum \'azaabum muheen','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>10,'arabic_text'=>'مِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ','transliteration'=>'Minw waraaa\'ihim Jahannamu Wa-laa yughnee \'anhum maa kasaboo shai\'anw Wa-laa mat takhazoo min doonil laahi awliyaaa; Wa-lahum \'azaabun \'azeem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>11,'arabic_text'=>'هَٰذَا هُدٗىۖ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٌ','transliteration'=>'Haazaa hudaa; wal-lazeena kafaroo bi-aayaati Rabbihim lahum \'azaabum mir rijzin \'aleem','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>12,'arabic_text'=>'۞ ٱللَّهُ ٱلَّذِي سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِيَ ٱلۡفُلۡكُ فِيهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ','transliteration'=>'Allaahul lazee sahkhara lakumul bahra litajriyal fulku feehi bi-amrihee Wa-litabtaghoo min fadlihee Wa-la\'allakum tashkuroon','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>13,'arabic_text'=>'وَسَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ جَمِيعٗا مِّنۡهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ','transliteration'=>'Wa-sakhkhara lakum maa fis samaawaati Wa-maa fil ardi jamee\'am minhu; inna fee zaalika la-Aayaatil liqawmien yatafakkaroon','page_number'=>499,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>14,'arabic_text'=>'قُل لِّلَّذِينَ ءَامَنُواْ يَغۡفِرُواْ لِلَّذِينَ لَا يَرۡجُونَ أَيَّامَ ٱللَّهِ لِيَجۡزِيَ قَوۡمَۢا بِمَا كَانُواْ يَكۡسِبُونَ','transliteration'=>'Qul lillazeena aamanoo yaghfiroo lillazeena laa yarjoona ayyaamal laahi liyajziya qawmam bimaa kaanoo yaksiboon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>15,'arabic_text'=>'مَنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ','transliteration'=>'Maa \'amila saalihan falinafsihee Wa-man asaaa\'a fa\'alaihaa summa ilaa Rabbikum turja\'oon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>16,'arabic_text'=>'وَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ','transliteration'=>'Wa-laqad aatainaa Baneee Israaa\'eelal Kitaaba walhukma wan Nubuwwata Wa-razaqnaahum minat taiyibaati Wa-faddalnaahum;alal \'aalameen','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>17,'arabic_text'=>'وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','transliteration'=>'Wa-aatainaahum baiyinaatim minal amri famakh talafooo illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>18,'arabic_text'=>'ثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٖ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ لَا يَعۡلَمُونَ','transliteration'=>'Summa ja\'alnaaka \'alaa sharee\'atim minal amri fattabi\'haa Wa-laa tattabi\' ahwaaa\' al-lazeena laa ya\'lamoon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>19,'arabic_text'=>'إِنَّهُمۡ لَن يُغۡنُواْ عَنكَ مِنَ ٱللَّهِ شَيۡـٔٗاۚ وَإِنَّ ٱلظَّٰلِمِينَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۖ وَٱللَّهُ وَلِيُّ ٱلۡمُتَّقِينَ','transliteration'=>'Innahum laien yughnoo \'anka minal laahi shai\'aa; Wa-innaz zaalimeena ba\'duhum awliyaaa\'u ba\'dinw wallaahu waliyyul muttaqeen','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>20,'arabic_text'=>'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُوقِنُونَ','transliteration'=>'Haazaa basaaa\'iru linnaasi Wa-hudanw Wa-rahmatul liqawmien yooqinoon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>21,'arabic_text'=>'أَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ مَا يَحۡكُمُونَ','transliteration'=>'Am hasibal lazeenaj tarahus saiyyiaati an naj\'alahum kallazeena aamanoo Wa-\'amilu saalihaati sawaaa\'am mahyaahum Wa-mamaatuhum; saaa\'a maa yahkumoon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>22,'arabic_text'=>'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-khalaqal laahus samaawaati wal-arda bilhaqqi Wa-litujzaa kullu nafsim bimaa kasabat Wa-hum laa yuzlamoon','page_number'=>500,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>23,'arabic_text'=>'أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ','transliteration'=>'Afara\'ayta manit takhaza ilaahahoo hawaahu Wa-adal-lahul laahu \'alaa \'ilminw Wa-khatama \'alaa sam\'ihee Wa-qalbihee Wa-ja\'ala \'alaa basarihee ghishaawatan famaien yahdeehi mim ba\'dil laah; afalaa tazakkaroon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>24,'arabic_text'=>'وَقَالُواْ مَا هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا يُهۡلِكُنَآ إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَظُنُّونَ','transliteration'=>'Wa-qaaloo maa hiya illaa hayaatunad dunyaa namootu Wa-nahyaa Wa-maa yuhlikunaaa illad dahr; Wa-maa lahum bizaalika min \'ilmin in hum illaa yazunnoon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>25,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-izaa tutlaa \'alaihim aayaatuna baiyinaatim maa kaana hujjatahum illaaa an qaalu\'too bi aabaaa\'inaaa in kuntum saadiqeen','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>26,'arabic_text'=>'قُلِ ٱللَّهُ يُحۡيِيكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يَجۡمَعُكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ','transliteration'=>'Qulil laahu yuhyeekum summa yumeetukum summa yajma\'ukum ilaa Yawmil Qiyaamati laa raiba feehi Wa-laakinna aksaran naasi laa ya\'lamoon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>27,'arabic_text'=>'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَخۡسَرُ ٱلۡمُبۡطِلُونَ','transliteration'=>'Wa-lillaahi mulkus samaawaati wal-ard; Wa-Yawma taqoomus Saa\'atu Yawma-\'izien yakhsarul mubtiloon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>28,'arabic_text'=>'وَتَرَىٰ كُلَّ أُمَّةٖ جَاثِيَةٗۚ كُلُّ أُمَّةٖ تُدۡعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلۡيَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Wa-taraa kulla ummatin jaasiyah; kullu ummatin tud\'aaa ilaa kitaabihaa al-Yawma tujzawna maa kuntum ta\'maloon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>29,'arabic_text'=>'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Haazaa kitaabunaa yantiqu \'alaikum bilhaqq; innaa kunnaa nastansikhu maa kuntum ta\'maloon','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>30,'arabic_text'=>'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ','transliteration'=>'Fa-ammal lazeena aamaanoo Wa-\'amilus saalihaati fayudkhiluhum Rabbuhum fee rahmatih; zaalika huwal fawzul mubeen','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>31,'arabic_text'=>'وَأَمَّا ٱلَّذِينَ كَفَرُوٓاْ أَفَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمٗا مُّجۡرِمِينَ','transliteration'=>'Wa-ammal lazeena kafarooo afalam takun Aayaatee tutlaa \'alaikum fastakbartum Wa-kuntum qawmam mujrimeen','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>32,'arabic_text'=>'وَإِذَا قِيلَ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱلسَّاعَةُ لَا رَيۡبَ فِيهَا قُلۡتُم مَّا نَدۡرِي مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنّٗا وَمَا نَحۡنُ بِمُسۡتَيۡقِنِينَ','transliteration'=>'Wa-izaa qeela inna wa\'dallaahi haqqunw was Saa\'atu laa raiba feehaa qultum maa nadree mas Saa\'atu in nazunnu illaa zannanw Wa-maa nahnu bimustaiqineen','page_number'=>501,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>33,'arabic_text'=>'وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-badaa lahum saiyyiaatu maa \'amiloo Wa-haaqa bihim maa kaanoo bihee yastahzi\'oon','page_number'=>502,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>34,'arabic_text'=>'وَقِيلَ ٱلۡيَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ','transliteration'=>'Wa-qeelal yawma nansaakum kamaa naseetum liqaaa\'a yawmikum haazaa Wa-maawaakumun Naaru Wa-maa lakum min naasireen','page_number'=>502,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>35,'arabic_text'=>'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَايَٰتِ ٱللَّهِ هُزُوٗا وَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَبُونَ','transliteration'=>'Zaalikum bi-annakumut takhaztum aayaatil laahi huzuwanw Wa-gharratkumul hayaatud dunyaa; fal yawma laa yukhrajoona minhaa Wa-laahum yusta\'taboon','page_number'=>502,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>36,'arabic_text'=>'فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ','transliteration'=>'Falillaahil hamdu Rabbis samaawaati Wa-Rabbil ardi Rabbil \'aalameen','page_number'=>502,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            ['surah_id'=>45,'ayah_number'=>37,'arabic_text'=>'وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Wa-lahul kibriyaaa\'u fis samaawaati wal-ardi Wa-Huwal \'Azeezul Hakeem','page_number'=>502,'juz_number'=>25,'hizb_number'=>50,'is_sajdah'=>false],
            /* Surah 46: The Wind-Curved Sandhills (Al-Ahqaf) */
            ['surah_id'=>46,'ayah_number'=>1,'arabic_text'=>'حمٓ','transliteration'=>'Haa-Meeeem','page_number'=>502,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>2,'arabic_text'=>'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','transliteration'=>'Tanzeelul Kitaabi minal laahil \'Azeezil Hakeem','page_number'=>502,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>3,'arabic_text'=>'مَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۚ وَٱلَّذِينَ كَفَرُواْ عَمَّآ أُنذِرُواْ مُعۡرِضُونَ','transliteration'=>'Maa khalaqnas samaawaati wal-arda Wa-maa bainahumaaa illaa bilhaqqi Wa-ajalim musammaa; wallazeena kafaroo \'ammaaa unziroo mu\'ridoon','page_number'=>502,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>4,'arabic_text'=>'قُلۡ أَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِۖ ٱئۡتُونِي بِكِتَٰبٖ مِّن قَبۡلِ هَٰذَآ أَوۡ أَثَٰرَةٖ مِّنۡ عِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Qul ara\'aytum maa tad\'oona min doonil laahi aroonee maazaa khalaqoo minal ardi am lahum shirkun fis samaawaati eetoonee bi-kitaabim min qabli haazaaa aw asaaratim min \'ilmin in kuntum saadiqeen','page_number'=>502,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>5,'arabic_text'=>'وَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ','transliteration'=>'Wa-man adallu mimmaien yad\'oo min doonil laahi mal laa yastajeebu lahooo ilaa Yawmil Qiyaamati Wa-hum \'an du\'aaa\'ihim ghaafiloon','page_number'=>502,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>6,'arabic_text'=>'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُواْ لَهُمۡ أَعۡدَآءٗ وَكَانُواْ بِعِبَادَتِهِمۡ كَٰفِرِينَ','transliteration'=>'Wa-izaa hushiran naasu kaanoo lahum a\'daaa\'anw Wa-kaanoo bi\'ibaadatihim kaafireen','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>7,'arabic_text'=>'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ هَٰذَا سِحۡرٞ مُّبِينٌ','transliteration'=>'Wa-izaa tutlaa \'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lilhaqqi lammaa jaaa\'ahum haazaa sihrum mubeen','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>8,'arabic_text'=>'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَلَا تَمۡلِكُونَ لِي مِنَ ٱللَّهِ شَيۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِيضُونَ فِيهِۚ كَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ','transliteration'=>'Am yaqooloonaf taraahu qul inif taraituhoo falaa tamlikoona lee minal laahi shai\'an Huwa a\'lamu bimaa tufeedoona feehi kafaa bihee shaheedam bainee Wa-bainakum Wa-Huwal Ghafoorur Raheem','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>9,'arabic_text'=>'قُلۡ مَا كُنتُ بِدۡعٗا مِّنَ ٱلرُّسُلِ وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ','transliteration'=>'Qul maa kuntu bid\'am minal Rusuli Wa-maaa adreee ma yuf\'alu bee Wa-laa bikum in attabi\'u illaa maa yoohaaa ilaiya Wa-maaa ana illaa nazeerum mubeen','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>10,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدٞ مِّنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Qul ara\'aytum in kaana min \'indil laahi Wa-kafartum bihee Wa-shahida shaahidum mim Banee Israaa\'eela \'alaa mislihee fa-aamana wastak-bartum innal laaha laa yahdil qawmaz zaalimeen','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>11,'arabic_text'=>'وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِۚ وَإِذۡ لَمۡ يَهۡتَدُواْ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفۡكٞ قَدِيمٞ','transliteration'=>'Wa-qaalal lazeena kafaroo lillazeena aamanoo law kaana khairam maa sabaqoonaaa ilyh; Wa-iz lam yahtadoo bihee fasa-yaqooloona haazaaa ifkun qadeem','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>12,'arabic_text'=>'وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةٗۚ وَهَٰذَا كِتَٰبٞ مُّصَدِّقٞ لِّسَانًا عَرَبِيّٗا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُواْ وَبُشۡرَىٰ لِلۡمُحۡسِنِينَ','transliteration'=>'Wa-min qablihee kitaabu Moosaaa imaamanw wa-rahmah; Wa-haazaa Kitaabum musad-diqul lisaanan \'Arabiyyal liyunziral lazeena zalamoo Wa-bushraa lilmuhsineen','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>13,'arabic_text'=>'إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','transliteration'=>'Innal lazeena qaaloo Rabbunal laahu summas taqaamoo falaa khawfun \'alaihim Wa-laa hum yahzanoon','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>14,'arabic_text'=>'أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ulaaa\'ika Ashabul Jannati khaalideena feehaa jazaaa\'am bimaa kaano ya\'maloon','page_number'=>503,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>15,'arabic_text'=>'وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Wa-wassainal insaana biwaalidaihi ihsaana; hamalat-hu ummuhoo kurhanwn wa-wada\'at-hu kurhanw Wa-hamluhoo Wa-fisaaluhoo salaasoona shahraa; hattaaa izaa balagha ashuddahoo Wa-balagha arba\'eena sanatan qaala Rabbi awzi\'-neee an ashkura ni\'matakal lateee an\'amta \'alaiyya Wa-\'alaa waalidaiya Wa-an a\'mala saalihan tardaahu Wa-aslih lee fee zurriyyatee; innee tubtu ilaika Wa-innee minal muslimeen','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>16,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمۡ فِيٓ أَصۡحَٰبِ ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِي كَانُواْ يُوعَدُونَ','transliteration'=>'Ulaaa\'ikal lazeena nata-qabbalu \'anhum ahsana maa \'amiloo Wa-natajaawazu \'an saiyiaatihim feee Ashaabil jannati Wa\'das sidqil lazee kaanoo yoo\'adoon','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>17,'arabic_text'=>'وَٱلَّذِي قَالَ لِوَٰلِدَيۡهِ أُفّٖ لَّكُمَآ أَتَعِدَانِنِيٓ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن قَبۡلِي وَهُمَا يَسۡتَغِيثَانِ ٱللَّهَ وَيۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','transliteration'=>'Wallazee qaala liwaali-daihi uffil lakumaaa ata\'idanineee an ukhraja Wa-qad khalatil quroonu min qablee Wa-humaa yastagheesaanil laaha wailaka aamin inna wa\'dal laahi haqq, fa-yaqoolu maa haazaaa illaaa asaateerul awwaleen','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>18,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ','transliteration'=>'Ulaaa\'ikal lazeena haqqa \'alaihimul qawlu feee umamin qad khalat min qablihim minal jinni wal-insi innahum kaanoo khaasireen','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>19,'arabic_text'=>'وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۖ وَلِيُوَفِّيَهُمۡ أَعۡمَٰلَهُمۡ وَهُمۡ لَا يُظۡلَمُونَ','transliteration'=>'Wa-likullin darajaatum mimmaa \'amiloo Wa-liyuwaf-fiyahum a\'maalahum Wa-hum laa yuzlamoon','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>20,'arabic_text'=>'وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ','transliteration'=>'Wa-Yawma yu\'radul lazeena kafaroo \'alan Naari azhabtum taiyibaatikum fee hayaatikumud dunyaa wastam-ta\'tum bihaa fal-Yawma tujzawna \'azaabal hooni bimaa kuntum tastakbiroona fil ardi bighairil haqqi Wa-bimaa kuntum tafsuqoon','page_number'=>504,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>21,'arabic_text'=>'۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ','transliteration'=>'Wazkur akhaa \'Aad, iz anzara qawmahoo bil-Ahqaafi Wa-qad khalatin nuzuru mim baini yadaihi Wa-min khalfiheee allaa ta\'budooo illal laaha inneee akhaafu \'alaikum \'azaaba Yawmin \'azeem','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>22,'arabic_text'=>'قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','transliteration'=>'Qaaloo aji\'tanaa li-taa-fikanaa \'an aalihatinaa fa\'tinaa bimaa ta\'idunaaa in kunta minas saadiqeen','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>23,'arabic_text'=>'قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ','transliteration'=>'Qaala innamal \'ilmu indal laahi Wa-uballighukum maaa ursiltu bihee Wa-laakinneee araakum qawman tajhaloon','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>24,'arabic_text'=>'فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ','transliteration'=>'Falammaa ra awhu \'aaridam mustaqbila awdiyatihim qaaloo haazaa \'aaridum mumtirunaa; bal huwa masta\'jaltum bihee reehun feehaa \'azaabun aleem','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>25,'arabic_text'=>'تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ','transliteration'=>'Tudammiru kulla shai\'im bi-amri Rabbihaa fa-asbahoo laa yuraaa illaa masaakinuhum; kazaalika najzil qawmal mujrimeen','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>26,'arabic_text'=>'وَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','transliteration'=>'Wa-laqad makkannaahum feemaaa im makkannaakum feehi waj\'alnaa lahum sam\'anw Wa-absaaranw Wa-af\'idatan famaaa aghnaa \'anhum samu\'uhum Wa-laaa absaaruhum Wa-laaa af\'idatuhum min shai\'in iz kaanoo yajhadoona bi-Aayaatil laahi Wa-haaqa bihim maa kaanoo bihee yastahzi\'oon','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>27,'arabic_text'=>'وَلَقَدۡ أَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَرۡجِعُونَ','transliteration'=>'Wa-laqad ahlaknaa ma hawlakum minal quraa Wa-sarrafnal Aayaati la\'allahum yarji\'oon','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>28,'arabic_text'=>'فَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ بَلۡ ضَلُّواْ عَنۡهُمۡۚ وَذَٰلِكَ إِفۡكُهُمۡ وَمَا كَانُواْ يَفۡتَرُونَ','transliteration'=>'Falaw-laa nasarahumul lazeenat takhazoo min doonil laahi qurbaanan aalihatam bal dalloo \'anhum\' Wa-zaalika ifkuhum Wa-maa kaanoo yaftaroon','page_number'=>505,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>29,'arabic_text'=>'وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ','transliteration'=>'Wa-iz sarafinaaa ilaika nafaram minal jinni yastami\'oonal Quraana falammaa hadaroohu qaalooo ansitoo falammaa qudiya wallaw ilaa qawmihim munzireen','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>30,'arabic_text'=>'قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ','transliteration'=>'Qaaloo yaa-qawmanaaa innaa sami\'naa Kitaaban unzila mim ba\'di Moosa musaddiqal limaa baina yadihi yahdeee ilal haqqi Wa-ilaa Tareeqim Mustaqeem','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>31,'arabic_text'=>'يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمٖ','transliteration'=>'Yaa-qawmanaaa ajeeboo daa\'iyal laahi Wa-aaminoo bihee yaghfir lakum min zunoobikum Wa-yujirkum min \'azaabin aleem','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>32,'arabic_text'=>'وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزٖ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ','transliteration'=>'Wa-mal laa yujib daa\'iyal laahi falaisa bimu\'jizin fil ardi Wa-laisa lahoo min dooniheee awliyaaa\'; ulaaa-ika fee dalaalim mubeen','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>33,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Awalam yaraw annal laahal lazee khalaqas samaawaati wal-larda Wa-lam ya\'ya bikhal qihinna biqaadirin \'alaaa aiyuhyiyal mawtaa; balaaa innahoo \'alaa kulli shai\'in Qadeer','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>34,'arabic_text'=>'وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۖ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ','transliteration'=>'Wa-Yawma yu\'radul lazeena kafaroo \'alan naari alaisa haaza bil-haqq; qaaloo balaa Wa-Rabbinaa; qaala fazooqul \'azaaba bimaa kuntum takfuroon','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>46,'ayah_number'=>35,'arabic_text'=>'فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Fasbir kamaa sabara ulul \'azmi minar Rusuli Wa-laa tasta\'jil lahum; ka-annahum Yawma yarawna maa yoo\'adoona lam yalbasooo illaa saa\'atam min nahaar; balaagh; fahal yuhlaku illal qawmul faasiqoon','page_number'=>506,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            /* Surah 47: Muhammad (Muhammad) */
            ['surah_id'=>47,'ayah_number'=>1,'arabic_text'=>'ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعۡمَٰلَهُمۡ','transliteration'=>'Allazeena kafaroo Wa-saddoo \'an sabeelil laahi adalla a\'maalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>2,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٖ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ','transliteration'=>'Wallazeena aamanoo Wa-\'amilus saalihaati Wa-aamanoo bimaa nuzzila \'alaa Muhammadinw-wa huwal haqqu mir Rabbihim kaffara \'anhum saiyiaatihim Wa-aslaha baalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>3,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُواْ ٱتَّبَعُواْ ٱلۡبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُواْ ٱتَّبَعُواْ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَٰلَهُمۡ','transliteration'=>'Zaalika bi-annal lazeena kafarut taba\'ul baatila Wa-annal lazeena aamanut taba\'ul haqqa mir Rabbihim; kazaalika yadribul laahu linnaasi amsaalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>4,'arabic_text'=>'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ','transliteration'=>'Fa-izaa laqeetumul lazeena kafaroo fadarbar riqaabi, hattaaa izaa askhan-tumoohum fashuddul wasaaqa, fa-immaa mannnam ba\'du Wa-immaa fidaaa\'an hattaa tada\'al harbu awzaarahaa; zaalika Wa-law yashaaa\'ul laahu lantasara minhum Wa-laakin li-yabluwa ba\'dakum bi-ba\'d; wallazeena qutiloo fee sabeelil laahi falaien yudilla a\'maalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>5,'arabic_text'=>'سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ','transliteration'=>'Sa-yahdeehim Wa-yuslihu baalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>6,'arabic_text'=>'وَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ','transliteration'=>'Wa-yudkhiluhumul jannata \'arrafahaa lahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>7,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ','transliteration'=>'Yaaa-ayyuhal lazeena aamanooo in tansurul laaha yansurkum Wa-yusabbit aqdaamakum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>8,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ فَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ','transliteration'=>'Wallazeena kafaroo fata\'-sal lahum Wa-adalla a\'maalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>9,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ','transliteration'=>'Zaalika bi-annahum karihoo maaa anzal allaahu fa-ahbata a\'maalahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>10,'arabic_text'=>'۞ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ وَلِلۡكَٰفِرِينَ أَمۡثَٰلُهَا','transliteration'=>'Afalam yaseeroo fil ardi fayanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; dammaral laahu \'alaihim Wa-lilkaafireena amsaaluhaa','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>11,'arabic_text'=>'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ','transliteration'=>'Zaalika bi-annal laaha mawlal lazeena aamanoo Wa-annal kaafireena laa mawlaa lahum','page_number'=>507,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>12,'arabic_text'=>'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ','transliteration'=>'Innal-laaha yudkhilul lazeena aamanoo Wa-\'amilus saalihaati Jannaatin tajree min tahtihal anhaaru wallazeena kafaroo yatamatta\'oona Wa-ya\'kuloona kamaa ta\'kulul an\'aamu wan Naaru maswan lahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>13,'arabic_text'=>'وَكَأَيِّن مِّن قَرۡيَةٍ هِيَ أَشَدُّ قُوَّةٗ مِّن قَرۡيَتِكَ ٱلَّتِيٓ أَخۡرَجَتۡكَ أَهۡلَكۡنَٰهُمۡ فَلَا نَاصِرَ لَهُمۡ','transliteration'=>'Wa-ka-ayyim min qaryatin hiya ashaddu quwwatam min qaryatikal lateee akhrajatka ahlaknaahum falaa naasira lahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>14,'arabic_text'=>'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم','transliteration'=>'Afaman kaana \'alaa baiyinatim mir Rabbihee kaman zuyyina lahoo sooo\'u \'amalihee wattaba\'ooo ahwaaa\'ahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>15,'arabic_text'=>'مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرٞ مِّن مَّآءٍ غَيۡرِ ءَاسِنٖ وَأَنۡهَٰرٞ مِّن لَّبَنٖ لَّمۡ يَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرٞ مِّنۡ خَمۡرٖ لَّذَّةٖ لِّلشَّٰرِبِينَ وَأَنۡهَٰرٞ مِّنۡ عَسَلٖ مُّصَفّٗىۖ وَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةٞ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدٞ فِي ٱلنَّارِ وَسُقُواْ مَآءً حَمِيمٗا فَقَطَّعَ أَمۡعَآءَهُمۡ','transliteration'=>'Masalul jannatil latee wu\'idal muttaqoona feehaaa anhaarum min maaa\'in ghayri aasininw Wa-anhaarum mil labanil lam yataghaiyar ta\'muhoo Wa-anhaarum min khamril lazzatin li-shaaribeena Wa-anhaarum min \'asalim musaffanw Wa-lahum feeha min kullis samaraati Wa-maghfiratum mir Rabbihim kaman huwa khaalidun fin naari Wa-suqoo maaa\'an hameeman faqatta\'a am\'aaa\'ahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>16,'arabic_text'=>'وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَ حَتَّىٰٓ إِذَا خَرَجُواْ مِنۡ عِندِكَ قَالُواْ لِلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡ','transliteration'=>'Wa-minhum maien yastami\'u ilaika hattaaa izaa kharajoo min \'indika qaaloo lil-lazeena ootul \'ilma maazaa qaala aanifaa; ulaaa\'ikal lazeena taba\'al laahu \'alaa quloobihim wattaba\'ooo ahwaaa\'ahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>17,'arabic_text'=>'وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ','transliteration'=>'Wallazeenah tadaw zaadahum hudanw Wa-aataahum taqwaahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>18,'arabic_text'=>'فَهَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗۖ فَقَدۡ جَآءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَآءَتۡهُمۡ ذِكۡرَىٰهُمۡ','transliteration'=>'Fahal yanzuroona illas Saa\'ata an ta\'tiyahum baghtatan faqad jaaa\'a ashraatuhaa; fa-annaa lahum izaa jaaa\'at-hum zikraahum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>19,'arabic_text'=>'فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ','transliteration'=>'Fa\'lam annahoo laaa ilaaha illal laahu wastaghfir lizambika Wa-lilmu\'mineena walmu\'minaat; wallaahu ya\'lamu mutaqallabakum Wa-maswaakum','page_number'=>508,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>20,'arabic_text'=>'وَيَقُولُ ٱلَّذِينَ ءَامَنُواْ لَوۡلَا نُزِّلَتۡ سُورَةٞۖ فَإِذَآ أُنزِلَتۡ سُورَةٞ مُّحۡكَمَةٞ وَذُكِرَ فِيهَا ٱلۡقِتَالُ رَأَيۡتَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يَنظُرُونَ إِلَيۡكَ نَظَرَ ٱلۡمَغۡشِيِّ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ','transliteration'=>'Wa-yaqoolul lazeena aamanoo law-laa nuzzilat Sooratun fa-izaaa unzilat Sooratum Muhkamatunw Wa-zukira feehal qitaalu ra-aytal lazeena fee quloobihim maraduien yanzuroona ilaika nazaral maghshiyyi \'alaihi minal mawti fa\'awlaa lahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>21,'arabic_text'=>'طَاعَةٞ وَقَوۡلٞ مَّعۡرُوفٞۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُواْ ٱللَّهَ لَكَانَ خَيۡرٗا لَّهُمۡ','transliteration'=>'Taa\'atunw Wa-qawlum ma\'roof; fa-izaa \'azamal amru falaw sadaqul laaha lakaana khairal lahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>22,'arabic_text'=>'فَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ','transliteration'=>'Fahal \'asaitum in tawallaitum an tufsidoo fil ardi Wa-tuqatti\'ooo arhaamakum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>23,'arabic_text'=>'أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ','transliteration'=>'Ulaaa\'ikal lazeena la\'anahumul laahu fa-asammahum Wa-a\'maaa absaarahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>24,'arabic_text'=>'أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ','transliteration'=>'Afalaa yatadabbaroonal Qur-aana am \'alaa quloobin aqfaaluhaa','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>25,'arabic_text'=>'إِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ','transliteration'=>'Innal lazeenar taddoo \'alaaa adbaarihim min ba\'di maa tabaiyana lahumul hudash Shaitaanu sawwala lahum Wa-amlaa lahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>26,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمۡ فِي بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ','transliteration'=>'Zaalika bi-annahum qaaloo lillazeena karihoo maa nazzalal laahu sanutee\'ukum fee ba\'dil amri wallaahu ya\'lamu israarahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>27,'arabic_text'=>'فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ','transliteration'=>'Fakaifa izaa tawaffat-humul malaaa\'ikatu yadriboona wujoohahum Wa-adbaa-rahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>28,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ','transliteration'=>'Zaalika bi-annahumut taba\'oo maaa askhatal laaha Wa-karihoo ridwaanahoo fa-ahbata a\'maalahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>29,'arabic_text'=>'أَمۡ حَسِبَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخۡرِجَ ٱللَّهُ أَضۡغَٰنَهُمۡ','transliteration'=>'Am hasibal lazeena fee quloobihim maradun al laien yukhrijal laahu adghaanahum','page_number'=>509,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>30,'arabic_text'=>'وَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِي لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ يَعۡلَمُ أَعۡمَٰلَكُمۡ','transliteration'=>'Wa-law nashaaa\'u la-arainaakahum fala-\'araftahum bi-seemaahum; Wa-lata\'rifan-nahum fee lahnil qawl; wallaahu ya\'lamu a\'maalakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>31,'arabic_text'=>'وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ','transliteration'=>'Wa-lanabluwannakum hattaa na\'lamal mujaahideena minkum wassaabireena Wa-nabluwa akhbaarakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>32,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ وَشَآقُّواْ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَىٰ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗا وَسَيُحۡبِطُ أَعۡمَٰلَهُمۡ','transliteration'=>'Innal lazeena kafaroo Wa-saddoo \'an sabeelil laahi Wa-shaaaqqur Rasoola min ba\'di maa tabaiyana lahumul hudaa laien yadurrul laaha shai\'anw Wa-sa-yuhbitu a\'maalahum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>33,'arabic_text'=>'۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo atee\'ul laaha Wa-atee\'ur Rasoola Wa-laa tubtilooo a\'maalakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>34,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡ','transliteration'=>'Innal lazeena kafaroo Wa-saddoo \'an sabeelil laahi summa maatoo Wa-hum kuffaarun falaien yaghfiral laahu lahum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>35,'arabic_text'=>'فَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن يَتِرَكُمۡ أَعۡمَٰلَكُمۡ','transliteration'=>'Falaa tahinoo Wa-tad\'ooo ilas salmi Wa-antumul a\'lawna wallaahu ma\'akum Wa-lany yatirakum a\'maalakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>36,'arabic_text'=>'إِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ','transliteration'=>'Innamal hayaatud dunyaa la\'ibunw Wa-lahw; Wa-in tu\'minoo Wa-tattaqoo yu\'tikum ujoorakum Wa-laa yas\'alkum amwaalakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>37,'arabic_text'=>'إِن يَسۡـَٔلۡكُمُوهَا فَيُحۡفِكُمۡ تَبۡخَلُواْ وَيُخۡرِجۡ أَضۡغَٰنَكُمۡ','transliteration'=>'Ien yas\'alkumoohaa fa-yuhfikum tabkhaloo Wa-yukhrij adghaanakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>47,'ayah_number'=>38,'arabic_text'=>'هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم','transliteration'=>'Haaa antum haaa\'ulaaa\'i tud\'awna litunfiqoo fee sabeelillaahi faminkum many yabkhalu Wa-many yabkhal fa-innamaa yabkhalu \'an nafsih; wallaahu Ghaniyyu Wa-antumul fuqaraaa\'; Wa-in tatawallaw yastabdil qawman ghairakum summa laa yakoonooo amsaalakum','page_number'=>510,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            /* Surah 48: The Victory (Al-Fath) */
            ['surah_id'=>48,'ayah_number'=>1,'arabic_text'=>'إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا','transliteration'=>'Innaa fatahnaa laka Fatham Mubeenaa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>2,'arabic_text'=>'لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا','transliteration'=>'Liyaghfira lakal laahu maa taqaddama min zanbika Wa-maa ta-akhkhara Wa-yutimma ni\'matahoo \'alaika Wa-yahdiyaka siraatan mustaqeema','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>3,'arabic_text'=>'وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا','transliteration'=>'Wa-yansurakal laahu nasran \'azeezaa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>4,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا','transliteration'=>'Huwal lazeee anzalas sakeenata fee quloobil mu\'mineena liyazdaadooo eemaanamma\'a eemaanihim; Wa-lillaahi junoodus samawaati wal ard; Wa-kaanal laahu \'Aleeman Hakeemaa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>5,'arabic_text'=>'لِّيُدۡخِلَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِيمٗا','transliteration'=>'Liyudkhilal mu\'mineena walmu\'minaati jannaatin tajree min tahtihal anhaaru khaalideena feehaa Wa-yukaffira \'anhum saiyyi-aatihim; Wa-kaana zaalika \'indal laahi fawzan \'azeemaa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>6,'arabic_text'=>'وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَيۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرٗا','transliteration'=>'Wa-yu\'azzibal munaafiqeena walmunaafiqaati wal-mushrikeena walmushrikaatiz zaaanneena billaahi zannas saw\'; \'alaihim daaa\'iratus saw\'i Wa-ghadibal laahu \'alaihim Wa-la\'anahum Wa-a\'adda lahum jahannama Wa-saaa-at maseeraa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>7,'arabic_text'=>'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','transliteration'=>'Wa-lillaahi junoodus samaawaati wal-ard; Wa-kaanal laahu \'azeezan hakeema','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>8,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا','transliteration'=>'Innaaa arsalnaaka shaahi-danw Wa-mubashshiranw Wa-nazeera','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>9,'arabic_text'=>'لِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا','transliteration'=>'Litu-minoo billaahi Wa-Rasoolihee Wa-tu\'azziroohu watuwaqqiroohu watusabbi-hoohu bukratanw Wa-aseelaa','page_number'=>511,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>10,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمٗا','transliteration'=>'Innal lazeena yubaayi\'oonaka innamaa yubaayi\'oonal laaha yadul laahi fawqa aydeehim; faman nakasa fainnamaa yankusu \'alaa nafsihee Wa-man awfaa bimaa \'aahada \'alaihullaaha fasa yu\'teehi ajran \'azeemaa','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>11,'arabic_text'=>'سَيَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا','transliteration'=>'Sa-yaqoolu lakal mukhal-lafoona minal A\'raabi shaighalatnaaa amwaalunaa Wa-ahloonaa fastaghfir lanaa; yaqooloona bi-alsinatihim maa laisa fee quloobihim; qul famaien yamliku lakum minal laahi shai\'an in araada bikum darran aw araada bikum naf\'aa; bal kaanal laahu bimaa ta\'maloona Khabeeraa','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>12,'arabic_text'=>'بَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورٗا','transliteration'=>'Bal zanantum al laien yanqalibar Rasoolu walmu\'minoona ilaaa ahleehim abadanw Wa-zuyyina zaalika fee quloobikum Wa-zanantum zannnas saw\'i Wa-kuntum qawmam booraa','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>13,'arabic_text'=>'وَمَن لَّمۡ يُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرٗا','transliteration'=>'Wa-mal lam yu\'mim billaahi Wa-Rasoolihee fainnaaa a\'tadnaa lilkaafireena sa\'eeraa','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>14,'arabic_text'=>'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا','transliteration'=>'Wa-lillaahii mulkus samaawaati wal-ard; yaghfiru limaien yashaaa\'u Wa-yu\'azzibu maien yashaaa\'; Wa-kaanal laahu Ghafoorar Raheemaa','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>15,'arabic_text'=>'سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا','transliteration'=>'Sa-yaqoolul mukhalla-foona izan talaqtum ilaa maghaanima litaakhuzoohaa zaroonaa nattabi\'kum yureedoona any yubaddiloo Kalaamallaah; qul lan tattabi\'oonaa kazaalikum qaalal laahu min qablu fasa yaqooloona bal tahsudoonanna; bal kaanoo laa yafqahoona illaa qaleela','page_number'=>512,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>16,'arabic_text'=>'قُل لِّلۡمُخَلَّفِينَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُوْلِي بَأۡسٖ شَدِيدٖ تُقَٰتِلُونَهُمۡ أَوۡ يُسۡلِمُونَۖ فَإِن تُطِيعُواْ يُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنٗاۖ وَإِن تَتَوَلَّوۡاْ كَمَا تَوَلَّيۡتُم مِّن قَبۡلُ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا','transliteration'=>'Qul lilmukhallafeena minal A\'raabi satud\'awna ilaa qawmin ulee baasin shadeedin tuqaati-loonahum aw yuslimoona fa-in tutee\'oo yu\'tikumul laahu ajran hasananw Wa-in tatawallaw kamaa tawallaitum min qablu yu\'azzibkum \'azaaban aleemaa','page_number'=>513,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>17,'arabic_text'=>'لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا','transliteration'=>'Laisa \'alal a\'maa harajunw Wa-laa \'alal a\'raji harajunw Wa-laa \'alal mareedi haraj\' Wa-maien yutil\'il laaha Wa-Rasoolahoo yudkhilhu jannaatin tajree min tahtihal anhaaru Wa-maien yatawalla yu\'azzibhu \'azaaban aleemaa','page_number'=>513,'juz_number'=>26,'hizb_number'=>51,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>18,'arabic_text'=>'۞ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا','transliteration'=>'Laqad radiyal laahu \'anil mu\'mineena iz yubaayi-\'oonaka tahtash shajarati fa\'alima maa fee quloobihim fa-anzalas sakeenata \'alaihim Wa-asaa-bahum fat-han qareebaa','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>19,'arabic_text'=>'وَمَغَانِمَ كَثِيرَةٗ يَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا','transliteration'=>'Wa-maghaanima kaseera-taien yaakhuzoonahaa; Wa-kaanal laahu \'Azeezan Hakeemaa','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>20,'arabic_text'=>'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ وَكَفَّ أَيۡدِيَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةٗ لِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا','transliteration'=>'Wa\'adakumul laahu ma-ghaanima kaseeratan taakhuzoo-nahaa fa\'ajjala lakum haazihee Wa-kaffa aydiyan naasi \'ankum Wa-litakoona aayatal lilmu\'mineena Wa-yahdiyakum siraatam mustaqeema','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>21,'arabic_text'=>'وَأُخۡرَىٰ لَمۡ تَقۡدِرُواْ عَلَيۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا','transliteration'=>'Wa-ukhraa lam taqdiroo \'alaihaa qad ahaatal laahu bihaa; Wa-kaanal laahu \'alaa kulli shai\'in qadeera','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>22,'arabic_text'=>'وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُواْ لَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا','transliteration'=>'Wa-law qaatalakumul lazeena kafaroo la-wallawul adbaara summa laa yajidoona waliyanw-wa laa naseeraa','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>23,'arabic_text'=>'سُنَّةَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا','transliteration'=>'Sunnatal laahil latee qad khalat min qablu Wa-lan tajida lisunnatil laahi tabdeelaa','page_number'=>513,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>24,'arabic_text'=>'وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا','transliteration'=>'Wa-Huwal lazee kaffa aydiyahum \'ankum Wa-aydiyakum \'anhum bibatni Makkata mim ba\'di an azfarakum \'alaihim; Wa-kaanal laahu bimaa ta\'maloona Baseera','page_number'=>514,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>25,'arabic_text'=>'هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا','transliteration'=>'Humul lazeena kafaroo Wa-saddookum \'anil-Masjidil-Haraami walhadya ma\'koofan any yablugha mahillah; Wa-law laa rijaalum mu\'minoona Wa-nisaaa\'um mu\'minaatul lam ta\'lamoohum an tata\'oohum fatuseebakum minhum ma\'arratum bighairi \'ilmin liyud khilal laahu fee rahmatihee many yashaaa\'; law tazayyaloo la\'azzabnal lazeena kafaroo minhum \'azaaban aleema','page_number'=>514,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>26,'arabic_text'=>'إِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا','transliteration'=>'Iz ja\'alal lazeena kafaroo fee quloobihimul hamiyyata hamiyyatal jaahiliyyati fa-anzalal laahu sakeenatahoo \'alaa Rasoolihee Wa-\'alal mu-mineena Wa-alzamahum kalimatat taqwaa Wa-kaanooo ahaqqa bihaa Wa-ahlahaa; Wa-kaanal laahu bikulli shai\'in Aleema','page_number'=>514,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>27,'arabic_text'=>'لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتۡحٗا قَرِيبًا','transliteration'=>'Laqad sadaqal laahu Rasoolahur ru\'yaa bilhaqq, latadkhulunnal Masjidal Haraama in shaaa\'al laahu aamineena muhalliqeena ru\'oosakum Wa-muqassireena laa takhaafoona fa\'alima maa lam ta\'lamoo faja\'ala min dooni zaalika fathan qareebaa','page_number'=>514,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>28,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا','transliteration'=>'Huwal lazeee arsala Rasoolahoo bilhudaa Wa-deenil haqqi liyuzhirahoo \'alad deeni kullih; Wa-kafaa billaahi Shaheeda','page_number'=>514,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>48,'ayah_number'=>29,'arabic_text'=>'مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا','transliteration'=>'Muhammadur Rasoolul laah; wallazeena ma\'ahooo ashiddaaa\'u \'alal kuffaaari ruhamaaa\'u bainahum taraahum rukka\'an sujjadaien yabtaghoona fadlam minal laahi Wa-ridwaanan seemaahum fee wujoohihim min asaris sujood; zaalika masaluhum fit tawraah; Wa-masaluhum fil Injeeli kazar\'in akhraja shat-\'ahoo fa-\'aazarahoo fastaghlaza fastawaa \'alaa sooqihee yu\'jibuz zurraa\'a liyagheeza bihimul kuffaar; wa\'adal laahul lazeena aamanoo Wa-\'amilus saalihaati minhum maghfiratanw Wa-ajran \'azeemaa','page_number'=>515,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            /* Surah 49: The Rooms (Al-Hujurat) */
            ['surah_id'=>49,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo la tuqaddimoo baina yada-yil laahi Wa-Rasoolihee wattaqul laah; innal laaha samee\'un \'Aleem','page_number'=>515,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>2,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo laa tarfa\'ooo aswaatakum fawqa sawtin Nabiyyi Wa-laa tajharoo lahoo bilqawli kajahri ba\'dikum liba-\'din an tahbata a-\'maalukum Wa-antum laa tash\'uroon','page_number'=>515,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>3,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ','transliteration'=>'Innal lazeena yaghud-doona aswaatahum \'inda Rasoolil laahi ulaaa\'ikal lazeenam tah-anal laahu quloobahum littaqwaa; lahum maghfiratunw waajrun \'azeem','page_number'=>515,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>4,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ','transliteration'=>'Innal lazeena yunaadoo-naka minw waraaa\'il hujuraati aksaruhum laa ya\'qiloon','page_number'=>515,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>5,'arabic_text'=>'وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرٗا لَّهُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Wa-law annahum sabaroo hatta takhruja ilaihim lakaana khairal lahum; wallaahu Ghafoorur Raheem','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>6,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo in jaaa\'akum faasqum binaba-in fatabaiyanooo an tuseeboo qawmam bijahalatin fatusbihoo \'alaa maa fa\'altum naadimeen','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>7,'arabic_text'=>'وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ','transliteration'=>'Wa\'lamooo anna feekum Rasoolal laah; law yutee\'ukum fee kaseerim minal amrila \'anittum Wa-laakinnal laaha habbaba ilaikumul eemaana Wa-zaiyanahoo fee quloobikum Wa-karraha ilaikumul kufra walfusooqa wal\'isyaan; ulaaaika humur raashidoon','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>8,'arabic_text'=>'فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Fadlam minal laahi Wa-ni\'mah; wallaahu \'Aleemun Hakeem','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>9,'arabic_text'=>'وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ','transliteration'=>'Wa-in taaa\'ifataani minal mu\'mineena naqtataloo fa-aslihoo bainahumaa; fa-im baghat ihdaahumaa \'alal ukhraa faqaatilul latee tabghee hattaa tafeee\'a ilaaa amril laah; fa-in faaa\'at fa-aslihoo bainahumaa bil\'adli Wa-aqsitoo, innal laaha yuhibbul muqsiteen','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>10,'arabic_text'=>'إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ','transliteration'=>'Innamal mu\'minoona ikhwatun fa-aslihoo baina akhawaykum wattaqul laaha la\'allakum turhamoon','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>11,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo laa yaskhar qawmum min qawmin \'asaaa aien yakoonoo khairam minhum Wa-laa nisaaa\'um min nisaaa\'in \'Asaaa ay yakunna khairam minhunna Wa-laa talmizooo anfusakum Wa-laa tanaabazoo bil alqaab; bi\'sal ismul fusooqu ba\'dal eemaan; Wa-mal-lam yatub fa-ulaaa\'ika humuz zaalimoon','page_number'=>516,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>12,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanuj taniboo kaseeram minaz zanni inna ba\'daz zanni ismunw Wa-laa tajassasoo Wa-la yaghtab ba\'dukum ba\'daa; a-yuhibbu ahadukum aien yaakula lahma akheehi maitan fakarih-tumooh; wattaqul laa; innal laaha tawwaabur Raheem','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>13,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ','transliteration'=>'Yaaa-ayyuhan naasu innaa khalaqnaakum min zakarinw Wa-unsaa Wa-ja\'alnaakum shu\'oobanw Wa-qabaaa\'ila lita\'aarafoo inna akramakum \'indal laahi atqaakum innal laaha \'Aleemun khabeer','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>14,'arabic_text'=>'۞ قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Qaalatil-A \'raabu aamannaa qul lam tu\'minoo Wa-laakin qoolooo aslamnaa Wa-lamma yadkhulil eemaanu fee quloobikum Wa-in tutee\'ul laaha Wa-Rasoolahoo laa yalitkum min a\'maalikum shai\'aa; innal laaha Ghafoorur Raheem','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>15,'arabic_text'=>'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ','transliteration'=>'Innamal muu\'minoonal lazeena aamanoo billaahi Wa-Rasoolihee summa lam yartaaboo Wa-jaahadoo biamwaalihim Wa-anfusihim fee sabeelil laah; ulaaaika humus saadiqoon','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>16,'arabic_text'=>'قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Qul atu\'allimoonal laaha bideenikum wallaahu ya\'lamu maa fis samaawaati Wa-maa fil ard; wallaahu bikulli shai\'in \'Aleem','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>17,'arabic_text'=>'يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Yamunnoona \'alaika an aslamoo qul laa tamunnoo \'alaiya Islaamakum balil laahu yamunnu \'alaikum an hadaakum lil-eemaani in kuntum saadiqeen','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>49,'ayah_number'=>18,'arabic_text'=>'إِنَّ ٱللَّهَ يَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Innal laaha ya\'lamu ghaibas samaawaati wal-ard; wallaahu baseerum bimaa ta\'maloon','page_number'=>517,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            /* Surah 50: The Letter "Qaf" (Qaf) */
            ['surah_id'=>50,'ayah_number'=>1,'arabic_text'=>'قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ','transliteration'=>'Qaaaf; wal-Qur-aanil Majeed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>2,'arabic_text'=>'بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡ فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ','transliteration'=>'Bal \'ajibooo an jaa\'ahum munzirum minhum faqaalal kaafiroona haazaa shai\'un \'ajeeb','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>3,'arabic_text'=>'أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗاۖ ذَٰلِكَ رَجۡعُۢ بَعِيدٞ','transliteration'=>'A-izaa mitnaa Wa-kunnaa turaaban zaalika raj\'um ba\'eed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>4,'arabic_text'=>'قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ','transliteration'=>'Qad \'alimnaa maa tanqu-sul ardu minhum Wa-\'indanaa Kitaabun Hafeez','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>5,'arabic_text'=>'بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ','transliteration'=>'Bal kazzaboo bilhaqqi lammaa jaaa\'ahum fahum feee amrim mareej','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>6,'arabic_text'=>'أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٖ','transliteration'=>'Afalam yanzurooo ilas samaaa\'i fawqahum kaifa banainaahaa Wa-zaiyannaahaa Wa-maa lahaa min furooj','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>7,'arabic_text'=>'وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ','transliteration'=>'Wal-arda madadnaahaa Wa-alqainaa feehaa rawaasiya Wa-ambatnaa feehaa min kulli zawjim baheej','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>8,'arabic_text'=>'تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ','transliteration'=>'Tabsiratanw Wa-zikraa likulli \'abdim muneeb','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>9,'arabic_text'=>'وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتٖ وَحَبَّ ٱلۡحَصِيدِ','transliteration'=>'Wa-nazzalnaa minas samaaa\'i maaa\'am mubaarakan fa-ambatnaa bihee jannaatinw Wa-habbal haseed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>10,'arabic_text'=>'وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ','transliteration'=>'Wannakhla baasiqaatil laha tal\'un nadeed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>11,'arabic_text'=>'رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ','transliteration'=>'Rizqal lil\'ibaad, Wa-ahyainaa bihee baldatam maitaa; kazaalikal khurooj','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>12,'arabic_text'=>'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ','transliteration'=>'Kazzabat qablahum qawmu Noohinw Wa-Ashaabur Rassi Wa-Samood','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>13,'arabic_text'=>'وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ','transliteration'=>'Wa-\'Aadunw Wa-Fir\'awnu wikhwaanu loot','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>14,'arabic_text'=>'وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ','transliteration'=>'Wa-Ashaabul Aykati Wa-qawmu Tubba\'; kullun kazzabar Rusula fahaqqa wa\'eed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>15,'arabic_text'=>'أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسٖ مِّنۡ خَلۡقٖ جَدِيدٖ','transliteration'=>'Afa\'a-yeenaa bilkhalqil awwal; bal hum fee labsim min khalqin jadeed','page_number'=>518,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>16,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ','transliteration'=>'Wa-laqad khalaqnal insaana Wa-na\'lamu maa tuwaswisu bihee nafsuhoo Wa-Nahnu aqrabu ilaihi min hablil wareed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>17,'arabic_text'=>'إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ','transliteration'=>'Iz yatalaqqal mutalaqqi-yaani \'anil yameeni Wa-\'anish shimaali qa\'eed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>18,'arabic_text'=>'مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ','transliteration'=>'Maa yalfizu min qawlin illaa ladaihi raqeebun \'ateed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>19,'arabic_text'=>'وَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ','transliteration'=>'Wa-jaaa\'at sakratul mawti bilhaqq; zaalika maa kunta minhu taheed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>20,'arabic_text'=>'وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ','transliteration'=>'Wa-nufikha fis Soor; zaalika yawmul wa\'eed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>21,'arabic_text'=>'وَجَآءَتۡ كُلُّ نَفۡسٖ مَّعَهَا سَآئِقٞ وَشَهِيدٞ','transliteration'=>'Wa-jaaa\'at kullu nafsim ma\'ahaa saaa\'iqunw Wa-shaheed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>22,'arabic_text'=>'لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ','transliteration'=>'Laqad kunta fee ghaf-latim min haazaa fakashafnaa \'anka ghitaaa\'aka fabasarukal yawma hadeed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>23,'arabic_text'=>'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ','transliteration'=>'Wa-qaala qareenuhoo haazaa maa ladaiya \'ateed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>24,'arabic_text'=>'أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٖ','transliteration'=>'Alqiyaa fee Jahannama kulla kaffaarin \'aneed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>25,'arabic_text'=>'مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٖ مُّرِيبٍ','transliteration'=>'Mannaa\'il lilkhayri mu\'tadim mureeb','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>26,'arabic_text'=>'ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ','transliteration'=>'Allazee ja\'ala ma\'al laahi ilaahan aakhara fa-alqiyaahu fil \'azaabish shadeed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>27,'arabic_text'=>'۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ','transliteration'=>'Qaala qareenuhoo Rabbanaa maaa atghaituhoo Wa-laakin kaana fee dalaalin ba\'eed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>28,'arabic_text'=>'قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ','transliteration'=>'Qaala laa takhtasimoo ladaayya Wa-qad qaddamtu ilaikum bilwa\'eed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>29,'arabic_text'=>'مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّٰمٖ لِّلۡعَبِيدِ','transliteration'=>'Maa yubaddalul qawlu ladaiya Wa-maaa ana bizal-laamil lil\'abeed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>30,'arabic_text'=>'يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ','transliteration'=>'Yawma naqoolu li\'jahannama halim talaati Wa-taqoolu hal mim mazeed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>31,'arabic_text'=>'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ','transliteration'=>'Wa-uzlifatil jannatu lil-muttaqeena ghaira ba\'eed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>32,'arabic_text'=>'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ','transliteration'=>'Haaza maa too\'adoona likulli awwaabin hafeez','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>33,'arabic_text'=>'مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ','transliteration'=>'Man khashiyar Rahmaana bilghaibi Wa-jaaa\'a biqalbim muneeb','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>34,'arabic_text'=>'ٱدۡخُلُوهَا بِسَلَٰمٖۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ','transliteration'=>'Udkhuloohaa bisalaamin zaalika yawmul khulood','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>35,'arabic_text'=>'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدٞ','transliteration'=>'Lahum maa yashaaa\'oona feehaa Wa-ladainaa mazeed','page_number'=>519,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>36,'arabic_text'=>'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ','transliteration'=>'Wa-kam ahlaknaa qablahum min qarnin hum ashaddu minhum batshan fanaqqaboo fil bilaad, hal mim mahees','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>37,'arabic_text'=>'إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ','transliteration'=>'Inna fee zaalika lazikraa liman kaana lahoo qalbun aw alqas sam\'a Wa-huwa shaheed','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>38,'arabic_text'=>'وَلَقَدۡ خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ وَمَا مَسَّنَا مِن لُّغُوبٖ','transliteration'=>'Wa-laqad khalaqnas samaawaati wal-arda Wa-maa bainahumaa fee sittati ayyaamin Wa-maa massanaa mil lughoob','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>39,'arabic_text'=>'فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ','transliteration'=>'Fasbir \'alaa maa yaqooloona Wa-sabbih bihamdi Rabbika qabla tuloo\'ish shamsi Wa-qablal ghuroob','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>40,'arabic_text'=>'وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ','transliteration'=>'Wa-minal laili fasabbih-hu Wa-adbaaras sujood','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>41,'arabic_text'=>'وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانٖ قَرِيبٖ','transliteration'=>'Wastami\' yawma yunaa-dil munaadi mim makaanin qareeb','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>42,'arabic_text'=>'يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ','transliteration'=>'Yawma yasmaoonas sai-hata bilhaqq zaalika yawmul khurooj','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>43,'arabic_text'=>'إِنَّا نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ','transliteration'=>'Innaa Nahnu nuhyee Wa-numeetu Wa-ilainal maseer','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>44,'arabic_text'=>'يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعٗاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرٞ','transliteration'=>'Yawma tashaqqaqul ardu \'anhum siraa\'aa; zaalika hashrun \'alainaa yaseer','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>50,'ayah_number'=>45,'arabic_text'=>'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ','transliteration'=>'Nahnu a\'lamu bimaa yaqooloona Wa-maaa anta \'alaihim bijabbaarin fazakkir bil-quraani maien yakhaafu wa\'eed','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            /* Surah 51: The Winnowing Winds (Adh-Dhariyat) */
            ['surah_id'=>51,'ayah_number'=>1,'arabic_text'=>'وَٱلذَّٰرِيَٰتِ ذَرۡوٗا','transliteration'=>'Waz-zaariyaati zarwaa','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>2,'arabic_text'=>'فَٱلۡحَٰمِلَٰتِ وِقۡرٗا','transliteration'=>'Falhaamilaati wiqraa','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>3,'arabic_text'=>'فَٱلۡجَٰرِيَٰتِ يُسۡرٗا','transliteration'=>'Faljaariyaati yusraa','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>4,'arabic_text'=>'فَٱلۡمُقَسِّمَٰتِ أَمۡرًا','transliteration'=>'Falmuqassimaati amraa','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>5,'arabic_text'=>'إِنَّمَا تُوعَدُونَ لَصَادِقٞ','transliteration'=>'Innamaa too\'adoona la-saadiq','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>6,'arabic_text'=>'وَإِنَّ ٱلدِّينَ لَوَٰقِعٞ','transliteration'=>'Wa-innad deena la-waaqi\'','page_number'=>520,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>7,'arabic_text'=>'وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ','transliteration'=>'Wassamaaa\'i zaatil hubuk','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>8,'arabic_text'=>'إِنَّكُمۡ لَفِي قَوۡلٖ مُّخۡتَلِفٖ','transliteration'=>'Innakum lafee qawlim mukhtalif','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>9,'arabic_text'=>'يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ','transliteration'=>'Yu\'faku \'anhu man ufik','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>10,'arabic_text'=>'قُتِلَ ٱلۡخَرَّٰصُونَ','transliteration'=>'Qutilal kharraasoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>11,'arabic_text'=>'ٱلَّذِينَ هُمۡ فِي غَمۡرَةٖ سَاهُونَ','transliteration'=>'Allazeena hum fee ghamratin saahoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>12,'arabic_text'=>'يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ','transliteration'=>'Yas\'aloona ayyaana yawmud Deen','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>13,'arabic_text'=>'يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ','transliteration'=>'Yawma hum \'alan naari yuftanoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>14,'arabic_text'=>'ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ','transliteration'=>'Zooqoo fitnatakum haa-zal lazee kuntum bihee tas-ta\'jiloon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>15,'arabic_text'=>'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ','transliteration'=>'Innal muttaqeena fee jannaatinw Wa-\'uyoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>16,'arabic_text'=>'ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ','transliteration'=>'Aakhizeena maaa aataahum Rabbuhum; innahum kaanoo qabla zaalika muhsineen','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>17,'arabic_text'=>'كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ','transliteration'=>'kaanoo qaleelam minal laili maa yahja\'oon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>18,'arabic_text'=>'وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ','transliteration'=>'Wa-bilashaari hum yastaghfiroon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>19,'arabic_text'=>'وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ','transliteration'=>'Wa-feee amwaalihim haqqul lissaaa\'ili walmahroom','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>20,'arabic_text'=>'وَفِي ٱلۡأَرۡضِ ءَايَٰتٞ لِّلۡمُوقِنِينَ','transliteration'=>'Wa-fil ardi aayaatul lilmooqineen','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>21,'arabic_text'=>'وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ','transliteration'=>'Wa-feee anfusikum; afalaa tubsiroon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>22,'arabic_text'=>'وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ','transliteration'=>'Wa-fis samaaa\'i rizqukum Wa-maa too\'adoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>23,'arabic_text'=>'فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ','transliteration'=>'Fawa-Rabbis samaaa\'i wal-ardi innahoo lahaqqum misla maa annakum tantiqoon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>24,'arabic_text'=>'هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ','transliteration'=>'Hal ataaka hadeesu daifi Ibraaheemal mukrameen','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>25,'arabic_text'=>'إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ','transliteration'=>'Iz dakhaloo \'alaihi faqaaloo salaaman qaala salaamun qawmum munkaroon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>26,'arabic_text'=>'فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ','transliteration'=>'Faraagha ilaaa ahlihee fajaaa\'a bi\'ijlin sameen','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>27,'arabic_text'=>'فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ','transliteration'=>'Faqarrabahooo ilaihim qaala alaa taakuloon','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>28,'arabic_text'=>'فَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٖ','transliteration'=>'Fa-awjasa minhum khee-fatan qaaloo laa takhaf Wa-bashsharoohu bighulaamin \'aleem','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>29,'arabic_text'=>'فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةٖ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمٞ','transliteration'=>'Fa-aqbalatim ra-atuhoo fee sarratin fasakkat wajhahaa Wa-qaalat \'ajoozun \'aqeem','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>30,'arabic_text'=>'قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ','transliteration'=>'Qaaloo kazaaliki qaala Rabbuki innahoo huwal hakeemul \'aleem','page_number'=>521,'juz_number'=>26,'hizb_number'=>52,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>31,'arabic_text'=>'۞ قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ','transliteration'=>'Qaala famaa khatbukum ayyuhal mursaloon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>32,'arabic_text'=>'قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ','transliteration'=>'Qaalooo innaaa ursilnaaa ilaa qawmim mujrimeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>33,'arabic_text'=>'لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةٗ مِّن طِينٖ','transliteration'=>'Linursila \'alaihim hijaa-ratam min teen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>34,'arabic_text'=>'مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ','transliteration'=>'Musawwamatan \'inda rabbika lilmusrifeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>35,'arabic_text'=>'فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Fa-akhrajnaa man kaana feehaa minal mu\'mineen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>36,'arabic_text'=>'فَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتٖ مِّنَ ٱلۡمُسۡلِمِينَ','transliteration'=>'Famaa wajadnaa feehaa ghaira baitim minal muslimeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>37,'arabic_text'=>'وَتَرَكۡنَا فِيهَآ ءَايَةٗ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ','transliteration'=>'Wa-taraknaa feehaaa aayatal lillazeena yakhaafoonal \'azaabal aleem','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>38,'arabic_text'=>'وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنٖ مُّبِينٖ','transliteration'=>'Wa-fee Moosaaa iz arsalnaahu ilaa Fir\'awna bisultaa-nim mubeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>39,'arabic_text'=>'فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونٞ','transliteration'=>'Fatawalla biruknihee Wa-qaala saahirun aw majnoon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>40,'arabic_text'=>'فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمٞ','transliteration'=>'Fa-akhaznaahu Wa-junoo-dahoo fanabaznaahum fil yammi Wa-huwa muleem','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>41,'arabic_text'=>'وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ','transliteration'=>'Wa-fee \'Aadin iz arsalnaa \'alaihimur reehal \'aqeem','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>42,'arabic_text'=>'مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ','transliteration'=>'Maa tazaru min shai\'in atat \'alaihi illaa ja\'alat-hu karrameem','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>43,'arabic_text'=>'وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينٖ','transliteration'=>'Wa-fee Samooda iz qeela lahum tamatta\'\'oo hattaa heen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>44,'arabic_text'=>'فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ وَهُمۡ يَنظُرُونَ','transliteration'=>'Fa\'ataw \'an amri Rabbihim fa-akhazal-humus saa\'iqatu Wa-hum yanzuroon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>45,'arabic_text'=>'فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامٖ وَمَا كَانُواْ مُنتَصِرِينَ','transliteration'=>'Famas tataa\'oo min qiyaaminw Wa-maa kaanoo muntasireen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>46,'arabic_text'=>'وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ','transliteration'=>'Wa-qawma Noohim min qablu innahum kaano qawman faasiqeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>47,'arabic_text'=>'وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ','transliteration'=>'Wassamaaa\'a banainaa-haa bi-aydinw Wa-innaa lamoosi\'oon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>48,'arabic_text'=>'وَٱلۡأَرۡضَ فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ','transliteration'=>'Wal-arda farashnaahaa fani\'mal maahidoon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>49,'arabic_text'=>'وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ','transliteration'=>'Wa-min kulli shai\'in khalaqnaa zawjaini la\'allakum tazakkaroon','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>50,'arabic_text'=>'فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ','transliteration'=>'Fafirrooo ilal laahi innee lakum minhu nazeerum mubeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>51,'arabic_text'=>'وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ','transliteration'=>'Wa-laa taj\'aloo ma\'al laahi ilaahan aakhara innee lakum minhu nazeerum mubeen','page_number'=>522,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>52,'arabic_text'=>'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ','transliteration'=>'Kazaalika maaa atal lazeena min qablihim mir Rasoolin illaa qaaloo saahirun aw majnoon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>53,'arabic_text'=>'أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ','transliteration'=>'Atawaasaw bih; bal hum qawmun taaghoon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>54,'arabic_text'=>'فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومٖ','transliteration'=>'Fatawalla \'anhum famaaa anta bimaloom','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>55,'arabic_text'=>'وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-zakkir fa-innaz zikraa tanfa\'ul mu\'mineen','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>56,'arabic_text'=>'وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ','transliteration'=>'Wa-maa khalaqtul jinna wal-insa illaa liya\'budoon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>57,'arabic_text'=>'مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ','transliteration'=>'Maaa ureedu minhum mir rizqinw Wa-maaa ureedu aien yut\'imoon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>58,'arabic_text'=>'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ','transliteration'=>'Innal laaha Huwar Razzaaqu Zul Quwwatil Mateen','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>59,'arabic_text'=>'فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبٗا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ','transliteration'=>'Fa-inna lillazeena zalamoo zanoobam misla zanoobi ashaabihim falaa yasta\'jiloon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>51,'ayah_number'=>60,'arabic_text'=>'فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ','transliteration'=>'Fawailul lillazeena kafaroo mien yawmihimul lazee yoo\'adoon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
