            ['surah_id'=>52,'ayah_number'=>1,'arabic_text'=>'وَٱلطُّورِ','transliteration'=>'Wat-Toor','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>2,'arabic_text'=>'وَكِتَٰبٖ مَّسۡطُورٖ','transliteration'=>'Wa-kitaabim mastoor','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>3,'arabic_text'=>'فِي رَقّٖ مَّنشُورٖ','transliteration'=>'Fee raqqim manshoor','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>4,'arabic_text'=>'وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ','transliteration'=>'Wal-baitil ma\'moor','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>5,'arabic_text'=>'وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ','transliteration'=>'Wassaqfil marfoo\'','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>6,'arabic_text'=>'وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ','transliteration'=>'Wal-bahril masjoor','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>7,'arabic_text'=>'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ','transliteration'=>'Inna \'azaaba Rabbika lawaaqi\'','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>8,'arabic_text'=>'مَّا لَهُۥ مِن دَافِعٖ','transliteration'=>'Maa lahoo min daafi\'','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>9,'arabic_text'=>'يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرٗا','transliteration'=>'Yawma tamoorus samaaa\'u mawraa','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>10,'arabic_text'=>'وَتَسِيرُ ٱلۡجِبَالُ سَيۡرٗا','transliteration'=>'Wa-taseerul jibaalu sairaa','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>11,'arabic_text'=>'فَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ','transliteration'=>'Fawailuien yawma-\'izil lil-mukaazzibeen','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>12,'arabic_text'=>'ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ','transliteration'=>'Allazeena hum fee khawdien yal\'aboon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>13,'arabic_text'=>'يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا','transliteration'=>'Yawma yuda\'-\'oona ilaa naari jahannama da\'-\'aa','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>14,'arabic_text'=>'هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ','transliteration'=>'Haazihin naarul latee kuntum bihaa tukazziboon','page_number'=>523,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>15,'arabic_text'=>'أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ','transliteration'=>'Afasihrun haazaaaa am antum laa tubsiroon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>16,'arabic_text'=>'ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Islawhaa fasbirooo aw laa tasbiroo sawaaa\'un \'alaikum innamaa tujzawna maa kuntum ta\'maloon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>17,'arabic_text'=>'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَنَعِيمٖ','transliteration'=>'Innal muttaqeena fee jannaatinw Wa-na\'eem','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>18,'arabic_text'=>'فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ','transliteration'=>'Faakiheena bimaaa aataahum rabbuhum Wa-waqaahum rabbuhum \'azaabal jaheem','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>19,'arabic_text'=>'كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Kuloo washraboo haneee-\'am bimaa kuntum ta\'maloon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>20,'arabic_text'=>'مُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ','transliteration'=>'Muttaki\'eena \'alaa sururim masfoofatinw Wa-zawwaj-naahum bihoorin \'een','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>21,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينٞ','transliteration'=>'Wallazeena aamanoo wattaba\'at-hum zurriyyatuhum bieemaanin alhaqnaa bihim zurriyyatahum Wa-maaa alatnaahum min \'amalihim min shai\'; kullum ri\'im bimaa kasaba raheen','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>22,'arabic_text'=>'وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ','transliteration'=>'Wa-amdadnaahum bifaa-kihatinw Wa-lahmim mimmaa yashtahoon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>23,'arabic_text'=>'يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ','transliteration'=>'Yatanaaza\'oona feehaa kaasal laa laghwun feehaa Wa-laa taaseem','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>24,'arabic_text'=>'۞ وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ','transliteration'=>'Wa-yatoofu \'alaihim ghilmaanul lahum ka-annahum lu\'lu\'um maknoon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>25,'arabic_text'=>'وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ','transliteration'=>'Wa-aqbala ba\'duhum \'alaa ba\'dien yatasaaa\'aloon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>26,'arabic_text'=>'قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ','transliteration'=>'Qaalooo innaa kunnaa qablu feee ahlinaa mushfiqeen','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>27,'arabic_text'=>'فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ','transliteration'=>'Famannnal laahu \'alainaa Wa-waqaanaa \'azaabas samoom','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>28,'arabic_text'=>'إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ','transliteration'=>'Innaa kunnaa min qablu nad\'oohu innahoo huwal barrur raheem','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>29,'arabic_text'=>'فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنٖ وَلَا مَجۡنُونٍ','transliteration'=>'Fazakkir famaaa anta bini\'mati rabbika bikaahininw Wa-laa majnoon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>30,'arabic_text'=>'أَمۡ يَقُولُونَ شَاعِرٞ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ','transliteration'=>'Am yaqooloona shaa\'irun natarabbasu bihee raibal manoon','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>31,'arabic_text'=>'قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ','transliteration'=>'Qul tarabbasoo fa-innee ma\'akum minal mutarabbiseen','page_number'=>524,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>32,'arabic_text'=>'أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ','transliteration'=>'Am taamuruhum ahlaamuhum bihaazaaa am hum qawmun taaghoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>33,'arabic_text'=>'أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ','transliteration'=>'Am yaqooloona taqawwalah; bal laa yu\'minoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>34,'arabic_text'=>'فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ','transliteration'=>'Falyaatoo bihadeesim misliheee in kaanoo saadiqeen','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>35,'arabic_text'=>'أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ','transliteration'=>'Am khuliqoo min ghairi shai\'in am humul khaaliqoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>36,'arabic_text'=>'أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ','transliteration'=>'Am khalaqus samaawaati wal-ard; bal laa yooqinoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>37,'arabic_text'=>'أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ','transliteration'=>'Am \'indahum khazaaa\'inu rabbika am humul musaitiroon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>38,'arabic_text'=>'أَمۡ لَهُمۡ سُلَّمٞ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنٖ مُّبِينٍ','transliteration'=>'Am lahum sullamuien yastami\'oona feehi falyaati mustami\'uhum bisultaanim mubeen','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>39,'arabic_text'=>'أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ','transliteration'=>'Am lahul banaatu Wa-lakumul banoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>40,'arabic_text'=>'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ','transliteration'=>'Am tas\'aluhum ajran fahum mim maghramim musqaloon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>41,'arabic_text'=>'أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ','transliteration'=>'Am \'indahumul ghaibu fahum yaktuboon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>42,'arabic_text'=>'أَمۡ يُرِيدُونَ كَيۡدٗاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ','transliteration'=>'Am yureedoona kaidan fallazeena kafaroo humul makeedoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>43,'arabic_text'=>'أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ','transliteration'=>'Am lahum ilaahun ghairul laa; subhaanal laahi \'ammaa yushrikoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>44,'arabic_text'=>'وَإِن يَرَوۡاْ كِسۡفٗا مِّنَ ٱلسَّمَآءِ سَاقِطٗا يَقُولُواْ سَحَابٞ مَّرۡكُومٞ','transliteration'=>'Wa-ien yaraw kisfam minas samaaa\'i saaqitaien yaqooloo sahaabum markoom','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>45,'arabic_text'=>'فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ','transliteration'=>'Fazarhum hatta yulaaqoo yawmahumul lazee feehi yus\'aqoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>46,'arabic_text'=>'يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ','transliteration'=>'Yawma laa yughnee \'anhum kaidumhum shai\'anw Wa-laa hum yunsaroon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>47,'arabic_text'=>'وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','transliteration'=>'Wa-inna lillazeena zalamoo \'azaaban doona zalika Wa-laakinna aksarahum laa ya\'lamoon','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>48,'arabic_text'=>'وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ','transliteration'=>'Wasbir lihukmi rabbika fa-innaka bi-a\'yuninaa Wa-sabbih bihamdi rabbika heena taqoom','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>52,'ayah_number'=>49,'arabic_text'=>'وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ','transliteration'=>'Wa-minal laili fasabbihhu Wa-idbaaran nujoom','page_number'=>525,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            /* Surah 53: The Star (An-Najm) */
            ['surah_id'=>53,'ayah_number'=>1,'arabic_text'=>'وَٱلنَّجۡمِ إِذَا هَوَىٰ','transliteration'=>'Wannajmi izaa hawaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>2,'arabic_text'=>'مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ','transliteration'=>'Maa dalla saahibukum Wa-maa ghawaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>3,'arabic_text'=>'وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ','transliteration'=>'Wa-maa yantiqu \'anil hawaaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>4,'arabic_text'=>'إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ','transliteration'=>'In huwa illaa Wahyuny yoohaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>5,'arabic_text'=>'عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ','transliteration'=>'Allamahoo shadeedul quwaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>6,'arabic_text'=>'ذُو مِرَّةٖ فَٱسۡتَوَىٰ','transliteration'=>'Zoo mirratin fastawaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>7,'arabic_text'=>'وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ','transliteration'=>'Wa-huwa bil-ufuqil a\'laa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>8,'arabic_text'=>'ثُمَّ دَنَا فَتَدَلَّىٰ','transliteration'=>'Summa danaa fatadalla','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>9,'arabic_text'=>'فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ','transliteration'=>'Fakaana qaaba qawsaini aw adnaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>10,'arabic_text'=>'فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ','transliteration'=>'Fa-awhaaa ilaa \'abdihee maaa awhaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>11,'arabic_text'=>'مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ','transliteration'=>'Maa kazabal fu\'aadu maa ra-aa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>12,'arabic_text'=>'أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ','transliteration'=>'Afatumaaroonahoo \'alaa maa yaraa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>13,'arabic_text'=>'وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ','transliteration'=>'Wa-laqad ra-aahu nazlatan ukhraa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>14,'arabic_text'=>'عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ','transliteration'=>'Inda sidratil muntaha','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>15,'arabic_text'=>'عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ','transliteration'=>'Indahaa jannatul maawaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>16,'arabic_text'=>'إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ','transliteration'=>'Iz yaghshas sidrata maa yaghshaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>17,'arabic_text'=>'مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ','transliteration'=>'Maa zaaghal basaru Wa-maa taghaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>18,'arabic_text'=>'لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ','transliteration'=>'Laqad ra-aa min aayaati Rabbihil kubraaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>19,'arabic_text'=>'أَفَرَءَيۡتُمُ ٱللَّٰتَ وَٱلۡعُزَّىٰ','transliteration'=>'Afara\'aytumul laata wal-\'uzzaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>20,'arabic_text'=>'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ','transliteration'=>'Wa-manaatas saalisatal ukhraa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>21,'arabic_text'=>'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ','transliteration'=>'A-lakumuz zakaru Wa-lahul unsaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>22,'arabic_text'=>'تِلۡكَ إِذٗا قِسۡمَةٞ ضِيزَىٰٓ','transliteration'=>'Tilka izan qismatun deezaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>23,'arabic_text'=>'إِنۡ هِيَ إِلَّآ أَسۡمَآءٞ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ','transliteration'=>'In hiya illaaa asmaaa\'un sammaitumoohaaa antum Wa-aabaaa\'ukum maaa anzalal laahu bihaa min sultaan; ien yattabi\'oona illaz zanna Wa-maa tahwal anfusu Wa-laqad jaaa\'ahum mir Rabbihimul hudaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>24,'arabic_text'=>'أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ','transliteration'=>'Am lil-insaani maa taman-naa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>25,'arabic_text'=>'فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ','transliteration'=>'Falillaahil aakhiratu wal-oolaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>26,'arabic_text'=>'۞ وَكَم مِّن مَّلَكٖ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ','transliteration'=>'Wa-kam mim malakin fis samaawaati laa tughnee shafaa\'atuhum shai\'an illaa mim ba\'di aien yaazanal laahu limaien yashaaa\'u Wa-yardaa','page_number'=>526,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>27,'arabic_text'=>'إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ','transliteration'=>'innal lazeena laa yu\'minoona bil-aakhirati la-yusammoonal malaaa\'ikata tasmiyatal unsaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>28,'arabic_text'=>'وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـٔٗا','transliteration'=>'Wa-maa lahum bihee min \'ilmin ien yattabi\'oona illaz zanna Wa-innaz zanna laa yughnee minal haqqi shai\'aa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>29,'arabic_text'=>'فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا','transliteration'=>'Fa-a\'rid \'am man tawallaa \'an zikrinaa Wa-lam yurid illal hayaatad dunyaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>30,'arabic_text'=>'ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ','transliteration'=>'Zalika mablaghuhum minal \'ilm; inna rabbaka huwa a\'lamu biman dalla \'an sabee-lihee Wa-huwa a\'lamu bimanih tadaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>31,'arabic_text'=>'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى','transliteration'=>'Wa-lillaahi maa fis samaawaati Wa-maa fil ardi liyajziyal lazeena asaaa\'oo bimaa \'amiloo Wa-yajziyal lazeena ahsanoo bilhusnaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>32,'arabic_text'=>'ٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةٞ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ','transliteration'=>'Allazeena yajtaniboona kabaaa\'iral ismi walfawaa-hisha illal lamam; inna rabbaka waasi\'ul maghfirah; huwa a\'lamu bikum iz ansha-akum minal ardi Wa-iz antum ajinnatun fee butooni umma-haatikum falaa tuzakkooo anfusakum huwa a\'lamu bimanit taqaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>33,'arabic_text'=>'أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ','transliteration'=>'Afara\'ayatal lazee tawallaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>34,'arabic_text'=>'وَأَعۡطَىٰ قَلِيلٗا وَأَكۡدَىٰٓ','transliteration'=>'Wa-a\'taa qaleelanw Wa-akdaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>35,'arabic_text'=>'أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ','transliteration'=>'A\'indahoo \'ilmul ghaibi fahuwa yaraa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>36,'arabic_text'=>'أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ','transliteration'=>'Am lam yunabbaa bimaa fee suhuhfi Moosa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>37,'arabic_text'=>'وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ','transliteration'=>'Wa-Ibraaheemal lazee waffaaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>38,'arabic_text'=>'أَلَّا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰ','transliteration'=>'Allaa taziru waaziratunw wizra ukhraa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>39,'arabic_text'=>'وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ','transliteration'=>'Wa-al laisa lil-insaani illaa maa sa\'aa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>40,'arabic_text'=>'وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ','transliteration'=>'Wa-anna sa\'yahoo sawfa yuraa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>41,'arabic_text'=>'ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ','transliteration'=>'Summa yujzaahul jazaaa \'al-awfaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>42,'arabic_text'=>'وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ','transliteration'=>'Wa-anna ilaa rabbikal muntahaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>43,'arabic_text'=>'وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ','transliteration'=>'Wa-annahoo huwa adhaka Wa-abkaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>44,'arabic_text'=>'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا','transliteration'=>'Wa-annahoo huwa amaata Wa-ahyaa','page_number'=>527,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>45,'arabic_text'=>'وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ','transliteration'=>'Wa-annahoo khalaqaz zawjainiz zakara wal-unsaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>46,'arabic_text'=>'مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ','transliteration'=>'Min nutfatin izaa tumnaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>47,'arabic_text'=>'وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ','transliteration'=>'Wa-anna \'alaihin nash-atal ukhraa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>48,'arabic_text'=>'وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ','transliteration'=>'Wa-annahoo huwa aghnaa Wa-aqnaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>49,'arabic_text'=>'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ','transliteration'=>'Wa-annahoo huwa rabbush shi\'raa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>50,'arabic_text'=>'وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ','transliteration'=>'Wa-annahooo ahlak-a \'Aadanil oolaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>51,'arabic_text'=>'وَثَمُودَاْ فَمَآ أَبۡقَىٰ','transliteration'=>'Wa-samooda famaaa abqaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>52,'arabic_text'=>'وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ','transliteration'=>'Wa-qawma Noohim min qablu innahum kaanoo hum azlama Wa-atghaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>53,'arabic_text'=>'وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ','transliteration'=>'Wal-mu\'tafikata ahwaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>54,'arabic_text'=>'فَغَشَّىٰهَا مَا غَشَّىٰ','transliteration'=>'Faghashshaahaa maa ghashshaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>55,'arabic_text'=>'فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ','transliteration'=>'Fabi-ayyi aalaaa\'i Rabbika tatamaaraa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>56,'arabic_text'=>'هَٰذَا نَذِيرٞ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ','transliteration'=>'Haazaa nazeerum minan nuzuril oolaa','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>57,'arabic_text'=>'أَزِفَتِ ٱلۡأٓزِفَةُ','transliteration'=>'Azifatil aazifah','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>58,'arabic_text'=>'لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ','transliteration'=>'Laisa lahaa min doonil laahi kaashifah','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>59,'arabic_text'=>'أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ تَعۡجَبُونَ','transliteration'=>'Afamin hazal hadeesi ta\'jaboon','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>60,'arabic_text'=>'وَتَضۡحَكُونَ وَلَا تَبۡكُونَ','transliteration'=>'Wa-tadhakoona Wa-laa tabkoon','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>61,'arabic_text'=>'وَأَنتُمۡ سَٰمِدُونَ','transliteration'=>'Wa-antum saamidoon','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>53,'ayah_number'=>62,'arabic_text'=>'فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ','transliteration'=>'Fasjudoo lillaahi wa\'budoo','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>true],
            /* Surah 54: The Moon (Al-Qamar) */
            ['surah_id'=>54,'ayah_number'=>1,'arabic_text'=>'ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ','transliteration'=>'Iqtarabatis Saa\'atu wan-shaqqal qamar','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>2,'arabic_text'=>'وَإِن يَرَوۡاْ ءَايَةٗ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرٞ مُّسۡتَمِرّٞ','transliteration'=>'Wa-ien yaraw aayataien yu\'ridoo Wa-yaqooloo sihrun mustamirr','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>3,'arabic_text'=>'وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ','transliteration'=>'Wa-kazzaboo wattaba\'ooo ahwaaa\'ahum; Wa-kullu amrin mustaqirr','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>4,'arabic_text'=>'وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ','transliteration'=>'Wa-laqad jaaa\'ahum minal anbaaa\'i maa feehi muzdajar','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>5,'arabic_text'=>'حِكۡمَةُۢ بَٰلِغَةٞۖ فَمَا تُغۡنِ ٱلنُّذُرُ','transliteration'=>'Hikmatun baalighatun famaa tughnin nuzur','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>6,'arabic_text'=>'فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءٖ نُّكُرٍ','transliteration'=>'Fatawalla \'anhum; yawma yad\'ud daa\'i ilaa shai-\'in nukur','page_number'=>528,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>7,'arabic_text'=>'خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ','transliteration'=>'Khushsha\'an absaaruhum yakhrujoona minal ajdaasi ka-annahum jaraadum muntashir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>8,'arabic_text'=>'مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ','transliteration'=>'Muhti\'eena ilad daa\'i yaqoolul kaafiroona haazaa yawmun \'asir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>9,'arabic_text'=>'۞ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونٞ وَٱزۡدُجِرَ','transliteration'=>'Kazzabat qablahum qawmu Noohin fakazzaboo \'abdanaa Wa-qaaloo majnoonunw wazdujir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>10,'arabic_text'=>'فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ','transliteration'=>'Fada\'aa Rabbahooo annee maghloobun fantasir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>11,'arabic_text'=>'فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءٖ مُّنۡهَمِرٖ','transliteration'=>'Fafatahnaaa abwaabas samaaa\'i bi-maaa\'in munhamir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>12,'arabic_text'=>'وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرٖ قَدۡ قُدِرَ','transliteration'=>'Wa-fajjarnal arda \'uyoonan faltaqal maaa\'u \'alaaa amrin qad qudir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>13,'arabic_text'=>'وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحٖ وَدُسُرٖ','transliteration'=>'Wa-hamalnaahu \'alaa zaati alwaahinw Wa-dusur','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>14,'arabic_text'=>'تَجۡرِي بِأَعۡيُنِنَا جَزَآءٗ لِّمَن كَانَ كُفِرَ','transliteration'=>'Tajree bi-a\'yuninaa jazaaa\'an liman kaana kufir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>15,'arabic_text'=>'وَلَقَد تَّرَكۡنَٰهَآ ءَايَةٗ فَهَلۡ مِن مُّدَّكِرٖ','transliteration'=>'Wa-laqat taraknaahaa aayatan fahal min muddakir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>16,'arabic_text'=>'فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','transliteration'=>'Fakaifa kaana \'azaabee Wa-nuzur','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>17,'arabic_text'=>'وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ','transliteration'=>'Wa-laqad yassarnal Qur\'aana liz-zikri fahal min muddakir','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>18,'arabic_text'=>'كَذَّبَتۡ عَادٞ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','transliteration'=>'Kazzabat \'Aadun fakaifa kaana \'azaabee Wa-nuzur','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
            ['surah_id'=>54,'ayah_number'=>19,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِي يَوۡمِ نَحۡسٖ مُّسۡتَمِرّٖ','transliteration'=>'Innaa arsalnaa \'alaihim reehan sarsaran fee Yawmi nahsin mustamirr','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
