            ['surah_id'=>54,'ayah_number'=>23,'arabic_text'=>'كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ','transliteration'=>'Kazzabat Samoodu binnuzur','page_number'=>529,'juz_number'=>27,'hizb_number'=>53,'is_sajdah'=>false],
