            /* Surah 57: The Iron (Al-Hadid) */
            ['surah_id'=>57,'ayah_number'=>1,'arabic_text'=>'سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Sabbaha lillaahi maa fis samaawaati wal-ardi Wa-Huwal \'Azeezul Hakeem','page_number'=>537,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>2,'arabic_text'=>'لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Lahoo mulkus samaawaati wal-ardi yuhyee Wa-yumeetu Wa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>537,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>3,'arabic_text'=>'هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ','transliteration'=>'Huwal Awwalu wal\'Aakhiru waz-Zaahiru wal-Baatinu Wa-huwa bikulli shai\'in Aleem','page_number'=>537,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>4,'arabic_text'=>'هُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Huwal lazee khalaqas samaawaati wal arda fee sittati ayyaamin summas tawaa \'alal \'Arsh; ya\'lamu maa yaliju filardi Wa-maa yakhruju minhaa Wa-maa yanzilu minas samaaa\'i Wa-maa ya\'ruju feeha Wa-Huwa ma\'akum ayna maa kuntum; wallaahu bimaa ta\'maloona Baseer','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>5,'arabic_text'=>'لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','transliteration'=>'Lahoo mulkus samaawaati wal-ard; Wa-ilal laahi turja\'ul umoor','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>6,'arabic_text'=>'يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۚ وَهُوَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Yoolijul laila fin nahaari Wa-yoolijun nahaara fil lail; Wa-Huwa \'Aleemum bizaatis sudoor','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>7,'arabic_text'=>'ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ','transliteration'=>'Aaaminoo billaahi Wa-Rasoolihee Wa-anfiqoo mimmaa ja\'alakum mustakh-lafeena feehi fallazeena aamanoo minkum Wa-anfaqoo lahum ajrun kabeer','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>8,'arabic_text'=>'وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','transliteration'=>'Wa-maa lakum laa tu\'minoona billaahi war-Rasoolu yad\'ookum li-tu\'minoo bi-Rabbikum Wa-qad akhaza meesaaqakum in kuntum mu\'mineen','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>9,'arabic_text'=>'هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ ءَايَٰتِۭ بَيِّنَٰتٖ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفٞ رَّحِيمٞ','transliteration'=>'Huwal lazee yunazzilu \'alaa \'abdiheee Aayaatim baiyinaatil liyukhrijakum minaz zulumaati ilan noor; Wa-innal laaha bikum la-Ra\'oofur Raheem','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>10,'arabic_text'=>'وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَٰتَلَۚ أُوْلَٰٓئِكَ أَعۡظَمُ دَرَجَةٗ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Wa-maa lakum allaa tunfiqoo fee sabeelil laahi Wa-lillaahi meeraasus samaawaati wal-ard; laa yastawee minkum man anfaqa min qablil fat-hi Wa-qaatal; ulaaa\'ika a\'zamu darajatam minal lazeena anfaqoo min ba\'du Wa-qaataloo; Wa-kullanw wa\'ad allaahul husnaa; wallaahu bimaa ta\'maloona Khabeer','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>11,'arabic_text'=>'مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ','transliteration'=>'Man zal lazee yuqridul laaha qardan hasanan fa-yudaa\'ifahoo lahoo Wa-lahooo ajrun kareem','page_number'=>538,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>12,'arabic_text'=>'يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Yawma taral mu\'mineena walmu\'minaati yas\'aa nooruhum baina aydeehim Wa-bi-aymaanihim bushraakumul yawma jannaatun tajree min tahtihal anhaaru khaalideena feeha; zaalika huwal fawzul \'azeem','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>13,'arabic_text'=>'يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورٗاۖ فَضُرِبَ بَيۡنَهُم بِسُورٖ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ','transliteration'=>'Yawma yaqoolul munaafiqoona walmunaafiqaatu lil-lazeena aamanun zuroonaa naqtabis min noorikum qeela irji\'oo waraaa\'akum faltamisoo nooran faduriba bainahum bisooril lahoo baabun, baatinuhoo feehir rahmatu Wa-zaahiruhoo min qibalihi \'azaab','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>14,'arabic_text'=>'يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ','transliteration'=>'Yunaadoonahum alam nakum ma\'akum qaaloo balaa Wa-laakinnakum fatantum anfusakum Wa-tarabbastum wartabtum Wa-gharratkumul amaaniyyu hatta jaaa\'a amrul laahi Wa-gharrakum billaahil gharoor','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>15,'arabic_text'=>'فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ فِدۡيَةٞ وَلَا مِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Fal-Yawma laa yu\'khazu minkum fidyatunw Wa-laa minal lazeena kafaroo; ma\'waakumun Naaru hiya maw-laakum Wa-bi\'sal maseer','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>16,'arabic_text'=>'۞ أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ','transliteration'=>'Alam ya\'ni lil-lazeena aamanooo an takhsha\'a quloobuhum lizikril laahi Wa-maa nazala minal haqqi Wa-laa yakoonoo kallazeena ootul Kitaaba min qablu fataala \'alaihimul amadu faqasat quloobuhum Wa-kaseerum minhum faasiqoon','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>17,'arabic_text'=>'ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ','transliteration'=>'I\'lamooo annal laaha yuhyil arda ba\'da mawtihaa; qad baiyannaa lakumul Aayaati la\'allakum ta\'qiloon','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>18,'arabic_text'=>'إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرٞ كَرِيمٞ','transliteration'=>'Innal mussaddiqeena wal-mussaddiqaati Wa-aqradul laaha qardan hassanaien yudaa\'afu lahum Wa-lahum ajrun kareem','page_number'=>539,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>19,'arabic_text'=>'وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','transliteration'=>'Wallazeena aamanoo billaahi Wa-Rusuliheee ulaaa\'ika humus siddeeqoon; wash-shuhadaaa\'u \'inda Rabbihim lahum ajruhum Wa-nooruhum; wallazeena kafaroo Wa-kazzaboo bi-aayaatinaaa ulaaa\'ika As-haabul jaheem','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>20,'arabic_text'=>'ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَكُونُ حُطَٰمٗاۖ وَفِي ٱلۡأٓخِرَةِ عَذَابٞ شَدِيدٞ وَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرِضۡوَٰنٞۚ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ','transliteration'=>'I\'lamooo annamal hayaa-tud dunyaa la\'ibunw Wa-lahwunw Wa-zeenatunw Wa-tafaakhurum bainakum Wa-takaasurun fil amwaali wal-awlaad, kamasali ghaisin a\'jabal kuffaara nabaatuhoo summa yaheeju fataraahu musfaaran summa yakoonu hutaamaa; Wa-fil aakhirati \'azaabun shadeedunw Wa-magh-firatum minal laahi Wa-ridwaan; Wa-mal haiyaa-tud dun-yaaa illaa mataa\'ul ghuroor','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>21,'arabic_text'=>'سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Saabiqooo ilaa maghfiratim mir Rabbikum Wa-jannatin \'arduhaa ka-\'ardis samaaa\'i wal-ardi u\'iddat lillazeena aamanoo billaahi Wa-Rusulih; zaalika fadlul laahi yu\'teehi maien yashaaa\'; wal-laahu zul fadlil \'azeem','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>22,'arabic_text'=>'مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ','transliteration'=>'Maaa asaaba min museebatin fil ardi Wa-laa feee anfusikum illaa fee kitaabim min qabli an nabra-ahaa; innaa zaalika \'alal laahi yaseer','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>23,'arabic_text'=>'لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ','transliteration'=>'Likailaa ta\'saw \'alaa maa faatakum Wa-laa tafrahoo bimaaa aataakum; wallaahu laa yuhibbu kulla mukhtaalin fakhoor','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>24,'arabic_text'=>'ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','transliteration'=>'Allazeeena yabkhaloona Wa-yaamuroonan naasa bil-bukhl; Wa-maien yatawalla fa-innal laaha Huwal Ghaniyyul Hameed','page_number'=>540,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>25,'arabic_text'=>'لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ','transliteration'=>'Laqad arsalnaa Rusulanaa bilbaiyinaati Wa-anzalnaa ma\'ahumul Kitaaba wal-Meezaana liyaqooman naasu bilqist, Wa-anzalnal hadeeda feehi baasun shadeedunw Wa-manaafi\'u linnaasi Wa-liya\'lamal laahu many yansuruhoo Wa-Rusulahoo bilghaib; innal laaha Qawiyyun \'Azeez','page_number'=>541,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>26,'arabic_text'=>'وَلَقَدۡ أَرۡسَلۡنَا نُوحٗا وَإِبۡرَٰهِيمَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ فَمِنۡهُم مُّهۡتَدٖۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ','transliteration'=>'Wa-laqad arsalnaa Noohanw Wa-Ibraaheema Wa-ja\'alnaa fee zurriyyatihiman nubuwwata wal-Kitaaba faminhum muhtad; Wa-kaseerum minhum faasiqoon','page_number'=>541,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>27,'arabic_text'=>'ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ وَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةٗ وَرَحۡمَةٗۚ وَرَهۡبَانِيَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ','transliteration'=>'Summa qaffainaa \'alaa aasaarihim bi-Rusulinaa Wa-qaffainaa bi-\'Eesab ni Maryama Wa-aatainaahul Injeela Wa-ja\'alnaa fee quloobil lazeenat taba\'oohu ra\'fatanw Wa-rahmatanw rahbaaniyyatan ibtada\'ooha maa katabnaahaa \'alaihim illab tighaaa\'a ridwaanil laahi famaa ra\'awhaa haqqa ri\'aayatihaa; fa-aatainal lazeena aamanoo minhum ajrahum; Wa-kaseerum minhum faasiqoon','page_number'=>541,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>28,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamaanut taqul laaha Wa-aaminoo bi-Rasoolihee yu\'tikum kiflaini mir rahmatihee Wa-yaj\'al lakum nooran tamshoona bihee Wa-yaghfir lakum; wallaahu Ghafoorur Raheem','page_number'=>541,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            ['surah_id'=>57,'ayah_number'=>29,'arabic_text'=>'لِّئَلَّا يَعۡلَمَ أَهۡلُ ٱلۡكِتَٰبِ أَلَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Li\'alla ya\'lama Ahlul kitaabi allaa yaqdiroona \'alaa shai\'in min fadlil laahi Wa-annal fadla bi-Yadil laahi yu\'teehi maien yashaaa\'; wallaahu Zul fadilil \'azeem','page_number'=>541,'juz_number'=>27,'hizb_number'=>54,'is_sajdah'=>false],
            /* Surah 58: The Pleading Woman (Al-Mujadila) */
            ['surah_id'=>58,'ayah_number'=>1,'arabic_text'=>'قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ','transliteration'=>'Qad sami\'al laahu qawlal latee tujaadiluka fee zawjihaa Wa-tashtakeee ilal laahi wallaahu yasma\'u tahaawurakumaa; innal laaha samee\'um baseer','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>2,'arabic_text'=>'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ','transliteration'=>'Allazeena yuzaahiroona minkum min nisaaa\'ihim maa hunnaa ummahaatihim in ummahaatuhum illal laaa\'ee waladnahum; Wa-innaahum la-yaqooloona munkaram minal qawli Wa-zooraa; Wa-innal laaha la\'afuwwun ghafoor','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>3,'arabic_text'=>'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Wallazeena yuzaahiroona min nisaaa\'ihim summa ya\'oodoona limaa qaaloo fatahreeru raqabatim min qabli aien yatamaaassaa; zaalikum too\'azoona bih; wallaahu bimaa ta\'maloona khabeer','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>4,'arabic_text'=>'فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ','transliteration'=>'Famal lam yajid fa-siyaamu shahraini mutataabi\'ayni min qabli aien yatamaaassaa famal lam yastati\' fa-it\'aamu sitteena miskeena; zaalika litu\'minoo billaahi Wa-rasoolih\'wa tilka hudoodul laah; Wa-lilkaafireena \'azaabun aleem','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>5,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ','transliteration'=>'Innal lazeena yuhaaaddoonal laaha Wa-Rasoolahoo kubitoo kamaa kubital lazeena min qablihim; Wa-qad anzalnaaa aayaatim baiyinaat; Wa-lilkaa-fireena \'azaabum muheen','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>6,'arabic_text'=>'يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ','transliteration'=>'Yawma yab\'asuhumul laahu jamee\'an fayunabbi\'uhum bimaa \'amiloo; ahsaahul laahu Wa-nasooh; wallaahu \'alaa kulli shai\'in shaheed','page_number'=>542,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>7,'arabic_text'=>'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ','transliteration'=>'Alam tara annal laaha ya\'lamu maa fis samaawaati Wa-maa fil ardi maa yakoonu min najwaa salaasatin illaa Huwa raabi\'uhum Wa-laa khamsatin illaa huwa saadisuhum Wa-laaa adnaa min zaalika Wa-laaa aksara illaa huwa ma\'ahum ayna, maa kaanoo summa yunabbi\'uhum bimaa \'amiloo yawmal qiyaamah; innal laaha bikulli shai\'in aleem','page_number'=>543,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>8,'arabic_text'=>'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Alam tara ilal lazeena nuhoo \'anin najwaa summa ya\'oodoona limaa nuhoo \'anhu Wa-yatanaajawna bil-ismi wal\'udwaani Wa-ma\'siyatir rasooli Wa-izaa jaaa\'ooka haiyawka bimaa lam yuhai-yika bihil laahu Wa-yaqooloona fee anfusihim law-laa yu\'azzibunal laahu bimaa naqool; hasbuhum jahannnamu yaslawnahaa fabi\'sal maseer','page_number'=>543,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>9,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo izaa tanaajaytum falaa tatanaajaw bil-ismi wal-\'udwaani Wa-ma\'siyatir rasooli Wa-tanaajaw bil-birri wattaqwaa wattaqul laahal lazeee ilaihi tuhsharoon','page_number'=>543,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>10,'arabic_text'=>'إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Innaman najwaa minash shaitaani liyahzunal lazeena aamanoo Wa-laisa bidaaarrihim shai\'an illaa bi-iznil laah; Wa-\'alal laahi falyatawakkalil mu\'minoon','page_number'=>543,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>11,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo izaa qeela lakum tafassahoo fil majaalisi fafsahoo yafsahil laahu lakum Wa-izaa qeelan shuzoo fanshuzoo yarfa\'il laahul lazeena aamanoo minkum wallazeena ootul \'ilma darajaat; wallaahu bimaa ta\'maloona khabeer','page_number'=>543,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>12,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَةٗۚ ذَٰلِكَ خَيۡرٞ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Yaaa-ayyuhal lazeena aamanooo izaa naajitumur Rasoola faqaddimoo baina yadai najwaakum sadaqah; zaalika khairul lakum Wa-athar; fa-il lam tajidoo fa-innal laaha ghafoorur Raheem','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>13,'arabic_text'=>'ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتٖۚ فَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'A-ashfaqtum an tuqaddimoo baina yadai najwaakum sadaqaat; fa-iz lam taf\'aloo Wa-taabal laahu \'alaikum fa-aqeemus Salaata Wa-aatuz Zakaata Wa-atee\'ul laaha Wa-rasoolah; wallaahu khabeerum bimaa ta\'maloon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>14,'arabic_text'=>'۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ يَعۡلَمُونَ','transliteration'=>'Alam tara ilal lazeena tawallaw qawman ghadibal laahu \'alaihim maa hum minkum Wa-laa minhum Wa-yahlifoona \'alal kazibi Wa-hum ya\'lamoon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>15,'arabic_text'=>'أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'A\'addal laahu lahum \'azaaban shadeedan innahum saaa\'a maa kaanoo ya\'maloon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>16,'arabic_text'=>'ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ عَذَابٞ مُّهِينٞ','transliteration'=>'Ittakhazooo aymaanahum junnatan fasaddoo \'an sabeelil laahi falahum \'azaabum muheen','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>17,'arabic_text'=>'لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','transliteration'=>'Lan tughniya \'anhum amwaaluhum Wa-laaa awladuhum minal laahi shai\'aa; ulaaa-\'ika As-haabun Naari hum feehaa khaalidoon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>18,'arabic_text'=>'يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعٗا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ','transliteration'=>'Yawma yab\'asuhumul laahu jamee\'an fa-yahlifoona lahoo kamaa yahlifoona lakum Wa-yahsaboona annahum \'alaa shai\'; alaaa innahum humul kaaziboon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>19,'arabic_text'=>'ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Istahwaza \'alaihimush shaitaanu fa-ansaahum zikral laah; ulaaa\'ika hizbush shaitaaan; alaaa innaa hizbash shaitaani humul khaasiroon','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>20,'arabic_text'=>'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ','transliteration'=>'Innal lazeena yuhaaaddoonal laaha Wa-Rasoolahooo ulaaa\'ika fil azalleen','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>21,'arabic_text'=>'كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ','transliteration'=>'Katabal laahu la-aghlibanna ana Wa-Rusulee; innal laaha qawiyyun \'Azeez','page_number'=>544,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>58,'ayah_number'=>22,'arabic_text'=>'لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحٖ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Laa tajidu qawmaien yu\'minoona billaahi wal-yawmil aakhiri yuwaaaddoona man haaaddal laaha Wa-Rasoolahoo Wa-law kaanooo aabaaa\'ahum aw abnaaa\'ahum aw ikhwaa-nahum aw \'asheeratahum; ulaaa\'ika kataba fee quloobihi-mul eemaana Wa-ayyadahum biroohim minhu Wa-yudkhilu-hum jannatin tajree min tahtihal anhaaru khaalideena feehaa; radiyal laahu \'anhum Wa-radoo \'anhu; ulaaa-\'ika hizbul laah; alaaa inna hizbal laahi humul muflihoon','page_number'=>545,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            /* Surah 59: The Exile (Al-Hashr) */
            ['surah_id'=>59,'ayah_number'=>1,'arabic_text'=>'سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Sabbaha lillaahi maa fis samaawaati Wa-maa fil ardi Wa-Huwal \'Azeezul Hakeem','page_number'=>545,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>2,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ','transliteration'=>'Huwal lazeee akharajal lazeena kafaroo min ahlil kitaabi min diyaarihim li-awwalil Hashr; maa zanantum aien yakhrujoo Wa-zannooo annahum maa-ni\'atuhum husoonuhum minal laahi faataahumul laahu min haisu lam yahtasiboo Wa-qazafa fee quloobihimur ru\'ba yukhriboona bu-yootahum bi-aydeehim Wa-aydil mu\'mineena fa\'tabiroo yaaa-ulil absaar','page_number'=>545,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>3,'arabic_text'=>'وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ','transliteration'=>'Wa-law-laaa an katabal laahu \'alaihimul jalaaa\'a la\'azzabahum fid dunyaa Wa-lahum fil Aakhirati \'azaabun Naar','page_number'=>545,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>4,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Zaalika bi-annahum shaaqqul laaha Wa-Rasoolahoo Wa-maien yushaaaqqil laaha fa-innal laaha shadeedul \'iqaab','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>5,'arabic_text'=>'مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ','transliteration'=>'Maa qata\'tum mil leenatin aw taraktumoohaa qaaa\'imatan\'alaaa usoolihaa fabi iznil laahi Wa-liyukhziyal faasiqeen','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>6,'arabic_text'=>'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلٖ وَلَا رِكَابٖ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Wa-maaa afaaa\'al laahu \'alaaa Rasoolihee minhum famaaa awjaftum \'alaihi min khailiinw Wa-laa rikaabinw Wa-laakinnal laaha yusallitu Rusulahoo \'alaa maien yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>7,'arabic_text'=>'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','transliteration'=>'Maaa afaaa\'al laahu \'alaa Rasoolihee min ahlil quraa falillaahi Wa-lir-Rasooli Wa-lizil qurbaa wal-yataamaa walmasaakeeni wabnis sabeeli kai laa yakoona doolatam bainal aghniyaaa\'i minkum; Wa-maaa aataakumur Rasoolu fakhuzoohu Wa-maa nahaakum \'anhu fantahoo; wattaqul laah(a) innal laaha shadeedul \'iqaab','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>8,'arabic_text'=>'لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ','transliteration'=>'Lilfuqaraaa\'il Muhaaji-reenal lazeena ukhrijoo min diyaarihim Wa-amwaalihim yabtaghoona fadlam minal laahi Wa-ridwaananw Wa-yansuroonal laaha Wa-Rasoolah; ulaaa\'ika humus saadiqoon','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>9,'arabic_text'=>'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Wallazeena tabawwa\'ud daara wal-eemaana min qablihim yuhibboona man haajara ilaihim Wa-laa yajidoona fee sudoorihim haajatam mimmaa ootoo Wa-yu\'siroona \'alaa anfusihim Wa-law kaana bihim khasaasah; Wa-maien yooqa shuhha nafsihee fa-ulaaa\'ika humul muflihoon','page_number'=>546,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>10,'arabic_text'=>'وَٱلَّذِينَ جَآءُو مِنۢ بَعۡدِهِمۡ يَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ','transliteration'=>'Wallazeena jaaa\'oo min ba\'dihim yaqooloona Rabbanagh fir lanaa Wa-li-ikhwaani-nal lazeena sabqoonaa bil-eemaani Wa-laa taj\'al fee quloobinaa ghillalil lazeena aamanoo rabbannaaa innaka Ra\'oofur Raheem','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>11,'arabic_text'=>'۞ أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نَافَقُواْ يَقُولُونَ لِإِخۡوَٰنِهِمُ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَئِنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَدٗا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ','transliteration'=>'Alam tara ilal lazeena naafaqoo yaqooloona li-ikhwaanihimul lazeena kafaroo min ahlil kitaabi la\'in ukhrijtum lanakhrujanna ma\'akum Wa-laa nutee\'u feekum ahadan abadanw wa-in qootiltum lanansuran-nakum wallaahu yashhadu innahum lakaaziboon','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>12,'arabic_text'=>'لَئِنۡ أُخۡرِجُواْ لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمۡ وَلَئِن نَّصَرُوهُمۡ لَيُوَلُّنَّ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يُنصَرُونَ','transliteration'=>'La\'in ukhrijoo laa yakhrujoona ma\'ahum Wa-la\'in qootiloo laa yansuroonahum Wa-la\'in nasaroohum la-yuwallunnal adbaara summa laa yunsaroon','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>13,'arabic_text'=>'لَأَنتُمۡ أَشَدُّ رَهۡبَةٗ فِي صُدُورِهِم مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ','transliteration'=>'La-antum ashaddu rahbatan fee sudoorihim minal laah; zaalika bi-annahum qawmul laa yafqahoon','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>14,'arabic_text'=>'لَا يُقَٰتِلُونَكُمۡ جَمِيعًا إِلَّا فِي قُرٗى مُّحَصَّنَةٍ أَوۡ مِن وَرَآءِ جُدُرِۭۚ بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ','transliteration'=>'Laa yuqaatiloonakum jamee\'an illaa fee quram muhas-sanatin aw minw waraaa\'i judur; baasuhum bainahum shadeed; tahsabuhum jamee\'anw-wa quloobuhum shatta; zaalika biannahum qawmul laa ya\'qiloon','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>15,'arabic_text'=>'كَمَثَلِ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَرِيبٗاۖ ذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Kamasalil lazeena min qablihim qareeban zaaqoo wabaala amrihim Wa-lahum \'azaabun aleem','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>16,'arabic_text'=>'كَمَثَلِ ٱلشَّيۡطَٰنِ إِذۡ قَالَ لِلۡإِنسَٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيٓءٞ مِّنكَ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ','transliteration'=>'Kamasalish shaitaani izqaala lil insaanik fur falammaa kafara qaala innee bareee\'um minka inneee akhaaful laaha rabbal \'aalameen','page_number'=>547,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>17,'arabic_text'=>'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِي ٱلنَّارِ خَٰلِدَيۡنِ فِيهَاۚ وَذَٰلِكَ جَزَٰٓؤُاْ ٱلظَّٰلِمِينَ','transliteration'=>'Fakaana \'aaqibatahumaaa annahumaa fin naari khaalidaini feehaa; Wa-zaalika jazaaa\'uz zaalimeen','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>18,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Yaaa ayyuhal lazeena aamanut taqul-laaha; waltanzur nafsum maa qaddamat lighadiw wattaqual laah; innal laaha khabeerum bimaa ta\'maloon','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>19,'arabic_text'=>'وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ','transliteration'=>'Wa-laa takoonoo kallazeena nasul laaha fa-ansaahum anfusahum; ulaaa\'ika humul faasiqoon','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>20,'arabic_text'=>'لَا يَسۡتَوِيٓ أَصۡحَٰبُ ٱلنَّارِ وَأَصۡحَٰبُ ٱلۡجَنَّةِۚ أَصۡحَٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَآئِزُونَ','transliteration'=>'Laa yastaweee as-haabun naari Wa-ashaabul jannah; as-haabul jannati humul faaa\'izoon','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>21,'arabic_text'=>'لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ يَتَفَكَّرُونَ','transliteration'=>'Law anzalnaa haazal quraana \'alaa jabilil lara-aytahoo khaashi\'am muta-saddi\'am min khashiyatil laah; Wa-tilkal amsaalu nadribuhaa linnaasi la\'allahum yatafakkaroon','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>22,'arabic_text'=>'هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ','transliteration'=>'Huwal laahul lazee laaa Ilaaha illaa Huwa \'Aalimul Ghaibi wash-shahaada; Huwar Rahmaanur Raheem','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>23,'arabic_text'=>'هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ','transliteration'=>'Huwal laahul lazee laaa Ilaaha illaa Huwal Malikul Quddoosus Salaamul Muminul Muhaiminul \'aAzeezul Jabbaarul Mutakabbir; Subhaanal laahi \'Ammaa yushrikoon','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>59,'ayah_number'=>24,'arabic_text'=>'هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Huwal Laahul Khaaliqul Baari-\'ul Musawwir; lahul Asmaaa\'ul Husnaa; yusabbihu lahoo maa fis samaawaati wal-ardi Wa-Huwal \'Azeezul Hakeem','page_number'=>548,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            /* Surah 60: She that is to be examined (Al-Mumtahanah) */
            ['surah_id'=>60,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo laa tattakhizoo \'aduwwee Wa-\'aduwaakum awliyaaa\'a tulqoona ilaihim bilmawaddati Wa-qad kafaroo bima jaaa\'akum minal haqq, yukhrijoonar Rasoola Wa-iyyaakum an tu\'minoo billaahi rabbikum in kuntum kharajtum jihaadan fee sabeelee wabtighaaa\'a mardaatee; tusirroona ilaihim bilma-waddati Wa-ana a\'alamu bimaaa akhfaitum Wa-maaa a\'lantum; Wa-many yaf\'alhu minkum faqad dalla sawaaa\'as sabeel','page_number'=>549,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>2,'arabic_text'=>'إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ','transliteration'=>'Ien yasqafookum yakoonoo lakum a\'daaa\'anw Wa-yabsutooo ilaikum aydiyahum Wa-alsinatahum bissooo\'i Wa-waddoo law takfuroon','page_number'=>549,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>3,'arabic_text'=>'لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ','transliteration'=>'Lan tanfa\'akum arhaamukum Wa-laaa awlaadukum; yawmal qiyaamati yafsilu bainakum; wallaahu bimaa ta\'maloon baseer','page_number'=>549,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>4,'arabic_text'=>'قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ','transliteration'=>'Qad kaanat lakum uswatun hasanatun feee Ibraaheema wallazeena ma\'ahoo iz qaaloo liqawmihim innaa bura-\'aaa\'u minkum Wa-mimmaa ta\'budoona min doonil laahi kafarnaa bikum Wa-badaa bainanaa Wa-bainakumul \'adaawatu wal-baghdaaa\'u abadan hattaa tu\'minoo billaahi wahdahooo illaa qawla Ibraheema li-abeehi la-astaghfiranna laka Wa-maaa amliku laka minal laahi min shai; rabbanaa \'alaika tawakkalnaa Wa-ilaika anabnaa Wa-ilaikal maseer','page_number'=>549,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>5,'arabic_text'=>'رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Rabbana laa taj\'alnaa fitnatal lillazeena kafaroo waghfir lanaa rabbanaa innaka antal azeezul hakeem','page_number'=>549,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>6,'arabic_text'=>'لَقَدۡ كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','transliteration'=>'Laqad kaana lakum feehim uswatunhasanatul liman kaana yarjul laaha wal yawmal aakhir; Wa-many yatawalla fa-innal laaha huwal ghaniyyul hameed','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>7,'arabic_text'=>'۞ عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Asal laahu any yaj\'ala bainakum Wa-bainal lazeena \'aadaitum minhum mawaddah; wallahu qadeer; wallahu ghafoorur raheem','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>8,'arabic_text'=>'لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ','transliteration'=>'Laa yanhaakumul laahu \'anil lazeena lam yuqaatilookum fid deeni Wa-lam yukhrijookum min diyaarikum an tabarroohum Wa-tuqsitooo ilaihim; innal laaha yuhibbul muqsiteen','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>9,'arabic_text'=>'إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم مِّن دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ','transliteration'=>'Innamaa yanhaakumul laahu \'anil lazeena qaatalookum fid deeni Wa-akhrajookum min diyaarikum Wa-zaaharoo \'alaa ikhraajikum an tawallawhum; Wa-many yatawallahum fa-ulaaa\'ika humuz zaalimoon','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>10,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ ذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo izaa jaaa\'akumul mu\'minaatu muhaajiraatin famtahinoo-hunn; Allaahu a\'lamu bi-eemaani-hinn; fa-in \'alimtumoo-hunna mu\'minaatin falaa tarji\'oo-hunna ilal kuffaar; laa hunna hillul lahum Wa-laa hum yahilloona lahunna Wa-aatoohum maa anfaqoo Wa-laa junaaha \'alaikum an tankihoohunna izaaa aataitumoohunna ujoorahunn; Wa-laa tumsikoo bi-\'isamil kawaafir; was\'aloo maaa anfaqtum walyas\'aloo maaa anfaqoo; zaalikum hukmul laahi yahkumu bainakum; wallaahu \'aleemun hakeem','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>11,'arabic_text'=>'وَإِن فَاتَكُمۡ شَيۡءٞ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُواْ ٱلَّذِينَ ذَهَبَتۡ أَزۡوَٰجُهُم مِّثۡلَ مَآ أَنفَقُواْۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ','transliteration'=>'Wa-in faatakum shai\'un min azwaajikum ilal kuffaari fa-\'aaqabtum fa-aatul lazeena zahabat azwaajuhum misla maaa anfaqoo; wattaqul laahal lazeee antum bihee mu\'minoon','page_number'=>550,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>12,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ بِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ','transliteration'=>'Yaaa-ayyuhan nabbiyyu izaa jaaa\'akal mu\'minaatu yubaayigh\'naka \'alaaa al laa yushrikna billaahi shai-\'anw Wa-laa yasriqna Wa-laa yazneena Wa-laa yaqtulna awlaadahunna Wa-laa ya\'teena bibuhtaanien yaftaree-nahoo baina aydeehinna Wa-arjulihinna Wa-laa ya\'seenaka fee ma\'roofin fa-baayigh\'-hunna wastaghfir lahunnalla hunn allaah; innallaaha ghafoorur raheem','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>60,'ayah_number'=>13,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ قَدۡ يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ','transliteration'=>'Yaaa-ayyuhal lazeena amanoo laa tatawallaw qawman ghadibal laahu \'alaihim qad ya\'isoo minal aakhirati kamaa ya\'isal kuffaaru min as-haabil quboor','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            /* Surah 61: The Ranks (As-Saf) */
            ['surah_id'=>61,'ayah_number'=>1,'arabic_text'=>'سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Sabbaha lillaahi maa fis amaawaati Wa-maa fil ardi Wa-huwal \'Azeezul Hakeem','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>2,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ','transliteration'=>'Yaa-ayyuhal lazeena aamanoo lima taqooloona maa laa taf\'aloon','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>3,'arabic_text'=>'كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ','transliteration'=>'Kabura maqtan \'indal laahi an taqooloo maa laa taf\'aloon','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>4,'arabic_text'=>'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ','transliteration'=>'Innal laaha yuhibbul lazeena yuqaatiloona fee sabeelihee saffan ka-annahum bunyaanum marsoos','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>5,'arabic_text'=>'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ','transliteration'=>'Wa-iz qaala Moosa liqawmihee yaa-qawmi lima tu\'zoonanee Wa-qat ta\'lamoona annee Rasoolul laahi ilaikum falammaa zaaghooo azaaghal laahu quloobahum; wallaahu laa yahdil qawmal faasiqeen','page_number'=>551,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>6,'arabic_text'=>'وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ','transliteration'=>'Wa-iz qaala \'Eesab nu Maryama yaa-Banee Israaa\'eela innee Rasoolul laahi ilaikum musaddiqal limaa baina yadayya minat Tawraati Wa-mubashshiram bi-Rasooliny yaatee mim ba\'dis muhooo Ahmad; falammaa jaaa\'ahum bil-baiyinaati qaaloo haazaa sihrum mubeen','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>7,'arabic_text'=>'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-man azlamu mimma-nif taraa \'alal laahil kaziba Wa-huwa yad\'aaa ilal Islaam; wallaahu laa yahdil qawmaz zaalimeen','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>8,'arabic_text'=>'يُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ','transliteration'=>'Yureedoona liyutfi\'oo nooral laahi bi-afwaahihim wallaahu mutimmu noorihee Wa-law karihal kaafiroon','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>9,'arabic_text'=>'هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ','transliteration'=>'Huwal lazee arsala Rasoolahoo bilhudaa Wa-deenil haqqi liyuzhirahoo \'alad deeni kullihee Wa-law karihal mushrikoon','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>10,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo hal adullukum \'alaa tijaaratin tunjeekum min \'azaabin aleem','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>11,'arabic_text'=>'تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Tu\'minoona billaahi Wa-Rasoolihee Wa-tujaahidoona fee sabeelil laahi bi-amwaalikum Wa-anfusikum; zaalikum khairul lakum in kuntum ta\'lamoon','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>12,'arabic_text'=>'يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Yaghfir lakum zunoobakum Wa-yudkhilkum Jannaatin tajree min tahtihal anhaaru Wa-masaakina taiyibatan fee Jannaati \'Adn; zaalikal fawzul \'Azeem','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>13,'arabic_text'=>'وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرٞ مِّنَ ٱللَّهِ وَفَتۡحٞ قَرِيبٞۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ','transliteration'=>'Wa-ukhraa tuhibboonahaa nasrum minal laahi Wa-fat-hun qareeb; Wa-bashshiril mu-\'mineen','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            ['surah_id'=>61,'ayah_number'=>14,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ لِلۡحَوَارِيِّـۧنَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّآئِفَةٞ مِّنۢ بَنِيٓ إِسۡرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٞۖ فَأَيَّدۡنَا ٱلَّذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُواْ ظَٰهِرِينَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo koonooo ansaaral laahi kamaa qaala \'Eesab nu Maryama lil-Hawaariyyeena man ansaareee ilal laah; qaalal Hawaariyyoona nahnu ansaa-rul laahi fa-aamanat taaa\'ifatum mim Bannee Israaa\'eela Wa-kafarat taaa\'ifatun fa-ayyadnal lazeena aamanoo \'alaa \'aduwwihim fa-asbahoo zaahireen','page_number'=>552,'juz_number'=>28,'hizb_number'=>55,'is_sajdah'=>false],
            /* Surah 62: The Congregation, Friday (Al-Jumu'ah) */
            ['surah_id'=>62,'ayah_number'=>1,'arabic_text'=>'يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','transliteration'=>'Yusabbihu lilaahi maa fis samaawaati Wa-maa fil ardil Malikil Quddoosil \'Azeezil Hakeem','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>2,'arabic_text'=>'هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Huwal lazee ba\'asa fil ummiyyeena Rasoolam min-hum yatloo \'alaihim aayaatihee Wa-yuzakkeehim Wa-yu\'allimuhumul Kitaaba wal-Hikmata Wa-in kaanoo min qablu lafee dalaalim mubeen','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>3,'arabic_text'=>'وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Wa-aakhareena minhum lammaa yalhaqoo bihim Wa-huwal \'azeezul hakeem','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>4,'arabic_text'=>'ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','transliteration'=>'Zaalika fadlul laahi yu\'teehi many yashaaa; wallaahu zul fadlil \'azeem','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>5,'arabic_text'=>'مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ','transliteration'=>'Masalul lazeena hum-milut tawraata summa lam yahmiloonhaa kamasalil himaari yah-milu asfaaraa; bi\'sa masalul qawmil lazeena kaazzaboo bi-aayaatil laah; wallaahu laa yahdil qawmaz zaalimeen','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>6,'arabic_text'=>'قُلۡ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓاْ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Qul yaaa-ayyuhal lazeena haadoo in za\'amtum annakum awliyaaa\'u lilaahi min doonin naasi fatamannawul mawta in kuntum saadiqeen','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>7,'arabic_text'=>'وَلَا يَتَمَنَّوۡنَهُۥٓ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ','transliteration'=>'Wa-laa yatamannaw-nahooo abadam bimaa qaddamat aydeehim; wallaahu \'aleemum biz-zaalimeen','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>8,'arabic_text'=>'قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Qul innal mawtal lazee tafirroona minhu fa-innahoo mulaaqeekum summa turaddoona ilaa \'Aalimil Ghaibi wash-shahaadati fa-yunabbi\'ukum bimaa kuntum ta\'maloon','page_number'=>553,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>9,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo izaa noodiya lis-Salaati miny yawmil Jumu\'ati fas\'aw ilaa zikril laahi Wa-zarul bai\'; zaalikum khayrul lakum in kuntum ta\'lamoon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>10,'arabic_text'=>'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ','transliteration'=>'Fa-izaa qudiyatis Salaatu fantashiroo fil ardi wabtaghoo min fadlil laahi wazkurul laaha kaseeral la\'allakum tuflihoon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>62,'ayah_number'=>11,'arabic_text'=>'وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ','transliteration'=>'Wa-izaa ra\'aw tijaaratan aw lahwanin faddooo ilaihaa Wa-tarakooka qaaa\'imaa; qul maa \'indal laahi khairum minal lahwi Wa-minat tijaarah; wallaahu khayrur raaziqeen','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            /* Surah 63: The Hypocrites (Al-Munafiqun) */
            ['surah_id'=>63,'ayah_number'=>1,'arabic_text'=>'إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ','transliteration'=>'Izaa jaaa\'akal munaafiqoona qaaloo nashhadu innaka la-rasoolul laah; wallaahu ya\'lamu innaka la-rasooluhoo wallaahu yashhadu innal munaafiqeena lakaaziboon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>2,'arabic_text'=>'ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ','transliteration'=>'Ittakhazoo aymaanahum junnatan fasaddoo \'an sabeelil laah; innahum saaa\'a maa kaanoo ya\'maloon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>3,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ','transliteration'=>'Zaalika bi-annahum aamanoo summa kafaroo fatubi\'a \'alaa quloobihim fahum laa yafqahoon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>4,'arabic_text'=>'۞ وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ','transliteration'=>'Wa-izaa ra-aytahum tu\'jibuka ajsaamuhum Wa-iny yaqooloo tasma\' liqawlihim kaannahum khushubum musannadah; yahsaboona kulla saihatin \'alaihim; humul \'aduwwu fahzarhum; qaatalahumul laahu annaa yu\'fakoon','page_number'=>554,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>5,'arabic_text'=>'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ','transliteration'=>'Wa-izaa qeela lahum ta\'aalaw yastaghfir lakum rasoolul laahi lawwaw ru\'oo-sahum Wa-ra-aytahum yasuddoona Wa-hum mustakbiroon','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>6,'arabic_text'=>'سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ','transliteration'=>'Sawaaa\'un \'alaihim as-taghfarta lahum am lam tastaghfir lahum lany yaghfiral laahu lahum; innal laaha laa yahdil qawmal faasiqeen','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>7,'arabic_text'=>'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ','transliteration'=>'Humul lazeena yaqooloona laa tunfiqoo \'alaa man inda Rasoolil laahi hatta yanfaddoo; Wa-lillaahi khazaaa\'inus samaawaati wal-ardi Wa-laakinnal munaafiqeena la yafqahoon','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>8,'arabic_text'=>'يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ','transliteration'=>'Yaqooloona la\'ir raja\'naaa ilal madeenati la-yukhrijanal a\'azzu minhal azall; Wa-lillaahil \'izzatu Wa-li-Rasoolihee Wa-lilmu\'mineena Wa-laakinnal munaafiqeena laa ya\'lamoon','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>9,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo la tulhikum amwaalukum Wa-laa awlaadukum \'anzik ril laah; Wa-mai yaf\'al zaalika fa-ulaaa\'ika humul khaasiroon','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>10,'arabic_text'=>'وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ','transliteration'=>'Wa-anifqoo mim maa razaqnaakum min qabli any ya\'tiya ahadakumul mawtu fa-yaqoola rabbi law-laaa akhkhartaneee ilaaa ajalin qareebin fa-assaddaqa Wa-akum minas saaliheen','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>63,'ayah_number'=>11,'arabic_text'=>'وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','transliteration'=>'Wa-lany yu-\'akhkhiral laahu nafsan izaa jaaa\'a ajaluhaa; wallaahu khabeerum bimaa ta\'maloon','page_number'=>555,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            /* Surah 64: The Mutual Disillusion (At-Taghabun) */
            ['surah_id'=>64,'ayah_number'=>1,'arabic_text'=>'يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Yusabbihu lillaahi maa fis samaawaati Wa-maa fil ardi lahul mulku Wa-lahul hamd, Wa-Huwa \'alaa kulli shai\'in Qadeer','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>2,'arabic_text'=>'هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرٞ وَمِنكُم مُّؤۡمِنٞۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ','transliteration'=>'Huwal lazee khalaqakum faminkum kaafirunw Wa-min-kum mu\'min; wallaahu bimaa ta\'maloona Baseer','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>3,'arabic_text'=>'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ','transliteration'=>'Khalaqas samaawaati wal-arda bilhaqqi Wa-sawwarakum fa-ahsana suwarakum Wa-ilaihil maseer','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>4,'arabic_text'=>'يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Ya\'lamu maa fis samaawaati wal-ardi Wa-ya\'lamu maa tusirroona Wa-maa tu\'linoon; wallaahu \'Aleemum bizaatis sudoor','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>5,'arabic_text'=>'أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Alam ya\'tikum naba\'ul lazeena kafaroo min qablu fazaaqoo wabaala amrihim Wa-lahum \'azaabun aleem','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>6,'arabic_text'=>'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرٞ يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدٞ','transliteration'=>'Zaalika bi-annahoo kaanat ta\'teehim Rusuluhum bilbaiyinaati faqaaloo a-basharuny yahdoonanaa fakafaroo Wa-tawallaw; wastaghnal laah; wallaahu ghaniyyun hameed','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>7,'arabic_text'=>'زَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ','transliteration'=>'Za\'amal lazeena kafarooo al lany yub\'asoo; qul balaa Wa-rabbee latub\'asunna summa latunabba\'unna bimaa \'amiltum; Wa-zaalika \'alal laahi yaseer','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>8,'arabic_text'=>'فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ','transliteration'=>'Fa-aaminoo billaahi Wa-rasoolihee wannooril lazeee anzalnaa; wallaahu bima ta\'maloona khabeer','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>9,'arabic_text'=>'يَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','transliteration'=>'Yawma yajma\'ukum li-yawmil jam\'i zaalika yawmut taghaabun; Wa-many yumim billaahi Wa-ya\'mal saalihany yukaffir \'anhu sayyi-aatihee Wa-yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul \'azeem','page_number'=>556,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>10,'arabic_text'=>'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Wallazeena kafaroo Wa-kazzaboo bi-aayaaatinaaa ulaaa\'ika ashaabun naari khaalideena feehaa Wa-bi\'sal maseer','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>11,'arabic_text'=>'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ','transliteration'=>'Maaa asaaba mim musee-batin illaa bi-iznil laah; Wa-many yu\'mim billaahi yahdi qalbah; wallaahu bikulli shai\'in Aleem','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>12,'arabic_text'=>'وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن تَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ','transliteration'=>'Wa-atee\'ul laaha Wa-atee\'ur Rasool; fa-in tawallaitum fa-innamaa \'alaa Rasoolinal balaaghul mubeen','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>13,'arabic_text'=>'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','transliteration'=>'Allaahu laaa ilaaha illaa Hoo; Wa-\'alal laahi falyata-wakkalil mu\'minoon','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>14,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ','transliteration'=>'Yaaa-ayyuhal lazeena aamanooo inna min azwaaji-kum Wa-awlaadikum \'aduwwal lakum fahzaroohum; Wa-in ta\'foo Wa-tasfahoo Wa-taghfiroo fa-innal laaha ghafoorur Raheem','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>15,'arabic_text'=>'إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ','transliteration'=>'Innamaa amwaalukum Wa-awlaadukum fitnah; wallaahu \'indahooo ajrun \'azeem','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>16,'arabic_text'=>'فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','transliteration'=>'Fattaqul laaha mas tata\'tum wasma\'oo Wa-atee\'oo Wa-anfiqoo khairal li-anfusikum; Wa-many yooqa shuh-ha nafsihee fa-ulaaa\'ika humul muflihoon','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>17,'arabic_text'=>'إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ','transliteration'=>'In tuqridul laaha qardan hasanany yudaaifhu lakum Wa-yaghfir lakum; wallaahu Shakoorun Haleem','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>64,'ayah_number'=>18,'arabic_text'=>'عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','transliteration'=>'Aalimul Ghaibi wash-shahaadatil \'Azeezul Hakeem','page_number'=>557,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            /* Surah 65: The Divorce (At-Talaq) */
            ['surah_id'=>65,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا','transliteration'=>'Yaaa-ayyuhan nabiyyu izaa tallaqtummun nisaaa\'a fatalliqoohunna li\'iddatihinna Wa-ahsul iddata wattaqul laaha rabbakum; laa tukhri-joohunna mim bu-yootihinna Wa-laa yakhrujna illaaa any ya\'teema bifaahishatim mubaiyinah; Wa-tilka hudoodul laah; Wa-many yata\'adda hudoodal laahi faqad zalama nafsah; laa tadree la\'allal laaha yuhdisu ba\'da zaalika amraa','page_number'=>558,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>2,'arabic_text'=>'فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا','transliteration'=>'Fa-izaa balaghna ajalahunna fa-amsikoohunna bima\'roofin aw faariqoohunna bima\'roofinw Wa-ashhidoo zawai \'adlim minkum Wa-aqeemush shahaadata lillaah; zaalikum yoo\'azu bihee man kaana yu\'minu billaahi wal-yawmil aakhir; Wa-many yattaqil laaha yaj\'al lahoo makhrajaa','page_number'=>558,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>3,'arabic_text'=>'وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا','transliteration'=>'Wa-yarzuqhu min haisu laa yahtasib; Wa-many yatawakkal \'alal laahi fahuwa husbuh; innal laaha baalighu amrih; qad ja\'alal laahu likulli shai\'in qadraa','page_number'=>558,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>4,'arabic_text'=>'وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا','transliteration'=>'Wallaaa\'ee ya\'isna minal maheedi min nisaaa\'ikum inir tabtum fa\'iddatuhunna salaasatu ashhurinw wallaaa\'ee lam yahidn; Wa-ulaatul ahmaali ajaluhunna any yada\'na hamlahun; Wa-many yattaqil laaha yaj\'al lahoo min amrihee yusraa','page_number'=>558,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>5,'arabic_text'=>'ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا','transliteration'=>'Zaalika amrul laahi anzalahoo ilaikum; Wa-many yattaqil laaha yukaffir \'anhu saiyi-aatihee Wa-yu\'zim lahoo ajraa','page_number'=>558,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>6,'arabic_text'=>'أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ','transliteration'=>'Askinoohunna min haisu sakantum minw wujdikum Wa-laa tudaaarroohunna litudaiyiqoo \'alaihinn; Wa-in kunna ulaati hamlin fa-anfiqoo \'alaihinna hattaa yada\'na hamlahunn; fain arda\'na lakum fa-aatoo-hunna ujoorahunn; wa\'tamiroo bainakum bima\'roofinw Wa-in ta\'aasartum fasaturdi\'u lahooo ukhraa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>7,'arabic_text'=>'لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا','transliteration'=>'Liyunfiq zoo sa\'atim min sa\'atih; Wa-man qudira \'alaihi rizquhoo falyunfiq mimmaaa aataahul laah; laa yukalliful laahu nafsan illaa maaa aataahaa; sa-yaj\'alul laahu ba\'da \'usriny yusraa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>8,'arabic_text'=>'وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا','transliteration'=>'Wa-ka-ayyim min qaryatin \'atat \'an amri Rabbihaa Wa-Rusulihee fahaasabnaahaa hisaaban shadeedanw Wa-\'azzabnaahaa \'azaaban nukraa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>9,'arabic_text'=>'فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا','transliteration'=>'Fazaaqat wabbala amrihaa Wa-kaana \'aaqibatu amrihaa khusraa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>10,'arabic_text'=>'أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدٗاۖ فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَيۡكُمۡ ذِكۡرٗا','transliteration'=>'A\'addal laahu lahum \'azaaban shadeedan fattaqul laaha yaaa-ulil albaab, allazeena aammanoo; qad anzalal laahu ilaikum zikraa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>11,'arabic_text'=>'رَّسُولٗا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٖ لِّيُخۡرِجَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا','transliteration'=>'Rasoolany yatloo \'alaikum aayaatil laahi mubaiyinaatil liyukhrijal lazeena aamanoo Wa-\'amilus saalihaati minaz zulumaati ilan noor; Wa-many yu\'min billaahi Wa-ya\'mal saalihany yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaa abadaa qad ahsanal laahu lahoo rizqaa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>65,'ayah_number'=>12,'arabic_text'=>'ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا','transliteration'=>'Allaahul lazee khalaq Sab\'a Samaawaatinw Wa-minal ardi mislahunna yatanazzalul amru bainahunna lita\'lamooo annal laaha \'alaa kulli shai\'in Qadeerunw Wa-annal laaha qad ahaata bikulli shai\'in \'ilmaa','page_number'=>559,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            /* Surah 66: The Prohibition (At-Tahrim) */
            ['surah_id'=>66,'ayah_number'=>1,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ','transliteration'=>'Yaaa-ayyuhan nabiyyu lima tuharrimu maaa ahallal laahu laka tabtaghee mardaata azwaajik; wallaahu ghafoorur raheem','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>2,'arabic_text'=>'قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ','transliteration'=>'Qad faradal laahu lakum tahillata aymaanikum; wallaahu mawlaakum Wa-huwal \'aleemul hakeem','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>3,'arabic_text'=>'وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ','transliteration'=>'Wa-iz asarran nabiyyu ilaa ba\'di azwaajihee hadeesan falammaa nabba-at bihee Wa-azharahul laahu \'alaihi \'arrafa ba\'dahoo Wa-a\'rada \'am ba\'din falammaa nabba-ahaa bihee qaalat man amba-aka haaza qaala nabba-aniyal \'aleemul khabeer','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>4,'arabic_text'=>'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ','transliteration'=>'In tatoobaaa ilal laahi faqad saghat quloobukumaa Wa-in tazaaharaa \'alaihi fa-innal laaha huwa mawlaahu Wa-jibreelu Wa-saalihul mu\'mineen; wal-malaaa\'ikatu ba\'da zaalika zaheer','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>5,'arabic_text'=>'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا','transliteration'=>'Asaa rabbuhooo in tallaqakunna any yubdilahooo azwaajan khairam minkunna muslimaatim mu\'minaatin qaanitaatin taaa\'ibaatin \'aabidaatin saaa\'ihaatin saiyibaatinw Wa-abkaaraa','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>6,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo qooo anfusakum Wa-ahleekum naaranw waqoodu-han naasu wal-hijaaratu \'alaihaa malaaa\'ikatun ghilaazun shidaadul laa ya\'soonal laaha maa amarahum Wa-yaf\'aloona maa yu\'maroon','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>7,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ','transliteration'=>'Yaaa-ayyuhal lazeena kafaroo la ta\'tazirul yawma innamaa tujzawna maa kuntum ta\'maloon','page_number'=>560,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>8,'arabic_text'=>'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ','transliteration'=>'Yaaa-ayyuhal lazeena aamanoo toobooo ilal laahi tawbatan nasoohan \'asaa rabbukum any yukaffira \'ankum sayyi-aatikum Wa-yudkhilakum jannaatin tajree min tahtihal anhaaru yawma laa yukhzil laahun nabiyya wallazeena aamanoo ma\'ahoo nooruhum yas\'aa baina aydeehim Wa-bi-aymaanihim yaqooloona rabbanaaa atmim lanaa nooranaa waghfir lana innaka \'alaa kulli shai\'in qadeer','page_number'=>561,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>9,'arabic_text'=>'يَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Yaaa-ayyuhan nabiyyu jaahidil kuffaara walmunaa-fiqeena waghluz \'alaihim; Wa-ma\'waahum jahannamu Wa-bi\'sal maseer','page_number'=>561,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>10,'arabic_text'=>'ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ','transliteration'=>'Darabal laahu masalal lillazeena kafarum ra-ata Noohinw wamra-ata Loot, kaanataa tahta \'abdaini min \'ibaadinaa saalihaini fakhaanataahumaa falam yughniyaa \'anhumaa minal laahi shai-anw wa-qeelad khulan naara ma\'ad Daakhileen','page_number'=>561,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>11,'arabic_text'=>'وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','transliteration'=>'Wa-darabal laahu masalal lil-lezeena aamanum ra-ata Fir\'awn; iz qaalat rab-bib ni lee \'indaka baitan fil jannati Wa-najjinee min Fir\'awna Wa-\'amalihee Wa-najjinee minal qawmiz zaalimeen','page_number'=>561,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            ['surah_id'=>66,'ayah_number'=>12,'arabic_text'=>'وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ','transliteration'=>'Wa-Maryamab nata \'Imraanal lateee ahsanat farjahaa fanafakhnaa feehee mir roohinaa Wa-saddaqat bi-kalimaati Rabhihaa Wa-Kutubihee wakaanati minal qaaniteen','page_number'=>561,'juz_number'=>28,'hizb_number'=>56,'is_sajdah'=>false],
            /* Surah 67: The Sovereignty (Al-Mulk) */
            ['surah_id'=>67,'ayah_number'=>1,'arabic_text'=>'تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ','transliteration'=>'Tabaarakal lazee biyadihil mulku Wa-huwa \'alaa kulli shai-in qadeer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>2,'arabic_text'=>'ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ','transliteration'=>'Allazee khalaqal mawta walhayaata liyabluwakum ayyukum ahsanu \'amalaa; Wa-huwal \'azeezul ghafoor','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>3,'arabic_text'=>'ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ','transliteration'=>'Allazee khalaqa sab\'a samaawaatin tibaaqaa maa taraa fee khalqir rahmaani min tafaawut farji\'il basara hal taraa min futoor','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>4,'arabic_text'=>'ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ','transliteration'=>'Summar ji\'il basara karrataini yanqalib ilaikal basaru khaasi\'anw Wa-huwa haseer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>5,'arabic_text'=>'وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ','transliteration'=>'Wa-laqad zaiyannas samaaa\'ad dunyaa bimasaa-beeha Wa-ja\'alnaahaa rujoomal lish-shayaateeni Wa-a\'tadnaa lahum \'azaabas sa\'eer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>6,'arabic_text'=>'وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ','transliteration'=>'Wa-lillazeena kafaroo bi-rabbihim \'azaabu jahannama Wa-bi\'sal maseer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>7,'arabic_text'=>'إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقٗا وَهِيَ تَفُورُ','transliteration'=>'Izaaa ulqoo feehaa sami\'oo lahaa shaheeqanw Wa-hiya tafoor','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>8,'arabic_text'=>'تَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ','transliteration'=>'Takaadu tamayyazu minal ghaizz kullamaaa ulqiya feehaa fawjun sa-alahum khazanatuhaaa alam ya\'tikum nazeer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>9,'arabic_text'=>'قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرٞ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ كَبِيرٖ','transliteration'=>'Qaaloo balaa qad jaaa\'anaa nazeerun fakazzabnaa Wa-qulnaa maa nazzalal laahu min shai-in in antum illaa fee dalaalin kabeer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>10,'arabic_text'=>'وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ','transliteration'=>'Wa-qaaloo law kunnaa nasma\'u aw na\'qilu maa kunnaa feee as-haabis sa\'eer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>11,'arabic_text'=>'فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ','transliteration'=>'Fa\'tarafoo bizambihim fasuhqal li-as-haabis sa\'eer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>12,'arabic_text'=>'إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ','transliteration'=>'Innal lazeena yakhshawna rabbahum bilghaibi lahum maghfiratunw Wa-ajrun kabeer','page_number'=>562,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>13,'arabic_text'=>'وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','transliteration'=>'Wa-asirroo qawlakum awij haroo bih; innahoo \'aleemum bizaatis sudoor','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>14,'arabic_text'=>'أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ','transliteration'=>'Alaa ya\'lamu man khalaqa Wa-huwal lateeful khabeer','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>15,'arabic_text'=>'هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ','transliteration'=>'Huwal lazee ja\'ala lakumul arda zaloolan famshoo fee manaakibihaa Wa-kuloo mir rizqih; Wa-ilaihin nushoor','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>16,'arabic_text'=>'ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ','transliteration'=>'A-amintum man fis samaaa\'i ai yakhsifa bi-kumul arda fa-izaa hiya tamoor','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>17,'arabic_text'=>'أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ فَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ','transliteration'=>'Am amintum man fis samaaa\'i ai yursila \'alaikum haasiba fasata\'lamoona kaifa nazeer','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>18,'arabic_text'=>'وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ','transliteration'=>'Wa-laqad kazzabal lazeena min qablihim fakaifa kaana nakeer','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>19,'arabic_text'=>'أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَٰٓفَّٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ','transliteration'=>'Awalam yaraw ilat tairi fawqahum saaaffaatinw Wa-yaqbidn; maa yumsikuhunna illaar rahmaan; innahoo bikulli shai-im baseer','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>20,'arabic_text'=>'أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ','transliteration'=>'Amman haazal lazee huwa jundul lakum yansurukum min doonir rahmaan; inil kaafiroona illaa fee ghuroor','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>21,'arabic_text'=>'أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ وَنُفُورٍ','transliteration'=>'Amman haazal lazee yarzuqukum in amsaka rizqah; bal lajjoo fee \'utuwwinw Wa-nufoor','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>22,'arabic_text'=>'أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ','transliteration'=>'Afamai yamshee mukibban \'alaa wajhihee ahdaaa ammany yamshee sawiyyan \'alaa siratim mustaqeem','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>23,'arabic_text'=>'قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ','transliteration'=>'Qul huwal lazee ansha-akum Wa-ja\'ala lakumus sam\'a wal-absaara wal-af\'idata qaleelam maa tashkuroon','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>24,'arabic_text'=>'قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ','transliteration'=>'Qul huwal lazee zara-akum fil ardi Wa-ilaihi tuhsharoon','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>25,'arabic_text'=>'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','transliteration'=>'Wa-yaqooloona mataa haazal wa\'du in kuntum saadiqeen','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>26,'arabic_text'=>'قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ','transliteration'=>'Qul innamal \'ilmu \'indal laahi Wa-innamaaa ana nazeerum mubeen','page_number'=>563,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>27,'arabic_text'=>'فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَدَّعُونَ','transliteration'=>'Falaammaa ra-awhu zulfatan seee\'at wujoohul lazeena kafaroo Wa-qeela haazal lazee kuntum bihee tadda\'oon','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>28,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ','transliteration'=>'Qul ara\'aytum in ahlaka-niyal laahu Wa-mam ma\'iya aw rahimanaa famai yujeerul kaafireena min \'azaabin aleem','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>29,'arabic_text'=>'قُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ','transliteration'=>'Qul huwar rahmaanu aamannaa bihee Wa-\'alaihi tawakkalnaa fasata\'lamoona man huwa fee dalaalim mubeen','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>67,'ayah_number'=>30,'arabic_text'=>'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرٗا فَمَن يَأۡتِيكُم بِمَآءٖ مَّعِينِۭ','transliteration'=>'Qul ara\'aytum in asbaha maaa\'ukum ghawran famai ya\'teekum bimaaa\'im ma\'een','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            /* Surah 68: The Pen (Al-Qalam) */
            ['surah_id'=>68,'ayah_number'=>1,'arabic_text'=>'نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ','transliteration'=>'Noon; walqalami Wa-maa yasturoon','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
