            ['surah_id'=>68,'ayah_number'=>8,'arabic_text'=>'فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ','transliteration'=>'Falaa tuti\'il mukazzibeen','page_number'=>564,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
