            ['surah_id'=>68,'ayah_number'=>28,'arabic_text'=>'قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ','transliteration'=>'Qaala awsatuhum alam aqul lakum law-laa tusabbihoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>29,'arabic_text'=>'قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ','transliteration'=>'Qaaloo subhaana rabbinaaa innaa kunnaa zaalimeen','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>30,'arabic_text'=>'فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ','transliteration'=>'Fa-aqbala ba\'duhum \'alaa ba\'diny yatalaawamoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>31,'arabic_text'=>'قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ','transliteration'=>'Qaaloo yaa-wailanaaa innaa kunnaa taagheen','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>32,'arabic_text'=>'عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ','transliteration'=>'Asaa rabbunaaa any yubdilanaa khairam minhaaa innaaa ilaa rabbinaa raaghiboon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>33,'arabic_text'=>'كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ','transliteration'=>'Kazaalikal azaab, Wa-la\'azaabul aakhirati akbar; law kaanoo ya\'lamoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>34,'arabic_text'=>'إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّٰتِ ٱلنَّعِيمِ','transliteration'=>'Inna lilmuttaqeena \'inda rabbihim jannaatin na\'eem','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>35,'arabic_text'=>'أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ','transliteration'=>'Afanaj\'alul muslimeena kalmujrimeen','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>36,'arabic_text'=>'مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ','transliteration'=>'Maa lakum kaifa tahkumoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>37,'arabic_text'=>'أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ','transliteration'=>'Am lakum kitaabun feehi tadrusoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>38,'arabic_text'=>'إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ','transliteration'=>'Inna lakum feehi lamaa takhaiyaroon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>39,'arabic_text'=>'أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ','transliteration'=>'Am lakum aymaanun \'alainaa baalighatun ilaa yawmil qiyaamati inna lakum lamaa tahkumoon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>40,'arabic_text'=>'سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ','transliteration'=>'Salhum ayyuhum bizaa-lika za\'eem','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>41,'arabic_text'=>'أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ','transliteration'=>'Am lahum shurakaaa\'u fal-ya\'too bishurakaaa-\'ihim in kaanoo saadiqeen','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>42,'arabic_text'=>'يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ','transliteration'=>'Yawma yukshafu \'am saaqinw Wa-yud\'awna ilas sujoodi falaa yastatee\'oon','page_number'=>565,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>43,'arabic_text'=>'خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ','transliteration'=>'Khaashi\'atan absaaruhum tarhaquhum zillatunw Wa-qad kaanoo yud\'awna ilas sujoodi Wa-hum saalimoon','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>44,'arabic_text'=>'فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ','transliteration'=>'Fazarnee Wa-many yukazzibu bihaazal hadeesi sanastad-rijuhum min haisu laa ya\'lamoon','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>45,'arabic_text'=>'وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ','transliteration'=>'Wa-umlee lahum; inna kaidee mateen','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>46,'arabic_text'=>'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ','transliteration'=>'Am tas\'aluhum ajran fahum min maghramin musqaloon','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>47,'arabic_text'=>'أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ','transliteration'=>'Am \'indahumul ghaibu fahum yaktuboon','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>48,'arabic_text'=>'فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ','transliteration'=>'Fasbir lihukmi rabbika Wa-laa takun kasaahibil hoot; iz naadaa Wa-huwa makzoom','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>49,'arabic_text'=>'لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ','transliteration'=>'Law-laaa an tadaara-kahoo ni\'matum mir rabbihee lanubiza bil\'araaa\'i Wa-huwa mazmoom','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>68,'ayah_number'=>50,'arabic_text'=>'فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ','transliteration'=>'Fajtabaahu rabbuhoo faja\'alahoo minas saaliheen','page_number'=>566,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
