            /* Surah 71: Noah (Nuh) */
            ['surah_id'=>71,'ayah_number'=>1,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ','transliteration'=>'Innaaa arsalnaa Noohan ilaa qawmihee an anzir qawmaka min qabli any yaatiyahum \'azaabun aleem','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>2,'arabic_text'=>'قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ','transliteration'=>'Qaala yaa-qawmi innee lakum nazeerum mubeen','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>3,'arabic_text'=>'أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ','transliteration'=>'Ani\' budul laaha watta-qoohu Wa-atee\'oon','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>4,'arabic_text'=>'يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ','transliteration'=>'Yaghfir lakum min zunoobikum Wa-yu\'akhkhirkum ilaaa ajalim musammaa; innaa ajalal laahi izaa jaaa\'a laa yu\'akhkhar; law kuntum ta\'lamoon','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>5,'arabic_text'=>'قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا','transliteration'=>'Qaala rabbi innee da\'awtu qawmee lailanw Wa-naharaa','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>6,'arabic_text'=>'فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا','transliteration'=>'Falam yazid-hum du\'aaa-\'eee illaa firaaraa','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>7,'arabic_text'=>'وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا','transliteration'=>'Wa-inee kullamaa da\'awtuhum litaghfira lahum ja\'alooo asaabi\'ahum fee aazaanihim wastaghshaw siyaabahum Wa-asarroo wastakbarus tikbaaraa','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>8,'arabic_text'=>'ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا','transliteration'=>'Summa innee da\'aw-tuhum jihaara','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>9,'arabic_text'=>'ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا','transliteration'=>'Summaa inneee a\'lantu lahum Wa-asrartu lahum israaraa','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>10,'arabic_text'=>'فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا','transliteration'=>'Faqultus taghfiroo Rabakum innahoo kaana Ghaffaaraa','page_number'=>570,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>11,'arabic_text'=>'يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا','transliteration'=>'Yursilis samaaa\'a \'alaikum midraaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>12,'arabic_text'=>'وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا','transliteration'=>'Wa-yumdidkum bi-am-waalinw Wa-baneena Wa-yaj\'al lakum Jannaatinw Wa-yaj\'al lakum anhaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>13,'arabic_text'=>'مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا','transliteration'=>'Maa lakum laa tarjoona lillaahi waqaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>14,'arabic_text'=>'وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا','transliteration'=>'Wa-qad khalaqakum at-waaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>15,'arabic_text'=>'أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا','transliteration'=>'Alam taraw kaifa khalaqal laahu sab\'a samaawaatin tibaaqaa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>16,'arabic_text'=>'وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا','transliteration'=>'Wa-ja\'alal qamara feehinna nooranw Wa-ja\'alash shamsa siraajaa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>17,'arabic_text'=>'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا','transliteration'=>'Wallaahu ambatakum minal ardi nabaataa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>18,'arabic_text'=>'ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا','transliteration'=>'Summa yu\'eedukum feehaa Wa-ukhrijukum ikhraajaa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>19,'arabic_text'=>'وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا','transliteration'=>'Wallaahu ja\'ala lakumul arda bisaataa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>20,'arabic_text'=>'لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا','transliteration'=>'Litaslukoo minhaa subulan fijaajaa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>21,'arabic_text'=>'قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا','transliteration'=>'Qaala Noohur Rabbi innahum \'asawnee wattaba\'oo mal lam yazid-hu maaluhoo Wa-waladuhooo illaa khasaara','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>22,'arabic_text'=>'وَمَكَرُواْ مَكۡرٗا كُبَّارٗا','transliteration'=>'Wa-makaroo makran kubbaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>23,'arabic_text'=>'وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا','transliteration'=>'Wa-qaaloo laa tazarunna aalihatakum Wa-laa tazarunna Waddanw Wa-laa Suwaa\'anw Wa-laa Yaghoosa Wa-Ya\'ooqa Wa-Nasraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>24,'arabic_text'=>'وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلٗا','transliteration'=>'Wa-qad adalloo kasee-ranw Wa-laa tazidiz zaalimeena illaa dalaalaa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>25,'arabic_text'=>'مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا','transliteration'=>'Mimmaa khateee\'-aatihim ughriqoo fa-udkhiloo Naaran falam yajidoo lahum min doonil laahi ansaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>26,'arabic_text'=>'وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا','transliteration'=>'Wa-qaala Noohur Rabbi laa tazar \'alal ardi minal kaafireena daiyaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>27,'arabic_text'=>'إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا','transliteration'=>'Innaka in tazarhum yudil-loo \'ibaadaka Wa-laa yalidooo illaa faajiran kaffaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            ['surah_id'=>71,'ayah_number'=>28,'arabic_text'=>'رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارَۢا','transliteration'=>'Rabbigh fir lee Wa-liwaa-lidaiya Wa-liman dakhala baitiya mu\'minanw Wa-lil-mu\'mineena wal-mu\'minaati Wa-laa tazidiz zaalimeena illaa tabaaraa','page_number'=>571,'juz_number'=>29,'hizb_number'=>57,'is_sajdah'=>false],
            /* Surah 72: The Jinn (Al-Jinn) */
            ['surah_id'=>72,'ayah_number'=>1,'arabic_text'=>'قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا','transliteration'=>'Qul oohiya ilaiya annna hustama\'a nafarum minal jinni faqaalooo innaa sami\'naa quraanan ajaba','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>2,'arabic_text'=>'يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا','transliteration'=>'Yahdeee ilar rushdi fa-aamannaa bihee Wa-lan nushrika bi-rabbinaaa \'ahada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>3,'arabic_text'=>'وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا','transliteration'=>'Wa-annahoo Ta\'aalaa jaddu Rabbinaa maat takhaza saahibatanw Wa-laa walada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>4,'arabic_text'=>'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا','transliteration'=>'Wa-annahoo kaana yaqoolu safeehunaa \'al allahi shatata','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>5,'arabic_text'=>'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا','transliteration'=>'Wa-annaa zanannaaa al lan taqoolal insu wal-jinnu \'al allahi kaziba','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>6,'arabic_text'=>'وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا','transliteration'=>'Wa-annahoo kaana rijaalun minal insi ya\'oozoona bi-rijaalin minal jinni fa-zaadoohum rahaqa','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>7,'arabic_text'=>'وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا','transliteration'=>'Wa-annahum zannoo kamaa zanantum al lany yab\'asal laahu \'ahada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>8,'arabic_text'=>'وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا','transliteration'=>'Wa-annaa lamasnas samaaa\'a fa-wajadnaahaa muli\'at harasan shadeedanw Wa-shuhuba','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>9,'arabic_text'=>'وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا','transliteration'=>'Wa-annaa kunnaa naq\'udu minhaa maqaa\'ida lis\'sam\'i famany yastami\'il \'aana yajid lahoo shihaabar rasada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>10,'arabic_text'=>'وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا','transliteration'=>'Wa-annaa laa nadreee asharrun ureeda biman fil ardi \'am \'araada bihim rabbuhum rashada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>11,'arabic_text'=>'وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا','transliteration'=>'Wa-annaa minnas saalihoona Wa-minnaa doona zaalika kunnaa taraaa\'iqa qidada','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>12,'arabic_text'=>'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا','transliteration'=>'Wa-annaa zanan-naaa al lan nu\'jizal laaha fil ardi Wa-lan nu\'jizahoo haraba','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>13,'arabic_text'=>'وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا','transliteration'=>'Wa-annaa lammaa sami\'nal hudaaa aamannaa bihee famany yu\'min bi-rabbihee falaa yakhaafu bakhsanw Wa-laa rahaqa','page_number'=>572,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>14,'arabic_text'=>'وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا','transliteration'=>'Wa-annaa minnal muslimoona Wa-minnal qaasitoona faman aslama fa-ulaaa\'ika taharraw rashada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>15,'arabic_text'=>'وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا','transliteration'=>'Wa-ammal qaasitoona fa-kaanoo li-jahannama hataba','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>16,'arabic_text'=>'وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا','transliteration'=>'Wa-alla-wis taqaamoo \'alat tareeqati la-asqaynaahum maa\'an ghadaqa','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>17,'arabic_text'=>'لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا','transliteration'=>'Linaftinahum feeh; Wa-many yu\'rid \'an zikri rabbihee yasluk-hu \'azaaban sa\'ada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>18,'arabic_text'=>'وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا','transliteration'=>'Wa-annal masaajida lil-laahi falaa tad\'oo ma\'al laahi \'ahada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>19,'arabic_text'=>'وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا','transliteration'=>'Wa-annahoo lammaa qaama \'abdul laahi yad\'oohu kaadoo yakoonoona \'alaihi libada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>20,'arabic_text'=>'قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا','transliteration'=>'Qul innamaaa ad\'oo rabbee Wa-laaa ushriku biheee \'ahada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>21,'arabic_text'=>'قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا','transliteration'=>'Qul innee laaa amliku lakum darranw Wa-laa rashada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>22,'arabic_text'=>'قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا','transliteration'=>'Qul innee lany yujeeranee minal laahi \'ahadunw, Wa-lan ajida min doonihee multahada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>23,'arabic_text'=>'إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا','transliteration'=>'Illaa balaagham minal laahi Wa-risaalaatih; Wa-many ya\'sil laaha Wa-rasoolahoo fa-inna lahoo naara jahannama khaalideena feehaaa \'abada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>24,'arabic_text'=>'حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا','transliteration'=>'Hattaaa izaa ra-aw maa yoo\'adoona fasaya\'lamoona man ad\'afu naasiranw Wa-aqallu \'adada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>25,'arabic_text'=>'قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا','transliteration'=>'Qul in adreee a-qareebum maa too\'adoona am yaj\'alu lahoo rabbeee \'amada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>26,'arabic_text'=>'عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا','transliteration'=>'Aalimul ghaibi falaa yuzhiru alaa ghaibiheee \'ahada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>27,'arabic_text'=>'إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدٗا','transliteration'=>'Illaa manir tadaa mir rasoolin fa-innahoo yasluku min baini yadaihi Wa-min khalfihee rasada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>72,'ayah_number'=>28,'arabic_text'=>'لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا','transliteration'=>'Liya\'lama an qad ablaghoo risaalaati rabbihim Wa-ahaata bi-maa ladaihim Wa-ahsaa kulla shai\'in \'adada','page_number'=>573,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            /* Surah 73: The Enshrouded One (Al-Muzzammil) */
