            ['surah_id'=>73,'ayah_number'=>2,'arabic_text'=>'قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا','transliteration'=>'Qumil laila illaa qaleelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>3,'arabic_text'=>'نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا','transliteration'=>'Nisfahooo awin qus minhu qaleelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>4,'arabic_text'=>'أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا','transliteration'=>'Aw zid \'alaihi Wa-rattilil Qur\'aana tarteela','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>5,'arabic_text'=>'إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا','transliteration'=>'Innaa sanulqee \'alaika qawlan saqeelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>6,'arabic_text'=>'إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا','transliteration'=>'Inn naashi\'atal laili hiya ashadddu wat-anw Wa-aqwamu qeelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>7,'arabic_text'=>'إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا','transliteration'=>'Inna laka fin nahaari sabhan taweelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>8,'arabic_text'=>'وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا','transliteration'=>'Wazkuris ma rabbika Wa-tabattal ilaihi tabteelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>9,'arabic_text'=>'رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا','transliteration'=>'Rabbul mashriqi wal-maghriibi laaa ilaaha illaa Huwa fattakhizhu wakeelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>10,'arabic_text'=>'وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا','transliteration'=>'Wasbir \'alaa maa yaqoo-loona wahjurhum hajran jameelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>11,'arabic_text'=>'وَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا','transliteration'=>'Wa-zarnee walmukaz-zibeena ulin na\'mati Wa-mahhilhum qaleelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>12,'arabic_text'=>'إِنَّ لَدَيۡنَآ أَنكَالٗا وَجَحِيمٗا','transliteration'=>'Inna ladainaaa ankaalanw Wa-jaheemaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>13,'arabic_text'=>'وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا','transliteration'=>'Wa-ta\'aaman zaa ghussa-tinw wa\'azaaban aleemaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>14,'arabic_text'=>'يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِيبٗا مَّهِيلًا','transliteration'=>'Yawma tarjuful ardu waljibaalu Wa-kaanatil jibaalu kaseebam maheelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>15,'arabic_text'=>'إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا','transliteration'=>'Innaa arsalnaaa ilaikum rasoolan shaahidan \'aleykum kamaaa arsalnaaa ilaa Fir\'awna rasoolaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>16,'arabic_text'=>'فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَٰهُ أَخۡذٗا وَبِيلٗا','transliteration'=>'Fa\'asaa Fir\'awnur Rasoola fa-akhaznaahu akhzanw wabeelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>17,'arabic_text'=>'فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمٗا يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا','transliteration'=>'Fakaifa tattaqoona in kafartum yawmany yaj\'alul wildaana sheeba','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>18,'arabic_text'=>'ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا','transliteration'=>'Assamaaa\'u munfatirum bih; kaana wa\'duhoo maf\'oola','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>19,'arabic_text'=>'إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا','transliteration'=>'Inna haazihee tazkiratun fa-man shaaa\'at takhaza ilaa Rabbihee sabeelaa','page_number'=>574,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>73,'ayah_number'=>20,'arabic_text'=>'۞ إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ','transliteration'=>'Inna Rabbaka ya\'lamu annaka taqoomu adnaa min sulusa-yil laili Wa-nisfahoo Wa-sulusahoo Wa-taaa\'ifatum minal lazeena ma\'ak; wal-laahu yuqaddirul laila wanna-haar; \'alima al lan tuhsoohu fataaba \'alaikum faqra\'oo maa tayassara minal quraan; \'alima an sa-yakoonu minkum mardaa Wa-aakharoona yadriboona fil ardi yabtaghoona min fadlil laahi Wa-aakharoona yuqaatiloona fee sabeelil laahi faqra\'oo ma tayassara minhu Wa-aqeemus salaata Wa-aatuz zakaata Wa-aqridul laaha qardan hasanaa; Wa-maa tuqadimoo li-anfusikum min khairin tajidoohu \'indal laahi huwa khayranw Wa-a\'zama ajraa; wastaghfirul laahaa innal laaha ghafoorur raheem.','page_number'=>575,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
