            ['surah_id'=>75,'ayah_number'=>36,'arabic_text'=>'أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى','transliteration'=>'Ayahsabul insaanu ai yutraka sudaa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>75,'ayah_number'=>37,'arabic_text'=>'أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ','transliteration'=>'Alam yaku nutfatam mim maniyyiny yumnaa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>75,'ayah_number'=>38,'arabic_text'=>'ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ','transliteration'=>'Summa kaana \'alaqatan fakhalaqa fasawwaa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>75,'ayah_number'=>39,'arabic_text'=>'فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ','transliteration'=>'Faja\'ala minhuz zawjayniz zakara wal-unsaa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>75,'ayah_number'=>40,'arabic_text'=>'أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ','transliteration'=>'Alaisa zaalika biqaadirin \'alaaa any yuhyiyal mawtaa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            /* Surah 76: The Man (Al-Insan) */
            ['surah_id'=>76,'ayah_number'=>1,'arabic_text'=>'هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا','transliteration'=>'Hal ataa \'alal insaani heenum minad dahri lam yakun shai\'am mazkooraa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>2,'arabic_text'=>'إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا','transliteration'=>'Innaa khalaqnal insaana min nutfatin amshaajin nabta-leehi faja\'alnaahu samee\'am baseeraa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>3,'arabic_text'=>'إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا','transliteration'=>'Innaa hadainaahus sabeela immaa shaakiranw Wa-immaa kafoora','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>4,'arabic_text'=>'إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا','transliteration'=>'Innaaa a\'tadnaa lilkaa-fireena salaasila Wa-aghlaalanw Wa-sa\'eeraa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>5,'arabic_text'=>'إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا','transliteration'=>'Innal abraara yashra-boona min kaasin kaana mizaa-juhaa kaafooraa','page_number'=>578,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>6,'arabic_text'=>'عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا','transliteration'=>'Aynany yashrabu bihaa \'ibaadul laahi yufajjiroonahaa tafjeeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>7,'arabic_text'=>'يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا','transliteration'=>'Yoofoona binnazri Wa-yakhaafoona yawman kaana sharruhoo mustateeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>8,'arabic_text'=>'وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا','transliteration'=>'Wa-yut\'imoonat ta\'aama \'alaa hubbihee miskeenanw Wa-yateemanw Wa-aseeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>9,'arabic_text'=>'إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا','transliteration'=>'Innaamaa nut\'imukum li-wajhil laahi laa nureedu minkum jazaaa\'anw Wa-laa shukooraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>10,'arabic_text'=>'إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا','transliteration'=>'Innaa nakhaafu mir Rabbinna Yawman \'aboosan qamtareeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>11,'arabic_text'=>'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا','transliteration'=>'Fa-waqaahumul laahu sharra zaalikal yawmi Wa-laqqaahum nadratanw Wa-surooraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>12,'arabic_text'=>'وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا','transliteration'=>'Wa-jazaahum bimaa sabaroo janatanw Wa-hareeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>13,'arabic_text'=>'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا','transliteration'=>'Muttaki\'eena feeha \'alal araaa-\'iki laa yarawna feehaa shamsanw Wa-laa zamhareeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>14,'arabic_text'=>'وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلٗا','transliteration'=>'Wa-daaniyatan \'alaihim zilaaluhaa Wa-zullilat qutoofu-haa tazleela','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>15,'arabic_text'=>'وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠','transliteration'=>'Wa-yutaafu \'alaihim bi-aaniyatim min fiddatinw Wa-akwaabin kaanat qawaareeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>16,'arabic_text'=>'قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا','transliteration'=>'Qawaareera min fiddatin qaddaroohaa taqdeeraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>17,'arabic_text'=>'وَيُسۡقَوۡنَ فِيهَا كَأۡسٗا كَانَ مِزَاجُهَا زَنجَبِيلًا','transliteration'=>'Wa-yuskawna feehaa kaasan kaana mizaajuhaa zanjabeelaa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>18,'arabic_text'=>'عَيۡنٗا فِيهَا تُسَمَّىٰ سَلۡسَبِيلٗا','transliteration'=>'Aynan feeha tusammaa salsabeelaa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>19,'arabic_text'=>'۞ وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا','transliteration'=>'Wa-yatoofu \'alaihim wildaanum mukhalladoona izaa ra-aytahum hasibtahum lu\'lu-\'am mansoora','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>20,'arabic_text'=>'وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمٗا وَمُلۡكٗا كَبِيرًا','transliteration'=>'Wa-izaa ra-ayta samma ra-ayta na\'eemanw Wa-mulkan kabeera','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>21,'arabic_text'=>'عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا','transliteration'=>'Aaliyahum siyaabu sundusin khudrunw Wa-istabraq, Wa-hullooo asaawira min fiddatinw Wa-saqaahum Rabbuhum sharaaban tahooraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>22,'arabic_text'=>'إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءٗ وَكَانَ سَعۡيُكُم مَّشۡكُورًا','transliteration'=>'Innaa haazaa kaana lakum jazz-\'anw Wa-kaana sa\'yukum mashkooraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>23,'arabic_text'=>'إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا','transliteration'=>'Innaa nahnu nazzalnaa \'alaikal quraana tanzeelaa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>24,'arabic_text'=>'فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا','transliteration'=>'Fasbir lihukmi Rabbika Wa-laa tuti\' minhum aasiman aw kafooraa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>25,'arabic_text'=>'وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا','transliteration'=>'Wazkuris ma Rabbika bukratanw Wa-aseelaa','page_number'=>579,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>26,'arabic_text'=>'وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا','transliteration'=>'Wa-minal laili fasjud lahoo Wa-sabbihhu lailan taweelaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>27,'arabic_text'=>'إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمٗا ثَقِيلٗا','transliteration'=>'Inna haaa\'ulaa\'i yuhibboona \'aajilata Wa-yazaroona waraaa\'ahum yawman saqeelaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>28,'arabic_text'=>'نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا','transliteration'=>'Nahnu khalaqnaahum Wa-shadadnaaa asrahum Wa-izaa shi\'naa baddalnaaa amsaala-hum tabdeelaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>29,'arabic_text'=>'إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا','transliteration'=>'Inna haazihee tazkiratun fa-man shaaa\'at takhaza ilaa rabbihee sabeela','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>30,'arabic_text'=>'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا','transliteration'=>'Wa-maa tashaaa\'oona illaa any yashaaa\'al laah; innal laahaa kaana \'Aleeman Hakeema','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>76,'ayah_number'=>31,'arabic_text'=>'يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا','transliteration'=>'Yudkhilu mai yashaaa\'u fee rahmatih; wazzaalimeena a\'adda lahum \'azaaban aleemaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            /* Surah 77: The Emissaries (Al-Mursalat) */
            ['surah_id'=>77,'ayah_number'=>1,'arabic_text'=>'وَٱلۡمُرۡسَلَٰتِ عُرۡفٗا','transliteration'=>'Wal-mursalaati \'urfaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>2,'arabic_text'=>'فَٱلۡعَٰصِفَٰتِ عَصۡفٗا','transliteration'=>'Fal\'aasifaati \'asfaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>3,'arabic_text'=>'وَٱلنَّٰشِرَٰتِ نَشۡرٗا','transliteration'=>'Wannaashiraati nashraa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>4,'arabic_text'=>'فَٱلۡفَٰرِقَٰتِ فَرۡقٗا','transliteration'=>'Falfaariqaati farqaa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>5,'arabic_text'=>'فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا','transliteration'=>'Falmulqiyaati zikra','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>6,'arabic_text'=>'عُذۡرًا أَوۡ نُذۡرًا','transliteration'=>'Uzran aw nuzraa','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>7,'arabic_text'=>'إِنَّمَا تُوعَدُونَ لَوَٰقِعٞ','transliteration'=>'Innamaa too\'adoona lawaaqi\'','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>8,'arabic_text'=>'فَإِذَا ٱلنُّجُومُ طُمِسَتۡ','transliteration'=>'Fa-izam nujoomu tumisat','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>9,'arabic_text'=>'وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ','transliteration'=>'Wa-izas samaaa\'u furijat','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>10,'arabic_text'=>'وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ','transliteration'=>'Wa-izal jibaalu nusifat','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>11,'arabic_text'=>'وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ','transliteration'=>'Wa-izar Rusulu uqqitat','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>12,'arabic_text'=>'لِأَيِّ يَوۡمٍ أُجِّلَتۡ','transliteration'=>'Li-ayyi yawmin ujjilat','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>13,'arabic_text'=>'لِيَوۡمِ ٱلۡفَصۡلِ','transliteration'=>'Li-yawmil Fasl','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
            ['surah_id'=>77,'ayah_number'=>14,'arabic_text'=>'وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ','transliteration'=>'Wa-maaa adraaka maa yawmul fasl','page_number'=>580,'juz_number'=>29,'hizb_number'=>58,'is_sajdah'=>false],
