            ['surah_id'=>97,'ayah_number'=>1,'arabic_text'=>'إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ','transliteration'=>'Innaa anzalnaahu fee lailatil qadr','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
