            /* Surah 98: The Clear Proof (Al-Bayyinah) */
            ['surah_id'=>98,'ayah_number'=>1,'arabic_text'=>'لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ','transliteration'=>'Lam ya-kunil lazeena kafaru min ahlil kitaabi wal-mushri-keena mun-fak-keena hattaa ta-tiya-humul bayyinah','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>2,'arabic_text'=>'رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ','transliteration'=>'Rasoolum minal laahi yatlu suhufam mutahharah','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>3,'arabic_text'=>'فِيهَا كُتُبٞ قَيِّمَةٞ','transliteration'=>'Feeha kutubun qaiyimah','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>4,'arabic_text'=>'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ','transliteration'=>'Wa-maa tafarraqal lazeena ootul kitaaba il-la mim b\'adi ma jaa-at-humul baiyyinah','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>5,'arabic_text'=>'وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ','transliteration'=>'Wa-maa umiroo il-la liy\'abu-dul laaha mukhliseena lahud deena huna-faa-a Wa-yuqeemus salaata Wa-yu-tuz zakaata; Wa-zaalika deenul qaiyimah','page_number'=>598,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>6,'arabic_text'=>'إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ','transliteration'=>'Innal lazeena kafaru min ahlil kitaabi wal-mushri-keena fee nari jahan-nama khaali-deena feeha; ulaa-ika hum shar-rul ba-reeyah','page_number'=>599,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>7,'arabic_text'=>'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ','transliteration'=>'Innal lazeena aamanu Wa-\'amilus saalihaati ula-ika hum khairul bareey-yah','page_number'=>599,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
            ['surah_id'=>98,'ayah_number'=>8,'arabic_text'=>'جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ','transliteration'=>'Jazaa-uhum inda rabbihim jan-naatu \'adnin tajree min tahtihal an-haaru khalideena feeha abada; radiy yallaahu \'anhum Wa-ra-du \'an zaalika liman khashiya rabbah','page_number'=>599,'juz_number'=>30,'hizb_number'=>60,'is_sajdah'=>false],
